const C: Record<string, string[]> = {"Mishneh Torah, Agents and Partners 10":["שֻׁתָּף שֶׁטָּעַן עַל חֲבֵרוֹ שֶׁכָּךְ הָיָה תְּנַאי בֵּינֵיהֶם וְהַלָּה אוֹמֵר לֹא הָיָה תְּנַאי זֶה מֵעוֹלָם. אוֹ שֶׁטָּעַן שֶׁהַקֶּרֶן שֶׁלִּי הָיָה כָּךְ וְכָךְ וְהַלָּה אוֹמֵר אֵינוֹ אֶלָּא פָּחוֹת מִזֶּה. אוֹ שֶׁטָּעַן שֶׁכְּבָר נָתַתִּי לְךָ הַשֻּׁתָּפוּת וְהַלָּה אוֹמֵר לֹא לָקַחְתִּי. אוֹ שֶׁסְּחוֹרָה זוֹ מִשֶּׁלִּי וְהַלָּה אוֹמֵר מִשֶּׁל אֶמְצַע וְכָל כַּיּוֹצֵא בִּטְעָנוֹת אֵלּוּ הָרְשׁוּת בְּיַד הַתּוֹבֵעַ בִּשְׁבוּעָה. כֵּיצַד. אִם רָצָה הַתּוֹבֵעַ שֶׁלֹּא יִשָּׁבַע הַשֻׁתָּף שְׁבוּעַת הַשֻּׁתָּפִין וְיַשְׁבִּיעוֹ הֶסֵּת עַל הַטַּעֲנָה שֶׁכּוֹפֵר בָּהּ וְאוֹמֵר לֹא הָיוּ דְּבָרִים מֵעוֹלָם הֲרֵי זֶה מַשְׁבִּיעוֹ. וְאִם רָצָה מְגַלְגֵּל עָלָיו כָּל אֵלּוּ הַדְּבָרִים בִּשְׁבוּעַת הַשֻּׁתָּפִין וּמַשְׁבִּיעוֹ בְּטַעֲנַת סָפֵק שֶׁלֹּא גָּזַלְתָּ כְּלוּם כָּל יְמֵי הַשֻּׁתָּפוּת וְשֶׁהָיָה בֵּינֵינוּ תְּנַאי כָּךְ וְשֶׁזּוֹ הַסְּחוֹרָה שֶׁלְּךָ וְשֶׁנָּתַתָּ לִי כָּךְ וְכָךְ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַתּוֹבֵעַ שֻׁתָּפוֹ לְהַשְׁבִּיעוֹ שְׁבוּעַת הַשֻּׁתָּפִין הַנִּתְבָּע אוֹמֵר כְּבָר חָלַקְנוּ וְלֹא נִשְׁאַר לְךָ אֶצְלִי כְּלוּם וְהַתּוֹבֵעַ אוֹמֵר עֲדַיִן לֹא חָלַקְנוּ וְלֹא עָשִׂינוּ חֶשְׁבּוֹן. אוֹ שֶׁאָמַר הַתּוֹבֵעַ חָלַקְנוּ עַל מְנָת שֶׁאַשְׁבִּיעַ אוֹתְךָ שְׁבוּעַת הַשֻּׁתָּפִין בְּכָל עֵת שֶׁאֶרְצֶה וַעֲדַיִן לֹא נִשְׁבַּעְתָּ וְאַתָּה מַדְחֶה אוֹתִי מִיּוֹם לְיוֹם. אֵינוֹ יָכוֹל לְהַשְׁבִּיעוֹ בְּטַעֲנַת סָפֵק. אֲפִלּוּ אָמַר הַנִּתְבָּע כֵּן חָלַקְנוּ וְנִשְׁאַר לְךָ אֶצְלִי וְזֶה הַנִּשְׁאָר אֵינוֹ אֶלָּא חוֹב שֶׁזְּקָפַתּוּ עָלַי אוֹ פִּקָּדוֹן הִנַּחְתָּ אֶצְלִי אַף עַל פִּי שֶׁיֵּשׁ עֵדִים שֶׁהָיָה שֻׁתָּפוֹ אֵינוֹ יָכוֹל לְהַשְׁבִּיעוֹ בְּטַעֲנַת סָפֵק וְאֵינוֹ יָכוֹל לְהַשְׁבִּיעַ הֶסֵּת שֶׁכְּבָר חָלְקוּ אוֹ שֶׁלֹּא נִשְׁתַּתְּפוּ מֵעוֹלָם וַאֲפִלּוּ עַל יְדֵי גִּלְגּוּל לְפִי שֶׁאֵין מַשְׁבִּיעִין הֶסֵּת וְאֵין מְגַלְגְּלִין אֶלָּא אִם טָעֲנוֹ דָּבָר שֶׁאִם יוֹדֶה בּוֹ יִהְיֶה חַיָּב לְשַׁלֵּם מָמוֹן. אֲבָל דָּבָר שֶׁאֲפִלּוּ הוֹדָה בּוֹ אֵינוֹ חַיָּב אֶלָּא שְׁבוּעָה אֵינוֹ נִשְׁבָּע עָלָיו וַאֲפִלּוּ עַל יְדֵי גִּלְגּוּל וְכָזֶה הוֹרוּ הַגְּאוֹנִים בַּעֲלֵי הוֹרָאָה:","טָעַן שֶׁעֲדַיִן שֻׁתָּפִי אַתָּה וְנִשְׁאַר לִי אֶצְלְךָ כָּךְ וְכָךְ וְזֶה אוֹמֵר כְּבָר חָלַקְנוּ וְלֹא נִשְׁאַר לְךָ אֶצְלִי כְּלוּם אוֹ לֹא הָיִיתָ שֻׁתָּפִי מֵעוֹלָם הֲרֵי הַנִּתְבָּע נִשְׁבָּע הֶסֵּת שֶׁאֵין לוֹ בְּיָדוֹ כְּלוּם וּמְגַלְגֵּל עָלָיו שֶׁלֹּא גְּזָלְתַּנִי כְּלוּם מֵעוֹלָם. וְאֵינוֹ מְגַלְגֵּל עָלָיו שֶׁלֹּא הָיוּ שֻׁתָּפוֹ אוֹ שֶׁכְּבָר חָלַקְנוּ מִן הַטַּעַם שֶׁבֵּאַרְנוּ:","טָעַן שֶׁעֲדַיִן שֻׁתָּפִין אֲנַחְנוּ וְיֵשׁ לִי לְהַשְׁבִּיעֲךָ בְּטַעֲנַת סָפֵק וְהַלָּה אוֹמֵר לֹא נִשְׁתַּתַּפְנוּ מֵעוֹלָם וְהֵבִיא הַתּוֹבֵעַ עֵדִים שֶׁהָיָה שֻׁתָּפוֹ וְחָזַר הַנִּתְבָּע אַחַר כָּךְ וְאָמַר חָלַקְנוּ אֵין שׁוֹמְעִין לוֹ שֶׁהֲרֵי הֻחְזַק כַּפְרָן לִשְׁבוּעָה זוֹ וְיִשָּׁבַע שְׁבוּעַת הַשֻּׁתָּפִין. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","רְאוּבֵן שֶׁהֵטִיל לְכִיס אַרְבַּע מֵאוֹת דִּינָרִים וְהֵטִיל שִׁמְעוֹן מָאתַיִם וְנִשְׁתַּתְּפוּ וְנָשְׂאוּ וְנָתְנוּ בְּיַחַד וַהֲרֵי הַמָּמוֹן כֻּלּוֹ בְּיַד רְאוּבֵן וְטָעַן רְאוּבֵן שֶׁפָּחַת מִן הַקֶּרֶן חֲמֵשׁ מֵאוֹת דִּינָרִין אֵין אוֹמְרִים יִשָּׁבַע רְאוּבֵן שְׁבוּעַת הַשֻּׁתָּפִין שֶׁפָּחֲתוּ כָּךְ וִישַׁלֵּם שִׁמְעוֹן חֲמִשִּׁים מִבֵּיתוֹ אֶלָּא יִשָּׁבַע רְאוּבֵן שְׁבוּעַת הַשֻּׁתָּפִין שֶׁפָּחֲתוּ וְיֵלֵךְ בַּמָּנֶה שֶׁבְּיָדוֹ בִּלְבַד וְלֹא יְשַׁלֵּם שִׁמְעוֹן כְּלוּם. טָעַן רְאוּבֵן שֶׁשִּׁמְעוֹן יוֹדֵעַ בְּוַדַּאי בִּפְחָת זוֹ שֶׁפָּחֲתוּ יְגַלְגֵּל עַל שִׁמְעוֹן שֶׁאֵינוֹ יוֹדֵעַ בְּוַדַּאי סְכוּם הַפְּחָת הַזֶּה. וְאִם לֹא נִתְעַסֵּק שִׁמְעוֹן בְּשֻׁתָּפוּת זוֹ כְּלָל יִשָּׁבַע שִׁמְעוֹן הֶסֵּת שֶׁאֵינוֹ יוֹדֵעַ בְּוַדַּאי בְּזֶה הַהֶפְסֵד וְיִפָּטֵר. וְלֹא עוֹד אֶלָּא אִם הָיָה זֶה הַמָּנֶה הַנִּשְׁאָר בְּיַד שִׁמְעוֹן חוֹלְקִים אוֹתוֹ בְּשָׁוֶה. שֶׁאֵין הַשֻׁתָּף מִן הַנִּשְׁבָּעִין וְנוֹטְלִין כְּדֵי שֶׁיִּשָּׁבַע וְיִטּל מַה שֶּׁבְּיַד חֲבֵרוֹ אֶלָּא נִשְׁבָּע וְנִפְטָר אוֹ נוֹטֵל מִדָּבָר שֶׁהוּא תַּחַת יָדוֹ. וְהִזָּהֵר בְּדִין זֶה שֶׁכְּבָר טָעוּ בּוֹ בַּעֲלֵי הוֹרָאָה:","טָעַן שִׁמְעוֹן שֶׁיֵּשׁ לְלֵוִי עָלָיו חוֹב בְּזוֹ הַשֻּׁתָּפוּת מָנֶה. אִם הָיָה בְּיָדוֹ כְּדֵי הַחוֹב וְהָיָה יָכוֹל לִתְּנוֹ לְלֵוִי נֶאֱמָן וְנוֹתְנִין הַחוֹב וְאַחַר כָּךְ מְחַשְּׁבִין. וְאִם אֵין בְּיָדוֹ לִתֵּן אֵינוֹ נֶאֱמָן לְהוֹצִיא מִיַּד רְאוּבֵן אוֹ מִן הַסְּחוֹרָה הַיְדוּעָה לְשֻׁתָּפוּת שֶׁמָּא קְנוּנְיָא הֵם עוֹשִׂין שִׁמְעוֹן וְלֵוִי עַל נִכְסֵי רְאוּבֵן. אֲפִלּוּ הָיְתָה הַמִּלְוֶה בִּשְׁטָר אֵין רְאוּבֵן חַיָּב לְשַׁלֵּם מִמֶּנָּה כְּלוּם. אֲבָל אִם טָעַן שִׁמְעוֹן שֶׁרְאוּבֵן יוֹדֵעַ בְּוַדַּאי שֶׁזֶּה הַחוֹב שֶׁעָלַי מֵחֲמַת הַשֻּׁתָּפוּת הוּא וְהַחוֹב אֶצְלֵנוּ הוּא יִשָּׁבַע רְאוּבֵן הֶסֵּת אוֹ עַל יְדֵי גִּלְגּוּל שֶׁאֵינוֹ יוֹדֵעַ שֶׁחוֹב זֶה אֶצְלֵנוּ וִישַׁלֵּם שִׁמְעוֹן הַחוֹב מִשֶּׁלּוֹ. וְכֵן אִם יָצָא שְׁטַר חוֹב עַל לֵוִי בְּשֵׁם שִׁמְעוֹן בְּמֵאָה דִּינָרִין מִמָּמוֹן הַשֻּׁתָּפוּת וְאָמַר שִׁמְעוֹן נִפְרַעְתִּי וְהֶחְזַרְתִּי לַכִּיס. אוֹ שֶׁאָמַר שִׁמְעוֹן קָבַעְתִּי לוֹ זְמַן לְשָׁנָה אוֹ לִשְׁתַּיִם. אֵינוֹ נֶאֱמָן שֶׁמָּא קְנוּנְיָא הוּא עוֹשֶׂה עַל נִכְסֵי רְאוּבֵן. וכֵּיצַד דָּנִין בְּדִין זֶה. לֵוִי כְּבָר נִפְטַר בְּהוֹדָאַת שִׁמְעוֹן. וְאִם לֹא הֵבִיא שִׁמְעוֹן רְאָיָה יְשַׁלֵּם מִבֵּיתוֹ וְיִתְבַּע אֶת לֵוִי בְּסוֹף זְמַן שֶׁאָמַר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה: סְלִיקוּ לְהוּ הִלְכוֹת שְׁלוּחִין וְשֻׁתָּפִּין"],"Mishneh Torah, Appraisals and Devoted Property 4":["שָׂדֶה שֶׁיְּרָשָׁהּ אָדָם מִמּוֹרִישָׁיו הִיא הַנִּקְרֵאת שְׂדֵה אֲחֻזָּה. וְשָׂדֶה שֶׁלְּקָחָהּ אוֹ זָכָה בָּהּ הִיא הַנִּקְרֵאת שְׂדֵה מִקְנָה. וְהַמַּקְדִּישׁ שְׂדֵה אֲחֻזָּתוֹ מוֹדְדִין אוֹתָהּ וְעֶרְכָּהּ הוּא הָעֵרֶךְ הַקָּצוּב בַּתּוֹרָה:","וְכַמָּה הוּא. כָּל מָקוֹם שֶׁרָאוּי לִזְרֹעַ בּוֹ חֹמֶר שְׂעוֹרִים וְיִזְרָעֶנּוּ בַּיָּד וְלֹא יְקָרֵב זְרִיעָתוֹ וְלֹא יְרַחֵק אוֹתָהּ. עֶרְכּוֹ חֲמִשִּׁים שְׁקָלִים לְכָל שְׁנֵי יוֹבֵל. וְאֵין שְׁנַת יוֹבֵל מִן הַמִּנְיָן. וְאֶחָד הַמַּקְדִּישׁ שָׂדֶה טוֹבָה שֶׁאֵין בְּכָל אֶרֶץ יִשְׂרָאֵל כְּמוֹתָהּ. אוֹ שָׂדֶה רָעָה שֶׁאֵין כָּמוֹהָ לְרֹעַ. כָּזֶה מַעֲרִיכִין אוֹתוֹ:","כְּבָר בֵּאַרְנוּ בְּהִלְכוֹת שְׁקָלִים שֶׁהַשֶּׁקֶל הָאָמוּר בַּתּוֹרָה הוּא הַנִּקְרָא סֶלַע בִּלְשׁוֹן חֲכָמִים. וְהַגֵּרָה הָאֲמוּרָה בַּתּוֹרָה הִיא הַמָּעָה בְּדִבְרֵי חֲכָמִים וְהוֹסִיפוּ עַל הַשֶּׁקֶל וְעָשׂוּ אוֹתוֹ סֶלַע. וְהַסֶּלַע אַרְבָּעָה דִּינָרִין. וְהַדִּינָר שֵׁשׁ מָעִין. וְהַמָּעָה שְׁנֵי פּוּנְדְיוֹנִין. נִמְצָא לְכָל שָׁנָה סֶלַע וּפוּנְדְיוֹן. שֶׁאַף עַל פִּי שֶׁהַסֶּלַע שְׁמוֹנָה וְאַרְבָּעִים פּוּנְדְיוֹנִין. כְּשֶׁיִּתֵּן פּוּנְדְיוֹנוֹת לִקַּח סֶלַע מִן הַשֻּׁלְחָנִי נוֹתֵן תִּשְׁעָה וְאַרְבָּעִים:","הַחֹמֶר הוּא הַכּוֹר. וְהוּא שְׁנֵי לְתָכִין. וְהַלֶּתֶךְ חֲמֵשׁ עֶשְׂרֵה סְאִין. נִמְצָא הַחֹמֶר שְׁלֹשִׁים סְאָה שֶׁהֵן עֶשֶׂר אֵיפוֹת כָּל שָׁלֹשׁ סְאִין אֵיפָה. וּכְבָר בֵּאַרְנוּ בְּהִלְכוֹת שַׁבָּת שֶׁהַמָּקוֹם שֶׁיֵּשׁ בִּשְׁבוֹרוֹ חֲמִשִּׁים אַמָּה עַל חֲמִשִּׁים אַמָּה הוּא בֵּית סְאָה וְהוּא מִזְרַע סְאָה. נִמְצֵאתָ לָמֵד שֶׁהַמָּקוֹם שֶׁיֵּשׁ בִּשְׁבוֹרוֹ חֲמִשָּׁה וְשִׁבְעִים אֶלֶף אַמָּה שֶׁהוּא בְּרִבּוּעַ מָאתַיִם אַרְבַּע וְשִׁבְעִים אַמּוֹת עַל מָאתַיִם אַרְבַּע וְשִׁבְעִים אַמּוֹת בְּקֵרוּב הוּא בֵּית כּוֹר וְהוּא (ויקרא כז טז) \"זֶרַע חֹמֶר שְׂעוֹרִים\":","כֵּיצַד דֶּרֶךְ הַחֶשְׁבּוֹן בְּעֶרְכֵי שָׂדוֹת. הֲרֵי שֶׁהִקְדִּישׁ שְׂדֵה אֲחֻזָּתוֹ וְנִשְׁאַר לַיּוֹבֵל שְׁמוֹנֶה שָׁנִים חוּץ מִשְּׁנַת הַיּוֹבֵל שֶׁאֵינָהּ בַּחֶשְׁבּוֹן כְּמוֹ שֶׁבֵּאַרְנוּ. כָּל הָרוֹצֶה לִפְדּוֹתָהּ מִיַּד הֶקְדֵּשׁ נוֹתֵן לְכָל (ויקרא כז טז) \"זֶרַע חֹמֶר שְׂעוֹרִים\" שְׁמוֹנָה סְלָעִים וּשְׁמוֹנֶה פּוּנְדְיוֹנוֹת. וְאִם רָצוּ הַבְּעָלִים לִפְדּוֹתָהּ נוֹתְנִין עֶשֶׂר סְלָעִים וַעֲשָׂרָה פּוּנְדְיוֹנוֹת לְפִי שֶׁהֵן מוֹסִיפִין חֹמֶשׁ. וְכֵן כָּל חֹמֶשׁ הָאָמוּר בַּתּוֹרָה צָרִיךְ שֶׁיְּהֵא הַקֶּרֶן עִם הַתּוֹסָפוֹת חֲמִשָּׁה נִמְצָא שֶׁהוֹסִיף רְבִיעַ הַקֶּרֶן. וְכֵן אִם פָּדְתָה אִשְׁתּוֹ שֶׁל מַקְדִּישׁ אוֹ אֶחָד מִיּוֹרְשָׁיו הֲרֵי אֵלּוּ מוֹסִיפִין חֹמֶשׁ:","נִשְׁאַר לַיּוֹבֵל אַרְבַּע שָׁנִים נוֹתֵן הַפּוֹדֶה אַרְבַּע סְלָעִים וְאַרְבָּעָה פּוּנְדְיוֹנוֹת לְכָל חֹמֶר וְאִם הַבְּעָלִים פָּדוּ אוֹתָהּ נוֹתֵן חֹמֶשׁ. וְכֵן לְפִי חֶשְׁבּוֹן זֶה סֶלַע וּפוּנְדְיוֹן לְכָל שָׁנָה. וְאֵינוֹ נוֹתֵן שָׁנָה בְּשָׁנָה אֶלָּא נוֹתֵן הַכּל כְּאֶחָד:","נִשְׁאַר בֵּינוֹ וּבֵין הַיּוֹבֵל שָׁנָה אֵינוֹ יָכוֹל לִתֵּן סֶלַע וּפוּנְדְיוֹן לִפְדּוֹתָהּ שֶׁנֶּאֱמַר (ויקרא כז יח) \"וְחִשַּׁב לוֹ הַכֹּהֵן\" (ויקרא כז יח) \"עַל פִּי הַשָּׁנִים הַנּוֹתָרוֹת\" אֵינָהּ נִפְדֵית בְּגִרְעוֹן כֶּסֶף אֶלָּא קֹדֶם לַיּוֹבֵל בִּשְׁתֵּי שָׁנִים אוֹ יוֹתֵר:","נִשְׁאַר בֵּינוֹ וּבֵין הַיּוֹבֵל שָׁנָה וְחֳדָשִׁים אִם רָצָה הַגִּזְבָּר לַחְשֹׁב הֶחֳדָשִׁים שָׁנָה וְיִתֵּן שְׁנַיִם שְׁקָלִים וּשְׁנַיִם פּוּנְדְיוֹנִים לְכָל זֶרַע חֹמֶר הֲרֵי זֶה מֻתָּר. לְפִי שֶׁאֵין מְחַשְּׁבִין חֳדָשִׁים לַהֶקְדֵּשׁ שֶׁנֶּאֱמַר (ויקרא כז יח) \"עַל פִּי הַשָּׁנִים הַנּוֹתָרֹת\". שָׁנִים אַתָּה מְחַשֵּׁב לַהֶקְדֵּשׁ וְאֵי אַתָּה מְחַשֵּׁב חֳדָשִׁים:","לְפִיכָךְ אֵין רָאוּי לְאָדָם לְהַקְדִּישׁ שָׂדֵהוּ לִפְנֵי הַיּוֹבֵל בְּפָחוֹת מִשְּׁתֵי שָׁנִים. וְאִם הִקְדִּישָׁהּ הֲרֵי זוֹ מְקֻדֶּשֶׁת. וְאֵינָהּ נִפְדֵית בְּגִרְעוֹן כֶּסֶף אֶלָּא אִם רָצָה הַפּוֹדֶה לִתֵּן חֲמִשִּׁים שֶׁקֶל לְכָל חֹמֶר פּוֹדֶה אוֹתָהּ וְאִם לֹא פְּדָאָהּ הֲרֵי זוֹ יוֹצְאָה לַכֹּהֲנִים בַּיּוֹבֵל כְּמוֹ שֶׁיִּתְבָּאֵר:","הִקְדִּישׁ שָׂדֵהוּ בִּשְׁנַת הַיּוֹבֵל עַצְמָהּ אֵינָהּ מְקֻדֶּשֶׁת. וְכֹהֵן וְלֵוִי שֶׁהִקְדִּישׁוּ בִּשְׁנַת הַיּוֹבֵל עַצְמָהּ הֲרֵי זוֹ מְקֻדֶּשֶׁת:","כְּשֵׁם שֶׁגּוֹאֲלִין לְעוֹלָם כָּךְ מַקְדִּישִׁין לְעוֹלָם:","הַמַּקְדִּישׁ אֶת שָׂדֵהוּ אַחַר הַיּוֹבֵל אֵינָהּ נִפְדֵית בְּגִרְעוֹן כֶּסֶף עַד שֶׁיִּגָּמֵר שָׁנָה אַחַר הַיּוֹבֵל. לְפִי שֶׁאֵין מְחַשְּׁבִין חֳדָשִׁים לַהֶקְדֵּשׁ. לְפִיכָךְ אִם רָצָה הַפּוֹדֶה לִתֵּן חֲמִשִּׁים שֶׁקֶל לְכָל זֶרַע חֹמֶר הֲרֵי זֶה פּוֹדֶה אֲפִלּוּ בַּיּוֹם שֶׁאַחַר הַיּוֹבֵל וְאֵינוֹ גּוֹרֵעַ כְּלוּם:","כְּשֶׁמּוֹדְדִין אֵין מוֹדְדִין אֶלָּא מְקוֹמוֹת הָרְאוּיִין לִזְרִיעָה. הָיוּ שָׁם סְלָעִים גְּבוֹהִים עֲשָׂרָה טְפָחִים אוֹ נְקָעִים מְלֵאִים מַיִם עֲמוּקִים עֲשָׂרָה טְפָחִים אֵין נִמְדָּדִין עִמָּהּ. פָּחוֹת מִכָּאן נִמְדָּדִין עִמָּהּ:","הָיוּ בָּהּ מְקוֹמוֹת נְמוּכוֹת עֲשָׂרָה אוֹ יוֹתֵר וְאֵין בָּהֶן מַיִם נִמְדָּדִין בִּפְנֵי עַצְמָן וּמְחַשְּׁבִין לָהֶם מַה שֶּׁרָאוּי לָהֶם:","הָיְתָה מְלֵאָה אִילָנוֹת אַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ הֲרֵי הִקְדִּישׁ גַּם הָאִילָנוֹת שֶׁכָּל הַמַּקְדִּישׁ בְּעַיִן יָפָה הוּא מַקְדִּישׁ וּמְחַשְּׁבִין אֶת הָאִילָנוֹת בְּשָׁוְיֵיהֶן וְהַקַּרְקַע מוֹדְדִין אוֹתָהּ וְיִהְיֶה עֶרְכָּהּ סֶלַע וּפוּנְדְיוֹן לְכָל שָׁנָה וּלְכָל זֶרַע חֹמֶר כְּמוֹ שֶׁבֵּאַרְנוּ:","הַמַּקְדִּישׁ אֶת הַשָּׂדֶה שֶׁאֵינָהּ רְאוּיָה לִזְרִיעָה וְהִיא הַנִּקְרֵאת טְרָשִׁין פּוֹדִין אוֹתָהּ בְּשָׁוְיָהּ. וְכֵן הַמַּקְדִּישׁ אֶת הָאִילָנוֹת בִּלְבַד פּוֹדִין אוֹתָן בְּשָׁוְיֵיהֶן:","הָיוּ הָאִילָנוֹת שְׁלֹשָׁה אִילָנוֹת לְתוֹךְ בֵּית סְאָה וְלֹא פֵּרֵשׁ שֶׁהָאִילָנוֹת בִּלְבַד הוּא שֶׁהִקְדִּישׁ הֲרֵי זֶה הִקְדִּישׁ אֶת הַקַּרְקַע וְאֶת הָאִילָנוֹת שֶׁבֵּינֵיהֶן. אֲבָל אִם הָיוּ הָאִילָנוֹת נְטוּעִים כָּל שְׁלֹשָׁה אִילָנוֹת בְּיֶתֶר מִבֵּית סְאָה אוֹ בְּפָחוֹת אוֹ שֶׁהִקְדִּישָׁן זֶה אַחַר זֶה הֲרֵי זֶה לֹא הִקְדִּישׁ אֶת הַקַּרְקַע וְלֹא אֶת הָאִילָנוֹת שֶׁבֵּינֵיהֶם:","הִקְדִּישׁ הָאִילָנוֹת וְאַחַר כָּךְ הִקְדִּישׁ אֶת הַקַּרְקַע פּוֹדֶה אֶת הָאִילָנוֹת בְּשָׁוְיֵיהֶן וְאֶת הַקַּרְקַע עַל פִּי מִדָּתָהּ:","הַמַּקְדִּישׁ שְׂדֵה אֲחֻזָּתוֹ וְהִגִּיעַ הַיּוֹבֵל וְלֹא נִפְדֵית אֶלָּא הֲרֵי הִיא תַּחַת יַד הַקֹּדֶשׁ. הַכֹּהֲנִים נוֹתְנִין אֶת דָּמֶיהָ וְתִהְיֶה אֲחֻזָּה לָהֶם. שֶׁאֵין הֶקְדֵּשׁ יוֹצֵא בְּלֹא פִּדְיוֹן. וְאוֹתָן הַדָּמִים יִפְּלוּ לְהֶקְדֵּשׁ בֶּדֶק הַבַּיִת:","גְּאָלָהּ הַמַּקְדִּישׁ קֹדֶם שֶׁיַּגִּיעַ הַיּוֹבֵל הֲרֵי זוֹ חוֹזֶרֶת לִבְעָלֶיהָ וְהָעֵרֶךְ שֶׁנָּתַן יִפּל לְבֶדֶק הַבַּיִת כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵן אִם גְּאָלָהּ בְּנוֹ שֶׁל מַקְדִּישׁ הֲרֵי זוֹ חוֹזֶרֶת לְאָבִיו בַּיּוֹבֵל. אֲבָל אִם גָּאֲלָה אוֹתָהּ בִּתּוֹ אוֹ שְׁאָר קְרוֹבָיו אוֹ נָכְרִי מִיַּד הַהֶקְדֵּשׁ. אִם חָזַר הַמַּקְדִּישׁ וּגְאָלָהּ מִיָּדָן חוֹזֶרֶת לוֹ לְעוֹלָם. וְאִם לֹא גְּאָלָהּ מִיָּדָן אֶלָּא הִגִּיעַ הַיּוֹבֵל וְהִיא תַּחַת יַד הַבַּת אוֹ שְׁאָר קְרוֹבִים אוֹ נָכְרִי הֲרֵי זוֹ יוֹצְאָה לַהֶקְדֵּשׁ וְאֵינָהּ חוֹזֶרֶת לַבְּעָלִים לְעוֹלָם. אֶלָּא תִּהְיֶה אֲחֻזָּה לַכֹּהֲנִים שֶׁנֶּאֱמַר (ויקרא כז כא) \"וְהָיָה הַשָּׂדֶה בְּצֵאתוֹ בַיֹּבֵל לַכֹּהֵן\" וְגוֹ'. וְאֵין הַכֹּהֲנִים צְרִיכִין לִתֵּן דָּמִים שֶׁכְּבָר נִפְדֵית מִיַּד הַהֶקְדֵּשׁ וְלָקַח עֶרְכָּהּ מְאֻחָר אֶלָּא תַּחְזֹר לַכֹּהֲנִים כְּאִלּוּ הֵם בְּעָלֶיהָ:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּיִשְׂרָאֵל. אֲבָל אִם הָיָה הַמַּקְדִּישׁ כֹּהֵן אוֹ לֵוִי הֲרֵי זֶה גּוֹאֵל לְעוֹלָם. וַאֲפִלּוּ עָבַר עָלֶיהָ הַיּוֹבֵל וְלֹא נִפְדֵית מִן הַהֶקְדֵּשׁ פּוֹדֶה אוֹתָהּ אַחַר הַיּוֹבֵל שֶׁנֶּאֱמַר (ויקרא כה לב) \"גְּאֻלַּת עוֹלָם תִּהְיֶה לַלְוִיִּם\":","הָאִשָּׁה שֶׁהִקְדִּישָׁה שְׂדֵה אֲחֻזָּתָהּ וּגְאָלָהּ בַּעְלָהּ מִיַּד הַהֶקְדֵּשׁ וְהִגִּיעַ הַיּוֹבֵל וְהִיא תַּחַת יַד הַבַּעַל הֲרֵי הַדָּבָר סָפֵק אִם תַּחְזֹר לָאִשָּׁה אוֹ תֵּצֵא לַכֹּהֲנִים. לְפִיכָךְ קָדְמָה הָאִשָּׁה וְהֶחֱזִיקָה בָּהּ אַחַר הַיּוֹבֵל אֵין הַכֹּהֲנִים יְכוֹלִין לְהוֹצִיא מִיָּדָהּ. וְכֵן אִם קָדְמוּ הַכֹּהֲנִים וְהֶחֱזִיקוּ בָּהּ אֵינָהּ יְכוֹלָה לְהוֹצִיא מִיָּדָם:","הַמַּקְדִּישׁ שָׂדֵהוּ וּפָדָה אוֹתָהּ כֹּהֵן מִיַּד הַהֶקְדֵּשׁ וְהִגִּיעַ הַיּוֹבֵל וְהִיא תַּחַת יַד הַכֹּהֵן לֹא יֹאמַר הוֹאִיל וַהֲרֵי הִיא יוֹצְאָה לַכֹּהֲנִים הֲרֵי הִיא תַּחַת יָדִי וְזָכִיתִי בָּהּ אֶלָּא יוֹצְאָה לְכָל אֶחָיו הַכֹּהֲנִים:","כְּשֶׁתֵּצֵא הַשָּׂדֶה לַכֹּהֲנִים בַּיּוֹבֵל תִּנָּתֵן לַכֹּהֲנִים שֶׁבַּמִּשְׁמָר שֶׁפָּגַע בּוֹ הַיּוֹבֵל. וְאִם הָיָה רֹאשׁ הַשָּׁנָה שֶׁל יוֹבֵל בְּשַׁבָּת שֶׁהֲרֵי מִשְׁמָר יוֹצֵא וּמִשְׁמָר נִכְנָס תִּנָּתֵן לַמִּשְׁמָר הַיּוֹצֵא:","הַמַּקְדִּישׁ אֶת הָאִילָנוֹת וְהִגִּיעַ הַיּוֹבֵל וְלֹא פָּדוּ אוֹתָם אֵינָן יוֹצְאִין לַכֹּהֲנִים שֶׁנֶּאֱמַר (ויקרא כז כא) \"וְהָיָה הַשָּׂדֶה בְּצֵאתוֹ בַיֹּבֵל\" וְאֵין אֵלּוּ שָׂדֶה. אֲבָל הַמַּקְדִּישׁ אֶת הַטְּרָשִׁים וְהִגִּיעַ יוֹבֵל וְלֹא פָּדוּ אוֹתָן הַבְּעָלִים הֲרֵי אֵלּוּ יוֹצְאִין לַכֹּהֲנִים שֶׁנֶּאֱמַר וְהָיָה הַשָּׂדֶה וְזוֹ נִקְרֵאת שָׂדֶה:","כֵּיצַד דִּין מַקְדִּישׁ שְׂדֵה מִקְנָתוֹ. שָׁמִין אוֹתָהּ בְּדָמֶיהָ וְרוֹאִין כַּמָּה הִיא שָׁוָה עַד הַיּוֹבֵל וּפוֹדֶה אוֹתָהּ כָּל מִי שֶׁיִּרְצֶה. וְאִם פָּדָה אוֹתָהּ הַמַּקְדִּישׁ אֵינוֹ מוֹסִיף חֹמֶשׁ וּפִדְיוֹנָהּ לְבֶדֶק הַבַּיִת כִּשְׁאָר עֲרָכִין וְדָמִים. וּכְשֶׁיַּגִּיעַ הַיּוֹבֵל תַּחְזֹר לַבְּעָלִים הָרִאשׁוֹנִים שֶׁמְּכָרוּהָ. בֵּין שֶׁנִּפְדֵית מִיַּד הַגִּזְבָּר וַהֲרֵי הִיא יוֹצְאָה מִיַּד אַחֵר. בֵּין שֶׁלֹּא נִפְדֵית וַהֲרֵי הִיא יוֹצְאָה מִיַּד הַהֶקְדֵּשׁ הֲרֵי זוֹ חוֹזֶרֶת לַמּוֹכֵר וְאֵינָהּ יוֹצְאָה לַכֹּהֲנִים שֶׁאֵין אָדָם מַקְדִּישׁ דָּבָר שֶׁאֵינוֹ שֶׁלּוֹ:","כָּל שָׂדֶה שֶׁשָּׁמִין אוֹתָהּ לַהֶקְדֵּשׁ לִמְכֹּר אוֹתָהּ בְּדָמֶיהָ מַכְרִיזִין עָלֶיהָ שִׁשִּׁים יוֹם רְצוּפִין בַּבֹּקֶר בִּשְׁעַת הַכְנָסַת פּוֹעֲלִים וּבָעֶרֶב בִּשְׁעַת הוֹצָאַת פּוֹעֲלִים. וּמְסַיְּמִין מְצָרֶיהָ וְאוֹמֵר כָּךְ הִיא יָפָה וּבְכָךְ הִיא שׁוּמָה כָּל הָרוֹצֶה לִקַּח יָבוֹא וְיִקַּח:","הַלּוֹקֵחַ שָׂדֶה מֵאָבִיו אוֹ מִשְּׁאָר הַמּוֹרִישִׁין אוֹתוֹ וְהִקְדִּישָׁהּ. בֵּין שֶׁהִקְדִּישָׁהּ אַחַר מוֹת אָבִיו אוֹ מוֹרִישׁוֹ. וּבֵין שֶׁהִקְדִּישָׁהּ בְּחַיֵּי אָבִיו אוֹ שְׁאָר מוֹרִישָׁיו וְאַחַר כָּךְ מֵת אָבִיו הֲרֵי זוֹ כִּשְׂדֵה אֲחֻזָּה. שֶׁנֶּאֱמַר (ויקרא כז כב) \"וְאִם אֶת שְׂדֵה מִקְנָתוֹ אֲשֶׁר לֹא מִשְּׂדֵה אֲחֻזָּתוֹ\" שָׂדֶה שֶׁאֵינָהּ רְאוּיָה לִהְיוֹת שְׂדֵה אֲחֻזָּה יָצָאת זוֹ שֶׁרְאוּיָה לוֹ לְיוֹרְשָׁהּ:"],"Mishneh Torah, Blessings 6":["כָּל הָאוֹכֵל הַפַּת שֶׁמְּבָרְכִין עָלָיו הַמּוֹצִיא צָרִיךְ נְטִילַת יָדַיִם תְּחִלָּה וָסוֹף. וְאַף עַל פִּי שֶׁהִיא פַּת חֻלִּין וְאַף עַל פִּי שֶׁאֵין יָדָיו מְלֻכְלָכוֹת וְאֵינוֹ יוֹדֵעַ לָהֶן טֻמְאָה לֹא יֹאכַל עַד שֶׁיִּטּל שְׁתֵּי יָדָיו. וְכֵן כָּל דָּבָר שֶׁטִּבּוּלוֹ בְּמַשְׁקִין צָרִיךְ נְטִילַת יָדַיִם תְּחִלָּה:","כָּל הַנּוֹטֵל יָדָיו בֵּין לַאֲכִילָה בֵּין לִקְרִיאַת שְׁמַע בֵּין לִתְפִלָּה מְבָרֵךְ תְּחִלָּה אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל נְטִילַת יָדָיִם. שֶׁזּוֹ מִצְוַת חֲכָמִים שֶּׁנִּצְטַוֵּינוּ מִן הַתּוֹרָה לִשְׁמֹעַ מֵהֶן שֶׁנֶּאֱמַר (דברים יז יא) ״עַל פִּי הַתּוֹרָה אֲשֶׁר יוֹרוּךָ״. ומַיִם אַחֲרוֹנִים אֵין מְבָרְכִין עֲלֵיהֶן שֶׁאֵינָם אֶלָּא מִפְּנֵי הַסַּכָּנָה. וּלְפִיכָךְ חַיָּב אָדָם לְהִזָּהֵר בָּהֶן בְּיוֹתֵר:","נְטִילַת יָדַיִם בֵּין תַּבְשִׁיל לְתַבְשִׁיל רְשׁוּת. רָצָה נוֹטֵל רָצָה אֵינוֹ נוֹטֵל. וּפֵרוֹת שֶׁל חֻלִּין אֵינָן צְרִיכִין נְטִילַת יָדַיִם בֵּין בַּתְּחִלָּה בֵּין בַּסּוֹף. וְכָל הַנּוֹטֵל יָדָיו לְפֵרוֹת הֲרֵי זֶה מִגַּסֵּי הָרוּחַ. כָּל פַּת שֶׁהַמֶּלַח בּוֹ צָרִיךְ נְטִילַת יָדַיִם בָּאַחֲרוֹנָה שֶׁמָּא יֵשׁ בּוֹ מֶלַח סְדוֹמִית אוֹ מֶלַח שֶׁטִּבְעוֹ כְּמֶלַח סְדוֹמִית וְיַעֲבִיר יָדָיו עַל עֵינָיו וִיסַמֵּא. מִפְּנֵי זֶה חַיָּבִין לִטּל יָדַיִם בְּסוֹף כָּל סְעֻדָּה מִפְּנֵי הַמֶּלַח. וּבְמַחֲנֶה פְּטוּרִים מִנְּטִילַת יָדַיִם בַּתְּחִלָּה מִפְּנֵי שֶׁהֵן טְרוּדִים בְּמִלְחָמָה. וְחַיָּבִין בָּאַחֲרוֹנָה מִפְּנֵי הַסַּכָּנָה:","עַד הֵיכָן הִיא נְטִילַת יָדַיִם. עַד הַפֶּרֶק. וְכַמָּה שִׁעוּר הַמַּיִם. רְבִיעִית לְכָל שְׁתֵּי יָדַיִם. וְכָל שֶׁחוֹצְצִים בִּטְבִילָה חוֹצֵץ בִּנְטִילַת יָדַיִם. וְכָל הָעוֹלֶה לְמִדַּת מִקְוֶה עוֹלֶה לְשִׁעוּר רְבִיעִית:","כָּל הַצָּרִיךְ נְטִילַת יָדַיִם וְהִטְבִּיל יָדָיו בְּמֵי מִקְוֶה אֵינוֹ צָרִיךְ דָּבָר אַחֵר. וְאִם הִטְבִּילָן בְּמַיִם שֶׁאֵין בָּהֶם שִׁעוּר מִקְוֶה אוֹ בְּמַיִם שְׁאוּבִין שֶׁבַּקַּרְקַע לֹא עָשָׂה כְּלוּם שֶׁאֵין הַמַּיִם שְׁאוּבִין מְטַהֲרִין אֶת הַיָּדַיִם אֶלָּא בִּנְטִילָה:","כָּל הַנּוֹטֵל יָדָיו צָרִיךְ לְהִזָּהֵר בְּאַרְבָּעָה דְּבָרִים. בַּמַּיִם עַצְמָן שֶׁלֹּא יִהְיוּ פְּסוּלִין לִנְטִילַת יָדַיִם. וּבַשִּׁעוּר שֶׁיִּהְיֶה בָּהֶן רְבִיעִית לְכָל שְׁתֵּי יָדַיִם. וּבַכְּלִי שֶׁיִּהְיוּ הַמַּיִם שֶׁנּוֹטְלִין בָּהֶן בִּכְלִי. וּבְנוֹטֵל שֶׁיִּהְיוּ הַמַּיִם בָּאִין מִכֹּחַ נוֹתֵן:","אַרְבָּעָה דְּבָרִים פּוֹסְלִין אֶת הַמַּיִם. שִׁנּוּי מַרְאֶה. וְגִלּוּי. וַעֲשִׂיַּת מְלָאכָה בָּהֶן. וְהֶפְסֵד שֶׁמּוֹנֵעַ אֶת הַבְּהֵמָה מִלִּשְׁתּוֹת מֵהֶן. כֵּיצַד. מַיִם שֶׁנִּשְׁתַּנּוּ מַרְאִיתָן בֵּין בְּכֵלִים בֵּין בְּקַרְקָעוֹת בֵּין מֵחֲמַת דָּבָר שֶׁנָּפַל לְתוֹכָן בֵּין מֵחֲמַת מְקוֹמָן הֲרֵי אֵלּוּ פְּסוּלִין. וְכֵן אִם נִתְגַּלּוּ גִּלּוּי הָאוֹסֵר אוֹתָן מִשְּׁתִיָּה נִפְסְלוּ לִנְטִילַת יָדַיִם:","כָּל מַיִם שֶׁנַּעֲשָׂה בָּהֶן מְלָאכָה נַעֲשׂוּ שׁוֹפְכִין וּפְסוּלִין לִנְטִילַת יָדַיִם. כֵּיצַד. מַיִם שְׁאוּבִין שֶׁהֵדִיחַ בָּהֶן כֵּלִים אוֹ שֶׁשָּׁרָה בָּהֶם פִּתּוֹ וְכַיּוֹצֵא בְּזֶה בֵּין בְּכֵלִים בֵּין בְּקַרְקָעוֹת פְּסוּלִין לִנְטִילַת יָדַיִם. הֵדִיחַ בָּהֶן כֵּלִים מוּדָחִין אוֹ חֲדָשִׁים לֹא פְּסָלָן. מַיִם שֶׁהַנַּחְתּוֹם מְטַבֵּל בָּהֶן אֶת הַכְּעָכִים פְּסוּלִין. וְשֶׁהוּא חוֹפֵן מֵהֶן בִּשְׁעַת לִישָׁה כְּשֵׁרִים. שֶׁהַמַּיִם שֶׁבְּחָפְנָיו הֵן שֶׁנַּעֲשׂוּ בָּהֶן מְלָאכָה. אֲבָל הַמַּיִם שֶׁחֹפֶן מֵהֶם הֲרֵי הֵן בְּכַשְׁרוּתָן:","וְכָל מַיִם שֶׁנִּפְסְלוּ מִשְּׁתִיַּת כֶּלֶב. כְּגוֹן שֶׁהָיוּ מָרִים אוֹ מְלוּחִים אוֹ עֲכוּרִין אוֹ רֵיחַ רַע עַד שֶׁלֹּא יִשְׁתֶּה מֵהֶן הַכֶּלֶב. בְּכֵלִים פְּסוּלִין לִנְטִילַת יָדַיִם וּבְקַרְקָעוֹת כְּשֵׁרִים לְהַטְבִּיל. חַמֵּי טְבֶרְיָא בִּמְקוֹמָן מַטְבִּילִין בָּהֶם אֶת הַיָּדַיִם. אֲבָל אִם נָטַל מֵהֶן בִּכְלִי אוֹ שֶׁהִפְלִיג מֵהֶן אַמָּה לְמָקוֹם אַחֵר אֵין נוֹטְלִין מֵהֶן לֹא רִאשׁוֹנִים וְלֹא אַחֲרוֹנִים מִפְּנֵי שֶׁאֵינָן רְאוּיִין לִשְׁתִיַּת בְּהֵמָה:","יֵשׁ לַנּוֹטֵל לִתֵּן עַל יָדָיו מְעַט מְעַט עַד שֶׁיִּתֵּן כַּשִּׁעוּר. וְאִם נָתַן הָרְבִיעִית כֻּלָּהּ בִּשְׁטִיפָה אַחַת כָּשֵׁר. נוֹטְלִין אַרְבָּעָה אוֹ חֲמִשָּׁה זֶה בְּצַד זֶה אוֹ יָד זֶה עַל גַּבֵּי זֶה בִּשְׁטִיפָה אַחַת. וּבִלְבַד שֶׁיַּרְפּוּ יְדֵיהֶן כְּדֵי שֶׁיָּבוֹא בֵּינֵיהֶן הַמַּיִם. וְיִהְיֶה בְּאוֹתָהּ הַשְּׁטִיפָה כְּדֵי רְבִיעִית לְכָל אֶחָד וְאֶחָד:","אֵין נוֹטְלִין מַיִם לַיָּדַיִם לֹא בְּדָפְנוֹת הַכֵּלִים וְלֹא בְּשׁוּלֵי הַמַּחַץ וְלֹא בַּחֲרָסִים וְלֹא בִּמְגוּפַת הֶחָבִית. וְאִם תִּקֵּן הַמְּגוּפָה לִנְטִילָה נוֹטְלִין מִמֶּנָּה לַיָּדַיִם. וְכֵן הַחֵמֶת שֶׁתִּקְּנָהּ נוֹטְלִין מִמֶּנָּה לַיָּדַיִם. אֲבָל שַׂק וְקֻפָּה שֶׁנִּתְקְנוּ אֵין נוֹטְלִין מֵהֶן לַיָּדַיִם. וְלֹא יִתֵּן לַחֲבֵרוֹ בְּחָפְנָיו שֶׁאֵין חָפְנָיו כְּלִי. וְכֵלִים שֶׁנִּשְׁבְּרוּ שְׁבִירָה הַמְטַהֶרֶת אוֹתָן מִידֵי טֻמְאָה אֵין נוֹתְנִין בָּהֶם לַיָּדַיִם מִפְּנֵי שֶׁהֵן שִׁבְרֵי כֵּלִים:","בְּכָל הַכֵּלִים נוֹטְלִים לַיָּדַיִם וַאֲפִלּוּ כְּלֵי גְּלָלִים וּכְלֵי אֲדָמָה. וְהוּא שֶׁיִּהְיוּ שְׁלֵמִים. כְּלִי שֶׁאֵינוֹ מַחֲזִיק רְבִיעִית אוֹ אֵין בּוֹ רְבִיעִית אֵין נוֹתְנִין מִמֶּנָּה לַיָּדַיִם:","הַכּל כְּשֵׁרִין לִתֵּן לַיָּדַיִם אֲפִלּוּ חֶרֶשׁ שׁוֹטֶה וְקָטָן. אִם אֵין שָׁם אַחֵר מַנִּיחַ הַכְּלִי בֵּין בִּרְכָּיו וְצַק עַל יָדָיו. אוֹ יַטֶּה הֶחָבִית עַל יָדָיו וְיִטּל. אוֹ נוֹטֵל יָדוֹ אַחַת וְצַק בְּזוֹ עַל זוֹ וְחוֹזֵר וְצַק בָּרִאשׁוֹנָה עַל הַשְּׁנִיָּה. וְהַקּוֹף נוֹטֵל לַיָּדַיִם:","הַשֹּׁקֶת שֶׁדּוֹלֶה אָדָם בְּיָדוֹ אוֹ בְּגַלְגַּל וְנוֹתֵן לְתוֹכָהּ וְהַמַּיִם נִמְשָׁכִין מִמֶּנָּה בָּאַמָּה וְהוֹלְכִין וּמַשְׁקִין הַיְרָקוֹת אוֹ הַבְּהֵמָה וְהִנִּיחַ יָדָיו בַּשֹּׁקֶת וְעָבְרוּ הַמַּיִם וְשָׁטְפוּ עַל יָדָיו לֹא עָלְתָה לוֹ נְטִילָה. שֶׁהֲרֵי אֵין כָּאן נוֹתֵן עַל יָדָיו. וְאִם הָיוּ יָדָיו קְרוֹבוֹת לִשְׁפִיכַת הַדְּלִי עַד שֶׁנִּמְצְאוּ הַמַּיִם שָׁטְפוּ עַל יָדָיו מִכֹּחַ נְתִינַת הָאָדָם עָלְתָה לוֹ נְטִילָה:","מַיִם שֶׁנִּסְתַּפֵּק לוֹ אִם נַעֲשָׂה מֵהֶן מְלָאכָה אוֹ לֹא נַעֲשָׂה. אִם יֵשׁ בָּהֶן כַּשִּׁעוּר אוֹ שֶׁאֵין בָּהֶן. אִם הֵן טְהוֹרִין אוֹ טְמֵאִין. סָפֵק נָטַל יָדָיו סָפֵק לֹא נָטַל יָדָיו. סְפֵקוֹ טָהוֹר שֶׁכָּל סָפֵק שֶׁבְּטָהֳרַת יָדַיִם טָהוֹר:","מַיִם הָרִאשׁוֹנִים צָרִיךְ שֶׁיַּגְבִּיהַּ יָדָיו לְמַעְלָה עַד שֶׁלֹּא יֵצְאוּ מַיִם חוּץ לַפֶּרֶק וְיַחְזְרוּ וִיטַמְּאוּ אֶת הַיָּדַיִם. וְאַחֲרוֹנִים צָרִיךְ שֶׁיַּשְׁפִּיל יָדָיו לְמַטָּה כְּדֵי שֶׁיֵּצֵא כָּל כֹּחַ הַמֶּלַח מֵעַל יָדָיו. מַיִם רִאשׁוֹנִים נִטָּלִים בֵּין עַל גַּבֵּי כְּלִי בֵּין עַל גַּבֵּי קַרְקַע. וְאַחֲרוֹנִים אֵינָן נִטָּלִין אֶלָּא עַל גַּבֵּי כְּלִי. מַיִם רִאשׁוֹנִים נִטָּלִין בֵּין בְּחַמֵּי הָאוּר בֵּין בְּצוֹנֵן. וְאַחֲרוֹנִים אֵינָן נִטָּלִין בְּחַמִּין. וְהוּא שֶׁיִּהְיוּ חַמִּים שֶׁהַיָּד סוֹלֶדֶת בָּהֶן מִפְּנֵי שֶׁאֵין מַעֲבִירִין אֶת הַזֻּהֲמָא, שֶׁאֵינוֹ יָכוֹל לְשַׁפְשֵׁף בָּהֶן. אֲבָל הָיוּ פּוֹשְׁרִין נוֹטְלִין מֵהֶן בָּאַחֲרוֹנָה:","נוֹטֵל אָדָם יָדָיו שַׁחֲרִית וּמַתְנֶה עֲלֵיהֶן כָּל הַיּוֹם וְאֵינוֹ צָרִיךְ לִטּל אֶת יָדָיו לְכָל אֲכִילָה וַאֲכִילָה. וְהוּא שֶׁלֹּא יַסִּיחַ דַּעְתּוֹ מֵהֶן. אֲבָל אִם הִסִּיחַ דַּעְתּוֹ מֵהֶן צָרִיךְ לִטּל יָדָיו בְּכָל עֵת שֶׁצָּרִיךְ נְטִילָה:","לָט אָדָם אֶת יָדָיו בְּמַפָּה וְאוֹכֵל בָּהֶן פַּת אוֹ דָּבָר שֶׁטִּבּוּלוֹ בְּמַשְׁקֶה אַף עַל פִּי שֶׁלֹּא נָטַל יָדָיו. הַמַּאֲכִיל לַאֲחֵרִים אֵינוֹ צָרִיךְ נְטִילַת יָדַיִם. וְהָאוֹכֵל צָרִיךְ נְטִילַת יָדַיִם אַף עַל פִּי שֶׁאַחֵר נוֹתֵן לְתוֹךְ פִּיו וְאֵינוֹ נוֹגֵעַ בַּמַּאֲכָל. וְהוּא הַדִּין לְאוֹכֵל בְּמַגְרֵפָה שֶׁצָּרִיךְ נְטִילַת יָדַיִם:","אָסוּר לְהַאֲכִיל מִי שֶׁלֹּא נָטַל יָדָיו וְאַף עַל פִּי שֶׁהוּא נוֹתֵן לְתוֹךְ פִּיו. וְאָסוּר לְזַלְזֵל בִּנְטִילַת יָדַיִם. וְצִוּוּיִים הַרְבֵּה צִוּוּ חֲכָמִים וְהִזְהִירוּ עַל הַדָּבָר. אֲפִלּוּ אֵין לוֹ מַיִם אֶלָּא כְּדֵי שְׁתִיָּה נוֹטֵל יָדָיו בְּמִקְצָתָן וְאַחַר כָּךְ אוֹכֵל וְשׁוֹתֶה מִקְצָתָן:","צָרִיךְ אָדָם לְנַגֵּב אֶת יָדָיו וְאַחַר כָּךְ יֹאכַל. וְכָל הָאוֹכֵל בְּלֹא נִגּוּב יָדַיִם כְּאוֹכֵל לֶחֶם טָמֵא. וְכָל הַנּוֹטֵל יָדָיו בָּאַחֲרוֹנָה מְנַגֵּב וְאַחַר כָּךְ מְבָרֵךְ. וְתֵכֶף לִנְטִילַת יָדַיִם בִּרְכַּת הַמָּזוֹן, לֹא יַפְסִיק בֵּינֵיהֶם בְּדָבָר אַחֵר. אֲפִלּוּ לִשְׁתּוֹת מַיִם אַחַר שֶׁנּוֹטֵל יָדָיו בָּאַחֲרוֹנָה אָסוּר עַד שֶׁיְּבָרֵךְ בִּרְכַּת הַמָּזוֹן:"],"Mishneh Torah, Circumcision 1":["מִילָה מִצְוַת עֲשֵׂה שֶׁחַיָּבִין עָלֶיהָ כָּרֵת שֶׁנֶּאֱמַר (בראשית יז יד) ״וְעָרֵל זָכָר אֲשֶׁר לֹא יִמּוֹל אֶת בְּשַׂר עָרְלָתוֹ וְנִכְרְתָה הַנֶּפֶשׁ הַהִוא מֵעַמֶּיהָ״. וּמִצְוָה עַל הָאָב לָמוּל אֶת בְּנוֹ וְעַל הָרַב לָמוּל אֶת עֲבָדָיו (בראשית יז יב) ״יְלִיד בַּיִת וּמִקְנַת כֶּסֶף״. עָבַר הָאָב אוֹ הָאָדוֹן וְלֹא מָל אוֹתָן בִּטֵּל מִצְוַת עֲשֵׂה וְאֵינוֹ חַיָּב כָּרֵת שֶׁאֵין הַכָּרֵת תָּלוּי אֶלָּא בֶּעָרֵל עַצְמוֹ. וּבֵית דִּין מְצֻוִּים לָמוּל אוֹתוֹ הַבֵּן אוֹ הָעֶבֶד בִּזְמַנּוֹ וְלֹא יַנִּיחוּ עָרֵל בְּיִשְׂרָאֵל וְלֹא בְּעַבְדֵיהֶן:","אֵין מָלִין בְּנוֹ שֶׁל אָדָם שֶׁלֹּא מִדַּעְתּוֹ אֶלָּא אִם כֵּן עָבַר וְנִמְנַע לְמוּלוֹ שֶׁבֵּית דִּין מָלִין אוֹתוֹ בְּעַל כָּרְחוֹ. נִתְעַלֵּם מִבֵּית דִּין וְלֹא מָלוּ אוֹתוֹ. כְּשֶׁיִּגְדַּל הוּא חַיָּב לָמוּל אֶת עַצְמוֹ. וְכָל יוֹם וְיוֹם שֶׁיַּעֲבֹר עָלָיו מִשֶּׁיִּגְדַּל וְלֹא יָמוּל אֶת עַצְמוֹ הֲרֵי הוּא מְבַטֵּל מִצְוַת עֲשֵׂה. אֲבָל אֵינוֹ חַיָּב כָּרֵת עַד שֶׁיָּמוּת וְהוּא עָרֵל בְּמֵזִיד:","אֶחָד עֶבֶד שֶׁנּוֹלַד בִּרְשׁוּת יִשְׂרָאֵל וְאֶחָד עֶבֶד הַנִּלְקָח מִן הַכּוּתִים חַיָּב הָרַב לָמוּל אוֹתָן. אֶלָּא שֶׁיְּלִיד בַּיִת נִמּוֹל לִשְׁמוֹנָה. וּמִקְנַת כֶּסֶף נִמּוֹל בַּיּוֹם שֶׁנִּלְקַח אֲפִלּוּ לְקָחוֹ בַּיּוֹם שֶׁנּוֹלַד נִמּוֹל בְּיוֹמוֹ:","יֵשׁ מִקְנַת כֶּסֶף שֶׁנִּמּוֹל לִשְׁמוֹנָה וְיֵשׁ יְלִיד בַּיִת שֶׁנִּמּוֹל בַּיּוֹם שֶׁנּוֹלַד. כֵּיצַד. לָקַח שִׁפְחָה וְלָקַח עֻבָּרָהּ עִמָּהּ וְיָלְדָה הֲרֵי זֶה נִמּוֹל לִשְׁמוֹנָה. וְאַף עַל פִּי שֶׁלָּקַח הָעֻבָּר בִּפְנֵי עַצְמוֹ וַהֲרֵי הָעֻבָּר עַצְמוֹ מִקְנַת כֶּסֶף הוֹאִיל וְקָנָה אִמּוֹ קֹדֶם שֶׁנּוֹלַד נִמּוֹל לִשְׁמוֹנָה:","לָקַח שִׁפְחָה לְעֻבָּרֶיהָ. אוֹ שֶׁלָּקַח שִׁפְחָה עַל מְנָת שֶׁלֹּא לְהַטְבִּילָהּ לְשֵׁם עַבְדוּת. אַף עַל פִּי שֶׁנּוֹלַד בִּרְשׁוּתוֹ נִמּוֹל בַּיּוֹם שֶׁנּוֹלָד. שֶׁהֲרֵי הַנּוֹלָד הַזֶּה כְּאִלּוּ הוּא מִקְנַת כֶּסֶף לְבַדּוֹ וּכְאִלּוּ הַיּוֹם קָנָהוּ. שֶׁאֵין אִמּוֹ בִּכְלַל שִׁפְחוֹת יִשְׂרָאֵל כְּדֵי שֶׁיִּהְיֶה הַבֵּן יְלִיד בַּיִת. וְאִם טָבְלָה אִמּוֹ אַחַר שֶׁיָּלְדָה הֲרֵי זֶה נִמּוֹל לִשְׁמוֹנָה:","לָקַח עֶבֶד גָּדוֹל מִן הָעַכּוּ״ם וְלֹא רָצָה הָעֶבֶד לָמוּל מְגַלְגְּלִין עִמּוֹ כָּל שְׁנֵים עָשָׂר חֹדֶשׁ. יֶתֶר עַל כֵּן אָסוּר לְקַיְּמוֹ כְּשֶׁהוּא עָרֵל. אֶלָּא חוֹזֵר וּמוֹכְרוֹ לְעַכּוּ״ם. וְאִם הִתְנָה עָלָיו מִתְּחִלָּה וְהוּא אֵצֶל רַבּוֹ הָעַכּוּ״ם שֶׁלֹּא יָמוּל אוֹתוֹ מֻתָּר לְקַיְּמוֹ וְהוּא עָרֵל. וּבִלְבַד שֶׁיְּקַבֵּל עָלָיו שֶׁבַע מִצְוֹת שֶׁנִּצְטַוּוּ בְּנֵי נֹחַ וְיִהְיֶה כְּגֵר תּוֹשָׁב. אֲבָל אִם לֹא קִבֵּל עָלָיו שֶׁבַע מִצְוֹת יֵהָרֵג מִיָּד. וְאֵין מְקַבְּלִים גֵּר תּוֹשָׁב אֶלָּא בִּזְמַן שֶׁהַיּוֹבֵל נוֹהֵג:","גֵּר שֶׁנִּכְנַס לִקְהַל יִשְׂרָאֵל חַיָּב מִילָה תְּחִלָּה. וְאִם מָל כְּשֶׁהָיָה עַכּוּ״ם צָרִיךְ לְהַטִּיף מִמֶּנּוּ דַּם בְּרִית בַּיּוֹם שֶׁנִּתְגַּיֵּר. וְכֵן קָטָן שֶׁנּוֹלַד כְּשֶׁהוּא מָהוּל צָרִיךְ לְהַטִּיף מִמֶּנּוּ דַּם בְּרִית בַּיּוֹם הַשְּׁמִינִי. אַנְדְּרוֹגִינוּס וְהוּא הַיָּלוּד שֶׁיֵּשׁ לוֹ זַכְרוּת כְּזָכָר וְנַקְבוּת כִּנְקֵבָה צָרִיךְ לָמוּל אוֹתוֹ בַּשְּׁמִינִי. וְכֵן יוֹצֵא דֹּפֶן וּמִי שֶׁיֵּשׁ לוֹ שְׁתֵּי עָרְלוֹת מָלִין אֶת שְׁתֵּיהֶן בַּשְּׁמִינִי:","אֵין מָלִין לְעוֹלָם אֶלָּא בַּיּוֹם אַחַר עֲלוֹת הַשֶּׁמֶשׁ. בֵּין בַּיּוֹם הַשְּׁמִינִי שֶׁהוּא זְמַנָּהּ בֵּין שֶׁלֹּא בִּזְמַנָּהּ שֶׁהוּא מִתְּשִׁיעִי וָהָלְאָה שֶׁנֶּאֱמַר (ויקרא יב ג) ״בַּיּוֹם הַשְּׁמִינִי״ בַּיּוֹם וְלֹא בַּלַּיְלָה. מָל מִשֶּׁעָלָה עַמּוּד הַשַּׁחַר כָּשֵׁר. וְכָל הַיּוֹם כָּשֵׁר לְמִילָה. וְאַף עַל פִּי כֵן מִצְוָה לְהַקְדִּים בִּתְחִלַּת הַיּוֹם שֶׁזְּרִיזִין מַקְדִּימִין לְמִצְוֹת:","מִילָה בִּזְמַנָּהּ דּוֹחָה אֶת הַשַּׁבָּת. וְשֶׁלֹּא בִּזְמַנָּהּ אֵינָהּ דּוֹחָה לֹא אֶת הַשַּׁבָּת וְלֹא אֶת יוֹם טוֹב. וּבֵין בִּזְמַנָּהּ וּבֵין שֶׁלֹּא בִּזְמַנָּהּ דּוֹחָה אֶת הַצָּרַעַת. כֵּיצַד. שֶׁאִם הָיְתָה בַּהֶרֶת בְּעוֹר הָעָרְלָה חוֹתְכָהּ עִם הָעָרְלָה. אַף עַל פִּי שֶׁקְּצִיצַת נֶגַע הַצָּרַעַת בְּלֹא תַּעֲשֶׂה יָבֹא עֲשֵׂה וְיִדְחֶה אֶת לֹא תַּעֲשֶׂה:","כְּשֵׁם שֶׁמִּילַת הַבָּנִים דּוֹחָה אֶת הַשַּׁבָּת כָּךְ מִילַת הָעֲבָדִים שֶׁהֵן נִמּוֹלִים לִשְׁמוֹנָה דּוֹחָה אֶת הַשַּׁבָּת אִם חָל שְׁמִינִי שֶׁלָּהֶן בְּשַׁבָּת. חוּץ מִילִיד בַּיִת שֶׁלֹּא טָבְלָה אִמּוֹ עַד שֶׁיָּלְדָה שֶׁאַף עַל פִּי שֶׁנִּמּוֹל לִשְׁמוֹנָה אֵינוֹ דּוֹחֶה אֶת הַשַּׁבָּת:","קָטָן שֶׁנּוֹלַד כְּשֶׁהוּא מָהוּל. וּמִי שֶׁנּוֹלַד בַּחֹדֶשׁ הַשְּׁמִינִי לְעִבּוּרוֹ קֹדֶם שֶׁתִּגָּמֵר בְּרִיָּתוֹ שֶׁהוּא כְּנֵפֶל מִפְּנֵי שֶׁאֵינוֹ חַי. וְיוֹצֵא דֹּפֶן וְאַנְדְּרוֹגִינוּס וּמִי שֶׁיֵּשׁ לוֹ שְׁתֵּי עָרְלוֹת אֵין דּוֹחִין אֶת הַשַּׁבָּת אֶלָּא נִימוֹלִין בְּאֶחָד בְּשַׁבָּת שֶׁהוּא יוֹם תְּשִׁיעִי שֶׁלָּהֶן:","מִי שֶׁנּוֹלַד בֵּין הַשְּׁמָשׁוֹת סָפֵק בַּיּוֹם סָפֵק בַּלַּיְלָה מוֹנִין מִן הַלַּיְלָה וְנִמּוֹל לִתְשִׁיעִי שֶׁהוּא סָפֵק שְׁמִינִי. וְאִם נוֹלַד עֶרֶב שַׁבָּת בֵּין הַשְּׁמָשׁוֹת אֵינוֹ דּוֹחֶה אֶת הַשַּׁבָּת אֶלָּא נִמּוֹל בְּאֶחָד בְּשַׁבָּת. שֶׁאֵין דּוֹחִין אֶת הַשַּׁבָּת מִסָּפֵק:","מִי שֶׁנּוֹלַד בַּחֹדֶשׁ הַשְּׁמִינִי. אִם הָיָה שָׁלֵם בִּשְׂעָרוֹ וּבְצִפָּרְנָיו הֲרֵי זֶה וָלָד שָׁלֵם וּבֶן שִׁבְעָה הוּא אֶלָּא שֶׁנִּשְׁתַּהָה. וּמֻתָּר לְטַלְטְלוֹ בְּשַׁבָּת וְאֵינוֹ כְּאֶבֶן. וּמָלִין אוֹתוֹ בְּשַׁבָּת. אֲבָל אִם נוֹלַד וּשְׂעָרוֹ לָקוּי וְאֵין צִפָּרְנָיו שְׁלֵמִין כִּבְרִיָּתָן הֲרֵי זֶה בֶּן שְׁמוֹנָה וַדַּאי שֶׁלֹּא הָיָה רָאוּי לְהִוָּלֵד אֶלָּא בְּתִשְׁעָה וְיָצָא קֹדֶם שֶׁיִּגָּמֵר. וּלְפִיכָךְ הוּא חָשׁוּב כְּאֶבֶן וְאָסוּר לְטַלְטְלוֹ בְּשַׁבָּת. וְאַף עַל פִּי כֵן אִם שָׁהָה שְׁלֹשִׁים יוֹם הֲרֵי הוּא וָלָד שֶׁל קַיָּמָא. וַהֲרֵי הוּא כִּשְׁאָר הַנּוֹלָדִין לְכָל דָּבָר. שֶׁכָּל שֶׁשָּׁהָה שְׁלֹשִׁים יוֹם בָּאָדָם אֵינוֹ נֵפֶל:","מִי שֶׁנּוֹלַד בַּחֹדֶשׁ הַשְּׁבִיעִי לְעִבּוּרוֹ אִם נוֹלַד שָׁלֵם הֲרֵי זֶה וָלָד שֶׁל קַיָּמָא וּמָלִין אוֹתוֹ בְּשַׁבָּת. סָפֵק בֶּן שִׁבְעָה סָפֵק בֶּן שְׁמוֹנָה מָלִין אוֹתוֹ בְּשַׁבָּת עַל כָּל פָּנִים. אִם בֶּן שִׁבְעָה הוּא וְשָׁלֵם הוּא בְּדִין הוּא שֶׁיִּדְחֶה שַׁבָּת. וְאִם בֶּן שְׁמוֹנָה הוּא הֲרֵי זֶה שֶׁמָּל כִּמְחַתֵּךְ בָּשָׂר הוּא לְפִי שֶׁזֶּה נֵפֶל אִם הוּא בֶּן שְׁמוֹנָה:","הוֹצִיא הָעֻבָּר רֹאשׁוֹ חוּץ לִמְעֵי אִמּוֹ בֵּין הַשְּׁמָשׁוֹת אַף עַל פִּי שֶׁלֹּא יָצָא כֻּלּוֹ אֶלָּא בְּלֵילֵי שַׁבָּת אֵין מָלִין אוֹתוֹ בְּשַׁבָּת. וְכָל מִי שֶׁאֵינוֹ דּוֹחֶה אֶת הַשַּׁבָּת אֵינוֹ דּוֹחֶה אֶת יוֹם טוֹב רִאשׁוֹן וְדוֹחֶה אֶת יוֹם טוֹב שֵׁנִי. וּבִשְׁנֵי יָמִים טוֹבִים שֶׁל רֹאשׁ הַשָּׁנָה אֵינוֹ דּוֹחֶה לֹא אֶת הָרִאשׁוֹן וְלֹא אֶת הַשֵּׁנִי. וְכֵן מִילָה שֶׁלֹּא בִּזְמַנָּהּ אֵינָהּ דּוֹחָה אֶת שְׁנֵי יָמִים טוֹבִים שֶׁל רֹאשׁ הַשָּׁנָה:","חוֹלֶה אֵין מָלִין אוֹתוֹ עַד שֶׁיַּבְרִיא. וּמוֹנִין לוֹ מֵעֵת שֶׁיַּבְרִיא מֵחָלְיוֹ שִׁבְעָה יָמִים מֵעֵת לְעֵת וְאַחַר כָּךְ מָלִין אוֹתוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁחֲלַצְתּוֹ חַמָּה וְכַיּוֹצֵא בְּחלִי זֶה. אֲבָל אִם כָּאֲבוּ לוֹ עֵינָיו בְּעֵת שֶׁיִּפָּתְחוּ עֵינָיו וְיֵרָפְאוּ מָלִין אוֹתוֹ מִיָּד. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","קָטָן שֶׁנִּמְצָא בַּשְּׁמִינִי שֶׁלּוֹ יָרוֹק בְּיוֹתֵר אֵין מָלִין אוֹתוֹ עַד שֶׁיִּפּל בּוֹ דָּם וְיַחְזְרוּ מַרְאָיו כְּמַרְאֵה הַקְּטַנִּים הַבְּרִיאִים. וְכֵן אִם הָיָה אָדֹם בְּיוֹתֵר כְּמִי שֶׁצָּבְעוּ אוֹתוֹ אֵין מָלִין אוֹתוֹ עַד שֶׁיִּבָּלַע בּוֹ דָּמוֹ וְיַחְזְרוּ מַרְאָיו כִּשְׁאָר הַקְּטַנִּים מִפְּנֵי שֶׁזֶּה חלִי הוּא. וְצָרִיךְ לְהִזָּהֵר בִּדְבָרִים אֵלּוּ הַרְבֵּה:","אִשָּׁה שֶׁמָּלָה בְּנָהּ רִאשׁוֹן וּמֵת מֵחֲמַת מִילָה שֶׁהִכְשִׁילָה אֶת כֹּחוֹ. וְכֵן מָלָה אֶת הַשֵּׁנִי וּמֵת מֵחֲמַת מִילָה. בֵּין מִבַּעֲלָהּ הָרִאשׁוֹן בֵּין מִבַּעֲלָהּ הַשֵּׁנִי הֲרֵי זֶה לֹא יָמוּל אֶת הַשְּׁלִישִׁי בִּזְמַנּוֹ. אֶלָּא מַמְתִּינִין לוֹ עַד שֶׁיַּגְדִּיל וְיִתְחַזֵּק כֹּחוֹ. אֵין מָלִין אֶלָּא וָלָד שֶׁאֵין בּוֹ שׁוּם חלִי. שֶׁסַּכָּנַת נְפָשׁוֹת דּוֹחָה אֶת הַכּל. וְאֶפְשָׁר לָמוּל לְאַחַר זְמַן וְאִי אֶפְשָׁר לְהַחֲזִיר נֶפֶשׁ אַחַת מִיִּשְׂרָאֵל לְעוֹלָם:"],"Mishneh Torah, Creditor and Debtor 18":["הַמַּלְוֶה אֶת חֲבֵרוֹ סְתָם הֲרֵי כָּל נְכָסָיו אַחְרָאִין וְעַרְבָאִין לְחוֹב זֶה. לְפִיכָךְ כְּשֶׁיָּבוֹא לִגְבּוֹת תּוֹבֵעַ אֶת בַּעַל חוֹבוֹ תְּחִלָּה אִם מָצָא עִמּוֹ נְכָסִים בֵּין מִטַּלְטְלִין בֵּין קַרְקָעוֹת גּוֹבֶה מֵהֶן בִּרְצוֹן הַלּוֶֹה. וְאִם לֹא נָתַן הַלּוֶֹה מִדַּעְתּוֹ מְגַבִּין אוֹתוֹ בֵּית דִּין. לֹא הִסְפִּיק לוֹ כָּל הַנִּמְצָא כְּנֶגֶד שְׁטַר חוֹבוֹ הֲרֵי זֶה גּוֹבֶה מִכָּל הַקַּרְקָעוֹת שֶׁהָיוּ לַלּוֶֹה אַף עַל פִּי שֶׁהֵן עַתָּה מְכוּרִין לַאֲחֵרִים אוֹ נְתוּנִים בְּמַתָּנָה. הוֹאִיל וּמָכַר הַלּוֶֹה אוֹ נָתַן אַחַר שֶׁנִּשְׁתַּעְבֵּד בְּחוֹב זֶה הֲרֵי זֶה מוֹצִיא מִיַּד הַלָּקוֹחוֹת אוֹ מִיַּד בַּעֲלֵי הַמַּתָּנוֹת וְזֶהוּ הַנִּקְרָא טוֹרֵף. בַּמֶּה דְּבָרִים אֲמוּרִים בְּקַרְקָעוֹת שֶׁהָיוּ לוֹ בְּעֵת שֶׁלָּוָה. אֲבָל נְכָסִים הַבָּאִין לוֹ לְאַחַר שֶׁלָּוָה לֹא נִשְׁתַּעְבְּדוּ לְבַעַל חוֹב וְאֵינוֹ טוֹרְפָן. וְאִם הִתְנָה עָלָיו שֶׁכָּל נְכָסִים שֶׁיִּקְנֶה יִהְיוּ מְשֻׁעְבָּדִין לְהִפָּרַע מֵהֶן וְקָנָה אַחַר שֶׁלָּוָה וּמָכַר אוֹ נָתַן הֲרֵי בַּעַל חוֹב טוֹרֵף מֵהֶן:","אֵין כָּל הַדְּבָרִים אֲמוּרִין אֶלָּא בְּקַרְקַע אֲבָל הַמִּטַּלְטְלִין אֵין עֲלֵיהֶן אַחֲרָיוּת אֲפִלּוּ מִטַּלְטְלִין שֶׁהָיוּ לוֹ בְּעֵת שֶׁלָּוָה שֶׁמְּכָרָן לִשְׁעָתוֹ אֵין בַּעַל חוֹב טוֹרֵף אוֹתָן. הִקְנָה לְבַעַל חוֹבוֹ כָּל הַמִּטַּלְטְלִין עַל גַּב קַרְקַע שֶׁיֵּשׁ לוֹ לִהְיוֹתוֹ נִפְרָע מִן הַכּל הֲרֵי זֶה טוֹרֵף מֵאוֹתָן הַמִּטַּלְטְלִין וְהוּא שֶׁיִּכְתֹּב לוֹ בִּשְׁטַר חוֹבוֹ שֶׁהִקְנֵיתִי לְךָ מִטַּלְטְלִין שֶׁיֵּשׁ לִי עַל גַּב הַקַּרְקַע שֶׁיֵּשׁ לִי שֶׁלֹּא כְּאַסְמַכְתָּא וְשֶׁלֹּא כְּטָפְסֵי הַשְּׁטָרוֹת. וְכֵן אִם כָּתַב שֶׁכָּל נְכָסִים שֶׁאֲנִי עָתִיד לִקְנוֹת בֵּין קַרְקָעוֹת בֵּין מִטַּלְטְלִין הֲרֵי הֵן מְשֻׁעְבָּדִים לְךָ לְהִפָּרַע מֵהֶן וְהַמִּטַּלְטְלִין קְנוּיִין לְךָ עַל גַּב הַקַּרְקָעוֹת לְהִפָּרַע מֵהֶן שֶׁלֹּא כְּאַסְמַכְתָּא וְשֶׁלֹּא כְּטָפְסֵי הַשְּׁטָרוֹת הֲרֵי זֶה טוֹרֵף אַף מִן הַמִּטַּלְטְלִין שֶׁקָּנָה הַלּוֶֹה לְאַחַר שֶׁלָּוָה. שֶׁכָּל תְּנַאי שֶׁבְּמָמוֹן קַיָּם:","עָשָׂה שָׂדֵהוּ אַפּוֹתֵיקֵי לְבַעַל חוֹבוֹ אוֹ לְאִשָּׁה בִּכְתֻבָּתָהּ וְהוּא שֶׁיִּכְתֹּב לָהֶן מִכָּאן תִּגְבּוּ וּשְׁטָפוֹ נָהָר הֲרֵי זֶה גּוֹבֶה מִשְּׁאָר נְכָסִים וְטוֹרֵף אוֹתָן. וְאִם הִתְנָה עִמּוֹ שֶׁלֹּא יִהְיֶה לוֹ פֵּרָעוֹן אֶלָּא מִזּוֹ אֵינוֹ גּוֹבֶה מִשְּׁאָר נְכָסִים. וְכֵן אִם לָוָה מִמֶּנּוּ וּפֵרֵשׁ שֶׁאֵין לוֹ אַחֲרָיוּת עָלָיו הֲרֵי זֶה אֵינוֹ גּוֹבֶה מִן הַמְשֻׁעְבָּדִין לְעוֹלָם:","עָשָׂה שָׂדֵהוּ אַפּוֹתֵיקִי לְבַעַל חוֹבוֹ אוֹ לְאִשָּׁה בִּכְתֻבָּתָהּ וּמְכָרָהּ הֲרֵי זוֹ מְכוּרָה וּכְשֶׁיָּבוֹא בַּעַל חוֹב לִגְבּוֹת אִם לֹא יִמְצָא נְכָסִים בְּנֵי חוֹרִין יִטְרֹף אוֹתָהּ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁמָּכַר לִשְׁעָתָהּ אֲבָל מְכָרָהּ מִמְכַּר עוֹלָם אֵינָהּ מְכוּרָה:","עָשָׂה עַבְדּוֹ אַפּוֹתֵיקֵי וּמְכָרוֹ הֲרֵי בַּעַל חוֹב גּוֹבֶה מִמֶּנּוּ מִפְּנֵי שֶׁיֵּשׁ לוֹ קוֹל. עָשָׂה שׁוֹרוֹ אַפּוֹתֵיקֵי וּמְכָרוֹ אֵין בַּעַל חוֹב גּוֹבֶה מִמֶּנּוּ. וְכֵן שְׁאָר הַמִּטַּלְטְלִין מִפְּנֵי שֶׁאֵין לָהֶן קוֹל:","עֶבֶד שֶׁעֲשָׂאָהוּ רַבּוֹ אַפּוֹתֵיקֵי וְשִׁחְרְרוֹ אַף עַל פִּי שֶׁכָּתַב לוֹ לֹא יִהְיֶה לְךָ פֵּרָעוֹן אֶלָּא מִזֶּה יֵצֵא לְחֵרוּת. וְכֵן אִם הִקְדִּישׁוֹ. שֶׁהֶחָמֵץ וְהַשִּׁחְרוּר וְהַהֶקְדֵּשׁ מַפְקִיעִין מִיַּד שִׁעְבּוּד וַהֲרֵי בַּעַל חוֹב גּוֹבֶה חוֹבוֹ מִן הַלּוֶֹה וְכוֹתֵב עָלָיו שְׁטָר בְּחוֹבוֹ וְטוֹרֵף מִזְּמַן זֶה הַשְּׁטָר. וְלָמָּה הוּא חַיָּב לְשַׁלֵּם מִפְּנֵי שֶׁגּוֹרֵם לְאַבֵּד מָמוֹן חֲבֵרוֹ וְכָל הַגּוֹרֵם לְהַזִּיק מְשַׁלֵּם כְּמוֹ שֶׁבֵּאַרְנוּ בִּמְקוֹמוֹ. וְכוֹפִין אֶת רַבּוֹ הַשֵּׁנִי לְשַׁחְרְרוֹ מִפְּנֵי תִּקּוּן הָעוֹלָם שֶׁלֹּא יִמְצָאֶנּוּ בַּשּׁוּק וְיֹאמַר לוֹ עַבְדִּי אַתָּה:","הַמַּקְדִּישׁ נְכָסָיו אֵין בַּעַל חוֹב יָכוֹל לִטְרֹף מִן הַהֶקְדֵּשׁ שֶׁהַהֶקְדֵּשׁ מַפְקִיעַ הַשִּׁעְבּוּד. וּכְשֶׁפּוֹדִין הַקַּרְקַע מִיַּד הַהֶקְדֵּשׁ אוֹמְדִין כַּמָּה אָדָם רוֹצֶה לִתֵּן בְּשָׂדֶה זוֹ עַל מְנָת שֶׁיִּתֵּן לְבַעַל חוֹב אֶת חוֹבוֹ וּלְאִשָּׁה כְּתֻבָּתָהּ. לְפִיכָךְ לִכְשֶׁתִּפָּדֶה וְתֵצֵא לְחֻלִּין בְּיַד הַלּוֹקֵחַ יָבוֹא בַּעַל חוֹב וְיִטְרֹף אוֹתָהּ אוֹ הָאִשָּׁה בִּכְתֻבָּתָהּ כְּמוֹ שֶׁבֵּאַרְנוּ בַּעֲרָכִין:","בַּעַל חוֹב שֶׁבָּא לִטְרֹף אִם יֵשׁ מָעוֹת לַלּוֹקֵחַ יָכוֹל לְסַלְּקוֹ וְלִתֵּן לוֹ דְּמֵי מַה שֶּׁהוּא טוֹרֵף וְחוֹזֵר הַלּוֹקֵחַ וְתוֹבֵעַ לַמּוֹכֵר. וְאִם עָשָׂה אוֹתוֹ אַפּוֹתֵיקֵי אֵינוֹ יָכוֹל לְסַלְּקוֹ בְּדָמִים:","רְאוּבֵן שֶׁהָיָה חַיָּב לְשִׁמְעוֹן מָאתַיִם וְהָיוּ לוֹ שְׁתֵּי שָׂדוֹת וּמָכַר אַחַת מֵהֶן לְלֵוִי בְּמָנֶה וְחָזַר וּמָכַר לוֹ הַשְּׁנִיָּה בְּמָנֶה וּבָא שִׁמְעוֹן וְטָרַף אַחַת בְּמָנֶה וְחָזַר לִטְרֹף הַשְּׁנִיָּה בַּמָּנֶה הַנִּשְׁאָר לוֹ וְהֵבִיא לוֹ מָאתַיִם וְאָמַר לוֹ אִם תִּרְצֶה לִהְיוֹת הַשָּׂדֶה שֶׁטָּרַפְתָּ שׁוּמָה לְךָ בְּכָל הַמָּאתַיִם שֶׁיֵּשׁ לְךָ הֲרֵי מוּטָב וְאִם לָאו הֵילָךְ מָאתַיִם שֶׁל חוֹבְךָ וְהִסְתַּלֵּק. הַדִּין עִם לֵוִי. רָצָה שִׁמְעוֹן וְעָמַד בָּהּ אַף עַל פִּי שֶׁקִּבְּלָהּ בְּמָאתַיִם אֵין לֵוִי חוֹזֵר וְתוֹבֵעַ רְאוּבֵן אֶלָּא בְּמָנֶה:","מֵת רְאוּבֵן וְהִנִּיחַ שָׂדֶה אַחַת שָׁוָה מֵאָה וּבָא שִׁמְעוֹן וּטְרָפָהּ וְנָתְנוּ לוֹ הַיְתוֹמִים מֵאָה מִן הַמִּטַּלְטְלִין שֶׁהִנִּיחַ אֲבִיהֶן וְסִלְּקוּהוּ הֲרֵי זֶה חוֹזֵר וְטוֹרֵף אוֹתָהּ בִּשְׁאָר חוֹבוֹ. שֶׁמֵּאָה שֶׁנָּתְנוּ לוֹ מִצְוָה עָשׂוּ שֶׁמִּצְוָה עַל הַיְתוֹמִים לִפְרֹעַ חוֹבוֹת אֲבִיהֶם. וְאִם אָמְרוּ לוֹ אֵלּוּ בְּמֵאָה דְּמֵי הַשָּׂדֶה שֶׁטָּרַפְתָּ אֵינוֹ יָכוֹל לַחְזֹר וְלִטְרֹף אוֹתָהּ פַּעַם אַחֶרֶת בִּשְׁאָר חוֹבוֹ:"],"Mishneh Torah, Creditor and Debtor 4":["נֶשֶׁךְ וּמַרְבִּית אֶחָד הוּא שֶׁנֶּאֱמַר (ויקרא כה לז) \"אֶת כַּסְפְּךָ לֹא תִתֵּן לוֹ בְּנֶשֶׁךְ וּבְמַרְבִּית לֹא תִתֵּן אָכְלֶךָ\" וּלְהַלָּן הוּא אוֹמֵר (דברים כג כ) \"נֶשֶׁךְ כֶּסֶף נֶשֶׁךְ אֹכֶל נֶשֶׁךְ כָּל דָּבָר אֲשֶׁר יִשָּׁךְ\". וְלָמָּה נִקְרָא שְׁמוֹ נֶשֶׁךְ מִפְּנֵי שֶׁהוּא נוֹשֵׁךְ שֶׁמְּצַעֵר אֶת חֲבֵרוֹ וְאוֹכֵל אֶת בְּשָׂרוֹ. וְלָמָּה חִלְּקָן הַכָּתוּב לַעֲבֹר עָלָיו בִּשְׁנֵי לָאוִין:","כְּדֶרֶךְ שֶׁאָסוּר לְהַלְווֹת כָּךְ אָסוּר לִלְווֹת בְּרִבִּית שֶׁנֶּאֱמַר (דברים כג כ) \"לֹא תַשִּׁיךְ לְאָחִיךָ\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזּוֹ אַזְהָרָה לַלּוֶֹה כְּלוֹמַר לֹא תִּנְשֹׁךְ לְאָחִיךְ. וְכֵן אָסוּר לְהִתְעַסֵּק בֵּין לוֶֹה וּמַלְוֶה בְּרִבִּית. וְכָל מִי שֶׁהָיָה עָרֵב אוֹ סוֹפֵר אוֹ עֵד בֵּינֵיהֶן הֲרֵי זֶה עוֹבֵר בְּלֹא תַּעֲשֶׂה. שֶׁנֶּאֱמַר (שמות כב כד) \"לֹא תְשִׂימוּן עָלָיו נֶשֶׁךְ\" זוֹ אַזְהָרָה אַף לָעֵדִים וְלָעָרֵב וְלַסּוֹפֵר. הָא לָמַדְתָּ שֶׁהַמַּלְוֶה בְּרִבִּית עוֹבֵר עַל שִׁשָּׁה לָאוִין. (שמות כב כד) \"לֹא תִהְיֶה לוֹ כְּנשֶׁה\". (ויקרא כה לז) \"אֶת כַּסְפְּךָ לֹא תִתֵּן לוֹ בְּנֶשֶׁךְ\". (ויקרא כה לז) \"וּבְמַרְבִּית לֹא תִתֵּן אָכְלֶךָ\". (ויקרא כה לו) \"אַל תִּקַּח מֵאִתּוֹ נֶשֶׁךְ וְתַרְבִּית\". לֹא תְשִׂימוּן עָלָיו נֶשֶׁךְ. (ויקרא יט יד) \"וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁל\". וְהַלּוֶֹה עוֹבֵר בִּשְׁנַיִם. לֹא תַשִּׁיךְ לְאָחִיךָ. וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁל. עָרֵב וְעֵדִים וְכַיּוֹצֵא בָּהֶן אֵין עוֹבְרִין אֶלָּא מִשּׁוּם לֹא תְשִׂימוּן עָלָיו נֶשֶׁךְ. וְכָל מִי שֶׁהָיָה סַרְסוּר בֵּין שְׁנֵיהֶם אוֹ שֶׁסִּיֵּעַ אֶחָד מֵהֶן אוֹ הוֹרָהוּ עוֹבֵר מִשּׁוּם לִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁל:","אַף עַל פִּי שֶׁהַמַּלְוֶה וְהַלּוֶֹה עוֹבְרִין עַל כָּל אֵלּוּ הַלָּאוִין אֵינָן לוֹקִין עָלָיו מִפְּנֵי שֶׁנִּתָּן לְהִשָּׁבוֹן. שֶׁכָּל הַמַּלְוֶה בְּרִבִּית אִם הָיְתָה רִבִּית קְצוּצָה שֶׁהִיא אֲסוּרָה מִן הַתּוֹרָה הֲרֵי זוֹ יוֹצְאָה בְּדַיָּנִין וּמוֹצִיאִין אוֹתָהּ מִן הַמַּלְוֶה וּמַחְזִירִין לַלּוֶֹה. וְאִם מֵת הַמַּלְוֶה אֵין מוֹצִיאִין מִיַּד הַבָּנִים:","הִנִּיחַ לָהֶם אֲבִיהֶם מָעוֹת שֶׁל רִבִּית אַף עַל פִּי שֶׁהֵן יוֹדְעִין שֶׁהֵן שֶׁל רִבִּית אֵינָן חַיָּבִים לְהַחְזִיר. הִנִּיחַ לָהֶם פָּרָה וְטַלִּית שֶׁל רִבִּית וְכָל דָּבָר הַמְסֻיָּם חַיָּבִים לְהַחְזִיר מִפְּנֵי כְּבוֹד אֲבִיהֶן. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁעָשָׂה תְּשׁוּבָה וְלֹא הִסְפִּיק לְהַחְזִיר עַד שֶׁמֵּת. אֲבָל אִם לֹא עָשָׂה תְּשׁוּבָה אֵין חוֹשְׁשִׁין לִכְבוֹדוֹ וַאֲפִלּוּ דָּבָר הַמְסֻיָּם אֵין מַחֲזִירִין:","הַגַּזְלָנִין וּמַלְוֵי בְּרִבִּית שֶׁהֶחְזִירוּ אֵין מְקַבְּלִין מֵהֶן כְּדֵי לִפְתֹּחַ לָהֶן דֶּרֶךְ לִתְשׁוּבָה. וְכָל הַמְקַבֵּל מֵהֶן אֵין רוּחַ חֲכָמִים נוֹחָה הֵימֶנּוּ. אִם הָיְתָה גְּזֵלָה קַיֶּמֶת וְהָרִבִּית דָּבָר הַמְסֻיָּם וַהֲרֵי הוּא בְּעַצְמוֹ מְקַבְּלִין מֵהֶן:","שְׁטָר שֶׁכָּתוּב בּוֹ רִבִּית בֵּין קְצוּצָה בֵּין שֶׁל דִּבְרֵיהֶם גּוֹבֶה אֶת הַקֶּרֶן וְאֵינוֹ גּוֹבֶה אֶת הָרִבִּית. קָדַם וְגָבָה הַכּל מוֹצִיאִין מִמֶּנּוּ הָרִבִּית קְצוּצָה. אֲבָל אֲבַק רִבִּית שֶׁהוּא מִדִּבְרֵיהֶם אֵינוֹ גּוֹבֶה מִן הַלּוֶֹה לַמַּלְוֶה וְאֵין מַחֲזִירִין אוֹתוֹ מִן הַמַּלְוֶה לַלּוֶֹה:","כָּל הַכּוֹתֵב שְׁטַר רִבִּית הֲרֵי זֶה כְּכוֹתֵב וּמֵעִיד עָלָיו עֵדִים שֶׁכָּפַר בַּה' אֱלֹהֵי יִשְׂרָאֵל. וְכֵן כָּל הַלּוֶֹה וּמַלְוֶה בְּרִבִּית בֵּינָן לְבֵין עַצְמָן הֲרֵי הֵן כְּכוֹפְרִים בַּה' אֱלֹהֵי יִשְׂרָאֵל וְכָפְרוּ בִּיצִיאַת מִצְרַיִם שֶׁנֶּאֱמַר (ויקרא כה לז) \"אֶת כַּסְפְּךָ לֹא תִתֵּן לוֹ בְּנֶשֶׁךְ\" וְגוֹ' (ויקרא כה לח) \"אֲנִי ה' אֱלֹהֵיכֶם אֲשֶׁר הוֹצֵאתִי אֶתְכֶם מֵאֶרֶץ מִצְרָיִם\":","אָסוּר לְאָדָם לְהַלְווֹת בָּנָיו וּבְנֵי בֵּיתוֹ בְּרִבִּית. אַף עַל פִּי שֶׁאֵינוֹ מַקְפִּיד וּמַתָּנָה הוּא שֶׁנּוֹתֵן לָהֶן הֲרֵי זֶה אָסוּר שֶׁמָּא יַרְגִּילֵם בְּדָבָר זֶה:","תַּלְמִידֵי חֲכָמִים שֶׁהִלְווּ זֶה אֶת זֶה וְנָתַן לוֹ יֶתֶר עַל מַה שֶּׁהִלְוָה מִמֶּנּוּ הֲרֵי זֶה מֻתָּר שֶׁהַדָּבָר יָדוּעַ שֶׁלֹּא נָתַן לוֹ אֶלָּא מַתָּנָה שֶׁהֲרֵי הֵן יוֹדְעִין חֹמֶר אִסּוּר הָרִבִּית:","הַמַּלְוֶה אֶת חֲבֵרוֹ וּמָצָא הַלּוֶֹה יוֹתֵר [אוֹ שֶׁהֶחְזִיר לוֹ חוֹבוֹ וּמָצָא הַמַּלְוֶה יוֹתֵר] אִם בִּכְדֵי שֶׁהַדַּעַת טוֹעָה חַיָּב לְהַחְזִיר וְאִם לָאו מַתָּנָה הוּא שֶׁנָּתַן לוֹ אוֹ גְּזֵלָה הָיְתָה לוֹ בְּיָדוֹ וְהִבְלִיעַ לוֹ בְּחֶשְׁבּוֹן אוֹ אַחֵר צִוָּה לְהַבְלִיעַ לוֹ. בְּכַמָּה הַדַּעַת טוֹעָה בְּאֶחָד וּבִשְׁנַיִם אוֹ בַּחֲמִשָּׁה אוֹ בַּעֲשָׂרָה שֶׁמָּא מָנָה חֲמִשָּׁה חֲמִשָּׁה אוֹ עֲשָׂרָה עֲשָׂרָה. וְכֵן אִם מָצָא יָתֵר מִנְיַן הַחֲמִישִׁיּוֹת אוֹ מִנְיַן הָעֲשִׂירִיּוֹת אֶחָד אֶחָד חַיָּב לְהַחְזִיר לוֹ שֶׁמָּא הָאֲחָדִים שֶׁהָיָה מוֹנֶה בָּהֶן הַחֲמִישִׁיּוֹת אוֹ הָעֲשִׂירִיּוֹת נִתְעָרְבוּ עִמָּהֶם:","הַמַּלְוֶה אֶת חֲבֵרוֹ עַל הַמַּטְבֵּעַ וְכֵן הַכּוֹתֵב לְאִשְׁתּוֹ בִּכְתֻבָּתָהּ מַטְבֵּעַ יָדוּעַ וּפֵרֵשׁ מִשְׁקָלוֹ וְהוֹסִיפוּ עַל מִשְׁקָלוֹ אִם הוּזְלוּ הַפֵּרוֹת מֵחֲמַת הַתּוֹסֶפֶת מְנַכֶּה לוֹ שִׁעוּר הַתּוֹסֶפֶת וַאֲפִלּוּ הוֹסִיפוּ עָלָיו כָּל שֶׁהוּא. וְאִם לֹא הוּזְלוּ מֵחֲמַת הַתּוֹסֶפֶת אֵינוֹ מְנַכֶּה לוֹ אֶלָּא נוֹתֵן לוֹ מִמַּטְבֵּעַ הַיּוֹצֵא בְּאוֹתָהּ שָׁעָה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהוֹסִיפוּ עָלָיו עַד חֲמִישִׁיתוֹ כְּגוֹן שֶׁהָיָה מִשְׁקָלוֹ אַרְבָּעָה וַעֲשָׂאוֹ חֲמִשָּׁה אֲבָל אִם הוֹסִיפוּ לוֹ יוֹתֵר עַל חֲמִישִׁיתוֹ מְנַכֶּה לוֹ כָּל הַתּוֹסֶפֶת אַף עַל פִּי שֶׁלֹּא הוּזְלוּ הַפֵּרוֹת. וְהוּא הַדִּין לְמַלְוֶה עַל הַמַּטְבֵּעַ וּפָחֲתוּ מִמֶּנּוּ:","הַמַּלְוֶה אֶת חֲבֵרוֹ עַל הַמַּטְבֵּעַ וְנִפְסַל אִם יָכוֹל לְהוֹצִיאוֹ בִּמְדִינָה אַחֶרֶת וְיֵשׁ לוֹ דֶּרֶךְ לְאוֹתָהּ מְדִינָה נוֹתֵן לוֹ מִמַּטְבֵּעַ שֶׁהִלְוָהוּ וְאוֹמֵר לוֹ לֵךְ וְהוֹצִיאוֹ בְּמָקוֹם פְּלוֹנִי. וְאִם אֵין לוֹ דֶּרֶךְ לְשָׁם נוֹתֵן לוֹ מִמַּטְבֵּעַ הַיּוֹצֵא בְּאוֹתָהּ שָׁעָה. וְכֵן בִּכְתֻבָּה:","הוֹרוּ מִקְצָת הַגְּאוֹנִים שֶׁהַלּוֶֹה שֶׁמָּחַל לַמַּלְוֶה בְּרִבִּית שֶׁלָּקַח מִמֶּנּוּ אוֹ שֶׁעָתִיד לִקַּח אַף עַל פִּי שֶׁקָּנוּ מִיָּדוֹ שֶׁמָּחַל אוֹ נָתַן מַתָּנָה אֵינוֹ מוֹעִיל כְּלוּם שֶׁכָּל רִבִּית שֶׁבָּעוֹלָם מְחִילָה הִיא אֲבָל הַתּוֹרָה לֹא מָחֲלָה וְאָסְרָה מְחִילָה זוֹ וּלְפִיכָךְ אֵין הַמְּחִילָה מוֹעֶלֶת בְּרִבִּית אֲפִלּוּ בְּרִבִּית שֶׁל דִּבְרֵיהֶם. יֵרָאֶה לִי שֶׁאֵין הוֹרָאָה זוֹ נְכוֹנָה אֶלָּא מֵאַחַר שֶׁאוֹמְרִים לַמַּלְוֶה לְהַחְזִיר לוֹ וְיָדַע הַמַּלְוֶה שֶׁדְּבַר אִסּוּר עָשָׂה וְיֵשׁ לוֹ לִטּל מִמֶּנּוּ אִם רָצָה לִמְחל מוֹחֵל כְּדֶרֶךְ שֶׁמּוֹחֵל הַגֵּזֶל. וּבְפֵרוּשׁ אָמְרוּ חֲכָמִים שֶׁהַגַּזְלָנִין וּמַלְוֵי בְּרִבִּית שֶׁהֶחְזִירוּ אֵין מְקַבְּלִין מֵהֶן מִכְּלָל שֶׁהַמְּחִילָה מוֹעֶלֶת:","נִכְסֵי יְתוֹמִים מֻתָּר לִתֵּן אוֹתָם לְאָדָם נֶאֱמָן שֶׁיֵּשׁ לוֹ נְכָסִים טוֹבִים קָרוֹב לְשָׂכָר וְרָחוֹק לְהֶפְסֵד. כֵּיצַד. אוֹמֵר לוֹ תִּהְיֶה נוֹשֵׂא וְנוֹתֵן בָּהֶן אִם יֵשׁ שָׁם רֶוַח תֵּן לָהֶם חֶלְקָן מִן הָרֶוַח וְאִם יֵשׁ שָׁם הֶפְסֵד תַּפְסִיד אַתָּה לְבַדְּךָ שֶׁזֶּה אֲבַק רִבִּית הוּא וְכָל אֲבַק רִבִּית אֵינָהּ אֲסוּרָה אֶלָּא מִדִּבְרֵיהֶם וּבְנִכְסֵי יְתוֹמִים לֹא גָּזְרוּ:"],"Mishneh Torah, Daily Offerings and Additional Offerings 6":["סֵדֶר עֲבוֹדוֹת הַתְּמִידוֹת בְּכָל יוֹם כָּךְ הוּא. סָמוּךְ לַעֲלוֹת הַשַּׁחַר יָבוֹא הַמְמֻנֶּה שֶׁעַל הַפְּיָסוֹת וְיַקִּישׁ עַל הָעֲזָרָה וּפוֹתְחִין לוֹ. וּמְבַלְּשִׁין אֶת כָּל הָעֲזָרָה. וּמַעֲמִידִין עוֹשֵׂי חֲבִיתִין לַעֲשׂוֹת הַחֲבִיתִין. וְכָל הַכֹּהֲנִים שֶׁשָּׁם כְּבָר טָבְלוּ קֹדֶם שֶׁיָּבוֹא הַמְמֻנֶּה וְלָבְשׁוּ בִּגְדֵי כְּהֻנָּה. וְיָבוֹאוּ וְיַעַמְדוּ בְּלִשְׁכַּת הַגָּזִית. וְיָפִיסוּ פַּיִס רִאשׁוֹן וְשֵׁנִי וְיִזְכֶּה כָּל אֶחָד בִּמְלַאכְתּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. וּמַתְחִיל זֶה שֶׁזָּכָה בִּתְרוּמַת הַדֶּשֶׁן וְתוֹרֵם עַל הַסֵּדֶר שֶׁאָמַרְנוּ. וְאַחַר כָּךְ מְסַדֵּר מַעֲרָכָה גְּדוֹלָה. וְאַחַר כָּךְ מְסַדֵּר מַעֲרָכָה שְׁנִיָּה. וְאַחַר כָּךְ מַעֲלֶה שְׁנֵי גִּזְרֵי עֵצִים וּמַנִּיחָן עַל מַעֲרָכָה גְּדוֹלָה לְהַרְבּוֹת הָאֵשׁ. וְאַחַר כָּךְ נִכְנָסִין לְלִשְׁכַּת הַכֵּלִים וּמוֹצִיאִין כָּל כְּלֵי הַשָּׁרֵת הַצְּרִיכִין לָהֶן כָּל הַיּוֹם. וּמַשְׁקִין אֶת הַתָּמִיד מַיִם וְזֶה שֶׁזָּכָה בִּשְׁחִיטָתוֹ מוֹשְׁכוֹ לְבֵית הַמִּטְבָּחַיִם. וְהוֹלְכִין אַחֲרָיו הַכֹּהֲנִים שֶׁזָּכוּ לְהַעֲלוֹת הָאֵיבָרִים וְשׁוֹהִין שָׁם עַד שֶׁפּוֹתְחִין שַׁעַר הַהֵיכָל הַגָּדוֹל. וּבִשְׁעַת פְּתִיחַת הַשַּׁעַר שׁוֹחֲטִין אֶת הַתָּמִיד. וְאַחַר כָּךְ נִכְנָסִין לַהֵיכָל שְׁנֵי כֹּהֲנִים. הָאֶחָד שֶׁזָּכָה בְּדִשּׁוּן הַמִּזְבֵּחַ הַפְּנִימִי וְהַשֵּׁנִי שֶׁזָּכָה בְּדִשּׁוּן הַמְּנוֹרָה:","וְהַמְדַשֵּׁן אֶת הַמִּזְבֵּחַ מְדַשְּׁנוֹ בְּשָׁעָה שֶׁהַשּׁוֹחֵט שׁוֹחֵט אֶת הַתָּמִיד. וְאַחַר כָּךְ זוֹרֵק הַדָּם זֶה שֶׁקִּבְּלוֹ:","וְאַחַר שֶׁזּוֹרְקִין אֶת הַדָּם מֵטִיב זֶה שֶׁבַּהֵיכָל חָמֵשׁ נֵרוֹת וְיוֹצְאִין שְׁנֵיהֶן מִן הַהֵיכָל. וְאֵלּוּ שֶׁבְּבֵית הַמִּטְבָּחַיִם מַפְשִׁיטִין וּמְנַתְּחִין וְכָל אֶחָד וְאֶחָד מַעֲלֶה אֵיבָר שֶׁזָּכָה בּוֹ לַכֶּבֶשׁ. וְנוֹתְנִין הָאֵיבָרִים מֵחֲצִי כֶּבֶשׁ וּלְמַטָּה בְּמַעֲרָבוֹ. וְשֶׁל מוּסָפִין הָיוּ נוֹתְנִין אוֹתָן מֵחֲצִי כֶּבֶשׁ וּלְמַטָּה בְּמִזְרָחוֹ. וְשֶׁל רָאשֵׁי חֳדָשִׁים נוֹתְנִין עַל הַמִּזְבֵּחַ מִלְּמַעְלָה בֵּין קֶרֶן לְקֶרֶן בִּמְקוֹם הִלּוּךְ רַגְלֵי הַכֹּהֲנִים כְּדֵי לְפַרְסְמוֹ שֶׁהוּא רֹאשׁ חֹדֶשׁ. וּמוֹלְחִין שָׁם אֶת הָאֵיבָרִים וְזוֹרְקִין מֶלַח עַל גַּבֵּי הַכֶּבֶשׁ אֲפִלּוּ בְּשַׁבָּת. כְּדֵי שֶׁלֹּא יַחְלִיק וְיִפְּלוּ הַכֹּהֲנִים שָׁם בְּעֵת הֲלִיכָתָן בָּעֵצִים לַמַּעֲרָכָה. וְאַף עַל פִּי שֶׁהַמֶּלַח חוֹצֵץ בֵּין רַגְלֵיהֶם וּבֵין הַכֶּבֶשׁ הוֹאִיל וְאֵין הַהוֹלָכָה הַזֹּאת עֲבוֹדָה אֵינָן חוֹשְׁשִׁין:","וְאַחַר שֶׁמַּעֲלִין הָאֵיבָרִים לַכֶּבֶשׁ מִתְכַּנְּסִין כֻּלָּן לְלִשְׁכַּת הַגָּזִית. וְהַמְמֻנֶּה אוֹמֵר לָהֶם בָּרְכוּ בְּרָכָה אַחַת. וְהֵן פּוֹתְחִין וְקוֹרִין אַהֲבַת עוֹלָם וַעֲשֶׂרֶת הַדִּבְּרוֹת וּשְׁמַע וְהָיָה אִם שָׁמוֹעַ וַיֹּאמֶר וֶאֱמֶת וְיַצִּיב וּרְצֵה וְשִׂים שָׁלוֹם. וּבְשַׁבָּת מוֹסִיפִין בְּרָכָה אַחַת וְהִיא שֶׁיֹּאמְרוּ אַנְשֵׁי מִשְׁמָר הַיּוֹצֵא לְאַנְשֵׁי מִשְׁמָר הַנִּכְנָס. מִי שֶׁשִּׁכֵּן אֶת שְׁמוֹ בַּבַּיִת הַזֶּה יַשְׁכִּין בֵּינֵיכֶם אַהֲבָה אַחְוָה שָׁלוֹם וְרֵעוּת. וְאַחַר כָּךְ מְפִיסִין פַּיִס שְׁלִישִׁי וּרְבִיעִי וְזוֹכֶה בַּקְּטֹרֶת מִי שֶׁזָּכָה וְנִכְנַס וּמַקְטִיר. וְאַחַר כָּךְ נִכְנַס זֶה שֶׁזָּכָה בְּדִשּׁוּן הַמְּנוֹרָה וּמֵטִיב שְׁתֵּי הַנֵּרוֹת וְיוֹצֵא זֶה שֶׁהִקְטִיר עִם מְדַשֵּׁן הַמְּנוֹרָה. וְעוֹמֵד עַל מַעֲלוֹת הָאוּלָם הוּא וְאֶחָיו הַכֹּהֲנִים:","כְּשֶׁיַּגִּיעַ בֵּין הָאוּלָם וְלַמִּזְבֵּחַ. נָטַל אֶחָד הַמַּגְרֵפָה וּזְרָקָהּ בֵּין הָאוּלָם לַמִּזְבֵּחַ. וְהָיָה לָהּ קוֹל גָּדוֹל. וּשְׁלֹשָׁה דְּבָרִים הָיְתָה מְשַׁמֶּשֶׁת בָּהֶן. הַשּׁוֹמֵעַ אֶת קוֹלָהּ הָיָה יוֹדֵעַ שֶׁאֶחָיו הַכֹּהֲנִים נִכְנָסִין לְהִשְׁתַּחֲווֹת וְהוּא רָץ וּבָא. וּבֶן לֵוִי הַשּׁוֹמֵעַ אֶת קוֹלָהּ הָיָה יוֹדֵעַ שֶׁאֶחָיו הַלְוִיִּם נִכְנָסִין לְדַבֵּר בְּשִׁיר וְהוּא רָץ וּבָא. וְרֹאשׁ הַמַּעֲמָד כְּשֶׁהָיָה שׁוֹמֵעַ אֶת קוֹלָהּ הָיָה מַעֲמִיד אֶת הַטְּמֵאִים עַל שַׁעַר הַמִּזְרָח מִפְּנֵי הַחֲשָׁד. שֶׁיֵּדְעוּ הַכּל שֶׁעֲדַיִן לֹא הֵבִיאוּ כַּפָּרָתָן. וְאַחַר כָּךְ מַעֲלֶה זֶה שֶׁזָּכָה בָּאֵיבָרִים אֶת הָאֵיבָרִים מִן הַכֶּבֶשׁ לַמִּזְבֵּחַ. וְאַחַר שֶׁמַּעֲלִין אֶת הָאֵיבָרִים. מַתְחִילִין אֵלּוּ שֶׁעַל מַעֲלוֹת הָאוּלָם וּמְבָרְכִין בִּרְכַּת כֹּהֲנִים בְּרָכָה אַחַת בַּשֵּׁם הַמְפֹרָשׁ כְּמוֹ שֶׁבֵּאַרְנוּ בִּמְקוֹמָהּ. וְאַחַר כָּךְ מַעֲלִין סלֶת הַנְּסָכִים. וְאַחַר הַסּלֶת מַקְטִיר הַחֲבִיתִין. וְאַחַר הַחֲבִיתִין מַעֲלִין אֶת הַיַּיִן לְנִסּוּךְ. וּבִשְׁעַת הַנִּסּוּךְ אוֹמְרִין הַלְוִיִּם הַשִּׁיר. וּמַכִּין הַמְשׁוֹרְרִין בְּמִינֵי נִגּוּן שֶׁבַּמִּקְדָּשׁ וְתוֹקְעִין תֵּשַׁע תְּקִיעוֹת עַל פִּרְקֵי הַשִּׁיר:","כְּשֶׁהָיוּ נוֹתְנִין הַיַּיִן לַמְנַסֵּךְ. הָיוּ שְׁנֵי כֹּהֲנִים עוֹמְדִין עַל שֻׁלְחַן הַחֲלָבִים וּשְׁתֵּי חֲצוֹצְרוֹת בְּיָדָן. וְהַסְּגָן עוֹמֵד עַל קֶרֶן הַמִּזְבֵּחַ וְהַסּוּדָרִין בְּיָדוֹ. וְתָקְעוּ וְהֵרִיעוּ וְתָקְעוּ. וּבָאוּ וְעָמְדוּ אֵצֶל זֶה הַמְמֻנֶּה עַל הַצִּלְצָל. אֶחָד מִימִינוֹ וְאֶחָד מִשְּׂמֹאלוֹ:","שָׁחָה הַמְנַסֵּךְ לְנַסֵּךְ. מֵנִיף הַסְּגָן בְּסוּדָרִין. הִקִּישׁ זֶה בַּצִּלְצָל וְתָקְעוּ אֵלּוּ בַּחֲצוֹצְרוֹת וְדִבְּרוּ הַלְוִיִּם בְּשִׁיר. הִגִּיעוּ לְפֶרֶק תָּקְעוּ וְהִשְׁתַּחֲווּ כָּל הָעָם שֶׁבָּעֲזָרָה. עַל כָּל פֶּרֶק תְּקִיעָה וְעַל כָּל תְּקִיעָה הִשְׁתַּחֲוָיָה. וְכָל הַתְּקִיעוֹת שֶׁעַל הַתָּמִיד תֵּשַׁע כְּמוֹ שֶׁבֵּאַרְנוּ:","אֵין אוֹמְרִין שִׁירָה אֶלָּא עַל עוֹלוֹת הַצִּבּוּר וְזִבְחֵי שַׁלְמֵיהֶם הָאֲמוּרִין בַּתּוֹרָה. אֲבָל עוֹלוֹת נְדָבָה שֶׁמַּקְרִיבִין מִמּוֹתַר תְּרוּמַת הַלִּשְׁכָּה אַף עַל פִּי שֶׁהֵן שֶׁל צִבּוּר אֵין אוֹמְרִין שִׁירָה עֲלֵיהֶן. וְכֵן נְסָכִים הַבָּאִין בִּפְנֵי עַצְמָן אֵין אוֹמְרִין עֲלֵיהֶן שִׁירָה:","הַשִּׁיר שֶׁהָיוּ הַלְוִיִּם אוֹמְרִין. בַּיּוֹם הָרִאשׁוֹן הָיוּ אוֹמְרִין (תהילים כד א) \"לַה' הָאָרֶץ וּמְלוֹאָהּ\". בַּשֵּׁנִי הָיוּ אוֹמְרִין (תהילים מח ב) \"גָּדוֹל ה' וּמְהֻלָּל מְאֹד בְּעִיר אֱלֹהֵינוּ הַר קָדְשׁוֹ\" וְגוֹ'. בַּשְּׁלִישִׁי הָיוּ אוֹמְרִין (תהילים פב א) \"אֱלֹהִים נִצָּב בַּעֲדַת אֵל בְּקֶרֶב אֱלֹהִים יִשְׁפֹּט\". בִּרְבִיעִי הָיוּ אוֹמְרִין (תהילים צד א) \"אֵל נְקָמוֹת ה' אֵל נְקָמוֹת הוֹפִיעַ\". בַּחֲמִישִׁי הָיוּ אוֹמְרִין (תהילים פא ב) \"הַרְנִינוּ לֵאלֹהִים עוּזֵּנוּ הָרִיעוּ לֵאלֹהֵי יַעֲקֹב\". בַּשִּׁשִּׁי הָיוּ אוֹמְרִין (תהילים צג א) \"ה' מָלָךְ גֵּאוּת לָבֵשׁ לָבֵשׁ ה' עֹז הִתְאַזָּר\" וְגוֹ'. בְּשַׁבָּת הָיוּ אוֹמְרִין (תהילים צב א) \"מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת\". בְּמוּסְפֵי שַׁבָּת אוֹמְרִים שִׁירַת (דברים לב א) \"הַאֲזִינוּ\" וְחוֹלְקִין אוֹתָהּ לְשִׁשָּׁה פְּרָקִים הַזִּי\"ו לָ\"ךְ כְּדֶרֶךְ שֶׁקּוֹרְאִין אוֹתָהּ שִׁשָּׁה בְּבֵית הַכְּנֶסֶת. וְאוֹמְרִין פֶּרֶק בְּכָל שַׁבָּת. גָּמְרוּ הַשִּׁירָה בְּשִׁשָּׁה שַׁבָּתוֹת חוֹזְרִין לָרֹאשׁ. בְּמִנְחָה שֶׁל שַׁבָּת אוֹמֵר (שמות טו א) \"אָז יָשִׁיר משֶׁה\" וּ(שמות טו יא) \"מִי כָמֹכָה\" וְגוֹ'. בְּמוּסָף שֶׁל רֹאשׁ הַשָּׁנָה הָיוּ אוֹמְרִין הַרְנִינוּ לֵאלֹהִים עוּזֵּנוּ. וְאִם חָל לִהְיוֹת בַּחֲמִישִׁי אוֹמֵר (תהילים פא ז) \"הֲסִירוֹתִי מִסֵּבֶל שִׁכְמוֹ\" וְגוֹ'. בְּמִנְחָה שֶׁל רֹאשׁ הַשָּׁנָה הָיוּ אוֹמְרִים (תהילים כט ח) \"קוֹל ה' יָחִיל מִדְבָּר\" וְגוֹ':","רֹאשׁ חֹדֶשׁ שֶׁחָל לִהְיוֹת בְּשַׁבַּת שִׁירָה שֶׁל רֹאשׁ חֹדֶשׁ דּוֹחֶה אֶת שִׁירָה שֶׁל שַׁבָּת כְּדֵי לְפַרְסֵם שֶׁהַיּוֹם רֹאשׁ חֹדֶשׁ:","בְּשַׁבָּת מַקְטִירִין אֶת שְׁנֵי בְּזִיכֵי לְבוֹנָה עִם הַמּוּסָפִין. קֹדֶם נִסּוּךְ הַיַּיִן שֶׁל מוּסָפִין. וְכַסֵּדֶר שֶׁעוֹשִׂין בְּכָל יוֹם בַּבֹּקֶר כָּךְ עוֹשִׂין בֵּין הָעַרְבַּיִם. חוּץ מֵהֲרָמַת הַדֶּשֶׁן מִמִּזְבֵּחַ הַחִיצוֹן וְסִדּוּר הַמַּעֲרָכוֹת וְהַפְּיָסוֹת. שֶׁאֵין עוֹשִׂין דְּבָרִים אֵלּוּ אֶלָּא בְּכָל יוֹם בַּשַּׁחַר לְבַד כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Damages to Property 4":["הַכּוֹנֵּס צֹאן לַדִּיר וְנָעַל בִּפְנֵיהֶן בְּדֶלֶת שֶׁיְּכוֹלָה לַעֲמֹד בְּרוּחַ מְצוּיָה וְיָצְאָה וְהִזִּיקָה פָּטוּר. וְאִם אֵינָהּ יְכוֹלָה לַעֲמֹד בְּרוּחַ מְצוּיָה אוֹ שֶׁהָיוּ כָּתְלֵי הַדִּיר רְעוּעִין הֲרֵי לֹא נָעַל בִּפְנֵיהֶן כָּרָאוּי וְאִם יָצָאת וְהִזִּיקָה חַיָּב. וַאֲפִלּוּ חָתְרָה וְיָצָאת וַאֲפִלּוּ נִפְרְצָה מְחִצָּה בַּלַּיְלָה אוֹ פְּרָצוּהָ לִסְטִים בַּעַל הַצֹּאן חַיָּב. הָיְתָה מְחִצָּה בְּרִיאָה וְנִפְרְצָה בַּלַּיְלָה אוֹ שֶׁפְּרָצוּהָ לִסְטִים וְיָצָאת וְהִזִּיקָה פָּטוּר. הוֹצִיאוּהָ לִסְטִים וְהִזִּיקָה לִסְטִים חַיָּבִים:","הַפּוֹרֵץ גָּדֵר לִפְנֵי בֶּהֱמַת חֲבֵרוֹ וְיָצָאת וְהִזִּיקָה. אִם הָיָה גָּדֵר חָזָק וּבָרִיא חַיָּב. וְאִם הָיָה כֹּתֶל רָעוּעַ פָּטוּר בְּדִינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. וְכֵן הַנּוֹתֵן סַם הַמָּוֶת לִפְנֵי בֶּהֱמַת חֲבֵרוֹ פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם:","הַמַּעֲמִיד בֶּהֱמַת חֲבֵרוֹ עַל גַּבֵּי קָמַת חֲבֵרוֹ הַמַּעֲמִיד חַיָּב לְשַׁלֵּם מַה שֶּׁהִזִּיק. וְכֵן אִם הִכִּישָׁהּ עַד שֶׁהָלְכָה לְקָמַת חֲבֵרוֹ וְהִזִּיקָה זֶה שֶׁהִכִּישָׁהּ חַיָּב:","הַמּוֹסֵר בְּהֶמְתּוֹ לְשׁוֹמֵר חִנָּם אוֹ לְנוֹשֵׂא שָׂכָר אוֹ לְשׂוֹכֵר אוֹ לְשׁוֹאֵל נִכְנְסוּ תַּחַת הַבְּעָלִים וְאִם הִזִּיקָה חַיָּב הַשּׁוֹמֵר. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁלֹּא שְׁמָרוּהָ כְּלָל. אֲבָל אִם שְׁמָרוּהָ שְׁמִירָה מְעֻלָּה כָּרָאוּי וְיָצָאת וְהִזִּיקָה הַשּׁוֹמְרִים פְּטוּרִין וְהַבְּעָלִים חַיָּבִים אֲפִלּוּ הֵמִיתָה אֶת הָאָדָם. שְׁמָרוּהָ שְׁמִירָה פְּחוּתָה אִם שׁוֹמֵר חִנָּם הוּא פָּטוּר וְאִם שׁוֹמֵר שָׂכָר אוֹ שׂוֹכֵר אוֹ שׁוֹאֵל הוּא חַיָּבִין:","הִנִּיחָהּ בַּחַמָּה אֲפִלּוּ חָתְרָה וְיָצָאת וְהִזִּיקָה חַיָּב זֶה שֶׁהִנִּיחָהּ שָׁם. שֶׁכֵּיוָן שֶׁהִנִּיחָהּ בַּחַמָּה הֲרֵי הִיא מִצְטַעֶרֶת וּבוֹרַחַת וְעוֹשָׂה כָּל שֶׁאֶפְשָׁר לָהּ לַעֲשׂוֹת:","מָסַר בְּהֶמְתּוֹ לְחֵרֵשׁ שׁוֹטֶה וְקָטָן אַף עַל פִּי שֶׁהָיָה הַשּׁוֹר קָשׁוּר הַבְּעָלִים חַיָּבִין. שֶׁדֶּרֶךְ הַשּׁוֹר וְכַיּוֹצֵא בּוֹ לְהַתִּיר הַקֶּשֶׁר וְלָצֵאת וּלְהַזִּיק. אֲפִלּוּ שְׁמָרוּהָ שְׁמִירָה מְעֻלָּה וְחָתְרָה וְיָצְאָה וְהִזִּיקָה הַבְּעָלִים חַיָּבִים:","מָסַר שׁוֹרוֹ לַחֲמִשָּׁה וּפָשַׁע בּוֹ אֶחָד מֵהֶן וְיָצָא וְהִזִּיק אִם אֵינוֹ מִשְׁתַּמֵּר אֶלָּא בַּחֲמִשְּׁתָּן זֶה שֶׁפָּשַׁע בִּשְׁמִירָתוֹ חַיָּב. וְאִם מִשְׁתַּמֵּר בִּשְׁאֵרָן אַף אֵלּוּ הַנִּשְׁאָרִין חַיָּבִין:","שְׁאָלוֹ בְּחֶזְקַת תָּם וְנִמְצָא מוּעָד. אִם יָדַע הַשּׁוֹאֵל שֶׁהוּא נַגְחָן הַבְּעָלִים מְשַׁלְּמִים חֲצִי נֵזֶק שֶׁכָּל מָקוֹם שֶׁהוּא הוֹלֵךְ הֲרֵי שֵׁם בְּעָלָיו עָלָיו. וְהַשּׁוֹאֵל מְשַׁלֵּם חֲצִי נֵזֶק. שֶׁאֲפִלּוּ הָיָה תָּם (כְּשֶׁעָלָה בְּדַעְתּוֹ) חֲצִי נֵזֶק הָיָה מְשַׁלֵּם שֶׁהֲרֵי יָדַע שֶׁהוּא נַגְחָן. וְאִם לֹא יָדַע שֶׁהוּא נַגְחָן אֵין הַשּׁוֹאֵל חַיָּב כְּלוּם וְהַבְּעָלִים מְשַׁלְּמִין נֵזֶק שָׁלֵם:","שְׁאָלוֹ כְּשֶׁהוּא תָּם וְהוּעַד בְּבֵית הַשּׁוֹאֵל וְהֶחֱזִירוֹ לִבְעָלָיו חָזַר לְתַמּוּתוֹ. הוֹאִיל וְנִשְׁתַּנֵּית רְשׁוּתוֹ בָּטְלָה הַהַעֲדָה וְהַבְּעָלִים מְשַׁלְּמִין חֲצִי נֵזֶק וְהַשּׁוֹאֵל פָּטוּר שֶׁהֲרֵי הֶחֱזִירוֹ:","שׁוֹמֵר שֶׁקִּבֵּל עָלָיו שְׁמִירַת גּוּף הַבְּהֵמָה בִּלְבַד אֲבָל לֹא שְׁמִירַת נְזָקֶיהָ וְהִזִּיקָה פָּטוּר מִלְּשַׁלֵּם וְהַבְּעָלִים חַיָּבִים. קִבֵּל שְׁמִירַת נְזָקֶיהָ וְהִזִּיקָה חַיָּב הַשּׁוֹמֵר. וְאִם הֻזְּקָה פָּטוּר וְהַבְּעָלִים עוֹשִׂים דִּין עִם הַמַּזִּיק:","מָסַר הַשּׁוֹמֵר לְשׁוֹמֵר אַחֵר הַשּׁוֹמֵר הָרִאשׁוֹן חַיָּב לְשַׁלֵּם לַנִּזָּק שֶׁהַשּׁוֹמֵר שֶׁמָּסַר לְשׁוֹמֵר חַיָּב. וַהֲרֵי הַנִּזָּק אוֹמֵר לוֹ לָמָּה לֹא שָׁמַרְתָּ אַתָּה בְּעַצְמְךָ וּמָסַרְתָּ לְאַחֵר שָׁלֵם לִי אַתָּה וְלֵךְ וַעֲשֵׂה דִּין עִם הַשּׁוֹמֵר שֶׁמָּסַרְתָּ לוֹ אַתָּה. מְסָרָהּ הַשּׁוֹמֵר לִבְנוֹ אוֹ לְבֶן בֵּיתוֹ אוֹ לִמְסַעֲדוֹ נִכְנְסוּ תַּחַת הַשּׁוֹמֵר וְחַיָּבִים:","כָּל שׁוֹמֵר שֶׁנִּתְחַיֵּב לְשַׁלֵּם וְאֵין לוֹ וְהָיָה הַמַּזִּיק תָּם שֶׁהוּא מְשַׁלֵּם חֲצִי נֵזֶק מִגּוּפוֹ הֲרֵי הַנִּזָּק מִשְׁתַּלֵּם מִן הַבְּהֵמָה שֶׁהִזִּיקָה וְיִשָּׁאֵר דְּמֵי מַה שֶּׁגָּבָה הַנִּזָּק חוֹב עַל הַשּׁוֹמֵר לְבַעַל הַבְּהֵמָה:","כָּל בְּהֵמָה שֶׁהִזִּיקָה פֵּרוֹת מְחֻבָּרִין מְשַׁעֲרִין מַה שֶּׁהִזִּיקָה בְּשִׁשִּׁים וּמְשַׁלֵּם זֶה שֶׁנִּתְחַיֵּב לְשַׁלֵּם בֵּין הַבְּעָלִים בֵּין הַשּׁוֹמְרִים. כֵּיצַד. הֲרֵי שֶׁאָכְלָה בֵּית סְאָה שָׁמִין שִׁשִּׁים בֵּית סְאָה בְּאוֹתָהּ הַשָּׂדֶה כַּמָּה הָיָה שָׁוֶה וְכַמָּה הוּא שָׁוֶה עַתָּה אַחַר שֶׁנִּפְסַד בּוֹ הַבֵּית סְאָה וּמְשַׁלֵּם הַשְּׁאָר. וְכֵן אִם אָכְלָה קַב אוֹ רֹבַע אֲפִלּוּ קֶלַח אֶחָד שָׁמִין אוֹתוֹ בְּשִׁשִּׁים:","אָכְלָה פֵּרוֹת גְּמוּרִין שֶׁאֵין צְרִיכִים לַקַּרְקַע מְשַׁלֵּם דְּמֵי פֵּרוֹת גְּמוּרִין בִּשְׁוֵיהֶן אִם סְאָה דְּמֵי סְאָה וְאִם סָאתַיִם דְּמֵי סָאתַיִם. הֲרֵי שֶׁאָכְלָה פֵּרוֹת דֶּקֶל אֶחָד וְכֵן הַלּוֹקֵט פֵּרוֹת דֶּקֶל חֲבֵרוֹ וְאָכַל אִם הָיָה דֶּקֶל רוֹמִי וְכַיּוֹצֵא בּוֹ שֶׁאֵין הַתְּמָרִים שֶׁלּוֹ יָפוֹת מְשַׁעֲרִין אוֹתוֹ בְּשִׁשִּׁים עַל גַּב הַקַּרְקַע. וְאִם דֶּקֶל פַּרְסִי וְכַיּוֹצֵא בּוֹ הוּא שֶׁהַתְּמָרִים שֶׁלּוֹ יָפוֹת בְּיוֹתֵר מְשַׁעֲרִין הַדֶּקֶל בִּפְנֵי עַצְמוֹ כַּמָּה הָיָה שָׁוֶה וְכַמָּה הוּא שָׁוֶה עַתָּה:"],"Mishneh Torah, Defilement by Leprosy 15":["נִּגְעֵי בָּתִּים יֵשׁ בָּהֶן הֶסְגֵּר שְׁלֹשָׁה שָׁבוּעוֹת שֶׁהֵן תִּשְׁעָה עָשָׂר יוֹם שֶׁיּוֹם שְׁבִיעִי עוֹלֶה לְכָאן וּלְכָאן וְיוֹם שְׁלֹשָׁה עָשָׂר עוֹלֶה לְכָאן וּלְכָאן נִמְצֵאתָ אַתָּה לָמֵד שֶׁאִם צָרִיךְ לִשְׁלֹשָׁה שָׁבוּעוֹת רוֹאֵהוּ בַּשְּׁבִיעִי וּבְיוֹם שְׁלֹשָׁה עָשָׂר וּבְיוֹם תִּשְׁעָה עָשָׂר. וְהֶסְגֵּר בָּתִּים שְׁלֹשָׁה שָׁבוּעוֹת אֵינוֹ מְפֹרָשׁ בַּתּוֹרָה וְכֵן רֹב דִּינֵי נִגְעֵי בָּתִּים דִּבְרֵי קַבָּלָה הֵן:","וְכָל הַדִּינִין הַמְפֹרָשִׁין בָּהֶן בַּתּוֹרָה וּבְדִבְרֵי קַבָּלָה כָּךְ הֵם. כְּשֶׁיָּבוֹא הַכֹּהֵן וְיִרְאֶה הַנֶּגַע שׁוֹקֵעַ יְרַקְרַק אוֹ אֲדַמְדַּם כְּמוֹ שֶׁבֵּאַרְנוּ יַסְגִּיר שִׁבְעַת יָמִים וַאֲפִלּוּ מְצָאוֹ כֻּלּוֹ בַּתְּחִלָּה יְרַקְרַק אוֹ אֲדַמְדַּם יַסְגִּיר. וּבַשְּׁבִיעִי רוֹאֵהוּ אִם כֵּהָה הַנֶּגַע וְאֵין צָרִיךְ לוֹמַר אִם הָלַךְ קוֹלֵף מְקוֹם הַנֶּגַע בִּלְבַד וְהַבַּיִת טָהוֹר. מְצָאוֹ שֶׁעָמַד בְּעֵינָיו וְלֹא פָּשָׂה מַסְגִּיר שָׁבוּעַ שֵׁנִי וְרוֹאֵהוּ בְּיוֹם שְׁלֹשָׁה עָשָׂר אִם כֵּהָה הַנֶּגַע אוֹ הָלַךְ לוֹ קוֹלֵף מְקוֹם הַנֶּגַע וּמְטַהֵר אֶת הַבַּיִת בְּצִפֳּרִים. וְאִם מָצָא הַנֶּגַע שֶׁפָּשָׂה בְּסוֹף שָׁבוּעַ שֵׁנִי אוֹ שֶׁעָמַד בְּעֵינוֹ חוֹלֵץ אֶת הָאֲבָנִים שֶׁבָּהֶן הַנֶּגַע וּמַקְצֶה הֶעָפָר אֶל מִחוּץ לָעִיר וְטָח אֶת כָּל הַבַּיִת וּמַסְגִּירוֹ שָׁבוּעַ שְׁלִישִׁי. וּבְיוֹם תִּשְׁעָה עָשָׂר רוֹאֵהוּ אִם חָזַר בּוֹ נֶגַע כִּשְׁנֵי גְּרִיסִין הֲרֵי זֶה פִּשְׂיוֹן אַחֲרֵי הִטּוֹחַ וְנוֹתֵץ אֶת כָּל הַבַּיִת וְאִם לֹא חָזַר בּוֹ נֶגַע מְטַהֲרוֹ בְּצִפֳּרִים. וְכָל זְמַן שֶׁיַּחְזֹר בּוֹ הַנֶּגַע קֹדֶם שֶׁיְּטַהֲרוֹ בְּצִפֳּרִים הֲרֵי זֶה יִנָּתֵץ. וְאִם נִרְאָה בּוֹ נֶגַע אַחַר שֶׁטִּהֲרוֹ בְּצִפֳּרִים יֵרָאֶה בַּתְּחִלָּה. וְכֵן אִם פָּשָׂה הַנֶּגַע בְּסוֹף שָׁבוּעַ רִאשׁוֹן חוֹלֵץ אֶת הָאֲבָנִים שֶׁבָּהֶן הַנֶּגַע וְקוֹצֶה הֶעָפָר חוּץ לָעִיר וְטָח אֶת כָּל הַבַּיִת וּמַסְגִּירוֹ שָׁבוּעַ שֵׁנִי וְרוֹאֶה אִם מָצָא בּוֹ נֶגַע כִּשְׁנֵי גְּרִיסִין הֲרֵי זֶה פִּשְׂיוֹן אַחֲרֵי הִטּוֹחַ וְנוֹתֵץ אֶת כָּל הַבַּיִת וְאִם לֹא חָזַר בּוֹ נֶגַע מְטַהֲרוֹ בְּצִפֳּרִים. וְכָל זְמַן שֶׁיִּרְאֶה בּוֹ נֶגַע קֹדֶם טָהֳרָה בְּצִפֳּרִים יִנָּתֵץ. וְאִם נִרְאָה בּוֹ אַחַר שֶׁטִּהֲרוֹ בְּצִפֳּרִים יֵרָאֶה בַּתְּחִלָּה:","כְּשֶׁהוּא חוֹלֵץ אֶת הָאֲבָנִים שֶׁבָּהֶן הַנֶּגַע אֵינוֹ חוֹלֵץ פָּחוֹת מִשְּׁתֵי אֲבָנִים וְאֵינוֹ נוֹטֵל אֲבָנִים מִצַּד זֶה וּמְבִיאָן לְצַד זֶה שֶׁנֶּאֱמַר (ויקרא יד מב) \"וְלָקְחוּ אֲבָנִים אֲחֵרוֹת\". וְלֹא עָפָר מִצַּד זֶה וּמֵבִיא לְצַד זֶה שֶׁנֶּאֱמַר (ויקרא יד מב) \"וְעָפָר אַחֵר יִקַּח וְטָח אֶת הַבָּיִת\". וְאֵינוֹ טָח בְּסִיד אֶלָּא בְּעָפָר שֶׁנֶּאֱמַר וְעָפָר אַחֵר יִקַּח וְגוֹ'. אֵינוֹ מֵבִיא אֶבֶן אַחַת תַּחַת שְׁתַּיִם שֶׁחָלַץ וְלֹא שְׁתֵּי אֲבָנִים תַּחַת אֶבֶן אַחַת חֲלוּצָה אֶלָּא מֵבִיא שְׁתַּיִם תַּחַת שְׁתַּיִם. וְיֵשׁ לוֹ לְהָבִיא שְׁתַּיִם תַּחַת שָׁלֹשׁ:","הָיָה הַכֹּתֶל בֵּינוֹ לְבֵין חֲבֵרוֹ שְׁנֵיהֶן חוֹלְצִין וּשְׁנֵיהֶן קוֹצִים אֶת הֶעָפָר וּשְׁנֵיהֶם מְבִיאִין אֲבָנִים אֲחֵרוֹת. אֲבָל בַּעַל הַבַּיִת מֵבִיא לְבַדּוֹ אֶת הֶעָפָר שֶׁנֶּאֱמַר (ויקרא יד מב) \"וְעָפָר אַחֵר יִקַּח וְטָח\" אֵין חֲבֵרוֹ מְטַפֵּל עִמּוֹ בְּטִיחָה:","אֶבֶן שֶׁבַּזָּוִית בִּזְמַן שֶׁהוּא חוֹלֵץ חוֹלֵץ אֶת כֻּלָּהּ וּבִזְמַן שֶׁהוּא נוֹתֵץ נוֹתֵץ אֶת שֶׁלּוֹ וּמַנִּיחַ אֶת שֶׁל חֲבֵרוֹ. וְיֵשׁ בַּדָּבָר סָפֵק אִם תִּהְיֶה זוֹ שֶׁל חֲבֵרוֹ כְּמוֹ יָד לָאֶבֶן שֶׁלּוֹ:","בַּיִת שֶׁנִּרְאָה בּוֹ נֶגַע וְהָיְתָה עֲלִיָּה עַל גַּבָּיו נוֹתֵן אֶת הַקּוֹרוֹת לַעֲלִיָּה. נִרְאָה בַּעֲלִיָּה נוֹתֵן אֶת הַקּוֹרוֹת לַבַּיִת. לֹא הָיְתָה עֲלִיָּה עַל גַּבָּיו אֲבָנָיו וְעֵצָיו וַעֲפָרוֹ כֻּלָּן נִתָּצִין עִמּוֹ. וּמַצִּיל אֶת הַמַּלְבְּנִין וְאֶת סְרִיגֵי הַחַלּוֹנוֹת:","הַלּוֹקֵחַ אֲבָנִים מִבַּיִת מֻסְגָּר וּבְנָאָן בְּבַיִת טָהוֹר חָזַר הַנֶּגַע לַמֻּסְגָּר חוֹלֵץ אֶת הָאֲבָנִים שֶׁבַּטָּהוֹר. נִרְאָה נֶגַע עַל הָאֲבָנִים שֶׁבָּנָה הַמֻּסְגָּר יִנָּתֵץ וְהַבַּיִת הַשֵּׁנִי מַסְגִּירִין אוֹתוֹ בְּנֶגַע זֶה כְּדִין כָּל בַּיִת שֶׁנִּרְאָה בּוֹ נֶגַע בַּתְּחִלָּה:","כֵּיצַד מְטַהֲרִין אֶת הַבַּיִת הַמְנֻגָּע. אַחַר הַחֲלִיצָה וְהַטִּיחָה מֵבִיא מַיִם חַיִּים בִּכְלִי חֶרֶס וּשְׁתֵּי צִפֳּרִים וְעֵץ אֶרֶז וְאֵזוֹב וּשְׁנִי תּוֹלַעַת כְּטָהֳרַת אָדָם שֶׁבֵּאַרְנוּ לְכָל דָּבָר. אֶלָּא שֶׁבְּאָדָם מַזֶּה שֶׁבַע פְּעָמִים לְאַחַר יָדוֹ שֶׁל מְצֹרָע וּבְבַיִת מַזֶּה שֶׁבַע פְּעָמִים עַל הַמַּשְׁקוֹף שֶׁל בַּיִת מִבַּחוּץ. וּשְׁאָר כָּל מַעֲשֵׂיהֶן שָׁוִין:"],"Mishneh Torah, Defilement by a Corpse 11":["אֶרֶץ הָעַכּוּ\"ם בַּתְּחִלָּה גָּזְרוּ עַל גּוּשָׁהּ בִּלְבַד כְּבֵית הַפְּרָס ולֹא הָיוּ מְטַמְּאִים אֶלָּא הַמְהַלֵּךְ בָּהּ אוֹ נוֹגֵעַ אוֹ נוֹשֵׂא מֵעֲפָרָהּ. חָזְרוּ וְגָזְרוּ עַל אֲוִירָהּ שֶׁיְּטַמֵּא וְאַף עַל פִּי שֶׁלֹּא נָגַע וְלֹא נָשָׂא אֶלָּא כֵּיוָן שֶׁהִכְנִיס רֹאשׁוֹ וְרֻבּוֹ לַאֲוִיר אֶרֶץ הָעַכּוּ\"ם נִטְמָא. וְכֵן כְּלִי חֶרֶשׂ שֶׁהִכְנִיס אֲוִירוֹ לְאֶרֶץ הָעַכּוּ\"ם וּשְׁאָר כֵּלִים שֶׁהִכְנִיס רֻבָּם לַאֲוִיר אֶרֶץ הָעַכּוּ\"ם נִטְמְאוּ:","טֻמְאַת אֲוִיר אֶרֶץ הָעַכּוּ\"ם לֹא עָשׂוּ אוֹתָהּ כְּטֻמְאַת עֲפָרָהּ אֶלָּא קַלָּה הִיא מִמֶּנָּה. שֶׁעַל טֻמְאַת עֲפָרָהּ שׂוֹרְפִין תְּרוּמוֹת וְקָדָשִׁים. וְהַמִּתְטַמֵּא בְּגוּשָׁהּ טָמֵא טֻמְאַת שִׁבְעָה וְצָרִיךְ הַזָּיָה שְׁלִישִׁי וּשְׁבִיעִי. אֲבָל הַנִּטְמָא בַּאֲוִירָהּ אֵין צָרִיךְ הַזָּיָה שְׁלִישִׁי וּשְׁבִיעִי אֶלָּא טְבִילָה וְהַעֲרֵב שֶׁמֶשׁ. וְכֵן תְּרוּמָה וְקָדָשִׁים שֶׁנִּטְמְאוּ מֵחֲמַת אֲוִירָהּ תּוֹלִין לֹא אוֹכְלִין וְלֹא שׂוֹרְפִין:","עֲפַר אֶרֶץ הָעַכּוּ\"ם וַעֲפַר בֵּית הַפְּרָס מְטַמְּאִין בְּמַגָּע וּבְמַשָּׂא כְּמוֹ שֶׁבֵּאַרְנוּ. וְכַמָּה שִׁעוּרָן כְּחוֹתַם הַמַּרְצוּפִין וְהוּא כְּפִיקָה גְּדוֹלָה שֶׁל סַקָּאִין. עֲפַר בֵּית הַפְּרָס וַעֲפַר חוּצָה לָאָרֶץ שֶׁבָּא בְּיָרָק. אִם יֵשׁ בְּמָקוֹם אֶחָד כְּחוֹתַם הַמַּרְצוּפִין מְטַמֵּא וְאִם לָאו אֵינוֹ מִצְטָרֵף. שֶׁלֹּא גָּזְרוּ אֶלָּא עַל גּוּשׁ כִּבְרִיָּתוֹ. מַעֲשֶׂה שֶׁהָיוּ אִגְּרוֹת בָּאוֹת מִחוּצָה לָאָרֶץ לִבְנֵי כֹּהֲנִים גְּדוֹלִים וְהָיוּ בָּהֶן כִּסְאָה וּכְסָאתַיִם חוֹתָמוֹת וְלֹא חָשׁוּ לָהֶן מִשּׁוּם טֻמְאָה לְפִי שֶׁלֹּא הָיָה בְּחוֹתָם מֵהֶן כְּחוֹתַם הַמַּרְצוּפִין:","הַמֵּבִיא תַּנּוּרִים וּסְפָלִין וּכְלֵי חֶרֶשׂ מִחוּצָה לָאָרֶץ עַד שֶׁלֹּא הֻסְּקוּ טְמֵאִים מִשּׁוּם אֶרֶץ הָעַכּוּ\"ם. מִשֶּׁהֻסְּקוּ טְמֵאִים מִשּׁוּם כְּלֵי חֶרֶס שֶׁנִּטְמָא בְּאֶרֶץ הָעַכּוּ\"ם שֶׁאֵינוֹ מְטַמֵּא אָדָם וְכֵלִים כְּמוֹ שֶׁבֵּאַרְנוּ:","הַמְהַלֵּךְ בְּאֶרֶץ הָעַכּוּ\"ם בֶּהָרִים וּבַסְּלָעִים טָמֵא טֻמְאַת שִׁבְעָה. בַּיָּם וּבְמָקוֹם שֶׁהַיָּם עוֹלֶה בְּזַעְפּוֹ טָהוֹר מִשּׁוּם נוֹגֵעַ בָּאָרֶץ הָעַכּוּ\"ם וְטָמֵא מִשּׁוּם אֲוִירָה. הַנִּכְנָס לְאֶרֶץ הָעַכּוּ\"ם בְּשִׁדָּה תֵּבָה וּמִגְדָּל הַפּוֹרְחִין בָּאֲוִיר טָמֵא. שֶׁאֹהֶל זָרוּק אֵינוֹ קָרוּי אֹהֶל:","סוּרְיָא עֲפָרָהּ טָמֵא כְּחוּצָה לָאָרֶץ וַאֲוִירָהּ טָהוֹר. לֹא גָּזְרוּ עַל אֲוִירָה. לְפִיכָךְ אִם הָיְתָה סְמוּכָה לְאֶרֶץ יִשְׂרָאֵל שָׂפָה בְּשָׂפָה וְלֹא הָיָה מַפְסִיק בֵּינֵיהֶן לֹא אֶרֶץ הָעַכּוּ\"ם וְלֹא בֵּית הַקְּבָרוֹת וְלֹא בֵּית הַפְּרָס הֲרֵי זֶה יָכוֹל לְהִכָּנֵס לָהּ בְּטָהֳרָה בְּשִׁדָּה תֵּבָה וּמִגְדָּל וְהוּא שֶׁלֹּא יִגַּע בְּגוּשָׁהּ. וְכֵן אֶרֶץ הָעַכּוּ\"ם הַסְּמוּכָה לְאֶרֶץ יִשְׂרָאֵל וְאֵין בֵּינֵיהֶן מָקוֹם טָמֵא הֲרֵי זוֹ נִבְדֶּקֶת וּטְהוֹרָה:","מָקוֹם שֶׁשָּׁכְנוּ בּוֹ עַכּוּ\"ם בְּאֶרֶץ יִשְׂרָאֵל הֲרֵי זֶה מְטַמֵּא כְּאֶרֶץ הָעַכּוּ\"ם עַד שֶׁיִּבָּדֵק שֶׁמָּא קָבְרוּ בּוֹ נְפָלִים:","וּתְרוּמָה וְקָדָשִׁים שֶׁנִּטְמְאוּ מֵחֲמַת מְדוֹר הָעַכּוּ\"ם תּוֹלִין לֹא אוֹכְלִין וְלֹא שׂוֹרְפִין. וְכַמָּה יִשְׁהוּ בַּמָּקוֹם וְיִהְיֶה צָרִיךְ בְּדִיקָה. אַרְבָּעִים יוֹם כְּדֵי שֶׁתִּתְעַבֵּר אִשָּׁה וְתַפִּיל נֵפֶל שֶׁמְּטַמֵּא. אֲפִלּוּ אִישׁ שֶׁאֵין עִמּוֹ אִשָּׁה אִם שָׁהָה אַרְבָּעִים יוֹם מְדוֹרוֹ טָמֵא עַד שֶׁיִּבָּדֵק. גְּזֵרָה מִשּׁוּם מָדוֹר שֶׁתִּהְיֶה בּוֹ אִשָּׁה. אֲפִלּוּ עֶבֶד וְסָרִיס אוֹ אִשָּׁה אוֹ קָטָן בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד עוֹשֶׂה מְדוֹר הָעַכּוּ\"ם:","מְדוֹר עַכּוּ\"ם שֶׁהָיָה בּוֹ עֶבֶד (מִיִּשְׂרָאֵל) אוֹ אִשָּׁה אוֹ קָטָן בֶּן תֵּשַׁע מְשַׁמְּרִין אוֹתוֹ שֶׁלֹּא יִקְבְּרוּ שָׁם נֵפֶל אֵינוֹ צָרִיךְ בְּדִיקָה. וְאֶת מַה הֵן בּוֹדְקִין אֶת הַבִּיבִין הָעֲמֻקִּים וְאֶת הַמַּיִם הַסְּרוּחִין. וְכָל מָקוֹם שֶׁהַחֲזִיר וְהַחֻלְדָּה יְכוֹלִין לְהוֹלִיךְ מִשָּׁם הַנֵּפֶל אֵינוֹ צָרִיךְ בְּדִיקָה מִפְּנֵי שֶׁהֵן גּוֹרְרִין אוֹתָם מִשָּׁם. מְדוֹר הָעַכּוּ\"ם שֶׁחָרַב הֲרֵי הוּא בְּטֻמְאָתוֹ עַד שֶׁיִּבָּדֵק:","הַאִיצְטְוַונִיוֹת אֵין בָּהֶן מִשּׁוּם מְדוֹר עַכּוּ\"ם לְפִי שֶׁהִיא גְּלוּיָה וְאֵין בָּהּ מָקוֹם לְהַטְמִין הַנְּפָלִים. וַעֲשָׂרָה מְקוֹמוֹת אֵין בָּהֶם מִשּׁוּם מְדוֹר עַכּוּ\"ם לְפִי שֶׁאֵין דִּירָתָן קְבוּעָה לֹא גָּזְרוּ עֲלֵיהֶן טֻמְאָה. וְאֵלּוּ הֵן הָעֲשָׂרָה מְקוֹמוֹת אָהֳלֵי הָעַרְבִיִּים וְהַסֻּכּוֹת וְהַצְּרִיפִין וְהַבֻּרְגָּנִין וְהַתִּקְרָה שֶׁעַל גַּבֵּי הָעַמּוּדִים וְאֵין לָהּ דְּפָנוֹת וְהֵן בָּתֵּי הַקַּיִץ וּבֵית שַׁעַר וַאֲוִירָהּ שֶׁל חָצֵר וְהַמֶּרְחָץ וּמָקוֹם שֶׁעוֹשִׂין בּוֹ הַחִצִּים וּכְלֵי הַמִּלְחָמָה וּמְקוֹם הַלִּגְיוֹנוֹת:","הַחֲנוּת אֵין בָּהּ מִשּׁוּם מְדוֹר עַכּוּ\"ם אֶלָּא אִם כֵּן הָיָה דָּר בְּתוֹכָהּ. חָצֵר שֶׁהִיא טְמֵאָה מִשּׁוּם מְדוֹר הָעַכּוּ\"ם הֲרֵי בֵּית שַׁעַר שֶׁלָּהּ וַאֲוִירָהּ טְמֵאִין כָּמוֹהָ. וְאֵין מְדוֹר הָעַכּוּ\"ם וְלֹא בֵּית הַפְּרָס בְּחוּצָה לָאָרֶץ:","עֲיָרוֹת הַמֻּבְלָעוֹת בְּאֶרֶץ יִשְׂרָאֵל. כְּגוֹן סִיסִית וְחַבְרוֹתֶיהָ. [אַשְׁקְלוֹן וְחַבְרוֹתֶיהָ]. אַף עַל פִּי שֶׁפְּטוּרוֹת מִן הַמַּעַשְׂרוֹת וּמִן הַשְּׁבִיעִית אֵין בָּהֶן מִשּׁוּם אֶרֶץ הָעַכּוּ\"ם. וְחֶזְקַת דְּרָכִים שֶׁל עוֹלֵי בָּבֶל טְהוֹרוֹת אַף עַל פִּי שֶׁהֵן מֻבְלָעוֹת בְּאֶרֶץ הָעַכּוּ\"ם:"],"Mishneh Torah, Defilement by a Corpse 22":["שׁוּלֵי הַמַּחֲצִין וְשׁוּלֵי קַרְקָעוֹת וְהַכֵּלִים וְדָפְנוֹתֵיהֶן מֵאֲחוֹרֵיהֶן אֵין מַצִּילִין בְּצָמִיד פָּתִיל בְּאֹהֶל הַמֵּת. קִרְסְמָן וְשָׁפָן וַעֲשָׂאָן כֵּלִים מַצִּילִין בְּצָמִיד פָּתִיל. שֶׁאֵין מַצִּיל בְּצָמִיד פָּתִיל אֶלָּא כֵּלִים:","כְּלִי חֶרֶשׂ שֶׁנָּתַן בּוֹ טִיט עַד חֶצְיוֹ לֹא בִּטְּלוֹ. וְאִם הִשְׁקִיעַ בּוֹ אֶת הַכֵּלִים מַצִּיל:","כְּלִי חֶרֶשׂ מַצִּיל בְּצָמִיד פָּתִיל עַד שֶׁיִּנָּקֵב בְּמוֹצִיא רִמּוֹן. וּבְגָדוֹל עַד שֶׁפָּחַת רֻבּוֹ. כֵּיצַד. כְּלִי גָּדוֹל שֶׁנִּפְחַת [חֶצְיוֹ] וְהִקִּיפוֹ צָמִיד פָּתִיל וְסָתַם מְקוֹם הַפְּחָת בְּצָמִיד פָּתִיל הֲרֵי זֶה מַצִּיל אַף עַל פִּי שֶׁאֵינוֹ חָשׁוּב כְּלִי לְעִנְיַן טֻמְאָה. אֲבָל כְּלִי הַמֻּקָּף צָמִיד פָּתִיל שֶׁהָיָה נָקוּב אוֹ סָדוּק וְלֹא סָתַם הַנֶּקֶב נִטְמָא וְאֵינוֹ מַצִּיל. וְכַמָּה יִהְיֶה בַּנֶּקֶב. אִם הָיָה כְּלִי הֶעָשׂוּי לָאֳכָלִים שִׁעוּרוֹ בְּמוֹצִיא זֵיתִים. הָיָה עָשׂוּי לְמַשְׁקֶה שִׁעוּרוֹ בְּכוֹנֵס מַשְׁקֶה. הֶעָשׂוּי לְכָךְ וּלְכָךְ מְטִילִין אוֹתוֹ לְחֻמְרָא. וּמִשֶׁיִּנָּקֵב בְּכוֹנֵס מַשְׁקֶה אֵינוֹ מַצִּיל עַד שֶׁיִּסְתֹּם הַנֶּקֶב אוֹ עַד שֶׁיְּמַעֲטֶנּוּ:","תַּנּוּר שֶׁהָיְתָה סְרִידָא עַל פִּיו וּמֻקָּף צָמִיד פָּתִיל וְנָתוּן בְּאֹהֶל הַמֵּת וְנִסְדַּק הַתַּנּוּר. אִם הָיָה הַסֶּדֶק מְלֹא פִּי מַרְדֵּעַ שֶׁהוּא הֶקֵּף טֶפַח נִטְמָא הַתַּנּוּר וְאַף עַל פִּי שֶׁאֵין הַמַּרְדֵּעַ יָכוֹל לְהִכָּנֵס בַּסֶּדֶק אֶלָּא הֲרֵי הוּא כְּמוֹתוֹ בְּשָׁוֶה. פָּחוֹת מִכָּאן הַתַּנּוּר טָהוֹר. נִסְדְּקָה הַסְּרִידָא שֶׁעַל פִּיו כִּמְלֹא פִּי מַרְדֵּעַ נִכְנַס הֲרֵי זֶה טָמֵא. פָּחוֹת מִכָּאן נִצָּל בְּצָמִיד פָּתִיל. הָיָה הַסֶּדֶק עִגּוּל אֵין רוֹאִין אוֹתוֹ אָרֹךְ אֶלָּא שִׁעוּרוֹ כִּמְלֹא פִּי מַרְדֵּעַ נִכְנָס:","תַּנּוּר הַמֻּקָּף צָמִיד פָּתִיל שֶׁנִּקַּב נֶקֶב בְּעֵינוֹ שֶׁל תַּנּוּר הַטּוּחָה אִם הָיָה הַנֶּקֶב מְלֹא כּוּשׁ נִכְנַס וְיוֹצֵא כְּשֶׁהוּא דּוֹלֵק הֲרֵי זֶה נִטְמָא. וְאִם הָיָה הַנֶּקֶב פָּחוֹת מִזֶּה נִצָּל:","נִקַּב הַתַּנּוּר מִצִּדּוֹ שִׁעוּרוֹ מְלֹא כּוּשׁ נִכְנָס וְיוֹצֵא שֶׁלֹּא דּוֹלֵק. וְכֵן מְגוּפַת הֶחָבִית שֶׁנִּקְּבָה שִׁעוּרָהּ כְּדֵי שֶׁתִּכָּנֵס מִצָּה שְׁנִיָּה שֶׁל שִׁיפוֹן בַּנֶּקֶב. וַחֲצָבִים גְּדוֹלִים שֶׁנִּקְּבוּ שִׁעוּרָן כְּדֵי שֶׁתִּכָּנֵס מִצָּה שְׁנִיָּה שֶׁל קָנֶה. פָּחוֹת מִכָּאן טְהוֹרִין. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁנַּעֲשׂוּ לְיַיִן. אֲבָל אִם נַעֲשׂוּ לִשְׁאָר הַמַּשְׁקִין אֲפִלּוּ נִקְּבוּ בְּכָל שֶׁהֵן נִטְמְאוּ. וְאֵין הַצָּמִיד פָּתִיל מוֹעִיל לָהֶם עַד שֶׁיִּסְתֹּם הַנֶּקֶב. וְאַף בִּזְמַן שֶׁנַּעֲשׂוּ לְיַיִן לֹא אָמְרוּ אֶלָּא שֶׁנִּקְּבוּ שֶׁלֹּא בִּידֵי אָדָם. אֲבָל אִם נַעֲשׂוּ בִּידֵי אָדָם אֲפִלּוּ כָּל שֶׁהֵן טְמֵאִים. וְאֵינָן נִצָּלִין עַד שֶׁיִּסָּתֵם הַנֶּקֶב:","חָבִית שֶׁהִיא מְלֵאָה מַשְׁקִין טְהוֹרִין וּמְנִיקַת שֶׁל חֶרֶס בְּתוֹכָהּ וְהֶחָבִית מֻקֶּפֶת צָמִיד פָּתִיל וּנְתוּנָה בְּאֹהֶל הַמֵּת. הֶחָבִית וְהַמַּשְׁקִין טְהוֹרִין וְהַמְּנִיקַת טְמֵאָה. מִפְּנֵי שֶׁקְּצָתָהּ הָאַחַת בְּתוֹךְ הֶחָבִית הַמֻּקֶּפֶת וְהַקָּצֶה הַשֵּׁנִי פָּתוּחַ לְאֹהֶל הַמֵּת וְאֵינוֹ סָתוּם. אַף עַל פִּי שֶׁהִיא עֲקֻמָּה אֵין הֶעָקֹם כְּסָתוּם:","חָבִית הַמֻּקֶּפֶת צָמִיד פָּתִיל שֶׁנִּקְּבָה מִצִּדָּהּ וְסָתְמוּ שְׁמָרִים אֶת הַנֶּקֶב הִצִּיל. אָגַף חֲצִי הַנֶּקֶב וְסָתַם חֶצְיוֹ הֲרֵי זֶה סָפֵק אִם הִצִּיל אִם לֹא הִצִּיל. סָתַם אֶת הַנֶּקֶב בִּזְמוֹרָה עַד שֶׁיְּמָרֵחַ מִן הַצְּדָדִין. סְתָמוֹ בִּשְׁנֵי קֵסָמִים עַד שֶׁיְּמָרֵחַ מִן הַצְּדָדִין וּבֵין זְמוֹרָה לַחֲבֵרְתָהּ. וְכֵן נֶסֶר שֶׁנָּתוּן עַל פִּי הַתַּנּוּר וּמֵרֵחַ מִן הַצְּדָדִין [הִצִּיל. הָיוּ שְׁתֵּי נְסָרִים עַד שֶׁיְּמָרֵחַ מִן הַצְּדָדִין וּבֵין] נֶסֶר לַחֲבֵרוֹ. חִבֵּר אֶת שְׁנֵי הַנְּסָרִים בְּמַסְמְרִים שֶׁל עֵץ וְכַיּוֹצֵא בָּהֶן אוֹ שֶׁלִּפֵּף עֲלֵיהֶן שׁוּגְמִין אֵין צָרִיךְ לְמָרֵחַ מִן הָאֶמְצַע. בַּמֶּה מַקִּיפִין. בְּסִיד. וּבְחַרְסִית. וּבִגְפַסִין. בְּזֶפֶת. וּבְשַׁעֲוָה. בְּטִיט. וּבְצוֹאָה. וּבְחֵמָר. וּבְכָל דָּבָר הַמִּתְמָרֵחַ. וְאֵין מַקִּיפִין לֹא בְּבַעַץ וְלֹא בְּעוֹפֶרֶת מִפְּנֵי שֶׁהוּא פָּתִיל וְאֵינוֹ צָמִיד. וּמַקִּיפִין בִּדְבֵלָה שְׁמֵנָה שֶׁלֹּא הֻכְשְׁרָה וּבְבָצֵק שֶׁנִּלּוֹשָׁה בְּמֵי פֵּרוֹת כְּדֵי שֶׁלֹּא יִטָּמֵא. שֶׁדָּבָר טָמֵא אֵינוֹ חוֹצֵץ:","מְגוּפַת הֶחָבִית שֶׁנִּתְחַלְחֲלָה אַף עַל פִּי שֶׁאֵינָהּ נִשְׁמֶטֶת אֵינָהּ מַצֶּלֶת שֶׁהֲרֵי נִתְרָעֵעַ הַצָּמִיד. הַכַּדּוּר וְהַפְּקַעַת שֶׁל גֶּמִי שֶׁנָּתַן עַל פִּי הֶחָבִית וּמֵרֵחַ מִן הַצְּדָדִין לֹא הִצִּיל עַד שֶׁיְּמָרֵחַ עַל כָּל הַכַּדּוּר וְעַל כָּל הַפְּקַעַת מִמַּטָּה לְמַעְלָה. וְכֵן בְּמַטְלַת שֶׁל בֶּגֶד שֶׁקְּשָׁרָהּ עַל פִּי הַכְּלִי. הָיְתָה שֶׁל נְיָר אוֹ שֶׁל עוֹר וּקְשָׁרָהּ בִּמְשִׁיחָה. אִם מֵרֵחַ מִן הַצְּדָדִין הִצִּיל:","חֵמֶת שֶׁל עוֹר הַדָּג אוֹ הַנְּיָר שֶׁהִלְבִּישׁ בָּהֶן אֶת הֶחָבִית וּצְרָרָהּ מִלְּמַטָּה הֲרֵי זוֹ מַצֶּלֶת. וְאִם לֹא צְרָרָהּ אַף עַל פִּי שֶׁמֵּרֵחַ מִן הַצְּדָדִין לֹא תַּצִּיל:","חָבִית זְפוּתָה שֶׁנִּתְקַלֵּף הַחֶרֶס מִלְּמַעְלָה וְהַזֶּפֶת שֶׁלָּהּ עוֹמֵד וְנָתַן הַכִּסּוּי עַל הַזֶּפֶת וּדְחָקוֹ עַד שֶׁיִּדְבַּק בַּזֶּפֶת. וְנִמְצָא הַזֶּפֶת עוֹמֵד בֵּין הַכִּסּוּי וּבֵין קַרְקַע הֶחָבִית הֲרֵי זֶה מַצִּיל. וְכֵן בִּכְלֵי הַמֻּרְיָס וְכַיּוֹצֵא בָּהֶן מִדְּבָרִים הַמִּתְמָרְחִין שֶׁהָיָה הַמִּתְמָרֵחַ בֵּין הַכִּסּוּי וּבֵין הַכְּלִי כְּמוֹ זֵר הוֹאִיל וְהַכּל דְּבוּקִין הֲרֵי זֶה מַצִּיל:"],"Mishneh Torah, Defilement of Foods 10":["כְּבָר בֵּאַרְנוּ שֶׁהַשִּׁבְעָה מַשְׁקִין בִּלְבַד הֵן שֶׁמִּתְטַמְּאִין אוֹ מַכְשִׁירִין וְהַשְּׁאָר קְרוּיִין מֵי פֵּרוֹת וְאֵינָם מִתְטַמְּאִין וְלֹא מַכְשִׁירִין. וְשִׁבְעָה מַשְׁקִין שֶׁמָּנִינוּ תּוֹלְדוֹתֵיהֶם כַּיּוֹצֵא בָּהֶם:","תּוֹלְדוֹת הַמַּיִם הֵם הַיּוֹצֵא מִן הָעַיִן וּמִן הָאֹזֶן וּמִן הַחֹטֶם וּמִן הַפֶּה וּמֵי רַגְלֵי בְּנֵי אָדָם בֵּין גְּדוֹלִים בֵּין קְטַנִּים כָּל אֵלּוּ הַיּוֹצְאִין מִן הָאָדָם מַשְׁקִין הֵן בֵּין שֶׁיָּצְאוּ לְדַעְתּוֹ שֶׁל אָדָם בֵּין שֶׁיָּצְאוּ שֶׁלֹּא לְדַעְתּוֹ. אֲבָל מֵי רַגְלֵי בְּהֵמָה וְהַמֶּלַח שֶׁנִּמְחָת הֲרֵי הֵן כְּמֵי פֵּרוֹת לֹא מִתְטַמְּאִין וְלֹא מַכְשִׁירִין:","הַדָּם הַמָּנוּי מִן הַמַּשְׁקִין הוּא הַדָּם הַשּׁוֹתֵת בִּשְׁעַת שְׁחִיטָה מִן הַבְּהֵמָה וְהַחַיָּה וְהָעוֹפוֹת הַטְּהוֹרִין. אֲבָל דַּם הַקִּלּוּחַ אֵינוֹ מַכְשִׁיר שֶׁעֲדַיִן חַיִּים הֵן וַהֲרֵי הוּא דּוֹמֶה לְדַם מַכָּה אוֹ לְדַם הַקָּזָה. הַשּׁוֹחֵט וְנִתַּז דָּם עַל הָאֳכָלִין וְנִתְקַנֵּחַ הַדָּם בֵּין סִימָן לְסִימָן הֲרֵי זֶה סָפֵק. לְפִיכָךְ תּוֹלִין עָלָיו לֹא אוֹכְלִין וְלֹא שׂוֹרְפִין. תּוֹלְדוֹת הַדָּם דַּם הַקָּזָה שֶׁל אָדָם שֶׁהוֹצִיאוֹ לִשְׁתִיָּה אֲבָל אִם הוֹצִיאוֹ לִרְפוּאָה טָהוֹר וְאֵינוֹ מַכְשִׁיר. וְכֵן דַּם שְׁחִיטָה בִּבְהֵמָה וּבְחַיָּה וּבְעוֹפוֹת הַטְּמֵאִין וְהַדָּם הַיּוֹצֵא עִם הַלֵּחָה וְעִם הָרְעִי וְדַם הַשְּׁחִין וְהָאֲבַעְבּוּעוֹת וְתַמְצִית הַבָּשָׂר כָּל אֵלּוּ אֵינָן מִתְטַמְּאִין וְלֹא מַכְשִׁירִין אֶלָּא הֲרֵי הֵן כִּשְׁאָר מֵי פֵּרוֹת. וְדַם הַשֶּׁרֶץ כִּבְשָׂרוֹ מְטַמֵּא וְאֵינוֹ מַכְשִׁיר. וְאֵין לָנוּ כַּיּוֹצֵא בּוֹ:","מֵי הֶחָלָב הֲרֵי הֵן כְּחָלָב. וַחֲלֵב הָאָדָם שֶׁאֵינוֹ צָרִיךְ לוֹ אֵינוֹ מַשְׁקֶה לֹא מַכְשִׁיר וְלֹא מִתְטַמֵּא. לְפִיכָךְ חֲלֵב הַזָּכָר אֵינוֹ מַשְׁקֶה. וְכֵן חֲלֵב בְּהֵמָה וְחַיָּה שֶׁיָּצָא שֶׁלֹּא לְרָצוֹן כְּגוֹן שֶׁזָּב מֵהַדָּד מֵאֵלָיו אוֹ שֶׁחֲלָבוֹ כְּמִתְעַסֵּק. אֲבָל חֲלֵב הָאִשָּׁה בֵּין שֶׁיָּצָא לְרָצוֹן בֵּין שֶׁיָּצָא שֶׁלֹּא לְרָצוֹן סְתָמוֹ מַשְׁקֶה וּמִתְטַמֵּא אוֹ מַכְשִׁיר מִפְּנֵי שֶׁהוּא רָאוּי לְתִינוֹק:","הַמַּשְׁקִין שֶׁיּוֹצְאִין מֵאוֹתָן הַטְּמֵאִין שֶׁאוֹתָן הַמַּשְׁקִין אֲבוֹת טֻמְאָה מְטַמְּאִים בְּלֹא הֶכְשֵׁר שֶׁהַטֻּמְאָה וְהַהֶכְשֵׁר בָּאִין כְּאַחַת וְאֵלּוּ הֵן. זוֹב הַזָּב וְשִׁכְבַת זַרְעוֹ וּמֵימֵי רַגְלָיו. וּרְבִיעִית דָּם מִן הַמֵּת. וְדַם הַנִּדָּה. וְכֵן דַּם מַגַּפְתּוֹ שֶׁל זָב וַחֲבֵרָיו וְחָלָב שֶׁל אִשָּׁה וְדִמְעַת עֵינַיִם עִם שְׁאָר תּוֹלְדוֹת הַמַּיִם הַיּוֹצְאִין מֵהֶן מְטַמְּאִין כְּמַשְׁקִין טְמֵאִין שֶׁמְּטַמְּאִין בְּלֹא כַּוָּנָה שֶׁמַּשְׁקִין טְמֵאִין מְטַמְּאִין לְרָצוֹן וְשֶׁלֹּא לְרָצוֹן. לְפִיכָךְ נִדָּה אוֹ זָבָה שֶׁנָּטַף חָלָב מִדָּדֶיהָ לַאֲוִיר הַתַּנּוּר נִטְמָא הַתַּנּוּר וְכָל מַה שֶּׁבְּתוֹכוֹ:","כְּבָר בֵּאַרְנוּ שֶׁהַמַּשְׁקִין הַיּוֹצְאִין מִטְּבוּל יוֹם אֵינָם טְמֵאִים. לְפִיכָךְ אִם נָפְלוּ אֲפִלּוּ עַל כִּכָּר שֶׁל תְּרוּמָה אֵינוֹ מֻכְשָׁר עַד שֶׁיִּפְּלוּ לְרָצוֹן כִּשְׁאָר הַמַּשְׁקִין הַטְּהוֹרִין שֶׁאֵינָן מַכְשִׁירִין אֶלָּא לְרָצוֹן:","הַזֵּעָה וְהַלֵּחָה הַסְּרוּחָה וְהָרְעִי וְהַמַּשְׁקִין הַיּוֹצְאִין מִבֶּן שְׁמוֹנָה חֳדָשִׁים וְהַשּׁוֹתֶה מֵי טְבֶרְיָה וְכַיּוֹצֵא בָּהֶן אַף עַל פִּי שֶׁיּוֹצְאִין נְקִיִּים כָּל אֵלּוּ אֵינָן חֲשׁוּבִין מַשְׁקֶה וְלֹא מִתְטַמְּאִין וְלֹא מַכְשִׁירִין:","הַשּׁוֹתֶה שְׁאָר מַשְׁקִין וְיָצְאוּ הֲרֵי הֵן מַשְׁקִין כְּשֶׁהָיוּ שֶׁאֵין שְׁאָר הַמַּשְׁקִין טְהוֹרִין בַּגּוּף. כֵּיצַד. שָׁתָה מַיִם טְמֵאִין וֶהֱקִיאָן הֲרֵי אֵלּוּ טְמֵאִין מִפְּנֵי שֶׁלֹּא טִהֲרוּ בִּיצִיאָתָן. שָׁתָה מַיִם טְמֵאִים וְטָבַל וְאַחַר כָּךְ הֱקִיאָן [אוֹ שֶׁנִּסְרְחוּ וְאַחַר כָּךְ הֱקִיאָן] אוֹ שֶׁיָּצְאוּ מִלְּמַטָּה אַף עַל פִּי שֶׁלֹּא טָבַל הֲרֵי הֵן טְהוֹרִין. שָׁתָה שְׁאָר מַשְׁקִין טְמֵאִין אוֹ שְׁאָר אֳכָלִין טְמֵאִין אַף עַל פִּי שֶׁטָּבַל וְאַחַר כָּךְ הֱקִיאָן טְמֵאִין לְפִי שֶׁאֵינָן טְהוֹרִין בַּגּוּף. נִסְרְחוּ אוֹ שֶׁיָּצְאוּ מִלְּמַטָּה הֲרֵי הֵן טְהוֹרִין:","כְּבָר בֵּאַרְנוּ שֶׁהַזֵּעָה אֵינָהּ מַשְׁקֶה אֲפִלּוּ שָׁתָה מַשְׁקִין טְמֵאִין וְהִזִּיעַ זֵעָתוֹ טְהוֹרָה. אֲבָל הַבָּא בְּמַיִם שְׁאוּבִין וְהִזִּיעַ זֵעָתוֹ טְמֵאָה. וְאִם נִסְתַּפֵּג מִן הַמַּיִם הַשְּׁאוּבִין וְאַחַר כָּךְ הִזִּיעַ זֵעָתוֹ טְהוֹרָה:","זֵעַת בָּתִּים שִׁיחִין וּמְעָרוֹת וּבוֹרוֹת אֵינָן מַשְׁקֶה וַאֲפִלּוּ הֵן טְמֵאִין זֵעָתָן טְהוֹרָה. אֲבָל זֵעַת הַמֶּרְחָץ בְּמַיִם אִם הָיְתָה הַמֶּרְחָץ טְמֵאָה זֵעָתָהּ טְמֵאָה. וְאִם הָיְתָה טְהוֹרָה וְהִכְנִיס בָּהּ פֵּרוֹת הֻכְשְׁרוּ. הִכְנִיסוּ לָהּ כֵּלִים הֲרֵי הַמַּיִם שֶׁעֲלֵיהֶן כִּתְלוּשִׁין בְּרָצוֹן וּמַכְשִׁירִין:","הַבְּרֵכָה שֶׁבַּבַּיִת וְהַבַּיִת מַזִּיעַ מֵחֲמָתָהּ אִם הָיְתָה הַבְּרֵכָה טְמֵאָה זֵעַת כָּל הַבַּיִת שֶׁמֵּחֲמָתָהּ טְמֵאָה:","שְׁתֵּי בְּרֵכוֹת בַּבַּיִת אַחַת טְמֵאָה וְאַחַת טְהוֹרָה. הַמַּזִּיעַ קָרוֹב לַטְּמֵאָה טָמֵא קָרוֹב לַטְּהוֹרָה טָהוֹר. מֶחֱצָה לְמֶחֱצָה טָמֵא:","הַמֹּהַל כַּשֶּׁמֶן. מַשְׁקִין הַמְנַטְּפִין מִסַּלֵּי זֵיתִים וַעֲנָבִים אֵינוֹ מַשְׁקֶה וְלֹא מִתְטַמְּאִין וְלֹא מַכְשִׁירִין עַד שֶׁיַּכְנִיסֵם בִּכְלִי:","הַשּׁוֹקֵל עֲנָבִים בְּכַף מֹאזְנַיִם הַיַּיִן שֶׁבַּכַּף אֵינוֹ מַשְׁקֶה עַד שֶׁיְּעָרֶנּוּ לְתוֹךְ הַכְּלִי וַהֲרֵי זֶה דּוֹמֶה לְסַלֵּי זֵיתִים וַעֲנָבִים שֶׁמְּנַטְּפִין:","הַדּוֹרֵס עֲנָבִים שֶׁל תְּרוּמָה בְּחָבִית אַף עַל פִּי שֶׁהַיַּיִן צָף עַל גַּבֵּי יָדָיו הֲרֵי הַכּל טָהוֹר:","מַשְׁקֵה בֵּית מִטְבָּחַיִם שֶׁבָּעֲזָרָה וְהוּא דַּם הַקָּדָשִׁים וְהַמַּיִם שֶׁמִּשְׁתַּמְּשִׁין בָּהֶן שָׁם טְהוֹרִין לְעוֹלָם וְאֵינָן מִתְטַמְּאִין וְלֹא מַכְשִׁירִין. וְדָבָר זֶה הֲלָכָה מִפִּי הַקַּבָּלָה. לְפִיכָךְ כָּל דְּמֵי הַזְּבָחִים אֵינוֹ מְקַבֵּל טֻמְאָה וְאֵינוֹ מַכְשִׁיר. וְהוֹאִיל וְדַם הַקָּדָשִׁים אֵינוֹ מַכְשִׁיר קָדָשִׁים שֶׁנִּשְׁחֲטוּ בָּעֲזָרָה לֹא הֻכְשְׁרוּ בְּדַם שְׁחִיטָה וְאֵין לִבְשַׂר הַקָּדָשִׁים הֶכְשֵׁר אֶלָּא בְּמַשְׁקִין שֶׁיִּפְּלוּ עַל הַבָּשָׂר חוּץ מִמַּשְׁקֵה בֵּית הַמִּטְבָּחַיִם:","פָּרַת קָדָשִׁים שֶׁהֶעֱבִירָהּ בַּנָּהָר וּשְׁחָטָהּ וַעֲדַיִן מַשְׁקֶה טוֹפֵחַ עָלֶיהָ הֲרֵי זוֹ מֻכְשֶׁרֶת. לְפִיכָךְ אִם נִמְצֵאת מַחַט טְמֵאָה בִּבְשָׂרָהּ הֲרֵי הַבָּשָׂר טָמֵא. וְכֵן אִם הָיְתָה הַפָּרָה חֲסוּמָה מִחוּץ לִירוּשָׁלַיִם אַף עַל פִּי שֶׁאֵין הַמַּחַט יְדוּעָה הֲרֵי הַבָּשָׂר טָמֵא מִפְּנֵי שֶׁנָּגַע בְּכֵלִים הַנִּמְצָאִין מִחוּץ לִירוּשָׁלַיִם. נִמְצֵאת הַמַּחַט בַּפֶּרֶשׁ הַבָּשָׂר טָהוֹר. וּבֵין כָּךְ וּבֵין כָּךְ הַיָּדַיִם טְהוֹרוֹת שֶׁאֵין טֻמְאַת יָדַיִם בַּמִּקְדָּשׁ כְּמוֹ שֶׁבֵּאַרְנוּ. בַּמֶּה דְּבָרִים אֲמוּרִים לִהְיוֹת הַבָּשָׂר טָמֵא בְּדִין תּוֹרָה. אֲבָל לְהִתְטַמֵּא מִדִּבְרֵיהֶן אֵין הֶקְדֵּשׁ צָרִיךְ הֶכְשֵׁר אֶלָּא חִבַּת הַקֹּדֶשׁ מַכְשֶׁרֶת הַבָּשָׂר. וְאִם נָגַע בָּהּ טֻמְאָה בֵּין קַלָּה בֵּין חֲמוּרָה נִפְסְלָה אַף עַל פִּי שֶׁלֹּא הֻכְשַׁר בְּמַשְׁקֶה כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Defilement of Foods 7":["הַנִּצוֹק אֵינוֹ חִבּוּר לֹא לְטֻמְאָה וְלֹא לְטָהֳרָה. כֵּיצַד. הָיָה מְעָרֶה מַשְׁקִין טְהוֹרִין לְתוֹךְ כְּלִי טָמֵא וַאֲפִלּוּ עַל גַּבֵּי הַשֶּׁרֶץ הֲרֵי הָעַמּוּד הַנִּצּוֹק טָהוֹר. וְאִם קָלַט מִן הַמַּשְׁקִין הַנִּגָּרִין מִן הָאֲוִיר הֲרֵי זֶה שֶׁקָּלַט טָהוֹר. וְאֵין צָרִיךְ לוֹמַר שֶׁהַמַּשְׁקִין שֶׁמְּעָרֶה מֵהֶן טְהוֹרִין:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁעֵרָה מִצּוֹנֵן לְצוֹנֵן אוֹ מֵחַם לְחַם אוֹ מֵחַם לְצוֹנֵן. אֲבָל הַמְעָרֶה מַשְׁקִין טְהוֹרִין צוֹנֵן לְתוֹךְ מַשְׁקִין טְמֵאִין חַמִּין הֲרֵי הַנִּצּוֹק חִבּוּר וְנִטְמְאוּ הַמַּשְׁקִין הַצּוֹנֵן כֻּלָּן שֶׁהוּא מְעָרֶה מֵהֶן וְנִטְמָא הַכְּלִי שֶׁמְּעָרֶה מִמֶּנּוּ מֵחֲמַת הַמַּשְׁקִין שֶׁבְּתוֹכוֹ שֶׁהֲרֵי נִטְמְאוּ. וּמִפְּנֵי מָה אָמְרוּ הַמְעָרֶה מַשְׁקִין צוֹנֵן לְחַמִּין חִבּוּר מִפְּנֵי שֶׁעֶשֶׁן הַחַמִּין עוֹלֶה כְּתִמְרוֹת עָשָׁן וּמִתְעָרֵב בַּנִּצּוֹק וּבַמַּיִם שֶׁבַּכְּלִי הָעֶלְיוֹן וּמְטַמֵּא הַכְּלִי שֶׁהֶעָשָׁן הָעוֹלֶה מִן הַחַמִּין מַשְׁקִין הוּא חָשׁוּב:","לְפִיכָךְ הָאִשָּׁה שֶׁהָיוּ יָדֶיהָ טְהוֹרוֹת וֶהֱגִיסָהּ בִּקְדֵרָה טְמֵאָה וְהִזִּיעוּ יָדֶיהָ מֵהֶבֶל הַקְּדֵרָה נִטְמְאוּ יָדֶיהָ כְּאִלּוּ נָגְעָה בַּמַּשְׁקֶה שֶׁבַּקְּדֵרָה. וְכֵן אִם הָיוּ יָדֶיהָ טְמֵאוֹת וֶהֱגִיסָהּ בִּקְדֵרָה וְהִזִּיעוּ יָדֶיהָ נִטְמָא כָּל מַה שֶּׁבַּקְּדֵרָה כְּאִלּוּ נָגְעָה בַּמַּשְׁקִין שֶׁבַּקְּדֵרָה:","נְחִיל דְּבַשׁ הַזִּיפִים וּדְבַשׁ הַצַּפַּחַת הַנִּצּוֹק שֶׁלָּהֶן חִבּוּר וַאֲפִלּוּ הָיָה מְעָרֶה מִצּוֹנֵן לְצוֹנֵן מִפְּנֵי שֶׁיֵּשׁ לָהֶן רִיר וַהֲרֵי הֵן נִמְשָׁכִין כְּדֶבֶק. לְפִיכָךְ כָּל הָאֳכָלִין אֵין הַנִּצּוֹק שֶׁלָּהֶן חִבּוּר וַאֲפִלּוּ הָיוּ עָבִים הַרְבֵּה כְּגוֹן הַגְּרִיסִין וְהַחֵלֶב הַמֻּתָּךְ וְכַיּוֹצֵא בָּהֶן. לְפִי שֶׁאֵין לָהֶן רִיר. וְכֵן שְׁאָר כָּל הַמַּשְׁקִין אֵין הַנִּצּוֹק שֶׁלָּהֶן חִבּוּר אֶלָּא אִם כֵּן עֵרָה מִצּוֹנֵן לְחַם כְּמוֹ שֶׁבֵּאַרְנוּ:","הַנִּצּוֹק אֵינוֹ חִבּוּר לְטָהֲרָה. כֵּיצַד. שֶׁאִם עֵרָה מַיִם טְמֵאִים מִכְּלִי אֶבֶן וְכַיּוֹצֵא בָּהֶן לְתוֹךְ הַמִּקְוֶה אֵין אוֹמְרִים מִשֶּׁהִגִּיעַ קְצָת הַנִּצּוֹק לַמִּקְוֶה טִהֲרוּ הַמַּיִם אֶלָּא הֲרֵי הֵן בְּטֻמְאָתָן עַד שֶׁיַּשִּׁיק הַמִּקְוֶה לְכֻלָּן מִצַּד אֶחָד כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵן הַקְּטַפְרֵס שֶׁיֵּשׁ עָלָיו מַשְׁקֶה טוֹפֵחַ אֵינוֹ מְחַבְּרָן לִשְׁאָר הַמַּשְׁקִין שֶׁבַּמִּדְרוֹן לֹא לְטֻמְאָה וְלֹא לְטָהֳרָה. אֲבָל הַמַּשְׁקִין שֶׁבַּאֶשְׁבּוֹרֶן כֻּלָּן חִבּוּר לְטֻמְאָה וּלְטָהֳרָה:","עֲרֵבָה שֶׁהִיא קְטַפְרֵס וְעָלֶיהָ מַשְׁקֶה טוֹפֵחַ וְשָׁלֹשׁ חֲתִיכוֹת אֳכָלִין טְמֵאִים בִּכְבֵיצָה מֻנָּחִין עָלֶיהָ זוֹ לְמַטָּה מִזּוֹ אֵינָן מִצְטָרְפוֹת. הָיוּ שְׁתַּיִם הֲרֵי אֵלּוּ מִצְטָרְפוֹת. וְאִם הָיָה תַּחְתֵּיהֶם מַשְׁקֶה עוֹמֵד אֲפִלּוּ כְּעֵין הַחַרְדָּל הֲרֵי זֶה מְצָרֵף אֶת כֻּלָּן:","כְּבָר בֵּאַרְנוּ שֶׁטְּבוּל יוֹם אֵינוֹ מְטַמֵּא חֻלִּין כְּלָל אֶלָּא פּוֹסֵל אָכְלֵי תְּרוּמָה וּמַשְׁקֵה תְּרוּמָה וְעוֹשֶׂה הַכּל שְׁלִישִׁי. וְכֵן אִם נָגַע בְּאָכְלֵי קֹדֶשׁ אוֹ מַשְׁקֵה קֹדֶשׁ פְּסָלָן וַעֲשָׂאָן רְבִיעִי:","יֵשׁ דְּבָרִים שֶׁאֵינָם חִבּוּר בִּטְבוּל יוֹם וְאַף עַל פִּי שֶׁהֵן חִבּוּר בְּכָל הַטֻּמְאוֹת. אֶלָּא אִם נָגַע בָּהֶן טְבוּל יוֹם לֹא פָּסַל אֶלָּא זֶה שֶׁנָּגַע בּוֹ. וְאִלּוּ הָיָה הַנּוֹגֵעַ בִּמְקוֹם טְבוּל יוֹם אָדָם אַחֵר הָיָה פּוֹסֵל הַכּל. אֲפִלּוּ הָיָה הַנּוֹגֵעַ אָדָם שֶׁאָכַל אֳכָלִין טְמֵאִין אוֹ שָׁתָה מַשְׁקִין טְמֵאִין שֶׁהִיא טֻמְאָה קַלָּה הֲרֵי זֶה פָּסַל הַכּל שֶׁלֹּא פְּסָלוֹ טְבוּל יוֹם. וְאֵין צָרִיךְ לוֹמַר שֶׁאִם הָיָה הַנּוֹגֵעַ אַב טֻמְאָה אוֹ רִאשׁוֹן שֶׁהוּא מְטַמֵּא הַכּל. וּמִפְּנֵי מָה הֵקֵלּוּ בִּטְבוּל יוֹם מִפְּנֵי שֶׁכְּבָר טָהַר וְאֵינוֹ מְחֻסָּר אֶלָּא הַעֲרֵב שֶׁמֶשׁ. וְעוֹד הֵקֵלוּ בִּטְבוּל יוֹם שֶׁיֵּשׁ אֳכָלִין שֶׁהֵן מְיֻחָדִין לְאָדָם וּמִתְטַמְּאִין בְּכָל הַטֻּמְאוֹת וְהֵן טְהוֹרוֹת בִּטְבוּל יוֹם. וְאֵלּוּ הֵן. הַשְּׂעוֹרָה וְהַכֻּסֶּמֶת בִּזְמַן שֶׁאֵינָן קְלוּפִין. אֲבָל בִּזְמַן שֶׁהֵן קְלוּפִין וְהַחִטָּה אַף עַל פִּי שֶׁאֵינָהּ קְלוּפָה. וְהַקֶּצַח וְהַשּׁוּמְשׁוּם. נִפְסָלִין בִּטְבוּל יוֹם וְאֵין צָרִיךְ לוֹמַר שֶׁהֵן מִתְטַמְּאִין בְּכָל הַטֻּמְאוֹת:","כָּל יַד הָאֳכָלִין שֶׁהֵן חִבּוּר בְּאַב הַטֻּמְאָה הֲרֵי הֵן חִבּוּר בִּטְבוּל יוֹם. וְכֵן כָּל הָאֹכֶל שֶׁנִּפְרָס וּמְעֹרֶה בְּמִקְצָת שֶׁהוּא חִבּוּר בְּאַב הַטֻּמְאָה כָּךְ הוּא חִבּוּר בִּטְבוּל יוֹם. וְכָל שֶׁאֵינוֹ חִבּוּר בִּטְבוּל יוֹם הֲרֵי הוּא חִבּוּר בְּיָדַיִם וְגַם זֶה חֹמֶר בְּטֻמְאַת יָדַיִם מִטְּבוּל יוֹם:"],"Mishneh Torah, Diverse Species 9":["הַמַּרְכִּיב זָכָר עַל נְקֵבָה שֶׁאֵינוֹ מִינוֹ בֵּין בִּבְהֵמָה בֵּין בְּחַיָּה וּבְעוֹף וַאֲפִלּוּ בְּמִינֵי חַיָּה שֶׁבַּיָּם הֲרֵי זֶה לוֹקֶה מִן הַתּוֹרָה בְּכָל מָקוֹם בֵּין בָּאָרֶץ בֵּין בְּחוּצָה לָאָרֶץ שֶׁנֶּאֱמַר (ויקרא יט יט) \"בְּהֶמְתְּךָ לֹא תַרְבִּיעַ כִּלְאַיִם\". וְאֶחָד בְּהֵמָה חַיָּה וְעוֹף שֶׁלּוֹ אוֹ שֶׁל חֲבֵרוֹ. וְאֵינוֹ לוֹקֶה עַד שֶׁיַּכְנִיס בְּיָדוֹ כְּמִכְחוֹל בִּשְׁפוֹפֶרֶת. אֲבָל אִם הֶעֱלָם זֶה עַל זֶה בִּלְבַד אוֹ שֶׁעוֹרְרָן בְּקוֹל מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","מֻתָּר לְהַכְנִיס שְׁנֵי מִינִין לְסַהַר אֶחָד. וְאִם רָאָה אוֹתָם רוֹבְעִים זֶה אֶת זֶה אֵינוֹ זָקוּק לְהַפְרִישָׁן. וְאָסוּר לְיִשְׂרָאֵל לִתֵּן בְּהֶמְתּוֹ לְעַכּוּ\"ם לְהַרְבִּיעָהּ לוֹ:","מִי שֶׁעָבַר וְהִרְכִּיב בְּהֶמְתּוֹ כִּלְאַיִם הֲרֵי הַנּוֹלָד מֵהֶם מֻתָּר בַּהֲנָאָה. וְאִם הָיָה מִין טְהוֹרָה עִם מִין טְהוֹרָה מֻתָּר בַּאֲכִילָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּמַאֲכָלוֹת אֲסוּרוֹת:","שְׁנֵי מִינֵי בְּהֵמָה אוֹ חַיָּה שֶׁדּוֹמִין זֶה לְזֶה אַף עַל פִּי שֶׁמִּתְעַבְּרִין זֶה מִזֶּה וְדוֹמִין זֶה לָזֶה הוֹאִיל וְהֵם שְׁנֵי מִינִין הֲרֵי הֵם כִּלְאַיִם וְאָסוּר לְהַרְכִּיבָן. כֵּיצַד. הַזְּאֵב עִם הַכֶּלֶב וְהַכֶּלֶב הַכּוּפְרִי עִם הַשּׁוּעָל וְהַצְּבָאִים עִם הָעִזִּים וְהַיְעֵלִים עִם הָרְחֵלִים וְהַסּוּס עִם הַפֶּרֶד וְהַפֶּרֶד עִם הַחֲמוֹר וְהַחֲמוֹר עִם הֶעָרוֹד אַף עַל פִּי שֶׁדּוֹמִין זֶה לָזֶה הֲרֵי הֵן כִּלְאַיִם זֶה בָּזֶה:","מִין שֶׁיֵּשׁ בּוֹ מִדְבָּרִי וְיִשּׁוּבִי כְּגוֹן שׁוֹר הַבָּר עִם הַשּׁוֹר וְהָרַמָּךְ עִם הַסּוּס מֻתָּר לְהַרְכִּיבָן זֶה עִם זֶה מִפְּנֵי שֶׁהֵן מִין אֶחָד. אֲבָל אַוָּז עִם אַוָּז בַּר כִּלְאַיִם זֶה בָּזֶה מִפְּנֵי שֶׁהָאַוָּז (בֵּיתִּיִי) בֵּיצָיו מִבִּפְנִים וְאַוָּז בַּר בֵּיצָיו מִבַּחוּץ מִכְלָל שֶׁהֵם שְׁנֵי מִינִין. וְהַכְּוִי כִּלְאַיִם עִם הַחַיָּה וְעִם הַבְּהֵמָה וְאֵין לוֹקִין עָלָיו מִפְּנֵי שֶׁהוּא סָפֵק:","הַיְלוּדִים מִן הַכִּלְאַיִם אִם הָיוּ אִמּוֹתֵיהֶן מִין אֶחָד מֻתָּר לְהַרְכִּיבָן זֶה עַל זֶה. וְאִם הָיוּ שְׁנֵי מִינִין אָסוּר לְהַרְכִּיבָן זֶה עַל זֶה וְאִם הִרְכִּיב לוֹקֶה. וְכֵן אִם הִרְכִּיב זֶה הַנּוֹלָד אֲפִלּוּ עַל מִין אִמּוֹ לוֹקֶה. כֵּיצַד. פֶּרֶד שֶׁאִמּוֹ חֲמוֹר מֻתָּר לְהַרְכִּיבוֹ עַל פְּרֵדָה שֶׁאִמָּהּ חֲמוֹר. וְאָסוּר לְהַרְכִּיבוֹ אֲפִלּוּ עַל הַחֲמוֹר. אֲבָל פֶּרֶד שֶׁאִמּוֹ סוּס אָסוּר לְהַרְכִּיבוֹ עַל פְּרֵדָה שֶׁאִמּוֹ חֲמוֹר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. לְפִיכָךְ הָרוֹצֶה לְהַרְכִּיב פֶּרֶד עַל פְּרֵדָה אוֹ לִמְשֹׁךְ בִּשְׁתֵּי פְּרֵדוֹת בּוֹדֵק בְּסִימָנֵי אָזְנַיִם וְזָנָב וְקוֹל אִם דּוֹמִין זֶה לָזֶה בְּיָדוּעַ שֶׁאִמָּן מִמִּין אֶחָד וּמֻתָּרִין:","כָּל הָעוֹשֶׂה מְלָאכָה בִּשְׁנֵי מִינֵי בְּהֵמָה אוֹ חַיָּה כְּאֶחָד וְהָיָה אֶחָד מֵהֶן מִין טְהוֹרָה וְהַשֵּׁנִי מִיִן טְמֵאָה הֲרֵי זֶה לוֹקֶה בְּכָל מָקוֹם שֶׁנֶּאֱמַר (דברים כב י) \"לֹא תַחֲרשׁ בְּשׁוֹר וּבַחֲמֹר יַחְדָּו\". אֶחָד הַחוֹרֵשׁ אוֹ הַזּוֹרֵעַ אוֹ הַמּוֹשֵׁךְ בָּהֶם עֲגָלָה אוֹ אֶבֶן כְּאֶחָד אוֹ הִנְהִיגָם כְּאֶחָד וַאֲפִלּוּ בְּקוֹל לוֹקֶה שֶׁנֶּאֱמַר יַחְדָּו מִכָּל מָקוֹם. אֲבָל הַמְזַוְּגָן פָּטוּר עַד שֶׁיִּמְשֹׁךְ אוֹ יַנְהִיג:","אֶחָד שׁוֹר וַחֲמוֹר וְאֶחָד כָּל שְׁנֵי מִינִין שֶׁאֶחָד טָמֵא וְאֶחָד טָהוֹר בֵּין בְּהֵמָה עִם בְּהֵמָה כַּחֲזִיר עִם הַכֶּבֶשׂ. אוֹ חַיָּה עִם חַיָּה כְּיַחְמוּר עִם הַפִּיל. אוֹ חַיָּה עִם בְּהֵמָה כְּכֶלֶב עִם הָעֵז אוֹ צְבִי עִם הַחֲזִיר וְכַיּוֹצֵא בָּהֶם עַל כָּל אֵלּוּ לוֹקֶה מִן הַתּוֹרָה שֶׁחַיָּה בִּכְלַל בְּהֵמָה הִיא כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת מַאֲכָלוֹת אֲסוּרוֹת. אֲבָל מִדִּבְרֵי סוֹפְרִים שְׁנֵי מִינִין שֶׁהֵן כִּלְאַיִם בְּהַרְבָּעָה אֲסוּרִים לַחֲרשׁ בָּהֶן כְּאֶחָד וּלְמָשְׁכָן וּלְהַנְהִיגָן. וְאִם עָשָׂה בָּהֶן מְלָאכָה כְּאֶחָד אוֹ מָשַׁךְ אוֹ הִנְהִיג מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וְאָסוּר לְהַנְהִיג בְּהֵמָה מִן הַיַּבָּשָׁה עִם חַיָּה שֶׁבַּיָּם כְּגוֹן עֵז עִם שִׁבּוּט וְאִם עָשָׂה פָּטוּר:","עֲגָלָה שֶׁהָיוּ מוֹשְׁכִין אוֹתָהּ כִּלְאַיִם הַיּוֹשֵׁב בַּעֲגָלָה לוֹקֶה. וְאַף עַל פִּי שֶׁלֹּא הִנְהִיג. שֶׁיְּשִׁיבָתוֹ גּוֹרֶמֶת לַבְּהֵמָה שֶׁתִּמְשֹׁךְ הָעֲגָלָה. וְכֵן אִם הָיָה יוֹשֵׁב אֶחָד בַּעֲגָלָה וְאֶחָד מַנְהִיג שְׁנֵיהֶן לוֹקִין. וַאֲפִלּוּ מֵאָה שֶׁהִנְהִיגוּ כִּלְאַיִם כְּאֶחָד כֻּלָּן לוֹקִין:","מֻתָּר לַעֲשׂוֹת מְלָאכָה בְּאָדָם וּבַבְּהֵמָה אוֹ חַיָּה כְּאֶחָד. כְּגוֹן אָדָם שֶׁחוֹרֵשׁ עִם הַשּׁוֹר אוֹ מוֹשֵׁךְ עֲגָלָה עִם חֲמוֹר וְכַיּוֹצֵא בָּזֶה שֶׁנֶּאֱמַר (דברים כב י) \"בְּשׁוֹר וּבַחֲמֹר יַחְדָּו\" לֹא בְּאָדָם וַחֲמוֹר אוֹ בְּאָדָם וְשׁוֹר:","בֶּהֱמַת פְּסוּלֵי הַמֻּקְדָּשִׁין אַף עַל פִּי שֶׁהִיא גּוּף אֶחָד עֲשָׂאָהּ הַכָּתוּב כִּשְׁנֵי גּוּפִין. מִפְּנֵי שֶׁהָיְתָה קֹדֶשׁ וְנַעֲשֵׂית כְּקֹדֶשׁ וּכְחל מְעֹרָבִין זֶה בְּזֶה וְנִמְצֵאת בְּהֵמָה זוֹ כִּבְהֵמָה טְמֵאָה עִם הַטְּהוֹרָה הַמְעֹרָבִין כְּאֶחָד. הֲרֵי הוּא אוֹמֵר (ויקרא כז יא) \"וְאִם כָּל בְּהֵמָה טְמֵאָה אֲשֶׁר לֹא יַקְרִיבוּ מִמֶּנָּה קָרְבָּן לַה'\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁאֵינוֹ מְדַבֵּר אֶלָּא בִּפְסוּלֵי הַמֻּקְדָּשִׁין. לְפִיכָךְ הַחוֹרֵשׁ בְּשׁוֹר פְּסוּלֵי הַמֻּקְדָּשִׁין אוֹ הַמַּרְבִּיעַ הֲרֵי זֶה לוֹקֶה מִשּׁוּם כִּלְאַיִם. וְאִסּוּר זֶה מִדִּבְרֵי קַבָּלָה:"],"Mishneh Torah, Divorce 8":["הַמְגָרֵשׁ עַל תְּנַאי אִם נִתְקַיֵּם הַתְּנַאי הֲרֵי זוֹ מְגֹרֶשֶׁת וְאִם לֹא נִתְקַיֵּם הַתְּנַאי אֵינָהּ מְגֹרֶשֶׁת. וּכְבָר בֵּאַרְנוּ בְּפֶרֶק שִׁשִּׁי מֵהִלְכוֹת אִישׁוּת מִשְׁפְּטֵי הַתְּנָאִין כֻּלָּם. וְשָׁם נִתְבָּאֵר שֶׁהַמְגָרֵשׁ עַל תְּנַאי כְּשֶׁיִּתְקַיֵּם הַתְּנַאי תִּהְיֶה מְגֹרֶשֶׁת בְּשָׁעָה שֶׁיִּתְקַיֵּם. לֹא בִּשְׁעַת נְתִינַת הַגֵּט לְיָדָהּ. לְפִיכָךְ יֵשׁ לַבַּעַל לְבַטֵּל הַגֵּט אוֹ לְהוֹסִיף עַל תְּנָאוֹ אוֹ לְהַתְנוֹת עַל תְּנַאי אַחֵר כָּל זְמַן שֶׁלֹּא נִתְקַיֵּם הַתְּנַאי הָרִאשׁוֹן אַף עַל פִּי שֶׁהִגִּיעַ גֵּט לְיָדָהּ. וְאִם מֵת הַבַּעַל אוֹ אָבַד הַגֵּט אוֹ נִשְׂרַף קֹדֶם שֶׁיִּתְקַיֵּם הַתְּנַאי אֵינָהּ מְגֹרֶשֶׁת. וּלְכַתְּחִלָּה לֹא תִּנָּשֵׂא עַד שֶׁיִּתְקַיֵּם הַתְּנַאי. וְאִם נִשֵּׂאת לֹא תֵּצֵא אֶלָּא אִם כֵּן לֹא נִשְׁאַר בְּיָדָהּ לְקַיְּמוֹ. שֶׁהֲרֵי בָּטַל הַתְּנַאי. וְשָׁם נִתְבָּאֵר שֶׁאִם אָמַר לָהּ הֲרֵי אַתְּ מְגֹרֶשֶׁת מֵעַכְשָׁו אוֹ מֵהַיּוֹם עַל תְּנַאי כָּךְ וְכָךְ. אוֹ שֶׁאָמַר לָהּ הֲרֵי אַתְּ מְגֹרֶשֶׁת עַל מְנָת כָּךְ וְכָךְ. כְּשֶׁיִּתְקַיֵּם הַתְּנַאי תִּהְיֶה מְגֹרֶשֶׁת מִשְּׁעַת נְתִינַת הַגֵּט לְיָדָהּ. לְפִיכָךְ אֵינוֹ יָכוֹל לְבַטֵּל הַגֵּט וְלֹא לְהוֹסִיף עַל תְּנָאוֹ מִשֶּׁהִגִּיעַ גֵּט לְיָדָהּ. וְאִם אָבַד אוֹ נִשְׂרַף אֲפִלּוּ מֵת הַבַּעַל קדֶם שֶׁיִּתְקַיֵּם הַתְּנַאי הֲרֵי זוֹ מְקַיֶּמֶת הַתְּנַאי אַחַר מוֹתוֹ וּכְבָר נִתְגָּרְשָׁה מִשְּׁעַת נְתִינַת הַגֵּט לְיָדָהּ וְיֵשׁ לָהּ לְהִנָּשֵׂא לְכַתְּחִלָּה אַף עַל פִּי שֶׁעֲדַיִן לֹא נִתְקַיֵּם הַתְּנַאי. וְאֵין חוֹשְׁשִׁין שֶׁמָּא לֹא יִתְקַיֵּם הוֹאִיל וְהָיָה הַתְּנַאי בִּמְעַכְשָׁו אוֹ בְּעַל מְנָת:","כָּל הַמְגָרֵשׁ עַל תְּנַאי בֵּין שֶׁאָמַר מֵעַכְשָׁו בֵּין שֶׁאָמַר אִם יִהְיֶה וְאִם לֹא יִהְיֶה הֲרֵי זֶה לֹא יִתְיַחֵד עִם אִשְׁתּוֹ כָּל זְמַן שֶׁלֹּא נִתְקַיֵּם הַתְּנַאי אֶלָּא בִּפְנֵי עֵד. וַאֲפִלּוּ עֶבֶד וַאֲפִלּוּ שִׁפְחָה חוּץ מִשִּׁפְחָתָהּ אוֹ בְּנָהּ קָטָן מִפְּנֵי שֶׁאֵינָהּ בּוֹשָׁה מִלְּשַׁמֵּשׁ בִּפְנֵיהֶם. וְהַדָּבָר יָדוּעַ שֶׁאִם נִתְיַחֵד עִמָּהּ בִּפְנֵי שְׁנֵי עֵדִים כְּאֶחָד אֲפִלּוּ נִתְקַיֵּם הַתְּנַאי אַחַר כָּךְ הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת. שֶׁמָּא בְּעָלָהּ וּבָטֵל הַגֵּט כְּמוֹ שֶׁיִּתְבָּאֵר בַּהֲלָכוֹת אֵלּוּ:","כֵּיצַד מְגָרֵשׁ אָדָם עַל תְּנַאי. לֹא שֶׁיֹּאמַר כִּתְבוּ גֵּט לְאִשְׁתִּי עַל תְּנַאי זֶה. אוֹ כִּתְבוּ וּתְנוּ לָהּ עַל תְּנַאי. וְאֵין צָרִיךְ לוֹמַר שֶׁלֹּא יִכְתֹּב בְּתוֹךְ הַגֵּט עַל תְּנַאי זֶה גֵּרֵשׁ פְּלוֹנִי אֶת פְּלוֹנִית. אֶלָּא כֵּיצַד עוֹשֶׂה. אוֹמֵר לַסּוֹפֵר לִכְתֹּב וְלָעֵדִים לַחְתֹּם וְכוֹתְבִין גֵּט כָּשֵׁר בְּלֹא שׁוּם תְּנַאי בָּעוֹלָם. וְאַחַר כָּךְ נוֹתֵן לָהּ הַגֵּט וְאוֹמֵר לָהּ הֲרֵי זֶה גִּטֵּךְ אוֹ הֲרֵי אַתְּ מְגֹרֶשֶׁת בָּזֶה עַל מְנָת כָּךְ וְכָךְ. אוֹ יֹאמַר לָהֶם אוֹ לַשָּׁלִיחַ תְּנוּ לָהּ גֵּט זֶה עַל מְנָת כָּךְ וְכָךְ:","כָּתַב הַתְּנַאי בַּגֵּט אַחַר שֶׁגָּמַר לִכְתֹּב תֹּרֶף הַגֵּט הֲרֵי זֶה גֵּט כָּשֵׁר. בֵּין שֶׁכְּתָבוֹ קֹדֶם חֲתִימַת הָעֵדִים בֵּין שֶׁכְּתָבוֹ לְאַחַר חֲתִימַת הָעֵדִים. אֲבָל אִם כְּתָבוֹ קֹדֶם תֹּרֶף הַגֵּט אֲפִלּוּ כָּתַב עַל מְנָת כָּךְ וְכָךְ הֲרֵי זֶה סְפֵק גֵּרוּשִׁין שֶׁהֲרֵי נִשְׁאַר לוֹ זְכוּת בְּגוּפוֹ שֶׁל גֵּט. וְכֵן אִם הִתְנָה עַל פֶּה קֹדֶם כְּתִיבַת הַתֹּרֶף הֲרֵי זֶה סְפֵק גֵּרוּשִׁין:","הַמְגָרֵשׁ אֶת אִשְׁתּוֹ וְהִתְנָה עָלֶיהָ בֵּין בִּכְתָב אַחַר הַתֹּרֶף בֵּין עַל פֶּה אַחַר הַתֹּרֶף וְאָמַר לָהּ הֲרֵי אַתְּ מֻתֶּרֶת לְכָל אָדָם חוּץ מֵאִישׁ פְּלוֹנִי אוֹ אֶלָּא לְאִישׁ פְּלוֹנִי וְנָתַן לָהּ הַגֵּט עַל תְּנַאי זֶה אִם הָיָה אוֹתוֹ הָאִישׁ עַכּוּ״‎ם אוֹ עֶבֶד אוֹ אָסוּר עָלֶיהָ מִשּׁוּם עֶרְוָה כְּגוֹן אָבִיהָ וְאָחִיהָ אוֹ אָבִיו אוֹ אָחִיו הֲרֵי זֶה גֵּט כָּשֵׁר. וְאִם הָיָה אוֹתוֹ הָאִישׁ שֶׁיֵּשׁ לוֹ בָּהּ קִדּוּשִׁין אַף עַל פִּי שֶׁהוּא מֵחַיָּבֵי לָאוִין וְאַף עַל פִּי שֶׁהוּא קָטָן אֵינוֹ גֵּט. שֶׁהֲרֵי שִׁיֵּר בַּגֵּט וְאֵין זֶה כְּרִיתוּת. הָיָה בַּעַל אֲחוֹתָהּ שֶׁאַף עַל פִּי שֶׁהוּא הַיּוֹם אָסוּר עָלֶיהָ מִשּׁוּם עֶרְוָה אִם תָּמוּת אֲחוֹתָהּ יִהְיֶה מֻתָּר לָהּ הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת:","אָמַר לָהּ הֲרֵי אַתְּ מֻתֶּרֶת לְכָל אָדָם חוּץ מִמִּי שֶׁיִּוָּלֵד שֶׁאֵינוֹ עַתָּה בָּעוֹלָם. אוֹ חוּץ מִזְּנוּתִיךְ כְּלוֹמַר תִּהְיֶה מֻתֶּרֶת לְהִנָּשֵׂא לְכָל אָדָם אֲבָל לִזְנוֹת הֲרֵי אַתְּ בְּאִסּוּר אֵשֶׁת אִישׁ. אוֹ הֲרֵי אַתְּ מֻתֶּרֶת לְכָל מִי שֶּׁיָּבוֹא עָלֶיךָ כְּדֶרֶךְ כָּל הָאָרֶץ אֲבָל שֶׁלֹּא כְּדַרְכֵּךְ הֲרֵי אַתְּ בְּאִסּוּרִיךְ. אוֹ הֲרֵי אַתְּ מֻתֶּרֶת לְכָל אָדָם חוּץ מִמְּקַדֵּשׁ בִּשְׁטָר. כְּלוֹמַר שֶׁהִיא מֻתֶּרֶת לְהִתְקַדֵּשׁ בְּכֶסֶף וּבְבִיאָה אֲבָל בִּשְׁטָר הֲרֵי אַתְּ בְּאִסּוּר אֵשֶׁת אִישׁ. אוֹ הֲרֵי אַתְּ מֻתֶּרֶת לְכָל אָדָם חוּץ מֵהֲפָרַת נְדָרַיִךְ. כְּלוֹמַר לֹא נִשְׁאַר לִי עָלַיִךְ שׁוּם אִישׁוּת חוּץ מֵהֲפָרַת נְדָרַיִךְ שֶׁאַתְּ אִשְׁתִּי לְעִנְיַן הֲפָרַת נְדָרִים. אוֹ לְעִנְיַן אֲכִילַת תְּרוּמָה. אוֹ לְעִנְיַן יְרֻשָּׁה שֶׁאִם מֵתָה יִירָשֶׁנָּה. בְּכָל אֶחָד מֵאֵלּוּ הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת:","אָמַר לָהּ הֲרֵי אַתְּ מֻתֶּרֶת לְכָל אָדָם חוּץ מֵרְאוּבֵן וְשִׁמְעוֹן וְחָזַר וְאָמַר לָהּ הֲרֵי אַתְּ מֻתֶּרֶת לִרְאוּבֵן וְשִׁמְעוֹן הֲרֵי זוֹ מְגֹרֶשֶׁת. שֶׁהֲרֵי בָּטֵל הַתְּנַאי שֶׁהָאֲנָשִׁים שֶׁהִתְנָה בָּהֶן הִתִּירָן לָהּ:","אָמַר לָהּ הֲרֵי אַתְּ מֻתֶּרֶת לִרְאוּבֵן הֲרֵי זוֹ אֵינָהּ מְגֹרֶשֶׁת שֶׁהֲרֵי לֹא בִּטֵּל תְּנָאוֹ שֶׁל שִׁמְעוֹן. אָמַר לָהּ הֲרֵי אַתְּ מֻתֶּרֶת לְשִׁמְעוֹן אוֹ הֲרֵי אַתְּ מֻתֶּרֶת אַף לְשִׁמְעוֹן הֲרֵי זֶה סְפֵק גֵּרוּשִׁין שֶׁמָּא לֹא הִתִּירָה אֶלָּא לְשִׁמְעוֹן וּרְאוּבֵן בְּאִסּוּרוֹ עוֹמֵד וְזֶה שֶׁאָמַר אַף לְשִׁמְעוֹן כְּלוֹמַר לְכָל אָדָם אַף לְשִׁמְעוֹן. אוֹ שֶׁמָּא הִתִּירָהּ לַכּל וְזֶה שֶׁאָמַר אַף לְשִׁמְעוֹן וְהוּא הַדִּין לִרְאוּבֵן שֶׁשִּׁמְעוֹן סָמוּךְ הָיָה לִרְאוּבֵן בִּתְנָאוֹ:","הִתְנָה עָלֶיהָ וְאָמַר הַיּוֹם אֵין אַתְּ אִשְׁתִּי וּלְמָחָר אַתְּ אִשְׁתִּי אֵינָהּ מְגֹרֶשֶׁת וְאַף עַל פִּי שֶׁכָּרַת בֵּינוֹ לְבֵינָהּ הַיּוֹם. לְפִיכָךְ כּוֹתְבִין בְּגִטִּין מִן הַיּוֹם הַזֶּה וּלְעוֹלָם:","הֲרֵי זֶה גִּטֵּךְ עַל מְנָת שֶׁלֹּא תִּשְׁתִּי יַיִן כָּל יְמֵי חַיָּיְכִי אֵינוֹ גֵּט שֶׁאֵין זֶה כְּרִיתוּת. כָּל יְמֵי חַיַּי אוֹ כָּל יְמֵי [חַיֵּי] פְּלוֹנִי הֲרֵי זֶה גֵּט שֶׁהֲרֵי כָּרַת בֵּינוֹ לְבֵינָהּ וְלֹא תִּשָּׁאֵר לוֹ עָלֶיהָ רְשׁוּת כְּשֶׁיָּמוּת אוֹתוֹ פְּלוֹנִי:","הֲרֵי זֶה גִּטֵּךְ עַל מְנָת שֶׁלֹּא תֵּלְכִי לְבֵית אָבִיךָ עַד שְׁלֹשִׁים יוֹם הֲרֵי זֶה גֵּט. שֶׁלֹּא תֵּלְכִי לְבֵית אָבִיךָ לְעוֹלָם אֵינוֹ גֵּט שֶׁהֲרֵי אֵין זֶה כְּרִיתוּת. לְפִיכָךְ הָאוֹמֵר הֲרֵי זֶה גִּטֵּךְ עַל מְנָת שֶׁלֹּא תֹּאכְלִי בָּשָׂר זֶה לְעוֹלָם. שֶׁלֹּא תִּשְׁתִּי יַיִן זֶה לְעוֹלָם אֵינוֹ גֵּט שֶׁאֵין זֶה כְּרִיתוּת. עַד שְׁלֹשִׁים יוֹם הֲרֵי זֶה גֵּט:","הֲרֵי זֶה גִּטֵּךְ עַל מְנָת שֶׁלֹּא תִּנָּשְׂאִי לִפְלוֹנִי אֵינוֹ גֵּט. הָא לְמָה זֶה דּוֹמֶה לְאוֹמֵר לָהּ הֲרֵי זֶה גִּטֵּךְ עַל מְנָת שֶׁלֹּא תִּשְׁתִּי יַיִן לְעוֹלָם אוֹ שֶׁלֹּא תֵּלְכִי לְבֵית אָבִיךְ לְעוֹלָם אוֹ כָּל יְמֵי חַיָּיְכִי. אֲבָל אִם אָמַר לָהּ עַל מְנָת שֶׁלֹּא תִּנָּשְׂאִי לִפְלוֹנִי עַד חֲמִשִּׁים שָׁנָה הֲרֵי זֶה גֵּט וְלֹא תִּנָּשֵׂא לוֹ כָּל זְמַן שֶׁהִתְנָה. וְאִם נִשֵּׂאת בָּטֵל הַגֵּט לְמַפְרֵעַ. זָנְתָה עִמּוֹ הַוָּלָד כָּשֵׁר וְהַגֵּט כָּשֵׁר שֶׁלֹּא הִתְנָה אֶלָּא עַל הַנִּשּׂוּאִין:","הֲרֵי זֶה גִּטֵּךְ עַל מְנָת שֶׁתִּנָּשְׂאִי לִפְלוֹנִי אִם נִשֵּׂאת לוֹ הֲרֵי זֶה גֵּט כִּשְׁאָר כָּל הַתְּנָאִים. אֲבָל אָמְרוּ חֲכָמִים לֹא תִּנָּשֵׂא לֹא לְאוֹתוֹ פְּלוֹנִי וְלֹא לְאַחֵר. לְאוֹתוֹ פְּלוֹנִי לֹא תִּנָּשֵׂא שֶׁמָּא יֹאמְרוּ נְשֵׁיהֶן נוֹתְנִין בְּמַתָּנָה זֶה לָזֶה. וּלְאַחֵר לֹא תִּנָּשֵׂא שֶׁאֵינוֹ גֵּט אֶלָּא בְּקִיּוּם הַתְּנַאי. עָבְרָה וְנִשֵּׂאת לְאוֹתוֹ פְּלוֹנִי לֹא תֵּצֵא. נִשֵּׂאת לְאַחֵר קֹדֶם שֶׁתִּנָּשֵׂא לְאוֹתוֹ פְּלוֹנִי בָּטֵל הַגֵּט וְתֵצֵא וְהַוָּלָד מַמְזֵר וּצְרִיכָה גֵּט מִשֵּׁנִי:","הֲרֵי זֶה גִּטֵּךְ וְהַנְּיָר שֶׁלִּי אֵינָהּ מְגֹרֶשֶׁת שֶׁאֵין זֶה כְּרִיתוּת. עַל מְנָת שֶׁתִּתְּנִי לִי אֶת הַנְּיָר הֲרֵי זֶה גֵּט וְתִתֵּן:","חָקַק הַגֵּט עַל טַס שֶׁל זָהָב וּנְתָנוֹ לָהּ וְאָמַר לָהּ הֲרֵי זֶה גִּטֵּךְ וּכְתֻבָּתֵךְ כָּשֵׁר וְנִתְקַבְּלָה כְּתֻבָּתָהּ אִם יֵשׁ בַּטַּס כְּדֵי כְּתֻבָּתָהּ וְאִם לָאו יַשְׁלִים כְּתֻבָּתָהּ:","כָּל הַמְגָרֵשׁ עַל תְּנַאי שֶׁמְּבֻטָּל הַגֵּט כְּגוֹן שֶׁהִתְנָה לָהּ שֶׁלֹּא תֹּאכַל בָּשָׂר וְלֹא תִּשְׁתֶּה יַיִן כָּל יְמֵי חַיֶּיהָ. אוֹ שֶׁתִּהְיֶה מֻתֶּרֶת לְכָל אָדָם חוּץ מִפְּלוֹנִי. אוֹ שֶׁהִתְנָה עָלֶיהָ שְׁאָר תְּנָאִים קֹדֶם כְּתִיבַת הַתֹּרֶף. אִם הָיָה תְּנָאוֹ כָּתוּב בַּגֵּט וְחָזַר וּמְחָקוֹ וּנְתָנוֹ לָהּ הֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת. וְאִם הָיָה הַתְּנַאי עַל פֶּה הֲרֵי זֶה נוֹטֵל הַגֵּט מִמֶּנָּה וְחוֹזֵר וְנוֹתְנוֹ לָהּ בְּלֹא תְּנַאי כְּלָל אוֹ בִּתְנַאי כָּשֵׁר:","כֵּיצַד. הֲרֵי שֶׁנָּתַן גֵּט לְאִשְׁתּוֹ וְאָמַר לָהּ הֲרֵי אַתְּ מְגֹרֶשֶׁת בָּזֶה וּמֻתֶּרֶת לְכָל אָדָם חוּץ מִפְּלוֹנִי. אִם נְטָלוֹ מִמֶּנָּה וְחָזַר וּנְתָנוֹ לָהּ וְאָמַר לָהּ הֲרֵי אַתְּ מֻתֶּרֶת לְכָל אָדָם אוֹ הֲרֵי זֶה גִּטֵּךְ הֲרֵי זוֹ מְגֹרֶשֶׁת. וְכֵן כָּל כַּיּוֹצֵא בּוֹ:","הַנּוֹתֵן גֵּט לְאִשְׁתּוֹ עַל תְּנַאי שֶׁתִּתֵּן לוֹ מָאתַיִם זוּז וְחָזַר וְהִתְנָה עָלֶיהָ תְּנַאי אַחֵר בִּפְנֵי עֵדִים שֶׁתְּשַׁמֵּשׁ אָבִיו שְׁתֵּי שָׁנִים. לֹא בִּטְּלוּ דְּבָרָיו הָאַחֲרוֹנִים אֶת הָרִאשׁוֹנִים אֶלָּא הֲרֵי זֶה כְּאוֹמֵר לָהּ עֲשִׂי אֶחָד מִשְּׁנֵי הַתְּנָאִים. רָצָת מְשַׁמֶּשֶׁת רָצָת נוֹתֶנֶת. וְאֵין אֶחָד מִן הָרִאשׁוֹנִים וְאֶחָד מִן הָאַחֲרוֹנִים מִצְטָרְפִין. אֲבָל אִם הִתְנָה עָלֶיהָ שֶׁתִּתֵּן לוֹ מָאתַיִם זוּז וְחָזַר וְהִתְנָה בִּפְנֵי שְׁנַיִם שֶׁתִּתֵּן לוֹ שְׁלֹשׁ מֵאוֹת זוּז. כְּבָר בִּטֵּל הַתְּנַאי שֶׁל מָאתַיִם וּצְרִיכָה לִתֵּן שְׁלֹשׁ מֵאוֹת זוּז. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הִתְנָה עָלֶיהָ שֶׁתַּעֲשֶׂה דָּבָר זֶה סְתָם הֲרֵי זֶה כִּמְפָרֵשׁ יוֹם אֶחָד הוֹאִיל וְלֹא פֵּרֵשׁ כַּמָּה זְמַן תַּעֲשֶׂה. כֵּיצַד. אָמַר לָהּ הֲרֵי זֶה גִּטֵּךְ עַל מְנָת שֶׁתַּעֲשִׂי עִמִּי מְלָאכָה. עַל מְנָת שֶׁתְּשַׁמְּשִׁי אֶת אַבָּא. עַל מְנָת שֶׁתֵּינִיקִי אֶת בְּנִי. אִם עָשְׂתָה עִמּוֹ מְלָאכָה אוֹ אִם שִׁמְּשָׁה אֶת אָבִיו יוֹם אֶחָד אוֹ שֶׁהֵינִיקָה בְּנוֹ יוֹם אֶחָד בְּתוֹךְ הַזְּמַן שֶׁהַבֵּן יוֹנֵק בּוֹ וְהוּא בְּתוֹךְ אַרְבָּעָה וְעֶשְׂרִים חֹדֶשׁ הֲרֵי זֶה גֵּט. מֵת הַבֵּן אוֹ מֵת אָבִיו קֹדֶם שֶׁתֵּינִיק אוֹ שֶׁתְּשַׁמֵּשׁ אֵינוֹ גֵּט:","אָמַר לָהּ עַל מְנָת שֶׁתֵּינִיקִי אֶת בְּנִי אוֹ תְּשַׁמְּשִׁי אֶת אָבִי שְׁתֵּי שָׁנִים. הֲרֵי זוֹ מַשְׁלֶמֶת הַזְּמַן שֶׁפֵּרֵשׁ. מֵת הַבֵּן אוֹ הָאָב בְּתוֹךְ הַזְּמַן אוֹ שֶׁאָמַר הָאָב אֵין רְצוֹנִי שֶׁתְּשַׁמְּשֵׁנִי אֵינוֹ גֵּט שֶׁהֲרֵי לֹא נִתְקַיֵּם הַתְּנַאי. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הֲרֵי זֶה גִּטֵּךְ עַל מְנָת שֶׁתִּתְּנִי לִי מָאתַיִם זוּז מִכָּאן וְעַד שְׁלֹשִׁים יוֹם. נָתְנָה בְּתוֹךְ שְׁלֹשִׁים יוֹם מִדַּעְתּוֹ הֲרֵי זוֹ מְגֹרֶשֶׁת. לְאַחַר שְׁלֹשִׁים אֵינָהּ מְגֹרֶשֶׁת. נְתָנָהּ לוֹ בְּעַל כָּרְחוֹ וְהוּא אֵינוֹ רוֹצֶה לְקַבֵּל הֲרֵי זֶה גֵּט פָּסוּל עַד שֶׁתִּתֵּן מִדַּעְתּוֹ. חָזַר וְאָמַר לָהּ בְּתוֹךְ הַשְּׁלֹשִׁים יוֹם הֲרֵי הֵן מְחוּלִין לָךְ אֵינָהּ מְגֹרֶשֶׁת. שֶׁהֲרֵי לֹא נַעֲשָׂה הַתְּנַאי. מֵת בְּתוֹךְ שְׁלֹשִׁים יוֹם הוֹאִיל וְשָׁלְמוּ הַשְּׁלֹשִׁים יוֹם וְלֹא נָתְנָה אֵינָהּ מְגֹרֶשֶׁת:","אָמַר לָהּ הֲרֵי זֶה גִּטֵּךְ עַל מְנָת שֶׁתִּתְּנִי לִי מָאתַיִם זוּז וְלֹא קָבַע זְמַן וּמֵת קֹדֶם שֶׁתִּתֵּן אֵינָהּ יְכוֹלָה לִתֵּן לְיוֹרְשָׁיו שֶׁלֹּא הִתְנָה עָלֶיהָ אֶלָּא שֶׁתִּתֵּן לוֹ. וְלֹא בָּטַל הַגֵּט שֶׁהֲרֵי לֹא קָבַע זְמַן. לְפִיכָךְ אַף עַל פִּי שֶׁאָבַד הַגֵּט אוֹ נִקְרַע קֹדֶם שֶׁיָּמוּת הֲרֵי זוֹ לֹא תִּנָּשֵׂא לְזָר עַד שֶׁתַּחֲלֹץ:","הֲרֵי זֶה גִּטֵּךְ עַל מְנָת שֶׁתִּתְּנִי לִי כְּלִי פְּלוֹנִי אוֹ בֶּגֶד פְּלוֹנִי וְאָבַד אוֹתוֹ כְּלִי אוֹ אוֹתוֹ בֶּגֶד אוֹ נִגְנַב אַף עַל פִּי שֶׁנָּתְנָה לוֹ אֶלֶף זוּז בְּדָמָיו אֵינוֹ גֵּט עַד שֶׁתִּתֵּן אוֹתוֹ כְּלִי אוֹ אוֹתוֹ בֶּגֶד עַצְמוֹ אוֹ עַד שֶׁיְּבַטֵּל הַתְּנַאי:","מִי שֶׁנִּתְגָּרְשָׁה עַל תְּנַאי וְקִדְּשָׁהּ אַחֵר קֹדֶם שֶׁיִּתְקַיֵּם הַתְּנַאי. אִם נִתְקַיֵּם הַתְּנַאי הֲרֵי זוֹ מְקֻדֶּשֶׁת. וְאִם לֹא נִתְקַיֵּם הַתְּנַאי וּבָטַל הַגֵּט אֵינָהּ צְרִיכָה גֵּט מִשֵּׁנִי שֶׁהֲרֵי אֵין קִדּוּשִׁין תּוֹפְסִין בָּהּ. אֲבָל אִם נִשֵּׂאת וְלֹא נִתְקַיֵּם הַתְּנַאי וּבָטַל הַגֵּט צְרִיכָה גֵּט מִשֵּׁנִי כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Fasts 3":["הֲרֵי שֶׁלֹּא יָרְדוּ לָהֶם גְּשָׁמִים כָּל עִקָּר מִתְּחִלַּת יְמוֹת הַגְּשָׁמִים. אִם הִגִּיעַ שִׁבְעָה עָשָׂר בְּמַרְחֶשְׁוָן וְלֹא יָרְדוּ גְּשָׁמִים מַתְחִילִין תַּלְמִידֵי חֲכָמִים בִּלְבַד לְהִתְעַנּוֹת שֵׁנִי וַחֲמִישִׁי וְשֵׁנִי. וְכָל הַתַּלְמִידִים רְאוּיִין לְכָךְ:","הִגִּיעַ רֹאשׁ חֹדֶשׁ כִּסְלֵו וְלֹא יָרְדוּ גְּשָׁמִים בֵּית דִּין גּוֹזְרִין שָׁלֹשׁ תַּעֲנִיּוֹת עַל הַצִּבּוּר שֵׁנִי וַחֲמִישִׁי וְשֵׁנִי. וּמֻתָּרִין בָּהֶן לֶאֱכל וְלִשְׁתּוֹת בַּלַּיְלָה. וְאַנְשֵׁי מִשְׁמָר אֵין מִתְעַנִּין עִמָּהֶן מִפְּנֵי שֶׁהֵן עֲסוּקִין בַּעֲבוֹדָה. וְכָל הָעָם נִכְנָסִים לְבָתֵּי כְּנֵסִיּוֹת וּמִתְפַּלְּלִין וְזוֹעֲקִין וּמִתְחַנְּנִין כְּדֶרֶךְ שֶׁעוֹשִׂין בְּכָל הַתַּעֲנִיּוֹת:","עָבְרוּ אֵלּוּ וְלֹא נַעֲנוּ בֵּית דִּין גּוֹזְרִין שָׁלֹשׁ תַּעֲנִיּוֹת אֲחֵרוֹת עַל הַצִּבּוּר שֵׁנִי וַחֲמִישִׁי וְשֵׁנִי. וּבְשָׁלֹשׁ אֵלּוּ אוֹכְלִין וְשׁוֹתִין מִבְּעוֹד יוֹם כְּמוֹ שֶׁעוֹשִׂין בְּצוֹם כִּפּוּר. וְאַנְשֵׁי מִשְׁמָר מִתְעַנִּין מִקְצָת הַיּוֹם וְלֹא מַשְׁלִימִין. וְאַנְשֵׁי בֵּית אָב וְהֵם הָעוֹסְקִין בַּעֲבוֹדָה בְּאוֹתוֹ הַיּוֹם לֹא יִהְיוּ מִתְעַנִּים כָּל עִקָּר. וְכָל תַּעֲנִית שֶׁאוֹכְלִין בָּהּ מִבְּעוֹד יוֹם אִם אָכַל וּפָסַק וְגָמַר שֶׁלֹּא לֶאֱכל אֵינוֹ חוֹזֵר וְאוֹכֵל אַף עַל פִּי שֶׁיֵּשׁ שְׁהוּת בַּיּוֹם:","בְּשָׁלֹשׁ תַּעֲנִיּוֹת אֵלּוּ כָּל הָעָם אֲסוּרִין בַּעֲשִׂיַּת מְלָאכָה בַּיּוֹם וּמֻתָּרִין בַּלַּיְלָה. וַאֲסוּרִין בִּרְחִיצַת כָּל הַגּוּף בְּחַמִּין אֲבָל פָּנָיו יָדָיו וְרַגְלָיו מֻתָּר. לְפִיכָךְ נוֹעֲלִין אֶת הַמֶּרְחֲצָאוֹת. וַאֲסוּרִין בְּסִיכָה. וְאִם לְהַעֲבִיר אֶת הַזֻּהֲמָה מֻתָּר. וַאֲסוּרִין בְּתַשְׁמִישׁ הַמִּטָּה. וּבִנְעִילַת הַסַּנְדָּל בָּעִיר אֲבָל בַּדֶּרֶךְ מֻתָּר לִנְעל. וּמִתְפַּלְּלִין בְּבָתֵּי כְּנֵסִיּוֹת וְזוֹעֲקִין וּמִתְחַנְּנִין כִּשְׁאָר תַּעֲנִיּוֹת:","עָבְרוּ אֵלּוּ וְלֹא נַעֲנוּ בֵּית דִּין גּוֹזְרִין שֶׁבַע תַּעֲנִיּוֹת אֲחֵרוֹת עַל הַצִּבּוּר שֵׁנִי וַחֲמִישִׁי וְשֵׁנִי וַחֲמִישִׁי וְשֵׁנִי וַחֲמִישִׁי וְשֵׁנִי. וּבְאֵלּוּ הַשֶּׁבַע בִּלְבַד עֵבָּרוֹת וּמֵינִיקוֹת מִתְעַנּוֹת אֲבָל בִּשְׁאָר הַתַּעֲנִיּוֹת אֵין עֵבָּרוֹת וּמֵינִיקוֹת מִתְעַנּוֹת. וְאַף עַל פִּי שֶׁאֵינָן מִתְעַנּוֹת אֵין מְעַנְּגוֹת עַצְמָן בְּתַפְנוּקִים אֶלָּא אוֹכְלוֹת וְשׁוֹתוֹת כְּדֵי קִיּוּם הַוָּלָד:","וּבְשֶׁבַע תַּעֲנִיּוֹת אֵלּוּ אַנְשֵׁי מִשְׁמָר מִתְעַנִּין וּמַשְׁלִימִין. וְאַנְשֵׁי בֵּית אָב מִתְעַנִּין מִקְצָת הַיּוֹם וְלֹא מַשְׁלִימִין. וְכָל דָּבָר שֶׁהוּא אָסוּר בְּשָׁלֹשׁ אֶמְצָעִיּוֹת אָסוּר בְּאֵלּוּ הַשֶּׁבַע הָאַחֲרוֹנוֹת:","וִיתֵרוֹת אֵלּוּ. שֶׁבָּהֶן בִּלְבַד מַתְרִיעִין וּמִתְפַּלְּלִין בִּרְחוֹב הָעִיר. וּמוֹרִידִין זָקֵן לְהוֹכִיחַ לָעָם כְּדֵי שֶׁיָּשׁוּבוּ מִדַּרְכָּם. וּמוֹסִיפִין שֵׁשׁ בְּרָכוֹת בִּתְפִלַּת שַׁחֲרִית וּבִתְפִלַּת מִנְחָה וְנִמְצְאוּ מִתְפַּלְּלִין כ\"ד בְּרָכוֹת. וְנוֹעֲלִין אֶת הַחֲנֻיּוֹת. וּבַשֵּׁנִי מַטִּין לְעֵת עֶרֶב וּפוֹתְחִין אֶת הַחֲנֻיּוֹת. אֲבָל בַּחֲמִישִׁי פּוֹתְחִין כָּל הַיּוֹם מִפְּנֵי כְּבוֹד הַשַּׁבָּת. וְאִם יֵשׁ לַחֲנוּת שְׁנֵי פְּתָחִים פּוֹתֵחַ אֶחָד וְנוֹעֵל אֶחָד וְאִם יֵשׁ לַחֲנוּת אִצְטַבָּה פּוֹתֵחַ כְּדַרְכּוֹ בַּחֲמִישִׁי וְאֵינוֹ חוֹשֵׁשׁ:","עָבְרוּ אֵלּוּ וְלֹא נַעֲנוּ. מְמַעֲטִין בְּמַשָּׂא וּמַתָּן וּבְבִנְיָן שֶׁל שִׂמְחָה כְּגוֹן צִיּוּר וְכִיּוּר. וּבִנְטִיעָה שֶׁל שִׂמְחָה כְּגוֹן מִינֵי הֲדַס וּמִינֵי אֲהָלִים. וּמְמַעֲטִין בְּאֵרוּסִין וְנִשּׂוּאִין אֶלָּא אִם כֵּן לֹא קִיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה. וְכָל מִי שֶׁקִּיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה אָסוּר לוֹ לְשַׁמֵּשׁ מִטָּתוֹ בִּשְׁנֵי רְעָבוֹן. וּמְמַעֲטִין בִּשְׁאֵלַת שָׁלוֹם בֵּין אָדָם לַחֲבֵרוֹ. וְתַּלְמִידֵי חֲכָמִים לֹא יִשְׁאֲלוּ שָׁלוֹם אֶלָּא כִּנְזוּפִין וּכִמְנֻדִּין לַמָּקוֹם. וְעַם הָאָרֶץ שֶׁנָּתַן לָהֶם שָׁלוֹם מַחְזִירִין לוֹ בְּשָׂפָה רָפָה וְכֹבֶד רֹאשׁ:","תַּלְמִידֵי חֲכָמִים חוֹזְרִין לְבַדָּם וּמִתְעַנִּים שֵׁנִי וַחֲמִישִׁי וְשֵׁנִי עַד שֶׁיֵּצֵא נִיסָן שֶׁל תְּקוּפָה אֲבָל לֹא הַצִּבּוּר. שֶׁאֵין גּוֹזְרִין עַל הַצִּבּוּר בִּשְׁבִיל גְּשָׁמִים שֶׁלֹּא יָרְדוּ יֶתֶר מִשְּׁלֹשׁ עֶשְׂרֵה תַּעֲנִיּוֹת אֵלּוּ. וּכְשֶׁמִּתְעַנִּין הַיְחִידִים עַד שֶׁיָּצָא נִיסָן מֻתָּרִין לֶאֱכל בַּלַּיְלָה וּמֻתָּרִין בַּעֲשִׂיַּת מְלָאכָה וּבִרְחִיצָה וּבְסִיכָה וְתַשְׁמִישׁ הַמִּטָּה וּנְעִילַת הַסַּנְדָּל כִּשְׁאָר כָּל הַתַּעֲנִיּוֹת. וּמַפְסִיקִין לְרָאשֵׁי חֳדָשִׁים וּפוּרִים. יָצָא נִיסָן שֶׁל תְּקוּפָה וְהוּא כְּשֶׁהִגִּיעַ הַשֶּׁמֶשׁ לִתְחִלַּת מַזַּל שׁוֹר אֵין מִתְעַנִּים. שֶׁאֵין הַגְּשָׁמִים בַּזְּמַן הַזֶּה אֶלָּא סִימַן קְלָלָה הוֹאִיל וְלֹא יָרְדוּ כָּל עִקָּר מִתְּחִלַּת הַשָּׁנָה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּאֶרֶץ יִשְׂרָאֵל וְכָל הַדּוֹמֶה לָהּ. אֲבָל מְקוֹמוֹת שֶׁעוֹנַת הַגְּשָׁמִים שֶׁלָּהֶן קֹדֶם י\"ז בְּמַרְחֶשְׁוָן אוֹ אַחַר זְמַן זֶה כְּשֶׁיַּגִּיעַ זְמַנָּם וְלֹא יָרְדוּ גְּשָׁמִים יְחִידִים מִתְעַנִּים שֵׁנִי וַחֲמִישִׁי וְשֵׁנִי. וּמַפְסִיקִין בְּרָאשֵׁי חֳדָשִׁים וּבַחֲנֻכָּה וּבְפוּרִים. וְשׁוֹהִין אַחֲרֵי כֵן כְּמוֹ שִׁבְעָה יָמִים. אִם לֹא יָרְדוּ גְּשָׁמִים בֵּית דִּין גּוֹזְרִין עַל הַצִּבּוּר שְׁלֹשׁ עֶשְׂרֵה תַּעֲנִיּוֹת עַל הַסֵּדֶר שֶׁאָמַרְנוּ:","כָּל תַּעֲנִיּוֹת שֶׁגּוֹזְרִין הַצִּבּוּר בְּחוּצָה לָאָרֶץ אוֹכְלִים בָּהֶם בַּלַּיְלָה וְדִינֵיהֶם כְּדִין שְׁאָר הַתַּעֲנִיּוֹת. שֶׁאֵין גּוֹזְרִין עַל הַצִּבּוּר תַּעֲנִית כְּגוֹן צוֹם כִּפּוּר אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל בִּלְבַד וּבִגְלַל הַמָּטָר. וּבְאוֹתָן עֶשֶׂר תַּעֲנִיּוֹת שֶׁהֵן שָׁלֹשׁ אֶמְצָעִיּוֹת וְשֶׁבַע אַחֲרוֹנוֹת:"],"Mishneh Torah, First Fruits and other Gifts to Priests Outside the Sanctuary 4":["כָּל הַמֵּבִיא בִּכּוּרִים טָעוּן קָרְבָּן וְשִׁיר וּתְנוּפָה וְלִינָה. אֲבָל הַוִּדּוּי אֵינוֹ שָׁוֶה בַּכּל. לְפִי שֶׁיֵּשׁ שֶׁחַיָּבִין לְהָבִיא בִּכּוּרִים וְאֵינָן קוֹרִין עֲלֵיהֶם:","וְאֵלּוּ מְבִיאִין וְלֹא קוֹרִין. הָאִשָּׁה וְהַטֻּמְטוּם וְהָאַנְדְּרוֹגִינוּס לְפִי שֶׁהֵן סְפֵק אִשָּׁה וְאֵינָן יְכוֹלִין לוֹמַר אֲשֶׁר נָתַתָּ לִּי ה'. וְכֵן הָאַפּוֹטְרוֹפִּין וְהָעֶבֶד וְהַשָּׁלִיחַ לְפִי שֶׁאֵינָן יְכוֹלִין לוֹמַר (דברים כו י) \"אֲשֶׁר נָתַתָּ לִּי ה'\":","הַגֵּר מֵבִיא וְקוֹרֵא שֶׁנֶּאֱמַר לְאַבְרָהָם (בראשית יז ה) \"אַב הֲמוֹן גּוֹיִם נְתַתִּיךָ\" הֲרֵי הוּא אַב כָּל הָעוֹלָם כֻּלּוֹ שֶׁנִּכְנָסִין תַּחַת כַּנְפֵי שְׁכִינָה. וּלְאַבְרָהָם הָיְתָה הַשְּׁבוּעָה תְּחִלָּה שֶׁיִּירְשׁוּ בָּנָיו אֶת הָאָרֶץ. וְכֵן כֹּהֲנִים וּלְוִיִּם מְבִיאִין וְקוֹרִין מִפְּנֵי שֶׁיֵּשׁ לָהֶן עָרֵי מִגְרָשׁ:","הַקּוֹנֶה שְׁנֵי אִילָנוֹת בְּתוֹךְ [שָׂדֶה] שֶׁל חֲבֵרוֹ מֵבִיא וְאֵינוֹ קוֹרֵא לְפִי שֶׁהַדָּבָר סָפֵק אִם יֵשׁ לוֹ קַרְקַע אוֹ אֵין לוֹ. וְכֵיצַד עוֹשֶׂה. מַקְדִּישׁ אוֹתָם תְּחִלָּה לְבֶדֶק הַבַּיִת מִפְּנֵי שֶׁהֵן סְפֵק חֻלִּין וְאֵין מַכְנִיסִין חֻלִּין לַעֲזָרָה וְהַכֹּהֵן פּוֹדֶה אוֹתָן מִיַּד הַהֶקְדֵּשׁ וְאַחַר כָּךְ אוֹכְלָן. וּמַפְרִישׁ מֵהֶן תְּרוּמָה וּמַעֲשֵׂר מִפְּנֵי שֶׁהֵן סְפֵק חֻלִּין וְנוֹתֵן הַמַּעַשְׂרוֹת שֶׁלָּהֶן לַכֹּהֲנִים שֶׁמָּא בִּכּוּרִים הֵם וַאֲסוּרִין לְזָרִים. וְאֵינוֹ מֵבִיא אוֹתָן בְּעַצְמוֹ אֶלָּא מְשַׁלְּחָן בְּיַד שָׁלִיחַ כְּדֵי שֶׁלֹּא תְּעַכֵּב אוֹתָן הַקְּרִיאָה מִלְּאָכְלָן. שֶׁכָּל שֶׁאֵינוֹ רָאוּי לִקְרִיאָה מִפְּנֵי הַסָּפֵק הַקְּרִיאָה מְעַכֶּבֶת בּוֹ:","הִפְרִישׁ בִּכּוּרָיו וּמָכַר שָׂדֵהוּ מֵבִיא וְאֵינוֹ קוֹרֵא. שֶׁאֵינוֹ יָכוֹל לוֹמַר (דברים כו י) \"אֲשֶׁר נָתַתָּ לִּי ה'\" שֶׁהֲרֵי אֵין לוֹ. וְהַלּוֹקֵחַ אֵינוֹ חַיָּב לְהַפְרִישׁ בִּכּוּרִים אֲחֵרִים מֵאוֹתוֹ הַמִּין שֶׁכְּבָר הִפְרִישׁ מִמֶּנּוּ הַמּוֹכֵר. וְאִם הִפְרִישׁ מֵבִיא וְאֵינוֹ קוֹרֵא. אֲבָל מִמִּין אַחֵר מַפְרִישׁ וּמֵבִיא וְקוֹרֵא:","הַמּוֹכֵר שָׂדֵהוּ לְפֵרוֹת הַלּוֹקֵחַ מֵבִיא וְאֵינוֹ קוֹרֵא שֶׁקִּנְיַן פֵּרוֹת אֵינוֹ כְּקִנְיַן הַגּוּף. אֲבָל מֵבִיא אָדָם מִנִּכְסֵי אִשְׁתּוֹ בִּכּוּרִים וְקוֹרֵא אַף עַל פִּי שֶׁאֵין לוֹ גּוּף הַקַּרְקַע שֶׁנֶּאֱמַר (דברים כו יא) \"אֲשֶׁר נָתַן לְךָ ה' אֱלֹהֶיךָ וּלְבֵיתֶךָ\". אַף עַל פִּי שֶׁמֵּתָה אִשְׁתּוֹ אַחַר שֶׁהִפְרִישׁ וְהוּא בַּדֶּרֶךְ מֵבִיא וְקוֹרֵא:","הַמּוֹכֵר שָׂדֵהוּ אוֹ שֶׁמָּכַר אִילָנוֹת וְקַרְקָעָן בִּזְמַן שֶׁהַיּוֹבֵל נוֹהֵג הֲרֵי זֶה מֵבִיא וְקוֹרֵא בְּיוֹבֵל רִאשׁוֹן בִּלְבַד שֶׁעֲדַיִן לֹא סָמְכָה דַּעְתּוֹ שֶׁל מוֹכֵר שֶׁתַּחֲזֹר לוֹ הַקַּרְקַע. אֲבָל אִם חָזַר וּמְכָרָהּ בְּיוֹבֵל שֵׁנִי הֲרֵי זֶה מֵבִיא וְאֵינוֹ קוֹרֵא שֶׁהֲרֵי סָמְכָה דַּעְתּוֹ שֶׁאֵין לוֹ אֶלָּא הַפֵּרוֹת וְקִנְיַן פֵּרוֹת אֵינוֹ כְּקִנְיַן הַגּוּף:","הִפְרִישׁ בִּכּוּרִים וְחַלָּה וַהֲרֵי הוּא מְסֻכָּן. זֶה שֶׁרָאוּי לְיָרְשׁוֹ מֵבִיא וְאֵינוֹ קוֹרֵא. הִפְרִישׁ בִּכּוּרָיו וְשִׁלְּחָן בְּיַד אַחֵר וּמֵת הַשָּׁלִיחַ בַּדֶּרֶךְ אַף עַל פִּי שֶׁחָזַר הוּא וֶהֱבִיאָן אֵינוֹ קוֹרֵא שֶׁנֶּאֱמַר (דברים כו ב) \"וְלָקַחְתָּ\" (דברים כו ג) \"וּבָאתָ\" עַד שֶׁתִּהְיֶה לְקִיחָה וַהֲבָאָה כְּאַחַת:","הִפְרִישׁ בִּכּוּרָיו וְאָבְדוּ קֹדֶם שֶׁיַּגִּיעַ לְהַר הַבַּיִת וְהִפְרִישׁ אֲחֵרִים תַּחְתֵּיהֶן מֵבִיא הַשְּׁנִיִּים וְאֵינוֹ קוֹרֵא. לְפִי שֶׁאֵינוֹ יָכוֹל לוֹמַר אֶת (דברים כו ב) \"רֵאשִׁית כָּל פְּרִי הָאֲדָמָה\" לְפִי שֶׁאֵינָן רֵאשִׁית. וְאֵלּוּ הַשְּׁנִיִּים אֵין חַיָּבִים עֲלֵיהֶן חֹמֶשׁ כְּבִכּוּרִים:","הֵבִיא בִּכּוּרָיו וְנִטְמְאוּ בַּעֲזָרָה נוֹפְצָם שָׁם וְאֵינוֹ קוֹרֵא:","הֵבִיא בִּכּוּרָיו מֵאֶחָד מִן הַמִּינִים וְקָרָא וְחָזַר וְהֵבִיא בִּכּוּרִים מִמִּין אַחֵר אֵינוֹ קוֹרֵא עֲלֵיהֶן שֶׁנֶּאֱמַר (דברים כו ג) \"הִגַּדְתִּי הַיּוֹם\" פַּעַם אַחַת בְּשָׁנָה הוּא מַגִּיד וְלֹא שְׁתַּיִם:","הִפְרִישׁ בִּכּוּרָיו וְיָבַשׁ הַמַּעְיָן אוֹ שֶׁנִּקְצַץ הָאִילָן מֵבִיא וְאֵינוֹ קוֹרֵא לְפִי שֶׁזֶּה כְּמִי שֶׁאֵין לוֹ קַרְקַע שֶׁהֲרֵי אָבְדָה:","הַמֵּבִיא בִּכּוּרִים מֵאַחַר חַג הַסֻּכּוֹת וְעַד חֲנֻכָּה אַף עַל פִּי שֶׁהִפְרִישָׁן קֹדֶם הֶחָג מֵבִיא וְאֵינוֹ קוֹרֵא שֶׁנֶּאֱמַר (דברים כו יא) \"וְשָׂמַחְתָּ בְכָל הַטּוֹב\" וְאֵין קְרִיאָה אֶלָּא בִּשְׁעַת שִׂמְחָה מֵחַג הַשָּׁבוּעוֹת עַד סוֹף הֶחָג. וּשְׁאָר הַמְּבִיאִין חוּץ מֵאֵלּוּ מְבִיאִין וְקוֹרִין:","הַבִּכּוּרִים וְהַתְּרוּמוֹת וְהַחַלָּה וְהַקֶּרֶן וְהַחֹמֶשׁ וּמַתְּנוֹת בְּהֵמָה הֵם נִכְסֵי כֹּהֵן. יֵשׁ לוֹ לִקְנוֹת מֵהֶן עֲבָדִים וְקַרְקָעוֹת וּבְהֵמָה טְמֵאָה וּבַעַל חוֹב נוֹטְלָן בְּחוֹבוֹ וְהָאִשָּׁה בִּכְתֻבָּתָהּ. וְקוֹנֶה בָּהֶן סֵפֶר תּוֹרָה:","אַף עַל פִּי שֶׁהַבִּכּוּרִים וְהַתְּרוּמוֹת אָסוּר לְהֵאָכֵל לְזָרִים וְאַף עַל פִּי שֶׁהַבִּכּוּרִים עוֹלִין בְּאֶחָד וּמֵאָה כִּתְרוּמָה אִם נִתְעָרְבוּ בְּחֻלִּין בִּירוּשָׁלַיִם אֲסוּרִין בְּכָל שֶׁהֵן בְּמִינָם כְּמַעֲשֵׂר שֵׁנִי. מִפְּנֵי שֶׁהוּא מְקוֹם אֲכִילָתָן עֲשָׂאוּם כְּדָבָר שֶׁיֵּשׁ לוֹ מַתִּירִין. וְאַף עַל פִּי שֶׁהַבִּכּוּרִים אֲסוּרִים לְזָרִים אַף בִּירוּשָׁלַיִם הֲרֵי הֵן אוֹסְרִין בְּכָל שֶׁהֵן. אֲפִלּוּ זָרַע הַבִּכּוּרִים אַחַר שֶׁנִּכְנְסוּ לִירוּשָׁלַיִם הֲרֵי הַגִּדּוּלִין אֲסוּרִין וְאוֹסְרִין בְּכָל שֶׁהֵן אִם נִתְעָרְבוּ בִּירוּשָׁלַיִם. אֲבָל הַזּוֹרֵעַ בִּכּוּרִים קֹדֶם שֶׁיִּכָּנְסוּ לִירוּשָׁלַיִם הַגִּדּוּלִין חֻלִּין:","כֵּיצַד מַעֲלִין אֶת הַבִּכּוּרִים. כָּל הָעֲיָרוֹת שֶׁבַּמַּעֲמָד מִתְכַּנְּסוֹת לְעִירוֹ שֶׁל מַעֲמָד כְּדֵי שֶׁלֹּא יַעֲלוּ יְחִידִים שֶׁנֶּאֱמַר (משלי יד כח) \"בְּרָב עָם הַדְרַת מֶלֶךְ\". וּבָאִים וְלָנִים בִּרְחוֹבָהּ שֶׁל עִיר. וְלֹא יִכָּנְסוּ לַבָּתִּים מִפְּנֵי אֹהֶל הַטֻּמְאָה. וּבַשַּׁחַר הַמְמֻנֶּה אוֹמֵר (ירמיה לא ה) \"קוּמוּ וְנַעֲלֶה צִיּוֹן אֶל ה' אֱלֹהֵינוּ\". וְהַשּׁוֹר הוֹלֵךְ לִפְנֵיהֶם וְקַרְנָיו מְצֻפִּין זָהָב וַעֲטָרָה שֶׁל זַיִת בְּרֹאשׁוֹ לְהוֹדִיעַ שֶׁהַבִּכּוּרִים מִשִּׁבְעַת הַמִּינִין. וְהֶחָלִיל מַכֶּה לִפְנֵיהֶם עַד שֶׁהֵם מַגִּיעִין קָרוֹב לִירוּשָׁלַיִם וְהֵם הוֹלְכִין בְּכָל הַדֶּרֶךְ וְקוֹרִין (תהילים קכב א) \"שָׂמַחְתִּי בְּאֹמְרִים לִי בֵּית ה' נֵלֵךְ\". וְלֹא הָיוּ מְהַלְּכִין בַּיּוֹם אֶלָּא שְׁתֵּי יָדוֹת בִּלְבַד. הִגִּיעוּ קָרוֹב לִירוּשָׁלַיִם שָׁלְחוּ לִפְנֵיהֶם שְׁלוּחִין לְהוֹדִיעַ לְאַנְשֵׁי יְרוּשָׁלַיִם וְעִטְּרוּ אֶת בִּכּוּרֵיהֶם וּפִרְכְּסוּ אוֹתָן. וְאִם הָיָה לָהֶם לַח וְיָבֵשׁ מַרְאִין אֶת הַלַּח מִלְּמַעְלָה. וְהַפַּחוֹת וְהַסְּגָנִים וְהַגִּזְבָּרִים יוֹצְאִין לִקְרָאתָן מִירוּשָׁלַיִם. לְפִי הַבָּאִים הֵם יוֹצְאִין אִם בָּאוּ אֲנָשִׁים הַרְבֵּה יוֹצְאִין לִקְרָאתָן רַבִּים. וְאִם מְעַט מְעַט. וּמִשֶּׁיִּכָּנְסוּ כֻּלָּן בְּשַׁעֲרֵי יְרוּשָׁלַיִם יַתְחִילוּ לִקְרוֹת (תהילים קכב ב) \"עֹמְדוֹת הָיוּ רַגְלֵינוּ בִּשְׁעָרַיִךְ יְרוּשָׁלָיִם\":","כָּל בַּעֲלֵי אֻמָּנֻיּוֹת שֶׁבִּירוּשָׁלַיִם עוֹמְדִין מִפְּנֵיהֶם וְשׁוֹאֲלִין בִּשְׁלוֹמָן. אֲחֵינוּ אַנְשֵׁי מְקוֹם פְּלוֹנִי בּוֹאֲכֶם בְּשָׁלוֹם. וְהֵם מְהַלְּכִין בְּתוֹךְ יְרוּשָׁלַיִם וְהֶחָלִיל מַכֶּה לִפְנֵיהֶם עַד שֶׁהֵם מַגִּיעִים לְהַר הַבַּיִת. הִגִּיעוּ לְהַר הַבַּיִת נוֹטֵל כָּל אֶחָד וְאֶחָד סַלּוֹ עַל כְּתֵפוֹ וְאוֹמְרִין (תהילים קנ א) \"הַלְלוּיָהּ הַלְלוּ אֵל בְּקָדְשׁוֹ\" וְכוּ' עַד (תהילים קנ ו) \"כּל הַנְּשָׁמָה תְּהַלֵּל יָהּ הַלְלוּיָהּ\". וְהֵם מְהַלְּכִים בְּהַר הַבַּיִת וְקוֹרְאִין עַד שֶׁמַּגִּיעִין לַעֲזָרָה. הִגִּיעוּ לַעֲזָרָה דִּבְּרוּ הַלְוִיִּם בְּשִׁיר (תהילים ל ב) \"אֲרוֹמִמְךָ ה' כִּי דִלִּיתָנִי\" וְגוֹ':"],"Mishneh Torah, Firstlings 7":["מִי שֶׁהָיוּ לוֹ עֲשָׂרָה טְלָאִים וְהִפְרִישׁ אֶחָד מֵעֲשָׂרָה. הָיוּ לוֹ מֵאָה וְהִפְרִישׁ עֲשָׂרָה לְמַעֲשֵׂר. אֵין אֵלּוּ מַעֲשֵׂר. אֶלָּא כֵּיצַד עוֹשֶׂה. כּוֹנֵס כָּל הַטְּלָאִים אוֹ כָּל הָעֲגָלִים לַדִּיר. וְעוֹשֶׂה לוֹ פֶּתַח קָטָן כְּדֵי שֶׁלֹּא יֵצְאוּ שְׁנַיִם כְּאֶחָד. וְאִמּוֹתֵיהֶן מַעֲמִיד מִבַּחוּץ. וְהֵן גּוֹעוֹת שֶׁיִּשְׁמְעוּ הַטְּלָאִים קוֹלָן וְיֵצְאוּ מִן הַדִּיר לִקְרָאתָן. שֶׁנֶּאֱמַר (ויקרא כז לב) \"כּל אֲשֶׁר יַעֲבֹר תַּחַת הַשָּׁבֶט\". שֶׁיַּעֲבֹר מֵעַצְמוֹ וְלֹא שֶׁיּוֹצִיאוֹ בְּיָדוֹ. וּכְשֶׁיֵּצְאוּ מִן הַדִּיר זֶה אַחַר זֶה. מַתְחִיל וּמוֹנֶה אוֹתָן בַּשֵּׁבֶט. א' ב' ג' ד' ה' ו' ז' ח' ט'. וְהַיּוֹצֵא עֲשִׂירִי בֵּין זָכָר בֵּין נְקֵבָה בֵּין תָּמִים בֵּין בַּעַל מוּם סוֹקְרוֹ בְּסִקְרָא וְאוֹמֵר הֲרֵי זֶה מַעֲשֵׂר. לֹא סְקָרוֹ בְּסִקְרָא וְלֹא מְנָאָן בַּשֵּׁבֶט אוֹ שֶׁמְּנָאָן רְבוּצִים אוֹ עוֹמְדִים הֲרֵי אֵלּוּ מַעֲשֵׂר הוֹאִיל וּמְנָאָם עֲשָׂרָה עֲשָׂרָה וְקִדֵּשׁ עֲשִׂירִי הֲרֵי זֶה מַעֲשֵׂר:","אֵין צָרִיךְ לְצָרֵף כָּל בְּהֵמָה שֶׁנּוֹלְדָה בִּרְשׁוּתוֹ לְדִיר אֶחָד אֶלָּא מְצָרֵף כָּל עֵדֶר וְעֵדֶר לְבַדּוֹ. הָיוּ לוֹ חֲמִשָּׁה טְלָאִים בִּירוּשָׁלַיִם וַחֲמִשָּׁה טְלָאִים בְּעַכּוֹ אֵין מִצְטָרְפִין וְכֻלָּן פְּטוּרִין מִן הַמַּעֲשֵׂר. וְכַמָּה יִהְיֶה בֵּין אֵלּוּ לְאֵלּוּ וְיִצְטָרְפוּ שִׁשָּׁה עָשָׂר מִיל:","הָיוּ שְׁלֹשָׁה עֲדָרִים בֵּין כָּל אֶחָד וְאֶחָד שִׁשָּׁה עָשָׂר מִיל הֲרֵי שְׁלָשְׁתָּן מִצְטָרְפִין. כֵּיצַד. הָיָה תִּשְׁעָה מִכָּאן וְתִשְׁעָה מִכָּאן וְאֶחָד בְּאֶמְצַע הֲרֵי שְׁלָשְׁתָּן נִכְנָסִין לַדִּיר לְהִתְעַשֵּׂר:","אֵין מְעַשְּׂרִין מִן הַצֹּאן עַל הַבָּקָר וְלֹא מִן הַבָּקָר עַל הַצֹּאן. אֲבָל מְעַשְּׂרִין מִן הַכְּבָשִׂים עַל הָעִזִּים וּמִן הָעִזִּים עַל הַכְּבָשִׂים. שֶׁנֶּאֱמַר (ויקרא כז לב) \"וְכָל מַעְשַׂר בָּקָר וָצֹאן\" מַשְׁמָע כָּל צֹאן אֶחָד שֶׁשְּׁנֵיהֶם נִקְרָאִים שֶׂה וַהֲרֵי הֵם כְּמִין אֶחָד:","אֵין מְעַשְּׂרִים מִן הַנּוֹלָדִים בְּשָׁנָה זוֹ עַל הַנּוֹלָדִים בְּשָׁנָה אַחֶרֶת כְּשֵׁם שֶׁאֵין מְעַשְּׂרִין בְּזֶרַע הָאָרֶץ מִן הֶחָדָשׁ עַל הַיָּשָׁן וְלֹא מִן הַיָּשָׁן עַל הֶחָדָשׁ שֶׁנֶּאֱמַר (דברים יד כב) \"הַיֹּצֵא הַשָּׂדֶה שָׁנָה שָׁנָה\". וְיֵרָאֶה לִי שֶׁאִם עִשֵּׂר בְּהֵמָה מִשָּׁנָה עַל שָׁנָה הֲרֵי זֶה מַעֲשֵׂר מִפְּנֵי חֻמְרַת הַקֳדָשִׁים שֶׁהֲרֵי לֹא הִקְפִּידָה תּוֹרָה עַל מַעֲשַׂר בְּהֵמָה בְּפֵרוּשׁ שֶׁיִּהְיֶה שָׁנָה שָׁנָה:","כָּל הַנּוֹלָדִים בְּאֶחָד בְּתִשְׁרֵי עַד עֶשְׂרִים וְתִשְׁעָה בֶּאֱלוּל מִצְטָרְפִין וּמְעַשְּׂרִין מֵאֵלּוּ עַל אֵלּוּ. נוֹלְדוּ חֲמִשָּׁה טְלָאִים בְּעֶשְׂרִים וְתִשְׁעָה בֶּאֱלוּל וַחֲמִשָּׁה בְּאֶחָד בְּתִשְׁרֵי אֵין מִצְטָרְפִין. יָלְדוּ תּוֹלָדוֹת בְּתוֹךְ שְׁנָתָן הֲרֵי הִיא וּבִתָּהּ נִכְנָסִים לַדִּיר לְהִתְעַשֵּׂר:","אֵין הַטְּלָאִים הַנּוֹלָדִים כְּמוֹ הַטֶּבֶל שֶׁאָסוּר לֶאֱכל מִמֶּנּוּ עַד שֶׁיְּעַשֵּׂר כְּמוֹ שֶׁבֵּאַרְנוּ בִּמְקוֹמוֹ אֶלָּא מֻתָּר לִמְכֹּר וְלִשְׁחֹט כָּל מַה שֶּׁיִּרְצֶה עַד שֶׁיְּעַשֵּׂר וְיִהְיֶה הַמַּעֲשֵׂר קֹדֶשׁ וְיֵאָכֵל כְּהִלְכָתוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:","קָבְעוּ חֲכָמִים שְׁלֹשָׁה זְמַנִּים בְּשָׁנָה לְמַעֲשַׂר בְּהֵמָה וּמִשֶּׁיַגִּיעַ זְמַן מֵהֶן אָסוּר לוֹ לִמְכֹּר אוֹ לִשְׁחֹט עַד שֶׁיְּעַשֵּׂר וְאִם שָׁחַט הֲרֵי זֶה מֻתָּר. וְאֵלּוּ הֵן הַשְּׁלֹשָׁה זְמַנִּים. בְּיוֹם חֲמִשָּׁה עָשָׂר קֹדֶם הַפֶּסַח וּבַיּוֹם חֲמִשָּׁה עָשָׂר קֹדֶם עֲצֶרֶת וּבַיּוֹם חֲמִשָּׁה עָשָׂר קֹדֶם הֶחָג. וְכָל זְמַן מֵאֵלּוּ נִקְרָא גֹּרֶן מַעֲשַׂר בְּהֵמָה. נִמְצֵאתָ אוֹמֵר שֶׁהַגֳּרָנוֹת שֶׁל מַעֲשַׂר בְּהֵמָה בְּיוֹם אַחֲרוֹן מֵחֹדֶשׁ אֲדָר וּבַיּוֹם שְׁלֹשִׁים וַחֲמִשָּׁה מִסְּפִירַת הָעֹמֶר וּבְיוֹם אַחֲרוֹן מֵחֹדֶשׁ אֱלוּל. וְלָמָּה קָבְעוּ הַגֳּרָנוֹת בַּיָמִים אֵלּוּ כְּדֵי שֶׁתִּהְיֶינָה הַבְּהֵמוֹת מְצוּיוֹת לְעוֹלֵי רְגָלִים. שֶׁאַף עַל פִּי שֶׁמֻּתָּר לִמְכֹּר קֹדֶם שֶׁיְּעַשֵּׂר כְּמוֹ שֶׁבֵּאַרְנוּ הָיוּ נִמְנָעִים לִמְכֹּר עַד שֶׁיְּעַשְּׂרוּ וְיַעֲשׂוּ הַמִּצְוָה:","הִכְנִיס כָּל הַצֹּאן אוֹ הַבָּקָר לַדִּיר וְהִתְחִיל לִמְנוֹת וּלְקַדֵּשׁ עֲשִׂירִי עַד שֶׁנִּשְׁאֲרוּ בְּתוֹךְ הַדִּיר פָּחוֹת מֵעֲשָׂרָה הֲרֵי זֶה מַנִּיחָן לְגֹרֶן אַחֵר וְהֵן מִצְטָרְפִין לְאֵלּוּ שֶׁיִּוָּלְדוּ וְיִתְעַשְּׂרוּ הַכּל בְּגֹרֶן אֶחָד. וְאַף עַל פִּי שֶׁהוּא יוֹדֵעַ שֶׁאֵלּוּ יִשָּׁאֲרוּ בַּמִּנְיָן חַיָּב לְהַכְנִיס הַכּל לַדִּיר וְהַנִּשְׁאָר יִשָּׁאֵר:"],"Mishneh Torah, Forbidden Foods 3":["כָּל מַאֲכָל הַיּוֹצֵא מִמִּין מִן הַמִּינִין הָאֲסוּרִין שֶׁלּוֹקִין עַל אֲכִילָתָן הֲרֵי אוֹתוֹ הַמַּאֲכָל אָסוּר בַּאֲכִילָה מִן הַתּוֹרָה. כְּגוֹן חֲלֵב בְּהֵמָה וְחַיָּה הַטְּמֵאִים וּבֵיצֵי עוֹף וְדָג הַטְּמֵאִים שֶׁנֶּאֱמַר (ויקרא יא טז) (דברים יד טו) \"וְאֵת בַּת הַיַּעֲנָה\" זוֹ בֵּיצָתָהּ. וְהוּא הַדִּין לְכָל הָאָסוּר כְּיַעֲנָה וּלְכָל הַדְּבָרִים הַדּוֹמִין לְבֵיצָה:","חֲלֵב הָאָדָם מֻתָּר בַּאֲכִילָה אַף עַל פִּי שֶׁבְּשַׂר הָאָדָם אָסוּר בַּאֲכִילָה. וּכְבָר בֵּאַרְנוּ שֶׁהוּא בַּעֲשֵׂה:","דְּבַשׁ דְּבוֹרִים וּדְבַשׁ צְרָעִים מֻתָּר מִפְּנֵי שֶׁאֵינוֹ מִתַּמְצִית גּוּפָן אֶלָּא כּוֹנְסִין אוֹתוֹ מִן הָעֲשָׂבִים בְּתוֹךְ פִּיהֶן וּמְקִיאִין אוֹתוֹ בַּכַּוֶּרֶת כְּדֵי שֶׁיִּמְצְאוּ אוֹתוֹ לֶאֱכל מִמֶּנּוּ בִּימוֹת הַגְּשָׁמִים:","אַף עַל פִּי שֶׁחֲלֵב אָדָם מֻתָּר אָסְרוּ חֲכָמִים לְגָדוֹל לִינֹק אוֹתוֹ מִן הַשָּׁדַיִם אֶלָּא חוֹלֶבֶת אִשָּׁה לְתוֹךְ הַכְּלִי וְשׁוֹתֶה. וְגָדוֹל שֶׁיָּנַק מִן הַשָּׁד כְּיוֹנֵק שֶׁרֶץ וּמַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","יוֹנֵק תִּינוֹק וְהוֹלֵךְ אֲפִלּוּ אַרְבַּע אוֹ חָמֵשׁ שָׁנִים. וְאִם גְּמָלוּהוּ וּפָרַשׁ שְׁלֹשָׁה יָמִים אוֹ יֶתֶר מֵחֲמַת בֻּרְיוֹ לֹא מֵחֲמַת חָלְיוֹ אֵינוֹ חוֹזֵר וְיוֹנֵק. וְהוּא שֶׁגְּמָלוּהוּ אַחַר כ\"ד חֹדֶשׁ. אֲבָל בְּתוֹךְ זְמַן זֶה אֲפִלּוּ גְּמָלוּהוּ חֹדֶשׁ אוֹ שְׁנַיִם מֻתָּר לַחֲזֹר וְלִינֹק עַד סוֹף כ\"ד חֹדֶשׁ:","אַף עַל פִּי שֶׁחֲלֵב בְּהֵמָה טְמֵאָה וּבֵיצֵי עוֹף טָמֵא אֲסוּרִין מִן הַתּוֹרָה אֵין לוֹקִין עֲלֵיהֶם שֶׁנֶּאֱמַר (ויקרא יא ח) (דברים יד ח) \"מִבְּשָׂרָם לֹא תֹאכֵלוּ\" עַל הַבָּשָׂר הוּא לוֹקֶה וְאֵינוֹ לוֹקֶה. עַל הַבֵּיצָה וְעַל הֶחָלָב. וַהֲרֵי הָאוֹכֵל אוֹתָן כְּאוֹכֵל חֲצִי שִׁעוּר שֶׁהוּא אָסוּר מִן הַתּוֹרָה וְאֵינוֹ לוֹקֶה אֲבָל מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","יֵרָאֶה לִי שֶׁהָאוֹכֵל בֵּיצֵי דָּגִים טְמֵאִים הַנִּמְצָאִים בִּמְעֵיהֶם כְּאוֹכֵל קִרְבֵי דָּגִים טְמֵאִים וְלוֹקֶה מִן הַתּוֹרָה. וְכֵן בֵּיצֵי הָעוֹף הַטָּמֵא הַתְּלוּיוֹת בְּאֶשְׁכּוֹל שֶׁעֲדַיִן לֹא פָּרְשׁוּ וְנִגְמְרוּ. הָאוֹכֵל אוֹתָן לוֹקֶה כְּאוֹכֵל בְּנֵי מֵעַיִם שֶׁלָּהֶן:","בֵּיצַת עוֹף טָמֵא שֶׁהִתְחִיל הָאֶפְרוֹחַ לְהִתְרַקֵּם בָּהּ וַאֲכָלוֹ לוֹקֶה מִשּׁוּם אוֹכֵל שֶׁרֶץ הָעוֹף. אֲבָל בֵּיצַת הָעוֹף טָהוֹר שֶׁהִתְחִיל הָאֶפְרוֹחַ לְהִתְרַקֵּם בָּהּ וַאֲכָלָהּ מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","נִמְצָא עָלֶיהָ קֹרֶט דָּם. אִם עַל הַחֶלְבּוֹן זוֹרֵק אֶת הַדָּם וְאוֹכֵל אֶת הַשְּׁאָר. וְאִם עַל הַחֶלְמוֹן אֲסוּרָה כֻּלָּהּ. בֵּיצָה הַמּוּזֶרֶת הַנֶּפֶשׁ הַיָּפָה תֹּאכְלֶנָּה:","אֶפְרוֹחַ שֶׁנּוֹלַד אַף עַל פִּי שֶׁלֹּא נִתְפַּתְּחוּ עֵינָיו מֻתָּר לְאָכְלוֹ. בְּהֵמָה טְהוֹרָה שֶׁנִּטְרְפָה חֲלָבָהּ אָסוּר כַּחֲלֵב בְּהֵמָה טְמֵאָה. וְכֵן בֵּיצַת עוֹף טָהוֹר שֶׁנִּטְרַף כְּבֵיצַת עוֹף טָמֵא וְאָסוּר:","אֶפְרוֹחַ שֶׁנּוֹלַד מִבֵּיצַת טְרֵפָה מֻתָּר שֶׁאֵין מִינוֹ טָמֵא. הָיָה הָעוֹף סְפֵק טְרֵפָה כָּל הַבֵּיצִים שֶׁתֵּלֵד בַּעֲרֵמָה רִאשׁוֹנָה מַשְׁהִין אוֹתָן. אִם טָעֲנָה עֲרֵמָה שְׁנִיָּה וְהִתְחִילָה לֵילֵד הֻתְּרוּ הָרִאשׁוֹנוֹת שֶׁאִם הָיְתָה טְרֵפָה לֹא הָיְתָה יוֹלֶדֶת עוֹד. וְאִם לֹא יָלְדָה הֲרֵי הֵן אֲסוּרוֹת:","חֲלֵב בְּהֵמָה טְמֵאָה אֵינוֹ נִקְפֶּה וְעוֹמֵד כַּחֲלֵב הַטְּהוֹרָה. וְאִם נִתְעָרֵב חֲלֵב טְמֵאָה בַּחֲלֵב בְּהֵמָה טְהוֹרָה כְּשֶׁתַּעֲמִיד אוֹתוֹ יַעֲמוֹד חֲלֵב הַטְּהוֹרָה וְיֵצֵא חֲלֵב הַטֻּמְאָה עִם הַקּוֹם שֶׁל גְּבִינָה:","וּמִפְּנֵי זֶה יִתֵּן הַדִּין שֶׁכָּל חָלָב הַנִּמְצָא בְּיַד עַכּוּ\"ם אָסוּר שֶׁמָּא עֵרֵב בּוֹ חֲלֵב בְּהֵמָה טְמֵאָה. וּגְבִינַת הָעַכּוּ\"ם מֻתֶּרֶת שֶׁאֵין חֲלֵב בְּהֵמָה טְמֵאָה מִתְגַּבֵּן. אֲבָל בִּימֵי חַכְמֵי מִשְׁנָה גָּזְרוּ עַל גְּבִינַת הָעַכּוּ\"ם וַאֲסָרוּם מִפְּנֵי שֶׁמַּעֲמִידִין אוֹתָהּ בְּעוֹר קֵבָה שֶׁל שְׁחִיטָתָן שֶׁהִיא נְבֵלָה. וְאִם תֹּאמַר וַהֲלֹא עוֹר הַקֵּבָה דָּבָר קָטָן הוּא עַד מְאֹד בֶּחָלָב שֶׁעָמַד בּוֹ וְלָמָּה לֹא יִבָּטֵל בְּמִעוּטוֹ. מִפְּנֵי שֶׁהוּא הַמַּעֲמִיד הַגְּבִינָה. וְהוֹאִיל וְדָבָר הָאָסוּר הוּא שֶׁהֶעֱמִיד הֲרֵי הַכּל אָסוּר כְּמוֹ שֶׁיִּתְבָּאֵר:","גְּבִינָה שֶׁמַּעֲמִידִין אוֹתָהּ הָעַכּוּ\"ם בַּעֲשָׂבִים אוֹ בְּמֵי פֵּרוֹת כְּגוֹן שְׂרַף הַתְּאֵנִים וַהֲרֵי הֵן נִכָּרִין בַּגְּבִינָה הוֹרוּ מִקְצָת הַגְּאוֹנִים שֶׁהִיא אֲסוּרָה. שֶׁכְּבָר גָּזְרוּ עַל כָּל גְּבִינַת הָעַכּוּ\"ם בֵּין שֶׁהֶעֱמִידוּהָ בְּדָבָר אָסוּר בֵּין שֶׁהֶעֱמִידוּהָ בְּדָבָר הַמֻּתָּר גְּזֵרָה מִשּׁוּם שֶׁמַּעֲמִידִין אוֹתָהּ בְּדָבָר הָאָסוּר:","הָאוֹכֵל גְּבִינַת הָעַכּוּ\"ם אוֹ חָלָב שֶׁחֲלָבוֹ עַכּוּ\"ם וְאֵין יִשְׂרָאֵל רוֹאֵהוּ מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. הַחֶמְאָה שֶׁל עַכּוּ\"ם מִקְצָת הַגְּאוֹנִים הִתִּירוּהָ שֶׁהֲרֵי לֹא גָּזְרוּ עַל הַחֶמְאָה וַחֲלֵב הַטְּמֵאָה אֵינוֹ עוֹמֵד. וּמִקְצָת הַגְּאוֹנִים אֲסָרוּהָ מִפְּנֵי צִחְצוּחֵי חָלָב שֶׁיִּשָּׁאֵר בָּהּ. שֶׁהֲרֵי הַקּוֹם שֶׁבַּחֶמְאָה אֵינוֹ מְעֹרָב עִם הַחֶמְאָה כְּדֵי שֶׁיִּבָּטֵל בְּמִעוּטוֹ. וְכָל חָלָב שֶׁלָּהֶן חוֹשְׁשִׁין לוֹ שֶׁמָּא עֵרְבוּ בּוֹ חֲלֵב בְּהֵמָה טְמֵאָה:","יֵרָאֶה לִי שֶׁאִם לָקַח חֶמְאָה מִן הָעַכּוּ\"ם וּבִשְּׁלָהּ עַד שֶׁהָלְכוּ לָהֶן צִחְצוּחֵי חָלָב הֲרֵי זוֹ מֻתֶּרֶת. שֶׁאִם תֹּאמַר נִתְעָרְבוּ עִמָּן וְנִתְבַּשְּׁלוּ כֻּלָּן בָּטְלוּ בְּמִעוּטָם. אֲבָל הַחֶמְאָה שֶׁבִּשְּׁלוּ אוֹתָהּ עַכּוּ\"ם אֲסוּרָה מִשּׁוּם גִּעוּלֵי עַכּוּ\"ם כְּמוֹ שֶׁיִּתְבָּאֵר:","יִשְׂרָאֵל שֶׁיָּשַׁב בְּצַד הָעֵדֶר שֶׁל נָכְרִי וּבָא הַנָּכְרִי וְהֵבִיא לוֹ חָלָב מִן הָעֵדֶר אַף עַל פִּי שֶׁיֵּשׁ בָּעֵדֶר בְּהֵמָה טְמֵאָה הֲרֵי זוֹ מֻתָּר. וְאַף עַל פִּי שֶׁלֹּא רָאָה אוֹתוֹ חוֹלֵב. וְהוּא שֶׁיָּכוֹל לִרְאוֹתוֹ כְּשֶׁהוּא חוֹלֵב כְּשֶׁיַּעֲמֹד. שֶׁהַנָּכְרִי מִתְיָרֵא לַחֲלֹב מִן הַטְּמֵאָה שֶׁמָּא יַעֲמֹד וְיִרְאֶה אוֹתוֹ:","בֵּיצָה שֶׁשְּׁנֵי רָאשֶׁיהָ כַּדִּין אוֹ שֶׁשְּׁנֵי רָאשֶׁיהָ חַדִּין. אוֹ שֶׁהָיָה חֶלְמוֹן מִבַּחוּץ וְחֶלְבּוֹן מִבִּפְנִים בְּיָדוּעַ שֶׁהוּא בֵּיצַת עוֹף טָמֵא. רֹאשָׁהּ אֶחָד כַּד וְרֹאשָׁהּ אֶחָד חַד וְחֶלְבּוֹן מִבַּחוּץ וְחֶלְמוֹן מִבִּפְנִים. אֶפְשָׁר שֶׁהִיא בֵּיצַת עוֹף טָמֵא וְאֶפְשָׁר שֶׁהִיא בֵּיצַת עוֹף טָהוֹר. לְפִיכָךְ שׁוֹאֵל לַצַּיָּד יִשְׂרָאֵל שֶׁמּוֹכְרָהּ. אִם אָמַר לוֹ שֶׁל עוֹף פְּלוֹנִי הוּא וְעוֹף טָהוֹר הוּא סוֹמֵךְ עָלָיו. וְאִם אָמַר שֶׁל עוֹף טָהוֹר וְלֹא אָמַר לוֹ שְׁמוֹ אֵינוֹ סוֹמֵךְ עָלָיו:","לְפִיכָךְ אֵין לוֹקְחִים בֵּיצִים מִן הָעַכּוּ\"ם אֶלָּא אִם הָיָה מַכִּיר אוֹתָן וְיֵשׁ לוֹ בָּהֶן טְבִיעוּת עַיִן שֶׁהֵן בֵּיצֵי עוֹף פְּלוֹנִי הַטָּהוֹר. וְאֵין חוֹשְׁשִׁין לָהֶן שֶׁמָּא הֵן בֵּיצֵי טְרֵפָה אוֹ בֵּיצֵי נְבֵלָה. וְאֵין לוֹקְחִין מִן הָעַכּוּ\"ם בֵּיצָה טְרוּפָה כְּלָל:","בֵּיצֵי דָּגִים סִימָנֵיהֶם כְּסִימָנֵי בֵּיצֵי הָעוֹף. אִם הָיוּ שְׁנֵי רָאשֶׁיהָ כַּדִּין אוֹ חַדִּין טְמֵאָה. אֶחָד כַּד וְאֶחָד חַד שׁוֹאֵל לְיִשְׂרְאֵלִי הַמּוֹכֵר. אִם אָמַר לוֹ אֲנִי מְלַחְתִּים וְהוֹצֵאתִים מִדָּג טָהוֹר אוֹכֵל עַל פִּיו. וְאִם אָמַר לוֹ טְהוֹרִין הֵם אֵינוֹ נֶאֱמָן אֶלָּא אִם כֵּן הָיָה אָדָם שֶׁהֻחְזַק בְּכַשְׁרוּת:","וְכֵן אֵין לוֹקְחִין גְּבִינָה וַחֲתִיכַת דָּג שֶׁאֵין בָּהּ סִימָן אֶלָּא מִיִּשְׂרְאֵלִי שֶׁהֻחְזַק בְּכַשְׁרוּת. אֲבָל בְּאֶרֶץ יִשְׂרָאֵל כְּשֶׁהָיְתָה רֻבָּהּ יִשְׂרָאֵל לוֹקְחִין מִכָּל יִשְׂרְאֵלִי שֶׁבָּהּ. וְהֶחָלָב לוֹקְחִין אוֹתוֹ מִכָּל יִשְׂרָאֵל מִכָּל מָקוֹם:","הַכּוֹבֵשׁ דָּגִים טְמֵאִים צִירָן אָסוּר. אֲבָל צִיר חֲגָבִים טְמֵאִים מֻתָּר מִפְּנֵי שֶׁאֵין בָּהֶם לַחְלוּחִית. לְפִיכָךְ אֵין לוֹקְחִין צִיר מִן הָעַכּוּ\"ם אֶלָּא אִם כֵּן הָיָה בּוֹ דָּג טָהוֹר מְשׁוֹטֵט בּוֹ אֲפִלּוּ דָּג אֶחָד:","עַכּוּ\"ם שֶׁהֵבִיא עֲרֵבָה מְלֵאָה חָבִיּוֹת פְּתוּחוֹת שֶׁל צִיר וְדָג אֶחָד טָהוֹר בְּאַחַת מֵהֶם כֻּלָּן מֻתָּרוֹת. הָיוּ סְתוּמוֹת פָּתַח אַחַת וְנִמְצָא בָּהּ דָּג טָהוֹר שְׁנִיָּה וְנִמְצָא בָּהּ טָהוֹר כֻּלָּן מֻתָּרוֹת. וְהוּא שֶׁיִּהְיֶה רֹאשׁוֹ שֶׁל דָּג וּשְׁדֵרוֹ קַיָּם כְּדֵי שֶׁיְּהֵא נִכָּר שֶׁהוּא דָּג טָהוֹר. לְפִיכָךְ אֵין לוֹקְחִין דָּגִים מְרוֹצָצִין מְלוּחִין מִן הָעַכּוּ\"ם וְהֵם הַנִּקְרָאִים טָרִית טְרוּפָה. וְאִם הָיָה רֹאשׁ הַדָּג וּשְׁדֵרוֹ נִכָּר אַף עַל פִּי שֶׁהוּא מְרוֹצָץ מֻתָּר לִקַּח אוֹתוֹ מִן הָעַכּוּ\"ם:","עַכּוּ\"ם שֶׁהֵבִיא גָּרָב שֶׁל חֲתִיכוֹת דָּג שֶׁחִתּוּכָן שָׁוֶה וְהֵן נִכָּרִין שֶׁכֻּלָּן מִדָּג אֶחָד וּמָצָא בַּחֲתִיכָה אַחַת מֵהֶן קַשְׂקַשִּׂין הֲרֵי כֻּלָּן מֻתָּרוֹת:"],"Mishneh Torah, Forbidden Intercourse 14":["כֵּיצַד מְקַבְּלִין גֵּרֵי הַצֶּדֶק. כְּשֶׁיָּבוֹא אֶחָד לִהִתְגַּיֵּר מִן הָעַכּוּ\"ם וְיִבְדְּקוּ אַחֲרָיו וְלֹא יִמְצְאוּ עִלָּה. אוֹמְרִים לוֹ מָה רָאִיתָ שֶׁבָּאתָ לְהִתְגַּיֵּר. אִי אַתָּה יוֹדֵעַ שֶׁיִּשְׂרָאֵל בַּזְּמַן הַזֶּה דְּווּיִים וּדְחוּפִים וּמְסֻחָפִין וּמְטֹרָפִין וְיִסּוּרִין בָּאִין עֲלֵיהֶן. אִם אָמַר אֲנִי יוֹדֵעַ וְאֵינִי כְּדַאי מְקַבְּלִין אוֹתוֹ מִיָּד:","וּמוֹדִיעִין אוֹתוֹ עִקְּרֵי הַדָּת שֶׁהוּא יִחוּד הַשֵּׁם וְאִסּוּר עַכּוּ\"ם. וּמַאֲרִיכִין בַּדָּבָר הַזֶּה. וּמוֹדִיעִין אוֹתוֹ מִקְצָת מִצְוֹת קַלּוֹת וּמִקְצָת מִצְוֹת חֲמוּרוֹת. וְאֵין מַאֲרִיכִין בְּדָבָר זֶה. וּמוֹדִיעִין אוֹתוֹ עֲוֹן לֶקֶט שִׁכְחָה וּפֵאָה וּמַעֲשֵׂר שֵׁנִי. וּמוֹדִיעִין אוֹתוֹ עָנְשָׁן שֶׁל מִצְוֹת. כֵּיצַד. אוֹמְרִים לוֹ הֱוֵי יוֹדֵעַ שֶׁעַד שֶׁלֹּא בָּאתָ לְדָת זוֹ אִם אָכַלְתָּ חֵלֶב אִי אַתָּה עָנוּשׁ כָּרֵת. אִם חִלַּלְתָּ שַׁבָּת אִי אַתָּה עָנוּשׁ סְקִילָה. וְעַכְשָׁיו אַחַר שֶׁתִּתְגַּיֵּר אִם אָכַלְתָּ חֵלֶב אַתָּה עָנוּשׁ כָּרֵת. אִם חִלַּלְתָּ שַׁבָּת אַתָּה עָנוּשׁ סְקִילָה. וְאֵין מַרְבִּין עָלָיו. וְאֵין מְדַקְדְּקִין עָלָיו. שֶׁמָּא יִגְרֹם לְטָרְדוֹ וּלְהַטּוֹתוֹ מִדֶּרֶךְ טוֹבָה לְדֶרֶךְ רָעָה. שֶׁבַּתְּחִלָּה אֵין מוֹשְׁכִין אֶת הָאָדָם אֶלָּא בְּדִבְרֵי רָצוֹן וְרַכִּים. וְכֵן הוּא אוֹמֵר (הושע יא ד) \"בְּחַבְלֵי אָדָם אֶמְשְׁכֵם\" וְאַחַר כָּךְ (הושע יא ד) \"בַּעֲבֹתוֹת אַהֲבָה\":","וּכְשֵׁם שֶׁמּוֹדִיעִין אוֹתוֹ עָנְשָׁן שֶׁל מִצְוֹת כָּךְ מוֹדִיעִין אוֹתוֹ שְׂכָרָן שֶׁל מִצְוֹת. וּמוֹדִיעִין אוֹתוֹ שֶׁבַּעֲשִׂיַּת מִצְוֹת אֵלּוּ יִזְכֶּה לְחַיֵּי הָעוֹלָם הַבָּא. וְשֶׁאֵין שׁוּם צַדִּיק גָּמוּר אֶלָּא בַּעַל הַחָכְמָה שֶׁעוֹשֶׂה מִצְוֹת אֵלּוּ וְיוֹדְעָן:","וְאוֹמְרִים לוֹ הֱוֵי יוֹדֵעַ שֶׁהָעוֹלָם הַבָּא אֵינוֹ צָפוּן אֶלָּא לַצַּדִּיקִים וְהֵם יִשְׂרָאֵל. וְזֶה שֶׁתִּרְאֶה יִשְׂרָאֵל בְּצַעַר בָּעוֹלָם הַזֶּה טוֹבָה הִיא צְפוּנָה לָהֶם שֶׁאֵינָן יְכוֹלִין לְקַבֵּל רֹב טוֹבָה בָּעוֹלָם הַזֶּה כָּאֻמּוֹת. שֶׁמָּא יָרוּם לִבָּם וְיִתְעוּ וְיַפְסִידוּ שְׂכַר הָעוֹלָם הַבָּא כָּעִנְיָן שֶׁנֶּאֱמַר (דברים לב טו) \"וַיִּשְׁמַן יְשֻׁרוּן וַיִּבְעָט\":","וְאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא מֵבִיא עֲלֵיהֶן רֹב פֻּרְעָנוּת כְּדֵי שֶׁלֹּא יֹאבְדוּ אֶלָּא כָּל הָעַכּוּ\"ם כָּלִין וְהֵן עוֹמְדִין. וּמַאֲרִיכִין בַּדָּבָר הַזֶּה כְּדֵי לְחַבְּבָן. אִם חָזַר בּוֹ וְלֹא רָצָה לְקַבֵּל הוֹלֵךְ לְדַרְכּוֹ. וְאִם קִבֵּל אֵין מַשְׁהִין אוֹתוֹ אֶלָּא מָלִין אוֹתוֹ מִיָּד. וְאִם הָיָה מָהוּל מַטִּיפִין מִמֶּנּוּ דַּם בְּרִית וּמַשְׁהִים אוֹתוֹ עַד שֶׁיִּתְרַפֵּא רְפוּאָה שְׁלֵמָה. וְאַחַר כָּךְ מַטְבִּילִין אוֹתוֹ:","וּשְׁלֹשָׁה עוֹמְדִין עַל גַּבָּיו וּמוֹדִיעִין אוֹתוֹ מִקְצָת מִצְוֹת קַלּוֹת וּמִקְצָת מִצְוֹת חֲמוּרוֹת פַּעַם שְׁנִיָּה וְהוּא עוֹמֵד בַּמַּיִם. וְאִם הָיְתָה אִשָּׁה נָשִׁים מוֹשִׁיבוֹת אוֹתָהּ בַּמַּיִם עַד צַוָּארָהּ וְהַדַּיָּנִין מִבַּחוּץ וּמוֹדִיעִין אוֹתָהּ מִקְצָת מִצְוֹת קַלּוֹת וַחֲמוּרוֹת. וְהִיא יוֹשֶׁבֶת בַּמַּיִם וְאַחַר כָּךְ טוֹבֶלֶת בִּפְנֵיהֶם וְהֵן מַחְזִירִין פְּנֵיהֶן וְיוֹצְאִין כְּדֵי שֶׁלֹּא יִרְאוּ אוֹתָהּ כְּשֶׁתַּעֲלֶה מִן הַמַּיִם:","אֵי זֶה הוּא גֵּר תּוֹשָׁב זֶה עַכּוּ\"ם שֶׁקִּבֵּל עָלָיו שֶׁלֹּא יַעֲבֹד עֲבוֹדָה זָרָה עִם שְׁאָר הַמִּצְוֹת שֶׁנִּצְטַוּוּ בְּנֵי נֹחַ וְלֹא מָל וְלֹא טָבַל הֲרֵי זֶה מְקַבְּלִין אוֹתוֹ וְהוּא מֵחֲסִידֵי אֻמּוֹת הָעוֹלָם. וְלָמָּה נִקְרָא שְׁמוֹ תּוֹשָׁב לְפִי שֶׁמֻּתָּר לָנוּ לְהוֹשִׁיבוֹ בֵּינֵינוּ בְּאֶרֶץ יִשְׂרָאֵל כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת עַכּוּ\"ם:","וְאֵין מְקַבְּלִין גֵּר תּוֹשָׁב אֶלָּא בִּזְמַן שֶׁהַיּוֹבֵל נוֹהֵג. אֲבָל בַּזְּמַן הַזֶּה אֲפִלּוּ קִבֵּל עָלָיו כָּל הַתּוֹרָה כֻּלָּהּ חוּץ מִדִּקְדּוּק אֶחָד אֵין מְקַבְּלִין אוֹתוֹ:","הָעֶבֶד הַנִּלְקָח מִן הָעַכּוּ\"ם אֵין אוֹמְרִין לוֹ מָה רָאִיתָ שֶׁבָּאתָ. אֶלָּא אוֹמְרִים לוֹ רְצוֹנְךָ שֶׁתִּכָּנֵס לִכְלַל עַבְדֵי יִשְׂרָאֵל וְתִהְיֶה מִן הַכְּשֵׁרִים אוֹ לֹא. אִם רָצָה מוֹדִיעִין לוֹ עִקְּרֵי הַדָּת וּמִקְצָת מִצְוֹת קַלּוֹת וַחֲמוּרוֹת וְעָנְשָׁן וּשְׂכָרָן כְּמוֹ שֶׁמּוֹדִיעִין אֶת הַגֵּר וּמַטְבִּילִין אוֹתוֹ כְּגֵר. וּמוֹדִיעִין אוֹתוֹ כְּשֶׁהוּא בַּמַּיִם. וְאִם לֹא רָצָה לְקַבֵּל מְגַלְגְּלִין עָלָיו כָּל שְׁנֵים עָשָׂר חֹדֶשׁ וּמוֹכְרוֹ לְעַכּוּ\"ם. וְאָסוּר לְקַיְּמוֹ יוֹתֵר עַל כֵּן. וְאִם הִתְנָה עָלָיו מִתְּחִלָּה שֶׁלֹּא יָמוּל וְלֹא יִטְבּל אֶלָּא יִהְיֶה גֵּר תּוֹשָׁב מֻתָּר לְקַיְּמוֹ בַּעֲבוֹדָתוֹ כְּשֶׁהוּא גֵּר תּוֹשָׁב. וְאֵין מְקַיְּמִין עֶבֶד כָּזֶה אֶלָּא בִּזְמַן הַיּוֹבֵל:","הָעַכּוּ\"ם אֵין אֲסוּרִים עֲלֵיהֶם מִשּׁוּם עֶרְוָה אֶלָּא אִמּוֹ וְאֵשֶׁת אָבִיו וַאֲחוֹתוֹ מֵאִמּוֹ וְאֵשֶׁת אִישׁ וְזָכָר וּבְהֵמָה כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת מְלָכִים וּמִלְחֲמוֹתֵיהֶן. אֲבָל שְׁאָר עֲרָיוֹת מֻתָּרִין לָהֶן:","עַכּוּ\"ם שֶׁנִּתְגַּיֵּר וְעֶבֶד שֶׁנִּשְׁתַּחְרֵר הֲרֵי הוּא כְּקָטָן שֶׁנּוֹלַד. וְכָל שְׁאֵר בָּשָׂר שֶׁהָיוּ לוֹ כְּשֶׁהוּא עַכּוּ\"ם אוֹ כְּשֶׁהוּא עֶבֶד אֵינָן שְׁאֵר בָּשָׂר. וְאִם נִתְגַּיֵּר הוּא וְהֵם אֵינוֹ חַיָּב עַל אַחַת מֵהֶם מִשּׁוּם עֶרְוָה כְּלָל:","דִּין תּוֹרָה שֶׁמֻּתָּר לְעַכּוּ\"ם שֶׁיִּשָּׂא אִמּוֹ אוֹ אֲחוֹתוֹ מֵאִמּוֹ שֶׁנִּתְגַּיְּרוּ. אֲבָל חֲכָמִים אָסְרוּ דָּבָר זֶה כְּדֵי שֶׁלֹּא יֹאמְרוּ בָּאנוּ מִקְּדֻשָּׁה חֲמוּרָה לִקְדֻשָּׁה קַלָּה. שֶׁאֶמֶשׁ הָיְתָה לוֹ זוֹ אֲסוּרָה וְהַיּוֹם מֻתֶּרֶת. וְכֵן גֵּר שֶׁבָּא עַל אִמּוֹ אוֹ אֲחוֹתוֹ וְהִיא בְּגֵיוּתָהּ הֲרֵי זֶה כְּבָא עַל הַנָּכְרִית:","כֵּיצַד דִּין הַגֵּרִים בַּעֲרָיוֹת שֶׁל שְׁאֵר בָּשָׂר. אִם הָיָה נָשׂוּי כְּשֶׁהוּא עַכּוּ\"ם לְאִמּוֹ אוֹ לַאֲחוֹתוֹ וְנִתְגַּיְּרוּ מַפְרִישִׁין אוֹתָן כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם הָיָה נָשׂוּי לִשְׁאָר עֲרָיוֹת וְנִתְגַּיֵּר הוּא וְאִשְׁתּוֹ אֵין מַפְרִישִׁין אוֹתָן. גֵּר אָסוּר בִּשְׁאֵר הָאֵם אַחַר שֶׁנִּתְגַּיֵּר מִדִּבְרֵי סוֹפְרִים. וּמֻתָּר בִּשְׁאֵר הָאָב אַף עַל פִּי שֶׁיּוֹדֵעַ בְּוַדַּאי שֶׁזֶּה שְׁאֵרוֹ מֵאָבִיו. כְּגוֹן תְּאוֹמִים שֶׁדָּבָר בָּרוּר שֶׁאָבִיו שֶׁל זֶה הוּא אָבִיו שֶׁל זֶה אַף עַל פִּי כֵן לֹא גָּזְרוּ עַל שְׁאֵר אָבִיו. לְפִיכָךְ נוֹשֵׂא הַגֵּר אֵשֶׁת אָחִיו מֵאָבִיו וְאֵשֶׁת אֲחִי אָבִיו וְאֵשֶׁת אָבִיו וְאֵשֶׁת בְּנוֹ אַף עַל פִּי שֶׁנִּשֵּׂאת לְאָחִיו אוֹ לְאָבִיו אוֹ לַאֲחִי אָבִיו אוֹ לִבְנוֹ אַחַר שֶׁנִּתְגַּיְּרוּ. וְכֵן אֲחוֹת אִמּוֹ מֵאָבִיהָ וַאֲחוֹתוֹ מֵאָבִיו. וּבִתּוֹ שֶׁנִּתְגַּיְּרָה מֻתֶּרֶת לוֹ. אֲבָל אֵינוֹ נוֹשֵׂא לֹא אֲחוֹתוֹ מֵאִמּוֹ וְלֹא אֲחוֹת אִמּוֹ מֵאִמָּהּ וְלֹא אֵשֶׁת אָחִיו מֵאִמּוֹ שֶׁנְּשָׂאָהּ אָחִיו מֵאִמּוֹ אַחַר שֶׁנִּתְגַּיֵּר. אֲבָל אִם נְשָׂאָהּ אָחִיו כְּשֶׁהוּא עַכּוּ\"ם הֲרֵי זוֹ מֻתֶּרֶת לוֹ:","שְׁנֵי אַחִים תְּאוֹמִים שֶׁהָיְתָה הוֹרָתָן שֶׁלֹּא בִּקְדֻשָּׁה וְלֵדָתָן בִּקְדֻשָּׁה חַיָּבִין מִשּׁוּם אֵשֶׁת אָח:","הַנּוֹשֵׂא גִּיֹּרֶת וּבִתָּהּ הַגִּיֹּרֶת אוֹ שְׁתֵּי אֲחָיוֹת מִן הָאֵם יוֹשֵׁב עִם אַחַת מֵהֶן וּמְגָרֵשׁ הַשְּׁנִיָּה. נָשָׂא גִּיֹּרֶת וּמֵתָה הֲרֵי זֶה מֻתָּר לִשָּׂא אִמָּהּ אוֹ בִּתָּהּ שֶׁלֹּא גָּזְרוּ אֶלָּא בְּחַיֵּיהֶן. וּמֻתָּר לְאָדָם לִשָּׂא שְׁתֵּי אֲחָיוֹת גִּיּוֹרוֹת מִן הָאָב שֶׁלֹּא גָּזְרוּ בִּשְׁאֵר הָאָב כְּמוֹ שֶׁבֵּאַרְנוּ:","הַשְּׁנִיּוֹת כֻּלָּן לֹא גָּזְרוּ עֲלֵיהֶן בְּגֵרִים. לְפִיכָךְ מֻתָּר הַגֵּר לִשָּׂא אֵם אִמּוֹ. וְנוֹשֵׂא אָדָם גִּיֹּרֶת וְאֵם אִמָּהּ אוֹ בַּת בַּת בִּתָּהּ. וְכֵן בִּשְׁאָר הַשְּׁנִיּוֹת:","הָעֶבֶד מֻתָּר לִשָּׂא אִמּוֹ כְּשֶׁהוּא עֶבֶד וְאֵין צָרִיךְ לוֹמַר בִּתּוֹ וַאֲחוֹתוֹ וְכַיּוֹצֵא בָּהֶן שֶׁכְּבָר יָצָא מִכְּלַל עַכּוּ\"ם. וְאֵין הָעֲרָיוֹת הָאֲסוּרוֹת עַל הָעַכּוּ\"ם אֲסוּרוֹת עָלָיו וְלֹא בָּא לִכְלַל יִשְׂרָאֵל כְּדֵי שֶׁיֵּאָסְרוּ עָלָיו עֲרָיוֹת הָאֲסוּרוֹת עַל הַגֵּרִים:","וְיֵרָאֶה לִי שֶׁאִם בָּא הָעֶבֶד עַל הַזָּכוּר וּבְהֵמָה יֵהָרֵגוּ. שֶׁאִסּוּר שְׁתֵּי עֲרָיוֹת אֵלּוּ שָׁוֶה בְּכָל הָאָדָם:","עֲבָדִים שֶׁנִּשְׁתַּחְרְרוּ הֲרֵי הֵן כְּגֵרִים. כָּל שֶׁאָסוּר לְגֵרִים אָסוּר לָהֶן וְכָל הַמֻּתָּר לְגֵרִים מֻתָּר לָהֶן. נוֹתֵן אָדָם שִׁפְחָתוֹ לְעַבְדּוֹ אוֹ לְעֶבֶד חֲבֵרוֹ. וּמוֹסֵר שִׁפְחָה אַחַת לִשְׁנֵי עֲבָדִים לְכַתְּחִלָּה וְאֵינָן צְרִיכִין שׁוּם דָּבָר אֶלָּא הֲרֵי הֵן כִּבְהֵמוֹת. וְשִׁפְחָה שֶׁהִיא מְיֻחֶדֶת לְעֶבֶד אוֹ שֶׁאֵינָהּ מְיֻחֶדֶת אַחַת הִיא לְפִי שֶׁאֵין אִישׁוּת אֶלָּא לְיִשְׂרָאֵל אוֹ לְעַכּוּ\"ם עַל הָעַכּוּ\"ם אֲבָל לֹא לַעֲבָדִים עַל הָעֲבָדִים וְלֹא לַעֲבָדִים עַל יִשְׂרָאֵל:"],"Mishneh Torah, Forbidden Intercourse 5":["הָאִשָׁה מִתְטַמֵּאת בְּאֹנֶס בֵּין לְנִדָּה בֵּין לְזִיבוּת. כֵּיצַד. כְּגוֹן שֶׁקָּפְצָה מִמָּקוֹם לְמָקוֹם. אוֹ רָאֲתָה בְּהֵמָה אוֹ חַיָּה אוֹ עוֹף מִתְעַסְּקִין זֶה עִם זֶה וְחָמְדָה וְרָאֲתָה דָּם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה הוֹאִיל וְרָאֲתָה דָּם מִכָּל מָקוֹם נִטְמֵאת וּמְטַמְּאָה בְּכָל שֶׁהוּא. אֲפִלּוּ רָאֲתָה דָּם טִפָּה כְּחַרְדָּל הֲרֵי זוֹ כְּמִי שֶׁזָּב מִמֶּנָּה דָּמִים הַרְבֵּה:","כָּל הַנָּשִׁים מִתְטַמְּאוֹת בַּבַּיִת הַחִיצוֹן. וְאַף עַל פִּי שֶׁלֹּא יָצָא הַדָּם לַחוּץ אֶלָּא נֶעֱקַר מִן הָרֶחֶם וְלֹא שָׁתַת הוֹאִיל וְיָצָא מִבֵּין הַשִּׁנַּיִם הֲרֵי זוֹ טְמֵאָה וְאַף עַל פִּי שֶׁעֲדַיִן הַדָּם בִּבְשָׂרָהּ שֶׁנֶּאֱמַר (ויקרא טו יט) \"דָּם יִהְיֶה זֹבָהּ בִּבְשָׂרָהּ\". וְעַד הֵיכָן הוּא בֵּין הַשִּׁנַּיִם עַד מָקוֹם שֶׁיַּגִּיעַ אֵלָיו הָאֵיבָר בִּשְׁעַת גְּמַר בִּיאָה. וּבֵין הַשִּׁנַּיִם עַצְמוֹ כִּלְפָנִים:","מָשָׁל מָשְׁלוּ חֲכָמִים בָּאִשָּׁה. הָרֶחֶם שֶׁנּוֹצַר בּוֹ הַוָּלָד הוּא הַנִּקְרָא מָקוֹר. וְהוּא שֶׁדַּם נִדָּה וְזָבָה יוֹצֵא מִמֶּנּוּ. וְקוֹרְאִין אוֹתוֹ חֶדֶר לְפִי שֶׁהוּא לִפְנַי וְלִפְנִים. וְצַוַּאר הָרֶחֶם כֻּלּוֹ וְהוּא הַמָּקוֹם הָאָרֹךְ שֶׁמִּתְקַּבֵּץ רֹאשׁוֹ בִּשְׁעַת הָעִבּוּר כְּדֵי שֶׁלֹּא יִפּל הַוָּלָד וְנִפְתַּח הַרְבֵּה בִּשְׁעַת לֵדָה קוֹרְאִין אוֹתוֹ פְּרוֹזְדוֹר כְּלוֹמַר שֶׁהוּא בֵּית שַׁעַר לַרֶחֶם:","וּבִשְׁעַת גְּמַר בִּיאָה הָאֵיבָר נִכְנַס בִּפְרוֹזְדוֹר וְאֵינוֹ מַגִּיעַ עַד רֹאשׁוֹ שֶׁמִּבִּפְנִים אֶלָּא רָחוֹק מִמֶּנּוּ מְעַט לְפִי הָאֶצְבָּעוֹת. וּלְמַעְלָה מִן הַחֶדֶר וּמִן הַפְּרוֹזְדוֹר בֵּין חֶדֶר לִפְרוֹזְדוֹר הוּא הַמָּקוֹם שֶׁיֵּשׁ בּוֹ שְׁתֵּי בֵּיצִים שֶׁל אִשָּׁה. וְהַשְּׁבִילִים שֶׁבָּהֶן מִתְבַּשֶּׁלֶת שִׁכְבַת זֶרַע שֶׁלָּהּ מָקוֹם זֶה הוּא הַנִּקְרָא עֲלִיָּה. וּכְמוֹ נֶקֶב פָּתוּחַ מִן הָעֲלִיָּה לְגַג הַפְּרוֹזְדוֹר וְנֶקֶב זֶה קוֹרְאִין אוֹתוֹ לוּל. וְהָאֵיבָר נִכְנַס לִפְנִים מִן הַלּוּל בִּשְׁעַת גְּמַר בִּיאָה:","דָּם הַבָּא מִן הַחֶדֶר כֻּלּוֹ טָמֵא חוּץ מִדַּם טֹהַר שֶׁהַתּוֹרָה טִהֲרַתּוּ וְדַם קֹשִׁי כְּמוֹ שֶׁיִּתְבָּאֵר. וְדַם הָעֲלִיָּה כֻּלּוֹ טָהוֹר שֶׁהוּא כְּמוֹ דַּם מַכָּה שֶׁבַּמֵּעַיִם אוֹ בַּכָּבֵד אוֹ בְּכוּלְיָא וְכַיּוֹצֵא בָּהֶן. וְדָם הַנִּמְצָא בַּפְּרוֹזְדוֹר אִם נִמְצָא מִן הַלּוּל וּלְפָנִים הֲרֵי זֶה טָמֵא שֶׁחֶזְקָתוֹ מִן הַחֶדֶר. וְחַיָּבִין עָלָיו עַל בִּיאַת מִקְדָּשׁ וְשׂוֹרְפִין עָלָיו תְּרוּמָה וְקָדָשִׁים וְאֵין אוֹמְרִים שֶׁמָּא מִן הָעֲלִיָּה יָרַד דֶּרֶךְ הַנֶּקֶב. שֶׁרֹב הַדָּמִים הַנִּמְצָאִין כָּאן מִן הַחֶדֶר. נִמְצָא הַדָּם בַּפְּרוֹזְדוֹר חוּץ לַנֶּקֶב הֲרֵי טֻמְאָתוֹ בְּסָפֵק שֶׁמָּא מִן הַחֶדֶר בָּא אוֹ מִן הָעֲלִיָּה שָׁתַת דֶּרֶךְ הַלּוּל. לְפִיכָךְ אֵין שׂוֹרְפִין עָלָיו תְּרוּמָה וְקָדָשִׁים וְאֵין חַיָּבִין עָלָיו עַל בִּיאַת הַמִּקְדָּשׁ:","לֹא כָּל מַשְׁקֶה הַבָּא מִן הַחֶדֶר מְטַמֵּא אֶלָּא הַדָּם בִּלְבַד שֶׁנֶּאֱמַר (ויקרא טו יט) \"דָּם יִהְיֶה זֹבָהּ\". לְפִיכָךְ אִם שָׁתַת מִן הָרֶחֶם לֹבֶן אוֹ מַשְׁקֶה יָרֹק אַף עַל פִּי שֶׁסְּמִיכָתוֹ כְּדָם הוֹאִיל וְאֵין מַרְאָיו מַרְאֶה דָּם הֲרֵי זֶה טָהוֹר:","וַחֲמִשָּׁה דָּמִים טְמֵאִים בָּאִשָּׁה וְהַשְּׁאָר טְהוֹרִין. וְאֵלּוּ הֵן. הָאָדֹם. וְהַשָּׁחוֹר. וּכְקֶרֶן כַּרְכֹּם. וּכְמֵימֵי אֲדָמָה. וּכְיַיִן הַמָּזוּג:","הָאָדֹם כֵּיצַד הוּא עֵינוֹ. כְּעַמּוּד שֶׁיָּצָא רִאשׁוֹן מִדַּם הַקָּזָה שֶׁל בְּנֵי אָדָם, נוֹתֵן הַדָּם בְּכוֹס וּמַקִּיף לוֹ וְרוֹאֵהוּ. וְהַשָּׁחוֹר כְּעֵין הַדְּיוֹ הַיָּבֵשׁ. כְּקֶרֶן כַּרְכֹּם כֵּיצַד. יָבִיא כַּרְכֹּם לַח בְּגוּשׁ אֲדָמָה שֶׁעָלָיו וְלוֹקֵחַ מִן הַבָּרוּר שֶׁבּוֹ הַקָּנֶה הָאֶמְצָעִי שֶׁלּוֹ שֶׁכֻּלּוֹ כְּמוֹ קָנֶה הוּא וּבְכָל אֶחָד וְאֶחָד שְׁלֹשָׁה קָנִים וּבְכָל קָנֶה שְׁלֹשָׁה עָלִים וּמַקִּיף הַדָּם לֶעָלֶה הָאֶמְצָעִי שֶׁבַּקָּנֶה הָאֶמְצָעִי וְרוֹאֶה בּוֹ. כְּמֵימֵי אֲדָמָה כֵּיצַד. יָבִיא אֲדָמָה מִבִּקְעַת סִיכְנֵי וְכַיּוֹצֵא בָּהּ שֶׁהִיא אֲדֻמָּה וְנוֹתֵן עָלֶיהָ מַיִם בִּכְלִי עַד שֶׁיַּעֲלֶה הַמַּיִם עַל הֶעָפָר כִּקְלִפַּת הַשּׁוּם. וְאֵין שִׁעוּר לַמַּיִם וְלֹא לֶעָפָר. וּמְעַכְּרָן בִּכְלִי וּמְשַׁעֵר בָּהֶן לִשְׁעָתוֹ וּבִמְקוֹמוֹ כְּשֶׁהֵן עֲכוּרִין. וְאִם צָלְלוּ חוֹזֵר וּמְעַכְּרָן:","אַרְבָּעָה מַרְאוֹת הַלָּלוּ אִם הָיָה מַרְאֵה הַדָּם כְּמַרְאֵה כָּל אֶחָד מֵהֶן אוֹ עָמֹק מֵהֶן הֲרֵי זֶה טָמֵא. הָיָה דִּיהָה מִמֶּנּוּ הֲרֵי זֶה טָהוֹר. כֵּיצַד. הָיָה הַדָּם שָׁחוֹר יֶתֶר מִכִּדְיוֹ הַיָּבֵשׁ טְמֵאָה. הָיָה פָּחוֹת מִמֶּנּוּ כְּגוֹן שֶׁהָיָה מַרְאֵהוּ כְּעֵין הַזַּיִת הַשָּׁחוֹר אוֹ כְּעֵין הַזֶּפֶת אוֹ כְּעֵין הָעוֹרֵב הֲרֵי זֶה טָהוֹר. וְכֵן בִּשְׁאָר הַשְּׁלֹשָׁה מַרְאוֹת:","כְּיַיִן הַמָּזוּג כֵּיצַד. חֵלֶק אֶחָד יַיִן מִן הַיַּיִן הַשָּׁרוֹנִי שֶׁל אֶרֶץ יִשְׂרָאֵל חַי וְחָדָשׁ וּשְׁנֵי חֲלָקִים מַיִם. הָיָה מַרְאֵה הַדָּם עָמֹק מִמֶּנּוּ אוֹ דִּיהָה מִמֶּנּוּ הֲרֵי זֶה טָהוֹר עַד שֶׁיִּהְיֶה כְּמֶזֶג זֶה בִּלְבַד. וְנֶאֱמֶנֶת אִשָּׁה לוֹמַר כְּמַרְאֶה זֶה רָאִיתִי וְאִבַּדְתִּיו וְהֶחָכָם מְטַמֵּא לָהּ אוֹ מְטַהֵר:","כֵּיצַד מַקִּיף וְרוֹאֶה. לוֹקֵחַ הַמַּטְלִית שֶׁיֵּשׁ בָּהּ הַדָּם בְּיָדוֹ וּמַבִּיט בּוֹ וּבַדְּיוֹ. אוֹ בְּעָלֶה שֶׁל כַּרְכֹּם. אוֹ בְּדַם הַקָּזָה שֶׁבַּכּוֹס. אוֹ בְּמֵימֵי אֲדָמָה. אוֹ בְּמֶזֶג שֶׁבַּכּוֹס. וְעוֹרֵךְ לָהּ כְּפִי מַה שֶּׁעֵינָיו רוֹאוֹת וּמְטַמֵּא אוֹ מְטַהֵר. וְאֵינוֹ מַבִּיט בַּזְּכוּכִית שֶׁל כּוֹס מִבַּחוּץ אֶלָּא בַּמַּשְׁקֶה שֶׁבַּכּוֹס. וְיִהְיֶה הַכּוֹס רָחָב מִשְׁקָלוֹ מָנֶה וּמַחֲזִיק שְׁנֵי לוֹגִין כְּדֵי שֶׁתִּכָּנֵס בּוֹ הָאוֹרָה וְלֹא יִהְיֶה אָפֵל:","אֵין בּוֹדְקִין הַדָּם אֶלָּא עַל גַּבֵּי מַטְלִית לְבָנָה וּבַחַמָּה. וְעוֹשֶׂה צֵל בְּיָדוֹ עַל הַדָּם וְהוּא עוֹמֵד בַּחַמָּה כְּדֵי שֶׁיִּרְאֶה עֵינוֹ כְּמוֹת שֶׁהִיא. וְלֹא כָּל הָרוֹאֶה צָרִיךְ לְכָל אֵלּוּ הַדְּבָרִים בְּכָל עֵת שֶׁיִּרְאֶה אֶלָּא טְבִיעוּת עַיִן יֵשׁ לְחָכָם בְּדָמִים. וּבְעֵת שֶׁיִּרְאֶה מִיָּד יְטַמֵּא אוֹ יְטַהֵר. וְאִם נִסְתַּפֵּק לוֹ בְּמַרְאֶה מִן הַמַּרְאוֹת צָרִיךְ לְהַקִּיף וְלַעֲרֹךְ לִדְיוֹ אוֹ לְדַם הַקָּזָה אוֹ לִשְׁאָר הַמַּרְאוֹת:","הַמַּפֶּלֶת חֲתִיכָה אַף עַל פִּי שֶׁהִיא אֲדֻמָּה אִם יֵשׁ עִמָּהּ דָּם טְמֵאָה וְאִם לָאו טְהוֹרָה וַאֲפִלּוּ נִקְרְעָה הַחֲתִיכָה וְנִמְצֵאת מְלֵאָה דָּם הֲרֵי זוֹ טְהוֹרָה שֶׁאֵין זֶה דַּם נִדָּה אֶלָּא דַּם חֲתִיכָה:","הִפִּילָה חֲתִיכָה קְרוּעָה וְדָם אָגוּר בְּתוֹכָהּ טְמֵאָה. הִפִּילָה כְּמִין קְלִפָּה כְּמִין שַׂעֲרָה כְּמִין עָפָר כְּמוֹ יַבְחוּשִׁין אִם הָיָה מַרְאֵה דְּבָרִים אֵלּוּ אָדֹם תַּטִּיל לְמַיִם פּוֹשְׁרִין. אִם נִמּוֹחוּ הֲרֵי זוֹ טְמֵאָה שֶׁדָּם הוּא וְקָפָה וְכָל הָרוֹאָה דָּם יָבֵשׁ טְמֵאָה. וְאִם שָׁהוּ בְּפוֹשְׁרִין מֵעֵת לְעֵת וְאַחַר כָּךְ נִמּוֹחוּ הֲרֵי זוֹ סָפֵק טְמֵאָה. לֹא נִמּוֹחוּ מֵעֵת לְעֵת הֲרֵי אֵלּוּ מִמַּכָּה וּטְהוֹרָה הִיא:","הִפִּילָה כְּמִין חֲגָבִים כְּמִין דָּגִים שְׁקָצִים וּרְמָשִׂים אִם יֵשׁ עִמָּהֶן דָּם טְמֵאָה וְאִם לָאו טְהוֹרָה:","הָאִשָּׁה שֶׁהִכְנִיסָה שְׁפוֹפֶרֶת בַּפְּרוֹזְדוֹר וְרָאֲתָה הַדָּם בְּתוֹךְ הַשְּׁפוֹפֶרֶת טְהוֹרָה שֶׁנֶּאֱמַר (ויקרא טו יט) \"דָּם יִהְיֶה זֹבָהּ בִּבְשָׂרָהּ\" עַד שֶׁתִּרְאֶה בִּבְשָׂרָהּ כְּדֶרֶךְ שֶׁהַנָּשִׁים רוֹאוֹת. וְאֵין דֶּרֶךְ הָאִשָּׁה לִרְאוֹת בִּשְׁפוֹפֶרֶת:","הָאִשָּׁה שֶׁהִשְׁתִּינָה מַיִם וְיָצָא דָּם עִם מֵי רַגְלַיִם. בֵּין שֶׁהִשְׁתִּינָה וְהִיא עוֹמֶדֶת בֵּין שֶׁהִשְׁתִּינָה וְהִיא יוֹשֶׁבֶת הֲרֵי זוֹ טְהוֹרָה. וַאֲפִלּוּ הִרְגִּישׁ גּוּפָהּ וְנִזְדַּעְזְעָה אֵינָהּ חוֹשֶׁשֶׁת שֶׁהַרְגָּשַׁת מֵי רַגְלַיִם הִיא זוֹ שֶׁאֵין מֵי רַגְלַיִם מִן הַחֶדֶר וְדָם זֶה דַּם מַכָּה הוּא בַּחַלְחֹלֶת אוֹ בַּכּוּלְיָא:","דַּם בְּתוּלִים טָהוֹר הוּא וְאֵינוֹ לֹא דַּם נִדָּה וְלֹא דַּם זִיבָה שֶׁאֵינוֹ מִן הַמָּקוֹר אֶלָּא כְּמוֹ דַּם חַבּוּרָה. וְכֵיצַד דִּין הַבְּתוּלָה בְּדָמִים. אִם נִשֵּׂאת קְטַנָּה בֵּין לֹא רָאֲתָה דָּם מִיָּמֶיהָ בֵּין שֶׁרָאֲתָה דָּם בְּבֵית אָבִיהָ הֲרֵי זוֹ מֻתֶּרֶת לְבַעְלָהּ עַד שֶׁתִּחְיֶה הַמַּכָּה שֶׁכָּל דָּם שֶׁתִּרְאֶה מֵחֲמַת הַמַּכָּה הוּא. וְאִם רָאֲתָה דָּם אַחַר שֶׁתִּחְיֶה הַמַּכָּה הֲרֵי זוֹ נִדָּה:","נִשֵּׂאת כְּשֶׁהִיא נַעֲרָה אִם לֹא רָאֲתָה מִיָּמֶיהָ דָּם הֲרֵי זוֹ מֻתֶּרֶת לְבַעְלָהּ אַרְבָּעָה יָמִים בַּיּוֹם וּבַלַּיְלָה אַף עַל פִּי שֶׁהַדָּם שׁוֹתֵת וְהוּא שֶׁלֹּא חָיְתָה הַמַּכָּה. וְאִם רָאֲתָה דָּם בְּבֵית אָבִיהָ וְאַחַר כָּךְ נִשֵּׂאת אֵין לוֹ לָבֹא עָלֶיהָ אֶלָּא בְּעִילָה רִאשׁוֹנָה וּפוֹרֵשׁ וְיִהְיֶה דַּם בְּתוּלִים זֶה כְּאִלּוּ הִיא תְּחִלַּת נִדָּה. וּבוֹגֶרֶת שֶׁלֹּא רָאֲתָה מִיָּמֶיהָ נוֹתְנִין לָהּ כָּל לַיְלָה הָרִאשׁוֹן:","אַרְבָּעָה לֵילוֹת שֶׁנּוֹתְנִין לְנַעֲרָה שֶׁלֹּא רָאֲתָה דָּם אַף עַל פִּי שֶׁהֵן בְּסֵרוּגִין בּוֹעֵל לַיְלָה הָרִאשׁוֹן וּמַמְתִּין אֲפִלּוּ שְׁנֵי חֳדָשִׁים אוֹ שְׁלֹשָׁה וּבוֹעֵל לַיְלָה שֵׁנִי. וְהוּא שֶׁלֹּא חָיְתָה הַמַּכָּה:","וְכֵן קְטַנָּה שֶׁנּוֹתְנִין לָהּ עַד שֶׁתִּחְיֶה הַמַּכָּה אֲפִלּוּ לֹא חָיְתָה שָׁנָה הֲרֵי זֶה בּוֹעֵל כָּל הַשָּׁנָה בֵּין בְּסֵרוּגִין בֵּין בְּיוֹם אַחַר יוֹם:","קְטַנָּה שֶׁנִּשֵּׂאת וְנַעֲשֵׂית נַעֲרָה תַּחַת בַּעְלָהּ וַעֲדַיִן הַדָּם שׁוֹתֵת מֵחֲמַת הַמַּכָּה כָּל בְּעִילוֹת שֶׁבָּעַל כְּשֶׁהִיא קְטַנָּה נֶחְשָׁבוֹת לוֹ כְּלַיְלָה אֶחָד וּמַשְׁלִימִין לוֹ כָּל אַרְבָּעָה יָמִים בִּימֵי הַנַּעֲרוּת. וַאֲפִלּוּ הָיוּ הַשְּׁלֹשָׁה יָמִים שֶׁנּוֹתְנִין לוֹ בִּימֵי הַנַּעֲרוּת בְּסֵרוּגִין וּבָעַל בְּכָל שְׁנֵי חֳדָשִׁים לַיְלָה אֶחָד הֲרֵי זֶה מֻתָּר וְהוּא שֶׁלֹּא חָיְתָה הַמַּכָּה:","כֵּיצַד יוֹדְעִין אִם חָיְתָה הַמַּכָּה אוֹ לֹא חָיְתָה. הָיְתָה רוֹאָה הַדָּם בְּעֵת שֶׁתַּעֲמֹד וּכְשֶׁתֵּשֵׁב לֹא תִּרְאֶה וּבְעֵת שֶׁתֵּשֵׁב עַל הַקַּרְקַע תִּרְאֶה וְאִם תֵּשֵׁב עַל גַּבֵּי כָּרִים וּכְסָתוֹת לֹא תִּרְאֶה עֲדַיִן לֹא חָיְתָה הַמַּכָּה. פָּסַק הַדָּם וְלֹא רָאֲתָה כְּלָל בֵּין עוֹמֶדֶת בֵּין יוֹשֶׁבֶת עַל הַכַּר כְּבָר חָיְתָה הַמַּכָּה. וְכֵן אִם לֹא פָּסַק כְּלָל אֶלָּא תִּרְאֶה הַדָּם וַאֲפִלּוּ כְּשֶׁהִיא יוֹשֶׁבֶת עַל הַכָּרִים וְהַכְּסָתוֹת אֵין זֶה דַּם מַכָּה אֶלָּא דַּם נִדָּה:","הָיְתָה רוֹאָה בְּעֵת תַּשְׁמִישׁ הֲרֵי זֶה מֵחֲמַת הַמַּכָּה. שִׁמְּשָׁה מִטָּתָהּ וְלֹא רָאֲתָה דָּם וְאַחַר כָּךְ רָאֲתָה דָּם שֶׁלֹּא מֵחֲמַת תַּשְׁמִישׁ הֲרֵי זֶה דַּם נִדָּה:","הַבּוֹעֵל בְּתוּלָה וְלֹא יָצָא מִמֶּנָּה דָּם וְחָזַר וּבְעָלָהּ וְיָצָא דָּם אֲפִלּוּ הָיְתָה קְטַנָּה הֲרֵי זֶה דַּם נִדָּה שֶׁאִלּוּ הָיָה דַּם בְּתוּלִים הָיָה בָּא בַּתְּחִלָּה. הַבּוֹעֵל פְּחוּתָה מִבַּת שָׁלֹשׁ וְיָצָא דָּם הֲרֵי זֶה דַּם בְּתוּלִים:"],"Mishneh Torah, Foreign Worship and Customs of the Nations 5":["הַמֵּסִית אֶחָד מִיִּשְׂרָאֵל בֵּין אִישׁ בֵּין אִשָּׁה הֲרֵי זֶה נִסְקָל אַף עַל פִּי שֶׁלֹּא עָבַד הַמֵּסִית וְלֹא הַמּוּסָת עֲבוֹדַת כּוֹכָבִים אֶלָּא מִפְּנֵי שֶׁהוֹרָהוּ לַעֲבֹד. בֵּין שֶׁהָיָה הַמֵּסִית הֶדְיוֹט בֵּין שֶׁהָיָה נָבִיא בֵּין שֶׁהָיָה הַמּוּסָת יָחִיד אִישׁ אוֹ אִשָּׁה אוֹ יְחִידִים מִיתָתוֹ בִּסְקִילָה:","הַמֵּסִית אֶת רֹב אַנְשֵׁי הָעִיר הֲרֵי זֶה מַדִּיחַ וְאֵינוֹ נִקְרָא מֵסִית. הָיָה זֶה שֶׁהִדִּיחַ רֹב הָעִיר נָבִיא מִיתָתוֹ בִּסְקִילָה וְהַנִּדָּחִים הֲרֵי הֵן כִּיחִידִים וְאֵינָם כְּאַנְשֵׁי עִיר הַנִּדַּחַת עַד שֶׁיִּהְיוּ הַמַּדִּיחִים שְׁנַיִם. וְאֶחָד הָאוֹמֵר אָמְרָה לִי עֲבוֹדַת כּוֹכָבִים עִבְדוּהָ. אוֹ שֶׁאָמַר אָמַר לִי הַקָּדוֹשׁ בָּרוּךְ הוּא עִבְדוּ עֲבוֹדַת כּוֹכָבִים הֲרֵי זֶה נָבִיא שֶׁהִדִּיחַ. וְאִם הֻדְּחוּ אַחֲרָיו רֹב הָעִיר נִסְקָל. הַמֵּסִית שֶׁהֵסִית בֵּין בִּלְשׁוֹן רַבִּים בֵּין בִּלְשׁוֹן יָחִיד הֲרֵי זֶה נִסְקָל. כֵּיצַד. הָאוֹמֵר לַחֲבֵרוֹ אֶעֱבֹד כּוֹכָבִים אֵלֵךְ וְאֶעֱבֹד נֵלֵךְ וְנַעֲבֹד בַּעֲבוֹדָה פְּלוֹנִית שֶׁדֶּרֶךְ אוֹתָהּ עֲבוֹדַת כּוֹכָבִים לְהֵעָבֵד בָּהּ. אֶזְבַּח אֵלֵךְ וְאֶזְבַּח נֵלֵךְ וְנִזְבַּח. אֲקַטֵּר אֵלֵךְ וַאֲקַטֵר נֵלֵךְ וּנְקַטֵּר. אֲנַסֵּךְ אֵלֵךְ וַאֲנַסֵּךְ נֵלֵךְ וּנְנַסֵּךְ. אֶשְׁתַּחֲוֶה אֵלֵךְ וְאֶשְׁתַּחֲוֶה נֵלֵךְ וְנִשְׁתַּחֲוֶה הֲרֵי זֶה מֵסִית. הֵסִית לִשְׁנַיִם הֲרֵי הֵן עֵדָיו וְהֵן מְבִיאִין אוֹתוֹ לְבֵית דִּין וּמְעִידִין עָלָיו שֶׁכָּךְ אָמַר לָהֶן וְסוֹקְלִין אוֹתוֹ:","וְאֵין הַמֵּסִית צָרִיךְ הַתְרָאָה. אָמַר לְאֶחָד הוּא אוֹמֵר יֵשׁ לִי חֲבֵרִים רוֹצִים בְּכָךְ וּמַעֲרִים עָלָיו עַד שֶׁיָּסִית בִּפְנֵי שְׁנַיִם כְּדֵי לְהָרְגוֹ. אִם לֹא רָצָה הַמֵּסִית לְהָסִית לִשְׁנַיִם מִצְוָה לְהַכְמִין לוֹ. כָּל חַיָּבֵי מִיתוֹת שֶׁבַּתּוֹרָה אֵין מַכְמִינִין עֲלֵיהֶן חוּץ מִזֶּה. כֵּיצַד מַכְמִינִין לוֹ. הַמּוּסָת מֵבִיא שְׁנַיִם וּמַעֲמִידָן בְּמָקוֹם אָפֵל כְּדֵי שֶׁיִּרְאוּ הַמֵּסִית וְיִשְׁמְעוּ דְּבָרָיו וְלֹא יִרְאֶה אוֹתָם, וְהוּא אוֹמֵר לַמֵּסִית אֱמֹר מַה שֶּׁאָמַרְתָּ לִי בְּיִחוּד, וְהוּא אוֹמֵר לוֹ, וְהַמּוּסָת מְשִׁיבוֹ הֵיאַךְ נַנִּיחַ אֶת אֱלֹהֵינוּ שֶׁבַּשָּׁמַיִם וְנֵלֵךְ וְנַעֲבֹד אֶת הָעֵצִים וְאֶת הָאֲבָנִים. אִם חָזַר בּוֹ אוֹ שָׁתַק פָּטוּר. וְאִם אָמַר לוֹ כָּךְ הִיא חוֹבָתֵנוּ וְכָךְ יָפֶה לָנוּ, הָעוֹמְדִים שָׁם בְּרָחוֹק מְבִיאִין אוֹתוֹ לְבֵית דִּין וְסוֹקְלִים אוֹתוֹ:","מִצְוָה בְּיַד הַמּוּסָת לְהָרְגוֹ שֶׁנֶּאֱמַר (דברים יג י) \"יָדְךָ תִּהְיֶה בּוֹ בָרִאשׁוֹנָה לַהֲמִיתוֹ\" וְגוֹ'. וְאָסוּר לַמּוּסָת לֶאֱהֹב אֶת הַמֵּסִית שֶׁנֶּאֱמַר (דברים יג ט) \"לֹא תֹאבֶה לוֹ\". וּלְפִי שֶׁנֶּאֱמַר בְּשׂוֹנֵא (שמות כג ה) \"עָזֹב תַּעֲזֹב עִמּוֹ\" יָכוֹל אַתָּה עוֹזֵב לָזֶה תַּלְמוּד לוֹמַר (דברים יג ט) \"וְלֹא תִשְׁמַע אֵלָיו\". וּלְפִי שֶׁנֶּאֱמַר (ויקרא יט טז) \"וְלֹא תַעֲמֹד עַל דַּם רֵעֶךָ\" יָכוֹל אִי אַתָּה עוֹמֵד עַל דָּמוֹ שֶׁל זֶה תַּלְמוּד לוֹמַר (דברים יג ט) \"וְלֹא תָחוֹס עֵינְךָ\". וְאָסוּר לַמּוּסָת לְלַמֵּד עָלָיו זְכוּת שֶׁנֶּאֱמַר (דברים יג ט) \"וְלֹא תַחְמל\". וְאִם יָדַע לוֹ חוֹבָה אֵינוֹ רַשַּׁאי לִשְׁתֹּק מִמֶּנָּה שֶׁנֶּאֱמַר (דברים יג ט) \"וְלֹא תְכַסֶּה עָלָיו\". וְאַזְהָרָה לְהֶדְיוֹט הַמֵּסִית מִנַּיִן שֶׁנֶּאֱמַר (דברים יג יב) \"וְכָל יִשְׂרָאֵל יִשְׁמְעוּ וְיִרָאוּ\":","הַמֵּסִית אֲחֵרִים לְעָבְדוֹ וְאָמַר לָהֶם עִבְדוּנִי אִם עֲבָדוּהוּ נִסְקָל וְאִם לֹא עֲבָדוּהוּ אַף עַל פִּי שֶׁקִּבְּלוּ מִמֶּנּוּ וְאָמְרוּ הֵן אֵינוֹ נִסְקָל. אֲבָל אִם הֵסִית לַעֲבוֹדַת אִישׁ אַחֵר אוֹ לִשְׁאָר מִינֵי עֲבוֹדַת כּוֹכָבִים אִם קִבֵּל מִמֶּנּוּ וְאָמַר הֵן נֵלֵךְ וְנַעֲבֹד אַף עַל פִּי שֶׁעֲדַיִן לֹא עָבַד שְׁנֵיהֶן נִסְקָלִין הַמֵּסִית וְהַמּוּסָת שֶׁנֶּאֱמַר (דברים יג ט) \"לֹא תֹאבֶה לוֹ וְלֹא תִשְׁמַע אֵלָיו\" הָא אִם שָׁמַע וְאָבָה חַיָּב:","נָבִיא הַמִּתְנַבֵּא בְּשֵׁם עֲבוֹדַת כּוֹכָבִים כֵּיצַד. זֶה הָאוֹמֵר אָמְרָה לִי עֲבוֹדַת כּוֹכָבִים פְּלוֹנִית אוֹ כּוֹכָב פְּלוֹנִי שֶׁמִּצְוָה לַעֲשׂוֹת כָּךְ וְכָךְ אוֹ שֶׁלֹּא לַעֲשׂוֹת, אֲפִלּוּ כִּוֵּן אֶת הַהֲלָכָה לְטַמֵּא אֶת הַטָּמֵא וּלְטַהֵר אֶת הַטָּהוֹר, אִם הִתְרוּ בּוֹ בִּפְנֵי שְׁנַיִם הֲרֵי זֶה נֶחְנָק שֶׁנֶּאֱמַר (דברים יח כ) \"וַאֲשֶׁר יְדַבֵּר בְּשֵׁם אֱלֹהִים אֲחֵרִים וּמֵת הַנָּבִיא הַהוּא\". וְאַזְהָרָה שֶׁלּוֹ מִכְּלָל שֶׁנֶּאֱמַר (שמות כג יג) \"וְשֵׁם אֱלֹהִים אֲחֵרִים לֹא תַזְכִּירוּ\":","וְאָסוּר לַעֲרֹךְ דִּין וּתְשׁוּבָה עִם הַמִּתְנַבֵּא בְּשֵׁם עֲבוֹדַת כּוֹכָבִים וְאֵין שׁוֹאֲלִין מִמֶּנּוּ אוֹת וּמוֹפֵת. וְאִם עָשָׂה מֵעַצְמוֹ אֵין מַשְׁגִּיחִין עָלָיו וְאֵין מְהַרְהֲרִין בּוֹ. וְכָל הַמְחַשֵּׁב בְּאוֹתוֹת שֶׁלּוֹ שֶׁמָּא אֱמֶת הֵן עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים יג ד) \"לֹא תִשְׁמַע אֶל דִּבְרֵי הַנָּבִיא הַהוּא\". וְכֵן נְבִיא הַשֶּׁקֶר מִיתָתוֹ בְּחֶנֶק אַף עַל פִּי שֶׁנִּתְנַבֵּא בְּשֵׁם ה' וְלֹא הוֹסִיף וְלֹא גָּרַע שֶׁנֶּאֱמַר (דברים יח כ) \"אַךְ הַנָּבִיא אֲשֶׁר יָזִיד לְדַבֵּר דָּבָר בִּשְׁמִי אֵת אֲשֶׁר לֹא צִוִּיתִי\" (דברים יח כ) \"וּמֵת הַנָּבִיא הַהוּא\":","אֶחָד הַמִּתְנַבֵּא מַה שֶּׁלֹּא שָׁמַע בְּמַרְאֵה הַנְּבוּאָה אוֹ מִי שֶׁשָּׁמַע דִּבְרֵי נָבִיא חֲבֵרוֹ וְאָמַר שֶׁדָּבָר זֶה לוֹ נֶאֱמַר וְהוּא נִתְנַבֵּא בּוֹ הֲרֵי זֶה נְבִיא שֶׁקֶר וּמִיתָתוֹ בְּחֶנֶק:","כָּל הַמּוֹנֵעַ עַצְמוֹ מֵהֲרִיגַת נְבִיא הַשֶּׁקֶר מִפְּנֵי מַעֲלָתוֹ שֶׁהֲרֵי הוֹלֵךְ בְּדַרְכֵי הַנְּבוּאָה הֲרֵי זֶה עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים יח כב) \"לֹא תָגוּר מִמֶּנּוּ\". וְכֵן הַמּוֹנֵעַ עַצְמוֹ מִלְּלַמֵּד עָלָיו חוֹבָה אוֹ הַפּוֹחֵד וְיָרֵא מִדְּבָרָיו הֲרֵי הוּא בִּכְלַל לֹא תָגוּר מִמֶּנּוּ. וְאֵין דָּנִין נְבִיא הַשֶּׁקֶר אֶלָּא בְּבֵית דִּין שֶׁל שִׁבְעִים וְאֶחָד:","הַנּוֹדֵר בְּשֵׁם עֲבוֹדַת כּוֹכָבִים וְהַנִּשְׁבָּע בָּהּ לוֹקֶה שֶׁנֶּאֱמַר (שמות כג יג) \"וְשֵׁם אֱלֹהִים אֲחֵרִים לֹא תַזְכִּירוּ\". אֶחָד הַנִּשְׁבָּע בָּהּ לְעַצְמוֹ וְאֶחָד הַנִּשְׁבָּע בָּהּ לְעוֹבֵד כּוֹכָבִים. וְאָסוּר לְהַשְׁבִּיעַ הָעוֹבֵד כּוֹכָבִים בְּיִרְאָתוֹ. אֲפִלּוּ לְהַזְכִּיר שֵׁם עֲבוֹדַת כּוֹכָבִים שֶׁלֹּא דֶּרֶךְ שְׁבוּעָה אָסוּר שֶׁנֶּאֱמַר לֹא תַזְכִּירוּ:","לֹא יֹאמַר אָדָם לַחֲבֵרוֹ שְׁמֹר לִי בַּצַּד עֲבוֹדַת כּוֹכָבִים פְּלוֹנִית וְכַיּוֹצֵא בָּהּ. וְכָל עֲבוֹדַת כּוֹכָבִים הַכְּתוּבָה בְּכִתְבֵי הַקֹּדֶשׁ מֻתָּר לְהַזְכִּיר שְׁמָהּ כְּגוֹן פְּעוֹר וּבֵל וּנְבוֹ וְגָד וְכַיּוֹצֵא בָּהֶן. וְאָסוּר לִגְרֹם לַאֲחֵרִים שֶׁיִּדְּרוּ וְשֶׁיְּקַיְּמוּ בְּשֵׁם עֲבוֹדַת כּוֹכָבִים. וְאֵינוֹ לוֹקֶה אֶלָּא הַנּוֹדֵר בִּשְׁמָהּ וְהַמְקַיֵּם בִּשְׁמָהּ וְהוּא הַנִּשְׁבָּע בִּשְׁמָהּ:"],"Mishneh Torah, Foundations of the Torah 7":["מִיסוֹדֵי הַדָּת לֵידַע שֶׁהָאֵל מְנַבֵּא אֶת בְּנֵי הָאָדָם. וְאֵין הַנְּבוּאָה חָלָה אֶלָּא עַל חָכָם גָּדוֹל בַּחָכְמָה, גִּבּוֹר בְּמִדּוֹתָיו, וְלֹא יְהֵא יִצְרוֹ מִתְגַּבֵּר עָלָיו בְּדָבָר בָּעוֹלָם אֶלָּא הוּא מִתְגַּבֵּר בְּדַעְתּוֹ עַל יִצְרוֹ תָּמִיד. וְהוּא בַּעַל דֵּעָה רְחָבָה נְכוֹנָה עַד מְאֹד. אָדָם שֶׁהוּא מְמֻלָּא בְּכָל הַמִּדּוֹת הָאֵלּוּ שָׁלֵם בְּגוּפוֹ, כְּשֶׁיִּכָּנֵס לַפַּרְדֵּס וְיִמָּשֵׁךְ בְּאוֹתָן הָעִנְיָנִים הַגְּדוֹלִים הָרְחוֹקִים, וְתִהְיֶה לוֹ דֵּעָה נְכוֹנָה לְהָבִין וּלְהַשִּׂיג וְהוּא מִתְקַדֵּשׁ וְהוֹלֵךְ וּפוֹרֵשׁ מִדַּרְכֵי כְּלַל הָעָם הַהוֹלְכִים בְּמַחֲשַׁכֵּי הַזְּמַן, וְהוֹלֵךְ וּמְזָרֵז עַצְמוֹ וּמְלַמֵּד נַפְשׁוֹ שֶׁלֹּא תִּהְיֶה לוֹ מַחֲשָׁבָה כְּלָל בְּאֶחָד מִדְּבָרִים בְּטֵלִים וְלֹא מֵהַבְלֵי הַזְּמַן וְתַחְבּוּלוֹתָיו, אֶלָּא דַּעְתּוֹ פְּנוּיָה תָּמִיד לְמַעְלָה קְשׁוּרָה תַּחַת הַכִּסֵּא לְהָבִין בְּאוֹתָן הַצּוּרוֹת הַקְּדוֹשׁוֹת הַטְּהוֹרוֹת, וּמִסְתַּכֵּל בְּחָכְמָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כֻּלָּהּ מִצּוּרָה רִאשׁוֹנָה עַד טַבּוּר הָאָרֶץ וְיוֹדֵעַ מֵהֶן גָּדְלוֹ, מִיָּד רוּחַ הַקֹּדֶשׁ שׁוֹרָה עָלָיו. וּבְעֵת שֶׁתָּנוּחַ עָלָיו הָרוּחַ תִּתְעָרֵב נַפְשׁוֹ בְּמַעֲלַת הַמַּלְאָכִים הַנִּקְרָאִים אִישִׁים וְיֵהָפֵךְ לְאִישׁ אַחֵר וְיָבִין בְּדַעְתּוֹ שֶׁאֵינוֹ כְּמוֹת שֶׁהָיָה אֶלָּא שֶׁנִּתְעַלָּה עַל מַעֲלַת שְׁאָר בְּנֵי אָדָם הַחֲכָמִים, כְּמוֹ שֶׁנֶּאֱמַר בְּשָׁאוּל (שמואל א י ו) \"וְהִתְנַבִּיתָ עִמָּם וְנֶהְפַּכְתָּ לְאִישׁ אַחֵר\":","הַנְּבִיאִים מַעֲלוֹת מַעֲלוֹת הֵן. כְּמוֹ שֶׁיֵּשׁ בַּחָכְמָה חָכָם גָּדוֹל מֵחֲבֵרוֹ כָּךְ בַּנְּבוּאָה נָבִיא גָּדוֹל מִנָּבִיא. וְכֻלָּן אֵין רוֹאִין מַרְאֵה הַנְּבוּאָה אֶלָּא בַּחֲלוֹם בְּחֶזְיוֹן לַיְלָה. אוֹ בַּיּוֹם אַחַר שֶׁתִּפּל עֲלֵיהֶן תַּרְדֵּמָה כְּמוֹ שֶׁנֶּאֱמַר (במדבר יב ו) \"בַּמַּרְאָה אֵלָיו אֶתְוַדָּע בַּחֲלוֹם אֲדַבֶּר בּוֹ\". וְכֻלָּן כְּשֶׁמִּתְנַבְּאִים אֵיבְרֵיהֶן מִזְדַּעְזְעִין וְכֹחַ הַגּוּף כָּשֵׁל וְעֶשְׁתּוֹנוֹתֵיהֶם מִתְטָרְפוֹת וְתִשָּׁאֵר הַדַּעַת פְּנוּיָה לְהָבִין מַה שֶּׁתִּרְאֶה. כְּמוֹ שֶׁנֶּאֱמַר בְּאַבְרָהָם (בראשית טו יב) \"וְהִנֵּה אֵימָה חֲשֵׁכָה גְדלָה נֹפֶלֶת עָלָיו\". וּכְמוֹ שֶׁנֶּאֱמַר בְּדָנִיֵּאל (דניאל י ח) \"וְהוֹדִי נֶהְפַּךְ עָלַי לְמַשְׁחִית וְלֹא עָצַרְתִּי כֹּחַ\":","הַדְּבָרִים שֶׁמּוֹדִיעִים לַנָּבִיא בְּמַרְאֵה הַנְּבוּאָה דֶּרֶךְ מָשָׁל מוֹדִיעִין לוֹ וּמִיָּד יֵחָקֵק בְּלִבּוֹ פִּתְרוֹן הַמָּשָׁל בְּמַרְאֵה הַנְּבוּאָה וְיֵדַע מָה הוּא. כְּמוֹ הַסֻּלָּם שֶׁרָאָה יַעֲקֹב אָבִינוּ וּמַלְאָכִים עוֹלִים וְיוֹרְדִים בּוֹ וְהוּא הָיָה מָשָׁל לְמַלְכֻיּוֹת וְשִׁעְבּוּדָן. וּכְמוֹ הַחַיּוֹת שֶׁרָאָה יְחֶזְקֵאל וְהַסִּיר נָפוּחַ וּמַקֵּל שָׁקֵד שֶׁרָאָה יִרְמְיָה וְהַמְּגִלָּה שֶׁרָאָה יְחֶזְקֵאל וְהָאֵיפָה שֶׁרָאָה זְכַרְיָה. וְכֵן שְׁאָר הַנְּבִיאִים. מֵהֶם אוֹמְרִים הַמָּשָׁל וּפִתְרוֹנוֹ כְּמוֹ אֵלּוּ. וְיֵשׁ שֶׁהֵן אוֹמְרִים הַפִּתְרוֹן בִּלְבַד. וּפְעָמִים אוֹמְרִים הַמָּשָׁל בִּלְבַד בְּלֹא פִּתְרוֹן כְּמִקְצָת דִּבְרֵי יְחֶזְקֵאל וּזְכַרְיָה וְכֻלָּן בְּמָשָׁל וְדֶרֶךְ חִידָה הֵם מִתְנַבְּאִים:","כָּל הַנְּבִיאִים אֵין מִתְנַבְּאִין בְּכָל עֵת שֶׁיִּרְצוּ אֶלָּא מְכַוְּנִים דַּעְתָּם וְיוֹשְׁבִים שְׂמֵחִים וְטוֹבֵי לֵב וּמִתְבּוֹדְדִים. שֶׁאֵין הַנְּבוּאָה שׁוֹרָה לֹא מִתּוֹךְ עַצְבוּת וְלֹא מִתּוֹךְ עַצְלוּת אֶלָּא מִתּוֹךְ שִׂמְחָה. לְפִיכָךְ בְּנֵי הַנְּבִיאִים לִפְנֵיהֶם נֵבֶל וְתֹף וְחָלִיל וְכִנּוֹר וְהֵם מְבַקְּשִׁים הַנְּבוּאָה. וְזֶהוּ שֶׁנֶּאֱמַר (שמואל א י ה) \"וְהֵמָּה מִתְנַבְּאִים\" כְּלוֹמַר מְהַלְּכִין בְּדֶרֶךְ הַנְּבוּאָה עַד שֶׁיִּנָּבְאוּ כְּמוֹ שֶׁאַתָּה אוֹמֵר פְּלוֹנִי מִתְגַּדֵּל:","אֵלּוּ שֶׁהֵם מְבַקְּשִׁין לְהִתְנַבֵּא הֵם הַנִּקְרָאִים בְּנֵי הַנְּבִיאִים. וְאַף עַל פִּי שֶׁמְּכַוְּנִים דַּעְתָּם אֶפְשָׁר שֶׁתִּשְׁרֶה שְׁכִינָה עֲלֵיהֶן וְאֶפְשָׁר שֶׁלֹּא תִּשְׁרֶה:","כָּל הַדְּבָרִים שֶׁאָמַרְנוּ הֵם דֶּרֶךְ נְבוּאָה לְכָל הַנְּבִיאִים הָרִאשׁוֹנִים וְהָאַחֲרוֹנִים חוּץ מִמּשֶׁה רַבֵּנוּ רַבָּן שֶׁל כָּל הַנְּבִיאִים. וּמַה הֶפְרֵשׁ יֵשׁ בֵּין נְבוּאַת משֶׁה לִשְׁאָר כָּל הַנְּבִיאִים. שֶׁכָּל הַנְּבִיאִים בַּחֲלוֹם אוֹ בְּמַרְאֶה וּמשֶׁה רַבֵּנוּ מִתְנַבֵּא וְהוּא עֵר וְעוֹמֵד שֶׁנֶּאֱמַר (במדבר ז פט) \"וּבְבֹא משֶׁה אֶל אֹהֶל מוֹעֵד לְדַבֵּר אִתּוֹ וַיִּשְׁמַע אֶת הַקּוֹל מִדַּבֵּר אֵלָיו\". כָּל הַנְּבִיאִים עַל יְדֵי מַלְאָךְ. לְפִיכָךְ רוֹאִים מַה שֶּׁהֵם רוֹאִים בְּמָשָׁל וְחִידָה. משֶׁה רַבֵּנוּ לֹא עַל יְדֵי מַלְאָךְ שֶׁנֶּאֱמַר (במדבר יב ח) \"פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ\". וְנֶאֱמַר (שמות לג יא) \"וְדִבֶּר ה' אֶל משֶׁה פָּנִים אֶל פָּנִים\". וְנֶאֱמַר (במדבר יב ח) \"וּתְמֻנַת ה' יַבִּיט\" כְּלוֹמַר שֶׁאֵין שָׁם מָשָׁל אֶלָּא רוֹאֶה הַדָּבָר עַל בֻּרְיוֹ בְּלֹא חִידָה וּבְלֹא מָשָׁל. הוּא שֶׁהַתּוֹרָה מְעִידָה עָלָיו (במדבר יב ח) \"בְּמַרְאֶה וְלֹא בְּחִידוֹת\" שֶׁאֵינוֹ מִתְנַבֵּא בְּחִידָה אֶלָּא בְּמַרְאֶה שֶׁרוֹאֶה הַדָּבָר עַל בֻּרְיוֹ. כָּל הַנְּבִיאִים יְרֵאִים וְנִבְהָלִים וּמִתְמוֹגְגִין וּמשֶׁה רַבֵּנוּ אֵינוֹ כֵן הוּא, שֶׁהַכָּתוּב אוֹמֵר (שמות לג יא) \"כַּאֲשֶׁר יְדַבֵּר אִישׁ אֶל רֵעֵהוּ\", כְּלוֹמַר כְּמוֹ שֶׁאֵין אָדָם נִבְהָל לִשְׁמֹעַ דִּבְרֵי חֲבֵרוֹ כָּךְ הָיָה כֹּחַ בְּדַעְתּוֹ שֶׁל משֶׁה רַבֵּנוּ לְהָבִין דִּבְרֵי הַנְּבוּאָה וְהוּא עוֹמֵד עַל עָמְדוֹ שָׁלֵם. כָּל הַנְּבִיאִים אֵין מִתְנַבְּאִים בְּכָל עֵת שֶׁיִּרְצוּ. משֶׁה רַבֵּנוּ אֵינוֹ כֵן אֶלָּא כָּל זְמַן שֶׁיַּחְפֹּץ רוּחַ הַקֹּדֶשׁ לוֹבַשְׁתּוֹ וּנְבוּאָה שׁוֹרָה עָלָיו וְאֵינוֹ צָרִיךְ לְכַוֵּן דַּעְתּוֹ וּלְהִזְדַּמֵּן לָהּ שֶׁהֲרֵי הוּא מְכֻוָּן וּמְזֻמָּן וְעוֹמֵד כְּמַלְאֲכֵי הַשָּׁרֵת. לְפִיכָךְ מִתְנַבֵּא בְּכָל עֵת שֶׁנֶּאֱמַר (במדבר ט ח) \"עִמְדוּ וְאֶשְׁמְעָה מַה יְצַוֶּה ה' לָכֶם\". וּבָזֶה הִבְטִיחוֹ הָאֵל שֶׁנֶּאֱמַר (גמרא יבמות סב א) \"לֵךְ אֱמֹר לָהֶם שׁוּבוּ לָכֶם לְאָהֳלֵיכֶם וְאַתָּה פֹּה עֲמֹד עִמָּדִי\". הָא לָמַדְתָּ שֶׁכָּל הַנְּבִיאִים כְּשֶׁהַנְּבוּאָה מִסְתַּלֶּקֶת מֵהֶם חוֹזְרִים לְאָהֳלָם שֶׁהוּא צָרְכֵי הַגּוּף כֻּלָּם כִּשְׁאָר הָעָם. לְפִיכָךְ אֵין פּוֹרְשִׁין מִנְּשׁוֹתֵיהֶם. וּמשֶׁה רַבֵּנוּ לֹא חָזַר לְאָהֳלוֹ הָרִאשׁוֹן לְפִיכָךְ פֵּרַשׁ מִן הָאִשָּׁה לְעוֹלָם וּמִן הַדּוֹמֶה לוֹ וְנִקְשְׁרָה דַּעְתּוֹ לְצוּר הָעוֹלָמִים וְלֹא נִסְתַּלֵּק מֵעָלָיו הַהוֹד לְעוֹלָם וְקָרַן עוֹר פָּנָיו וְנִתְקַדֵּשׁ כְּמַלְאָכִים:","הַנָּבִיא אֶפְשָׁר שֶׁתִּהְיֶה נְבוּאָתוֹ לְעַצְמוֹ בִּלְבַד לְהַרְחִיב לִבּוֹ וּלְהוֹסִיף דַּעְתּוֹ עַד שֶׁיֵּדַע מַה שֶּׁלֹּא הָיָה יוֹדֵעַ מֵאוֹתָן הַדְּבָרִים הַגְּדוֹלִים. וְאֶפְשָׁר שֶׁיְּשֻׁלַּח לְעַם מֵעַמֵּי הָאָרֶץ אוֹ לְאַנְשֵׁי עִיר אוֹ מַמְלָכָה לְכוֹנֵן אוֹתָם וּלְהוֹדִיעָם מַה יַּעֲשׂוּ אוֹ לְמָנְעָם מִמַּעֲשִׂים הָרָעִים שֶׁבִּידֵיהֶם. וּכְשֶׁמְּשַׁלְּחִים אוֹתוֹ נוֹתְנִין לוֹ אוֹת וּמוֹפֵת כְּדֵי שֶׁיֵּדְעוּ הָעָם שֶׁהָאֵל שְׁלָחוֹ בֶּאֱמֶת. וְלֹא כָּל הָעוֹשֶׂה אוֹת וּמוֹפֵת מַאֲמִינִים לוֹ שֶׁהוּא נָבִיא. אֶלָּא אָדָם שֶׁהָיִינוּ יוֹדְעִים בּוֹ מִתְּחִלָּתוֹ שֶׁהוּא רָאוּי לִנְבוּאָה בְּחָכְמָתוֹ וּבְמַעֲשָׂיו שֶׁנִּתְעַלָּה בָּהֶן עַל כָּל בְּנֵי גִּילוֹ וְהָיָה מְהַלֵּךְ בְּדַרְכֵי הַנְּבוּאָה בִּקְדֻשָּׁתָהּ וּבִפְרִישׁוּתָהּ וְאַחַר כָּךְ בָּא וְעָשָׂה אוֹת וּמוֹפֵת וְאָמַר שֶׁהָאֵל שְׁלָחוֹ מִצְוָה לִשְׁמֹעַ מִמֶּנּוּ שֶׁנֶּאֱמַר (דברים יח טו) \"אֵלָיו תִּשְׁמָעוּן\". וְאֶפְשָׁר שֶׁיַּעֲשֶׂה אוֹת וּמוֹפֵת וְאֵינוֹ נָבִיא. וְזֶה הָאוֹת יֵשׁ לוֹ דְּבָרִים בְּגוֹ. וְאַף עַל פִּי כֵן מִצְוָה לִשְׁמוֹעַ לוֹ הוֹאִיל וְאָדָם גָּדוֹל וְחָכָם וְרָאוּי לִנְבוּאָה [הוּא] מַעֲמִידִים אוֹתוֹ עַל חֶזְקָתוֹ. שֶׁבְּכָךְ נִצְטַוֵּינוּ כְּמוֹ שֶׁנִּצְטַוֵּינוּ לַחְתֹּךְ אֶת הַדִּין עַל פִּי שְׁנֵי עֵדִים כְּשֵׁרִים וְאַף עַל פִּי שֶׁאֶפְשָׁר שֶׁהֵעִידוּ בְּשֶׁקֶר הוֹאִיל וּכְשֵׁרִים הֵם אֶצְלֵנוּ מַעֲמִידִין אוֹתָן עַל כַּשְׁרוּתָן. וּבַדְּבָרִים הָאֵלּוּ וְכַיּוֹצֵא בָּהֶן נֶאֱמַר (דברים כט כח) \"הַנִּסְתָּרֹת לַה' אֱלֹהֵינוּ וְהַנִּגְלֹת לָנוּ וּלְבָנֵינוּ\". וְנֶאֱמַר (שמואל א טז ז) \"כִּי הָאָדָם יִרְאֶה לַעֵינַיִם וַה' יִרְאֶה לַלֵּבָב\":"],"Mishneh Torah, Gifts to the Poor 6":["מַתָּנָּה אַחֶרֶת שִׁשִּׁית יֵשׁ לָעֲנִיִּים בְּזֶרַע הָאָרֶץ וְהוּא הַמַּעֲשֵׂר שֶׁנּוֹתְנִין לָעֲנִיִּים וְהוּא הַנִּקְרָא מַעֲשַׂר עָנִי:","וְזֶהוּ סֵדֶר תְּרוּמוֹת וּמַעַשְׂרוֹת. אַחַר שֶׁקּוֹצֵר זֶרַע הָאָרֶץ אוֹ אוֹסֵף פְּרִי הָעֵץ וְתִגָּמֵר מְלַאכְתּוֹ מַפְרִישׁ מִמֶּנּוּ אֶחָד מִן הַחֲמִשִּׁים. וְזֶהוּ הַנִּקְרָא תְּרוּמָה גְּדוֹלָה וְנוֹתְנָהּ לַכֹּהֵן. וְעַל זֶה נֶאֱמַר בַּתּוֹרָה (דברים יח ד) \"רֵאשִׁית דְּגָנְךָ תִּירשְׁךָ וְיִצְהָרֶךָ\". וְאַחַר כָּךְ מַפְרִישׁ מִן הַשְּׁאָר אֶחָד מֵעֲשָׂרָה. וְזֶהוּ הַנִּקְרָא מַעֲשֵׂר רִאשׁוֹן. וְנוֹתְנוֹ לַלֵּוִי. וְעַל זֶה נֶאֱמַר בַּתּוֹרָה (במדבר יח כד) \"כִּי אֶת מַעְשַׂר בְּנֵי יִשְׂרָאֵל\" וְגוֹ' וְנֶאֱמַר (במדבר יח כא) \"וְלִבְנֵי לֵוִי הִנֵּה נָתַתִּי אֶת כָּל מַעֲשֵׂר בְּיִשְׂרָאֵל\":","וְאַחַר כָּךְ מַפְרִישׁ מִן הַשְּׁאָר אֶחָד מֵעֲשָׂרָה וְהוּא הַנִּקְרָא מַעֲשֵׂר שֵׁנִי. וְהוּא לִבְעָלָיו וְאוֹכְלִין אוֹתוֹ בִּירוּשָׁלַיִם. וְעָלָיו נֶאֱמַר (ויקרא כז לא) \"וְאִם גָּאל יִגְאַל אִישׁ מִמַּעַשְׂרוֹ\". וְעָלָיו נֶאֱמַר (דברים יד כב) \"עַשֵּׂר תְּעַשֵּׂר\" (דברים יד כג) \"וְאָכַלְתָּ לִפְנֵי ה' אֱלֹהֶיךָ בַּמָּקוֹם אֲשֶׁר יִבְחַר\":","עַל הַסֵּדֶר הַזֶּה מַפְרִישִׁין בְּשָׁנָה רִאשׁוֹנָה מִן הַשָּׁבוּעַ וּבַשְּׁנִיָּה וּבָרְבִיעִית וּבַחֲמִישִׁית. אֲבָל בַּשְּׁלִישִׁית וּבַשִּׁשִּׁית מִן הַשָּׁבוּעַ אַחַר שֶׁמַּפְרִישִׁים מַעֲשֵׂר רִאשׁוֹן מַפְרִישׁ מִן הַשְּׁאָר מַעֲשֵׂר אַחֵר וְנוֹתְנוֹ לָעֲנִיִּים וְהוּא הַנִּקְרָא מַעֲשַׂר עָנִי. וְאֵין בִּשְׁתֵּי שָׁנִים אֵלּוּ מַעֲשֵׂר שֵׁנִי אֶלָּא מַעֲשַׂר עָנִי. וְעָלָיו נֶאֱמַר (דברים יד כח) \"מִקְצֵה שָׁלֹשׁ שָׁנִים תּוֹצִיא אֶת כָּל מַעְשַׂר תְּבוּאָתְךָ בַּשָּׁנָה הַהִיא וְהִנַּחְתָּ בִּשְׁעָרֶיךָ\" (דברים יד כט) \"וּבָא הַלֵּוִי\". וְעָלָיו נֶאֱמַר (דברים כו יב) \"כִּי תְכַלֶּה לַעְשֵׂר\":","שְׁנַת הַשְּׁמִטָּה כֻּלָּהּ הֶפְקֵר וְאֵין בָּהּ לֹא תְּרוּמָה וְלֹא מַעַשְׂרוֹת כְּלָל לֹא רִאשׁוֹן וְלֹא שֵׁנִי וְלֹא מַעֲשַׂר עָנִי. וּבְחוּצָה לָאָרֶץ שֶׁאֵין בָּהּ שְׁמִטַּת קַרְקַע מַפְרִישִׁין בְּאֶרֶץ מִצְרַיִם וּבְעַמּוֹן וּבְמוֹאָב מַעֲשֵׂר רִאשׁוֹן וּמַעֲשַׂר עָנִי. מִפְּנֵי שֶׁהָאֲרָצוֹת אֵלּוּ קְרוֹבוֹת לְאֶרֶץ יִשְׂרָאֵל כְּדֵי שֶׁיְּהְיוּ עֲנִיֵּי יִשְׂרָאֵל נִסְמָכִין עָלֶיהָ בַּשְּׁבִיעִית. וַהֲלָכָה לְמשֶׁה מִסִּינַי שֶׁיִּהְיוּ מַפְרִישִׁים בְּאֶרֶץ עַמּוֹן וּמוֹאָב מַעֲשַׂר עָנִי בַּשְּׁבִיעִית. אֲבָל בְּאֶרֶץ שִׁנְעָר מַפְרִישִׁין בַּשְּׁבִיעִית מַעֲשֵׂר שֵׁנִי כְּסֵדֶר רֹב הַשָּׁנִים:","מַעֲשֵׂר רִאשׁוֹן שֶׁלָּקַח הַלֵּוִי מַפְרִישׁ מִמֶּנּוּ אֶחָד מֵעֲשָׂרָה וְנוֹתְנוֹ לַכֹּהֵן וְהוּא הַנִּקְרָא תְּרוּמַת מַעֲשֵׂר. וְעָלָיו נֶאֱמַר (במדבר יח כו) \"וְאֶל הַלְוִיִּם תְּדַבֵּר\":","בַּעַל הַשָּׂדֶה שֶׁעָבְרוּ עָלָיו עֲנִיִּים וְהָיָה לוֹ שָׁם מַעֲשַׂר עָנִי. נוֹתֵן לְכָל עָנִי שֶׁיַּעֲבֹר עָלָיו מִן הַמַּעֲשֵׂר כְּדֵי שָׂבְעוֹ שֶׁנֶּאֱמַר (דברים כו יב) \"וְאָכְלוּ בִשְׁעָרֶיךָ וְשָׂבֵעוּ\":","כְּדֵי שָׂבְעוֹ כַּמָּה. אִם מִן הַחִטִּים נוֹתֵן לֹא יִפְחֹת מֵחֲצִי קַב. וְאִם מִן הַשְּׂעוֹרִים לֹא יִפְחֹת מִקַּב. וְאִם מִן הַכֻּסְּמִין לֹא יִפְחֹת מִקַּב. וּמִן הַגְּרוֹגָרוֹת לֹא יִפְחֹת מִקַּב. וְאִם מִן הַדְּבֵלָה לֹא יִפְחֹת מִמִּשְׁקַל חָמֵשׁ וְעֶשְׂרִים סֶלַע. וְאִם מִן הַיַּיִן לֹא יִפְחֹת מֵחֲצִי לֹג. וְאִם מִן הַשֶּׁמֶן לֹא יִפְחֹת מֵרְבִיעִית. וְאִם מִן הָאֹרֶז רֹבַע הַקַּב. נָתַן לוֹ יָרָק נוֹתֵן לוֹ מִשְׁקַל לִיטְרָא וְהוּא מִשְׁקַל חֲמִשָּׁה וּשְׁלֹשִׁים דִּינָר. מִן הֶחָרוּבִין שְׁלֹשָׁה קַבִּין. מִן הָאֱגוֹזִים עֲשָׂרָה. מִן הָאֲפַרְסְקִין חֲמִשָּׁה. מִן הָרִמּוֹנִים שְׁנַיִם. אֶתְרוֹג אֶחָד. וְאִם נָתַן לוֹ מִשְּׁאָר הַפֵּרוֹת לֹא יִפְחֹת מִכְּדֵי שֶׁיִּמְכְּרֵם וְיִקַּח בִּדְמֵיהֶן מְזוֹן שְׁתֵּי סְעֻדּוֹת:","הָיָה לוֹ דָּבָר מֻעָט וְהָעֲנִיִּים מְרֻבִּין וְאֵין בּוֹ כְּדֵי לִתֵּן לְכָל אֶחָד וְאֶחָד כַּשִּׁעוּר נוֹתֵן לִפְנֵיהֶם וְהֵן מְחַלְּקִין בֵּינֵיהֶם:","וּמַעֲשַׂר עָנִי הַמִּתְחַלֵּק בַּגֹּרֶן אֵין בּוֹ טוֹבַת הֲנָאָה לַבְּעָלִים אֶלָּא הָעֲנִיִּים בָּאִים וְנוֹטְלִין עַל כָּרְחוֹ וַאֲפִלּוּ עָנִי שֶׁבְּיִשְׂרָאֵל מוֹצִיאִין אוֹתוֹ מִיָּדוֹ. אֲבָל הַמִּתְחַלֵּק בַּבַּיִת יֵשׁ לוֹ טוֹבַת הֲנָאָה לַבְּעָלִים וְנוֹתְנוֹ לְכָל עָנִי שֶׁיִּרְצֶה:","הָיָה לוֹ מַעֲשֵׂר בַּגֹּרֶן וְרָצָה לִתְּנוֹ לְעָנִי קְרוֹבוֹ אוֹ מְיֻדָּעוֹ. יֵשׁ לְהַפְרִישׁ מֶחֱצָה לִתְּנוֹ לוֹ. וְהַחֵצִי מְחַלְּקוֹ לְכָל עָנִי שֶׁיַּעֲבֹר כַּשִּׁעוּר שֶׁאָמַרְנוּ:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאֵינוֹ נוֹתֵן לֶעָנִי אֶלָּא כְּדֵי שָׂבְעוֹ בַּשָּׂדֶה. אֲבָל אִם הָיָה הַמַּעֲשֵׂר בַּבַּיִת מְחַלְּקוֹ לְכָל הָעֲנִיִּים אֲפִלּוּ כְּזַיִת כְּזַיִת. שֶׁאֵינוֹ מְצֻוֶּה לִתֵּן כְּדֵי שָׂבְעוֹ אֶלָּא בַּשָּׂדֶה. שֶׁהֲרֵי אֵינוֹ מוֹצֵא שָׁם לִקַּח שֶׁנֶּאֱמַר (דברים כו יב) \"וְאָכְלוּ בִשְׁעָרֶיךָ וְשָׂבֵעוּ\":","בָּאוּ אִישׁ וְאִשָּׁה לַבַּיִת. נוֹתְנִין לָאִשָּׁה תְּחִלָּה וּפוֹטְרִין אוֹתָהּ וְאַחַר כָּךְ נוֹתְנִין לָאִישׁ. אָב וּבְנוֹ. אִישׁ וּקְרוֹבוֹ. שְׁנֵי אַחִין. שְׁנֵי שֻׁתָּפִין. שֶׁהָיָה אֶחָד מֵהֶן עָנִי. נוֹתֵן לוֹ הָאַחֵר מַעֲשַׂר עָנִי שֶׁלּוֹ:","שְׁתֵּי עֲנִיִּים שֶׁקִּבְּלוּ שָׂדֶה בַּאֲרִיסוּת. זֶה מַפְרִישׁ מַעֲשַׂר עָנִי מֵחֶלְקוֹ וְנוֹתְנוֹ לַחֲבֵרוֹ. וְכֵן חֲבֵרוֹ מַפְרִישׁ מֵחֶלְקוֹ וְנוֹתֵן לוֹ:","הַמְקַבֵּל שָׂדֶה לִקְצֹר אָסוּר בְּלֶקֶט שִׁכְחָה וּפֵאָה וּמַעֲשַׂר עָנִי. אֵימָתַי בִּזְמַן שֶׁקִּבְּלָהּ מִמֶּנּוּ לִקַּח חֵלֶק בְּכָל הַשָּׂדֶה כְּגוֹן שֶׁנָּתַן לוֹ שְׁלִישָׁהּ אוֹ רְבִיעָהּ בִּשְׂכָרוֹ. אֲבָל אִם אָמַר לוֹ בַּעַל הַשָּׂדֶה שְׁלִישׁ מַה שֶּׁאַתָּה קוֹצֵר בִּלְבַד הוּא שֶׁלְּךָ אוֹ רְבִיעַ מַה שֶּׁתִּקְצֹר הֲרֵי זֶה אֵין לוֹ כְּלוּם עַד שֶׁיִּקְצֹר. וּבִשְׁעַת הַקָּצִיר הוּא עָנִי. לְפִיכָךְ מֻתָּר בְּלֶקֶט שִׁכְחָה וּפֵאָה. וְאָסוּר בְּמַעֲשַׂר עָנִי שֶׁאֵין מַפְרִישִׁין מַעֲשַׂר עָנִי אֶלָּא אַחַר שֶׁקָּצַר וַהֲרֵי זָכָה בְּחֶלְקוֹ שֶׁקָּצַר:","הַמּוֹכֵר אֶת שָׂדֵהוּ קַרְקַע וּפֵרוֹת וְהֶעֱנִי. הֲרֵי זֶה מֻתָּר בְּלֶקֶט שִׁכְחָה וּפֵאָה וּמַעֲשַׂר עָנִי שֶׁלָּהּ. וְהַלּוֹקֵחַ אָסוּר בָּהֶן אַף עַל פִּי שֶׁעֲדַיִן לֹא נָתַן דָּמִים. וַאֲפִלּוּ לָוָה הַדָּמִים וּלְקָחָהּ הֲרֵי זֶה אָסוּר בְּמַתְּנוֹת עֲנִיִּים:","מַעֲשַׂר עָנִי אֵין פּוֹרְעִין מִמֶּנּוּ מִלְוֶה. וְאֵין מְשַׁלְּמִין מִמֶּנּוּ אֶת הַתַּגְמוּלִין. אֲבָל מְשַׁלְּמִין מִמֶּנּוּ דָּבָר שֶׁל גְּמִילוּת חֲסָדִים וְצָרִיךְ לְהוֹדִיעוֹ שֶׁהוּא מַעֲשַׂר עָנִי. וְאֵין פּוֹדִין בּוֹ שְׁבוּיִים. וְאֵין עוֹשִׂין בּוֹ שׁוֹשְׁבִינוּת. וְאֵין נוֹתְנִין מִמֶּנּוּ דָּבָר לִצְדָקָה. וְנוֹתְנִין אוֹתוֹ לַחֲבֵר עִיר בְּטוֹבַת הֲנָאָה. וְאֵין מוֹצִיאִין אוֹתוֹ מֵהָאָרֶץ לְחוּץ לָאָרֶץ שֶׁנֶּאֱמַר (דברים יד כח) \"וְהִנַּחְתָּ בִּשְׁעָרֶיךָ\" וְנֶאֱמַר (דברים כו יב) \"וְאָכְלוּ בִשְׁעָרֶיךָ וְשָׂבֵעוּ\":"],"Mishneh Torah, Heave Offerings 3":["תְּרוּמָה גְּדוֹלָה אֵין לָהּ שִׁעוּר מִן הַתּוֹרָה. שֶׁנֶּאֱמַר (דברים יח ד) \"רֵאשִׁית דְּגָנְךָ\" כָּל שֶׁהוּא אֲפִלּוּ חִטָּה אַחַת פּוֹטֶרֶת הַכְּרִי. וּלְכַתְּחִלָּה לֹא יַפְרִישׁ אֶלָּא כַּשִּׁעוּר שֶׁנָּתְנוּ חֲכָמִים. וּבַזְּמַן הַזֶּה שֶׁהִיא עוֹמֶדֶת לִשְׂרֵפָה מִפְּנֵי הַטֻּמְאָה יֵשׁ לוֹ לְהַפְרִישׁ כָּל שֶׁהוּא לְכַתְּחִלָּה:","וְכַמָּה הוּא שִׁעוּרָהּ שֶׁנָּתְנוּ חֲכָמִים. עַיִן יָפָה אֶחָד מֵאַרְבָּעִים. וְהַבֵּינוֹנִית אֶחָד מֵחֲמִשִּׁים. רָעָה אֶחָד מִשִּׁשִּׁים. וְלֹא יִפְחֹת מֵאֶחָד מִשִּׁשִּׁים:","כָּל תְּרוּמָה שֶׁאֵין הַכֹּהֲנִים מַקְפִּידִין עָלֶיהָ כְּגוֹן תְּרוּמוֹת הֶחָרוּבִין וְהַקְּלִיסִין נִטֶּלֶת לְכַתְּחִלָּה אֶחָד מִשִּׁשִּׁים. וְאֵלּוּ נִטָּלִין אֶחָד מִשִּׁשִּׁים. תְּרוּמַת גִּדּוּלֵי תְּרוּמָה וְעֵרוּבֵי תְּרוּמָה וּתְרוּמָה טְמֵאָה שֶׁהָיְתָה הַטֻּמְאָה בְּאֹנֶס אוֹ בִּשְׁגָגָה וּתְרוּמַת הֶקְדֵּשׁ וּתְרוּמַת חוּצָה לָאָרֶץ וּתְרוּמַת הַקֶּצַח וְהַקְּלִיסִין וְהֶחָרוּבִין וְהַגִּמְזִיּוֹת וְהַתֻּרְמוֹסִין וּשְׂעוֹרִים אֲדוֹמִיּוֹת וְכַיּוֹצֵא בָּהֵן וּפֵרוֹת עָצִיץ שֶׁאֵינוֹ נָקוּב. וְכֵן הָאַפּוֹטְרוֹפְּסִין כְּשֶׁתּוֹרְמִין פֵּרוֹת יְתוֹמִים תּוֹרְמִין אֶחָד מִשִּׁשִּׁים:","אֵין תּוֹרְמִין תְּרוּמָה זוֹ לֹא בְּמִדָּה וְלֹא בְּמִשְׁקָל וְלֹא בְּמִנְיָן לְפִי שֶׁלֹּא נֶאֱמַר בָּהּ שִׁעוּר אֶלָּא אֹמֶד וּמַפְרִישׁ בְּדַעְתּוֹ כְּמוֹ אֶחָד (מִשִּׁשִּׁים) [מֵחֲמִשִּׁים]. אֲבָל תּוֹרֵם הוּא אֶת הַמָּדוּד וְאֶת הַשָּׁקוּל וְאֶת הַמָּנוּי. וְלֹא יִתְרֹם בְּסַל וּבְקֻפָּה שֶׁמִּדָּתָן יְדוּעָה. אֲבָל תּוֹרֵם הוּא בָּהֶן חֶצְיָן אוֹ שְׁלִישָׁן. וְלֹא יִתְרֹם בִּסְאָה חֶצְיָהּ שֶׁהַחֶצְיָהּ מִדָּה:","הַמַּרְבֶּה בִּתְרוּמָה הוֹאִיל וְשִׁיֵּר מִקְצָת חֻלִּין הֲרֵי זוֹ תְּרוּמָה. אֲבָל אִם אָמַר כָּל הַפֵּרוֹת הָאֵלּוּ תְּרוּמָה לֹא אָמַר כְּלוּם. הַמִּתְכַּוֵּן לִתְרֹם אֶחָד מֵעֲשָׂרָה וְעָלְתָה בְּיָדוֹ אֶחָד מִשִּׁשִּׁים תְּרוּמָתוֹ תְּרוּמָה. נִתְכַּוֵּן לִתְרֹם אֶחָד מִשִּׁשִּׁים וְעָלְתָה בְּיָדוֹ אֶחָד מֵחֲמִשִּׁים אֵינוֹ תְּרוּמָה:","הַמַּפְרִישׁ תְּרוּמָה וְעָלְתָה בְּיָדוֹ אֲפִלּוּ אֶחָד מֵעֶשְׂרִים תְּרוּמָתוֹ תְּרוּמָה. תָּרַם וְעָלְתָה בְּיָדוֹ אֶחָד מִשִּׁשִּׁים וְחָזַר וְהוֹסִיף לְשֵׁם תְּרוּמָה אוֹתָהּ הַתּוֹסֶפֶת חַיֶּבֶת בְּמַעַשְׂרוֹת וּמַפְרִישׁ מִמֶּנָּה הַכֹּהֵן הַמַּעַשְׂרוֹת וְאַחַר כָּךְ יֹאכְלֶנָּה. תָּרַם וְעָלְתָה בְּיָדוֹ אֶחָד מִשִּׁשִּׁים וְאֶחָד הֲרֵי זוֹ תְּרוּמָה וְיַחֲזֹר וְיִתְרֹם פַּעַם שְׁנִיָּה כְּדֵי לְהַשְׁלִים הַשִּׁעוּר שֶׁבְּדַעְתּוֹ. וְהַתּוֹסֶפֶת הַזֹּאת יֵשׁ לוֹ לְהַפְרִישָׁהּ בְּמִדָּה אוֹ בְּמִשְׁקָל אוֹ בְּמִנְיָן אֲבָל לֹא יַפְרִישֶׁנָּה אֶלָּא מִן הַמֻּקָּף כָּרִאשׁוֹנָה:","הַמַּפְרִישׁ מִקְצָת הַתְּרוּמָה אוֹתוֹ הַמִּקְצָת אֵינוֹ תְּרוּמָה וַהֲרֵי הוּא כְּחוֹלֵק הַכְּרִי. וְאַף עַל פִּי כֵן צָרִיךְ לְהַפְרִישׁ תְּרוּמַת אוֹתוֹ מִקְצָת מִמֶּנּוּ. וְלֹא יַפְרִישׁ עָלָיו מִפֵּרוֹת אֲחֵרוֹת:","הַמַּפְרִישׁ מִקְצָת תְּרוּמָה מִכְּרִי זֶה וּמִקְצָת תְּרוּמָה מִכְּרִי אַחֵר מִמִּינוֹ. הֲרֵי זֶה לֹא יִתְרֹם מִזֶּה עַל זֶה. האוֹמֵר תְּרוּמַת הַכְּרִי זֶה לְתוֹכוֹ אִם אָמַר בִּצְפוֹנוֹ אוֹ בִּדְרוֹמוֹ קָרָא שֵׁם וְחַיָּב לְהַפְרִישׁ מִמֶּנּוּ תְּרוּמָתוֹ וְאִם לֹא צִיֵּן בְּמָקוֹם לֹא אָמַר כְּלוּם:","אָמַר תְּרוּמַת הַכְּרִי זֶה וְהַכְּרִי הַזֶּה כָּזֶה מָקוֹם שֶׁנִּסְתַּיְּמָה תְּרוּמָתוֹ שֶׁל רִאשׁוֹן שָׁם נִסְתַיְּמָה תְּרוּמָתוֹ שֶׁל שֵׁנִי:","תְּרוּמַת מַעֲשֵׂר אֵין מַפְרִישִׁין אוֹתָהּ בְּאֹמֶד. אֶלָּא מְדַקְדֵּק בְּשִׁעוּרָהּ וַאֲפִלּוּ בַּזְּמַן הַזֶּה. שֶׁהֲרֵי שִׁעוּרָהּ מְפֹרָשׁ בַּתּוֹרָה:","דָּבָר שֶׁדַּרְכּוֹ לִמְדֹּד מוֹדֵד. וְדָבָר הַנִּשְׁקָל שׁוֹקֵל. דָּבָר שֶׁאֶפְשָׁר לִמְנוֹתוֹ מוֹנֶה. הָיָה אֶפְשָׁר לִמְנוֹתוֹ וּלְשָׁקְלוֹ וּלְמָדְדוֹ הַמּוֹנֶה מְשֻׁבָּח וְהַמּוֹדֵד מְשֻׁבָּח מִמֶּנּוּ וְהַשּׁוֹקֵל מְשֻׁבָּח מִשְּׁנֵיהֶן:","מִצְוַת תְּרוּמַת מַעֲשֵׂר שֶׁיַּפְרִישׁ אוֹתָן בֶּן לֵוִי מִמַּעַשְׂרוֹ. שֶׁנֶּאֱמַר (במדבר יח כו) \"וְכִי תִקְחוּ מֵאֵת בְּנֵי יִשְׂרָאֵל אֶת הַמַּעֲשֵׂר\". וְיֵשׁ לְיִשְׂרָאֵל לְהַפְרִישׁ אוֹתָהּ וְלִתְּנָהּ לַכֹּהֵן. וְיִתֵּן הַמַּעֲשֵׂר לַלֵּוִי אַחַר שֶׁיַּפְרִישׁ מִמֶּנּוּ תְּרוּמָתוֹ שֶׁהִיא מַעֲשֵׂר מִן הַמַּעֲשֵׂר:","יִשְׂרָאֵל שֶׁהִפְרִישׁ מַעֲשֵׂר רִאשׁוֹן כְּשֶׁהוּא שִׁבֳּלִים קֹדֶם שֶׁיָּדוּשׁ וְיַפְרִישׁ תְּרוּמָה גְּדוֹלָה וּנְתָנוֹ לְלֵוִי. אֵין הַלֵּוִי חַיָּב לְהַפְרִישׁ מִמֶּנּוּ תְּרוּמָה גְּדוֹלָה אַחַר שֶׁיְּדוּשֶׁנּוּ אֶלָּא תְּרוּמַת מַעֲשֵׂר בִּלְבַד. אֲבָל אִם דַּשׁ יִשְׂרָאֵל וְהִפְרִישׁ הַמַּעֲשֵׂר מִן הַדָּגָן קֹדֶם שֶׁיַּפְרִישׁ תְּרוּמָה גְּדוֹלָה [וּנְתָנוֹ לְלֵוִי חַיָּב הַלֵּוִי לְהַפְרִישׁ מִמֶּנּוּ תְּרוּמָה גְּדוֹלָה] וּתְרוּמַת מַעֲשֵׂר מֵאַחַר שֶׁנַּעֲשָׂה דָּגָן נִתְחַיֵּב בִּתְרוּמָה שֶׁנֶּאֱמַר (דברים יח ד) \"רֵאשִׁית דְּגָנְךָ\":","בֶּן לֵוִי שֶׁלָּקַח מַעֲשַׂר שִׁבֳּלִים לֹא יִתֵּן תְּרוּמָתוֹ לַכֹּהֵן שִׁבֳּלִים אֶלָּא קוֹנְסִין אוֹתוֹ לָדוּשׁ וְלִזְרוֹת וְלִתֵּן לוֹ מַעֲשֵׂר מִן הַמַּעֲשֵׂר מִן הַדָּגָן. וְאֵינוֹ חַיָּב לִתֵּן לוֹ מַעֲשֵׂר מִן הַתֶּבֶן אוֹ הָעֵצָה. וְאִם הִפְרִישׁ תְּרוּמַת מַעֲשֵׂר שִׁבֳּלִים כְּמוֹ שֶׁנָּתְנוּ לוֹ הֲרֵי זֶה כּוֹתֵשׁ וְנוֹתֵן לַכֹּהֵן אֶת הַזֶּרַע וְאֶת הַתֶּבֶן. וּמִפְּנֵי מָה קְנָסוּהוּ לִכְתּשׁ מִפְּנֵי שֶׁלָּקַח הַמַּעֲשֵׂר שִׁבֳּלִים וְהִפְקִיעַ מִמֶּנּוּ תְּרוּמָה גְּדוֹלָה:","בֶּן יִשְׂרָאֵל שֶׁאָמַר לְלֵוִי כָּךְ אָמַר לִי אַבָּא מַעֲשֵׂר לְךָ בְּיָדִי אֵין חוֹשְׁשִׁין לִתְרוּמַת מַעֲשֵׂר שֶׁבּוֹ. שֶׁהֲרֵי אָבִיו הִפְרִישׁ תְּרוּמָתוֹ וּלְפִיכָךְ צִוָּהוּ שֶׁזֶּה הַמַּעֲשֵׂר לִפְלוֹנִי הַלֵּוִי. וְאִם אָמַר לוֹ כָּךְ אָמַר לִי אַבָּא כּוֹר מַעֲשֵׂר יֵשׁ לְךָ בְּיָדִי חוֹשְׁשִׁין לִתְרוּמַת מַעֲשֵׂר שֶׁבּוֹ:","תְּרוּמַת מַעֲשֵׂר שֶׁהָיָה בָּהּ אֶחָד מִשְּׁמוֹנָה בִּשְׁמִינִית מוֹלִיכָהּ לַכֹּהֵן. פָּחוֹת מִכֵּן אֵינוֹ מְטַפֵּל לְהוֹלִיכָהּ אֶלָּא מַשְׁלִיכָהּ בָּאוּר וְשׂוֹרְפָהּ. וּבְיַיִן וּבְשֶׁמֶן אֲפִלּוּ כָּל שֶׁהוּא מוֹלִיכָהּ לַכֹּהֵן. וּבִלְבַד שֶׁתְּהֵא תְּרוּמַת מַעֲשֵׂר וַדָּאִית וּטְהוֹרָה. אֲבָל אִם הָיְתָה טְמֵאָה אוֹ שֶׁהָיְתָה שֶׁל דְּמַאי אִם אֵין בָּהּ כַּשִּׁעוּר אֵינוֹ מְטַפֵּל בָּהּ אֶלָּא שׂוֹרְפָהּ:","אֵין תּוֹרְמִין תְּרוּמָה גְּדוֹלָה אֶלָּא מִן הַמֻּקָּף. כֵּיצַד. הָיוּ לוֹ חֲמִשִּׁים סְאָה בְּבַיִת זֶה וַחֲמִשִּׁים סְאָה בְּבַיִת אַחֵר לֹא יַפְרִישׁ מֵאֶחָד מֵהֶן שְׁתֵּי סְאִים עַל הַמֵּאָה. שֶׁנִּמְצָא מַפְרִישׁ מִמָּקוֹם זֶה עַל מָקוֹם אַחֵר. וְאִם הִפְרִישׁ שֶׁלֹּא מִן הַמֻּקָּף תְּרוּמָתוֹ תְּרוּמָה וְהוּא שֶׁיִּהְיֶה הַמֻּפְרָשׁ שָׁמוּר אֲבָל אִם הָיָה טָעוּן כַּדֵּי יַיִן אוֹ שֶׁמֶן וְרָאָה שֶׁמִּשְׁתַּבְּרִין וְאָמַר הֲרֵי הֵן תְּרוּמָה עַל פֵּרוֹת שֶׁבְּבֵיתִי לֹא אָמַר כְּלוּם:","פֵּרוֹת הַמְפֻזָּרִין בְּתוֹךְ הַבַּיִת אוֹ שְׁתֵּי מְגוּרוֹת שֶׁבְּבַיִת אֶחָד תּוֹרֵם מֵאֶחָד עַל הַכּל. שַׂקֵּי תְּבוּאָה וְעִגּוּלֵי דְּבֵלָה וְחָבִיּוֹת שֶׁל גְּרוֹגָרוֹת אִם הָיוּ בַּהֲקֵיפָה אַחַת תּוֹרֵם מֵאַחַת עַל הַכּל. חָבִיּוֹת שֶׁל יַיִן עַד שֶׁלֹּא סָתַם אֶת פִּיהֶן תּוֹרֵם מֵאֶחָד עַל הַכּל. מִשֶּׁסָּתַם תּוֹרֵם מִכָּל אַחַת וְאַחַת:","הָיָה מְלַקֵּט גַּפֵּי יָרָק וּמַנִּיחַ בַּגִּנָּה תּוֹרֵם מֵאֶחָד עַל הַכּל. הֵבִיא מִין אֶחָד בֵּינֵיהֶן תּוֹרֵם מִכָּל אֶחָד וְאֶחָד. הֵבִיא מִינִין הַרְבֵּה בַּקֻּפָּה כְּרוּב מִלְּמַעְלָה וּכְרוּב מִלְּמַטָּה וּמִין אַחֵר בָּאֶמְצַע לֹא יִתְרֹם מִן הָעֶלְיוֹן עַל הַתַּחְתּוֹן. וְאִם הִקִּיף חֲמִשָּׁה צִבּוּרִים בְּגֹרֶן תּוֹרֵם מֵאֶחָד עַל הַכּל בִּזְמַן שֶׁעִקַּר הַגֹּרֶן קַיָּם. אֵין עִקַּר הַגֹּרֶן קַיָּם תּוֹרֵם מִכָּל אֶחָד וְאֶחָד:","תְּרוּמַת מַעֲשֵׂר מַפְרִישִׁין אוֹתוֹ שֶׁלֹּא מִן הַמֻּקָּף שֶׁנֶּאֱמַר (במדבר יח כח כט) \"מִכָּל מַעְשְׂרֹתֵיכֶם תָּרִימוּ תְּרוּמָה\" אֲפִלּוּ מַעֲשֵׂר אֶחָד בִּמְדִינָה זוֹ וּמַעֲשֵׂר אֶחָד בִּמְדִינָה אַחֶרֶת מַפְרִישׁ תְּרוּמָה מֵאֶחָד עַל הַכּל. וְתַלְמִידֵי חֲכָמִים אֵין תּוֹרְמִין אֶלָּא מִן הַמֻּקָּף וַאֲפִלּוּ תְּרוּמַת מַעֲשֵׂר:","בֶּן לֵוִי שֶׁהָיָה לוֹ מַעֲשֵׂר רִאשׁוֹן שֶׁלֹּא נִטְּלָה מִמֶּנּוּ תְּרוּמָתוֹ וְהִנִּיחוֹ לִהְיוֹת מַפְרִישׁ עָלָיו וְהוֹלֵךְ וְהוּא בְּטִבְלוֹ מַה שֶּׁעָשָׂה עָשׂוּי. שֶׁנֶּאֱמַר (במדבר יח כד) \"כִּי אֶת מַעְשַׂר בְּנֵי יִשְׂרָאֵל אֲשֶׁר יָרִימוּ לַה' תְּרוּמָה\" מְלַמֵּד שֶׁהוּא עוֹשֶׂה אֶת כֻּלּוֹ תְּרוּמָה לְאַחֵר:","הִפְרִישׁ מִמֶּנּוּ תְּרוּמַת מַעֲשֵׂר תְּחִלָּה וְאַחַר כָּךְ הִנִּיחוֹ לִהְיוֹת מַפְרִישׁ עָלָיו וְהוֹלֵךְ עַד שֶׁיַּעֲשֶׂה כֻּלּוֹ תְּרוּמַת מַעֲשֵׂר וְיִתְּנוֹ לַכֹּהֵן לֹא עָשָׂה כְּלוּם. שֶׁנֶּאֱמַר (במדבר יח כט) \"אֶת מִקְדְּשׁוֹ מִמֶּנּוּ\" בִּזְמַן שֶׁקָּדָשָׁיו בְּתוֹכוֹ עוֹשֶׂה אוֹתוֹ תְּרוּמָה לַאֲחֵרִים. אֵין קָדָשָׁיו בְּתוֹכוֹ אֵינוֹ עוֹשֶׂה אוֹתוֹ תְּרוּמָה לַאֲחֵרִים. וְכֵן הַמַּנִּיחַ פֵּרוֹת לִהְיוֹת מַפְרִישׁ עֲלֵיהֶם תְּרוּמָה גְּדוֹלָה צָרִיךְ שֶׁיִּהְיוּ טְבוּלִין לִתְרוּמָה. וְאִם הִנִּיחָן לִהְיוֹת מַפְרִישׁ עֲלֵיהֶן מַעֲשֵׂר צָרִיךְ שֶׁיִּהְיוּ טְבוּלִין לְמַעֲשֵׂר:","כְּשֶׁמַּפְרִישִׁין תְּרוּמָה וּמַעֲשֵׂר מַפְרִישִׁין אוֹתָן עַל הַסֵּדֶר. כֵּיצַד. מַפְרִישׁ בִּכּוּרִים תְּחִלָּה לַכּל. וְאַחַר כָּךְ תְּרוּמָה גְּדוֹלָה. וְאַחַר כָּךְ מַעֲשֵׂר רִאשׁוֹן. וְאַחַר כָּךְ מַעֲשֵׂר שֵׁנִי אוֹ מַעֲשֵׂר עָנִי. וְהַמַּקְדִּים שֵׁנִי לָרִאשׁוֹן. אוֹ מַעֲשֵׂר לִתְרוּמָה. אוֹ תְּרוּמָה לְבִכּוּרִים. אַף עַל פִּי שֶׁעָבַר עַל לֹא תַּעֲשֶׂה מַה שֶּׁעָשָׂה עָשׂוּי. וּמִנַּיִן שֶׁהוּא בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (שמות כב כח) \"מְלֵאָתְךָ וְדִמְעֲךָ לֹא תְאַחֵר\". לֹא תְּאַחֵר דָּבָר שֶׁרָאוּי לְהַקְדִּימוֹ. וְאֵין לוֹקִין עַל לָאו זֶה:","הָרוֹצֶה לְהַפְרִישׁ תְּרוּמָה גְּדוֹלָה וּתְרוּמַת מַעֲשֵׂר כְּאֶחָד מַפְרִישׁ אֶחָד מִשְּׁלֹשִׁים וּשְׁלֹשָׁה וּשְׁלִישׁ. וְאוֹמֵר אֶחָד מִמֵּאָה שֶׁיֵּשׁ כָּאן הֲרֵי הוּא בְּצַד זֶה שֶׁהִפְרַשְׁתִּי וַהֲרֵי הוּא חֻלִּין. וְהַנִּשְׁאָר מִזֶּה שֶׁהִפְרַשְׁתִּי הוּא תְּרוּמָה עַל הַכּל. וְהַמַּעֲשֵׂר שֶׁרָאוּי לִהְיוֹת לְמֵאָה חֻלִּין אֵלּוּ הֲרֵי הוּא בְּצַד זֶה שֶׁהִפְרַשְׁתִּי. וְזֶה הַנִּשְׁאָר יֶתֶר עַל הַתְּרוּמָה מִמַּה שֶּׁהִפְרַשְׁתִּי הֲרֵי הוּא תְּרוּמַת מַעֲשֵׂר עַל הַכּל:"],"Mishneh Torah, Hiring 2":["שְׁלֹשָׁה דִּינִין הָאֲמוּרִין בַּתּוֹרָה בְּאַרְבָּעָה הַשּׁוֹמְרִין אֵינָן אֶלָּא בְּמִטַּלְטְלִין שֶׁל יִשְׂרָאֵל וְשֶׁל הֶדְיוֹט שֶׁנֶּאֱמַר (שמות כב ו) \"כֶּסֶף אוֹ כֵלִים\" (שמות כב ט) \"וְכָל בְּהֵמָה\" יָצְאוּ קַרְקָעוֹת וְיָצְאוּ הָעֲבָדִים שֶׁהֻקְּשׁוּ לְקַרְקָעוֹת וְיָצְאוּ הַשְּׁטָרוֹת שֶׁאֵין גּוּפָן מָמוֹן וְיָצְאוּ הֶקְדֵּשׁוֹת שֶׁנֶּאֱמַר (שמות כב ו) \"כִּי יִתֵּן אִישׁ אֶל רֵעֵהוּ\" וְיָצְאוּ נִכְסֵי עַכּוּ\"ם. מִכָּאן אָמְרוּ חֲכָמִים הָעֲבָדִים וְהַשְּׁטָרוֹת וְהַקַּרְקָעוֹת וְהַהֶקְדֵּשׁוֹת שׁוֹמֵר חִנָּם שֶׁלָּהֶן אֵינוֹ נִשְׁבָּע. וְנוֹשֵׂא שָׂכָר אוֹ שׂוֹכֵר אֵינוֹ מְשַׁלֵּם. וְאִם קָנוּ מִיָּדוֹ חַיָּב בְּאַחֲרָיוּתָן:","וְתִקְּנוּ חֲכָמִים שֶׁנִּשְׁבָּעִין עַל הַהֶקְדֵּשׁוֹת שְׁבוּעַת הַשּׁוֹמְרִין כְּעֵין שֶׁל תּוֹרָה כְּדֵי שֶׁלֹּא יְזַלְזְלוּ בַּהֶקְדֵּשׁוֹת:","יֵרָאֶה לִי שֶׁאִם פָּשַׁע הַשּׁוֹמֵר בַּעֲבָדִים וְכַיּוֹצֵא בָּהֶן חַיָּב לְשַׁלֵּם. שֶׁאֵינוֹ פָּטוּר בַּעֲבָדִים וְקַרְקָעוֹת וּשְׁטָרוֹת אֶלָּא מִדִּין גְּנֵבָה וַאֲבֵדָה וּמֵתָה וְכַיּוֹצֵא בָּהֶן. שֶׁאִם הָיָה שׁוֹמֵר חִנָּם עַל מִטַּלְטְלִין וְנִגְנְבוּ אוֹ אָבְדוּ יִשָּׁבַע וּבַעֲבָדִים וְקַרְקָעוֹת וּשְׁטָרוֹת פָּטוּר מִשְּׁבוּעָה. וְכֵן אִם הָיָה שׁוֹמֵר שָׂכָר שֶׁמְּשַׁלֵּם גְּנֵבָה וַאֲבֵדָה בְּמִטַּלְטְלִין פָּטוּר מִלְּשַׁלֵּם בְּאֵלּוּ. אֲבָל אִם פָּשַׁע בָּהּ חַיָּב לְשַׁלֵּם שֶׁכָּל הַפּוֹשֵׁעַ מַזִּיק הוּא. וְאֵין הֶפְרֵשׁ בֵּין דִּין הַמַּזִּיק קַרְקַע לְדִין הַמַּזִּיק מִטַּלְטְלִין. וְדִין אֱמֶת הוּא זֶה לַמְּבִינִים וְכֵן רָאוּי לָדוּן. וְכֵן הוֹרוּ רַבּוֹתַי שֶׁהַמּוֹסֵר כַּרְמוֹ לְשׁוֹמֵר בֵּין בַּאֲרִיסוּת בֵּין בִּשְׁמִירוּת חִנָּם וְהִתְנָה עִמּוֹ שֶׁיַּחְפֹּר אוֹ יִזְמֹר אוֹ יְאַבֵּק מִשֶּׁלּוֹ וּפָשַׁע וְלֹא עָשָׂה חַיָּב כְּמִי שֶׁהִפְסִיד בַּיָּדַיִם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה שֶׁהִפְסִיד בַּיָּדַיִם חַיָּב עַל כָּל פָּנִים:","הַמּוֹסֵר לַחֲבֵרוֹ דָּבָר הַמְחֻבָּר לַקַּרְקַע לִשְׁמֹר אֲפִלּוּ הָיוּ עֲנָבִים הָעוֹמְדוֹת לְהִבָּצֵר הֲרֵי הֵן כְּקַרְקַע בְּדִין הַשּׁוֹמְרִין:","הִפְקִיד הֶקְדֵּשׁ וְאַחַר כָּךְ פָּדָהוּ וַהֲרֵי הוּא חֻלִּין בְּעֵת שֶׁנְּטָלוֹ מִיַּד הַשּׁוֹמֵר. אוֹ שֶׁהִשְׁאִילוֹ חֻלִּין וְאַחַר כָּךְ הִקְדִּישׁ וְהוּא בְּיַד הַשּׁוֹאֵל. וְכֵן עַכּוּ\"ם שֶׁהִפְקִיד וְאַחַר כָּךְ נִתְגַּיֵּר. כָּל אֵלּוּ אֵין בָּהֶן כָּל דִּינֵי הַשּׁוֹמְרִין עַד שֶׁתִּהְיֶה תְּחִלָּתָן וְסוֹפָן נִכְסֵי הֶדְיוֹט וְנִכְסֵי יִשְׂרָאֵל:","אֶחָד הָאִישׁ וְאֶחָד הָאִשָּׁה בְּדִין הַשּׁוֹמְרִין בֵּין שֶׁהָיָה הַדָּבָר הַשָּׁמוּר שֶׁל אִשָּׁה אוֹ שֶׁהָיָה בְּיַד הָאִשָּׁה:","קָטָן שֶׁהִפְקִיד בְּיַד גָּדוֹל אוֹ הִשְׁאִילוֹ הֲרֵי זֶה הַגָּדוֹל נִשְׁבָּע שְׁבוּעַת הַשּׁוֹמְרִים לַקָּטָן. הוֹרוּ רַבּוֹתַי שֶׁאֵין זֶה נִשְׁבָּע בְּטַעֲנַת הַקָּטָן כְּדֵי שֶׁנֹּאמַר אֵין נִשְׁבָּעִין עַל טַעֲנַת קָטָן שֶׁכָּל הַשּׁוֹמְרִין שְׁבוּעָתָן שְׁבוּעַת שֶׁמָּא הִיא:","כְּדֶרֶךְ שֶׁתִּקְּנוּ חֲכָמִים מְשִׁיכָה בְּלָקוֹחוֹת כָּךְ תִּקְּנוּ מְשִׁיכָה בְּשׁוֹמְרִין. הָאוֹמֵר לַחֲבֵרוֹ שְׁמֹר לִי זֶה וְאָמַר לוֹ הַנַּח לְפָנַי הֲרֵי זֶה שׁוֹמֵר חִנָּם. אָמַר לוֹ הַנַּח לְפָנֶיךָ אוֹ הַנַּח סְתָם אוֹ שֶׁאָמַר לוֹ הֲרֵי הַבַּיִת לְפָנֶיךָ אֵינוֹ לֹא שׁוֹמֵר חִנָּם וְלֹא שׁוֹמֵר שָׂכָר וְאֵינוֹ חַיָּב שְׁבוּעָה כְּלָל אֲבָל מַחֲרִים עַל מִי שֶׁלָּקַח הַפִּקָּדוֹן שֶׁלּוֹ וְלֹא יַחֲזִירוֹ לִבְעָלָיו. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. אֶחָד הַמַּפְקִיד אוֹ הַמַּשְׁאִיל אוֹ הַמַּשְׂכִּיר אֶת חֲבֵרוֹ בְּעֵדִים אוֹ שֶׁלֹּא בְּעֵדִים דִּין אֶחָד יֵשׁ לָהֶן כֵּיוָן שֶׁהוֹדָה זֶה מִפִּי עַצְמוֹ שֶׁשָּׁמַר לוֹ אוֹ שֶׁשָּׁאַל מִמֶּנּוּ הֲרֵי זֶה נִשְׁבָּע שְׁבוּעַת הַשּׁוֹמְרִין שֶׁאֵין אוֹמְרִים מִגּוֹ לְפָטְרוֹ מִשְּׁבוּעָה אֶלָּא לְפָטְרוֹ מִלְּשַׁלֵּם. אֲפִלּוּ הָיָה הַדָּבָר הַשָּׁאוּל אוֹ הַמֻּפְקָד אוֹ הַמֻּשְׂכָּר שְׁוֵה פְּרוּטָה הֲרֵי זֶה הַשּׁוֹמֵר נִשְׁבָּע עָלָיו. וְאֵין אֶחָד מִן הַשּׁוֹמְרִים צָרִיךְ לְהוֹדָיָה בְּמִקְצָת:","מַתְנֶה שׁוֹמֵר חִנָּם לִהְיוֹת פָּטוּר מִשְּׁבוּעָה וְהַשּׁוֹאֵל לִהְיוֹת פָּטוּר מִלְּשַׁלֵּם. וְכֵן מַתְנֶה בַּעַל הַפִּקָּדוֹן עַל שׁוֹמֵר חִנָּם אוֹ נוֹשֵׂא שָׂכָר וְשׂוֹכֵר לִהְיוֹת חַיָּבִין בַּכּל כְּשׁוֹאֵל. שֶׁכָּל תְּנַאי בְּמָמוֹן אוֹ בִּשְׁבוּעוֹת שֶׁל מָמוֹן קַיָּם וְאֵין צָרִיךְ קִנְיָן וְלֹא עֵדִים:","טָעַן זֶה שֶׁהָיָה שָׁם תְּנַאי וְהַשּׁוֹמֵר אוֹמֵר לֹא הָיָה שָׁם תְּנַאי נִשְׁבָּע הַשּׁוֹמֵר שְׁבוּעַת הַשּׁוֹמְרִין וּמְגַלְגֵּל בָּהּ שֶׁלֹּא הָיָה שָׁם תְּנַאי:","טָעַן שֶׁהִפְקִיד אֶצְלוֹ וְזֶה אוֹמֵר לֹא אָמַרְתִּי אֶלָּא הַנַּח לְפָנֶיךָ וְלֹא נַעֲשֵׂיתִי לוֹ שׁוֹמֵר נִשְׁבָּע הֶסֵּת שֶׁלֹּא קִבְּלוֹ אֶלָּא בְּדֶרֶךְ זוֹ וְכוֹלֵל בִּשְׁבוּעָתוֹ שֶׁלֹּא שָׁלַח בּוֹ יָד וְלֹא אִבְּדוֹ בַּיָּדַיִם וְלֹא בִּגְרָם שֶׁגָּרַם לוֹ שֶׁיִּהְיֶה חַיָּב לְשַׁלֵּם:","זֶה אוֹמֵר הִשְׁאַלְתִּיךָ אוֹ הִשְׂכַּרְתִּיךָ אוֹ הִפְקַדְתִּיךָ וְהַלָּה אוֹמֵר לֹא הָיוּ דְּבָרִים מֵעוֹלָם. אוֹ שֶׁאָמַר כֵּן הָיָה אֲבָל הְחֶזַרְתִּי לְךָ וְנִסְתַּלְּקָה הַשְּׁמִירָה וְלֹא נִשְׁאֲרָה בֵּינֵינוּ תְּבִיעָה. הֲרֵי הַנִּתְבָּע נִשְׁבָּע שְׁבוּעַת הֶסֵּת וְנִפְטָר. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁלֹּא הָיָה שָׁם שְׁטָר. אֲבָל אִם הִפְקִיד אוֹ הִשְׂכִּיר אוֹ הִשְׁאִיל בִּשְׁטָר וְאָמַר לוֹ הֶחְזַרְתִּי לְךָ הֲרֵי הַשּׁוֹמֵר נִשְׁבָּע בִּנְקִיטַת חֵפֶץ מִתּוֹךְ שֶׁיָּכוֹל לוֹמַר שׁוֹמֵר חִנָּם שֶׁנִּגְנַב אוֹ אָבַד וְהַשּׁוֹאֵל מֵתָה בִּשְׁעַת מְלָאכָה נֶאֱמָן לוֹמַר הֶחְזַרְתִּי. וּכְשֵׁם שֶׁאִם טָעַן שֶׁנֶּאֱנַס נִשְׁבָּע מִן הַתּוֹרָה בִּנְקִיטַת חֵפֶץ כָּךְ אִם טָעַן הְחֶזַרְתִּי יִשָּׁבַע כְּעֵין שֶׁל תּוֹרָה הוֹאִיל וְיֵשׁ שָׁם שְׁטָר בְּיַד הַתּוֹבֵעַ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה הַשּׁוֹמֵר יָכוֹל לִטְעֹן וְלוֹמַר נֶאֶנְסוּ וְלֹא נַצְרִיךְ אוֹתוֹ לְהָבִיא רְאָיָה עַל טַעֲנָתוֹ. אֲבָל אִם הָיָה חַיָּב לְהָבִיא רְאָיָה עַל טַעֲנָתוֹ כְּמוֹ שֶׁיִּתְבָּאֵר אֵינוֹ נֶאֱמָן לוֹמַר הֶחְזַרְתִּי אֶלָּא יִשָּׁבַע בַּעַל הַשְּׁטָר בִּנְקִיטַת חֵפֶץ שֶׁלֹּא הֶחְזִיר לוֹ וִישַׁלֵּם. אֵין לְךָ מִי שֶׁנִּשְׁבָּע מִתּוֹךְ שֶׁיָּכוֹל לוֹמַר כָּךְ וְכָךְ וְיִשָּׁבַע בִּנְקִיטַת חֵפֶץ אֶלָּא זֶה הַשּׁוֹמֵר בִּלְבַד שֶׁיֵּשׁ עָלָיו שְׁטָר אֲבָל שְׁאָר כָּל הַנִּשְׁבָּעִין בַּדִּין מִתּוֹךְ שֶׁיָּכוֹל לוֹמַר אֵינָן נִשְׁבָּעִין אֶלָּא הֶסֵּת:"],"Mishneh Torah, Human Dispositions 5":["כְּשֵׁם שֶׁהֶחָכָם נִכָּר בְּחָכְמָתוֹ וּבְדֵעוֹתָיו וְהוּא מֻבְדָּל בָּהֶם מִשְּׁאָר הָעָם. כָּךְ צָרִיךְ שֶׁיִּהְיֶה נִכָּר בְּמַעֲשָׂיו בְּמַאֲכָלוֹ וּבְמַשְׁקֵהוּ וּבִבְעִילָתוֹ וּבַעֲשִׂיַּת צְרָכָיו וּבְדִבּוּרוֹ וּבְהִלּוּכוֹ וּבְמַלְבּוּשׁוֹ וּבְכִלְכּוּל דְּבָרָיו וּבְמַשָּׂאוֹ וּבְמַתָּנוֹ. וְיִהְיוּ כָּל הַמַּעֲשִׂים הָאֵלּוּ נָאִים וּמְתֻקָּנִים בְּיוֹתֵר. כֵּיצַד. תַּלְמִיד חָכָם לֹא יִהְיֶה גַּרְגְּרָן אֶלָּא אוֹכֵל מַאֲכָל הָרָאוּי לְהַבְרוֹת גּוּפוֹ. וְלֹא יֹאכַל מִמֶּנּוּ אֲכִילָה גַּסָּה. וְלֹא יְהֵא רוֹדֵף לְמַלְּאֹת בִּטְנוֹ כְּאֵלּוּ שֶׁמִּתְמַלְּאִין מִמַּאֲכָל וּמִשְׁתֶּה עַד שֶׁתִּפַּח כְּרֵסָם. וַעֲלֵיהֶם מְפֹרָשׁ בַּקַּבָּלָה (מלאכי ב ג) \"וְזֵרִיתִי פֶרֶשׁ עַל פְּנֵיכֶם\". אָמְרוּ חֲכָמִים אֵלּוּ בְּנֵי אָדָם שֶׁאוֹכְלִין וְשׁוֹתִין וְעוֹשִׂין כָּל יְמֵיהֶם כְּחַגִּים. וְהֵם הָאוֹמְרִים (ישעיה כב יג) \"אָכוֹל וְשָׁתֹה כִּי מָחָר נָמוּת\". וְזֶהוּ מַאֲכַל הָרְשָׁעִים. וְשֻׁלְחָנוֹת אֵלּוּ הֵם שֶׁגִּנָּה הַכָּתוּב וְאָמַר (ישעיה כח ח) \"כִּי כָּל שֻׁלְחָנוֹת מָלְאוּ קִיא צֹאָה בְּלִי מָקוֹם\". אֲבָל הֶחָכָם אֵינוֹ אוֹכֵל אֶלָּא תַּבְשִׁיל אֶחָד אוֹ שְׁנַיִם וְאוֹכֵל מִמֶּנּוּ כְּדֵי חַיָּיו וְדַּיּוֹ. הוּא שֶׁאָמַר שְׁלֹמֹה (משלי יג כה) \"צַדִּיק אֹכֵל לְשֹׂבַע נַפְשׁוֹ\":","כְּשֶׁהֶחָכָם אוֹכֵל מְעַט זֶה הָרָאוּי לוֹ לֹא יֹאכְלֶנּוּ אֶלָּא בְּבֵיתוֹ עַל שֻׁלְחָנוֹ. וְלֹא יֹאכַל בַּחֲנוּת וְלֹא בַּשּׁוּק אֶלָּא מִפְּנֵי צֹרֶךְ גָּדוֹל. כְּדֵי שֶׁלֹּא יִתְגַּנֶּה בִּפְנֵי הַבְּרִיּוֹת. וְלֹא יֹאכַל אֵצֶל עַמֵּי הָאָרֶץ וְלֹא עַל אוֹתָן הַשֻּׁלְחָנוֹת הַמְּלֵאִים קִיא צוֹאָה. וְלֹא יַרְבֶּה סְעֻדּוֹתָיו בְּכָל מָקוֹם וַאֲפִלּוּ עִם הַחֲכָמִים. וְלֹא יֹאכַל בִּסְעֻדּוֹת שֶׁיֵּשׁ בָּהֶן קִבּוּץ הַרְבֵּה. וְאֵין רָאוּי לוֹ לֶאֱכל אֶלָּא בִּסְעֻדָּה שֶׁל מִצְוָה בִּלְבַד כְּגוֹן סְעֻדַּת אֵרוּסִין וְנִשּׂוּאִין. וְהוּא שֶׁיִּהְיֶה תַּלְמִיד חָכָם שֶׁנָּשָׂא בַּת תַּלְמִיד חָכָם. וְהַצַּדִּיקִים וְהַחֲסִידִים הָרִאשׁוֹנִים לֹא אָכְלוּ מִסְּעֻדָּה שֶׁאֵינָהּ שֶׁלָּהֶן:","כְּשֶׁהֶחָכָם שׁוֹתֶה יַיִן אֵינוֹ שׁוֹתֶה אֶלָּא כְּדֵי לִשְׁרוֹת אֲכִילָה שֶׁבְּמֵעָיו. וְכָל הַמִּשְׁתַּכֵּר הֲרֵי זֶה חוֹטֵא וּמְגֻנֶּה וּמַפְסִיד חָכְמָתוֹ. וְאִם נִשְׁתַּכֵּר בִּפְנֵי עַמֵּי הָאָרֶץ הֲרֵי זֶה חִלֵּל אֶת הַשֵּׁם. וְאָסוּר לִשְׁתּוֹת יַיִן בַּצָּהֳרַיִם וַאֲפִלּוּ מְעַט אֶלָּא אִם הָיָה בִּכְלַל הָאֲכִילָה. שֶׁהַשְּׁתִיָּה שֶׁהִיא בִּכְלַל הָאֲכִילָה אֵינָהּ מְשַׁכֶּרֶת. וְאֵין נִזְהָרִין אֶלָּא מִיַּיִן שֶׁלְּאַחַר הַמָּזוֹן:","אַף עַל פִּי שֶׁאִשְׁתּוֹ שֶׁל אָדָם מֻתֶּרֶת לוֹ תָּמִיד. רָאוּי לוֹ לְתַלְמִיד חָכָם שֶׁיַּנְהִיג עַצְמוֹ בִּקְדֻשָּׁה וְלֹא יְהֵא מָצוּי אֵצֶל אִשְׁתּוֹ כְּתַרְנְגוֹל אֶלָּא מִלֵּילֵי שַׁבָּת לְלֵילֵי שַׁבָּת אִם יֵשׁ בּוֹ כֹּחַ. וּכְשֶׁהוּא מְסַפֵּר עִמָּהּ לֹא יְסַפֵּר בִּתְחִלַּת הַלַּיְלָה כְּשֶׁהוּא שָׂבֵעַ וּבִטְנוֹ מָלֵא. וְלֹא בְּסוֹף הַלַּיְלָה כְּשֶׁהוּא רָעֵב. אֶלָּא בְּאֶמְצַע הַלַּיְלָה כְּשֶׁיִּתְעַכֵּל הַמָּזוֹן שֶׁבְּמֵעָיו. וְלֹא יָקֵל בְּרֹאשׁוֹ בְּיוֹתֵר וְלֹא יְנַבֵּל אֶת פִּיו בְּדִבְרֵי הֲבַאי וַאֲפִלּוּ בֵּינוֹ לְבֵינָהּ. הֲרֵי הוּא אוֹמֵר בְּקַבָּלָה מַגִּיד לְאָדָם מַה שֵּׂחוֹ. אָמְרוּ חֲכָמִים אֲפִלּוּ שִׂיחָה קַלָּה שֶׁבֵּין אָדָם לְאִשְׁתּוֹ עָתִיד לִתֵּן עָלֶיהָ אֶת הַדִּין. וְלֹא יִהְיוּ שְׁנֵיהֶם לֹא שִׁכּוֹרִים וְלֹא עַצְלָנִים וְלֹא עַצְבָּנִים, וְלֹא אֶחָד מֵהֶן. וְלֹא תִּהְיֶה יְשֵׁנָה. וְלֹא יֶאֱנֹס אוֹתָהּ וְהִיא אֵינָהּ רוֹצָה אֶלָּא בִּרְצוֹן שְׁנֵיהֶם וּבְשִׂמְחָתָם. יְסַפֵּר וְיִשְׂחַק מְעַט עִמָּהּ כְּדֵי שֶׁתִּתְיַשֵּׁב נַפְשָׁהּ וְיִבְעל בְּבוּשָׁה וְלֹא בְּעַזּוּת וְיִפְרשׁ מִיָּד:","כָּל הַנּוֹהֵג מִנְהָג זֶה לֹא דַּי לוֹ שֶׁקִּדֵּשׁ נַפְשׁוֹ וְטִהֵר עַצְמוֹ וְתִקֵּן דֵּעוֹתָיו אֶלָּא שֶׁאִם הָיוּ לוֹ בָּנִים יִהְיוּ נָאִים וּבַיְשָׁנִים רְאוּיִין לְחָכְמָה וְלַחֲסִידוּת. וְכָל הַנּוֹהֵג בְּמִנְהֲגוֹת שְׁאָר הָעָם הַהוֹלְכִים בַּחשֶׁךְ יִהְיוּ לוֹ בָּנִים כְּמוֹ אוֹתָם הָעָם:","צְנִיעוּת גְּדוֹלָה נוֹהֲגִים תַּלְמִידֵי חֲכָמִים בְּעַצְמָן. לֹא יִתְבַּזּוּ וְלֹא יִתְגַּלּוּ רֹאשָׁן וְלֹא גּוּפָן. וַאֲפִלּוּ בְּשָׁעָה שֶׁיִּכָּנֵס לְבֵית הַכִּסֵּא יְהֵא צָנוּעַ וְלֹא יְגַלֶּה בְּגָדָיו עַד שֶׁיֵּשֵׁב. וְלֹא יְקַנֵּחַ בְּיָמִין. וְיִתְרַחֵק מִכָּל אָדָם. וְיִכָּנֵס חֶדֶר לִפְנִים מֵחֶדֶר מְעָרָה לִפְנִים מִן הַמְּעָרָה וְנִפְנֶה. וְאִם נִפְנֶה אֲחוֹרֵי הַגָּדֵר יִתְרַחֵק כְּדֵי שֶׁלֹּא יִשְׁמַע חֲבֵרוֹ קוֹלוֹ אִם נִתְעַטֵּשׁ. וְאִם נִפְנֶה בְּבִקְעָה יַרְחִיק כְּדֵי שֶׁלֹּא יִרְאֶה חֲבֵרוֹ פֵּרוּעוֹ. וְלֹא יְדַבֵּר כְּשֶׁהוּא נִפְנֶה אֲפִלּוּ לְצֹרֶךְ גָּדוֹל. וּכְדֶרֶךְ שֶׁנּוֹהֵג צְנִיעוּת בַּיּוֹם בְּבֵית הַכִּסֵּא כָּךְ נוֹהֵג בַּלַּיְלָה. וּלְעוֹלָם יְלַמֵּד אָדָם עַצְמוֹ לְהִפָּנוֹת שַׁחֲרִית וְעַרְבִית בִּלְבַד כְּדֵי שֶׁלֹּא יִתְרַחֵק:","תַּלְמִיד חָכָם לֹא יְהֵא צוֹעֵק וְצוֹוֵחַ בִּשְׁעַת דִּבּוּרוֹ כִּבְהֵמוֹת וְחַיּוֹת. וְלֹא יַגְבִּיהַּ קוֹלוֹ בְּיוֹתֵר אֶלָּא דִּבּוּרוֹ בְּנַחַת עִם כָּל הַבְּרִיּוֹת. וּכְשֶׁיְּדַבֵּר בְּנַחַת יִזָּהֵר שֶׁלֹּא יִתְרַחֵק עַד שֶׁיֵּרָאֶה כְּדִבְרֵי גַּסֵּי הָרוּחַ. וּמַקְדִּים שָׁלוֹם לְכָל הָאָדָם כְּדֵי שֶׁתְּהֵא רוּחָן נוֹחָה הֵימֶנּוּ. וְדָן אֶת כָּל הָאָדָם לְכַף זְכוּת. מְסַפֵּר בְּשֶׁבַח חֲבֵרוֹ וְלֹא בִּגְנוּתוֹ כְּלָל. אוֹהֵב שָׁלוֹם וְרוֹדֵף שָׁלוֹם. אִם רוֹאֶה שֶׁדְּבָרָיו מוֹעִילִים וְנִשְׁמָעִים אוֹמֵר וְאִם לָאו שׁוֹתֵק. כֵּיצַד. לֹא יְרַצֶּה חֲבֵרוֹ בִּשְׁעַת כַּעֲסוֹ. וְלֹא יִשְׁאַל לוֹ עַל נִדְרוֹ בְּשָׁעָה שֶׁנָּדַר עַד שֶׁתִּתְקָרֵר דַּעְתּוֹ וְיָנוּחַ. וְלֹא יְנַחֲמֶנּוּ בְּשָׁעָה שֶׁמֵּתוֹ מֻטָּל לְפָנָיו מִפְּנֵי שֶׁהוּא בָּהוּל עַד שֶׁיִּקְבְּרֵהוּ. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ. וְלֹא יִרְאֶה לַחֲבֵרוֹ בִּשְׁעַת קַלְקָלָתוֹ אֶלָּא יַעֲלִים עֵינָיו מִמֶּנּוּ. וְלֹא יְשַׁנֶּה בְּדִבּוּרוֹ. וְלֹא יוֹסִיף וְלֹא יִגְרַע אֶלָּא בְּדִבְרֵי שָׁלוֹם וְכַיּוֹצֵא בָּהֶן. כְּלָלוֹ שֶׁל דָּבָר אֵינוֹ מְדַבֵּר אֶלָּא בְּדִבְרֵי חָכְמָה אוֹ בִּגְמִילוּת חֲסָדִים וְכַיּוֹצֵא בָּהֶן. וְלֹא יְסַפֵּר עִם אִשָּׁה בַּשּׁוּק וַאֲפִלּוּ הִיא אִשְׁתּוֹ אוֹ אֲחוֹתוֹ אוֹ בִּתּוֹ:","לֹא יֵלֵךְ תַּלְמִיד חָכָם בְּקוֹמָה זְקוּפָה וְגָרוֹן נָטוּי כָּעִנְיָן שֶׁנֶּאֱמַר (ישעיה ג טז) \"וַתֵּלַכְנָה נְטוּיוֹת גָּרוֹן וּמְשַׂקְּרוֹת עֵינָיִם\". וְלֹא יְהַלֵּךְ עָקֵב בְּצַד גּוּדָל בְּנַחַת כְּמוֹ הַנָּשִׁים וְגַסֵּי הָרוּחַ כָּעִנְיָן שֶׁנֶּאֱמַר (ישעיה ג טז) \"הָלוֹךְ וְטָפֹף תֵּלַכְנָה וּבְרַגְלֵיהֶם תְּעַכַּסְנָה\". וְלֹא יָרוּץ בִּרְשׁוּת הָרַבִּים כְּמִנְהַג מְשֻׁגָּעִים. וְלֹא יִכְפֹּף קוֹמָתוֹ כְּבַעֲלֵי חֲטוֹטֶרֶת. אֶלָּא מִסְתַּכֵּל לְמַטָּה כְּמוֹ שֶׁהוּא עוֹמֵד בִּתְפִלָּה. וּמְהַלֵּךְ בַּשּׁוּק כְּאָדָם שֶׁהוּא טָרוּד בַּעֲסָקָיו. גַּם מִמַּהֲלָכוֹ שֶׁל אָדָם נִכָּר אִם חָכָם וּבַעַל דֵּעָה הוּא אוֹ שׁוֹטֶה וְסָכָל. וְכֵן אָמַר שְׁלֹמֹה בְּחָכְמָתוֹ (קהלת י ג) \"וְגַם בַּדֶּרֶךְ כְּשֶׁסָּכָל הֹלֵךְ לִבּוֹ חָסֵר וְאָמַר לַכֹּל סָכָל הוּא\". הוּא מוֹדִיעַ לַכֹּל עַל עַצְמוֹ שֶׁהוּא סָכָל:","מַלְבּוּשׁ תַּלְמִיד חָכָם מַלְבּוּשׁ נָאֶה וְנָקִי. וְאָסוּר לוֹ שֶׁיִּמָּצֵא בְּבִגְדוֹ כֶּתֶם אוֹ שַׁמְנוּנִית וְכַיּוֹצֵא בָּהֶן. וְלֹא יִלְבַּשׁ לֹא מַלְבּוּשׁ מְלָכִים כְּגוֹן בִּגְדֵי זָהָב וְאַרְגָּמָן שֶׁהַכּל מִסְתַּכְּלִין בָּהֶן. וְלֹא מַלְבּוּשׁ עֲנִיִּים שֶׁהוּא מְבַזֶּה אֶת לוֹבְשָׁיו אֶלָּא בְּגָדִים בֵּינוֹנִים נָאִים. וְלֹא יְהֵא בְּשָׂרוֹ נִרְאֶה מִתַּחַת מַדָּיו כְּמוֹ בִּגְדֵי הַפִּשְׁתָּן הַקַּלִּים בְּיוֹתֵר שֶׁעוֹשִׂים בְּמִצְרַיִם. וְלֹא יִהְיוּ בְּגָדָיו סְחוּבִין עַל הָאָרֶץ כְּמוֹ בִּגְדֵי גַּסֵּי הָרוּחַ אֶלָּא עַד עֲקֵבוֹ וּבֵית יָד שֶׁלּוֹ עַד רָאשֵׁי אֶצְבְּעוֹתָיו. וְלֹא יְשַׁלְשֵׁל טַלִּיתוֹ מִפְּנֵי שֶׁנִּרְאֶה כְּגַסּוּת הָרוּחַ אֶלָּא בְּשַׁבָּת בִּלְבַד אִם אֵין לוֹ לְהַחֲלִיף. וְלֹא יִנְעַל מִנְעָלִים מְטֻלָּאִים טְלַאי עַל גַּבֵּי טְלַאי בִּימוֹת הַחַמָּה. אֲבָל בִּימוֹת הַגְּשָׁמִים מֻתָּר אִם הָיָה עָנִי. לֹא יֵצֵא מְבֻשָּׂם לַשּׁוּק וְלֹא בִּבְגָדִים מְבֻשָּׂמִים וְלֹא יָשִׂים בּשֶֹׁם בִּשְׂעָרוֹ. אֲבָל אִם מָשַׁח בְּשָׂרוֹ בְּבשֶֹׁם כְּדֵי לְהַעֲבִיר אֶת הַזֻּהֲמָא מֻתָּר. וְכֵן לֹא יֵצֵא יְחִידִי בַּלַּיְלָה. אֶלָּא אִם כֵּן הָיָה לוֹ זְמַן קָבוּעַ לָצֵאת בּוֹ לְתַלְמוּדוֹ. כָּל אֵלּוּ מִפְּנֵי הַחֲשָׁד:","תַּלְמִיד חָכָם מְכַלְכֵּל דְּבָרָיו בְּמִשְׁפָּט. אוֹכֵל וְשׁוֹתֶה וְזָן אֶת אַנְשֵׁי בֵּיתוֹ כְּפִי מָמוֹנוֹ וְהַצְלָחָתוֹ. וְלֹא יַטְרִיחַ עַל עַצְמוֹ יוֹתֵר מִדַּאי. צִוּוּ חֲכָמִים בְּדֶרֶךְ אֶרֶץ שֶׁלֹּא יֹאכַל אָדָם בָּשָׂר אֶלָּא לְתֵאָבוֹן. שֶׁנֶּאֱמַר (דברים יב כ) \"כִּי תְאַוֶּה נַפְשְׁךָ לֶאֱכל בָּשָׂר\". דַּיּוֹ לַבָּרִיא לֶאֱכל בָּשָׂר מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת. וְאִם הָיָה עָשִׁיר כְּדֵי לֶאֱכל בָּשָׂר בְּכָל יוֹם אוֹכֵל. צִוּוּ חֲכָמִים וְאָמְרוּ לְעוֹלָם יֹאכַל אָדָם פָּחוֹת מִן הָרָאוּי לוֹ לְפִי מָמוֹנוֹ וְיִלְבַּשׁ כָּרָאוּי לוֹ וִיכַבֵּד אִשְׁתּוֹ וּבָנָיו יוֹתֵר מִן הָרָאוּי לוֹ:","דֶּרֶךְ בַּעֲלֵי דֵּעָה שֶׁיִּקְבַּע לוֹ אָדָם מְלָאכָה הַמְפַרְנֶסֶת אוֹתוֹ תְּחִלָּה. וְאַחַר כָּךְ יִקְנֶה בֵּית דִּירָה. וְאַחַר כָּךְ יִשָּׂא אִשָּׁה. שֶׁנֶּאֱמַר (דברים כ ו) \"מִי הָאִישׁ אֲשֶׁר נָטַע כֶּרֶם וְלֹא חִלְּלוֹ\". (דברים כ ה) \"מִי הָאִישׁ אֲשֶׁר בָּנָה בַיִת חָדָשׁ וְלֹא חֲנָכוֹ\". (דברים כ ז) \"מִי הָאִישׁ אֲשֶׁר אֵרַשׂ אִשָּׁה וְלֹא לְקָחָהּ\". אֲבָל הַטִּפְּשִׁין מַתְחִילִין לִשָּׂא אִשָּׁה וְאַחַר כָּךְ אִם תִּמְצָא יָדוֹ יִקְנֶה בַּיִת וְאַחַר כָּךְ בְּסוֹף יָמָיו יְחַזֵּר לְבַקֵּשׁ אֻמָּנוּת אוֹ יִתְפַּרְנֵס מִן הַצְּדָקָה. וְכֵן הוּא אוֹמֵר בַּקְּלָלוֹת (דברים כח ל) \"אִשָּׁה תְאָרֵשׂ\" (דברים כח ל) \"בַּיִת תִּבְנֶה\" (דברים כח ל) \"כֶּרֶם תִּטַּע\". כְּלוֹמַר יִהְיוּ מַעֲשֶׂיךָ הֲפוּכִין כְּדֵי שֶׁלֹּא תַּצְלִיחַ אֶת דְּרָכֶיךָ. וּבַבְּרָכָה הוּא אוֹמֵר (שמואל א יח יד) \"וַיְהִי דָוִד לְכָל דְּרָכָו מַשְׂכִּיל וַה' עִמּוֹ\":","וְאָסוּר לוֹ לָאָדָם לְהַפְקִיר אוֹ לְהַקְדִּישׁ כָּל נְכָסָיו וְיַטְרִיחַ עַל הַבְּרִיּוֹת. וְלֹא יִמְכֹּר שָׂדֶה וְיִקְנֶה בַּיִת וְלֹא בַּיִת וְיִקְנֶה מִטַּלְטְלִין אוֹ יַעֲשֶׂה סְחוֹרָה בִּדְמֵי בֵּיתוֹ. אֲבָל מוֹכֵר הוּא מִטַּלְטְלִין וְקוֹנֶה שָׂדֶה. כְּלָלוֹ שֶׁל דָּבָר יָשִׂים מְגַמָּתוֹ לְהַצְלִיחַ נְכָסָיו וּלְהַחֲלִיף הַכָּלֶה בְּקַיָּם. וְלֹא תִּהְיֶה כַּוָּנָתוֹ לֵהָנוֹת מְעַט לְפִי שָׁעָה אוֹ לֵהָנוֹת מְעַט וְיַפְסִיד הַרְבֵּה:","מַשָּׂאוֹ וּמַתָּנוֹ שֶׁל תַּלְמִיד חָכָם בֶּאֱמֶת וּבֶאֱמוּנָה. אוֹמֵר עַל לָאו לָאו וְעַל הֵן הֵן. מְדַקְדֵּק עַל עַצְמוֹ בְּחֶשְׁבּוֹן וְנוֹתֵן וּמְוַתֵּר לַאֲחֵרִים כְּשֶׁיִּקַּח מֵהֶן וְלֹא יְדַקְדֵּק עֲלֵיהֶן. וְנוֹתֵן דְּמֵי הַמִּקָּח לְאַלְתַּר וְאֵינוֹ נַעֲשֶׂה לֹא עָרֵב וְלֹא קַבְּלָן וְלֹא יָבוֹא בְּהַרְשָׁאָה. (אֵינוֹ) מְחַיֵּב עַצְמוֹ בְּדִבְרֵי מִקָּח וּמִמְכָּר בְּמָקוֹם שֶׁלֹּא חִיְּבָה אוֹתוֹ תּוֹרָה. כְּדֵי שֶׁיַּעֲמֹד בְּדִבּוּרוֹ וְלֹא יְשַׁנֵּהוּ. וְאִם נִתְחַיְּבוּ לוֹ אֲחֵרִים בַּדִּין מַאֲרִיךְ וּמוֹחֵל לָהֶן וּמַלְוֶה וְחוֹנֵן. וְלֹא יֵרֵד לְתוֹךְ אֻמָּנוּת חֲבֵרוֹ. וְלֹא יָצֵר לְאָדָם לְעוֹלָם בְּחַיָּיו. כְּלָלוֹ שֶׁל דָּבָר יִהְיֶה מִן הַנִּרְדָּפִים וְלֹא מִן הָרוֹדְפִים מִן הַנֶּעֱלָבִים וְלֹא מִן הָעוֹלְבִים. וְאָדָם שֶׁעוֹשֶׂה כָּל הַמַּעֲשִׂים הָאֵלּוּ וְכַיּוֹצֵא בָּהֶן עָלָיו הַכָּתוּב אוֹמֵר וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר:"],"Mishneh Torah, Immersion Pools 8":["כָּל הַמְעֹרָב לַמִּקְוֶה הֲרֵי הוּא כְּמִקְוֶה וּמַטְבִּילִין בּוֹ. גּוּמוֹת הַסְּמוּכוֹת לְפִי הַמִּקְוֶה וּמְקוֹם רַגְלֵי פַּרְסוֹת בְּהֵמָה שֶׁהָיוּ בָּהֶן מַיִם מְעֹרָבִין עִם מֵי הַמִּקְוֶה כִּשְׁפוֹפֶרֶת הַנּוֹד מַטְבִּילִין בָּהֶן:","חוֹרֵי הַמְּעָרָה וְסִדְקֵי הַמְּעָרָה מַטְבִּילִין בָּהֶן אַף עַל פִּי שֶׁאֵין הַמַּיִם שֶׁבָּהֶן מְעֹרָבִין עִם מֵי הַמִּקְוֶה אֶלָּא בְּכָל שֶׁהוּא:","מַחַט שֶׁהָיְתָה נְתוּנָה עַל מַעֲלוֹת הַמִּקְוֶה וְהָיָה מוֹלִיךְ וּמֵבִיא בַּמַּיִם כֵּיוָן שֶׁעָבַר עָלֶיהָ הַגַּל טְהוֹרָה:","עוּקָה שֶׁבְּתוֹךְ מִקְוֶה אִם הָיְתָה הַקַּרְקַע הַמַּבְדֶּלֶת בֵּין הָעוּקָה וְהַמִּקְוֶה בְּרִיאָה וִיכוֹלָה לְהַעֲמִיד אֶת עַצְמָהּ אֵין מַטְבִּילִין בַּמַּיִם שֶׁבָּעוּקָה עַד שֶׁיִּהְיוּ מְעֹרָבִין עִם הַמִּקְוֶה כִּשְׁפוֹפֶרֶת הַנּוֹד. וְאִם אֵינָהּ יְכוֹלָה לְהַעֲמִיד אֶת עַצְמָהּ אֲפִלּוּ אֵינָן מְעֹרָבִין אֶלָּא בְּכָל שֶׁהוּא מַטְבִּילִין בָּהֶן:","כֹּתֶל שֶׁבֵּין שְׁנֵי מִקְוָאוֹת שֶׁנִּסְדַּק לִשְׁנַיִם מִצְטָרְפִין וְאִם הָיָה בִּשְׁנֵיהֶן אַרְבָּעִים סְאָה מַטְבִּילִין בְּכָל אֶחָד מֵהֶן. וְאִם נִסְדַּק לָעֵרֶב אֵין מִצְטָרְפִין עַד שֶׁיִּהְיֶה בְּמָקוֹם אֶחָד כִּשְׁפוֹפֶרֶת הַנּוֹד. נִפְרַץ הַכֹּתֶל מִלְּמַעְלָה אִם נִתְעָרְבוּ הַמַּיִם לְמַעְלָה מִן הַכֹּתֶל כִּקְלִפַּת הַשּׁוּם עַל רֹחַב שְׁפוֹפֶרֶת הַנּוֹד מִצְטָרְפִין:","כַּמָּה הוּא שִׁעוּר הַנֶּקֶב שֶׁהוּא כִּשְׁפוֹפֶרֶת הַנּוֹד. בְּרֹחַב שְׁתֵּי אֶצְבָּעוֹת בֵּינוֹנִיּוֹת שֶׁל כָּל אָדָם וְחוֹזְרוֹת בּוֹ. וְאֵינָן בַּגּוּדָל אֶלָּא שְׁתֵּי אֶצְבָּעוֹת רִאשׁוֹנוֹת מִן הָאַרְבַּע שֶׁבְּפַס הַיָּד. כָּל שֶׁיַּעֲמֹד כִּשְׁפוֹפֶרֶת הַנּוֹד מְמַעֵט וַאֲפִלּוּ בִּדְבָרִים שֶׁהֵן מִבְּרִיָּתוֹ שֶׁל מַיִם. סָפֵק יֵשׁ בַּנֶּקֶב כִּשְׁפוֹפֶרֶת הַנּוֹד סָפֵק אֵין בּוֹ אֵין מִצְטָרְפִין מִפְּנֵי שֶׁעִקַּר הַטְּבִילָה מִן הַתּוֹרָה וְכָל שֶׁעִקָּרוֹ מִן הַתּוֹרָה אַף עַל פִּי שֶׁשִּׁעוּרוֹ הֲלָכָה סְפֵק שִׁעוּרוֹ לְהַחְמִיר:","מְטַהֲרִין אֶת הַמִּקְוָאוֹת הָעֶלְיוֹן מִן הַתַּחְתּוֹן וְהָרָחוֹק מִן הַקָּרוֹב. כֵּיצַד. מְבִיאִין סִילוֹן שֶׁל חֶרֶס אוֹ שֶׁל אֲבָר וְכַיּוֹצֵא בָּהֶן שֶׁאֵין הַסִּילוֹנוֹת פּוֹסְלִין אֶת הַמִּקְוֶה וּמַנִּיחַ אֶת יָדָיו תַּחְתָּיו עַד שֶׁיִּתְמַלֵּא מַיִם וּמוֹשְׁכוֹ וּמַשִּׁיקוֹ עַד שֶׁיִּתְעָרֵב הַמַּיִם שֶׁבַּסִּילוֹן עִם מֵי הַמִּקְוֶה כְּאֶחָד אֲפִלּוּ כְּשַׂעֲרָה דַּיּוֹ וַהֲרֵי שְׁנֵי הַמִּקְוָאוֹת שֶׁהַסִּילוֹן בֵּינֵיהֶן כְּמִקְוֶה אֶחָד:","שָׁלֹשׁ גֻּמּוֹת שֶׁבַּנַּחַל הַתַּחְתּוֹנָה וְהָעֶלְיוֹנָה שֶׁל עֶשְׂרִים סְאָה וְהָאֶמְצָעִית שֶׁל אַרְבָּעִים וְשֶׁטֶף שֶׁל גְּשָׁמִים עוֹבֵר בְּתוֹךְ הַנַּחַל אַף עַל פִּי שֶׁהוּא נִכְנָס לְתוֹכָן וְיוֹצֵא מִתּוֹכָן אֵין זֶה עֵרוּב. וְאֵין מַטְבִּילִין אֶלָּא בָּאֶמְצָעִית שֶׁאֵין הַמַּיִם הַנִּזְחָלִין מְעָרְבִין אֶלָּא אִם כֵּן עָמְדוּ:","טִיט רַךְ שֶׁהַפָּרָה שׁוֹחָה וְשׁוֹתָה מִמֶּנּוּ הֲרֵי זֶה נִמְדָּד עִם הַמִּקְוֶה. הָיָה עָבֶה עַד שֶׁאֵין הַפָּרָה שׁוֹחָה וְשׁוֹתָה אֵינוֹ נִמְדָּד עִמּוֹ:","מִקְוֶה שֶׁיֵּשׁ בּוֹ אַרְבָּעִים סְאָה מַיִם וְטִיט מַטְבִּילִין בַּטִּיט וּבַמַּיִם. בְּאֵי זֶה טִיט מַטְבִּילִין בַּטִּיט הָרַךְ שֶׁהַמַּיִם צָפִין עַל גַּבָּיו. הָיוּ הַמַּיִם מִצַּד אֶחָד וְהַטִּיט הָרַךְ מִצַּד אַחֵר מַטְבִּילִין בַּמַּיִם וְלֹא בַּטִּיט:","כָּל שֶׁתְּחִלַּת בְּרִיָּתוֹ מִן הַמַּיִם כְּגוֹן יַבְחוּשִׁין אֲדֻמִּין מַטְבִּילִין בּוֹ. וּמַטְבִּילִין בְּעֵינוֹ שֶׁל דָּג:","מִקְוֶה שֶׁיֵּשׁ בּוֹ אַרְבָּעִים סְאָה מְכֻוָּנוֹת וְיָרְדוּ שְׁנַיִם וְטָבְלוּ זֶה אַחַר זֶה אַף עַל פִּי שֶׁרַגְלָיו שֶׁל רִאשׁוֹן נוֹגְעוֹת בַּמַּיִם הָרִאשׁוֹן טָהוֹר וְהַשֵּׁנִי בְּטֻמְאָתוֹ שֶׁהֲרֵי חָסְרוּ הַמַּיִם מֵאַרְבָּעִים סְאָה. הִטְבִּיל בּוֹ תְּחִלָּה סָגוֹס עָבֶה וְכַיּוֹצֵא בּוֹ וְהִגְבִּיהוֹ אִם הָיְתָה מִקְצָת הַסָּגוֹס נוֹגַעַת בַּמַּיִם הֲרֵי הַטּוֹבֵל בָּאַחֲרוֹנָה טָהוֹר שֶׁהֲרֵי הַמַּיִם כֻּלָּן מְעֹרָבִין. הִטְבִּיל בּוֹ אֶת הַמִּטָּה וְכַיּוֹצֵא בָּהּ אַף עַל פִּי שֶׁדָּחַק רַגְלֵי הַמִּטָּה בְּטִיט עָבֶה שֶׁבְּקַרְקַע הַמִּקְוֶה עַד שֶׁצָּפוּ הַמַּיִם עָלֶיהָ לְמַעְלָה הֲרֵי זוֹ טְהוֹרָה שֶׁהֲרֵי לֹא נִטְבְּעוּ בַּטִּיט עַד שֶׁטָּבְלוּ בַּמַּיִם תְּחִלָּה. הִטְבִּיל בּוֹ יוֹרָה גְּדוֹלָה הֲרֵי זוֹ טְמֵאָה כְּשֶׁהָיְתָה מִפְּנֵי שֶׁהַמַּיִם נִתָּזִין וְיוֹצְאִין חוּץ לַמִּקְוֶה וְנִמְצָא חָסֵר מֵאַרְבָּעִים. כֵּיצַד יַעֲשֶׂה. מוֹרִידָהּ דֶּרֶךְ פִּיהָ וְהוֹפְכָהּ בַּמִּקְוֶה וּמַטְבִּילָהּ וּמַעֲלֶה אוֹתָהּ דֶּרֶךְ שׁוּלֶיהָ כְּדֵי שֶׁלֹּא יִהְיוּ הַמַּיִם שֶׁבְּתוֹכָהּ שְׁאוּבִים וְיַחְזְרוּ לַמִּקְוֶה וְיִפְסְלוּהוּ:","מִקְוֶה שֶׁמֵּימָיו מְרֻדָּדִין כּוֹבֵשׁ אֲפִלּוּ חֲבִילֵי קַשׁ וַחֲבִילֵי קָנִים בְּתוֹךְ הַמַּיִם וּמִן הַצְּדָדִין עַד שֶׁיֵּעָרְמוּ הַמַּיִם לְמַעְלָה וְיוֹרֵד וְטוֹבֵל לְתוֹכָן:"],"Mishneh Torah, Inheritances 9":["הָאַחִין שֶׁעֲדַיִן לֹא חָלְקוּ יְרֻשַּׁת אֲבִיהֶן אֶלָּא כֻּלָּן מִשְׁתַּמְּשִׁין בְּיַחַד בְּמַה שֶּׁהִנִּיחַ לָהֶן הֲרֵי הֵן כְּשֻׁתָּפִין לְכָל דָּבָר. וְכֵן בִּשְׁאָר הַיּוֹרְשִׁין הֲרֵי הֵן שֻׁתָּפִין בְּנִכְסֵי מוֹרִישָׁן. וְכָל שֶׁנָּשָׂא וְנָתַן כָּל אֶחָד מֵהֶן בְּמָמוֹן זֶה הַשָּׂכָר לָאֶמְצַע:","הָיוּ הַיּוֹרְשִׁין גְּדוֹלִים וּקְטַנִּים וְהִשְׁבִּיחוּ הַגְּדוֹלִים אֶת הַנְּכָסִים הִשְׁבִּיחוּ לָאֶמְצַע. אָמְרוּ רְאוּ מַה שֶּׁהִנִּיחַ לָנוּ אַבָּא וַהֲרֵי אָנוּ עוֹשִׂין וְאוֹכְלִין. הַשֶּׁבַח שֶׁל מַשְׁבִּיחַ. וְהוּא שֶׁיִּהְיֶה הַשֶּׁבַח מֵחֲמַת הוֹצָאָה שֶׁהוֹצִיא הַמַּשְׁבִּיחַ. אֲבָל שָׁבְחוּ נְכָסִים מֵחֲמַת עַצְמָן הַשֶּׁבַח לָאֶמְצַע:","וְכֵן אִם הָיְתָה אִשְׁתּוֹ שֶׁל מֵת הִיא הַיּוֹרֶשֶׁת בִּכְלַל אַחְיוֹתֶיהָ אוֹ בִּכְלַל בְּנוֹת דּוֹדֶיהָ וְהִשְׁבִּיחָה הַנְּכָסִים הַשֶּׁבַח לָאֶמְצַע. וְאִם אָמְרָה רְאוּ מַה שֶּׁהִנִּיחַ לִי בַּעְלִי וַהֲרֵינִי עוֹשָׂה וְאוֹכֶלֶת הִשְׁבִּיחַ הַנְּכָסִים מֵחֲמַת הוֹצָאָה הֲרֵי הַשֶּׁבַח שֶׁלָּהּ:","מִי שֶׁיָּרַשׁ אֶת אָבִיו וְהִשְׁבִּיחַ הַנְּכָסִים וְנָטַע וּבָנָה וְאַחַר כָּךְ נוֹדַע שֶׁיֵּשׁ לוֹ אַחִין בִּמְדִינָה אַחֶרֶת. אִם קְטַנִּים הֵן הַשֶּׁבַח לָאֶמְצַע וְאִם הָיוּ גְּדוֹלִים הוֹאִיל וְלֹא נוֹדַע שֶׁיֵּשׁ לוֹ אַחִין שָׁמִין לוֹ כְּאָרִיס. וְכֵן אָח שֶׁיָּרַד לְנִכְסֵי קָטָן וְהִשְׁבִּיחַ אֵין שָׁמִין לוֹ כְּאָרִיס. אֶלָּא הַשֶּׁבַח לָאֶמְצַע שֶׁהֲרֵי לֹא בִּרְשׁוּת יָרַד:","אֶחָד מִן הָאַחִין שֶׁלָּקַח מָעוֹת וְעָשָׂה בָּהֶן סְחוֹרָה אִם הָיָה תַּלְמִיד חָכָם גָּדוֹל שֶׁאֵינוֹ מַנִּיחַ תּוֹרָתוֹ שָׁעָה אַחַת. הֲרֵי הַשָּׂכָר שֶׁלּוֹ שֶׁאֵין זֶה מַנִּיחַ תּוֹרָתוֹ וּמִתְעַסֵּק לְצֹרֶךְ אֶחָיו:","אֶחָד מִן הָאַחִין שֶׁמִּנָּהוּ הַמֶּלֶךְ גַּבַּאי אוֹ סוֹפֵר שֶׁמַּכְנִיס וּמוֹצִיא בְּמָמוֹן הַמֶּלֶךְ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה מֵעֲבוֹדַת הַמְּלָכִים. אִם מֵחֲמַת אֲבִיהֶן מִנָּהוּ כְּגוֹן שֶׁהָיָה אֲבִיהֶן יָדוּעַ בְּדָבָר זֶה וְאָמַר נַעֲמִיד תַּחְתָּיו בְּנוֹ כְּדֵי לַעֲשׂוֹת חֶסֶד עִם הַיְתוֹמִים. הַפְּרָס שֶׁיִּטּל וְכָל הַשָּׂכָר שֶׁיִּשְׂתַּכֵּר בַּעֲבוֹדָה לְכָל הָאַחִין. וַאֲפִלּוּ הָיָה חָכָם בְּיוֹתֵר וְרָאוּי לְמַנּוֹתוֹ. וְאִם מֵחֲמַת עַצְמוֹ מִנּוּהוּ הֲרֵי זֶה לְעַצְמוֹ:","אֶחָד מִן הָאַחִין שֶׁהָיָה נוֹשֵׂא וְנוֹתֵן בְּתוֹךְ הַבַּיִת וְקָנָה עֲבָדִים בִּשְׁמוֹ לְבַדּוֹ. הִלְוָה לַאֲחֵרִים וְהָיָה שְׁטַר הַחוֹב בִּשְׁמוֹ לְבַדּוֹ. וְאָמַר מָעוֹת אֵלּוּ שֶׁהִלְוֵיתִי אוֹ שֶׁקָּנִיתִי בָּהֶן עֲבָדִים אֵלּוּ שֶׁלִּי לְבַדִּי הֵן שֶׁנָּפְלוּ לִי מִבֵּית אָבִי אִמִּי. אוֹ מְצִיאָה מָצָאתִי אוֹ מַתָּנָה נִתְּנָה לִי. עָלָיו לְהָבִיא רְאָיָה שֶׁנָּפְלָה לוֹ יְרֻשָּׁה אַחֶרֶת אוֹ מָצָא מְצִיאָה אוֹ זָכָה בְּמַתָּנָה. וְכֵן הָאִשָּׁה שֶׁהָיְתָה נוֹשֵׂאת וְנוֹתֶנֶת בְּתוֹךְ הַבַּיִת וְהָיוּ אוֹנוֹת שֶׁהֵן שִׁטְרֵי מִמְכַּר עֲבָדִים וְשִׁטְרֵי חוֹבוֹת יוֹצְאוֹת עַל שְׁמָהּ. וְאָמְרָה שֶׁלִּי הֵן שֶׁנָּפְלוּ לִי מִבֵּית אֲבוֹתַי. עָלֶיהָ לְהָבִיא רְאָיָה שֶׁנָּפְלוּ לָהּ לִירֻשָּׁה. וְכֵן אַלְמָנָה שֶׁהָיְתָה נוֹשֵׂאת וְנוֹתֶנֶת בְּנִכְסֵי יְתוֹמִים וְהָיוּ אוֹנוֹת וּשְׁטָרוֹת יוֹצְאוֹת עַל שְׁמָהּ וְאָמְרָה מִירֻשָּׁה נָפְלוּ לִי אוֹ מְצִיאָה מָצָאתִי אוֹ מַתָּנָה נִתְּנָה לִי. עָלֶיהָ לְהָבִיא רְאָיָה. וְאִם יֵשׁ לָהּ נְדוּנְיָא וְאָמְרָה מִנְּדוּנְיָתִי לָקַחְתִּי נֶאֱמֶנֶת אֲבָל אִם אֵין לָהּ נְדוּנְיָא וְלֹא הֵבִיאָה רְאָיָה הֲרֵי הַכּל בְּחֶזְקַת הַיּוֹרְשִׁין:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּאַחִים וּבְאַלְמָנָה שֶׁאֵין חֲלוּקִין בְּעִסָּתָן. אֲבָל אִם הָיוּ חֲלוּקִין בְּעִסָּתָן שֶׁמָּא מֵעִסָּתוֹ קָמַץ וְעַל הָאַחִין לְהָבִיא רְאָיָה שֶׁהֵן מִשֶּׁל אֶמְצַע. וְכֵן אִם מֵת זֶה הַנּוֹתֵן וְהַנּוֹשֵׂא בְּתוֹךְ הַבַּיִת עַל הָאַחִין לְהָבִיא רְאָיָה אַף עַל פִּי שֶׁלֹּא הָיוּ חֲלוּקִין בְּעִסָּתָן:","אֶחָד מִן הָאַחִין שֶׁשְּׁטַר חוֹב יוֹצֵא מִתַּחַת יָדוֹ עָלָיו לְהָבִיא רְאָיָה שֶׁאָבִיו נְתָנוֹ לוֹ בִּכְתִיבָה וּמְסִירָה. אוֹ שֶׁצִּוָּה לוֹ בּוֹ כְּשֶׁהוּא שְׁכִיב מֵרַע. וְאִם לֹא הֵבִיא רְאָיָה הֲרֵי הוּא לָאֶמְצַע:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּאַחִין מִפְּנֵי שֶׁחֶזְקָתָן שׁוֹמְטִין זֶה מִזֶּה. אֲבָל אַחֵר שֶׁטָּעַן שֶׁנָּתַן לוֹ אוֹ שֶׁקָּנָהוּ מִבְּעָלָיו גּוֹבֶה בּוֹ וְאֵינוֹ צָרִיךְ לְהָבִיא רְאָיָה:","אֶחָד מִן הָאַחִין שֶׁנָּטַל מָאתַיִם זוּז לִלְמֹד תּוֹרָה אוֹ לִלְמֹד אֻמָּנוּת יְכוֹלִין הָאַחִין לוֹמַר לוֹ אִם אֵין אַתָּה אֶצְלֵנוּ אֵין לְךָ מְזוֹנוֹת אֶלָּא לְפִי בִּרְכַּת הַבַּיִת. שֶׁאֵין הוֹצָאַת מְזוֹנוֹת הָאֶחָד לְבַדּוֹ כְּהוֹצָאַת מְזוֹנוֹתָיו בֵּין רַבִּים:","מִי שֶׁמֵּת וְהִנִּיחַ בָּנִים גְּדוֹלִים וּקְטַנִּים אֵין הַגְּדוֹלִים מִתְפַּרְנְסִים פַּרְנָסַת הַקְּטַנִּים וְלֹא הַקְּטַנִּים נִזּוֹנִים מְזוֹנוֹת הַגְּדוֹלִים אֶלָּא חוֹלְקִים בְּשָׁוֶה. נִשְּׂאוּ גְּדוֹלִים לְאַחַר מִיתַת אֲבִיהֶן יִשְׂאוּ הַקְּטַנִּים כֵּן מִכְּלַל הַנְּכָסִים וְאַחַר כָּךְ יַחֲלֹקוּ. נִשְּׂאוּ הַגְּדוֹלִים בְּחַיֵּי אֲבִיהֶן וְאָמְרוּ הַקְּטַנִּים לְאַחַר מִיתַת אֲבִיהֶן הֲרֵי אָנוּ נוֹשְׂאִין כְּדֶרֶךְ שֶׁנְּשָׂאתֶם אַתֶּם. אֵין שׁוֹמְעִין לָהֶן אֶלָּא מַה שֶּׁנָּתַן לָהֶם אֲבִיהֶם נָתַן:","הִשִּׂיא הָאָב אֶת בְּנוֹ וְעָשָׂה לוֹ מִשְׁתֶּה וְהָיְתָה הַהוֹצָאָה מִשֶּׁל אָב וְנִשְׁתַּלְּחָה שׁוֹשְׁבִינוּת לְזֶה הַבֵּן בְּחַיֵּי הָאָב. כְּשֶׁהִיא חוֹזֶרֶת לְאַחַר מִיתַת הָאָב חוֹזֶרֶת לָאֶמְצַע. אֲבָל הוֹצִיא הַבֵּן בַּמִּשְׁתֶּה מִשֶּׁלּוֹ אֵינָהּ חוֹזֶרֶת אֶלָּא מֵחֵלֶק הַבֵּן שֶׁנִּשְׁתַּלְּחָה לוֹ בִּלְבַד:","הָאָב שֶׁשָּׁלַח שׁוֹשְׁבִינוּת בְּשֵׁם אֶחָד מִבָּנָיו כְּשֶׁתַּחְזֹר הַשּׁוֹשְׁבִינוּת לְאוֹתוֹ הַבֵּן הֲרֵי הִיא שֶׁלּוֹ. אֲבָל אִם שְׁלָחָהּ הָאָב בְּשֵׁם בָּנָיו סְתָם כְּשֶׁתַּחְזֹר תַּחְזֹר לָאֶמְצַע. וְאֵין זֶה שֶׁנִּשְׁתַּלְּחָה לוֹ חַיָּב לְהַחְזִירָהּ עַד שֶׁיִּשְׂמְחוּ עִמּוֹ הַבָּנִים כֻּלָּן. שֶׁהֲרֵי כֻּלָּן שׁוֹשְׁבִינִין שֶׁבְּשֵׁם כֻּלָּן נִשְׁתַּלְּחָה. לְפִיכָךְ אִם שָׂמֵחַ בְּמִקְצָתָן מַחְזִיר חֵלֶק זֶה שֶׁשָּׂמַח עִמּוֹ בִּלְבַד וַהֲרֵי הוּא לָאֶמְצַע:","גְּדוֹל הָאַחִין שֶׁהָיָה לוֹבֵשׁ וּמִתְכַּסֶּה מַלְבּוּשִׁין נָאִים אִם יֵשׁ לָאַחִים הֲנָאָה מִמֶּנּוּ כְּדֵי שֶׁיִּהְיוּ דְּבָרָיו נִשְׁמָעִין הֲרֵי זֶה לוֹבֵשׁ מִתְּפִיסַת הַבַּיִת:"],"Mishneh Torah, Kings and Wars 9":["עַל שִׁשָּׁה דְּבָרִים נִצְטַוָּה אָדָם הָרִאשׁוֹן. עַל עֲבוֹדָה זָרָה. וְעַל בִּרְכַּת הַשֵּׁם. וְעַל שְׁפִיכוּת דָּמִים. וְעַל גִּלּוּי עֲרָיוֹת. וְעַל הַגֵּזֶל. וְעַל הַדִּינִים. אַף עַל פִּי שֶׁכֻּלָּן הֵן קַבָּלָה בְּיָדֵינוּ מִמּשֶׁה רַבֵּנוּ. וְהַדַּעַת נוֹטָה לָהֶן. מִכְּלַל דִּבְרֵי תּוֹרָה יֵרָאֶה שֶׁעַל אֵלּוּ נִצְטַוָּה. הוֹסִיף לְנֹחַ אֵבֶר מִן הַחַי שֶׁנֶּאֱמַר (בראשית ט, ד) \"אַךְ בָּשָׂר בְּנַפְשׁוֹ דָמוֹ לֹא תֹאכֵלוּ\". נִמְצְאוּ שֶׁבַע מִצְוֹת. וְכֵן הָיָה הַדָּבָר בְּכָל הָעוֹלָם עַד אַבְרָהָם. בָּא אַבְרָהָם וְנִצְטַוָּה יֶתֶר עַל אֵלּוּ בְּמִילָה. וְהוּא הִתְפַּלֵּל שַׁחֲרִית. וְיִּצְחָק הִפְרִישׁ מַעֲשֵׂר וְהוֹסִיף תְּפִלָּה אַחֶרֶת לִפְנוֹת הַיּוֹם. וְיַעֲקֹב הוֹסִיף גִּיד הַנָּשֶׁה וְהִתְפַּלֵּל עַרְבִית. וּבְמִצְרַיִם נִצְטַוָּה עַמְרָם בְּמִצְוֹת יְתֵרוֹת. עַד שֶׁבָּא משֶׁה רַבֵּנוּ וְנִשְׁלְמָה תּוֹרָה עַל יָדוֹ:","בֶּן נֹחַ שֶׁעָבַד עֲבוֹדָה זָרָה הֲרֵי זֶה חַיָּב. וְהוּא שֶׁיַּעֲבֹד כְּדַרְכָּהּ. וְכָל עֲבוֹדָה זָרָה שֶׁבֵּית דִּין שֶׁל יִשְׂרָאֵל מְמִיתִין עָלֶיהָ בֶּן נֹחַ נֶהֱרָג עָלֶיהָ. וְכָל שֶׁאֵין בֵּית דִּין שֶׁל יִשְׂרָאֵל מְמִיתִין עָלֶיהָ אֵין בֶּן נֹחַ נֶהֱרָג עָלֶיהָ. וְאַף עַל פִּי שֶׁאֵינוֹ נֶהֱרָג אָסוּר בַּכּל. וְאֵין מְנִיחִין אוֹתוֹ לְהָקִים מַצֵּבָה. וְלֹא לִטַּע אֲשֵׁרָה. וְלֹא לַעֲשׂוֹת צוּרוֹת וְכַיּוֹצֵא בָּהֶן לְנוֹי:","בֶּן נֹחַ שֶׁבֵּרֵךְ אֶת הַשֵּׁם. בֵּין שֶׁבֵּרֵךְ בַּשֵּׁם הַמְיֻחָד. בֵּין שֶׁבֵּרֵךְ בְּכִנּוּי בְּכָל לָשׁוֹן חַיָּב. מַה שֶּׁאֵין כֵּן בְּיִשְׂרָאֵל:","בֶּן נֹחַ שֶׁהָרַג נֶפֶשׁ אֲפִלּוּ עֵבָּר בִּמְעֵי אִמּוֹ נֶהֱרָג עָלָיו. וְכֵן אִם הָרַג טְרֵפָה אוֹ שֶׁכְּפָתוֹ וּנְתָנוֹ לִפְנֵי אֲרִי אוֹ שֶׁהִנִּיחוֹ בָּרָעָב עַד שֶׁמֵּת. הוֹאִיל וְהֵמִית מִכָּל מָקוֹם נֶהֱרָג. וְכֵן אִם הָרַג רוֹדֵף שֶׁיָּכוֹל לְהַצִּילוֹ בְּאֶחָד מֵאֵיבָרָיו נֶהֱרָג עָלָיו. מַה שֶּׁאֵין כֵּן בְּיִשְׂרָאֵל:","שֵׁשׁ עֲרָיוֹת אֲסוּרוֹת עַל בְּנֵי נֹחַ. הָאֵם. וְאֵשֶׁת הָאָב. וְאֵשֶׁת אִישׁ. וַאֲחוֹתוֹ מֵאִמּוֹ. וְזָכוּר. וּבְהֵמָה. שֶׁנֶּאֱמַר (בראשית ב, כד) \"עַל כֵּן יַעֲזָב אִישׁ אֶת אָבִיו\" זוֹ אֵשֶׁת אָבִיו. (בראשית ב, כד) \"וְאֶת אִמּוֹ\" כְּמַשְׁמָעָהּ. (בראשית ב, כד) \"וְדָבַק בְּאִשְׁתּוֹ\" וְלֹא בְּאֵשֶׁת חֲבֵרוֹ. בְּאִשְׁתּוֹ וְלֹא בְּזָכוּר. (בראשית ב, כד) \"וְהָיוּ לְבָשָׂר אֶחָד\" לְהוֹצִיא בְּהֵמָה חַיָּה וְעוֹף שֶׁאֵין הוּא וְהֵם בָּשָׂר אֶחָד. וְנֶאֱמַר (בראשית כ, יב) \"אֲחֹתִי בַת אָבִי הִיא אַךְ לֹא בַת אִמִּי וַתְּהִי לִי לְאִשָּׁה\":","בֶּן נֹחַ חַיָּב עַל מְפֻתַּת אָבִיו וַאֲנוּסַת אָבִיו הֲרֵי הִיא אִמּוֹ מִכָּל מָקוֹם. וְחַיָּב עַל אֵשֶׁת אָבִיו אֲפִלּוּ לְאַחַר מִיתַת אָבִיו. וְחַיָּב עַל הַזָּכוּר בֵּין קָטָן בֵּין גָּדוֹל וְעַל הַבְּהֵמָה בֵּין קְטַנָּה בֵּין גְּדוֹלָה. וְהוּא נֶהֱרָג לְבַדּוֹ וְאֵין הוֹרְגִין אֶת הַבְּהֵמָה. שֶׁלֹּא נִצְטַוּוּ בַּהֲרִיגַת בְּהֵמָה אֶלָּא יִשְׂרָאֵל:","אֵין בֶּן נֹחַ חַיָּב עַל אֵשֶׁת חֲבֵרוֹ עַד שֶׁיָּבוֹא עָלֶיהָ כְּדַרְכָּהּ אַחַר שֶׁנִּבְעֲלָה לְבַעְלָהּ. אֲבָל מְאֹרָסָה אוֹ שֶׁנִּכְנְסָה לְחֻפָּה וְלֹא נִבְעֲלָה אֵין חַיָּבִין עָלֶיהָ. שֶׁנֶּאֱמַר (בראשית כ, ג) \"וְהִיא בְּעֻלַת בָּעַל\". בַּמֶּה דְּבָרִים אֲמוּרִים בְּבֶן נֹחַ שֶׁבָּא עַל בַּת נֹחַ. אֲבָל עַכּוּ\"ם הַבָּא עַל הַיִּשְׂרְאֵלִית בֵּין כְּדַרְכָּהּ בֵּין שֶׁלֹּא כְּדַרְכָּהּ חַיָּב. וְאִם הָיְתָה נַעֲרָה מְאֹרָסָה נִסְקָל עָלֶיהָ כְּדִינֵי יִשְׂרָאֵל. בָּא עָלֶיהָ אַחַר שֶׁנִּכְנְסָה לַחֻפָּה וְלֹא נִבְעֲלָה הֲרֵי זֶה בְּחֶנֶק כְּדִינֵי יִשְׂרָאֵל. אֲבָל אִם בָּא עַל אֵשֶׁת יִשְׂרָאֵל אַחַר שֶׁנִּבְעֲלָה הֲרֵי זֶה כְּמִי שֶׁבָּא עַל אֵשֶׁת עַכּוּ\"ם חֲבֵרוֹ וְיֵהָרֵג בְּסַיִף:","בֶּן נֹחַ שֶׁיִּחֵד שִׁפְחָה לְעַבְדּוֹ וּבָא עָלֶיהָ הֲרֵי זֶה נֶהֱרָג עָלֶיהָ מִשּׁוּם אֵשֶׁת חֲבֵרוֹ. וְאֵינוֹ חַיָּב עָלֶיהָ עַד שֶׁיִּפְשֹׁט הַדָּבָר וְיֹאמְרוּ לָהּ הָעָם זוֹ דְּבֵית עֶבֶד פְּלוֹנִי. וּמֵאֵימָתַי תַּחְזֹר לְהֶתֵּרָהּ מִשֶּׁיַּפְרִישֶׁנָּה מֵעַבְדּוֹ וְיִפְרַע רֹאשָׁהּ בַּשּׁוּק. וּמֵאֵימָתַי תִּהְיֶה אֵשֶׁת חֲבֵרוֹ כִּגְרוּשָׁה שֶׁלָּנוּ מִשֶּׁיּוֹצִיאֶנָּה מִבֵּיתוֹ וִישַׁלְּחֶנָּה לְעַצְמָהּ. אוֹ מִשֶּׁתֵּצֵא הִיא מִתַּחַת רְשׁוּתוֹ וַתֵּלֶךְ לָהּ. שֶׁאֵין לָהֶם גֵּרוּשִׁין בִּכְתָב. וְאֵין הַדָּבָר תָּלוּיִ בּוֹ לְבַד. אֶלָּא כָּל זְמַן שֶׁיִּרְצֶה הוּא אוֹ הִיא לִפְרשׁ זֶה מִזֶּה פּוֹרְשִׁין:","בֶּן נֹחַ חַיָּב עַל הַגֵּזֶל. בֵּין שֶׁגָּזַל עַכּוּ\"ם בֵּין שֶׁגָּזַל יִשְׂרָאֵל. וְאֶחָד הַגּוֹזֵל אוֹ הַגּוֹנֵב מָמוֹן אוֹ גּוֹנֵב נֶפֶשׁ אוֹ הַכּוֹבֵשׁ שְׂכַר שָׂכִיר וְכַיּוֹצֵא בּוֹ. אֲפִלּוּ פּוֹעֵל שֶׁאָכַל שֶׁלֹּא בִּשְׁעַת מְלָאכָה. עַל הַכּל הוּא חַיָּב וַהֲרֵי הוּא בִּכְלַל גַּזְלָן. מַה שֶּׁאֵין כֵּן בְּיִשְׂרָאֵל. וְכֵן חַיָּב עַל פָּחוֹת מִשְּׁוֵה פְּרוּטָה. וּבֶן נֹחַ שֶׁגָּזַל פָּחוֹת מִשְּׁוֵה פְּרוּטָה וּבָא אַחֵר וּגְזָלָהּ מִמֶּנּוּ. שְׁנֵיהֶן נֶהֱרָגִין עָלֶיהָ:","וְכֵן חַיָּב עַל אֵבֶר מִן הַחַי וְעַל בָּשָׂר מִן הַחַי בְּכָל שֶׁהוּא. שֶׁלֹּא נִתְּנוּ הַשִּׁעוּרִין אֶלָּא לְיִשְׂרָאֵל בִּלְבַד. וּמֻתָּר הוּא בְּדָם מִן הַחַי:","אֶחָד הָאֵבֶר אוֹ הַבָּשָׂר הַפּוֹרֵשׁ מִן הַבְּהֵמָה אוֹ מִן הַחַיָּה. אֲבָל הָעוֹף יֵרָאֶה לִי שֶׁאֵין בֶּן נֹחַ נֶהֱרָג עַל אֵבֶר מִן הַחַי מִמֶּנּוּ:","הַשּׁוֹחֵט אֶת הַבְּהֵמָה אֲפִלּוּ שָׁחַט בָּהּ שְׁנֵי הַסִּימָנִין. כָּל זְמַן שֶׁהִיא מְפַרְכֶּסֶת אֵבֶר וּבָשָׂר הַפּוֹרְשִׁין מִמֶּנָּה אֲסוּרִין לִבְנֵי נֹחַ מִשּׁוּם אֵבֶר מִן הַחַי:","כָּל שֶׁאָסוּר עַל יִשְׂרָאֵל מִשּׁוּם אֵבֶר מִן הַחַי אָסוּר עַל בְּנֵי נֹחַ. וְיֵשׁ שֶׁבְּנֵי נֹחַ חַיָּבִין וְלֹא יִשְׂרָאֵל. שֶׁבְּנֵי נֹחַ אֶחָד בְּהֵמָה וְחַיָּה בֵּין טְמֵאָה בֵּין טְהוֹרָה חַיָּבִין עָלֶיהָ מִשּׁוּם אֵבֶר מִן הַחַי. וּמִשּׁוּם בָּשָׂר מִן הַחַי. וְאֵבֶר וּבָשָׂר הַפּוֹרְשִׁין מִן הַמְפַרְכֶּסֶת אַף עַל פִּי שֶׁשָּׁחַט בָּהּ יִשְׂרָאֵל שְׁנֵי סִימָנִין הֲרֵי זֶה אָסוּר לִבְנֵי נֹחַ מִשּׁוּם אֵבֶר מִן הַחַי:","וְכֵיצַד מְצֻוִּין הֵן עַל הַדִּינִין. חַיָּבִין לְהוֹשִׁיב דַּיָּנִין וְשׁוֹפְטִים בְּכָל פֶּלֶךְ וּפֶלֶךְ לָדוּן בְּשֵׁשׁ מִצְוֹת אֵלּוּ. וּלְהַזְהִיר אֶת הָעָם. וּבֶן נֹחַ שֶׁעָבַר עַל אַחַת מִשֶּׁבַע מִצְוֹת אֵלּוּ יֵהָרֵג בְּסַיִף. וּמִפְּנֵי זֶה נִתְחַיְּבוּ כָּל בַּעֲלֵי שְׁכֶם הֲרִיגָה. שֶׁהֲרֵי שְׁכֶם גָּזַל וְהֵם רָאוּ וְיָדְעוּ וְלֹא דָּנוּהוּ. וּבֶן נֹחַ נֶהֱרָג בְּעֵד אֶחָד וּבְדַיָּן אֶחָד בְּלֹא הַתְרָאָה וְעַל פִּי קְרוֹבִין. אֲבָל לֹא בְּעֵדוּת אִשָּׁה. וְלֹא תָּדוּן אִשָּׁה לָהֶם:"],"Mishneh Torah, Levirate Marriage and Release 3":["הָאוֹמֵר זֶה בְּנִי אוֹ שֶׁאָמַר יֵשׁ לִי בָּנִים הֲרֵי זֶה נֶאֱמָן וּפוֹטֵר אֶת אִשְׁתּוֹ מִן הַחֲלִיצָה וּמִן הַיִּבּוּם:","אָמַר זֶה אָחִי אוֹ שֶׁאָמַר יֵשׁ לִי אַחִין אֵינוֹ נֶאֱמָן לֶאֱסֹר אֶת אִשְׁתּוֹ וּלְהַנִּיחָהּ זְקוּקָה לְיָבָם שֶׁהֲרֵי זֶה מִתְכַּוֵּן לְאָסְרָהּ לְאַחַר מוֹתוֹ:","הָיָה מֻחְזָק שֶׁיֵּשׁ לוֹ אַחִין וְאָמַר בִּשְׁעַת מִיתָתוֹ אֵין לִי אַחִין אֵינוֹ נֶאֱמָן. וְכֵן אִם אָמַר עַל מִי שֶׁהֻחְזַק אָחִיו אֵין זֶה אָחִי אֵינוֹ נֶאֱמָן. לֹא הָיָה מֻחְזָק בְּאַחִין וְיָצָא קוֹל שֶׁיֵּשׁ [שָׁם] עֵדִים שֶׁיָּעִידוּ שֶׁיֵּשׁ לְבַעְלָהּ אַחִין וְהָעֵדִים בִּמְדִינָה אַחֶרֶת. אֲפִלּוּ אָמַר הוּא בִּשְׁעַת מִיתָתוֹ אֵין לִי אָח הֲרֵי זוֹ חוֹשֶׁשֶׁת וְתַמְתִּין עַד שֶׁיָּבוֹאוּ הָעֵדִים שֶׁאָמְרוּ וְיִשְׁאֲלוּ:","מִי שֶׁזָּנָה עִם אִשָּׁה בֵּין פְּנוּיָה בֵּין אֵשֶׁת אִישׁ וְנִתְעַבְּרָה וְאָמַר זֶה הָעֻבָּר מִמֶּנִּי הוּא וַאֲפִלּוּ הִיא מוֹדָה לוֹ אַף עַל פִּי שֶׁהוּא בְּנוֹ לְעִנְיַן יְרֻשָּׁה הֲרֵי זֶה סָפֵק לְעִנְיַן יִבּוּם. כְּשֵׁם שֶׁזִּנְּתָה עִם זֶה כָּךְ זִנְּתָה עִם אַחֵר. וּמֵאַיִן יִוָּדַע הַדָּבָר שֶׁזֶּה בְּנוֹ וַדַּאי וַהֲרֵי אֵין לוֹ חֲזָקָה. אֶלָּא לְעוֹלָם סָפֵק הוּא וּלְהַחֲמִיר דָּנִין בּוֹ וְחוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:","נֶאֱמָן עֵד אֶחָד לְהָעִיד לִיבָמָה שֶׁמֵּת בַּעְלָהּ וּמִתְיַבֶּמֶת עַל פִּיו. אוֹ שֶׁמֵּת יְבָמָהּ אוֹ שֶׁנִּתַּן לְבַעְלָהּ בֵּן, לְהַתִּירָהּ לְזָר. אֲפִלּוּ עֶבֶד אוֹ אִשָּׁה אוֹ עַכּוּ״‎ם מֵסִיחַ לְפִי תֻּמּוֹ מֵעִיד בְּמִיתַת הַיָּבָם כְּמוֹ שֶׁמֵּעִיד בְּאֵשֶׁת אִישׁ לְהַתִּירָהּ כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת גֵּרוּשִׁין:","וְחָמֵשׁ נָשִׁים שֶׁאֵין מְעִידוֹת זוֹ לָזוֹ שֶׁמֵּת בַּעְלָהּ כָּךְ אֵין מְעִידִין לָהּ שֶׁמֵּת יְבָמָהּ. וְדִין עֵדוּת זוֹ כְּדִין אוֹתָהּ עֵדוּת לְעִנְיַן עֵדִים שֶׁמַּכְחִישִׁין זֶה אֶת זֶה בְּמִיתַת הַיָּבָם וּלְכָל דָּבָר:","שְׁתֵּי יְבָמוֹת שֶׁבָּאוּ מִמְּדִינַת הַיָּם זוֹ אוֹמֶרֶת מֵת בַּעְלִי וְזוֹ אוֹמֶרֶת מֵת בַּעְלִי. זוֹ אֲסוּרָה מִפְּנֵי בַּעְלָהּ שֶׁל זוֹ וְזוֹ אֲסוּרָה מִפְּנֵי בַּעְלָהּ שֶׁל זוֹ. שֶׁאֵין יְבִמְתָּהּ נֶאֱמֶנֶת לְהָעִיד לָהּ שֶׁמֵּת יְבָמָהּ כְּמוֹ שֶׁבֵּאַרְנוּ:","הָיָה לְאַחַת מֵהֶן עֵד שֶׁמֵּת בַּעְלָהּ. זוֹ שֶׁיֵּשׁ לָהּ הָעֵד עוֹמֶדֶת בְּאִסּוּרָהּ שֶׁאֵינָהּ אֲסוּרָה מִפְּנֵי בַּעְלָהּ אֶלָּא מִפְּנֵי יְבָמָהּ. וְזוֹ שֶׁאֵין לָהּ עֵד מֻתֶּרֶת שֶׁהֲרֵי הֵעִיד הָעֵד שֶׁמֵּת יְבָמָהּ וְהִיא נֶאֱמֶנֶת לוֹמַר שֶׁמֵּת בַּעְלִי:","הָיָה לָזוֹ בָּנִים וְלָזוֹ אֵין בָּנִים זוֹ שֶׁאֵין לָהּ בָּנִים אֲסוּרָה וְזוֹ שֶׁיֵּשׁ לָהּ בָּנִים מֻתֶּרֶת. הָיָה לָהֶן יָבָם אַחֵר כָּאן הֲרֵי זֶה מְיַבֵּם לִשְׁתֵּיהֶן:","מֵת זֶה הַיָּבָם שֶׁיִּבֵּם אוֹתָן אֲסוּרוֹת לְהִנָּשֵׂא לְזָר כְּשֶׁהָיוּ בַּתְּחִלָּה. נִתְיַבְּמוּ וְנִתְגָּרְשׁוּ הֲרֵי אֵלּוּ מֻתָּרוֹת לְזָר:","אַף עַל פִּי שֶׁהָאִשָּׁה נֶאֱמֶנֶת לוֹמַר מֵת בַּעְלִי וְתִנָּשֵׂא אוֹ תִּתְיַבֵּם אֵין הַיְבָמָה נֶאֱמֶנֶת לוֹמַר מֵת יְבָמִי שֶׁתִּנָּשֵׂא לְזָר הוֹאִיל וְהוּא אִסּוּר לָאו שֶׁמָּא יִהְיֶה קַל בְּעֵינֶיהָ. וְכֵן אֵין הַיָּבָם נֶאֱמָן לוֹמַר מֵת אָחִי שֶׁיְּיַבֵּם אֶת אִשְׁתּוֹ שֶׁמָּא עֵינָיו נָתַן בָּהּ. וְאֵין הָאִשָּׁה נֶאֱמֶנֶת לוֹמַר מֵתָה אֲחוֹתִי שֶׁתִּכָּנֵס לְבֵיתָהּ. וְאֵין הָאִישׁ נֶאֱמָן לוֹמַר מֵתָה אִשְׁתִּי שֶׁיִּשָּׂא אֶת אֲחוֹתָהּ עַד שֶׁיָּעִידוּ שְׁנֵי עֵדִים שֶׁמֵּתָה אֲחוֹתָהּ וְאַחַר כָּךְ תִּכָּנֵס לְבֵיתָהּ. שֶׁלֹּא הֶאֱמִינוּ עֵד אֶחָד אֶלָּא מִשּׁוּם הַתָּרַת עֲגוּנָה כְּמוֹ שֶׁבֵּאַרְנוּ:","לְפִיכָךְ הָאִשָּׁה שֶׁהָלְכָה הִיא וּבַעְלָהּ וִיבָמָהּ לִמְדִינַת הַיָּם וּבָאָה וְאָמְרָה מֵת בַּעְלִי וְאַחַר כָּךְ מֵת יְבָמִי. אוֹ שֶׁאָמְרָה מֵת יְבָמִי וְאַחַר כָּךְ מֵת בַּעְלִי הֲרֵי זוֹ אֵינָהּ נֶאֱמֶנֶת. אֲבָל אִם הָלְכָה הִיא וּבַעְלָהּ בִּלְבַד וּבָאָה וְאָמְרָה נִתַּן לִי יָבָם בִּמְדִינַת הַיָּם וָמֵת. בֵּין שֶׁאָמְרָה מֵת יְבָמִי וְאַחַר כָּךְ מֵת בַּעְלִי בֵּין שֶׁאָמְרָה מֵת בַּעְלִי וְאַחַר כָּךְ מֵת הַיָּבָם שֶׁנִּתַּן לִי הֲרֵי זוֹ נֶאֱמֶנֶת שֶׁהַפֶּה שֶׁאָסַר הוּא הַפֶּה שֶׁהִתִּיר:","הָאִשָּׁה שֶׁהָלְכָה הִיא וּבַעְלָהּ וּבְנָהּ לִמְדִינַת הַיָּם וּבָאָה וְאָמְרָה מֵת בַּעְלִי וְאַחַר כָּךְ מֵת בְּנִי נֶאֱמֶנֶת. שֶׁהֲרֵי הָיְתָה בְּחֶזְקַת הֶתֵּר לְזָר בְּעֵת שֶׁהָלְכָה. אָמְרָה מֵת בְּנִי וְאַחַר כָּךְ מֵת בַּעְלִי אֵינָהּ נֶאֱמֶנֶת לְהִתְיַבֵּם וְחוֹשְׁשִׁין לִדְבָרֶיהָ וְחוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:","הָלְכָה הִיא וּבַעְלָהּ בִּלְבַד וּבָאָה וְאָמְרָה נִתַּן לִי בֵּן בִּמְדִינַת הַיָּם וָמֵת וְאַחַר כָּךְ מֵת בַּעְלִי נֶאֱמֶנֶת וּמִתְיַבֶּמֶת שֶׁהֲרֵי הָיְתָה בְּחֶזְקַת הֶתֵּר לִיבָמָהּ בְּעֵת שֶׁהָלְכָה. אָמְרָה מֵת בַּעְלִי וְאַחַר כָּךְ מֵת הַבֵּן שֶׁנִּתַּן לִי אֵינָהּ נֶאֱמֶנֶת לִפְטֹר עַצְמָהּ מִן הַיִּבּוּם וּמִן הַחֲלִיצָה וְחוֹשְׁשִׁין לִדְבָרֶיהָ וְחוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיְתָה פְּסוּלָה לִכְהֻנָּה מִתְּחִלָּה כְּגוֹן שֶׁהָיְתָה גְּרוּשָׁה אוֹ חֲלָלָה אוֹ שֶׁאָמְרָה בַּמְּעָרָה הָיִינוּ כְּשֶׁמֵּת. אֲבָל אִם אֵין הַדָּבָר כֵּן אֵינָהּ חוֹלֶצֶת. שֶׁמָּא תַּחֲלֹץ וְיָבוֹאוּ עֵדִים וְיָעִידוּ שֶׁהַדָּבָר כְּמוֹ שֶׁאָמְרָה וְהַבַּעַל מֵת תְּחִלָּה וְנִמְצֵאת חֲלִיצָה זוֹ אֵינָהּ כְּלוּם וְתִנָּשֵׂא לְכֹהֵן וְיִרְאֶה הָרוֹאֶה אוֹתָהּ שֶׁחָלְצָה וְנִשֵּׂאת לְכֹהֵן וִידַמֶּה שֶׁהַחֲלוּצָה מֻתֶּרֶת לִכְהֻנָּה וְהוּא אֵינוֹ יוֹדֵעַ בָּעֵדִים שֶׁבָּאוּ. לְפִיכָךְ לֹא תַּחֲלֹץ וְלֹא תִּתְיַבֵּם אֶלָּא תִּשָּׁאֵר בְּחֶזְקַת זְקוּקָה כְּשֶׁיָּצְאָה עַד שֶׁיָּבוֹאוּ עֵדִים:","וְכֵן אִשָּׁה שֶׁהָלַךְ בַּעְלָהּ וְצָרָתָהּ לִמְדִינַת הַיָּם וּבָאוּ שְׁנַיִם וְאָמְרוּ לָהּ מֵת בַּעְלֵךְ הֲרֵי זוֹ לֹא תַּחֲלֹץ וְלֹא תִּתְיַבֵּם לְעוֹלָם עַד שֶׁיִּוָּדַע אִם יָלְדָה צָרָתָהּ אוֹ לֹא יָלְדָה. וְלָמָּה לֹא תַּחֲלֹץ אַחַר תִּשְׁעָה חֳדָשִׁים מִמִּיתַת הַבַּעַל וְתִהְיֶה מֻתֶּרֶת לְזָר עַל כָּל פָּנִים שֶׁאִם יָלְדָה צָרָתָהּ הֲרֵי נִפְטְרָה זוֹ וְאִם לֹא יָלְדָה הֲרֵי נֶחְלְצָה. גְּזֵרָה שֶׁמָּא יִוָּדַע אַחַר הַחֲלִיצָה שֶׁיָּלְדָה צָרָתָהּ וָלָד שֶׁל קַיָּמָא וְנִמְצֵאת זֹאת שֶׁאֵינָהּ חֲלוּצָה וְתִנָּשֵׂא לְכֹהֵן אַחַר שֶׁנֶּחְלְצָה וְיֹאמַר הָרוֹאֶה שֶׁלֹּא יָדַע בָּעֵדִים שֶׁבָּאוּ שֶׁהַחֲלוּצָה מֻתֶּרֶת לְכֹהֵן וְיָעִיד שֶׁרָאָה אוֹתָהּ נִשֵּׂאת לִכְהֻנָּה עַל פִּי בֵּית דִּין. לְפִיכָךְ אִם הָיְתָה אֲסוּרָה לִכְהֻנָּה מִתְּחִלָּתָהּ הֲרֵי זוֹ חוֹלֶצֶת לְאַחַר תִּשְׁעָה וְתִנָּשֵׂא לְזָר. אֲבָל זוֹ הַצָּרָה שֶׁהָיְתָה עִם בַּעְלָהּ כְּשֶׁמֵּת תַּמְתִּין תִּשְׁעִים יוֹם כִּשְׁאָר הַיְבָמוֹת וְתַחְלֹץ אוֹ תִּתְיַבֵּם וְלֹא תָּחוּשׁ לְצָרָתָהּ שֶׁבַּמְּדִינָה הָאַחֶרֶת הוֹאִיל וְלֹא הָיָה בַּעְלָהּ עִמָּהּ בַּמְּדִינָה:","הָאִשָּׁה שֶׁמֵּת בַּעְלָהּ וְהָיְתָה לָהּ חָמוֹת בִּמְדִינַת הַיָּם אֵינָהּ חוֹשֶׁשֶׁת שֶׁמָּא יָלְדָה חֲמוֹתָהּ וּכְבָר נִתַּן לָהּ יָבָם בִּמְדִינָה אַחֶרֶת. שֶׁלֹּא גָּזְרוּ בְּדָבָר זֶה. אֶלָּא נַעֲמִיד אוֹתָהּ עַל חֶזְקָתָהּ וַהֲרֵי הִיא מֻתֶּרֶת. וְהוּא הַדִּין לְאִשָּׁה שֶׁמֵּת בַּעְלָהּ וְהָיָה לוֹ בֵּן בִּמְדִינָה אַחֶרֶת הֲרֵי זוֹ מֻתֶּרֶת לְזָר וְאֵין חוֹשְׁשִׁין שֶׁמָּא מֵת הַבֵּן אֶלָּא הַעֲמֵד אוֹתָהּ עַל חֶזְקָתָהּ:","יָצָאת חֲמוֹתָהּ מְעֻבֶּרֶת הֲרֵי זוֹ חוֹשֶׁשֶׁת וְלֹא תִּנָּשֵׂא לְזָר עַד שֶׁתֵּדַע מֶה הָיָה סוֹף עִבּוּר חֲמוֹתָהּ שֶׁמָּא נוֹלַד לָהּ יָבָם קֹדֶם מִיתַת הַבַּעַל:","הָאִשָּׁה שֶׁהָלַךְ בַּעְלָהּ וּבְנָהּ לִמְדִינַת הַיָּם וּבָאוּ וְאָמְרוּ לָהּ מֵת בַּעְלֵךְ וְאַחַר כָּךְ מֵת בְּנֵךְ וְנִשֵּׂאת וְאַחַר כָּךְ נוֹדַע שֶׁחִלּוּף הָיוּ הַדְּבָרִים תֵּצֵא וְהַוָּלָד כָּשֵׁר. אָמְרוּ לָהּ מֵת בְּנֵךְ וְאַחַר כָּךְ מֵת בַּעְלֵךְ וְנִתְיַבְּמָה וְאַחַר כָּךְ נוֹדַע שֶׁהָיוּ הַדְּבָרִים חִלּוּף תֵּצֵא וְהַוָּלָד שֶׁנּוֹלַד לִפְנֵי הַשְּׁמוּעָה אוֹ לְאַחַר הַשְּׁמוּעָה מַמְזֵר:"],"Mishneh Torah, Marriage 15":["הָאִשָׁה שֶׁהִרְשַׁת אֶת בַּעִלָהּ אַחַר הַנִּשּׂוּאִין שֶׁיִּמְנַע עוֹנָתָהּ הֲרֵי זֶה מֻתָּר. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיוּ לוֹ בָּנִים שֶׁכְּבָר קִיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה אֲבָל לֹא קִיֵּם חַיָּב לִבְעל בְּכָל עוֹנָה עַד שֶׁיִּהְיוּ לוֹ בָּנִים. מִפְּנֵי שֶׁהִיא מִצְוַת עֲשֵׂה שֶׁל תּוֹרָה שֶׁנֶּאֱמַר (בראשית א כב) \"פְּרוּ וּרְבוּ\":","הָאִישׁ מְצֻוֶּה עַל פְּרִיָּה וּרְבִיָּה אֲבָל לֹא הָאִשָּׁה. וְאֵימָתַי הָאִישׁ נִתְחַיֵּב בְּמִצְוָה זוֹ מִבֶּן שְׁבַע עֶשְׂרֵה. וְכֵיוָן שֶׁעָבְרוּ עֶשְׂרִים שָׁנָה וְלֹא נָשָׂא אִשָּׁה הֲרֵי זֶה עוֹבֵר וּמְבַטֵּל מִצְוַת עֲשֵׂה. וְאִם הָיָה עוֹסֵק בַּתּוֹרָה וְטָרוּד בָּהּ וְהָיָה מִתְיָרֵא מִלִּשָּׂא אִשָּׁה כְּדֵי שֶׁלֹּא יִטְרַח בִּמְזוֹנוֹת בַּעֲבוּר אִשְׁתּוֹ וְיִבָּטֵל מִן הַתּוֹרָה הֲרֵי זֶה מֻתָּר לְהִתְאַחֵר. שֶׁהָעוֹסֵק בְּמִצְוָה פָּטוּר מִן הַמִּצְוָה וְכָל שֶׁכֵּן בְּתַלְמוּד תּוֹרָה:","מִי שֶׁחָשְׁקָה נַפְשׁוֹ בַּתּוֹרָה תָּמִיד וְשׁוֹגֶה בָּהּ כְּבֶן עֲזַאי וְדָבֵק בָּהּ כָּל יָמָיו וְלֹא נָשָׂא אִשָּׁה אֵין בְּיָדוֹ עָוֹן. וְהוּא שֶׁלֹּא יִהְיֶה יִצְרוֹ מִתְגַּבֵּר עָלָיו. אֲבָל אִם הָיָה יִצְרוֹ מִתְגַּבֵּר עָלָיו חַיָּב לִשָּׂא אִשָּׁה וַאֲפִלּוּ הָיוּ לוֹ בָּנִים שֶׁמָּא יָבוֹא לִידֵי הִרְהוּר:","כַּמָּה בָּנִים יִהְיוּ לְאִישׁ וְתִתְקַיֵּם מִצְוָה זוֹ בְּיָדוֹ. זָכָר וּנְקֵבָה. שֶׁנֶּאֱמַר (בראשית ה ב) \"זָכָר וּנְקֵבָה בְּרָאָם\". הָיָה הַבֵּן סָרִיס אוֹ שֶׁהָיְתָה הַבַּת אַיְלוֹנִית לֹא קִיֵּם מִצְוָה זוֹ:","נוֹלְדוּ לוֹ וּמֵתוּ וְהִנִּיחוּ בָּנִים הֲרֵי זֶה קִיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה. בְּנֵי בָּנִים הֲרֵי הֵם כְּבָנִים. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיוּ בְּנֵי הַבָּנִים זָכָר וּנְקֵבָה וְהָיוּ בָּאִים מִזָּכָר וּנְקֵבָה אַף עַל פִּי שֶׁהַזָּכָר בֶּן בִּתּוֹ וְהַנְּקֵבָה בַּת בְּנוֹ הוֹאִיל וְהֵם מִשְּׁנֵי בָּנָיו הֵן בָּאִים הֲרֵי קִיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה. אֲבָל אִם הָיוּ לוֹ בֵּן וּבַת וּמֵתוּ וְהִנִּיחַ אֶחָד מֵהֶן זָכָר וּנְקֵבָה עֲדַיִן לֹא קִיֵּם הַמִּצְוָה:","הָיוּ לוֹ בָּנִים בְּגֵיוּתוֹ וְנִתְגַּיֵּר הוּא וְהֵם הֲרֵי זֶה קִיֵּם מִצְוָה זוֹ. הָיוּ לוֹ בָּנִים וְהוּא עֶבֶד וְנִשְׁתַּחְרֵר הוּא וְהֵם לֹא קִיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה עַד שֶׁיִּוָּלֵד אַחַר שֶׁנִּשְׁתַּחְרֵר שֶׁהָעֶבֶד אֵין לוֹ יִחוּס:","לֹא יִשָּׂא אָדָם עֲקָרָה וּזְקֵנָה וְאַיְלוֹנִית וּקְטַנָּה שֶׁאֵינָהּ רְאוּיָה לֵילֵד אֶלָּא אִם כֵּן קִיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה אוֹ שֶׁהָיְתָה לוֹ אִשָּׁה אַחֶרֶת לִפְרוֹת וְלִרְבּוֹת מִמֶּנָּה. נָשָׂא אִשָּׁה וְשָׁהֲתָה עִמּוֹ עֶשֶׂר שָׁנִים וְלֹא יָלְדָה הֲרֵי זֶה יוֹצִיא וְיִתֵּן כְּתֻבָּה אוֹ יִשָּׂא אִשָּׁה הָרְאוּיָה לֵילֵד. וְאִם לֹא רָצָה לְהוֹצִיא כּוֹפִין אוֹתוֹ וּמַכִּין אוֹתוֹ בְּשׁוֹט עַד שֶׁיּוֹצִיא. וְאִם אָמַר אֵינִי בּוֹעֲלָהּ וַהֲרֵינִי שׁוֹכֵן עִמָּהּ בִּפְנֵי עֵדִים כְּדֵי שֶׁלֹּא אֶתְיַחֵד עִמָּהּ בֵּין שֶׁאָמְרָה הִיא בֵּין שֶׁאָמַר הוּא אֵין שׁוֹמְעִין אֶלָּא יוֹצִיא אוֹ יִשָּׂא אִשָּׁה הָרְאוּיָה לֵילֵד:","שָׁהֲתָה עֶשֶׂר שָׁנִים וְלֹא יָלְדָה וַהֲרֵי הוּא יוֹרֶה כְּחֵץ שִׁכְבַת זֶרַע. חֶזְקַת הַחלִי מִמֶּנָּה וְתֵצֵא שֶׁלֹּא בִּכְתֻבָּה וְיֵשׁ לָהּ תּוֹסֶפֶת. לֹא תִּהְיֶה זוֹ פְּחוּתָה מֵאַיְלוֹנִית שֶׁלֹּא הִכִּיר בָּהּ שֶׁיֵּשׁ לָהּ תּוֹסֶפֶת כְּמוֹ שֶׁיִּתְבָּאֵר. וְאִם אֵינוֹ יוֹרֶה כְּחֵץ חֶזְקַת הַחלִי מִמֶּנּוּ בִּלְבַד וְיוֹצִיא וְיִתֵּן הַכְּתֻבָּה כֻּלָּהּ עִקָּר וְתוֹסֶפֶת:","הוּא אוֹמֵר מִמֶּנָּה נִמְנָע הוֹלָדָה וְהִיא אוֹמֶרֶת מִמֶּנּוּ נִמְנָע מִפְּנֵי שֶׁאֵינוֹ יוֹרֶה כְּחֵץ נֶאֱמֶנֶת. וְיֵשׁ לוֹ לְהַחֲרִים סְתָם עַל מִי שֶׁטּוֹעֶנֶת דָּבָר שֶׁאֵינָהּ יוֹדַעַת בּוֹ בְּוַדַּאי וְאַחַר כָּךְ יִתֵּן כְּתֻבָּה. וְאִם אָמְרָה אֵינִי יוֹדַעַת אִם מִמֶּנִּי אִם מִמֶּנּוּ אֵין לָהּ עִקַּר כְּתֻבָּה כְּמוֹ שֶׁאָמַרְנוּ הַעֲמֵד מָמוֹן בְּחֶזְקַת בְּעָלָיו עַד שֶׁתִּטְעֹן בְּוַדַּאי שֶׁאֵינוֹ יוֹרֶה כְּחֵץ. וְלָמָּה נֶאֱמֶנֶת הִיא בְּטַעֲנָה זוֹ מִפְּנֵי שֶׁהִיא מַרְגֶּשֶׁת אִם יוֹרֶה כְּחֵץ אִם לֹא יוֹרֶה כְּחֵץ וְהוּא אֵינוֹ מַרְגִּישׁ:","הָאִשָּׁה שֶׁבָּאָה לִתְבֹּעַ מִבַּעְלָהּ לְגָרְשָׁהּ אַחַר עֶשֶׂר שָׁנִים מִפְּנֵי שֶׁלֹּא יָלְדָה וְהִיא אוֹמֶרֶת שֶׁאֵינוֹ יוֹרֶה כְּחֵץ שׁוֹמְעִין לָהּ. אַף עַל פִּי שֶׁאֵינָהּ מְצֻוָּה עַל פְּרִיָּה וּרְבִיָּה צְרִיכָה הִיא לְבָנִים לְזִקְנוּתָהּ. וְכוֹפִין אוֹתוֹ לְהוֹצִיא וְיִתֵּן עִקַּר כְּתֻבָּה בִּלְבַד שֶׁלֹּא כָּתַב לָהּ הַתּוֹסֶפֶת עַל מְנָת שֶׁתֵּצֵא לִרְצוֹנָהּ וְתִטּל:","הָלַךְ בִּסְחוֹרָה בְּתוֹךְ עֶשֶׂר שָׁנִים אוֹ שֶׁהָיָה הַבַּעַל חוֹלֶה אוֹ שֶׁהָיְתָה הִיא חוֹלָה אוֹ שֶׁהָיוּ חֲבוּשִׁין בְּבֵית הָאֲסוּרִין אֵין עוֹלֶה לָהֶן אוֹתוֹ זְמַן מִן הַמִּנְיָן:","הִפִּילָה מוֹנָה מִיּוֹם שֶׁהִפִּילָה. אִם הִפִּילָה וְחָזְרָה וְהִפִּילָה שָׁלֹשׁ פְּעָמִים הֻחְזְקָה לִנְפָלִים וְשֶׁמָּא לֹא זָכָה לְהִבָּנוֹת מִמֶּנָּה וְיוֹצִיא וְיִתֵּן כְּתֻבָּה:","הוּא אוֹמֵר הִפִּילָה בְּתוֹךְ עֶשֶׂר כְּדֵי שֶׁיִּשְׁהֶה עִמָּהּ וְהִיא אוֹמֶרֶת לֹא הִפַּלְתִּי נֶאֱמֶנֶת שֶׁאֵינָהּ מַחְזֶקֶת עַצְמָהּ בַּעֲקָרוּת. הוּא אוֹמֵר הִפִּילָה שְׁנַיִם וְהִיא אוֹמֶרֶת הִפַּלְתִּי שְׁלֹשָׁה נֶאֱמֶנֶת שֶׁאֵינָהּ מַחְזֶקֶת עַצְמָהּ בְּמַפֶּלֶת וְיוֹצִיא וְיִתֵּן כְּתֻבָּה. וּבְכָל זֶה מַשְׁבִּיעָהּ שְׁבוּעַת הֶסֵּת שֶׁלֹּא הִפִּילָה אוֹ שֶׁהִפִּילָה שְׁלֹשָׁה שֶׁבְּטַעֲנָה זוֹ יִתְחַיֵּב לִתֵּן כְּתֻבָּה:","נִשֵּׂאת לָרִאשׁוֹן וְשָׁהֲתָה עִמּוֹ עֶשֶׂר שָׁנִים וְלֹא יָלְדָה וְהוֹצִיאָהּ מֻתֶּרֶת לְהִנָּשֵׂא לְשֵׁנִי. שָׁהֲתָה עִם הַשֵּׁנִי עֶשֶׂר שָׁנִים וְלֹא יָלְדָה לֹא תִּנָּשֵׂא לִשְׁלִישִׁי. וְאִם נִשֵּׂאת לִשְׁלִישִׁי תֵּצֵא שֶׁלֹּא בִּכְתֻבָּה אֶלָּא אִם כֵּן יֵשׁ לוֹ אִשָּׁה אַחֶרֶת אוֹ שֶׁקִּיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה:","הָאִשָּׁה שֶׁבָּאָה לְבֵית דִּין וְאָמְרָה בַּעְלִי אֵינוֹ יָכוֹל לְשַׁמֵּשׁ כְּדֶרֶךְ כָּל הָאָרֶץ שִׁמּוּשׁ שֶׁמּוֹלִיד אוֹ שֶׁאֵינוֹ יוֹרֶה כְּחֵץ יַעֲשׂוּ הַדַּיָּנִין פְּשָׁרָה וְאוֹמְרִים לָהּ רָאוּי לִיךְ שֶׁתִּנְהֲגִי עִם בַּעְלֵךְ עַד שֶׁתִּשְׁהִי עֶשֶׂר שָׁנִים וְלֹא תּוֹלִידִי וְאַחַר כָּךְ תִּתְבְּעִי. וּמְגַלְגְּלִין עִמָּהּ בְּדָבָר זֶה וְאֵין כּוֹפִין אוֹתָהּ לֵישֵׁב וְלֹא דָּנִין אוֹתָהּ כְּדִין הַמּוֹרֶדֶת אֶלָּא מַאֲרִיכִין בְּדָבָר זֶה עַד שֶׁיַּעֲשׂוּ פְּשָׁרָה:","אַף עַל פִּי שֶׁקִּיֵּם אָדָם מִצְוַת פְּרִיָּה וּרְבִיָּה הֲרֵי הוּא מְצֻוֶּה מִדִּבְרֵי סוֹפְרִים שֶׁלֹּא יִבָּטֵל מִלִּפְרוֹת וְלִרְבּוֹת כָּל זְמַן שֶׁיֵּשׁ בּוֹ כֹּחַ. שֶׁכָּל הַמּוֹסִיף נֶפֶשׁ אַחַת בְּיִשְׂרָאֵל כְּאִלּוּ בָּנָה עוֹלָם. וְכֵן מִצְוַת חֲכָמִים הִיא שֶׁלֹּא יֵשֵׁב אָדָם בְּלֹא אִשָּׁה שֶׁלֹּא יָבֹא לִידֵי הִרְהוּר. וְלֹא תֵּשֵׁב אִשָּׁה בְּלֹא אִישׁ שֶׁלֹּא תֵּחָשֵׁד:","וְחוֹבָה עַל כָּל אִישׁ לְקַנְּאוֹת לְאִשְׁתּוֹ. אָמְרוּ חֲכָמִים אֵין אָדָם מְקַנֵּא לְאִשְׁתּוֹ אֶלָּא אִם כֵּן נִכְנְסָה בּוֹ רוּחַ טָהֳרָה. וְלֹא יְקַנֵּא לָהּ בְּיוֹתֵר מִדַּאי וְלֹא יֶאֱנֹס אוֹתָהּ וְיִבְעל בְּעַל כָּרְחָהּ אֶלָּא בְּדַעְתָּהּ וּמִתּוֹךְ שִׂיחָה וְשִׂמְחָה:","וְכֵן צִוּוּ חֲכָמִים עַל הָאִשָּׁה שֶׁתִּהְיֶה צְנוּעָה בְּתוֹךְ בֵּיתָהּ. וְלֹא תַּרְבֶּה שְׂחוֹק וְקַלּוּת רֹאשׁ בִּפְנֵי בַּעְלָהּ. וְלֹא תִּתְבַּע תַּשְׁמִישׁ הַמִּטָּה בְּפִיהָ. וְלֹא תִּהְיֶה מְדַבֶּרֶת בְּעֵסֶק זֶה. וְלֹא תִּמְנַע מִבַּעְלָהּ כְּדֵי לְצַעֲרוֹ עַד שֶׁיּוֹסִיף בְּאַהֲבָתָהּ אֶלָּא נִשְׁמַעַת לוֹ בְּכָל עֵת שֶׁיִּרְצֶה. וְתִזָּהֵר מִקְּרוֹבָיו וּבְנֵי בֵּיתוֹ כְּדֵי שֶׁלֹּא יַעֲבֹר עָלָיו רוּחַ קִנְאָה. וְתִתְרַחֵק מִן הַכִּעוּר וּמִן הַדּוֹמֶה לְכִעוּר:","וְכֵן צִוּוּ חֲכָמִים שֶׁיִּהְיֶה אָדָם מְכַבֵּד אֶת אִשְׁתּוֹ יוֹתֵר מִגּוּפוֹ וְאוֹהֲבָהּ כְּגוּפוֹ. וְאִם יֵשׁ לוֹ מָמוֹן מַרְבֶּה בְּטוֹבָתָהּ כְּפִי מָמוֹנוֹ. וְלֹא יַטִּיל עָלֶיהָ אֵימָה יְתֵרָה. וְיִהְיֶה דִּבּוּרוֹ עִמָּהּ בְּנַחַת. וְלֹא יִהְיֶה עָצֵב וְלֹא רַגְזָן:","וְכֵן צִוּוּ עַל הָאִשָּׁה שֶׁתִּהְיֶה מְכַבֶּדֶת אֶת בַּעְלָהּ בְּיוֹתֵר מִדַּאי וְיִהְיֶה עָלֶיהָ מוֹרָא מִמֶּנּוּ וְתַעֲשֶׂה כָּל מַעֲשֶׂיהָ עַל פִּיו. וְיִהְיֶה בְּעֵינֶיהָ כְּמוֹ שַׂר אוֹ מֶלֶךְ. מְהַלֶּכֶת בְּתַאֲוַת לִבּוֹ וּמַרְחֶקֶת כָּל מַה שֶּׁיִּשְׂנָא. וְזֶה דֶּרֶךְ בְּנוֹת יִשְׂרָאֵל וּבְנֵי יִשְׂרָאֵל הַקְּדוֹשִׁים וְהַטְּהוֹרִים בְּזִוּוּגָן. וּבִדְרָכִים אֵלּוּ יִהְיֶה יִשּׁוּבָן נָאֶה וּמְשֻׁבָּח:"],"Mishneh Torah, Marriage 3":["כֵּיצַד הָאִשָּׁה מִתְקַדֶּשֶׁת. אִם בְּכֶסֶף הוּא מְקַדֵּשׁ אֵין פָּחוֹת מִפְּרוּטָה כֶּסֶף אוֹ שְׁוֵה פְּרוּטָה. אוֹמֵר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי. אוֹ הֲרֵי אַתְּ מְאֹרֶסֶת לִי. אוֹ הֲרֵי אַתְּ לִי לְאִשָּׁה בָּזֶה. וְנוֹתֵן לָהּ בִּפְנֵי עֵדִים. וְהָאִישׁ הוּא שֶׁאוֹמֵר דְּבָרִים שֶׁמַּשְׁמָעָן שֶׁקּוֹנֶה אוֹתָהּ לוֹ לְאִשָּׁה וְהוּא שֶׁיִּתֵּן לָהּ הַכֶּסֶף:","נָתְנָה הִיא וְאָמְרָה לוֹ הֲרֵי אֲנִי מְקֻדֶּשֶׁת לְךָ. הֲרֵינִי מְאֹרֶסֶת לְךָ. הֲרֵינִי לְךָ לְאִנְתּוּ אוֹ בְּכָל לְשׁוֹן הַקְנָאָה אֵינָהּ מְקֻדֶּשֶׁת. וְכֵן אִם נָתְנָה הִיא לוֹ וְאָמַר הוּא אֵינָהּ מְקֻדֶּשֶׁת. וְאִם נָתַן הוּא וְאָמְרָה הִיא הֲרֵי זוֹ מְקֻדֶּשֶׁת מִסָּפֵק:","וְאִם קִדֵּשׁ בִּשְׁטָר כּוֹתֵב עַל הַנְּיָר אוֹ עַל הַחֶרֶס אוֹ עַל הֶעָלֶה אוֹ עַל כָּל דָּבָר שֶׁיִּרְצֶה. הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי אוֹ הֲרֵי אַתְּ מְאֹרֶסֶת לִי וְכָל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ וְנוֹתְנוֹ לָהּ בִּפְנֵי עֵדִים:","וְצָרִיךְ שֶׁיִּכְתֹּב אוֹתוֹ לְשֵׁם הָאִשָּׁה הַמִּתְקַדֶּשֶׁת כְּגֵט. וְאֵינוֹ כּוֹתְבוֹ אֶלָּא מִדַּעְתָּהּ. כְּתָבוֹ שֶׁלֹּא לִשְׁמָהּ אוֹ לִשְׁמָהּ שֶׁלֹּא מִדַּעְתָּהּ אַף עַל פִּי שֶׁנְּתָנוֹ לָהּ לְדַעְתָּהּ בִּפְנֵי עֵדִים אֵינָהּ מְקֻדֶּשֶׁת:","וְאִם קִדֵּשׁ בְּבִיאָה אוֹמֵר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי אוֹ הֲרֵי אַתְּ מְאֹרֶסֶת לִי אוֹ הֲרֵי אַתְּ לִי לְאִשָּׁה בִּבְעִילָה זוֹ וְכָל כַּיּוֹצֵא בָּזֶה. וּמִתְיַחֵד עִמָּהּ בִּפְנֵי שְׁנֵי עֵדִים וּבוֹעֲלָהּ. וְהַמְקַדֵּשׁ בְּבִיאָה (מִסְּתָמָא) דַּעְתּוֹ עַל גְּמַר בִּיאָה. וּכְשֶׁיִּגְמֹר בִּיאָתוֹ תִּהְיֶה מְקֻדֶּשֶׁת. (וּבֵין שֶׁבָּא עָלֶיהָ כְּדַרְכָּהּ וּבֵין שֶׁבָּא עָלֶיהָ שֶׁלֹּא כְּדַרְכָּהּ הֲרֵי זוֹ מְקֻדֶּשֶׁת):","הַדְּבָרִים שֶׁיֹּאמַר הָאִישׁ כְּשֶׁיְּקַדֵּשׁ צָרִיךְ שֶׁיִּהְיֶה מַשְׁמָעָם שֶׁהוּא קוֹנֶה הָאִשָּׁה וְלֹא שֶׁיְּהֵא מַשְׁמָע שֶׁהִקְנָה עַצְמוֹ לָהּ. כֵּיצַד. הֲרֵי שֶׁאָמַר לָהּ אוֹ שֶׁכָּתַב בַּשְּׁטָר שֶׁנְּתָנוֹ לָהּ. הֲרֵינִי בַּעְלֵךְ. הֲרֵינִי אֲרוּסֵךְ. הֲרֵינִי אִישֵׁךְ וְכָל כַּיּוֹצֵא בָּזֶה. אֵין כָּאן קִדּוּשִׁין כְּלָל. אָמַר לָהּ אוֹ כָּתַב לָהּ. הֲרֵי אַתְּ אִשְׁתִּי. הֲרֵי אַתְּ אֲרוּסָתִי. אוֹ הֲרֵי אַתְּ קְנוּיָה לִי. הֲרֵי אַתְּ שֶׁלִּי. הֲרֵי אַתְּ לְקוּחָתִי. הֲרֵי אֶת חֲרוּפָתִי. הֲרֵי אַתְּ בִּרְשׁוּתִי. הֲרֵי אַתְּ זְקוּקָה לִי וְכָל כַּיּוֹצֵא בָּהֶן. הֲרֵי זוֹ מְקֻדֶּשֶׁת:","אָמַר לָהּ אוֹ כָּתַב לָהּ הֲרֵי אַתְּ מְיֻחֶדֶת לִי. הֲרֵי אַתְּ מְיֹעֶדֶת לִי. הֲרֵי אַתְּ עֶזְרָתִי. הֲרֵי אַתְּ נֶגְדָּתִי. הֲרֵי אַתְּ צַלְעָתִי. הֲרֵי אַתְּ סְגוּרָתִי. הֲרֵי אַתְּ תַּחְתַּי. הֲרֵי אַתְּ עֲצוּרָתִי. הֲרֵי אַתְּ תְּפוּסָתִי. הֲרֵי זוֹ מְקֻדֶּשֶׁת בְּסָפֵק. וְהוּא שֶׁיִּהְיֶה מְדַבֵּר עִמָּהּ תְּחִלָּה עַל עִסְקֵי קִדּוּשִׁין. אֲבָל אִם אֵינוֹ מְדַבֵּר עִמָּהּ תְּחִלָּה עַל עִסִקֵי קִדּוּשִׁין אֵין חוֹשִׁשִׁין לִמִלּוֹת אֵלּוּ:","וְיֵשׁ לָאִישׁ לְקַדֵּשׁ הָאִשָּׁה בְּכָל לָשׁוֹן שֶׁהִיא מַכֶּרֶת בּוֹ. וְיִהְיֶה מַשְׁמַע הַדְּבָרִים בְּאוֹתָהּ הַלָּשׁוֹן שֶׁקְּנָאָהּ כְּמוֹ שֶׁבֵּאַרְנוּ. הָיָה מְדַבֵּר עִם הָאִשָּׁה עַל עִסְקֵי הַקִּדּוּשִׁין וְרָצְתָה וְעָמַד וְקִדֵּשׁ וְלֹא פֵּרֵשׁ וְלֹא אָמַר לָהּ כְּלוּם אֶלָּא נָתַן בְּיָדָהּ אוֹ בָּעַל הוֹאִיל וְהֵן עֲסוּקִין בָּעִנְיָן דַּיּוֹ וְאֵינוֹ צָרִיךְ לְפָרֵשׁ. וְכֵן עֵדֵי הַקִּדּוּשִׁין וְהַגֵּרוּשִׁין אֵינוֹ צָרִיךְ לוֹמַר לָהֵם אַתֵּם עֵדַי. אֵלָּא כֵּיוָן שֵׁגֵּרֵשׁ אוֹ קִדֵּשׁ בִּפִנֵיהֵם הֲרֵי זוֹ מְקֻדֶּשֶׁת אוֹ מִגֹרֵשֵׁת:","הָאוֹמֵר לְאִשָּׁה הִתְקַדְּשִׁי לְחֶצְיִי הֲרֵי זוֹ מְקֻדֶּשֶׁת. הָא לְמַה זֶּה דּוֹמֶה לְאוֹמֵר לָהּ תְּהִי אִשְׁתִּי אַתְּ וְאַחֶרֶת שֶׁנִּמְצָא שֶׁאֵין לָהּ אֶלָּא חֲצִי אִישׁ. אֲבָל אִם אָמַר חֶצְיֵךְ מְקֻדֶּשֶׁת לִי אֵינָהּ מְקֻדֶּשֶׁת שֶׁאֵין אִשָּׁה אַחַת רְאוּיָה לִשְׁנַיִם. וְכֵן אִם אוֹמֵר הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי וְלָזֶה אֵינָהּ מְקֻדֶּשֶׁת:","אָמַר לָהּ הֲרֵי חֶצְיֵךְ מְקֻדֶּשֶׁת לִי בִּפְרוּטָה וְחֶצְיֵךְ בִּפְרוּטָה. אוֹ שֶׁאָמַר לָהּ חֶצְיֵךְ מְקֻדֶּשֶׁת לִי בַּחֲצִי פְּרוּטָה וְחֶצְיֵךְ הָאַחֶרֶת מְקֻדֶּשֶׁת בַּחֲצִי פְּרוּטָה הֲרֵי זוֹ מְקֻדֶּשֶׁת. אָמַר לָהּ חֶצְיֵךְ מְקֻדֶּשֶׁת לִי בִּפְרוּטָה הַיּוֹם וְחֶצְיֵךְ בִּפְרוּטָה לְמָחָר. שְׁתֵּי חֲצָיַיִךְ בִּפְרוּטָה. שְׁתֵּי בְּנוֹתֶיךָ לִשְׁנֵי בָּנַי בִּפְרוּטָה. בִּתְּךָ מְקֻדֶּשֶׁת לִי וּפָרָתְךָ מְכוּרָה לִי בִּפְרוּטָה. אוֹ בִּתְּךָ וְקַרְקָעָתְךָ לִי בִּפְרוּטָה. בְּכָל אֵלּוּ מְקֻדֶּשֶׁת בְּסָפֵק:","הָאָב מְקַדֵּשׁ אֶת בִּתּוֹ שֶׁלֹּא לְדַעְתָּהּ כָּל זְמַן שֶׁהִיא קְטַנָּה. וְכֵן כְּשֶׁהִיא נַעֲרָה רְשׁוּתָהּ בְּיָדוֹ שֶׁנֶּאֱמַר (דברים כב טז) \"אֶת בִּתִּי נָתַתִּי לָאִישׁ הַזֶּה לְאִשָּׁה\". וְקִדּוּשֶׁיהָ לְאָבִיהָ. וְכֵן הוּא זַכַּאי בִּמְצִיאָתָהּ וּבְמַעֲשֵׂה יָדֶיהָ וּבִכְתֻבָּתָהּ אִם נִתְגָּרְשָׁה אוֹ נִתְאַלְמְנָה מִן הָאֵרוּסִין הוּא זַכַּאי בַּכּל עַד שֶׁתִּבָּגֵר. לְפִיכָךְ מְקַבֵּל הָאָב קִדּוּשֵׁי בִּתּוֹ מִיּוֹם שֶׁתִּוָּלֵד עַד שֶׁתִּבָּגֵר. וַאֲפִלּוּ הָיְתָה חֵרֶשֶׁת אוֹ שׁוֹטָה וְקִדְּשָׁהּ הָאָב הֲרֵי הִיא אֵשֶׁת אִישׁ גְּמוּרָה. וְאִם הָיְתָה בַּת שָׁלֹשׁ שָׁנִים וְיוֹם אֶחָד מִתְקַדֶּשֶׁת בְּבִיאָה מִדַּעַת אָבִיהָ. פָּחוֹת מִכֵּן אִם קִדְּשָׁהּ אָבִיהָ בְּבִיאָה אֵינָהּ מְקֻדֶּשֶׁת:","בָּגְרָה הַבַּת אֵין לְאָבִיהָ בָּהּ רְשׁוּת וַהֲרֵי הִיא כִּשְׁאָר כָּל הַנָּשִׁים שֶׁאֵינָם מִתְקַדְּשׁוֹת אֶלָּא לְדַעְתָּן. וְכֵן אִם הִשִּׂיאָהּ אָבִיהָ וְנִתְאַלְמְנָה אוֹ נִתְגָּרְשָׁה בְּחַיֵּי אָבִיהָ הֲרֵי הִיא בִּרְשׁוּת עַצְמָהּ וְאַף עַל פִּי שֶׁעֲדַיִן הִיא קְטַנָּה. כֵּיוָן שֶׁנִּשֵּׂאת אֵין לְאָבִיהָ בָּהּ רְשׁוּת לְעוֹלָם:","נִתְקַדְּשָׁה קֹדֶם שֶׁתִּבְגֹּר שֶׁלֹּא לְדַעַת אָבִיהָ אֵינָהּ מְקֻדֶּשֶׁת וַאֲפִלּוּ אִם נִתְרַצָּה הָאָב אַחַר שֶׁנִּתְקַדְּשָׁה. וַאֲפִלּוּ אִם נִתְאַלְמְנָה אוֹ נִתְגָּרְשָׁה מִן אוֹתָן הַקִּדּוּשִׁין אֵינָהּ אֲסוּרָה לְכֹהֵן. וּבֵין הִיא וּבֵין אָבִיהָ יְכוֹלִין לְעַכֵּב. בֵּין אִם נִתְקַדְּשָׁה בְּפָנָיו בֵּין שֶׁנִּתְקַדְּשָׁה שֶׁלֹּא בְּפָנָיו אֵינָהּ מְקֻדֶּשֶׁת:","הָיְתָה הַבַּת סָפֵק בּוֹגֶרֶת. בֵּין שֶׁקִּדְּשָׁהּ אָבִיהָ שֶׁלֹּא לְדַעְתָּהּ בֵּין שֶׁקִּדְּשָׁה הִיא עַצְמָהּ שֶׁלֹּא לְדַעַת אָבִיהָ. הֲרֵי זוֹ מְקֻדֶּשֶׁת בְּסָפֵק לְפִיכָךְ צְרִיכָה גֵּט מִסָּפֵק. יֵשׁ לָאִישׁ לַעֲשׂוֹת שָׁלִיחַ לְקַדֵּשׁ לוֹ אִשָּׁה בֵּין אִשָּׁה פְּלוֹנִית בֵּין אִשָּׁה מִשְּׁאָר הַנָּשִׁים. וְכֵן הָאִשָּׁה הַגְּדוֹלָה עוֹשָׂה שָׁלִיחַ לְקַבֵּל קִדּוּשֶׁיהָ בֵּין מֵאִישׁ פְּלוֹנִי בֵּין מֵאִישׁ מִשְּׁאָר אֲנָשִׁים. וְכֵן הָאָב עוֹשֶׂה שָׁלִיחַ לְקַבֵּל קִדּוּשֵׁי בִּתּוֹ כְּשֶׁהִיא בִּרְשׁוּתוֹ. וְאוֹמֵר הָאָב לְבִתּוֹ הַקְּטַנָּה צְאִי וְקַבְּלִי קִדּוּשַׁיִךְ:","כָּל הָעוֹשֶׂה שָׁלִיחַ לְקַבֵּל הַקִּדּוּשִׁין צָרִיךְ לַעֲשׂוֹתוֹ בִּפְנֵי עֵדִים. אֲבָל הָאִישׁ שֶׁעָשָׂה שָׁלִיחַ לְקַדֵּשׁ לוֹ אִשָּׁה אֵינוֹ צָרִיךְ לַעֲשׂוֹתוֹ בְּעֵדִים שֶׁאֵין מָקוֹם לְעֵדִים בִּשְׁלִיחוּת הָאִישׁ אֶלָּא לְהוֹדִיעַ אֲמִתַּת הַדָּבָר. לְפִיכָךְ אִם הוֹדוּ הַשָּׁלִיחַ וְהַמְשַׁלֵּחַ אֵינָן צְרִיכִין עֵדִים כְּמוֹ שְׁלִיחַ הַגֵּט וּכְמוֹ שָׁלִיחַ שֶׁהִרְשָׁהוּ לְהַפְרִישׁ לוֹ תְּרוּמָה וְכַיּוֹצֵא בָּהֶן בְּכָל מָקוֹם שֶׁשְּׁלוּחוֹ שֶׁל אָדָם כְּמוֹתוֹ וְאֵינוֹ צָרִיךְ עֵדִים:","הַשָּׁלִיחַ נַעֲשֶׂה עֵד לְפִיכָךְ אִם עָשָׂה שְׁנֵי שְׁלוּחִין לְקַדֵּשׁ לוֹ אִשָּׁה וְהָלְכוּ וְקִדְּשׁוּ אוֹתָהּ הֵן הֵן שְׁלוּחָיו וְהֵן הֵן עֵדֵי הַקִּדּוּשִׁין וְאֵינָן צְרִיכִין לְקַדְּשָׁהּ לוֹ בִּפְנֵי שְׁנַיִם אֲחֵרִים:","הַכּל כְּשֵׁרִין לִשְׁלִיחוּת חוּץ מֵחֵרֵשׁ שׁוֹטֶה וְקָטָן לְפִי שֶׁאֵינָן בְּנֵי דַּעַת וְהָעַכּוּ\"ם לְפִי שֶׁאֵינוֹ בְּנֵי בְּרִית וְנֶאֱמַר (במדבר יח כח) \"כֵּן תָּרִימוּ גַם אַתֶּם\" לְרַבּוֹת הַשָּׁלִיחַ וּמַה אַתֶּם בְּנֵי בְּרִית אַף שְׁלוּחֲכֶם בְּנֵי בְּרִית לְהוֹצִיא אֶת הָעַכּוּ\"ם. אֲבָל הָעֶבֶד אַף עַל פִּי שֶׁהוּא נַעֲשֶׂה שָׁלִיחַ לְדָבָר שֶׁבְּמָמוֹן הֲרֵי הוּא פָּסוּל לִשְׁלִיחוּת הַקִּדּוּשִׁין וְהַגִּטִּין לְפִי שֶׁאֵינוֹ בְּתוֹרַת גִּטִּין וְקִדּוּשִׁין:","שְׁלִיחַ הָאִישׁ שֶׁמְּקַדֵּשׁ אוֹמֵר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִפְלוֹנִי בְּכֶסֶף זֶה אוֹ בִּשְׁטָר זֶה. אִם שְׁלִיחַ הָאִשָּׁה הוּא שֶׁמְּקַבֵּל הַקִּדּוּשִׁין אוֹמֵר לוֹ הֲרֵי פְּלוֹנִית שֶׁשָּׁלְחָה אוֹתְךָ מְקֻדֶּשֶׁת לִי וְהוּא אוֹמֵר לוֹ קִדַּשְׁתִּיהָ לְךָ אוֹ אֵרַסְתִּיהָ לְךָ אוֹ נְתַתִּיהָ לְךָ לְאִשָּׁה וְכָל כַּיּוֹצֵא בָּזֶה. וְכֵן הַמְקַדֵּשׁ עַל יְדֵי הָאָב אוֹמֵר לוֹ הֲרֵי בִּתְּךָ פְּלוֹנִית מְקֻדֶּשֶׁת לִי וְהוּא אוֹמֵר לוֹ קִדַּשְׁתִּיהָ לְךָ. אִם אָמַר הָאָב אוֹ הַשָּׁלִיחַ הֵן דַּיּוֹ וַאֲפִלּוּ שָׁתַק. וְאִם הָיוּ עֲסוּקִין בְּאוֹתוֹ עִנְיָן וְנָתַן לָאָב אוֹ לַשָּׁלִיחַ וְלֹא פֵּרֵשׁ וְלֹא אָמַר דָּבָר דַּיּוֹ וְהִיא מְקֻדֶּשֶׁת. וְאִם קִדֵּשׁ בִּשְׁטָר אֵינוֹ כּוֹתְבוֹ אֶלָּא מִדַּעַת הָאָב אוֹ מִדַּעַת הַשָּׁלִיחַ. וְכֵן בְּכָל הַדְּבָרִים כֻּלָּן שֶׁל קִדּוּשִׁין דִּין הָאִישׁ עִם הָאִשָּׁה כְּדִין שָׁלִיחַ עִם שָׁלִיחַ אוֹ עִם הָאָב:","מִצְוָה שֶׁיְּקַדֵּשׁ אָדָם אֶת אִשְׁתּוֹ בְּעַצְמוֹ יוֹתֵר מֵעַל יְדֵי שְׁלוּחוֹ. וְכֵן מִצְוָה לָאִשָּׁה שֶׁתְּקַדֵּשׁ עַצְמָהּ בְּיָדָהּ יוֹתֵר מֵעַל יְדֵי שְׁלוּחָהּ. וְאַף עַל פִּי שֶׁיֵּשׁ רְשׁוּת לָאָב לְקַדֵּשׁ בִּתּוֹ כְּשֶׁהִיא קְטַנָּה וּכְשֶׁהִיא נַעֲרָה לְכָל מִי שֶׁיִּרְצֶה אֵין רָאוּי לַעֲשׂוֹת כֵּן אֶלָּא מִצְוַת חֲכָמִים שֶׁלֹּא יְקַדֵּשׁ אָדָם בִּתּוֹ כְּשֶׁהִיא קְטַנָּה עַד שֶׁתַּגְדִּיל וְתֹאמַר לִפְלוֹנִי אֲנִי רוֹצָה. וְכֵן הָאִישׁ אֵין רָאוּי לְקַדֵּשׁ קְטַנָּה. וְלֹא יְקַדֵּשׁ אִשָּׁה עַד שֶׁיִּרְאֶנָּה וְתִהְיֶה כְּשֵׁרָה בְּעֵינָיו שֶׁמָּא לֹא תִּמְצָא חֵן בְּעֵינָיו וְנִמְצָא מְגָרְשָׁהּ אוֹ שׁוֹכֵב עִמָּהּ וְהוּא שׂוֹנְאָהּ:","הַמְקַדֵּשׁ בְּבִיאָה הֲרֵי אֵלּוּ קִדּוּשֵׁי תּוֹרָה. וְכֵן מִתְקַדֶּשֶׁת בִּשְׁטָר מִן הַתּוֹרָה. כְּשֵׁם שֶׁגּוֹמֵר וּמְגָרֵשׁ שֶׁנֶּאֱמַר (דברים כד א) \"וְכָתַב לָהּ סֵפֶר כְּרִיתֻת\" כָּךְ גּוֹמֵר וּמַכְנִיס. אֲבָל הַכֶּסֶף מִדִּבְרֵי סוֹפְרִים (וְכֵן דִּין הַכֶּסֶף דִּין תּוֹרָה וּפֵרוּשׁוֹ מִדִּבְרֵי סוֹפְרִים) שֶׁנֶּאֱמַר (דברים כב יג) \"כִּי יִקַּח אִישׁ אִשָּׁה\" וְאָמְרוּ חֲכָמִים לִקּוּחִים אֵלּוּ יִהְיוּ בְּכֶסֶף שֶׁנֶּאֱמַר (בראשית כג יג) \"נָתַתִּי כֶּסֶף הַשָּׂדֶה קַח מִמֶּנִּי\":","אַף עַל פִּי שֶׁעִקַּר הַדָּבָר כָּךְ הוּא כְּבָר נָהֲגוּ כָּל יִשְׂרָאֵל לְקַדֵּשׁ בְּכֶסֶף אוֹ בִּשְׁוֵה כֶּסֶף. וְכֵן אִם רָצָה לְקַדֵּשׁ בִּשְׁטָר מְקַדֵּשׁ. אֲבָל אֵין מְקַדְּשִׁין בְּבִיאָה לְכַתְּחִלָּה וְאִם קִדֵּשׁ בְּבִיאָה מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת כְּדֵי שֶׁלֹּא יִהְיוּ יִשְׂרָאֵל פְּרוּצִים בְּדָבָר זֶה אַף עַל פִּי שֶׁקִּדּוּשָׁיו קִדּוּשִׁין גְּמוּרִין:","וְכֵן הַמְקַדֵּשׁ בְּלֹא שִׁדּוּכִין אוֹ הַמְקַדֵּשׁ בַּשּׁוּק אַף עַל פִּי שֶׁקִּדּוּשָׁיו קִדּוּשִׁין גְּמוּרִין מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת כְּדֵי שֶׁלֹּא יְהֵא דָּבָר זֶה הֶרְגֵּל לִזְנוּת וְיִדְמֶה לִקְדֵשָׁה שֶׁהָיְתָה קֹדֶם מַתַּן תּוֹרָה:","כָּל הַמְקַדֵּשׁ אִשָּׁה בֵּין עַל יְדֵי עַצְמוֹ בֵּין עַל יְדֵי שָׁלִיחַ צָרִיךְ לְבָרֵךְ קֹדֶם הַקִּדּוּשִׁין אוֹ הוּא אוֹ שְׁלוּחוֹ כְּדֶרֶךְ שֶׁמְּבָרְכִין עַל כָּל הַמִּצְוֹת וְאַחַר כָּךְ מְקַדֵּשׁ וְאִם קִדֵּשׁ וְלֹא בֵּרֵךְ לֹא יְבָרֵךְ אַחַר הַקִּדּוּשִׁין שֶׁזּוֹ בְּרָכָה לְבַטָּלָה מַה שֶּׁנַּעֲשָׂה כְּבָר נַעֲשָׂה:","כֵּיצַד מְבָרֵךְ. בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְהִבְדִּילָנוּ מִן הָעֲרָיוֹת וְאָסַר לָנוּ אֶת הָאֲרוּסוֹת וְהִתִּיר לָנוּ אֶת הַנְּשׂוּאוֹת עַל יְדֵי חֻפָּה וְקִדּוּשִׁין בָּרוּךְ אַתָּה ה' מְקַדֵּשׁ יִשְׂרָאֵל. זוֹ הִיא בִּרְכַּת אֵרוּסִין. וְנָהֲגוּ הָעָם לְהַסְדִּיר בְּרָכָה זוֹ עַל כּוֹס שֶׁל יַיִן אוֹ שֶׁל שֵׁכָר. וְאִם יֵשׁ שָׁם יַיִן מְבָרֵךְ עַל הַיַּיִן תְּחִלָּה וְאַחַר כָּךְ מְבָרֵךְ בִּרְכַּת אֵרוּסִין וְאַחַר כָּךְ מְקַדְּשָׁהּ. וְאִם אֵין לוֹ יַיִן אוֹ שֵׁכָר מְבָרֵךְ אוֹתָהּ בִּפְנֵי עַצְמָהּ:"],"Mishneh Torah, Mourning 14":["מִצְוַת עֲשֵׂה שֶׁל דִּבְרֵיהֶם לְבַקֵּר חוֹלִים. וּלְנַחֵם אֲבֵלִים. וּלְהוֹצִיא הַמֵּת. וּלְהַכְנִיס הַכַּלָּה. וּלְלַוּוֹת הָאוֹרְחִים. וּלְהִתְעַסֵּק בְּכָל צָרְכֵי הַקְּבוּרָה. לָשֵׂאת עַל הַכָּתֵף. וְלֵילֵךְ לְפָנָיו וְלִסְפֹּד וְלַחְפֹּר וְלִקְבֹּר. וְכֵן לְשַׂמֵּחַ הַכַּלָּה וְהֶחָתָן. וּלְסַעֲדָם בְּכָל צָרְכֵיהֶם. וְאֵלּוּ הֵן גְּמִילוּת חֲסָדִים שֶׁבְּגוּפוֹ שֶׁאֵין לָהֶם שִׁעוּר. אַף עַל פִּי שֶׁכָּל מִצְוֹת אֵלּוּ מִדִּבְרֵיהֶם הֲרֵי הֵן בִּכְלַל (ויקרא יט יח) \"וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ\". כָּל הַדְּבָרִים שֶׁאַתָּה רוֹצֶה שֶׁיַּעֲשׂוּ אוֹתָם לְךָ אֲחֵרִים. עֲשֵׂה אַתָּה אוֹתָן לְאָחִיךְ בְּתוֹרָה וּבְמִצְוֹת:","שְׂכַר הַלְּוָיָה מְרֻבֶּה מִן הַכּל. וְהוּא הַחֹק שֶׁחֲקָקוֹ אַבְרָהָם אָבִינוּ וְדֶרֶךְ הַחֶסֶד שֶׁנָּהַג בָּהּ. מַאֲכִיל עוֹבְרֵי דְּרָכִים וּמַשְׁקֶה אוֹתָן וּמְלַוֶּה אוֹתָן. וּגְדוֹלָה הַכְנָסַת אוֹרְחִים מֵהַקְבָּלַת פְּנֵי שְׁכִינָה. שֶׁנֶּאֱמַר (בראשית יח ב) \"וַיַּרְא וְהִנֵּה שְׁלֹשָׁה אֲנָשִׁים\". וְלִוּוּיָם יוֹתֵר מֵהַכְנָסָתָן. אָמְרוּ חֲכָמִים כָּל שֶׁאֵינוֹ מְלַוֶּה כְּאִלּוּ שׁוֹפֵךְ דָּמִים:","כּוֹפִין לִלְוָיָה כְּדֶרֶךְ שֶׁכּוֹפִין לִצְדָקָה. וּבֵית דִּין הָיוּ מְתַקְּנִין שְׁלוּחִין לְלַוּוֹת אָדָם הָעוֹבֵר מִמָּקוֹם לְמָקוֹם. וְאִם נִתְעַצְּלוּ בְּדָבָר זֶה מַעֲלֶה עֲלֵיהֶם כְּאִלּוּ שָׁפְכוּ דָּמִים. אֲפִלּוּ הַמְלַוֶּה אֶת חֲבֵרוֹ אַרְבַּע אַמּוֹת יֵשׁ לוֹ שָׂכָר הַרְבֵּה. וְכַמָּה שִׁעוּר לְוָיָה שֶׁחַיָּב אָדָם בָּהּ. הָרַב לְתַלְמִיד עַד עִבּוּרָהּ שֶׁל עִיר. וְהָאִישׁ לַחֲבֵרוֹ עַד תְּחוּם שַׁבָּת. וְהַתַּלְמִיד לָרַב עַד פַּרְסָה. וְאִם הָיָה רַבּוֹ מֻבְהָק עַד שָׁלֹשׁ פַּרְסָאוֹת:","בִּקּוּר חוֹלִים מִצְוָה עַל הַכּל. אֲפִלּוּ גָּדוֹל מְבַקֵּר אֶת הַקָּטָן. וּמְבַקְּרִין הַרְבֵּה פְּעָמִים בַּיּוֹם. וְכָל הַמּוֹסִיף מְשֻׁבָּח וּבִלְבַד שֶׁלֹּא יַטְרִיחַ. וְכָל הַמְבַקֵּר אֶת הַחוֹלֶה כְּאִלּוּ נָטַל חֵלֶק מֵחָלְיוֹ וְהֵקֵל מֵעָלָיו. וְכָל שֶׁאֵינוֹ מְבַקֵּר כְּאִלּוּ שׁוֹפֵךְ דָּמִים:","אֵין מְבַקְּרִין אֶת הַחוֹלֶה אֶלָּא מִיּוֹם שְׁלִישִׁי וָהָלְאָה. וְאִם קָפַץ עָלָיו הַחלִי וְהִכְבִּיד מְבַקְּרִין אוֹתוֹ מִיָּד. וְאֵין מְבַקְּרִין אֶת הַחוֹלֶה לֹא בְּשָׁלֹשׁ שָׁעוֹת רִאשׁוֹנוֹת בַּיּוֹם. וְלֹא בְּשָׁלֹשׁ אַחֲרוֹנוֹת. מִפְּנֵי שֶׁהֵן מִתְעַסְּקִין בְּצָרְכֵי הַחוֹלֶה. וְאֵין מְבַקְּרִין לֹא חוֹלֵי מֵעַיִם וְלֹא חוֹלֵי הָעַיִן. וְלֹא מֵחוֹשֵׁי הָרֹאשׁ. מִפְּנֵי שֶׁהַבִּקּוּר קָשֶׁה לָהֶן:","הַנִּכְנָס לְבַקֵּר אֶת הַחוֹלֶה לֹא יֵשֵׁב לֹא עַל גַּבֵּי מִטָּה וְלֹא עַל גַּבֵּי כִּסֵּא וְלֹא עַל גַּבֵּי סַפְסָל וְלֹא עַל גַּבֵּי מָקוֹם גָּבוֹהַּ וְלֹא לְמַעְלָה מִמְּרַאֲשׁוֹתָיו. אֶלָּא מִתְעַטֵּף וְיוֹשֵׁב לְמַטָּה מִמְּרַאֲשׁוֹתָיו וּמְבַקֵּשׁ עָלָיו רַחֲמִים וְיוֹצֵא:","יֵרָאֶה לִי שֶׁנֶּחָמַת אֲבֵלִים קוֹדֵם לְבִקּוּר חוֹלִים. שֶׁנִּחוּם אֲבֵלִים גְּמִילוּת חֶסֶד עִם הַחַיִּים וְעִם הַמֵּתִים:","מִי שֶׁהָיָה לְפָנָיו מֵת וְכַלָּה. מֵנִיחַ אֶת הַכַּלָּה וּמִתְעַסֵּק עִם הַמֵּת. וְכֵן הוּא אוֹמֵר (קהלת ז ד) \"לֵב חֲכָמִים בְּבֵית אֵבֶל\" וְגוֹ'. מֵת וְכַלָּה שֶׁפָּגְעוּ זֶה בָּזֶה בַּדֶּרֶךְ. מַעֲבִירִין אֶת הַמֵּת מִלִּפְנֵי הַכַּלָּה. וְזֶה וְזֶה עוֹבְרִין מִלִּפְנֵי הַמֶּלֶךְ:","מְבַטְּלִין תַּלְמוּד תּוֹרָה לְהוֹצָאַת הַמֵּת וּלְהַכְנָסַת הַכַּלָּה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁאֵין לוֹ כָּל צָרְכּוֹ. אֲבָל יֵשׁ לוֹ כָּל צָרְכּוֹ אֵין מְבַטְּלִין. וְכָל שֶׁאֵין מִתְעַסְּקִין בַּתּוֹרָה חַיָּבִין לְהִתְעַסֵּק עִמּוֹ:","מֵת אֶחָד בָּעִיר. כָּל בְּנֵי הָעִיר אֲסוּרִין בַּעֲשִׂיַּת מְלָאכָה עַד שֶׁיִּקְבְּרוּהוּ. וְאִם יֵשׁ לוֹ מִי שֶׁיִּתְעַסֵּק בִּצְרָכָיו מֻתָּרִין:","תַּלְמִיד חָכָם שֶׁמֵּת. אֲפִלּוּ הָיוּ עִמּוֹ עַד שִׁשִּׁים רִבּוֹא מְבַטְּלִין תַּלְמוּד תּוֹרָה לְהוֹצָאָתוֹ. הָיוּ שִׁשִּׁים רִבּוֹא אֵין מְבַטְּלִין. וְאִם הָיָה מְלַמֵּד לַאֲחֵרִים אֵין לוֹ שִׁעוּר אֶלָּא מְבַטְּלִין הַכּל לְהוֹצָאָתוֹ:","קוֹבְרִין מֵתֵי עַכּוּ\"ם וּמְנַחֲמִין אֲבֵלֵיהֶם וּמְבַקְּרִין חוֹלֵיהֶם מִפְּנֵי דַּרְכֵי שָׁלוֹם:","בָּתֵּי הַקְּבָרוֹת אֲסוּרִין בַּהֲנָאָה. כֵּיצַד. אֵין אוֹכְלִין בָּהֶן. וְאֵין שׁוֹתִין בָּהֶן. וְאֵין עוֹשִׂין בָּהֶן מְלָאכָה. וְלֹא קוֹרִין בָּהֶן וְלֹא שׁוֹנִין בָּהֶן. כְּלָלוֹ שֶׁל דָּבָר אֵין נֵאוֹתִין בָּהֶן. וְלֹא נוֹהֲגִין בָּהֶן קַלּוּת רֹאשׁ. לֹא יֵלֵךְ אָדָם בְּתוֹךְ אַרְבַּע אַמּוֹת שֶׁל קֶבֶר וּתְפִלִּין בְּיָדוֹ וְסֵפֶר תּוֹרָה בִּזְרוֹעוֹ. וְלֹא יִתְפַּלֵּל שָׁם. וּבְרִחוּק אַרְבַּע אַמּוֹת מֻתָּר:","הַמּוֹלִיךְ עֲצָמוֹת מִמָּקוֹם לְמָקוֹם לֹא יִתְּנֵם בְּדִיסְקִיָּא וְיַנִּיחֵם עַל גַּבֵּי חֲמוֹרוֹ וְיִרְכַּב עֲלֵיהֶם. מִפְּנֵי שֶׁנּוֹהֵג בָּהֶן מִנְהַג בִּזָּיוֹן. וְאִם הָיָה מִתְיָרֵא מִפְּנֵי הַגַּנָּבִים וּמִפְּנֵי הַלִּיסְטִים מֻתָּר:","אֵין מְפַנִּין אֶת הַמֵּת מִקֶּבֶר לְקֶבֶר אֲפִלּוּ מִבָּזוּי לִמְכֻבָּד. וְאִם הָיָה בְּתוֹךְ שָׂדֵהוּ מְפַנֵּהוּ אֲפִלּוּ מִמְּכֻבָּד לְבָזוּי:","אֵין קוֹבְרִין מֵת עַל גַּבֵּי מֵת וְלֹא שְׁנֵי מֵתִים כְּאֶחָד שֶׁבִּזָּיוֹן הוּא. וְקָטָן הַיָּשֵׁן עִם אִמּוֹ נִקְבָּר עִמָּהּ:","עֲפַר הַקֶּבֶר אֵינוֹ אָסוּר בַּהֲנָאָה שֶׁאֵין קַרְקַע עוֹלָם נֶאֱסֶרֶת. אֲבָל קֶבֶר הַבִּנְיָן אָסוּר בַּהֲנָאָה:","הַבּוֹנֶה קֶבֶר לְמֵת לֹא נֶאֱסַר עַד שֶׁיִּכָּנֵס בּוֹ הַמֵּת. וַאֲפִלּוּ הֵטִיל בּוֹ נֵפֶל נֶאֱסַר בַּהֲנָאָה:","נֶפֶשׁ שֶׁנַּעֲשָׂה לְשֵׁם חַי וְשָׂם בּוֹ הַמֵּת. וְהוֹסִיף בּוֹ דִּימוֹס אַחֵר לְשֵׁם הַמֵּת. אַף עַל פִּי שֶׁפִּנָּה הַמֵּת הַכּל אָסוּר בַּהֲנָאָה. וְאִם הִכִּיר אֶת הַתּוֹסֶפֶת חוֹלֵץ אוֹתָהּ וְהַשְּׁאָר מֻתָּר. נַעֲשָׂה לְשֵׁם הַמֵּת כֵּיוָן שֶׁהֻטַּל בּוֹ הַמֵּת נֶאֱסַר אַף עַל פִּי שֶׁפִּנָּהוּ:","הַבּוֹנֶה קֶבֶר לְאָבִיו וְהָלַךְ וּקְבָרוֹ בְּקֶבֶר אַחֵר. הֲרֵי זֶה לֹא יִקָּבֵר בּוֹ מֵת אַחֵר עוֹלָמִית. וְהַקֶּבֶר הַזֶּה אָסוּר בַּהֲנָאָה מִפְּנֵי כְּבוֹד אָבִיו:","הַמֵּת אָסוּר בַּהֲנָאָה כֻּלּוֹ. חוּץ מִשְּׂעָרוֹ שֶׁהוּא מֻתָּר בַּהֲנָאָה מִפְּנֵי שֶׁאֵינוֹ גּוּפוֹ. וְכֵן אֲרוֹנוֹ וְכָל תַּכְרִיכָיו אֲסוּרִין בַּהֲנָאָה. אֲבָל כֵּלִים הַמּוּכָנִים לְתַכְרִיךְ לֹא נֶאֶסְרוּ בַּהֲנָאָה. אֲפִלּוּ אָרַג בֶּגֶד לְמֵת לֹא נֶאֱסַר עַד שֶׁיַּגִּיעַ בַּמִּטָּה הַנִּקְבֶּרֶת עִמּוֹ. שֶׁאֵין הַהַזְמָנָה אוֹסֶרֶת:","כָּל הַכֵּלִים שֶׁזּוֹרְקִין עַל הַמֵּת עַל הַמִּטָּה הַנִּקְבֶּרֶת עִמּוֹ אֲסוּרִין בַּהֲנָאָה. שֶׁלֹּא יִתְחַלְּפוּ בַּתַּכְרִיכִין:","הָיוּ אָבִיו וְאִמּוֹ מְזָרְקִין כֵּלִים בַּחֲמָתָן עַל הַמֵּת. מִצְוָה עַל אֲחֵרִים לְהַצִּילָן. וְאִם הִגִּיעוּ לַמִּטָּה הַנִּקְבֶּרֶת עִמּוֹ אֵין מַצִּילִין אוֹתָן:","מְלַמְּדִין אֶת הָאָדָם שֶׁלֹּא יְהֵא חַבְּלָן וְלֹא יַפְסִיד אֶת הַכֵּלִים וְיַשְׁלִיכֵם לְחַבָּלָה. מוּטָב לְתִתָּם לַעֲנִיִּים וְאַל יַשְׁלִיכֵם לְרִמָּה וְתוֹלֵעָה. וְכָל הַמַּרְבֶּה כֵּלִים עַל הַמֵּת עוֹבֵר בְּלֹא תַשְׁחִית:","מֶלֶךְ שֶׁמֵּת עוֹקְרִין סוּס שֶׁהָיָה רוֹכֵב עָלָיו. וְעֶגְלָה שֶׁהָיְתָה מוֹשֶׁכֶת בַּקָּרוֹן שֶׁהָיָה יוֹשֵׁב בּוֹ מְנַשֵּׁר פַּרְסוֹתֶיהָ מִן הָאַרְכֻּבָּה וּלְמַטָּה מָקוֹם שֶׁאֵין עוֹשֶׂה אוֹתָהּ טְרֵפָה. וּמוֹשִׁיבִין יְשִׁיבָה עַל קִבְרוֹ שִׁבְעָה יָמִים. שֶׁנֶּאֱמַר (דברי הימים ב לב לג) \"וְכָבוֹד עָשׂוּ לוֹ בְמוֹתוֹ\" זֶה שֶׁהוֹשִׁיבוּ לוֹ יְשִׁיבָה עַל קִבְרוֹ. וְנָשִׂיא שֶׁמֵּת אֵין מְבַטְּלִין יְשִׁיבָתוֹ יֶתֶר עַל שְׁלֹשִׁים יוֹם:","מֶלֶךְ אוֹ נָשִׂיא שֶׁמֵּת יֵשׁ לָהֶן לִשְׂרֹף מִטָּתוֹ וְכָל כְּלֵי תַּשְׁמִישׁוֹ. וְאֵין בָּזֶה דֶּרֶךְ הָאֱמוֹרִי. וְלֹא מִשּׁוּם הַשְׁחָתָה. שֶׁנֶּאֱמַר (ירמיה לד ה) \"בְּשָׁלוֹם תָּמוּת וּבְמִשְׂרְפוֹת אֲבוֹתֶיךָ הָרִאשֹׁנִים\" (ירמיה לד ה) \"יִשְׂרְפוּ לָךְ\": סְלִיקוּ לְהוּ הִלְכוֹת אָבֵל בְּסַ\"ד"],"Mishneh Torah, Murderer and the Preservation of Life 12":["בְּהֵמָה חַיָּה אוֹ עוֹף שֶׁנְּשָׁכָן הַנָּחָשׁ וְכַיּוֹצֵא בּוֹ אוֹ שֶׁאָכְלוּ סַם הַמֵּמִית הָאָדָם קֹדֶם שֶׁיִּשְׁתַּנֶּה בְּגוּפָן הֲרֵי אֵלּוּ אֲסוּרִים מִשּׁוּם סַכָּנַת נְפָשׁוֹת. לְפִיכָךְ בְּהֵמָה חַיָּה וְעוֹף שֶׁנִּמְצְאוּ חֲתוּכֵי רַגְלַיִם אַף עַל פִּי שֶׁהֵן מֻתָּרִין מִשּׁוּם טְרֵפָה הֲרֵי אֵלּוּ אֲסוּרִין מִשּׁוּם סַכָּנָה שֶׁמָּא אֶחָד מִזּוֹחֲלֵי עָפָר נְשָׁכָן עַד שֶׁיִּבָּדְקוּ. כֵּיצַד בּוֹדְקָן. צוֹלֶה אוֹתָן בְּתַנּוּר. אִם לֹא נִתְחַתֵּךְ הַבָּשָׂר וְלֹא נִשְׁתַּנָּה מִשְּׁאָר הַצָּלִי הֲרֵי אֵלּוּ מֻתָּרִין:","וְכֵן נִקּוּרֵי תְּאֵנִים וַעֲנָבִים וְהַקִּשּׁוּאִים וְהַדִּלּוּעִין וְהָאֲבַטִּיחִין וְהַמְּלָפְפוֹנוֹת אֲפִלּוּ הָיוּ גְּדוֹלִים בְּיוֹתֵר בֵּין תְּלוּשִׁין בֵּין מְחֻבָּרִין וַאֲפִלּוּ הָיוּ בְּתוֹךְ הַכְּלִי כָּל שֶׁיֵּשׁ בּוֹ לֵחָה וְנִמְצָא נָשׁוּךְ אָסוּר שֶׁמָּא נָחָשׁ וְכַיּוֹצֵא בּוֹ נְשָׁכוֹ. וַאֲפִלּוּ רָאָה צִפּוֹר אוֹ עַכְבָּר יוֹשֵׁב וּמְנַקֵּר הֲרֵי אֵלּוּ אֲסוּרִין שֶׁמָּא בִּמְקוֹם נֶקֶב נִקַּב:","תְּאֵנָה אוֹ עֵנָב שֶׁנִּטַּל הָעֹקֶץ שֶׁלָּהֶן אֵין בָּהֶם מִשּׁוּם גִּלּוּי. לְפִיכָךְ אוֹכֵל אָדָם תְּאֵנִים וַעֲנָבִים בַּלַּיְלָה וְאֵינוֹ חוֹשֵׁשׁ. תְּאֵנָה נְקוּרָה שֶׁיָּבְשָׁה וְנַעֲשֵׂית גְּרוֹגֶרֶת וּתְמָרָה נְקוּרָה שֶׁיָּבְשָׁה שְׁתֵּיהֶן מֻתָּרוֹת:","אָסוּר לְאָדָם לִתֵּן מָעוֹת אוֹ דִּינָרִים לְתוֹךְ פִּיו שֶׁמָּא יֵשׁ עֲלֵיהֶן רֹק יָבֵשׁ שֶׁל מֻכֵּי שְׁחִין אוֹ מְצֹרָעִין אוֹ זֵעָה. שֶׁכָּל זֵעַת אָדָם סַם הַמָּוֶת חוּץ מִזֵּעַת הַפָּנִים:","וְכֵן לֹא יִתֵּן אָדָם פַּס יָדוֹ תַּחַת שֶׁחְיוֹ שֶׁמָּא נָגַע בְּיָדוֹ בִּמְצֹרָע אוֹ בְּסַם רַע שֶׁהַיָּדַיִם עַסְקָנִיּוֹת. וְלֹא יִתֵּן הַתַּבְשִׁיל תַּחַת הַמִּטָּה אַף עַל פִּי שֶׁהוּא עוֹסֵק בִּסְעוּדָה שֶׁמָּא יִפּל בּוֹ דָּבָר הַמַּזִּיק וְהוּא אֵינוֹ רוֹאֵהוּ:","וְכֵן לֹא יִנְעֹץ הַסַּכִּין בְּתוֹךְ הָאֶתְרוֹג אוֹ בְּתוֹךְ הַצְּנוֹן שֶׁמָּא יִפּל אָדָם עַל חֻדָּהּ וְיָמוּת. וְכֵן אָסוּר לָאָדָם לַעֲבֹר תַּחַת קִיר נָטוּי אוֹ עַל גֶּשֶׁר רָעוּעַ אוֹ לִכָּנֵס לְחֻרְבָּה. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ מִשְּׁאָר הַסַּכָּנוֹת אָסוּר לַעֲבֹר בִּמְקוֹמָן:","וְכֵן אָסוּר לִיהוּדִי לְהִתְיַחֵד עִם הָעַכּוּ\"ם מִפְּנֵי שֶׁהֵן חֲשׁוּדִים עַל שְׁפִיכוּת דָּמִים. וְלֹא יִתְלַוֶּה עִמָּהֶן בַּדֶּרֶךְ. פָּגַע עַכּוּ\"ם בַּדֶּרֶךְ מַחְזִירוֹ לִימִינוֹ. הָיוּ עוֹלִין בְּמַעֲלֶה אוֹ יוֹרְדִים בִּירִידָה לֹא יִהְיֶה יִשְׂרָאֵל לְמַטָּה וְעַכּוּ\"ם לְמַעְלָה אֶלָּא יִשְׂרָאֵל לְמַעְלָה וְעַכּוּ\"ם לְמַטָּה שֶׁמָּא יִפּל עָלָיו לַהֲמִיתוֹ. וְאַל יָשֹׁחַ לְפָנָיו שֶׁמָּא יָרֹץ אֶת גֻּלְגָּלְתּוֹ:","אִם שְׁאָלוֹ לְאָן אַתָּה הוֹלֵךְ יַרְחִיב לוֹ אֶת הַדֶּרֶךְ כְּדֶרֶךְ שֶׁהִרְחִיב יַעֲקֹב לְעֵשָׂו שֶׁנֶּאֱמַר (בראשית לג יד) \"עַד אֲשֶׁר אָבֹא אֶל אֲדֹנִי שֵׂעִירָה\":","אָסוּר לִקַּח רְפוּאָה מִן הָעַכּוּ\"ם אֶלָּא אִם כֵּן נִתְיָאֲשׁוּ מִמֶּנּוּ שֶׁיִּחְיֶה. וְאָסוּר לְהִתְרַפְּאוֹת מִן הָאֶפִּיקוֹרוֹס וְאַף עַל פִּי שֶׁנִּתְיָאֲשׁוּ מִמֶּנּוּ שֶׁמָּא יִמָּשְׁכוּ אַחֲרָיו. וּמֻתָּר לִקַּח רְפוּאָה מִן הָעַכּוּ\"ם לִבְהֵמָה אוֹ לְמַכָּה שֶׁבַּגּוּף מִבַּחוּץ כְּגוֹן מְלוּגְמָא וּרְטִיָּה. וְאִם הָיְתָה מַכָּה שֶׁל סַכָּנָה אָסוּר לִקַּח מִמֶּנּוּ. וְכָל מַכָּה שֶׁמְּחַלְּלִין עָלֶיהָ אֶת הַשַּׁבָּת אֵין מִתְרַפְּאִין מֵהֶם:","וּמֻתָּר לִשְׁאוֹל לְרוֹפֵא עַכּוּ\"ם וְיֹאמַר לוֹ סַם פְּלוֹנִי יָפֶה לְךָ וְכָךְ וְכָךְ תַּעֲשֶׂה אֲבָל לֹא יִקַּח מִמֶּנּוּ:","וְאָסוּר לְהִסְתַּפֵּר מֵהֶן בִּרְשׁוּת הַיָּחִיד שֶׁמָּא יַהַרְגֶנּוּ. אִם הָיָה אָדָם חָשׁוּב מֻתָּר מִפְּנֵי שֶׁמִּתְיָרֵא לְהָרְגוֹ. וְאִם דִּמָּה לְעַכּוּ\"ם שֶׁהוּא אָדָם חָשׁוּב כְּדֵי שֶׁיְּפַחֵד מִמֶּנּוּ וְלֹא יַהַרְגֶנּוּ הֲרֵי זֶה מֻתָּר לְהִסְתַּפֵּר מִמֶּנּוּ:","אָסוּר לִמְכֹּר לְעַכּוּ\"ם כָּל כְּלֵי הַמִּלְחָמָה וְאֵין מַשְׁחִיזִין לָהֶם אֶת הַזַּיִן וְאֵין מוֹכְרִין לָהֶן לֹא סַכִּין וְלֹא קוֹלָרִין וְלֹא כְּבָלִים [שֶׁל בַּרְזֶל] וְלֹא שַׁלְשְׁלָאוֹת שֶׁל בַּרְזֶל הִינְדּוּאָה וְלֹא דֻּבִּים וַאֲרָיוֹת וְלֹא כָּל דָּבָר שֶׁיֵּשׁ בּוֹ נֵזֶק לָרַבִּים. אֲבָל מוֹכְרִין לָהֶן תְּרִיסִין שֶׁאֵינָן אֶלָּא לְהָגֵן:","וּכְשֵׁם שֶׁאָסְרוּ לִמְכֹּר לְעַכּוּ\"ם כָּךְ אָסְרוּ לִמְכֹּר לְיִשְׂרָאֵל שֶׁמּוֹכֵר לְעַכּוּ\"ם. וּמֻתָּר לִמְכֹּר כְּלֵי זַיִן לְחַיִל שֶׁל בְּנֵי הַמְּדִינָה מִפְּנֵי שֶׁהֵן מְגִנִּין עַל יִשְׂרָאֵל:","כָּל שֶׁאָסוּר לִמְכֹּר לְעַכּוּ\"ם אָסוּר לִמְכֹּר לְיִשְׂרָאֵל שֶׁהוּא לִסְטִים מִפְּנֵי שֶׁנִּמְצָא מַחֲזִיק יְדֵי עוֹבְרֵי עֲבֵרָה וּמַכְשִׁילוֹ. וְכֵן כָּל הַמַּכְשִׁיל עִוֵּר בְּדָבָר וְהִשִּׂיאוֹ עֵצָה שֶׁאֵינָהּ הוֹגֶנֶת אוֹ שֶׁחִזֵּק יְדֵי עוֹבְרֵי עֲבֵרָה שֶׁהוּא עִוֵּר וְאֵינוֹ רוֹאֶה דֶּרֶךְ הָאֱמֶת מִפְּנֵי תַּאֲוַת לִבּוֹ הֲרֵי זֶה עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (ויקרא יט יד) \"וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁל\". הַבָּא לִטּל מִמְּךָ עֵצָה תֵּן לוֹ עֵצָה הַהוֹגֶנֶת לוֹ:","וְאָסוּר לְהַשִּׂיא עֵצָה טוֹבָה לְעַכּוּ\"ם אוֹ לְעֶבֶד רָשָׁע. וַאֲפִלּוּ לְהַשִּׂיאוֹ עֵצָה שֶׁיַּעֲשֶׂה דְּבַר מִצְוָה וְהוּא עוֹמֵד בְּרִשְׁעוֹ אָסוּר. וְלֹא נִתְנַסָּה דָּנִיֵּאל אֶלָּא עַל שֶׁהִשִּׂיא עֵצָה לִנְבוּכַדְנֶצַּר לִתֵּן צְדָקָה שֶׁנֶּאֱמַר לָהֶן (דניאל ד כד) \"מַלְכָּא מִלְכִּי יִשְׁפַּר עֲלָךְ\":"],"Mishneh Torah, Nazariteship 2":["הַנּוֹדֵר בְּנָזִיר בְּשׁוֹגֵג אוֹ בְּאֹנֶס אוֹ שֶׁנָּדַר לְזָרֵז חֲבֵרוֹ אוֹ דֶּרֶךְ הֲבַאי הֲרֵי זֶה פָּטוּר כִּשְׁאָר נְדָרִים. וּמִי שֶׁנָּדַר בְּנָזִיר וְנִחָם עַל נִדְרוֹ הֲרֵי זֶה נִשְׁאָל לְחָכָם וּמַתִּיר לוֹ נְזִירוּתוֹ כְּדֶרֶךְ שֶׁמַּתִּירִין שְׁאָר הַנְּדָרִים:","מִי שֶׁנָּדַר בְּנָזִיר וְהָלַךְ לְהָבִיא קָרְבְּנוֹתָיו שֶׁנָּזַר עַל דַּעַת שֶׁיְּבִיאֵם בִּמְלֹאת יְמֵי נִזְרוֹ. מְצָאָן שֶׁנִּגְנְבוּ אוֹ נִגְנְבָה בְּהֵמָה מֵהֶן. אִם עַד שֶׁלֹּא נִגְנְבָה הַבְּהֵמָה נָזַר הֲרֵי זֶה נָזִיר. וְאִם אַחַר שֶׁנִּגְנְבָה אוֹ שֶׁאָבְדָה אוֹ שֶׁמֵּתָה נָזַר אֵינוֹ נָזִיר שֶׁזֶּה נָזַר בְּטָעוּת:","הַמַּתְפִּיס בִּנְזִירוּת הֲרֵי זֶה נָזִיר כְּמוֹ שֶׁבֵּאַרְנוּ בְּדִין כָּל הַמַּתְפִּיס בְּנֵדֶר:","הָיָה נָזִיר עוֹבֵר לְפָנָיו וְאָמַר הֲרֵינִי כָּזֶה הֲרֵי זֶה נָזִיר. נָדַר חֲבֵרוֹ בְּנָזִיר וְאָמַר הוּא פִּי כְּפִיו מִיַּיִן אוֹ שֶׁאָמַר שְׂעָרִי כִּשְׂעָרוֹ מִלְּהִגָּזֵז הֲרֵי זֶה נָזִיר. וְכֵן אִם שָׁמַע וְאָמַר וַאֲנִי בְּתוֹךְ כְּדֵי דִּבּוּר [וְשָׁמַע שְׁלִישִׁי בְּתוֹךְ כְּדֵי דִּבּוּר] שֶׁל שֵׁנִי וְאָמַר וַאֲנִי וַאֲפִלּוּ הֵן מֵאָה כֻּלָּן נְזִירִין:","הָאוֹמֵר הֲרֵינִי נָזִיר כְּשֶׁיִּהְיֶה לִי בֵּן וַחֲבֵרוֹ אָמַר וַאֲנִי הֲרֵי חֲבֵרוֹ נָזִיר מִיָּד:","הָאוֹמֵר לַחֲבֵרוֹ הֲרֵינִי נָזִיר כְּשֶׁיִּהְיֶה לְךָ בֵּן וְשָׁמַע חֲבֵרוֹ וְאָמַר וַאֲנִי אֵין זֶה נָזִיר. שֶׁלֹּא נִתְכַּוֵּן זֶה הָאַחֲרוֹן אֶלָּא לוֹמַר שֶׁאֲנִי אוֹהֵב שֶׁיִּהְיֶה לְךָ בֵּן כְּמוֹ זֶה שֶׁהֲרֵי הוּא בּוֹשׁ מִמֶּנּוּ:","הָאוֹמֵר הֲרֵינִי נָזִיר כְּשֶׁיִּהְיֶה לִפְלוֹנִי בֵּן וְשָׁמַע חֲבֵרוֹ וְאָמַר וַאֲנִי. הֲרֵי זֶה סָפֵק שֶׁמָּא לֹא נִתְכַּוֵּן אֶלָּא לִהְיוֹת נָזִיר כְּמוֹתוֹ אוֹ לוֹמַר שֶׁאֲנִי אוֹהֵב אוֹתוֹ כְּמוֹתְךָ. וּסְפֵק נְזִירוּת לְהָקֵל:","שְׁנַיִם שֶׁהָיוּ מְהַלְּכִים בַּדֶּרֶךְ וְרָאוּ אֶחָד בָּא כְּנֶגְדָּן וְאָמַר אֶחָד מִן הַשְּׁנַיִם זֶה הַהוֹלֵךְ כְּנֶגְדֵּנוּ שִׁמְעוֹן הוּא. וְאָמַר חֲבֵרוֹ רְאוּבֵן הוּא. וְאָמַר זֶה הֲרֵינִי נָזִיר אִם יִהְיֶה רְאוּבֵן. וְאָמַר הָאַחֵר הֲרֵינִי נָזִיר אִם יִהְיֶה שִׁמְעוֹן. הִגִּיעַ אֲלֵיהֶם וַהֲרֵי הוּא רְאוּבֵן הֲרֵי זֶה נָזִיר. וְאִם הָיָה שִׁמְעוֹן הֲרֵי חֲבֵרוֹ נָזִיר כְּמוֹ שֶׁנָּדְרוּ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. לֹא הִגִּיעַ אֲלֵיהֶם אֶלָּא חָזַר לַאֲחוֹרָיו וְנֶעְלַם מֵעֵינֵיהֶם וְלֹא יָדְעוּ מִי הוּא אֵין אֶחָד מֵהֶן נָזִיר:","וְכֵן הָאוֹמֵר הֲרֵינִי נָזִיר אִם יִהְיֶה בִּכְרִי זֶה מֵאָה כּוֹר וְהָלַךְ לְמוֹדְדוֹ וּמְצָאוֹ שֶׁנִּגְנַב אוֹ שֶׁאָבַד אֵינוֹ נָזִיר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. שֶׁסָּפֵק נְזִירוּת לְהָקֵל:","הָיוּ מְהַלְּכִין בַּדֶּרֶךְ וְרָאוּ אֶת הַכְּוִי מֵרָחוֹק וְאָמַר אֶחָד מֵהֶם הֲרֵינִי נָזִיר שֶׁזֶּה חַיָּה. וְאָמַר אַחֵר הֲרֵינִי נָזִיר שֶׁזֶּה בְּהֵמָה. וְאָמַר אַחֵר הֲרֵינִי נָזִיר שֶׁאֵין זֶה חַיָּה. וְאָמַר אַחֵר הֲרֵינִי נָזִיר שֶׁאֵין זֶה בְּהֵמָה. וְאָמַר אַחֵר הֲרֵינִי נָזִיר שֶׁאֵין זֶה לֹא חַיָּה וְלֹא בְּהֵמָה. וְאָמַר אַחֵר הֲרֵינִי נָזִיר שֶׁזֶּה בְּהֵמָה וְחַיָּה הֲרֵי כֻּלָּם נְזִירִים. מִפְּנֵי שֶׁהַכְּוִי יֵשׁ בּוֹ דְּרָכִים שָׁוֶה בָּהֶן לְחַיָּה וְיֵשׁ בּוֹ דְּרָכִים שָׁוֶה בָּהֶן לִבְהֵמָה וְיֵשׁ בּוֹ דְּרָכִים שָׁוֶה לְחַיָּה וְלִבְהֵמָה וְיֵשׁ בּוֹ דְּרָכִים שֶׁאֵינוֹ שָׁוֶה לֹא לִבְהֵמָה וְלֹא לְחַיָּה. וְהוּא הַדִּין אִם רָאוּ אַנְדְּרוֹגִינוּס וְנֶחְלְקוּ בּוֹ אִם הוּא אִישׁ אוֹ אִשָּׁה וְנָדְרוּ עַל דֶּרֶךְ שֶׁנָּדְרוּ אֵלּוּ בִּכְוִי הֲרֵי כֻּלָּם נְזִירִים. שֶׁהָאַנְדְּרוֹגִינוּס יֵשׁ בּוֹ דְּרָכִים שָׁוֶה בָּהֶן לְאִישׁ. וּדְרָכִים שָׁוֶה בָּהֶן לְאִשָּׁה. וּדְרָכִים שֶׁאֵינוֹ שָׁוֶה בָּהֶן לֹא לְאִישׁ וְלֹא לְאִשָּׁה. וּדְרָכִים שֶׁהֵן שָׁוִין לְאִישׁ וּלְאִשָּׁה:","וְכָל הַדְּרָכִים הָאֵלּוּ בְּעִנְיְנֵי הַמִּצְוֹת וְלֹא בְּטִבְעוֹ וְתוֹלַדְתּוֹ. וְכֵן דַּרְכֵי הַכְּוִי בְּעִנְיְנֵי הַמִּצְוֹת לֹא בְּטִבְעוֹ וְתוֹלַדְתּוֹ. כֵּיצַד. דָּמוֹ טָעוּן כִּסּוּי כְּחַיָּה וְחֶלְבּוֹ אָסוּר כִּבְהֵמָה. וַהֲרֵי הוּא כִּלְאַיִם עִם הַבְּהֵמָה וְכֵן עִם הַחַיָּה כְּאִלּוּ אֵינָהּ חַיָּה וְלֹא בְּהֵמָה. וְטָעוּן שְׁחִיטָה כִּבְהֵמָה וְחַיָּה. וְיֵשׁ בּוֹ דְּרָכִים אֲחֵרִים וְכָל אֶחָד מֵהֶן יִתְבָּאֵר בִּמְקוֹמוֹ. וְכֵן אַנְדְּרוֹגִינוּס מִטַּמֵּא בְּלֹבֶן כַּאֲנָשִׁים. וּמִטַּמֵּא בְּאֹדֶם כְּנָשִׁים. וְאֵינוֹ נִמְכָּר בְּעֶבֶד עִבְרִי לֹא כַּאֲנָשִׁים וְלֹא כְּנָשִׁים. וְהַהוֹרְגוֹ נֶהֱרָג עָלָיו כַּאֲנָשִׁים וּכְנָשִׁים. וְיֵשׁ בּוֹ דִּינִים אֲחֵרִים וְכָל אֶחָד יִכָּתֵב בִּמְקוֹמוֹ:","וְכֵן אִם רָאוּ אֲנָשִׁים בָּאִים כְּנֶגְדָּם מֵהֶם פִּקְחִים וּמֵהֶם סוּמִים וְאָמַר אֶחָד הֲרֵינִי נָזִיר שֶׁאֵלּוּ פִּקְחִין. וְאָמַר אַחֵר הֲרֵינִי נָזִיר שֶׁאֵין אֵלּוּ פִּקְחִין. וְאָמַר אַחֵר הֲרֵי אֲנִי נָזִיר שֶׁאֵלּוּ סוּמִין. וְאָמַר אַחֵר הֲרֵינִי נָזִיר שֶׁאֵין אֵלּוּ סוּמִין. וְאָמַר אַחֵר הֲרֵינִי נָזִיר שֶׁאֵלּוּ פִּקְחִין וְסוּמִין. וְאָמַר אַחֵר הֲרֵינִי נָזִיר שֶׁאֵין אֵלּוּ לֹא פִּקְחִין וְלֹא סוּמִין. הֲרֵי כֻּלָּם נְזִירִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","קָטָן שֶׁהִגִּיעַ לְעוֹנַת נְדָרִים וְנָדַר בְּנָזִיר הֲרֵי זֶה נָזִיר וּמֵבִיא קָרְבְּנוֹתָיו. וְאַף עַל פִּי שֶׁעֲדַיִן לֹא הֵבִיא שְׁתֵּי שְׂעָרוֹת כִּשְׁאָר הַנְּדָרִים. וְהָאִישׁ מַדִּיר אֶת בְּנוֹ קָטָן בְּנָזִיר אַף עַל פִּי שֶׁלֹּא בָּא לְעוֹנַת נְדָרִים. וְאֵין הָאִשָּׁה מַדֶּרֶת אֶת בְּנָהּ בְּנָזִיר. וְדָבָר זֶה הֲלָכָה מִפִּי הַקַּבָּלָה הוּא וְאֵינוֹ נוֹהֵג בִּשְׁאָר נְדָרִים:","כֵּיצַד. הָאָב שֶׁאָמַר לִבְנוֹ הַקָּטָן הֲרֵי אַתָּה נָזִיר. אוֹ שֶׁאָמַר בְּנִי פְּלוֹנִי נָזִיר אוֹ הֲרֵי זֶה נָזִיר. וְשָׁתַק הַבֵּן. הֲרֵי זֶה נָזִיר וְחַיָּב הָאָב לִנְהֹג בּוֹ כָּל דִּקְדּוּקֵי נְזִירוּת וְאִם נִטְמָא מֵבִיא קָרְבַּן טֻמְאָה. וּכְשֶׁיַּשְׁלִים נְזִירוּתוֹ מֵבִיא קָרְבַּן טָהֳרָה כִּשְׁאָר הַנְּזִירִים הַגְּדוֹלִים:","לֹא רָצָה הַבֵּן וּמִחָה בְּדָבָר זֶה אוֹ שֶׁמִּחוּ קְרוֹבָיו אוֹ שֶׁגִּלֵּחַ שְׂעָרוֹ אוֹ שֶׁגִּלְּחוּהוּ קְרוֹבָיו שֶׁהֲרֵי נַעֲשָׂה מַעֲשֶׂה שֶׁגִּלָּה דַּעְתּוֹ שֶׁלֹּא רָצָה הוּא אוֹ קְרוֹבָיו בִּנְזִירוּת זוֹ הֲרֵי זֶה אֵינוֹ נָזִיר. וְעַד מָתַי יֵשׁ לוֹ לְהַדִּירוֹ עַד שֶׁיַּגְדִּיל וְיֵעָשֶׂה אִישׁ:","הָעַכּוּ\"ם אֵין לָהֶן נְזִירוּת. שֶׁנֶּאֱמַר (במדבר ו ב) \"דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל\":","נָשִׁים וַעֲבָדִים יֵשׁ לָהֶן נְזִירוּת. וְהָאָב אוֹ הַבַּעַל מֵפֵר נְזִירוּת הָאִשָּׁה אִם רָצָה כִּשְׁאָר הַנְּדָרִים. אֲבָל הָעֶבֶד יֵשׁ לְרַבּוֹ לָכֹף אוֹתוֹ לִשְׁתּוֹת וּלְהִטָּמֵא לַמֵּתִים וְאִם לֹא כָּפָה אוֹתוֹ נוֹהֵג נְזִירוּת:","נָדַר הָעֶבֶד שְׁאָר נְדָרִים שֶׁיֵּשׁ בָּהֶן עִנּוּי נֶפֶשׁ אוֹ שֶׁמְּעַכְּבִין אֶת הַמְּלָאכָה אוֹ שֶׁהֶעֱרִיךְ. אֵין רַבּוֹ צָרִיךְ לְכֻפּוֹ מִפְּנֵי שֶׁאֵין נַפְשׁוֹ קְנוּיָה לוֹ וְלֹא יָחוּל עָלָיו נֶדֶר. לְמָה הַדָּבָר דּוֹמֶה לְאוֹסֵר פֵּרוֹת אֲחֵרִים עֲלֵיהֶם. אֲבָל אִם אֵין שָׁם עִנּוּי וְלֹא דָּבָר שֶׁמְּעַכֵּב מְלָאכָה אֵינוֹ יָכוֹל לְכֻפּוֹ. נָדַר עַבְדּוֹ בִּנְזִירוּת וְאָמַר לוֹ מוּפָר לְךָ יָצָא לְחֵרוּת וְחַיָּב לְהַשְׁלִים נְזִירוּתוֹ. שֶׁהָעֶבֶד כּוֹפִין אוֹתוֹ וְאֵין מְפֵרִין לוֹ. וְאִם הֵפֵר יָצָא לְחֵרוּת:","עֶבֶד שֶׁנָּדַר בִּנְזִירוּת וּבָרַח אוֹ שֶׁהָלַךְ מֵרַבּוֹ הֲרֵי זֶה אָסוּר לִשְׁתּוֹת יַיִן כְּדֵי שֶׁיִּצְטַעֵר וְיַחְזֹר לִרְשׁוּת רַבּוֹ. נָזַר וְהִשְׁלִים נְזִירוּתוֹ וְגִלֵּחַ וְלֹא יְדָעוֹ רַבּוֹ וְאַחַר כָּךְ יָצָא לְחֵרוּת הֲרֵי זֶה יָצָא יְדֵי נִדְרוֹ. אֲבָל אִם נָדַר וְלֹא גִּלֵּחַ וְיָצָא לְחֵרוּת לֹא יָצָא יְדֵי נִדְרוֹ. נִטְמָא וְאַחַר כָּךְ יָצָא לְחֵרוּת מוֹנֶה מִשָּׁעָה שֶׁנִּטְמָא:","נְזִירוּת נוֹהֶגֶת בִּפְנֵי הַבַּיִת וְשֶׁלֹּא בִּפְנֵי הַבַּיִת. לְפִיכָךְ מִי שֶׁנָּדַר בְּנָזִיר בַּזְּמַן הַזֶּה הֲרֵי זֶה נָזִיר לְעוֹלָם. שֶׁאֵין לָנוּ בַּיִת כְּדֵי שֶׁיָּבִיא קָרְבְּנוֹתָיו בִּמְלֹאת יְמֵי נִזְרוֹ:","אֵין הַנְּזִירוּת נוֹהֶגֶת אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל. וּמִי שֶׁנָּזַר בְּחוּצָה לָאָרֶץ קוֹנְסִין אוֹתוֹ וּמְחַיְּבִין אוֹתוֹ לַעֲלוֹת לְאֶרֶץ יִשְׂרָאֵל וְלִהְיוֹת נָזִיר בְּאֶרֶץ יִשְׂרָאֵל כְּמִנְיַן הַיָּמִים שֶׁנָּזַר. לְפִיכָךְ מִי שֶׁנָּדַר בַּזְּמַן הַזֶּה בְּחוּצָה לָאָרֶץ כּוֹפִין אוֹתוֹ לַעֲלוֹת לְאֶרֶץ יִשְׂרָאֵל וְלִהְיוֹת נוֹהֵג שָׁם נְזִירוּת עַד שֶׁיָּמוּת אוֹ עַד שֶׁיִּבָּנֶה הַמִּקְדָּשׁ וְיָבִיא קָרְבְּנוֹתָיו בִּמְלֹאת יְמֵי נִזְרוֹ:","וְכָל זְמַן שֶׁהוּא בְּחוּצָה לָאָרֶץ הֲרֵי זֶה אָסוּר לִשְׁתּוֹת יַיִן וּלְהִטָּמֵא לַמֵּתִים וּלְגַלֵּחַ וְכָל דִּקְדּוּקֵי נְזִירוּת עָלָיו וְאַף עַל פִּי שֶׁאֵין יָמִים אֵלּוּ עוֹלִין לוֹ. וְאִם עָבַר וְשָׁתָה אוֹ גִּלֵּחַ אוֹ נָגַע בְּמֵת וְכַיּוֹצֵא בִּנְגִיעָה לוֹקֶה:"],"Mishneh Torah, Negative Mitzvot 102":["שלא ליתן שמן זית במנחת חוטא, שנאמר \"לא ישים עליה שמן\" (ויקרא ה,יא)."],"Mishneh Torah, Negative Mitzvot 113":["שלא לעבוד בקודשים, שנאמר \"לא תעבוד בבכור שורך\" (דברים טו,יט)."],"Mishneh Torah, Negative Mitzvot 124":["שלא לעשות שיירי מנחות חמץ, שנאמר \"לא תיאפה חמץ, חלקם\" (ויקרא ו,י)."],"Mishneh Torah, Negative Mitzvot 135":["שלא יאכל ערל תרומה, והוא הדין לשאר קודשים. .ודבר זה לימדו הכתוב מן הפסח בגזירה שווה, ואינו בפירוש מן התורה; ומפי השמועה למדו שאיסור ערל בקודשים מגופי תורה, ואינו מדברי סופרים."],"Mishneh Torah, Negative Mitzvot 146":["שלא לאכול בשר העולה, שנאמר \"לא תוכל . . . נדריך אשר תידור\" (דברים יב,יז); כלומר, לא תוכל לאכול נדריך אשר תידור. .וזו היא אזהרה של כל מועל, שלא ייהנה מן הקודשים האסורים ליהנות מהם; ואם נהנה, מעל."],"Mishneh Torah, Negative Mitzvot 157":["שלא לעבור על דברים שאסר אדם על נפשו, שנאמר \"לא יחל, דברו\" (במדבר ל,ג)."],"Mishneh Torah, Negative Mitzvot 168":["שלא ייכנס כוהן גדול עם מת, שנאמר \"ועל כל נפשות מת, לא יבוא\" (ויקרא כא,יא); כך למדו מפי השמועה, שהוא חייב בבל יבוא וחייב בבל ייטמא."],"Mishneh Torah, Negative Mitzvot 179":["שלא לאכול שרץ המים, שנאמר \"אל תשקצו, את נפשותיכם, בכל השרץ\" (ויקרא יא,מג)."],"Mishneh Torah, Negative Mitzvot 19":["שלא להציל המסית אלא עומד על דמו, שנאמר \"לא תחוס עינך עליו\" (דברים יג,ט)."],"Mishneh Torah, Negative Mitzvot 20":["שלא ילמד המוסת זכות על המסית, שנאמר \"לא תחמול\" (דברים יג,ט)."],"Mishneh Torah, Negative Mitzvot 210":["שלא לקצור כל השדה, שנאמר \"לא תכלה פאת שדך בקוצרך\" (ויקרא כג,כב)."],"Mishneh Torah, Negative Mitzvot 221":["שלא לעבוד אילן בשביעית, שנאמר \"וכרמך לא תזמור\" (ויקרא כה,ד)."],"Mishneh Torah, Negative Mitzvot 232":["שלא יימנע מלהחיות לעני ומליתן לו מה שהוא צריך, שנאמר \"לא תאמץ את לבבך\" (דברים טו,ז); נמצא הנותן צדקה עושה מצות עשה, והמעלים עיניו מן הצדקה יתר על שביטל עשה עבר על לא תעשה."],"Mishneh Torah, Negative Mitzvot 243":["שלא לגנוב נפש מישראל, שנאמר \"לא תגנוב\" (שמות כ,יב; דברים ה,טז); זה גונב נפש."],"Mishneh Torah, Negative Mitzvot 254":["שלא להחזיר עבד שברח לארץ ישראל לאדוניו שבחוצה לארץ, שנאמר \"לֹא תַסְגִּיר עֶבֶד אֶל אֲדוֹנָיו\" (דברים כג, טז)."],"Mishneh Torah, Negative Mitzvot 265":["שלא לחמוד, שנאמר \"לֹא תַחְמֹד אֵשֶׁת רֵעֶךָ\" (שמות כ, יג)."],"Mishneh Torah, Negative Mitzvot 276":["שלא יירא הדיין בדין מאדם רע, שנאמר \"לֹא תָגוּרוּ מִפְּנֵי אִישׁ\" (דברים א, יז)."],"Mishneh Torah, Negative Mitzvot 287":["שלא יעיד קרוב, שנאמר \"לֹא יוּמְתוּ אָבוֹת עַל בָּנִים\" (דברים כד, טז); מפי השמועה למדו שלא יומתו אבות בעדות בנים, והוא הדין לשאר הקרובים."],"Mishneh Torah, Negative Mitzvot 298":["שלא להניח מכשול, שנאמר \"וְלֹא תָשִׂים דָּמִים בְּבֵיתֶךָ\" (דברים כב, ח)."],"Mishneh Torah, Negative Mitzvot 308":["שלא לתלוש סימני צרעת, שנאמר \"הישמר בנגע הצרעת\" (דברים כד,ח)."],"Mishneh Torah, Negative Mitzvot 319":["שלא להכות אב ואם, שנאמר \"ומכה אביו ואימו, מות יומת\" (שמות כא,טו)."],"Mishneh Torah, Negative Mitzvot 33":["שלא לנחש, שנאמר \"לא תנחשו\" (ויקרא יט,כו)."],"Mishneh Torah, Negative Mitzvot 340":["שלא לגלות ערוות אחות האב, שנאמר \"ערוות אחות אביך, לא תגלה\" (ויקרא יח,יב)."],"Mishneh Torah, Negative Mitzvot 351":["שלא לגלות ערוות האב עצמו, שנאמר \"ערוות אביך . . . לא תגלה\" (ויקרא יח,ז)."],"Mishneh Torah, Negative Mitzvot 362":["שלא למנות על ישראל איש מקהל גרים, שנאמר \"לא תוכל לתת עליך איש נוכרי\" (דברים יז,טו)."],"Mishneh Torah, Negative Mitzvot 44":["שלא להשחית כל הזקן כעובדי עבודה זרה, שנאמר \"ולא תשחית, את פאת זקנך\" (ויקרא יט,כז)."],"Mishneh Torah, Negative Mitzvot 55":["שלא להרחיק מצרי מלבוא בקהל אלא עד שלושה דורות, שנאמר \"לא תתעב מצרי\" (דברים כג,ח)."],"Mishneh Torah, Negative Mitzvot 66":["שלא ילין הצלוב על העץ, שנאמר \"לֹא תָלִין נִבְלָתוֹ עַל הָעֵץ\" (דברים כא, כג)."],"Mishneh Torah, Negative Mitzvot 77":["שלא יכנס טמא לעזרה, שנאמר \"וְלֹא יְטַמְּאוּ אֶת מַחֲנֵיהֶם\" (במדבר ה, ג); זה מחנה שכינה."],"Mishneh Torah, Negative Mitzvot 88":["שלא ייקרע המעיל, שנאמר \"כפי תחרא יהיה לו--לא ייקרע\" (שמות כח,לב)."],"Mishneh Torah, Negative Mitzvot 99":["שלא להקריב תפל, שנאמר \"ולא תשבית מלח ברית אלוהיך\" (ויקרא ב,יג)."],"Mishneh Torah, Neighbors 7":["מִי שֶׁהָיְתָה לוֹ חַלּוֹן בְּכָתְלוֹ וּבָא חֲבֵרוֹ וְעָשָׂה חָצֵר בְּצִדּוֹ אֵינוֹ יָכוֹל לוֹמַר לְבַעַל הַחַלּוֹן סְתֹם חַלּוֹן זֶה כְּדֵי שֶׁלֹּא תַּבִּיט בִּי שֶׁהֲרֵי הֶחֱזִיק בְּהֶזֵּק זֶה. וְאִם בָּא חֲבֵרוֹ לִבְנוֹת כָּתְלוֹ כְּנֶגֶד הַחַלּוֹן כְּדֵי שֶׁיָּסוּר הֶזֵּק רְאִיָּתוֹ צָרִיךְ לְהַרְחִיק אֶת כָּתְלוֹ מִכְּנֶגֶד הַחַלּוֹן אַרְבַּע אַמּוֹת כְּדֵי שֶׁלֹּא יַאֲפִיל עָלָיו:","הָיְתָה הַחַלּוֹן לְמַטָּה בַּכֹּתֶל כּוֹפֶה אֶת חֲבֵרוֹ לִבְנוֹת כְּנֶגְדָּהּ בְּרִחוּק אַרְבַּע אַמּוֹת וּלְהַגְבִּיהַּ הַבִּנְיָן אַרְבַּע אַמּוֹת כְּדֵי שֶׁלֹּא יַבִּיט בּוֹ מִן הַחַלּוֹן:","הָיְתָה הַחַלּוֹן לְמַעְלָה בַּכֹּתֶל וּבָנָה חֲבֵרוֹ כֹּתֶל כְּנֶגֶד הַחַלּוֹן מִלְּמַטָּה אִם הָיָה מֵרֹאשׁ הַכֹּתֶל שֶׁבָּנָה עַד הַחַלּוֹן גֹּבַהּ אַרְבַּע אַמּוֹת אוֹ יוֹתֵר אֵינוֹ יָכוֹל לְמָנְעוֹ אַף עַל פִּי שֶׁלֹּא הִרְחִיק מִכֹּתֶל הַחַלּוֹן כְּלוּם שֶׁהֲרֵי לֹא הֶאֱפִיל עָלָיו וְאֵינוֹ מַזִּיקוֹ בִּרְאִיָּה. אֲבָל אִם נִשְׁאַר גֹּבַהּ מֵרֹאשׁ הַכֹּתֶל עַד הַחַלּוֹן פָּחוֹת מֵאַרְבַּע אַמּוֹת כּוֹפֵהוּ לְמַעֵט הַכֹּתֶל כְּדֵי שֶׁלֹּא יַעֲמֹד עַל רֹאשׁ הַכֹּתֶל וְיַשְׁקִיף מִן הַחַלּוֹן. אוֹ יַגְבִּיהַּ הַכֹּתֶל עַל הַחַלּוֹן אַרְבַּע אַמּוֹת וְיִהְיֶה הַכֹּתֶל רָחוֹק מִן הַחַלּוֹן אַרְבַּע אַמּוֹת כְּדֵי שֶׁלֹּא יַאֲפִיל וְלֹא יָצִיץ וְיִרְאֶה:","בָּנָה כֹּתֶל אֶחָד בְּצַד הַחַלּוֹן צָרִיךְ לְהַרְחִיק מִן הַחַלּוֹן טֶפַח וּמַגְבִּיהַּ הַכֹּתֶל אַרְבַּע אַמּוֹת עַל הַחַלּוֹן אוֹ כּוֹנֵס רֹאשׁ הַכֹּתֶל כְּדֵי שֶׁלֹּא יֵשֵׁב עָלָיו וְיָצִיץ וְיִרְאֶה:","בָּנָה שְׁנֵי כְּתָלִין מִשְּׁנֵי צִדֵּי הַחַלּוֹן. צָרִיךְ לִהְיוֹת בֵּינֵיהֶן רֹחַב אַרְבַּע אַמּוֹת וְהַחַלּוֹן בְּאֶמְצַע הָאַרְבַּע. וְלֹא יְסַכֵּךְ עַל גַּבֵּיהֶן אֶלָּא אִם כֵּן הִרְחִיק הַסִּכּוּךְ מִן הַכֹּתֶל שֶׁיֵּשׁ בּוֹ הַחַלּוֹן אַרְבַּע אַמּוֹת כְּדֵי שֶׁלֹּא יַאֲפִיל עָלָיו. לְפִיכָךְ מִי שֶׁבָּא לִפְתֹּחַ חַלּוֹן לַחֲצַר חֲבֵרוֹ בֵּין חַלּוֹן גְּדוֹלָה בֵּין חַלּוֹן קְטַנָּה בֵּין לְמַעְלָה בֵּין לְמַטָּה בַּעַל הֶחָצֵר מְעַכֵּב עָלָיו. שֶׁהֲרֵי אוֹמֵר לוֹ תַּזִּיק לִי בִּרְאִיָּה וְאַף עַל פִּי שֶׁהִיא גְּבוֹהָה תַּעֲלֶה בַּסֻּלָּם וְתִרְאֶה:","הֲרֵי שֶׁפָּתַח חַלּוֹן לַחֲצַר חֲבֵרוֹ וּמָחַל לוֹ בַּעַל הֶחָצֵר אוֹ שֶׁגִּלָּה דַּעְתּוֹ שֶׁהִנִּיחוֹ כְּגוֹן שֶׁבָּא וְסִיֵּעַ עִמּוֹ. אוֹ שֶׁיָּדַע הַנֵּזֶק וְלֹא עִרְעֵר. הֲרֵי זֶה הֶחֱזִיק בַּחַלּוֹן וְאֵינוֹ יָכוֹל אַחַר כָּךְ לַחְזֹר וּלְעַרְעֵר עָלָיו לִסְתֹּם. וְכֵיצַד דִּינָהּ שֶׁל חַלּוֹן זֶה שֶׁהִנִּיחָהּ לְפָתְחָהּ. אִם רֹאשׁוֹ שֶׁל אָדָם יָכוֹל לִכָּנֵס מִמֶּנָּה אוֹ שֶׁהָיְתָה לְמַטָּה מֵאַרְבַּע אַמּוֹת אַף עַל פִּי שֶׁאֵין רֹאשׁוֹ נִכְנָס מִמֶּנָּה אֵין בַּעַל הֶחָצֵר יָכוֹל לִבְנוֹת כְּנֶגְדָּהּ אוֹ מִצִּדֶּיהָ אֶלָּא אִם כֵּן הַרְחִיק אַרְבַּע אַמּוֹת כְּמוֹ שֶׁבֵּאַרְנוּ:","הָיְתָה חַלּוֹן קְטַנָּה שֶׁאֵין רֹאשׁוֹ שֶׁל אָדָם נִכְנָס מִמֶּנָּה וְהָיְתָה לְמַעְלָה מֵאַרְבַּע אַמּוֹת בַּעַל הֶחָצֵר יָכוֹל לִבְנוֹת כְּנֶגְדָּהּ וּבִצְדֶדֶיהָ שֶׁהֲרֵי טוֹעֵן וְאוֹמֵר לֹא הִנַּחְתִּיךָ לִפְתֹּחַ אֶלָּא מִפְּנֵי שֶׁהִיא קְטַנָּה וּגְבוֹהָה. אֲבָל שֶׁתַּחְזִיק עָלַי עַד שֶׁאַרְחִיק הַבִּנְיָן לֹא הִנַּחְתִּי. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁפְּתָחָהּ לְתַשְׁמִישׁ אוֹ כְּדֵי שֶׁיִּכָּנֵס בָּהּ הָרוּחַ. אֲבָל אִם פְּתָחָהּ לְאוֹרָה אֲפִלּוּ הָיְתָה קְטַנָּה בְּיוֹתֵר וּגְבוֹהָה בְּיוֹתֵר הוֹאִיל וְלֹא עִרְעֵר הֶחֱזִיק וְאֵין בַּעַל הֶחָצֵר יָכוֹל לִבְנוֹת כְּנֶגְדָּהּ אוֹ מִצְּדָדֶיהָ עַד שֶׁיַּרְחִיק אַרְבַּע אַמּוֹת כְּדֵי שֶׁלֹּא יַאֲפִיל עָלָיו שֶׁהֲרֵי מָחַל לוֹ עַל הָאוֹרָה. וְכֵן מִי שֶׁהָיְתָה לוֹ חַלּוֹן מֻחְזֶקֶת וּבָא חֲבֵרוֹ וּבָנָה כְּנֶגְדָּהּ אוֹ מִצְּדָדֶיהָ בְּלֹא הַרְחָקָה אוֹ סְתָמָהּ וְשָׁתַק בַּעַל הַחַלּוֹן אֵינוֹ יָכוֹל לַחְזֹר וּלְעַרְעֵר לִפְתֹּחַ הַחַלּוֹן אוֹ לְהַרְחִיק הַבִּנְיָן. שֶׁכֵּיוָן שֶׁשָּׁתַק מָחַל שֶׁאֵין אָדָם עָשׂוּי שֶׁסּוֹתְמִין אוֹרוֹ בְּפָנָיו וְשׁוֹתֵק אֶלָּא אִם כֵּן מָחַל:","מִי שֶׁהָיוּ לוֹ חַלּוֹנוֹת לְמַטָּה בְּכָתְלוֹ וּבָא חֲבֵרוֹ לִבְנוֹת בִּפְנֵיהֶן וְאָמַר לוֹ אֲנִי אֶפְתַּח לְךָ חַלּוֹנוֹת אֲחֵרוֹת בְּכֹתֶל זֶה עַצְמוֹ לְמַעְלָה מֵאֵלּוּ הֲרֵי זֶה מְעַכֵּב עָלָיו וְאוֹמֵר לוֹ בְּעֵת שֶׁתִּפְתַּח הַחַלּוֹנוֹת תַּרְעִיד אֶת הַכֹּתֶל וּתְקַלְקֵל אוֹתוֹ. וַאֲפִלּוּ אָמַר אֲנִי אֶסְתֹּר כָּל הַכֹּתֶל וְאֶבְנֶה אוֹתוֹ לְךָ חָדָשׁ וְאֶעֱשֶׂה בּוֹ חַלּוֹנוֹת לְמַעְלָה וְאֶשְׂכֹּר לְךָ בַּיִת שֶׁתָּדוּר בּוֹ עַד שֶׁאֶבְנֶה יָכוֹל לְעַכֵּב עָלָיו וְאוֹמֵר לוֹ אֵין רְצוֹנִי שֶׁאֶטְרַח מִמָּקוֹם לְמָקוֹם. לְפִיכָךְ אִם לֹא הָיָה שָׁם טֹרַח כְּלָל וְאֵין צָרִיךְ לְפָנוֹת אֵינוֹ יָכוֹל לְעַכֵּב עָלָיו. וְכוֹפִין אוֹתוֹ שֶׁיִּהְיֶה חֲבֵרוֹ סוֹתֵם חַלּוֹן זֶה שֶׁלְּמַטָּה מִמֶּנּוּ וְעוֹשֶׂה לוֹ חַלּוֹן מִלְּמַעְלָה שֶׁזּוֹ מִדַּת סְדוֹם. וְכֵן כָּל דָּבָר שֶׁזֶּה נֶהֱנֶה בּוֹ וְאֵין חֲבֵרוֹ מַפְסִיד וְאֵין חָסֵר כְּלוּם כּוֹפִין עָלָיו:","אֲבָל בַּעַל הַחַלּוֹנוֹת שֶׁרָצָה לְשַׁנּוֹת מְקוֹם חַלּוֹנוֹ בֵּין לְמַעְלָה בֵּין לְמַטָּה אֲפִלּוּ הָיְתָה גְּדוֹלָה וְאָמַר אֶפְתַּח אַחֶרֶת קְטַנָּה וְאֶסְתֹּם זוֹ בַּעַל הֶחָצֵר מְעַכֵּב עָלָיו. וְכֵן אֵינוֹ יָכוֹל לְהַרְחִיב בַּחַלּוֹן כָּל שֶׁהוּא:","שְׁנֵי אַחִין שֶׁחָלְקוּ חָצֵר מִדַּעְתָּן וְשָׁמוּ הַבִּנְיָן וְהָעֵצִים זֶה כְּנֶגֶד זֶה וְלֹא הִשְׁגִּיחוּ עַל שׁוּמַת הָאֲוִיר. וְהִגִּיעַ לְאֶחָד מֵהֶן בְּחֶלְקוֹ תַּרְבַּץ הֶחָצֵר וְלַשֵּׁנִי הָאַכְסַדְרָה. אִם רָצָה בַּעַל הֶחָצֵר לִבְנוֹת כֹּתֶל בְּסוֹף חֶלְקוֹ בּוֹנֶה בִּפְנֵי הָאַכְסַדְרָה וְאַף עַל פִּי שֶׁמַּאֲפִיל עָלָיו שֶׁהֲרֵי לֹא שָׁמוּ הָאֲוִיר:"],"Mishneh Torah, Oaths 7":["הַתּוֹבֵעַ חֲבֵרוֹ בְּמָמוֹן שֶׁאִם הוֹדָה בּוֹ יִהְיֶה חַיָּב לְשַׁלֵּם וְכָפַר וְנִשְׁבַּע. אוֹ שֶׁהִשְׁבִּיעוֹ הַתּוֹבֵעַ וְכָפַר. הֲרֵי זֶה הַנִּתְבָּע הוּא חַיָּב בִּשְׁבוּעַת הַפִּקָּדוֹן אַף עַל פִּי שֶׁלֹּא עָנָה אָמֵן. שֶּׁבִּשְׁבוּעַת הַפִּקָּדוֹן אֶחָד הַנִּשְׁבָּע מִפִּי עַצְמוֹ וְאֶחָד שֶׁהִשְׁבִּיעוֹ אַחֵר וְכָפַר אַף עַל פִּי שֶׁלֹּא עָנָה אָמֵן חַיָּב. שֶׁכְּפִירָתוֹ אַחַר שֶׁהִשְׁבִּיעוֹ הַתּוֹבֵעַ כַּעֲנִיַּת אָמֵן:","תְּבָעוֹ בְּמָמוֹן שֶׁאִם יוֹדֶה לוֹ וְיֹאמַר כֵּן הַדָּבָר לֹא יִהְיֶה חַיָּב לְשַׁלֵּם. כְּגוֹן שֶׁתְּבָעוֹ בִּקְנָס שֶׁאֵין אָדָם מְשַׁלֵּם קְנָס עַל פִּי עַצְמוֹ. וְכָפַר וְנִשְׁבַּע. הֲרֵי זֶה פָּטוּר מִשְּׁבוּעַת הַפִּקָּדוֹן וְחַיָּב מִשּׁוּם שְׁבוּעַת בִּטּוּי:","וְכֵן אִם תְּבָעוֹ בְּקַרְקַע אוֹ בְּעֶבֶד אוֹ בִּשְׁטָר וְכָפַר וְנִשְׁבַּע פָּטוּר מִשְּׁבוּעַת הַפִּקָּדוֹן וְחַיָּב בִּשְׁבוּעַת בִּטּוּי שֶׁהֲרֵי נִשְׁבַּע עַל שֶׁקֶר:","וְלָמָּה נִפְטָר מִשּׁוּם שְׁבוּעַת הַפִּקָּדוֹן וַהֲרֵי זֶה אִלּוּ הוֹדָה חַיָּב הָיָה וּמְשַׁלֵּם מַה שֶּׁכָּפַר. לְפִי שֶׁנֶּאֱמַר (ויקרא ה כא) \"בְּפִקָּדוֹן אוֹ בִתְשׂוּמֶת יָד אוֹ בְּגֵזֶל אוֹ עָשַׁק אֶת עֲמִיתוֹ\" (ויקרא ה כב) \"אוֹ מָצָא אֲבֵדָה\" הַכּל מִטַּלְטְלִין שֶׁאִם יוֹדֶה בָּהֶן יוֹצִיא מָמוֹן מִתַּחַת יָדוֹ. וְיָצְאוּ קַרְקָעוֹת שֶׁאֵין מִטַּלְטְלִין וַהֲרֵי הֵן לִפְנֵי בַּעֲלֵיהֶן וּבְחֶזְקָתָן. וְיָצְאוּ עֲבָדִים שֶׁהֻקְּשׁוּ לְקַרְקָעוֹת. וְיָצְאוּ שְׁטָרוֹת שֶׁאֵין גּוּפָן מָמוֹן:","אֶחָד הַנִּשְׁבָּע אַחַר שֶׁתְּבָעוֹ בַּעַל הַמָּמוֹן. אוֹ הַנִּשְׁבָּע מֵעַצְמוֹ אַף עַל פִּי שֶׁלֹּא תְּבָעוֹ. כֵּיצַד. כְּגוֹן שֶׁקָּדַם וְאָמַר לָמָּה אַתָּה הוֹלֵךְ אַחֲרַי כְּלוּם יֵשׁ לְךָ בְּיָדִי מָמוֹן שְׁבוּעָה שֶׁאֵין לְךָ בְּיָדִי מָמוֹן. הֲרֵי זֶה חַיָּב בִּשְׁבוּעַת הַפִּקָּדוֹן הוֹאִיל וְכָפַר וְנִשְׁבַּע וְאַף עַל פִּי שֶׁלֹּא תְּבָעוֹ זֶה:","אֶחָד הַנִּשְׁבָּע לְבַעַל הַמָּמוֹן עַצְמוֹ אוֹ לִשְׁלוּחוֹ הַבָּא בְּהַרְשָׁאָתוֹ. שֶׁשְּׁלוּחוֹ שֶׁל אָדָם כְּמוֹתוֹ:","וְאֵינוֹ חַיָּב בִּשְׁבוּעַת הַפִּקָּדוֹן עַד שֶׁיַּשְׁבִּיעוֹ בְּלָשׁוֹן שֶׁהוּא מַכִּירָהּ:","הַנִּשְׁבָּע שְׁבוּעַת הַפִּקָּדוֹן בְּמֵזִיד אַף עַל פִּי שֶׁנִּשְׁבַּע לַשֶּׁקֶר וְהִתְרוּ בּוֹ עֵדִים בִּשְׁעַת שְׁבוּעָתוֹ אֵינוֹ לוֹקֶה אֶלָּא מֵבִיא אֲשָׁמוֹ בִּלְבַד. שֶׁהֲרֵי הַכָּתוּב מוֹצִיאוֹ מִכְּלַל חַיָּבֵי מַלְקוֹת וְחִיְּבוֹ אָשָׁם בֵּין בְּזָדוֹן בֵּין בִּשְׁגָגָה כְּמוֹ שֶׁבֵּאַרְנוּ:","כָּפַר וְנִשְׁבַּע אַרְבַּע אוֹ חָמֵשׁ פְּעָמִים. אוֹ שֶׁהִשְׁבִּיעוֹ הַתּוֹבֵעַ אַרְבַּע וְחָמֵשׁ פְּעָמִים וְהוּא כּוֹפֵר עַל כָּל אַחַת וְאַחַת בֵּין בְּבֵית דִּין בֵּין שֶׁלֹּא בְּבֵית דִּין הֲרֵי זֶה חַיָּב קָרְבַּן אָשָׁם עַל כָּל שְׁבוּעָה וּשְׁבוּעָה. שֶׁאִלּוּ הוֹדָה אַחַר שֶׁכָּפַר הָיָה חַיָּב לְשַׁלֵּם אַף עַל פִּי שֶׁכָּפַר בְּבֵית דִּין וְנִמְצָא פּוֹטֵר עַצְמוֹ בְּכָל כְּפִירָה וּכְפִירָה מִן הַתַּשְׁלוּמִין. לְפִיכָךְ חַיָּב עַל כָּל שְׁבוּעָה וּשְׁבוּעָה:","הָיוּ חֲמִשָּׁה תּוֹבְעִין אוֹתוֹ וְאוֹמְרִין לוֹ תֵּן לָנוּ פִּקָּדוֹן שֶׁיֵּשׁ לָנוּ בְּיָדְךָ. שְׁבוּעָה שֶׁאֵין לָכֶם בְּיָדִי אֵינוֹ חַיָּב אֶלָּא קָרְבָּן אֶחָד. שְׁבוּעָה שֶׁאֵין לְךָ בְּיָדִי לֹא לְךָ וְלֹא לְךָ וְלֹא לְךָ חַיָּב עַל כָּל אַחַת וְאַחַת:","אָמַר לוֹ חֲבֵרוֹ תֵּן לִי פִּקָּדוֹן וּתְשׂוּמֶת יָד גֵּזֶל וַאֲבֵדָה שֶׁיֵּשׁ לִי בְּיָדְךָ. שְׁבוּעָה שֶׁאֵין לְךָ בְּיָדִי אֵינוֹ חַיָּב אֶלָּא אַחַת. וַאֲפִלּוּ הָיָה לוֹ פְּרוּטָה אַחַת מִכֻּלָּן הֲרֵי אֵלּוּ מִצְטָרְפִין וְחַיָּב:","שְׁבוּעָה שֶׁאֵין לְךָ בְּיָדִי פִּקָּדוֹן תְּשׂוּמֶת יָד גֵּזֶל וַאֲבֵדָה חַיָּב עַל כָּל אַחַת וְאַחַת:","תֵּן לִי חִטִּים וּשְׂעוֹרִים וְכֻסְּמִין שֶׁיֵּשׁ לִי בְּיָדְךָ. שְׁבוּעָה שֶׁאֵין לְךָ בְּיָדִי אֵינוֹ חַיָּב אֶלָּא אַחַת. שְׁבוּעָה שֶׁאֵין לְךָ בְּיָדִי חִטִּים וּשְׂעוֹרִין וְכֻסְּמִין חַיָּב עַל כָּל אַחַת וְאַחַת:","הָיוּ חֲמִשָּׁה תּוֹבְעִין אוֹתוֹ וְאוֹמְרִין לוֹ תֵּן לָנוּ פִּקָּדוֹן גֵּזֶל וַאֲבֵדָה וּתְשׂוּמֶת יָד שֶׁיֵּשׁ לָנוּ בְּיָדְךָ. וְאָמַר לָאֶחָד מֵהֶן שְׁבוּעָה שֶׁאֵין לְךָ בְּיָדִי פִּקָּדוֹן וְגֵזֶל וַאֲבֵדָה וּתְשׂוּמֶת יָד וְלֹא לְךָ וְלֹא לְךָ וְלֹא לְךָ הֲרֵי זֶה חַיָּב עַל כָּל טַעֲנָה וְטַעֲנָה לְכָל אֶחָד וְאֶחָד וְנִמְצָא זֶה חַיָּב עֶשְׂרִים אָשָׁם:","טָעַן שֶׁאָבַד הַפִּקָּדוֹן אוֹ כָּפַר בּוֹ וְנִשְׁבַּע וְאַחַר כָּךְ הוֹדָה. וְחָזַר וְטָעַן שֶׁאָבַד וְנִשְׁבַּע וְחָזַר וְהוֹדָה. מְשַׁלֵּם הַקֶּרֶן הָרִאשׁוֹן וְחֹמֶשׁ אֶחָד עַל כָּל שְׁבוּעָה וּשְׁבוּעָה שֶׁנֶּאֱמַר (ויקרא ה כד) \"וַחֲמִשִׁתָיו\". הַתּוֹרָה רִבְּתָה חֳמָשִׁין הַרְבֵּה עַל קֶרֶן אֶחָד. כֵּיצַד. הָיָה הַקֶּרֶן אַרְבָּעָה וְכָפַר וְנִשְׁבַּע וְהוֹדָה וְחָזַר וְטָעַן שֶׁאָבַד וְנִשְׁבַּע וְחָזַר וְהוֹדָה וְחָזַר וְטָעַן שֶׁאָבַד וְנִשְׁבַּע וְהוֹדָה מְשַׁלֵּם שִׁבְעָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","פָּחוֹת מִפְּרוּטָה אֵינוֹ מָמוֹן לְפִיכָךְ הַתּוֹבֵעַ חֲבֵרוֹ בְּפָחוֹת מִפְּרוּטָה אוֹ בְּפָחוֹת מִשְּׁוֵה פְּרוּטָה וְכָפַר וְנִשְׁבַּע פָּטוּר מִשְּׁבוּעַת הַפִּקָּדוֹן וְחַיָּב בִּשְׁבוּעַת בִּטּוּי:"],"Mishneh Torah, Offerings for Unintentional Transgressions 13":["כֵּיצַד אִם חָסֵר אַחַת מִכָּל הַדְּרָכִים שֶׁבֵּאַרְנוּ יִפָּטְרוּ בֵּית דִּין וְיִתְחַיְּבוּ הָעוֹשִׂים. הֲרֵי שֶׁהוֹרוּ בֵּית דִּין שֶׁל אֶחָד מִן הַשְּׁבָטִים לָהֶם שֶׁחֵלֶב הַקֵּיבָה מֻתָּר וַאֲכָלוּהוּ אַנְשֵׁי מְקוֹמָם עַל פִּיהֶם אוֹתוֹ בֵּית דִּין פְּטוּרִין וְכָל מִי שֶׁאָכַל מֵבִיא חַטָּאת קְבוּעָה עַל שִׁגְגַתוֹ. וְכֵן אִם הוֹרוּ בֵּית דִּין הַגָּדוֹל שֶׁדַּם הַלֵּב מֻתָּר וְלֹא הָיָה רֹאשׁ יְשִׁיבָה עִמָּהֶן אוֹ שֶׁהָיָה אֶחָד מֵהֶן אֵינוֹ רָאוּי לִהְיוֹת מְמֻנֶּה בְּסַנְהֶדְרִין כְּגוֹן שֶׁהָיָה גֵּר אוֹ מַמְזֵר אוֹ זָקֵן אוֹ שֶׁלֹּא רָאָה בָּנִים וְכַיּוֹצֵא בָּהֶן וְעָשׂוּ הָעָם עַל פִּיהֶם וְאָכְלוּ דַּם הַלֵּב הֲרֵי בֵּית דִּין פְּטוּרִין וְכָל מִי שֶׁאָכַל מֵבִיא חַטָּאת קְבוּעָה עַל שִׁגְגָתוֹ. וּמִנַּיִן שֶׁאֵין הַכָּתוּב מְדַבֵּר אֶלָּא בְּבֵית דִּין הַגָּדוֹל שֶׁנֶּאֱמַר (ויקרא ד יג) \"וְאִם כָּל עֲדַת יִשְׂרָאֵל יִשְׁגּוּ\" וְגוֹ'. וּמִנַּיִן שֶׁעַד שֶׁיִּהְיוּ כֻּלָּן רְאוּיִין לְהוֹרָאָה שֶׁנֶּאֱמַר (במדבר טו כד) \"וְאִם מֵעֵינֵי הָעֵדָה\" עַד שֶׁיִּהְיוּ לָהֶם כְּעֵינַיִם. וּלְהַלָּן הוּא אוֹמֵר (במדבר לה כד) \"וְשָׁפְטוּ הָעֵדָה\" מָה הָעֵדָה הָאֲמוּרָה בְּדִינֵי נְפָשׁוֹת כֻּלָּן רְאוּיִין לְהוֹרָאָה אַף עֵדָה הָאֲמוּרָה בִּשְׁגָגָה זוֹ עַד שֶׁיִּהְיוּ כֻּלָּן רְאוּיִין לְהוֹרָאָה. וְכֵן אִם הוֹרוּ וְיָדַע אֶחָד מֵהֶן שֶׁטָּעוּ וְאָמַר לָהֶם טוֹעִים אַתֶּם וְרַבּוּ עָלָיו הַמַּתִּירִים וְהִתִּירוּ. הֲרֵי בֵּית דִּין פְּטוּרִין וְכָל מִי שֶׁעָשָׂה עַל פִּיהֶם חַיָּב לְהָבִיא חַטָּאת קְבוּעָה עַל שִׁגְגָתוֹ. שֶׁנֶּאֱמַר וְאִם כָּל עֲדַת יִשְׂרָאֵל יִשְׁגּוּ עַד שֶׁיִּשְׁגּוּ כָּל הַסַּנְהֶדְרִין. יָדַע אֶחָד מִן הַסַּנְהֶדְרִין אוֹ מִעוּטָן שֶׁטָּעוּ הַמַּתִּירִין וְשָׁתְקוּ הוֹאִיל וְהוֹרוּ וְלֹא הָיָה שָׁם חוֹלֵק וּפָשְׁטָה הַהוֹרָאָה בְּרֹב הַקָּהָל הֲרֵי בֵּית דִּין חַיָּבִין בְּקָרְבָּן וְכָל שֶׁעָשָׂה עַל פִּיהֶם פָּטוּר. וְאֵלּוּ שֶׁשָּׁתְקוּ אִם עָשׂוּ עַל פִּי אֵלּוּ שֶׁהוֹרוּ הֲרֵי אֵלּוּ חַיָּבִין מִפְּנֵי שֶׁלֹּא תָּלוּ בְּבֵית דִּין. וְכֵן אִם נָשְׂאוּ וְנָתְנוּ בַּדָּבָר וְאָמְרוּ דָּבָר זֶה מֻתָּר הוּא וְלֹא הוֹרוּ לָעָם וְלֹא אָמְרוּ לָהֶם מֻתָּרִין אַתֶּם לַעֲשׂוֹת וְשָׁמַע הַשּׁוֹמֵעַ מֵהֶן בְּעֵת שֶׁגָּמְרוּ מֻתָּר וְהָלַךְ וְעָשָׂה כְּפִי מַה שֶּׁשָּׁמַע הֲרֵי כָּל הָעוֹשֶׂה חַיָּב חַטָּאת קְבוּעָה וּבֵית דִּין פְּטוּרִין שֶׁהֲרֵי לֹא הוֹרוּ לָהֶם בְּפֵרוּשׁ לַעֲשׂוֹת. וְכֵן אִם הוֹרוּ וְעָשׂוּ מִעוּט הַקָּהָל עַל פִּיהֶם וְנוֹדְעָה הַשְּׁגָגָה. הֲרֵי בֵּית דִּין פְּטוּרִין וְאֵלּוּ הַמִּעוּט שֶׁעָשׂוּ חַיָּבִין וְכָל אֶחָד וְאֶחָד מֵבִיא חַטָּאתוֹ:","וְהַסַּנְהֶדְרִין עַצְמָן שֶׁעָשׂוּ בְּהוֹרָאָתָן אֵינָן מִצְטָרְפִין לְרֹב הַקָּהָל. עַד שֶׁיִּהְיוּ הָרֹב שֶׁעָשׂוּ חוּץ מִן הַסַּנְהֶדְרִין. עָשׂוּ רֹב אַנְשֵׁי אֶרֶץ יִשְׂרָאֵל עַל פִּיהֶם. אַף עַל פִּי שֶׁאֵלּוּ הָעוֹשִׂים שֵׁבֶט אֶחָד. וְכֵן אִם עָשׂוּ רֹב הַשְּׁבָטִים אַף עַל פִּי שֶׁהֵן מִעוּט הַקָּהָל. בֵּית דִּין חַיָּבִים וְהָעוֹשִׂין פְּטוּרִין. כֵּיצַד. הָיוּ יוֹשְׁבֵי אֶרֶץ יִשְׂרָאֵל שֵׁשׁ מֵאוֹת אֶלֶף וְאֶחָד. וְהָיוּ הָעוֹשִׂין בְּהוֹרָאַת בֵּית דִּין שְׁלֹשׁ מֵאוֹת אֶלֶף וְאֶחָד וַהֲרֵי כֻּלָּן בְּנֵי יְהוּדָה בִּלְבַד. אוֹ שֶׁהָיוּ הָעוֹשִׂים בְּנֵי שִׁבְעָה שְׁבָטִים כֻּלָּן אַף עַל פִּי שֶׁיֵּשׁ בָּהֶן מֵאָה אֶלֶף. הֲרֵי בֵּית דִּין חַיָּבִין וְכָל הָעוֹשִׂים עַל פִּיהֶם פְּטוּרִין. וְאֵין מַשְׁגִּיחִין עַל יוֹשְׁבֵי חוּצָה לָאָרֶץ שֶׁאֵין קָרוּי קָהָל אֶלָּא בְּנֵי אֶרֶץ יִשְׂרָאֵל. וְשֵׁבֶט מְנַשֶּׁה וְאֶפְרַיִם אֵינָן חֲשׁוּבִין כִּשְׁנֵי שְׁבָטִים לָעִנְיָן הַזֶּה אֶלָּא שְׁנֵיהֶם שֵׁבֶט אֶחָד:","הָיוּ הָעוֹשִׂים מְרֻבִּין בִּשְׁעַת הַחֵטְא וּמוּעָטִין בִּשְׁעַת יְדִיעָה. אוֹ מוּעָטִין בִּשְׁעַת הַחֵטְא וּמְרֻבִּין בִּשְׁעַת יְדִיעָה. הַכּל הוֹלֵךְ אַחַר שְׁעַת הַמַּעֲשֶׂה:","הוֹרוּ בֵּית דִּין בְּחֵלֶב מִן הַחֲלָבִים שֶׁהוּא מֻתָּר וְאָכַל מִעוּט הַקָּהָל עַל פִּיהֶם וְנוֹדַע לָהֶם שֶׁחָטְאוּ וְחָזְרוּ בָּהֶן. וְאַחַר כָּךְ הוֹרוּ שֶׁעֲבוֹדָה זָרָה פְּלוֹנִית מֻתֶּרֶת וְעָבַד אוֹתָהּ עֲבוֹדָה זָרָה מִעוּט אַחֵר עַל פִּיהֶם. וּכְשֶׁיִּצְטָרְפוּ הָאוֹכְלִים לָעוֹבְדִים יִהְיוּ רֹב. הֲרֵי אֵלּוּ מִצְטָרְפִין אַף עַל פִּי שֶׁהָיְתָה לָהֶן יְדִיעָה בֵּינְתַיִם. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה הַמּוֹרֶה בֵּית דִּין אֶחָד. אֲבָל אִם מֵת בֵּית דִּין שֶׁהוֹרָה תְּחִלָּה וְעָמַד אַחֵר וְהוֹרוּ אֵין אֵלּוּ מִצְטָרְפִין לְאֵלּוּ:","אֲפִלּוּ הוֹרוּ שְׁנֵי בָּתֵּי הַדִּינִים בְּדָבָר אֶחָד כְּגוֹן חֵלֶב וְחֵלֶב. אוֹ דָּם וְדָם. וְכֵן אִם לֹא הָיוּ הָעוֹשִׂים שׁוֹגְגִין עַל פִּי הַהוֹרָאָה. הֲרֵי בֵּית דִּין פְּטוּרִין וְכָל הָעוֹשִׂים חַיָּבִין. כֵּיצַד. הוֹרוּ בֵּית דִּין לֶאֱכל חֵלֶב הַקֵּבָה כֻּלּוֹ. וְיָדַע אֶחָד מִן הַקָּהָל שֶׁטָּעוּ וְשֶׁחֵלֶב הַקֵּבָה אָסוּר וְאָכְלוּ מִפְּנֵי הוֹרָאָתָן. שֶׁהָיָה עוֹלֶה עַל דַּעְתָּן שֶׁמִּצְוָה לִשְׁמֹעַ מִבֵּית דִּין אַף עַל פִּי שֶׁהֵם טוֹעִים. הֲרֵי זֶה הָאוֹכֵל חַיָּב חַטָּאת קְבוּעָה עַל אֲכִילָתוֹ. וְאֵינוֹ מִצְטָרֵף לְמִנְיַן הַשּׁוֹגְגִים עַל פִּיהֶם. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה זֶה שֶׁיָּדַע שֶׁטָּעוּ חָכָם אוֹ תַּלְמִיד שֶׁהִגִּיעַ לְהוֹרָאָה. אֲבָל אִם הָיָה עַם הָאָרֶץ הֲרֵי זֶה פָּטוּר שֶׁאֵין יְדִיעָתוֹ בְּאִסּוּרִין יְדִיעָה וַדָּאִית וּמִצְטָרֵף לִכְלַל הַשּׁוֹגְגִים עַל פִּיהֶם. וְכֵן אִם לֹא יָדַע שֶׁטָּעוּ וְנִתְכַּוִּן לֶאֱכל שֻׁמָּן וְחֵלֶב וְאָכַל חֵלֶב הַקֵּבָה שֶׁהִתִּירוּהוּ וְהוּא לֹא יָדַע שֶׁהוּא חֵלֶב קֵבָה. הֲרֵי זֶה חַיָּב מִפְּנֵי שֶׁאֲכִילָתוֹ מִפְּנֵי שִׁגְגָתוֹ לֹא מִפְּנֵי הַהוֹרָאָה. וְאֵינוֹ מִצְטָרֵף לְמִנְיַן הַשּׁוֹגְגִים עַל פִּיהֶם שֶׁנֶּאֱמַר (במדבר טו כו) \"לְכָל הָעָם בִּשְׁגָגָה\". עַד שֶׁתִּהְיֶה שְׁגָגָה אַחַת לַכּל. וְכֵן אִם תָּלָה בְּעַצְמוֹ וְאָכַל חֵלֶב הַקֵּבָה שֶׁהוֹרוּ לְהַתִּירוֹ לֹא מִפְּנֵי הוֹרָאָתָן אֶלָּא מִפְּנֵי שֶׁהוּא מֻתָּר בְּדַעְתּוֹ הֲרֵי זֶה חַיָּב חַטָּאת קְבוּעָה בִּפְנֵי עַצְמוֹ. זֶה הַכְּלָל כָּל הַתּוֹלֶה בְּבֵית דִּין פָּטוּר וְהוּא שֶׁיִּהְיוּ שָׁם כָּל הַדְּרָכִים שֶׁמָּנִינוּ. וְכָל הַחַיָּב בִּפְנֵי עַצְמוֹ אֵינוֹ מִצְטָרֵף לְרֹב הַשּׁוֹגְגִים:","הוֹרוּ בֵּית דִּין לְהַתִּיר דָּבָר הָאָסוּר בְּזָדוֹן וְעָשׂוּ הַקָּהָל עַל פִּיהֶם בִּשְׁגָגָה בֵּית דִּין פְּטוּרִין מִן הַקָּרְבָּן מִפְּנֵי שֶׁהֵן מְזִידִין. וְכָל אֶחָד וְאֶחָד מִן הָעוֹשִׂים עַל פִּיהֶם חַיָּב קָרְבָּן בִּפְנֵי עַצְמוֹ מִפְּנֵי שֶׁהוּא שׁוֹגֵג. הוֹרוּ בֵּית דִּין בִּשְׁגָגָה וְיָדְעוּ הַקָּהָל שֶׁטָּעוּ וְשֶׁאֵין רָאוּי לְקַבֵּל מֵהֶן וְאַף עַל פִּי כֵּן עָשׂוּ הַקָּהָל עַל פִּיהֶם. אֵלּוּ וְאֵלּוּ פְּטוּרִין מִן הַקָּרְבָּן. בֵּית דִּין פְּטוּרִין שֶׁהֲרֵי לֹא עָשׂוּ הַקָּהָל מִפְּנֵי הוֹרָאָתָן שֶׁהִטְעָתָם. וְכָל הָעוֹשִׂים פְּטוּרִין מִן הַקָּרְבָּן מִפְּנֵי שֶׁמְּזִידִין הֵם שֶׁהֲרֵי יָדְעוּ שֶׁטָּעוּ וְשֶׁאֵין רָאוּי לַעֲשׂוֹת:"],"Mishneh Torah, One Who Injures a Person or Property 2":["הַחוֹבֵל בַּחֲבֵרוֹ חַבָּלָה שֶׁהוּא רָאוּי לְשַׁלֵּם הַחֲמִשָּׁה דְּבָרִים כֻּלָּם מְשַׁלֵּם חֲמִשָּׁה. הִזִּיקוֹ נֵזֶק שֶׁאֵין בּוֹ אֶלָּא אַרְבָּעָה מְשַׁלֵּם אַרְבָּעָה. שְׁלֹשָׁה מְשַׁלֵּם שְׁלֹשָׁה. שְׁנַיִם מְשַׁלֵּם שְׁנַיִם. אֶחָד מְשַׁלֵּם אֶחָד:","כֵּיצַד. קָטַע יָדוֹ אוֹ רַגְלוֹ אוֹ אֶצְבַּע מֵהֶן אוֹ שֶׁסִּמֵּא עֵינוֹ מְשַׁלֵּם חֲמִשָּׁה נֵזֶק וְצַעַר וְרִפּוּי וְשֶׁבֶת וּבשֶׁת. הִכָּהוּ עַל יָדוֹ וְצָבְתָה וְסוֹפָהּ לַחְזֹר. עַל עֵינוֹ וּמָרְדָה וְסוֹפָהּ לִחְיוֹת. מְשַׁלֵּם אַרְבָּעָה צַעַר וְרִפּוּי וְשֶׁבֶת וּבשֶׁת. הִכָּהוּ עַל רֹאשׁוֹ וְצָבָה מְשַׁלֵּם שְׁלֹשָׁה צַעַר וְרִפּוּי וּבשֶׁת. הִכָּהוּ בְּמָקוֹם שֶׁאֵינוֹ נִרְאֶה כְּגוֹן שֶׁהִכָּה עַל בִּרְכָּיו אוֹ בְּגַבּוֹ מְשַׁלֵּם שְׁנַיִם צַעַר וְרִפּוּי. הִכָּהוּ בְּמִטְפַּחַת שֶׁבְּיָדוֹ אוֹ בִּשְׁטָר וְכַיּוֹצֵא בְּאֵלּוּ נוֹתֵן אַחַת וְהִיא הַבּשֶׁת בִּלְבַד:","כְּוָאָהוּ בְּשִׁפּוּד אוֹ בְּמַסְמֵר עַל צִפָּרְנָיו בְּמָקוֹם שֶׁאֵינוֹ עוֹשֶׂה חַבּוּרָה וְלֹא מְעַכֵּב מְלָאכָה מְשַׁלֵּם הַצַּעַר בִּלְבַד. הִשְׁקָהוּ סַם אוֹ סָכוֹ סַם וְשִׁנָּה מַרְאֵה עוֹרוֹ מְשַׁלֵּם לוֹ רִפּוּי בִּלְבַד עַד שֶׁיַּחֲזֹר מַרְאֵהוּ כְּשֶׁהָיָה. אֲסָרוֹ בְּחֶדֶר נוֹתֵן לוֹ דְּמֵי שֶׁבֶת בִּלְבַד. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ:","הַמְגַלֵּחַ שְׂעַר רֹאשׁ חֲבֵרוֹ נוֹתֵן לוֹ דְּמֵי בָּשְׁתּוֹ בִּלְבַד מִפְּנֵי שֶׁסּוֹפוֹ לַחְזֹר. גִּלְּחוֹ בְּסַם אוֹ שֶׁכְּוָאָהוּ עַד שֶׁאֵין סוֹף הַשֵּׂעָר לַחְזֹר חַיָּב בַּחֲמִשָּׁה דְּבָרִים. בְּנֵזֶק בְּצַעַר וְרִפּוּי שֶׁהֲרֵי יִתְחַמֵּם רֹאשׁוֹ מִן הַכְּוִיָּה אוֹ מִן הַסַּם וְנִמְצָא חָשׁ בְּרֹאשׁוֹ. וּמְשַׁלֵּם לוֹ שֶׁבֶת שֶׁהֲרֵי הוּא רָאוּי לִרְקֹד וּלְנַדְנֵד דֶּלֶת רֹאשׁוֹ בִּשְׁעַת רִקּוּד וְנִמְצָא בָּטֵל מִמְּלָאכָה זוֹ. וּבשֶׁת שֶׁאֵין לְךָ בּשֶׁת גָּדוֹל מִזֶּה:","הָא לָמַדְתָּ שֶׁכָּל הַמְחַסֵּר חֲבֵרוֹ אֵיבָר שֶׁאֵינוֹ חוֹזֵר חַיָּב בְּכָל הַחֲמִשָּׁה דְּבָרִים. אֲפִלּוּ הִפִּיל שִׁנּוֹ חַיָּב בַּכּל שֶׁאִי אֶפְשָׁר שֶׁלֹּא יֶחֱלֶה פִּיו שָׁעָה אַחַת. אַף עַל פִּי שֶׁהַשֵּׁן אֵין לוֹ רְפוּאָה בְּשַׂר הַשִּׁנַּיִם צָרִיךְ רְפוּאָה:","אֲפִלּוּ חִסְּרוֹ כְּשַׂעֲרָה מֵעוֹר בְּשָׂרוֹ חַיָּב בַּחֲמִשָּׁה דְּבָרִים. שֶׁהָעוֹר אֵינוֹ חוֹזֵר אֶלָּא צַלֶּקֶת. לְפִיכָךְ הַחוֹבֵל בַּחֲבֵרוֹ וְקָרַע הָעוֹר וְהוֹצִיא מִמֶּנּוּ דָּם חַיָּב בַּחֲמִשָּׁה דְּבָרִים:","הַמַּבְעִית חֲבֵרוֹ אַף עַל פִּי שֶׁחָלָה מִן הַפַּחַד הֲרֵי זֶה פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. וְהוּא שֶׁלֹּא נָגַע בּוֹ אֶלָּא כְּגוֹן שֶׁצָּעַק מֵאֲחוֹרָיו אוֹ שֶׁנִּתְרָאָה [לוֹ] בָּאֲפֵלָה וְכַיּוֹצֵא בָּזֶה. וְכֵן אִם צָעַק בְּאָזְנוֹ וְחֵרְשׁוֹ פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. אֲחָזוֹ וְתָקַע בְּאָזְנוֹ וְחֵרְשׁוֹ אוֹ שֶׁנָּגַע בּוֹ וּדְחָפוֹ בְּעֵת שֶׁהִבְעִיתוֹ אוֹ שֶׁאָחַז בִּבְגָדָיו וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ חַיָּב בְּתַשְׁלוּמִין:","יֵרָאֶה לִי שֶׁהַנֶּחְבָּל שֶׁאָמַר נִתְחָרַשְׁתִּי אוֹ נִסְמֵית עֵינִי וַהֲרֵי אֵינִי רוֹאֶה אוֹ אֵינִי שׁוֹמֵעַ אֵינוֹ נֶאֱמָן. שֶׁהֲרֵי אֵין אָנוּ מַכִּירִין הַדָּבָר שֶׁמָּא יַעֲרִים. וְאֵינוֹ נוֹטֵל הַנֵּזֶק עַד שֶׁיִּבָּדֵק זְמַן מְרֻבֶּה וְיִהְיֶה מֻחְזָק שֶׁאָבַד מְאוֹר עֵינָיו אוֹ נִתְחָרֵשׁ וְאַחַר כָּךְ יְשַׁלֵּם זֶה:","כַּמָּה הוּא הַצַּעַר. הַכּל הוּא לְפִי הַנִּזָּק. יֵשׁ אָדָם שֶׁהוּא רַךְ וְעָנֹג מְאֹד וּבַעַל מָמוֹן וְאִלּוּ נָתְנוּ לוֹ מָמוֹן הַרְבֵּה לֹא הָיָה מִצְטַעֵר מְעַט. וְיֵשׁ אָדָם שֶׁהוּא עַמְלָן וְחָזָק וְעָנִי וּמִפְּנֵי זוּז אֶחָד מִצְטַעֵר צַעַר הַרְבֵּה. וְעַל פִּי הַדְּבָרִים הָאֵלֶּה אוֹמְדִין וּפוֹסְקִין הַצַּעַר:","כֵּיצַד מְשַׁעֲרִין הַצַּעַר בְּמָקוֹם שֶׁחִסְּרוֹ אֵיבָר. הֲרֵי שֶׁקָּטַע יָדוֹ אוֹ אֶצְבָּעוֹ אוֹמְדִים כַּמָּה אָדָם כָּזֶה רוֹצֶה לִתֵּן בֵּין לִקְטֹעַ לוֹ אֵיבָר זֶה בְּסַיִף אוֹ לִקְטֹעַ אוֹתוֹ בְּסַם אִם גָּזַר עָלָיו הַמֶּלֶךְ לִקְטֹעַ יָדוֹ אוֹ רַגְלוֹ. וְאוֹמְדִין כַּמָּה יֵשׁ בֵּין זֶה לָזֶה וּמְשַׁלֵּם הַמַּזִּיק:","כֵּיצַד מְשַׁעֲרִין הַשֶּׁבֶת. אִם לֹא חִסְּרוֹ אֵיבָר אֶלָּא חָלָה וְנָפַל לְמִשְׁכָּב אוֹ שֶׁצָּבְתָה יָדוֹ וְסוֹפָהּ לַחְזֹר נוֹתֵן לוֹ דְּמֵי שִׁבְתּוֹ שֶׁל כָּל יוֹם וְיוֹם כְּפוֹעֵל בָּטֵל שֶׁל אוֹתָהּ מְלָאכָה שֶׁבִּטֵּל מִמֶּנּוּ. וְאִם חִסְּרוֹ אֵיבָר אוֹ שֶׁקָּטַע יָדוֹ נוֹתֵן דְּמֵי יָדוֹ שֶׁהוּא הַנֵּזֶק. וְשֶׁבֶת רוֹאִין אוֹתוֹ כְּאִלּוּ הוּא שׁוֹמֵר קִשּׁוּאִים וְרוֹאִין כַּמָּה הוּא שְׂכַר שׁוֹמֵר קִשּׁוּאִין בְּכָל יוֹם וְעוֹשִׂין חֶשְׁבּוֹן כָּל יְמֵי חָלְיוֹ שֶׁל זֶה וְנוֹתֵן לוֹ. וְכֵן אִם קָטַע רַגְלוֹ רוֹאִין אוֹתוֹ כְּאִלּוּ הוּא שׁוֹמֵר עַל הַפֶּתַח. סִמֵּא עֵינוֹ רוֹאִין אוֹתוֹ כְּאִלּוּ הוּא טוֹחֵן בְּרֵחַיִם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הִכָּה אֶת חֲבֵרוֹ עַל אָזְנוֹ אוֹ אֲחָזוֹ וְתָקַע בְּאָזְנוֹ וְחֵרְשׁוֹ נוֹתֵן לוֹ דְּמֵי כֻּלּוֹ שֶׁהֲרֵי אֵינוֹ רָאוּי לִמְלָאכָה כְּלָל:","סִמֵּא אֶת עֵינוֹ וְלֹא אֲמָדוּהוּ קָטַע אֶת יָדוֹ וְלֹא אֲמָדוּהוּ וְקָטַע אֶת רַגְלוֹ וְלֹא אֲמָדוּהוּ וְאַחַר כָּךְ חֵרְשׁוֹ הוֹאִיל וְלֹא אֲמָדוּהוּ לְכָל נֵזֶק וְנֵזֶק נוֹתֵן לוֹ דְּמֵי כֻּלּוֹ. אֲמָדוּהוּ לְכָל נֵזֶק וְנֵזֶק וְאַחַר כָּךְ אֲמָדוּהוּ לְכֻלּוֹ אֵין גּוֹבִין מִמֶּנּוּ אֶלָּא דְּמֵי כֻּלּוֹ בִּלְבַד. וְאִם תָּפַשׂ הַנִּזָּק נֵזֶק כָּל אֵיבָר וְאֵיבָר וּדְמֵי כֻּלּוֹ אֵין מוֹצִיאִין מִיָּדוֹ:","כֵּיצַד מְשַׁעֲרִין הָרִפּוּי. אוֹמְדִין כַּמָּה יָמִים יִחְיֶה זֶה מֵחלִי זֶה וְכַמָּה הוּא צָרִיךְ וְנוֹתֵן לוֹ מִיָּד. וְאֵין מְחַיְּבִין אוֹתוֹ לִתֵּן דְּבַר יוֹם בְּיוֹמוֹ. וְדָבָר זֶה תַּקָּנָה הִיא לַמַּזִּיק:","וְכֵן הַשֶּׁבֶת אוֹמְדִין אוֹתָהּ וְנוֹתֵן הַכּל מִיָּד. אִם הָיָה מִתְגַּלְגֵּל בְּחָלְיוֹ וְהוֹלֵךְ וְאָרַךְ בּוֹ הַחלִי יֶתֶר עַל מַה שֶּׁאֲמָדוּהוּ אֵינוֹ מוֹסִיף לוֹ כְּלוּם. וְכֵן אִם הִבְרִיא מִיָּד אֵין פּוֹחֲתִין לוֹ מִמַּה שֶּׁאֲמָדוּהוּ:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁרָצָה הַמַּזִּיק שֶׁזּוֹ תַּקָּנָה הִיא לוֹ. אֲבָל אִם אָמַר הַמַּזִּיק אֵין רְצוֹנִי בְּתַקָּנָה זוֹ אֶלָּא אֲרַפְּאֶנּוּ דְּבַר יוֹם בְּיוֹמוֹ שׁוֹמְעִין לוֹ:","אָמַר לוֹ הַנִּזָּק פְּסֹק עִמִּי וְתֵן עַל יָדִי וַאֲנִי אֲרַפֵּא אֶת עַצְמִי אֵין שׁוֹמְעִין לוֹ שֶׁהֲרֵי אוֹמֵר לוֹ שֶׁמָּא לֹא תְּרַפֵּא עַצְמְךָ וְאֶחֱזַק אֲנִי כְּמַזִּיק אֶלָּא נוֹתֵן לוֹ דְּבַר יוֹם בְּיוֹמוֹ. אוֹ פּוֹסֵק עַל הַכּל וְנוֹתֵן דְּמֵי הָרִפּוּי עַל יְדֵי בֵּית דִּין:","אָמַר לוֹ הַמַּזִּיק אֲנִי אֲרַפֵּא אוֹתְךָ אוֹ יֵשׁ לִי רוֹפֵא שֶׁמְּרַפֵּא בְּחִנָּם אֵין שׁוֹמְעִין לוֹ אֶלָּא מֵבִיא רוֹפֵא אֻמָּן וּמְרַפְּאֵהוּ בְּשָׂכָר:","הֲרֵי שֶׁלֹּא פָּסַק עִמּוֹ אֶלָּא הָיָה מְרַפֵּא יוֹם וְיוֹם וְעָלוּ בּוֹ צְמָחִים מֵחֲמַת הַמַּכָּה אוֹ נִסְתְּרָה הַמַּכָּה אַחַר שֶׁחָיְתָה. חַיָּב לְרַפְּאוֹתוֹ וְלָתֵת לוֹ דְּמֵי שִׁבְתּוֹ. עָלוּ בּוֹ צְמָחִים שֶׁלֹּא מֵחֲמַת הַמַּכָּה חַיָּב לְרַפְּאוֹתוֹ וְאֵינוֹ נוֹתֵן לוֹ דְּמֵי שִׁבְתּוֹ. עָבַר עַל דִּבְרֵי רוֹפֵא וְהִכְבִּיד עָלָיו הַחלִי אֵינוֹ חַיָּב לְרַפְּאוֹתוֹ:","כְּשֶׁפּוֹסְקִין בֵּית דִּין עַל הַמַּזִּיק וּמְחַיְּבִין אוֹתוֹ לְשַׁלֵּם גּוֹבִין מִמֶּנּוּ הַכּל מִיָּד וְאֵין קוֹבְעִין לוֹ זְמַן כְּלָל. וְאִם נִתְחַיֵּב בְּבשֶׁת בִּלְבַד קוֹבְעִין לוֹ זְמַן לְשַׁלֵּם שֶׁהֲרֵי לֹא חִסְּרוֹ מָמוֹן:"],"Mishneh Torah, Other Sources of Defilement 14":["שְׁנֵּים עָשָׂר סְפֵקוֹת טהֲרוּ חֲכָמִים וְאֵלּוּ הֵן. סְפֵק מַיִם שְׁאוּבִים לְמִקְוֶה. סְפֵק טֻמְאָה צָפָה עַל פְּנֵי הַמַּיִם. סְפֵק מַשְׁקִין לְטַמֵּא אֲחֵרִים. אֲבָל לְטֻמְאַת עַצְמָן טְמֵאִים מִסָּפֵק. סְפֵק הַיָּדַיִם בֵּין לְטֻמְאַת עַצְמָן בֵּין לְטַמֵּא אֲחֵרִים בֵּין לְטָהֳרַת יָדַיִם מִטֻּמְאָתָן. סְפֵק דִּבְרֵי סוֹפְרִים. סְפֵק הַחֻלִּין. סְפֵק קָרְבָּנוֹת. סְפֵק נְגָעִים. סָפֵק עוֹבֵר וְעוֹמֵד. סְפֵק שְׁרָצִים. סְפֵק רְשׁוּת הָרַבִּים. סְפֵק שְׁתֵּי רְשׁוּיוֹת:","סְפֵק מַיִם שְׁאוּבִין לְמִקְוֶה כֵּיצַד. שְׁלֹשָׁה לוֹגִין מַיִם שְׁאוּבִין שֶׁנָּפְלוּ לַמִּקְוֶה פְּסָלוּהוּ. סָפֵק נָפְלוּ סָפֵק לֹא נָפְלוּ וַאֲפִלּוּ נָפְלוּ סָפֵק יֵשׁ בָּהֶן שִׁעוּר אוֹ אֵין בָּהֶן סְפֵקוֹ טָהוֹר וַהֲרֵי הַמִּקְוֶה בְּכַשְׁרוּתוֹ. וְאֵין מוֹרִין לוֹ לִטְבּל בְּמִקְוֶה זֶה וְלַעֲשׂוֹת טָהֳרוֹת לְכַתְּחִלָּה. וְאִם טָבַל וְעָשָׂה טָהֳרוֹתָיו טְהוֹרוֹת:","סְפֵק טֻמְאָה צָפָה עַל פְּנֵי הַמַּיִם כֵּיצַד. שֶׁרֶץ שֶׁהָיָה צָף עַל פְּנֵי הַמַּיִם. בֵּין שֶׁהָיוּ הַמַּיִם בְּכֵלִים אוֹ בְּקַרְקָעוֹת וְיָרַד לַמַּיִם אֲפִלּוּ אֵין שָׁם אֶלָּא מְלֹא אָדָם וְטֻמְאָה הֲרֵי זֶה טָהוֹר עַד שֶׁיֵּדַע וַדַּאי שֶׁנָּגַע. וְלֹא אָמְרוּ סְפֵק טֻמְאָה צָפָה טָהוֹר אֶלָּא לְשֶׁרֶץ בִּלְבַד. וְכָל הַנִּתְלִים וְהַנִּגְרָרִין הֲרֵי הֵן כְּמֻנָּחִין:","שֶׁרֶץ שֶׁהָיָה מֻנָּח בִּכְלִי וּכְלִי צָף עַל פְּנֵי הַמַּיִם אוֹ שֶׁהָיָה מֻנָּח עַל הַמֵּת אוֹ עַל הַנְּבֵלָה וַאֲפִלּוּ נִמּוֹחַ הַנְּבֵלָה אוֹ בָּשָׂר מֵת שֶׁתַּחְתָּיו אוֹ שֶׁהָיָה מֻנָּח עַל שִׁכְבַת זֶרַע הַצָּפָה עַל פְּנֵי הַמַּיִם הֲרֵי זֶה כְּמֻנָּח עַל הָאָרֶץ שֶׁסְּפֵקוֹ בִּרְשׁוּת הַיָּחִיד טָמֵא כְּמוֹ שֶׁיִּתְבָּאֵר. הָיָה שֶׁרֶץ עַל גַּבֵּי שֶׁרֶץ צָף עַל פְּנֵי הַמַּיִם הֲרֵי זֶה כְּטֻמְאָה עָבָה שֶׁצָּפָה עַל פְּנֵי הַמַּיִם וּסְפֵקוֹ טָהוֹר. הָיָה מֻנָּח עַל גַּבֵּי מֵי חַטָּאת וּמֵי חַטָּאת צָפִין עַל פְּנֵי הַמַּיִם הֲרֵי זֶה סָפֵק אִם הוּא כְּמֻנָּח אוֹ אֵינוֹ כְּמֻנָּח. לְפִיכָךְ יֵרָאֶה לִי שֶׁסְּפֵקוֹ טָהוֹר:","כְּדֶרֶךְ שֶׁטִּהֲרוּ סְפֵק טֻמְאָה צָפָה עַל פְּנֵי הַמַּיִם בֵּין בְּכֵלִים בֵּין בְּקַרְקָעוֹת כָּךְ טִהֲרוּ סְפֵק טָהֳרָה הַצָּפָה עַל פְּנֵי הַמַּיִם בֵּין בְּכֵלִים בֵּין בְּקַרְקָעוֹת. כֵּיצַד. עֲרֵבָה שֶׁהִיא טְמֵא מֵת וְכִכַּר תְּרוּמָה כָּרוּךְ בְּסִיב אוֹ בִּנְיָר וְנָתוּן בְּתוֹכָהּ וְיָרְדוּ לְתוֹכָהּ מֵי גְּשָׁמִים וְנִתְמַלֵּאת וְנִפְשַׁט הַנְּיָר וַהֲרֵי הַכִּכָּר צָף עַל פְּנֵי הַמַּיִם וְהַנְּיָר מַבְדִּיל בֵּינוֹ לְבֵין הַמַּיִם וְסָפֵק נָגַע צִדּוֹ בַּעֲרֵבָה סָפֵק לֹא נָגַע. הֲרֵי הוּא בְּטָהֳרָתוֹ מִפְּנֵי שֶׁהוּא צָף:","שֶׁרֶץ שֶׁנִּמְצָא צָף עַל גַּבֵּי בּוֹר בְּתוֹךְ הַגַּת לִתְרוּמָה סְפֵקוֹ טָמֵא. וְלַפּוֹעֲלִין סְפֵקָן טָהוֹר. מִפְּנֵי שֶׁהִיא טֻמְאָה צָפָה:","סָפֵק מַשְׁקִין לְטַמֵּא אֲחֵרִים טָהוֹר. לְטֻמְאַת עַצְמָן טָמֵא. כֵּיצַד. הָיָה מַקֵּל בְּיָדוֹ וּבְרֹאשׁוֹ מַשְׁקִין טְמֵאִים וּזְרָקָן לְתוֹךְ כִּכָּרוֹת טְהוֹרוֹת. סָפֵק נָגְעוּ הַמַּשְׁקִין בַּכִּכָּרוֹת סָפֵק לֹא נָגְעוּ טְהוֹרוֹת. וְכֵן אִם נִסְתַּפֵּק לוֹ אִם נָגְעוּ מַשְׁקִין טְמֵאִין בִּכְלִי זֶה אוֹ לֹא נָגְעוּ הֲרֵי הַכְּלִי טָהוֹר. וְכֵן אִם נִסְתַּפֵּק לוֹ אִם נָגְעוּ מַשְׁקִין אֵלּוּ הַטְּמֵאִין בְּמַשְׁקִין אֲחֵרִים אוֹ לֹא נָגְעוּ הֲרֵי הַמַּשְׁקִין הָאֲחֵרִים טְהוֹרִין. אֲבָל טָמֵא שֶׁפָּשַׁט יָדוֹ אוֹ רַגְלוֹ לְבֵין מַשְׁקִין טְהוֹרִין. אוֹ שֶׁזָּרַק כִּכָּר טָמֵא לְבֵין מַשְׁקִין טְהוֹרִין סָפֵק נָגַע בַּמַּשְׁקִין סָפֵק לֹא נָגַע הֲרֵי אֵלּוּ טְמֵאִין בְּסָפֵק. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","חָבִית שֶׁהִיא מְלֵאָה מַשְׁקִין וּפָשַׁט הַטָּמֵא אֶת יָדוֹ לַאֲוִירָהּ סָפֵק נָגַע בַּמַּשְׁקִין סָפֵק לֹא נָגַע בָּהֶן הַמַּשְׁקִין טְמֵאִין וְהֶחָבִית טְהוֹרָה שֶׁאֵין סְפֵק הַמַּשְׁקִין מְטַמֵּא. וְכֵן אִם נִכְנְסוּ מַשְׁקִין שֶׁהֵן טְמֵאִין מִסָּפֵק לַאֲוִיר הֶחָבִית הֲרֵי הֶחָבִית טְהוֹרָה וְהַמַּשְׁקִין שֶׁבְּתוֹכָהּ טְהוֹרִין שֶׁאֵינָן מִתְטַמְּאִין אֶלָּא מִן הֶחָבִית. וְאִם נִתְעָרְבוּ מַשְׁקִין אֵלּוּ הַסָּפֵק בְּמַשְׁקִין שֶׁבֶּחָבִית הֲרֵי כָּל הַמַּשְׁקִין טְמֵאִין בְּסָפֵק וְהֶחָבִית טְהוֹרָה. וְכֵן אִם נָפְלוּ מַשְׁקִין אֵלּוּ לְתוֹךְ הַתַּנּוּר הֲרֵי הַפַּת וְהַתַּנּוּר טְהוֹרִין:","הַמְרַבֵּץ בֵּיתוֹ בְּמַיִם טְמֵאִים אוֹ שֶׁזִּלְּפָן וְהָיוּ שָׁם טָהֳרוֹת סָפֵק נִתְּזוּ עֲלֵיהֶן סָפֵק לֹא נִתְּזוּ סְפֵקוֹ טָהוֹר:","זִלֵּף מַשְׁקִין טְהוֹרִין וּטְמֵאִים בְּתוֹךְ הַבַּיִת וְנִמְצְאוּ אַחַר כָּךְ מַשְׁקִין עַל כִּכָּר שֶׁל תְּרוּמָה. נְטָלָהּ וְנִשְׁאַל עָלֶיהָ הֲרֵי זוֹ טְהוֹרָה שֶׁסְּפֵק הַמַּשְׁקִין לְטַמֵּא טָהוֹר. הִנִּיחַ הַכִּכָּר עַד שֶׁיִּנָּגְבוּ הַמַּיִם שֶׁעָלֶיהָ הֲרֵי זוֹ טְמֵאָה בְּסָפֵק שֶׁסְּפֵק טֻמְאָה בִּרְשׁוּת הַיָּחִיד טָמֵא כְּמוֹ שֶׁיִּתְבָּאֵר. וַהֲרֵי אֵין כָּאן מַשְׁקִין אֶלָּא כִּכָּר שֶׁהִיא סָפֵק טְמֵאָה סָפֵק טְהוֹרָה:","סְפֵק יָדַיִם בֵּין לְהִתְטַמֵּא בֵּין לְטַמֵּא אֲחֵרִים בֵּין לְטָהֳרָתָן טָהוֹר כֵּיצַד. הָיוּ יָדָיו טְהוֹרוֹת וּלְפָנָיו שְׁנֵי כִּכָּרִים טְמֵאִין סָפֵק נָגַע סָפֵק לֹא נָגַע. אוֹ שֶׁהָיוּ יָדָיו טְמֵאוֹת וּלְפָנָיו שְׁנֵי כִּכָּרִים טְהוֹרִים סָפֵק נָגַע סָפֵק לֹא נָגַע. אוֹ שֶׁהָיוּ יָדָיו אַחַת טְהוֹרָה וְאַחַת טְמֵאָה וּלְפָנָיו שְׁנֵי כִּכָּרִים טְהוֹרִים וְנָגַע בְּאֶחָד מֵהֶן וְסָפֵק בַּטְּמֵאָה נָגַע סָפֵק בַּטְּהוֹרָה. אוֹ שֶׁהָיוּ יָדָיו טְהוֹרוֹת וּלְפָנָיו שְׁנֵי כִּכָּרִים אֶחָד טָהוֹר וְאֶחָד טָמֵא וְנָגַע בְּאֶחָד מֵהֶם סָפֵק בַּטָּמֵא נָגַע סָפֵק בַּטָּהוֹר נָגַע. אוֹ שֶׁהָיוּ יָדָיו אַחַת טְהוֹרָה וְאַחַת טְמֵאָה וּלְפָנָיו כִּכָּר טָמֵא וְכִכָּר טָהוֹר וְנָגַע בִּשְׁנֵיהֶן סָפֵק טְמֵאָה בַּטָּמֵא וְהַטְּהוֹרָה בַּטָּהוֹר אוֹ טְמֵאָה בַּטָּהוֹר וְהַטְּהוֹרָה בַּטָּמֵא. הַיָּדַיִם כְּמוֹ שֶׁהָיוּ וְהַכִּכָּרִים כְּמוֹת שֶׁהָיוּ. וְכֵן אִם הָיוּ יָדָיו טְמֵאוֹת וְהִטְבִּילָן אוֹ נְטָלָן סָפֵק שֶׁהַמַּיִם שֶׁטִּהֲרוּ בָּהֶן כְּשֵׁרִים לְיָדַיִם סָפֵק שֶׁהֵן פְּסוּלִין. סָפֵק יֵשׁ בָּהֶן כְּשִׁעוּר סָפֵק אֵין בָּהֶן. סָפֵק שֶׁהָיָה דָּבָר חוֹצֵץ עַל יָדוֹ סָפֵק שֶׁלֹּא הָיָה. הֲרֵי יָדָיו טְהוֹרוֹת:","הָיְתָה יָדוֹ אַחַת טְמֵאָה וְאֵינוֹ יוֹדֵעַ אֵי זוֹ הִיא אוֹמְרִין לוֹ שֶׁלֹּא יַעֲשֶׂה טָהֳרוֹת עַד שֶׁיִּטּל שְׁתֵּי יָדָיו. וְאִם נָגַע בְּאַחַת מֵהֶן בְּטָהֳרוֹת קֹדֶם שֶׁיִּטּוֹל יָדָיו טָהֳרוֹתָיו טְהוֹרוֹת:"],"Mishneh Torah, Other Sources of Defilement 7":["דָבָר מְפֹרָשׁ בַּתּוֹרָה שֶׁהָאֳכָלִין וְהַמַּשְׁקִין מִתְטַמְּאִין שֶׁנֶּאֱמַר (ויקרא יא לד) \"מִכָּל הָאֹכֶל אֲשֶׁר יֵאָכֵל אֲשֶׁר יָבוֹא עָלָיו מַיִם יִטְמָא וְכָל מַשְׁקֶה אֲשֶׁר יִשָּׁתֶה בְּכָל כְּלִי יִטְמָא\". וְאֵין הָאֹכֶל שֶׁנִּטְמָא מְטַמֵּא אֹכֶל אַחֵר מִן הַתּוֹרָה. וְלֹא הַמַּשְׁקִין שֶׁנִּטְמְאוּ מְטַמְּאִין דָּבָר אַחֵר מִן הַתּוֹרָה. אֲבָל מִדִּבְרֵי סוֹפְרִים גָּזְרוּ עַל הָאֹכֶל הַטָּמֵא שֶׁאִם נָגַע בְּאֹכֶל אַחֵר טִמְּאָהוּ. וְכֵן אִם נָגַע אֹכֶל הַטָּמֵא בְּמַשְׁקִין טְמֵאִין. וְאֵין אֹכֶל מְטַמֵּא כְּלִי שֶׁנָּגַע בּוֹ לְעוֹלָם וַאֲפִלּוּ מִדִּבְרֵיהֶם. וְכֵן גָּזְרוּ עַל הַמַּשְׁקִין הַטְּמֵאִים שֶׁיְּטַמְּאוּ אֳכָלִין אוֹ מַשְׁקִין אוֹ כֵּלִים שֶׁנָּגְעוּ בָּהֶן:","אֵין לְךָ וְלַד טֻמְאָה שֶׁמְּטַמֵּא כֵּלִים אֶלָּא מַשְׁקִין טְמֵאִים בִּלְבַד. וְטֻמְאָה זוֹ מִדִּבְרֵיהֶם וְהוּא שֶׁיִּהְיוּ אוֹתָן הַמַּשְׁקִין טְמֵאִין מֵחֲמַת אָב מֵאֲבוֹת הַטֻּמְאוֹת בֵּין שֶׁל תּוֹרָה בֵּין שֶׁל דִּבְרֵיהֶם. וּמִפְּנֵי מָה גָּזְרוּ עַל הַמַּשְׁקִין טְמֵאִין שֶׁיְּטַמְּאוּ כֵּלִים גְּזֵרָה מִשּׁוּם מַשְׁקֵה הַזָּב שֶׁהוּא אָב וּמְטַמֵּא כֵּלִים דִּין תּוֹרָה. שֶׁנֶּאֱמַר (ויקרא טו ח) \"וְכִי יָרֹק הַזָּב בַּטָּהוֹר\" כְּמוֹ שֶׁבֵּאַרְנוּ:","כְּשֶׁגָּזְרוּ עַל הַמַּשְׁקִין שֶׁיְּטַמְּאוּ אֶת הַכֵּלִים גָּזְרוּ שֶׁיִּהְיוּ מְטַמְּאִין אֶת הַכֵּלִים מִתּוֹכָן. כֵּיצַד. אִם נָפְלוּ לַאֲוִיר כְּלִי חֶרֶס נִטְמָא כֻּלּוֹ וַהֲרֵי הוּא שֵׁנִי וְאִם נָגְעוּ בִּשְׁאָר כֵּלִים מִתּוֹכָן מְטַמֵּא כֻּלָּן וְנַעֲשׂוּ שְׁנִיִּים. אֲבָל אִם נָגְעוּ מַשְׁקִין טְמֵאִים בַּאֲחוֹרֵי הַכְּלִי שֶׁיֵּשׁ לוֹ תּוֹךְ בֵּין בִּכְלִי חֶרֶס בֵּין בִּכְלִי שֶׁטֶף וּכְלִי מַתָּכוֹת נִטְמְאוּ אֲחוֹרָיו בִּלְבַד וַהֲרֵי אֲחוֹרָיו שֵׁנִי וְלֹא נִטְמָא תּוֹכוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים לִתְרוּמָה. אֲבָל לְקֹדֶשׁ כְּלִי שֶׁנִּטְמְאוּ אֲחוֹרָיו נִטְמָא כֻּלּוֹ וַהֲרֵי כֻּלּוֹ שֵׁנִי לְטֻמְאָה:","כְּבָר בֵּאַרְנוּ שֶׁהָאֳכָלִין אֵין מְטַמְּאִין כֵּלִים וְהַמַּשְׁקִין מְטַמְּאִין. וְלָמָּה עָשׂוּ בְּטֻמְאַת מַשְׁקִין הֶכֵּר זֶה וְאָמְרוּ שֶׁהַכְּלִי שֶׁנָּגְעוּ מַשְׁקִין טְמֵאִין בַּאֲחוֹרָיו לֹא נִטְמָא תּוֹכוֹ לִתְרוּמָה. לְהוֹדִיעַ שֶׁטֻּמְאַת כֵּלִים אֵלּוּ מִדִּבְרֵיהֶם שֶׁלֹּא יִשְׂרְפוּ עָלֶיהָ תְּרוּמָה וְקָדָשִׁים:","כְּבָר בֵּאַרְנוּ שֶׁהָאֳכָלִין וְהַמַּשְׁקִין שֶׁנָּגְעוּ בְּאָב מֵאֲבוֹת הַטֻּמְאוֹת הֲרֵי הֵן רִאשׁוֹן לְטֻמְאָה. וְכֵן אִם נָגַע אֹכֶל בְּאָדָם אוֹ בִּכְלִי שֶׁנִּטְמָא בְּאָב הֲרֵי אוֹתוֹ הָאֹכֶל שֵׁנִי לְטֻמְאָה. וְאֹכֶל שֶׁנָּגַע בְּזֶה הַשֵּׁנִי נִקְרָא שְׁלִישִׁי לְטֻמְאָה. וְאִם נָגַע הַשְּׁלִישִׁי בְּאֹכֶל (רְבִיעִי) הֲרֵי זֶה נִקְרָא רְבִיעִי לְטֻמְאָה. בַּמֶּה דְּבָרִים אֲמוּרִים בָּאֳכָלִין. אֲבָל הַמַּשְׁקִין אֶחָד מַשְׁקֶה שֶׁנָּגַע בְּאַב הַטֻּמְאָה אוֹ שֶׁנָּגַע בְּרִאשׁוֹן אוֹ שֶׁנָּגַע בְּשֵׁנִי הֲרֵי אוֹתוֹ הַמַּשְׁקֶה תְּחִלָּה לְטֻמְאָה וּמְטַמֵּא אֶת חֲבֵרוֹ וַחֲבֵרוֹ אֶת חֲבֵרוֹ אֲפִלּוּ הֵן מֵאָה שֶׁאֵין מוֹנִין בְּמַשְׁקִין. כֵּיצַד. יַיִן שֶׁנָּגַע בְּאַב הַטֻּמְאָה אוֹ בְּרִאשׁוֹן אוֹ בְּשֵׁנִי הֲרֵי יַיִן זֶה כְּרִאשׁוֹן לְטֻמְאָה. וְכֵן אִם נָגַע יַיִן זֶה בְּשֶׁמֶן וְשֶׁמֶן בְּחָלָב וְחָלָב בִּדְבַשׁ וּדְבַשׁ בְּמַיִם וּמַיִם בְּיַיִן אַחֵר וְכֵן עַד לְעוֹלָם כֻּלָּן רִאשׁוֹן לְטֻמְאָה וּכְאִלּוּ כָּל אֶחָד מֵהֶן נִטְמָא בְּאָב תְּחִלָּה וְכֻלָּן מְטַמְּאִין אֶת הַכֵּלִים. וְכֵן כְּלִי שֶׁנִּטְמְאוּ אֲחוֹרָיו בְּמַשְׁקִין וְנָגְעוּ מַשְׁקִין אֲחֵרִים בַּאֲחוֹרֵי הַכֵּלִים הַטְּמֵאִין אֲפִלּוּ הָיוּ מַשְׁקִין חֻלִּין נַעֲשׂוּ הַמַּשְׁקִין הָאֲחֵרִים תְּחִלָּה לְטֻמְאָה וּמְטַמְּאִין כֵּלִים אֲחֵרִים וְעוֹשִׂין אוֹתָן שְׁנִיִּים וְאֵין צָרִיךְ לוֹמַר שֶׁהֵן מְטַמְּאִין אֳכָלִין וּמַשְׁקִין אֲחֵרִים:","אֲחוֹרֵי הַכְּלִי שֶׁנִּטְמְאוּ בְּמַשְׁקִין וְנָגְעוּ אֳכָלִין בַּאֲחוֹרֵי הַכְּלִי הַטָּמֵא אֲפִלּוּ אָכְלֵי תְּרוּמָה הֲרֵי הֵן טְהוֹרִין שֶׁהַכְּלִי שֶׁנִּטְמְאוּ אֲחוֹרָיו בִּלְבַד אֵינוֹ מְטַמֵּא אֶת הָאֳכָלִין אֶלָּא לְקֹדֶשׁ בִּלְבַד שֶׁהַכְּלִי שֶׁנִּטְמְאוּ אֲחוֹרָיו הֲרֵי זֶה טָמֵא כֻּלּוֹ לְקֹדֶשׁ כְּמוֹ שֶׁבֵּאַרְנוּ וּלְפִיכָךְ מְטַמֵּא אֹכֶל הַקֹּדֶשׁ:"],"Mishneh Torah, Overview of Mishneh Torah Contents 5":["ספר קדושה","הלכותיו שלוש, וזה הוא סידורן: הלכות איסורי ביאה, הלכות מאכלות אסורות, הלכות שחיטה.","הלכות איסורי ביאה. יש בכללן שבע ושלושים מצוות – אחת מצות עשה, ושש ושלושים מצוות לא תעשה; וזה הוא פרטן: (א) שלא לבוא על האם; (ב) שלא לבוא על אשת אב; (ג) שלא לבעול אחות; (ד) שלא לבעול בת אשת אב; (ה) שלא לבעול בת הבן; (ו) שלא לבעול בת; (ז) שלא לבעול בת הבת; (ח) שלא לישא אישה ובתה; (ט) שלא לישא אישה ובת בנה; (י) שלא לישא אישה ובת בתה; (יא) שלא לבעול אחות אב; (יב) שלא לבעול אחות אם; (יג) שלא לבעול אשת אחי האב; (יד) שלא לבעול אשת הבן; (טו) שלא לבעול אשת אח; (טז) שלא לבעול אחות אשתו; (יז) שלא לשכב עם בהמה; (יח) שלא תביא אישה בהמה עליה; (יט) שלא לשכב עם זכר; (כ) שלא לגלות ערוות אב; (כא) שלא לגלות ערוות אחי האב; (כב) שלא לבעול אשת איש; (כג) שלא לבעול נידה; (כד) שלא להתחתן בגויים; (כה) שלא יבוא עמוני ומואבי בקהל; (כו) שלא להרחיק דור שלישי מצרי מלבוא בקהל; (כז) שלא להרחיק דור שלישי אדומי מלבוא בקהל; (כח) שלא יבוא ממזר בקהל; (כט) שלא יבוא סריס בקהל; (ל) שלא לסרס זכר, ואפילו בהמה חיה ועוף; (לא) שלא יישא כוהן גדול אלמנה; (לב) שלא יבעול כוהן גדול אלמנה, אפילו בלא נישואין; (לג) שיישא כוהן גדול בתולה בנערותה; (לד) שלא יישא כוהן גרושה; (לה) שלא יישא זונה; (לו) שלא יישא חללה; (לז) שלא יקרב אדם לאחת מכל העריות, ואפילו שלא בעל.","הלכות מאכלות אסורות. יש בכללן שמונה ועשרים מצוות – ארבע מצוות עשה, וארבע ועשרים מצוות לא תעשה; וזה הוא פרטן: (א) לבדוק בסימני בהמה וחיה להבדיל בין טמאה לטהורה; (ב) לבדוק בסימני העוף להבדיל בין טמא לטהור; (ג) לבדוק בסימני חגבים להבדיל בין טמא לטהור; (ד) לבדוק בסימני דגים להבדיל בין טמא לטהור; (ה) שלא לאכול בהמה וחיה טמאה; (ו) שלא לאכול עוף טמא; (ז) שלא לאכול דגים טמאים; (ח) שלא לאכול שרץ העוף; (ט) שלא לאכול שרץ הארץ; (י) שלא לאכול רמש הארץ; (יא) שלא לאכול תולעת הפירות כשתצא לארץ; (יב) שלא לאכול שרץ המים; (יג) שלא לאכול נבילה; (יד) שלא ליהנות בשור הנסקל; (טו) שלא לאכול טריפה; (טז) שלא לאכול אבר מן החי; (יז) שלא לאכול דם; (יח) שלא לאכול חלב בהמה טהורה; (יט) שלא לאכול גיד הנשה; (כ) שלא לאכול בשר בחלב; (כא) שלא לבשלו; (כב) שלא לאכול לחם תבואה חדשה; (כג) שלא לאכול קלי מן החדש; (כד) שלא לאכול כרמל מן החדש; (כה) שלא לאכול עורלה; (כו) שלא לאכול כלאי הכרם; (כז) שלא לאכול טבל; (כח) שלא לשתות יין נסך.","הלכות שחיטה. יש בכללן חמש מצוות – שלוש מצוות עשה, ושתיים מצוות לא תעשה; וזה הוא פרטן: (א) לשחוט ואחר כך יאכל; (ב) שלא לשחוט אותו ואת בנו ביום אחד; (ג) לכסות דם חיה ועוף; (ד) שלא ליקח האם על הבנים; (ה) לשלח האם, אם לקחה על הבנים.","נמצאו כל המצוות הנכללות בספר זה, שבעים – מהם שמונה מצוות עשה, ושתיים ושישים מצוות לא תעשה."],"Mishneh Torah, Ownerless Property and Gifts 5":["הַנּוֹתֵן מַתָּנָה בֵּין בָּרִיא בֵּין חוֹלֶה צָרִיךְ שֶׁתִּהְיֶה גְּלוּיָה וּמְפֻרְסֶמֶת. אָמַר לְעֵדִים כִּתְבוּ בַּסֵּתֶר וּתְנוּ לוֹ אֵינָהּ כְּלוּם. שֶׁזֶּה מַעֲרִים כְּדֵי לְאַבֵּד מָמוֹן אֲחֵרִים שֶׁיַּחֲזֹר וְיִמְכֹּר אַחַר שֶׁיִּתֵּן:","לְפִיכָךְ כָּל שְׁטַר מַתְּנַת קַרְקַע שֶׁאֵין כָּתוּב בּוֹ וְאָמַר לָנוּ פְּלוֹנִי הַנּוֹתֵן שְׁבוּ בַּשְּׁוָקִים וּבָרְחוֹבוֹת וְכִתְבוּ לוֹ מַתָּנָה גְּלוּיָה וּמְפֻרְסֶמֶת וְכַיּוֹצֵא בְּעִנְיָנִים אֵלּוּ חוֹשְׁשִׁין לָהּ שֶׁמָּא מַתָּנָה מְסֻתֶּרֶת הִיא וְלֹא זָכָה הַמְקַבֵּל:","הַכּוֹתֵב שְׁתֵּי מַתָּנוֹת עַל שָׂדֶה אַחַת הָרִאשׁוֹנָה מְסֻתֶּרֶת וְהָאַחֲרוֹנָה גְּלוּיָה וּמְפֻרְסֶמֶת אַחֲרוֹן קָנָה וַאֲפִלּוּ הָיְתָה הָרִאשׁוֹנָה סְתָם וְאֵין בָּהּ לֹא עִנְיַן סְתִירָה וְלֹא עִנְיַן גִּלּוּי אֶלָּא מַתָּנָה סְתָם הָאַחֲרוֹן קָנָה:","כְּבָר בֵּאַרְנוּ שֶׁהַמּוֹסֵר מוֹדָעָה וְאַחַר כָּךְ נָתַן הַמַּתָּנָה בְּטֵלָה אַף עַל פִּי שֶׁאֵין זֶה אֹנֶס. שֶׁאֵין הוֹלְכִין בְּמַתָּנָה אֶלָּא אַחַר דַּעַת הַנּוֹתֵן. הוֹאִיל וְגִלָּה דַּעְתּוֹ שֶׁאֵינוֹ רוֹצֶה בָּהּ מַתְּנָתוֹ בְּטֵלָה. לְפִיכָךְ מִי שֶׁהָיוּ הַדְּבָרִים מוֹכִיחִין שֶׁאֵין דַּעְתּוֹ לִתֵּן מַתָּנָה זוֹ אֲפִלּוּ שֶׁנְּתָנָהּ מַתָּנָה גְּלוּיָה וְנִמְצֵאת שֶׁנִּתְּנָה מִקֹּדֶם מַתָּנָה מְסֻתֶּרֶת הֲרֵי שְׁתֵּי הַמַּתָּנוֹת בְּטֵלוֹת. הָרִאשׁוֹנָה מִפְּנֵי שֶׁהִיא מְסֻתֶּרֶת. וְהַשְּׁנִיָּה מִפְּנֵי שֶׁהַדָּבָר מוֹכִיחַ שֶׁאֵינוֹ רוֹצֶה וַהֲרֵי קָדְמָה זוֹ הַמַּתָּנָה שֶׁנִּמְצְאָה כְּמוֹ מוֹדָעָה לָהּ:","מַעֲשֶׂה בְּאֶחָד שֶׁרָצָה לִשָּׂא אִשָּׁה. אָמְרָה לוֹ אֵינִי נִשֵּׂאת לְךָ עַד שֶׁתִּכְתֹּב לִי כָּל נְכָסֶיךָ. שָׁמַע בְּנוֹ הַגָּדוֹל וְצָוַח עַל שֶׁמַּנִּיחוֹ רֵיקָן. אָמַר לָעֵדִים לְכוּ וְהֵחָבְאוּ וְכִתְבוּ לוֹ כָּל נְכָסַי בְּמַתָּנָה. וְאַחַר כָּךְ כָּתַב לָהּ כָּל נְכָסָיו וּנְשָׂאָהּ. וּבָא מַעֲשֶׂה לִפְנֵי חֲכָמִים וְאָמְרוּ הַבֵּן לֹא קָנָה וְהָאִשָּׁה לֹא קָנְתָה. שֶׁהֲרֵי לֹא בִּרְצוֹנוֹ כָּתַב לָהּ וּכְאָנוּס בַּדָּבָר הוּא. שֶׁהֲרֵי גִּלָּה דַּעְתּוֹ בַּמַּתָּנָה הָרִאשׁוֹנָה אַף עַל פִּי שֶׁהִיא בְּטֵלָה מִפְּנֵי שֶׁהִיא מְסֻתֶּרֶת. וְכֵן כָּל כַּיּוֹצֵא בְּעִנְיָנִים אֵלּוּ:","שְׁנֵי שְׁטָרוֹת שֶׁזְּמַנָּן בְּיוֹם אֶחָד וְהֵן כְּתוּבִין עַל שָׂדֶה אַחַת בֵּין בְּמֶכֶר בֵּין בְּמַתָּנָה. אִם דֶּרֶךְ אַנְשֵׁי הַמָּקוֹם לִכְתֹּב שָׁעוֹת כָּל הַקּוֹדֵם זָכָה. וְאִם אֵין דֶּרֶךְ הַמָּקוֹם לִכְתֹּב שָׁעוֹת הֲרֵי הַדָּבָר מָסוּר לַדַּיָּנִים. כָּל שֶׁדַּעְתָּם נוֹטָה לְהַעֲמִיד שָׂדֶה זוֹ בְּיָדוֹ יַעֲמִידוּ:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁטָר שֶׁאֵין בּוֹ קִנְיָן אֶלָּא קָנָה שָׂדֶה זוֹ בִּשְׁטָר זֶה. שֶׁאֵין אָנוּ יוֹדְעִין מִי הוּא מִשְּׁנֵיהֶם שֶׁהִגִּיעַ שְׁטָרוֹ לְיָדוֹ תְּחִלָּה. אֲבָל אִם הָיָה בְּכָל שְׁטָר מֵהֶן קִנְיָן כָּל שֶׁקָּדַם לוֹ הַקִּנְיָן זָכָה וְיִשְׁאֲלוּ הָעֵדִים. וְכֵן אִם הָיוּ שָׁם עֵדִים שֶׁזֶּה הִגִּיעַ לְיָדוֹ שְׁטַר מַתְּנָתוֹ תְּחִלָּה קָנָה הָרִאשׁוֹן:","שְׁנֵי שְׁטָרוֹת הַיּוֹצְאִים עַל שָׂדֶה אַחַת בְּשֵׁם קוֹנֶה אֶחָד וְאֵין זְמַנָּם שָׁוֶה. אִם הָיָה שְׁטָר אֶחָד מֶכֶר וְאֶחָד מַתָּנָה. אִם הָיָה הַשְּׁטָר הָרִאשׁוֹן מַתָּנָה וְהַשֵּׁנִי שֶׁאַחֲרָיו מֶכֶר לֹא בִּטֵּל הָאַחֲרוֹן אֶת הָרִאשׁוֹן. שֶׁיֵּשׁ לוֹמַר לְהוֹסִיף לוֹ אַחֲרָיוּת חָזַר וְכָתַב בְּשֵׁם מֶכֶר אַף עַל פִּי שֶׁלֹּא הָיָה כּוֹתֵב שָׁם אַחֲרָיוּת שֶׁאַחֲרָיוּת טָעוּת סוֹפֵר הוּא. וְכֵן אִם הָרִאשׁוֹן מֶכֶר וְהַשֵּׁנִי מַתָּנָה קָנָה הַשָּׂדֶה מִזְּמַן רִאשׁוֹן. שֶׁלֹּא כָּתַב לוֹ שְׁטַר מַתָּנָה אֶלָּא לְיַפּוֹת כֹּחוֹ וּמִשּׁוּם דִּין בֶּן הַמֵּצַר:","הָיוּ שְׁנֵי הַשְּׁטָרוֹת בְּמֶכֶר אוֹ שְׁנֵיהֶם בְּמַתָּנָה. אִם הוֹסִיף בַּשֵּׁנִי כְּלוּם הֲרֵי הָרִאשׁוֹן קַיָּם שֶׁלֹּא כָּתַב הַשֵּׁנִי אֶלָּא מִפְּנֵי הַתּוֹסֶפֶת. וְאִם לֹא הוֹסִיף בִּטֵּל שְׁטָר שֵׁנִי אֶת הָרִאשׁוֹן וְאֵין לוֹ אַחֲרָיוּת אֶלָּא מִזְּמַן הַשֵּׁנִי. לְפִיכָךְ כָּל הַפֵּרוֹת שֶׁאָכַל הַלּוֹקֵחַ מִזְּמַן רִאשׁוֹן עַד זְמַן שֵׁנִי מַחְזִיר אוֹתָם. וְאִם הָיָה עַל אוֹתָהּ שָׂדֶה חֹק לַמֶּלֶךְ בְּכָל שָׁנָה. הַנּוֹתֵן אוֹ הַמּוֹכֵר נוֹתֵן אוֹתוֹ הַחֹק עַד זְמַן הַשְּׁטָר הַשֵּׁנִי:"],"Mishneh Torah, Paschal Offering 7":["רַבִים שֶׁהָיוּ טְמֵאֵי מֵת בְּפֶסַח רִאשׁוֹן אִם הָיוּ מִעוּט הַקָּהָל הֲרֵי אֵלּוּ נִדְחִין לְפֶסַח שֵׁנִי כִּשְׁאָר הַטְּמֵאִים. אֲבָל אִם הָיוּ רֹב הַקָּהָל טְמֵאֵי מֵת אוֹ שֶׁהָיוּ הַכֹּהֲנִים אוֹ כְּלֵי שָׁרֵת טְמֵאִים טֻמְאַת מֵת אֵינָן נִדְחִין. אֶלָּא יַקְרִיבוּ כֻּלָּן הַפֶּסַח בְּטֻמְאָה הַטְּמֵאִים עִם טְהוֹרִים. שֶׁנֶּאֱמַר (במדבר ט ו) \"וַיְהִי אֲנָשִׁים אֲשֶׁר הָיוּ טְמֵאִים לְנֶפֶשׁ אָדָם\" יְחִידִים נִדְחִים וְאֵין הַצִּבּוּר נִדְחֶה. וְדָבָר זֶה בְּטֻמְאַת הַמֵּת בִּלְבַד כְּמוֹ שֶׁבֵּאַרְנוּ בְּבִיאַת הַמִּקְדָּשׁ:","הָיוּ הַקָּהָל מֶחֱצָה טְהוֹרִים וּמֶחֱצָה טְמֵאֵי מֵת. כֻּלָּן עוֹשִׂין בָּרִאשׁוֹן וְהַטְּהוֹרִים עוֹשִׂין לְעַצְמָן בְּטָהֳרָה וְהַטְּמֵאִים עוֹשִׂין לְעַצְמָן בְּטֻמְאָה וְאוֹכְלִין אוֹתוֹ בְּטֻמְאָה. וְאִם הָיוּ טְמֵאֵי הַמֵּת עוֹדְפִין עַל הַטְּהוֹרִים אֲפִלּוּ אֶחָד יַעֲשׂוּ כֻּלָּן בְּטֻמְאָה:","הָיוּ הָאֲנָשִׁים מֶחֱצָה טְמֵאֵי מֵת וּמֶחֱצָה טְהוֹרִים וּבִזְמַן שֶׁאַתָּה מוֹנֶה הַנָּשִׁים בִּכְלַל הָאֲנָשִׁים יִהְיוּ הָרֹב טְהוֹרִים. הַטְּהוֹרִים עוֹשִׂים אֶת הָרִאשׁוֹן וְהַטְּמֵאִין אֵינָן עוֹשִׂין לֹא אֶת הָרִאשׁוֹן וְלֹא אֶת הַשֵּׁנִי. אֵין עוֹשִׂין רִאשׁוֹן מִפְּנֵי שֶׁהֵן מִעוּט. וְאֵין עוֹשִׂין אֶת הַשֵּׁנִי מִפְּנֵי שֶׁהַנָּשִׁים בַּשֵּׁנִי רְשׁוּת וְנִמְצְאוּ הַטְּמֵאִים מֶחֱצָה וְאֵין מֶחֱצָה עוֹשִׂין אֶת הַשֵּׁנִי:","הָיוּ רֹב הַקָּהָל זָבִים וּמְצֹרָעִים וּבוֹעֲלֵי נִדּוֹת וּמִעוּטָן טְמֵאֵי מֵת. אוֹתָן טְמֵאֵי מֵת אֵינָן עוֹשִׂין בָּרִאשׁוֹן לְפִי שֶׁהֵן מִעוּט וְאֵין עוֹשִׂין הַשֵּׁנִי שֶׁאֵין הַיְחִידִים עוֹשִׂין אֶת הַשֵּׁנִי אֶלָּא בִּזְמַן שֶׁעָשׂוּ רֹב הַקָּהָל אֶת הָרִאשׁוֹן. וְכָאן הוֹאִיל וְלֹא עָשָׂה רֹב הַקָּהָל בָּרִאשׁוֹן לֹא יַעֲשׂוּ אֵלּוּ הַמִּעוּט הַטְּמֵאִים לְמֵת אֶת הַשֵּׁנִי:","הָיוּ רֹב הַקָּהָל טְמֵאֵי מֵת וּמִעוּטָן זָבִים וְכַיּוֹצֵא בָּהֶן. טְמֵאֵי מֵת עוֹשִׂין אֶת הָרִאשׁוֹן וְהַזָּבִין וְכַיּוֹצֵא בָּהֶן אֵינָן עוֹשִׂין לֹא אֶת הָרִאשׁוֹן וְלֹא אֶת הַשֵּׁנִי. אֵינָן עוֹשִׂין בָּרִאשׁוֹן שֶׁאֵין נִדְחֵית בְּצִבּוּר אֶלָּא טֻמְאַת הַמֵּת בִּלְבַד. וְאֵינָן עוֹשִׂין בַּשֵּׁנִי שֶׁאֵין עוֹשִׂין פֶּסַח שֵׁנִי אֶלָּא אִם בָּא הָרִאשׁוֹן בְּטָהֳרָה. אֲבָל אִם נַעֲשָׂה רִאשׁוֹן בְּטֻמְאָה אֵין שָׁם פֶּסַח שֵׁנִי:","הָיוּ שְׁלִישׁ הַקָּהָל טְהוֹרִים וּשְׁלִישׁ זָבִים וְכַיּוֹצֵא בָּהֶם וּשְׁלִישׁ טְמֵאֵי מֵת אוֹתָן טְמֵאֵי מֵת אֵין עוֹשִׂין אֶת הָרִאשׁוֹן וְלֹא אֶת הַשֵּׁנִי. אֵינָן עוֹשִׂין רִאשׁוֹן שֶׁהֲרֵי הֵן מֻעָטִים לְגַבֵּי טְהוֹרִים עִם הַזָּבִים. וּבַשֵּׁנִי לֹא יַעֲשׂוּ שֶׁהֲרֵי מִעוּט עָשׂוּ בָּרִאשׁוֹן כְּמוֹ שֶׁבֵּאַרְנוּ. כֵּיצַד מְשַׁעֲרִים הַפֶּסַח לֵידַע אִם רֹב הַקָּהָל טְמֵאִים אוֹ טְהוֹרִים. אֵין מְשַׁעֲרִין בְּכָל הָאוֹכְלִין שֶׁאֶפְשָׁר שֶׁיִּהְיוּ עֶשְׂרִים נִמְנִין עַל פֶּסַח אֶחָד וּמְשַׁלְּחִין אוֹתוֹ בְּיַד אֶחָד לִשְׁחֹט עֲלֵיהֶן אֶלָּא מְשַׁעֲרִין בְּכָל הַנִּכְנָסִים לָעֲזָרָה וְעַד שֶׁהֵן מִבַּחוּץ קֹדֶם שֶׁתִּכָּנֵס כַּת הָרִאשׁוֹנָה מְשַׁעֲרִין אוֹתָן:","יָחִיד שֶׁנִּטְמָא בִּסְפֵק רְשׁוּת הַיָּחִיד כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ הֲרֵי זֶה יִדָּחֶה לְפֶסַח שֵׁנִי כִּשְׁאָר טְמֵאֵי מֵת. וְצִבּוּר שֶׁנִּטְמָא בִּסְפֵק רְשׁוּת הַיָּחִיד יַעֲשׂוּ כֻּלָּן בְּטֻמְאָה:","פֶּסַח שֶׁהִקְרִיבוּהוּ בְּטֻמְאָה הֲרֵי זֶה נֶאֱכָל בְּטֻמְאָה. שֶׁמִּתְּחִלָּתוֹ לֹא בָּא אֶלָּא לַאֲכִילָה. וְאֵינוֹ נֶאֱכָל לְכָל טָמֵא אֶלָּא לִטְמֵאֵי מֵת שֶׁנִּדְחֵית לָהֶם הַטֻּמְאָה הַזֹּאת וּלְכַיּוֹצֵא בָּהֶן מִטְּמֵאֵי מַגַּע טֻמְאוֹת. אֲבָל הַטְּמֵאִים שֶׁהַטֻּמְאָה יוֹצְאָה עֲלֵיהֶן מִגּוּפָן כְּגוֹן זָבִים וְזָבוֹת נִדּוֹת וְיוֹלְדוֹת וּמְצֹרָעִים לֹא יֹאכְלוּ מִמֶּנּוּ וְאִם אָכְלוּ פְּטוּרִין. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁהַנֶּאֱכָל לִטְהוֹרִין חַיָּבִין עָלָיו מִשּׁוּם טֻמְאָה וְהַנֶּאֱכָל לִטְמֵאִין אֵין חַיָּבִין עָלָיו מִשּׁוּם טֻמְאָה. אֲפִלּוּ אָכְלוּ טְמֵאֵי הַמֵּת מֵהָאֵימוּרִים שֶׁלּוֹ פְּטוּרִין. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהַפֶּסַח יֵאָכֵל בְּטֻמְאָה כְּשֶׁנִּטְמְאוּ הַצִּבּוּר קֹדֶם זְרִיקַת הַדָּם. אֲבָל אִם נִטְמְאוּ לְאַחַר זְרִיקַת הַדָּם לֹא יֵאָכֵל:","שְׁחָטוּהוּ בְּטָהֳרָה וְנִטְמְאוּ רֹב הַצִּבּוּר קֹדֶם זְרִיקָה. זוֹרֵק אֶת הַדָּם וְהַפֶּסַח לֹא יֵאָכֵל. גְּזֵרָה שֶׁמָּא יִטָּמְאוּ אַחַר זְרִיקָה בְּשָׁנָה אַחֶרֶת וְיֹאכְלוּהוּ בְּטֻמְאָה. הָיוּ כְּלֵי שָׁרֵת טְמֵאִים בְּשֶׁרֶץ וְכַיּוֹצֵא בּוֹ. הוֹאִיל וְאֵינָן מְטַמְּאִין אֶת הָאָדָם כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ. אַף עַל פִּי שֶׁמְּטַמְּאִין אֶת הַבָּשָׂר לֹא יַעֲשׂוּהוּ אֶלָּא הַטְּהוֹרִים וְיֵאָכֵל אַף עַל פִּי שֶׁהוּא טָמֵא. מוּטָב שֶׁיֵּאָכֵל בְּטֻמְאַת בָּשָׂר שֶׁהִיא בְּלָאו וְלֹא יֹאכְלוּהוּ טְמֵאֵי הַגּוּף שֶׁהֵם בְּכָרֵת כְּמוֹ שֶׁבֵּאַרְנוּ בִּפְסוּלֵי הַמֻּקְדָּשִׁין:"],"Mishneh Torah, Plaintiff and Defendant 3":["אֵין מוֹדֶה בְּמִקְצָת חַיָּב שְׁבוּעָה מִן הַתּוֹרָה עַד שֶׁיּוֹדֶה בִּפְרוּטָה אוֹ יֶתֶר וְיִכְפֹּר בִּשְׁתֵּי מָעִין כֶּסֶף אוֹ יֶתֶר. וְכַמָּה הִיא פְּרוּטָה מִשְׁקַל חֲצִי שְׂעוֹרָה שֶׁל כֶּסֶף נָקִי. וְכַמָּה הֵם שְׁתֵּי מָעִין מִשְׁקַל שְׁתַּיִם וּשְׁלֹשִׁים שְׂעוֹרוֹת כֶּסֶף מְזֻקָּק:","כָּל כֶּסֶף הָאָמוּר בַּתּוֹרָה הוּא שֶׁקֶל הַקֹּדֶשׁ וְהוּא עֶשְׂרִים מָעָה וְכָל כֶּסֶף שֶׁל דִּבְרֵיהֶן מִמַּטְבֵּעַ יְרוּשָׁלַיִם שֶׁהָיָה הַסֶּלַע שֶׁלָּהֶן אֶחָד מִשְּׁמֹנֶה בּוֹ כֶּסֶף וְהַשְּׁאָר נְחשֶׁת כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל הַמָּעָה הִיא הָיְתָה כֶּסֶף נָקִי אֲפִלּוּ בִּירוּשָׁלַיִם וְהִיא כֶּסֶף שֶׁל יְרוּשָׁלַיִם. וּלְפִי שֶׁזֶּה שֶׁהִצְרִיכוּ לִהְיוֹת כְּפִירַת הַטַּעֲנָה שְׁתֵּי כֶּסֶף הִיא מִדִּבְרֵיהֶם עָשׂוּ אוֹתָהּ שְׁתֵּי כֶּסֶף שֶׁל יְרוּשָׁלַיִם שֶׁהֵן שְׁתֵּי מָעִין וְלֹא עָשׂוּ אוֹתָהּ שְׁנֵי שְׁקָלִים בְּשֶׁקֶל הַקֹּדֶשׁ. זֶהוּ הַדָּבָר הַנִּרְאֶה בְּשִׁעוּר כְּפִירַת הַטַּעֲנָה. וְרַבּוֹתַי הוֹרוּ שֶׁכְּפִירַת הַטַּעֲנָה הוּא מִשְׁקַל תְּשַׁע עֶשְׂרֵה שְׂעוֹרוֹת וַחֲצִי שְׂעוֹרָה מִן הַכֶּסֶף. וְיֵשׁ לִי כַּמָּה רְאָיוֹת לִסְתֹּר אוֹתָהּ הַדֶּרֶךְ שֶׁתָּפְסוּ עַד שֶׁיָּצָא לָהֶם זֶה הַחֶשְׁבּוֹן. וְיֵרָאֶה לִי שֶׁהוּא טָעוּת:","שְׁתֵּי מָעִין וּפְרוּטָה יֵשׁ לִי בְּיָדְךָ אֵין לְךָ בְּיָדִי אֶלָּא פְּרוּטָה חַיָּב. אֵין לְךָ בְּיָדִי אֶלָּא שְׁתֵּי פְּרוּטוֹת פָּטוּר מִפְּנֵי שֶׁכָּפַר בְּפָחוֹת מִשְּׁתֵי מָעִין. מָנֶה לִי בְּיָדְךָ אֵין לְךָ בְּיָדִי אֶלָּא חֲצִי פְּרוּטָה פָּטוּר שֶׁכָּל הַמּוֹדֶה בְּפָחוֹת מִפְּרוּטָה כְּאִלּוּ לֹא הוֹדָה בִּכְלוּם:","מֵאָה תְּמָרִים יֵשׁ לִי בְּיָדְךָ אֵין לְךָ בְּיָדִי אֶלָּא תִּשְׁעִים. רוֹאִים אִם הָיוּ שָׁוִין שָׁם הָעֶשֶׂר שֶׁכָּפַר בָּהֶן שְׁתֵּי מָעִין נִשְׁבָּע וְאִם לָאו פָּטוּר. חֲמִשָּׁה אוֹ שִׁשָּׁה אֱגוֹזִים יֵשׁ לִי בְּיָדְךָ אֵין לְךָ [בְּיָדִי] אֶלָּא אֱגוֹז אֶחָד רוֹאִין אִם שָׁוֶה הָאֶחָד פְּרוּטָה נִשְׁבָּע וְאִם לָאו פָּטוּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּכֶסֶף אוֹ בְּמִינֵי סְחוֹרוֹת וּפֵרוֹת וְכַיּוֹצֵא בָּהֶן. אֲבָל הַכֵּלִים אֵין מְשַׁעֲרִין אֶת דְּמֵיהֶן וַאֲפִלּוּ הֵן עֶשֶׂר מְחָטִין בִּפְרוּטָה וּטְעָנוֹ שְׁתֵּי מְחָטִין הוֹדָה בְּאַחַת וְכָפַר בְּאַחַת חַיָּב. שֶׁנֶּאֱמַר (שמות כב ו) \"כֶּסֶף אוֹ כֵלִים\" כָּל הַכֵּלִים כְּכֶסֶף. טְעָנוֹ כֶּסֶף וְכֵלִים וְהוֹדָה בַּכֵּלִים וְכָפַר בַּכֶּסֶף אִם יֵשׁ בַּכְּפִירָה שְׁתֵּי מָעִין חַיָּב וְאִם לָאו פָּטוּר. הוֹדָה בַּכֶּסֶף וְכָפַר בַּכֵּלִים אִם הוֹדָה בִּפְרוּטָה חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הֵעִיד עָלָיו עֵד אֶחָד אֲפִלּוּ לֹא כָּפַר אֶלָּא פְּרוּטָה הֲרֵי זֶה נִשְׁבָּע שֶׁכָּל מִי שֶׁשְּׁנַיִם מְחַיְּבִים אוֹתוֹ מָמוֹן אֶחָד מְחַיְּבוֹ שְׁבוּעָה. כֵּיצַד. פְּרוּטָה אוֹ שְׁוֵה פְּרוּטָה יֵשׁ לִי בְּיָדְךָ אֵין לְךָ בְּיָדִי כְּלוּם וְעֵד אֶחָד מֵעִיד שֶׁיֵּשׁ לוֹ הֲרֵי זֶה נִשְׁבָּע. וְכֵן בִּשְׁבוּעַת הַשּׁוֹמְרִים אֲפִלּוּ הִפְקִיד אֶצְלוֹ פְּרוּטָה אוֹ שְׁוֵה פְּרוּטָה וְטָעַן שֶׁאָבְדָה נִשְׁבָּע. וְכָל פָּחוֹת מִפְּרוּטָה אֵינוֹ מָמוֹן וְאֵין בֵּית דִּין נִזְקָקִין לוֹ. וְכֵן כָּל הַנִּשְׁבָּעִין וְנוֹטְלִין נִשְׁבָּעִין וְנוֹטְלִין מִפְּרוּטָה וָמַעְלָה:","הוֹרוּ רַבּוֹתַי שֶׁהַנִּשְׁבָּעִין וְנוֹטְלִין אֵינָן צְרִיכִין טַעֲנַת שְׁתֵּי כֶּסֶף. וַאֲנִי אוֹמֵר שֶׁצָּרִיךְ הַנִּתְבָּע שֶׁיִּכְפֹּר בִּשְׁתֵּי מָעִין וְאַחַר כָּךְ יִשָּׁבַע הַתּוֹבֵעַ בְּתַקָּנַת חֲכָמִים וְיִטּל. שֶׁהֲרֵי הַנִּשְׁבָּעִין בְּטַעֲנַת סָפֵק צָרִיךְ שֶׁיִּהְיֶה בֵּינֵיהֶם כְּפִירַת שְׁתֵּי מָעִין וְאַחַר כָּךְ יִשָּׁבַע מִסָּפֵק:","אֵין מוֹדֶה בְּמִקְצָת חַיָּב שְׁבוּעָה עַד שֶׁתִּהְיֶה הוֹדָיָה מִמִּין הַטַּעֲנָה. כֵּיצַד. כּוֹר חִטִּים יֵשׁ לִי בְּיָדְךָ אֵין לְךָ בְּיָדִי אֶלָּא לֶתֶךְ חִטִּים חַיָּב. אֲבָל אִם אָמַר לוֹ אֵין לְךָ בְּיָדִי אֶלָּא כּוֹר שֶׁל שְׂעוֹרִים פָּטוּר שֶׁהַמִּין שֶׁטְּעָנוֹ לֹא הוֹדָה לוֹ בּוֹ וְהַמִּין שֶׁהוֹדָה לוֹ בּוֹ לֹא טְעָנוֹ. דִּינַר זָהָב יֵשׁ לִי בְּיָדְךָ פִּקָּדוֹן לֹא הִפְקַדְתָּ אֶצְלִי אֶלָּא דִּינַר כֶּסֶף. מָעָה כֶּסֶף הִפְקַדְתִּי אֶצְלְךָ לֹא הִפְקַדְתָּ אֶצְלִי אֶלָּא פְּרוּטָה פָּטוּר שֶׁטְּעָנוֹ מִין אֶחָד וְהוֹדָה לוֹ בְּמִין אַחֵר. וְכֵן אִם אָמַר לוֹ עֲשָׂרָה דִּינָרִים מִצְרִיּוֹת הִפְקַדְתִּי אֶצְלְךָ לֹא הִפְקַדְתָּ אֶצְלִי אֶלָּא עֲשָׂרָה צוֹרִיּוֹת פָּטוּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מְנוֹרָה גְּדוֹלָה יֵשׁ לִי בְּיָדְךָ אֵין לְךָ בְּיָדִי אֶלָּא מְנוֹרָה קְטַנָּה הֲרֵי זֶה פָּטוּר. אֲבָל אִם טְעָנוֹ מְנוֹרָה בַּת עֶשֶׂר לִיטְרִין וְהוֹדָה לוֹ בִּמְנוֹרָה בַּת חָמֵשׁ לִיטְרִין הֲרֵי זֶה מוֹדֶה בְּמִקְצָת מִפְּנֵי שֶׁיָּכוֹל לְגָרְרָהּ וּלְהַעֲמִידָהּ עַל חָמֵשׁ. וְכֵן אִם טְעָנוֹ אֵזוֹר גָּדוֹל וְאָמַר לוֹ אֵין לְךָ בְּיָדִי אֶלָּא אֵזוֹר קָטָן פָּטוּר. אֲבָל אִם טְעָנוֹ יְרִיעָה בַּת עֶשְׂרִים אַמָּה וְהוֹדָה לוֹ בִּירִיעָה בַּת עֶשֶׂר אַמּוֹת הֲרֵי זֶה נִשְׁבָּע מִפְּנֵי שֶׁיָּכוֹל לְחָתְכָהּ וּלְהַעֲמִידָהּ עַל עֶשֶׂר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כּוֹר חִטִּים יֵשׁ לִי בְּיָדְךָ אֵין לְךָ בְּיָדִי אֶלָּא כּוֹר שְׂעוֹרִים פָּטוּר אַף מִדְּמֵי שְׂעוֹרִים. שֶׁהֲרֵי אוֹמֵר לוֹ אֵין לִי בְּיָדְךָ שְׂעוֹרִים וְנִמְצָא זֶה דּוֹמֶה לְמִי שֶׁאָמַר לַחֲבֵרוֹ בְּבֵית דִּין מָנֶה לְךָ בְּיָדִי וְאוֹמֵר לוֹ הָאַחֵר אֵין לִי בְּיָדְךָ שֶׁאֵין בֵּית דִּין מְחַיְּבִין אוֹתוֹ לִתֵּן לוֹ כְּלוּם. וְאִם תָּפַס הַתּוֹבֵעַ דְּמֵי הַשְּׂעוֹרִים אֵין מוֹצִיאִין מִיָּדוֹ:","הַטּוֹעֵן אֶת חֲבֵרוֹ שְׁנֵי מִינִין וְהוֹדָה בְּאֶחָד מֵהֶן הֲרֵי הַהוֹדָיָה מִמִּין הַטַּעֲנָה וְנִשְׁבָּע. כֵּיצַד. כְּגוֹן כּוֹר חִטִּין וְכוֹר שְׂעוֹרִין יֵשׁ לִי בְּיָדְךָ אֵין לְךָ בְּיָדִי אֶלָּא כּוֹר חִטִּין חַיָּב. הִתְחִיל הַטּוֹעֵן וְאָמַר כּוֹר חִטִּין יֵשׁ לִי בְּיָדְךָ וְקֹדֶם שֶׁיַּשְׁלִים דְּבָרָיו וְאָמַר כּוֹר שְׂעוֹרִים יֵשׁ לִי בְּיָדְךָ אָמַר לוֹ הַנִּטְעָן אֵין לְךָ בְּיָדִי אֶלָּא כּוֹר שְׂעוֹרִים. אִם נִרְאֶה לַדַּיָּנִין שֶׁהַנִּטְעָן הֶעֱרִים חַיָּב שְׁבוּעָה. וְאִם לְפִי תֻּמּוֹ פָּטוּר:","כּוֹר חִטִּין יֵשׁ לִי בְּיָדְךָ אָמַר לוֹ הֵן וְכוֹר שְׂעוֹרִים אָמַר לוֹ אֵין לְךָ בְּיָדִי שְׂעוֹרִין. הֲרֵי זֶה פָּטוּר וְאֵין זֶה מוֹדֶה בְּמִקְצָת עַד שֶׁיֹּאמַר לוֹ בְּבַת אַחַת כּוֹר חִטִּים וְכוֹר שְׂעוֹרִין יֵשׁ לִי בְּיָדְךָ וְיֹאמַר לוֹ הַנִּטְעָן אֵין לְךָ בְּיָדִי אֶלָּא כּוֹר שְׂעוֹרִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מְלֹא עֲשָׂרָה כַּדִּין שֶׁמֶן יֵשׁ לִי בְּיָדְךָ אֵין לְךָ בְּיָדִי אֶלָּא עֲשָׂרָה כַּדִּין בְּלֹא שֶׁמֶן פָּטוּר. שֶׁהֲרֵי טְעָנוֹ שֶׁמֶן וְהוֹדָה לוֹ בָּחֲרָסִים. עֲשָׂרָה כַּדִּין שֶׁמֶן יֵשׁ לִי בְּיָדְךָ אֵין לְךָ בְּיָדִי אֶלָּא עֲשָׂרָה כַּדִּין רֵיקָנִין חַיָּב שְׁבוּעָה שֶׁהֲרֵי טְעָנוֹ הַכַּדִּין וְהַשֶּׁמֶן וְהוֹדָה לוֹ בַּכַּדִּין. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מָנֶה לִי אֶצְלְךָ הַלְוָאָה לֹא הָיוּ דְּבָרִים מֵעוֹלָם וְלֹא לָוִיתִי מִמְּךָ אֲבָל חֲמִשִּׁים דִּינָרִין יֵשׁ לְךָ בְּיָדִי פִּקָּדוֹן אוֹ מִשּׁוּם נֵזֶק וְכַיּוֹצֵא בּוֹ הוֹרוּ רַבּוֹתַי שֶׁזֶּה מוֹדֶה בְּמִקְצָת וְיִשָּׁבַע. שֶׁהֲרֵי טְעָנוֹ שֶׁהוּא חַיָּב לוֹ מֵאָה וְהוֹדָה לוֹ שֶׁהוּא חַיָּב חֲמִשִּׁים וּמַה לִּי נִתְחַיֵּב לוֹ מִשּׁוּם הַלְוָאָה אוֹ מִשּׁוּם פִּקָּדוֹן אוֹ מִשּׁוּם נֵזֶק. וְלָזֶה דַּעְתִּי נוֹטָה:","מָנֶה וּכְלִי יֵשׁ לִי בְּיָדְךָ אֵין לְךָ בְּיָדִי אֶלָּא הַכְּלִי וְהֵא לְךָ. הֲרֵי זֶה פָּטוּר וְנִשְׁבָּע הֶסֵּת שֶׁאֵין לוֹ אֶצְלוֹ אֶלָּא זֶה. אָמַר בַּעַל הַכְּלִי אֵין זֶה הַכְּלִי כּוֹלֵל בִּשְׁבוּעָתוֹ שֶׁזֶּה כֶּלְיוֹ. הוֹדָה הַנִּטְעָן שֶׁאֵין זֶה כֶּלְיוֹ וְנִתְחַלֵּף לוֹ בְּאַחֵר הֲרֵי זֶה חַיָּב שְׁבוּעָה. כָּל מָקוֹם שֶׁנֶּאֱמַר בְּעִנְיָן זֶה פָּטוּר הֲרֵי זֶה פָּטוּר מִשְּׁבוּעַת הַתּוֹרָה וְחַיָּב שְׁבוּעַת הֶסֵּת כְּמוֹ שֶׁבֵּאַרְנוּ כַּמָּה פְּעָמִים:"],"Mishneh Torah, Positive Mitzvot 103":["להיות בית מנוגע מטמא."],"Mishneh Torah, Positive Mitzvot 114":["להיות מעריך אדם נותן דמים הקצובין בפרשה, שנאמר: \"אִישׁ כִּי יַפְלִא נֶדֶר\" (ויקרא כז, ב)."],"Mishneh Torah, Positive Mitzvot 125":["להביא ביכורים לבית הבחירה, שנאמר: \"רֵאשִׁית בִּכּוּרֵי אַדְמָתְךָ\" (שמות כג, יט) (שמות לד, כו)."],"Mishneh Torah, Positive Mitzvot 136":["לקדש שנת יובל בשביתה כשמיטה, שנאמר: \"וקידשתם, את שנת החמישים\" (ויקרא כה,י)."],"Mishneh Torah, Positive Mitzvot 147":["לכסות דם חיה ועוף, שנאמר: \"ושפך, את דמו, וכיסהו, בעפר\" (ויקרא יז,יג)."],"Mishneh Torah, Positive Mitzvot 158":["לאכול מצה בליל זה, שנאמר: \"בערב, תאכלו, מצות\" (שמות יב,יח)."],"Mishneh Torah, Positive Mitzvot 169":["ליטול לולב, שנאמר: \"ולקחתם לכם ביום הראשון, פרי עץ הדר כפות תמרים\" (ויקרא כג,מ)."],"Mishneh Torah, Positive Mitzvot 18":["לִכְתֹּב הַמֶּלֶךְ סֵפֶר תּוֹרָה לְעַצְמוֹ, יָתֵר עַל הָאֶחָד שֶׁלְּכָל אָדָם, עַד שֶׁיִּהְיֶה לוֹ שְׁתֵּי תּוֹרוֹת, שֶׁנֶּאֱמָר: \"וְכָתַב לוֹ אֵת מִשְׁנֵה הַתּוֹרָה הַזֹּאת\" (דברים יז, יח)."],"Mishneh Torah, Positive Mitzvot 190":["לעשות במלחמת הרשות כמשפט הכתוב בתורה, שנאמר: \"כי תקרב אל עיר\" (דברים כ,י)."],"Mishneh Torah, Positive Mitzvot 200":["ליתן שכר שכיר בזמנו, שנאמר: \"ביומו תיתן שכרו\" (דברים כד,טו)."],"Mishneh Torah, Positive Mitzvot 211":["ליראה מאב ואם, שנאמר: \"אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ\" (ויקרא יט, ג)."],"Mishneh Torah, Positive Mitzvot 222":["לגרש בשטר, שנאמר: \"וכתב לה ספר כריתות ונתן בידה\" (דברים כד,א; דברים כד,ג)."],"Mishneh Torah, Positive Mitzvot 233":["לייעד אמה עברייה, שנאמר: \"אשר לו יעדה\" (שמות כא,ח), \"ואם לבנו, ייעדנה\" (שמות כא,ט)."],"Mishneh Torah, Positive Mitzvot 244":["לדון בדין השואל, שנאמר: \"וכי ישאל איש מעם ריעהו\" (שמות כב,יג)."],"Mishneh Torah, Positive Mitzvot 31":["לשלח טמאים ממחנה שכינה שהוא המקדש, שנאמר: \"וִישַׁלְּחוּ מִן הַמַּחֲנֶה כָּל צָרוּעַ וְכָל זָב וְכֹל טָמֵא לָנֶפֶשׁ\" (במדבר ה, ב)."],"Mishneh Torah, Positive Mitzvot 42":["להוסיף קרבן בכל ראש חודש וחודש, שנאמר: \"וּבְרָאשֵׁי חָדְשֵׁיכֶם תַּקְרִיבוּ...\" (במדבר כח, יא)."],"Mishneh Torah, Positive Mitzvot 53":["להיראות ברגלים, שנאמר: \"שָׁלֹשׁ פְּעָמִים בַּשָּׁנָה יֵרָאֶה כָּל זְכוּרְךָ\" (שמות כג יז; שם לג, כג; דברים טז טז."],"Mishneh Torah, Positive Mitzvot 64":["מעשה חטאת, שנאמר: \"זֹאת תּוֹרַת הַחַטָּאת\" (ויקרא ו, יח)."],"Mishneh Torah, Positive Mitzvot 75":["להקריב הזבה קרבן אחר שתטהר, שנאמר: \"ואם טהרה, מזובה\" (ויקרא טו,כח)."],"Mishneh Torah, Positive Mitzvot 86":["לפדות קודשים בעלי מומים ויהיו מותרים באכילה, שנאמר: \"רק בכל אוות נפשך תזבח ואכלת בשר\" (דברים יב,טו); מפי השמועה למדו שאינו מדבר אלא בפסולי המוקדשין שייפדו."],"Mishneh Torah, Positive Mitzvot 97":["להיות שמונה שרצים מטמאין, שנאמר \"וזה לכם הטמא\" (ויקרא יא, כט)."],"Mishneh Torah, Prayer and the Priestly Blessing 4":["חֲמִשָּׁה דְּבָרִים מְעַכְּבִין אֶת הַתְּפִלָּה אַף עַל פִּי שֶׁהִגִּיעַ זְמַנָּה. טָהֳרַת יָדַיִם. וְכִסּוּי הָעֶרְוָה. וְטָהֳרַת מְקוֹם תְּפִלָּה. וּדְבָרִים הַחוֹפְזִים אוֹתוֹ. וְכַוָּנַת הַלֵּב:","טָהֳרַת יָדַיִם כֵּיצַד. רוֹחֵץ יָדָיו בְּמַיִם עַד הַפֶּרֶק וְאַחַר כָּךְ יִתְפַּלֵּל. הָיָה מְהַלֵּךְ בַּדֶּרֶךְ וְהִגִּיעַ זְמַן תְּפִלָּה וְלֹא הָיָה לוֹ מַיִם. אִם הָיָה בֵּינוֹ וּבֵין הַמַּיִם אַרְבָּעָה מִילִין שֶׁהֵם שְׁמוֹנַת אֲלָפִים אַמָּה הוֹלֵךְ עַד מְקוֹם הַמַּיִם וְרוֹחֵץ וְאַחַר כָּךְ יִתְפַּלֵּל. הָיָה בֵּינוֹ וּבֵין הַמַּיִם יוֹתֵר עַל כֵּן מְקַנֵּחַ יָדָיו בִּצְרוֹר אוֹ בְּעָפָר אוֹ בְּקוֹרָה וּמִתְפַּלֵּל:","בַּמֶּה דְּבָרִים אֲמוּרִים לְפָנָיו אֲבָל אִם הָיָה מְקוֹם הַמַּיִם לַאֲחוֹרָיו אֵין מְחַיְּבִין אוֹתוֹ לַחֲזֹר לַאֲחוֹרָיו אֶלָּא עַד מִיל. אֲבָל אִם עָבַר מִן הַמַּיִם יוֹתֵר אֵינוֹ חַיָּב לַחֲזֹר אֶלָּא מְקַנֵּחַ יָדָיו וּמִתְפַּלֵּל. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאֵינוֹ מְטַהֵר לִתְפִלָּה אֶלָּא יָדָיו בִּלְבַד, בִּשְׁאָר תְּפִלּוֹת חוּץ מִתְּפִלַּת שַׁחֲרִית. אֲבָל שַׁחֲרִית רוֹחֵץ פָּנָיו יָדָיו וְרַגְלָיו וְאַחַר כָּךְ יִתְפַּלֵּל. וְאִם הָיָה רָחוֹק מִן הַמַּיִם מְקַנֵּחַ יָדָיו בִּלְבַד וְאַחַר כָּךְ יִתְפַּלֵּל:","כָּל הַטְּמֵאִין רוֹחֲצִין יְדֵיהֶן בִּלְבַד כִּטְהוֹרִין וּמִתְפַּלְּלִים. אַף עַל פִּי שֶׁאֶפְשָׁר לָהֶם לִטְבּל וְלַעֲלוֹת מִטֻּמְאָתָן אֵין הַטְּבִילָה מְעַכֶּבֶת. וּכְבָר בֵּאַרְנוּ שֶׁעֶזְרָא תִּקֵּן שֶׁלֹּא יִקְרָא בַּעַל קֶרִי בִּלְבַד בְּדִבְרֵי תּוֹרָה עַד שֶׁיִּטְבּל. וּבֵית דִּין שֶׁעָמְדוּ אַחַר כֵּן הִתְקִינוּ אַף לִתְפִלָּה שֶׁלֹּא יִתְפַּלֵּל בַּעַל קֶרִי בִּלְבַד עַד שֶׁיִּטְבּל. וְלֹא מִפְּנֵי טֻמְאָה וְטָהֳרָה נָגְעוּ בָּהּ אֶלָּא כְּדֵי שֶׁלֹּא יִהְיוּ תַּלְמִידֵי חֲכָמִים מְצוּיִים אֵצֶל נְשׁוֹתֵיהֶן כְּתַרְנְגוֹלִים. וּמִפְּנֵי זֶה תִּקְּנוּ טְבִילָה לְבַעַל קֶרִי לְבַדּוֹ וְהוֹצִיאוּהוּ מִכְּלַל הַטְּמֵאִין:","לְפִיכָךְ הָיוּ אוֹמְרִין בִּזְמַן תַּקָּנָה זוֹ שֶׁאֲפִלּוּ זָב שֶׁרָאָה קֶרִי וְנִדָּה שֶׁפָּלְטָה שִׁכְבַת זֶרַע וּמְשַׁמֶּשֶׁת שֶׁרָאֲתָה דַּם נִדָּה צְרִיכִין טְבִילָה לִקְרִיאַת שְׁמַע וְכֵן לִתְפִלָּה מִפְּנֵי הַקֶּרִי אַף עַל פִּי שֶׁהֵם טְמֵאִין. וְכֵן הַדִּין נוֹתֵן שֶׁאֵין טְבִילָה זוֹ מִפְּנֵי טָהֳרָה אֶלָּא מִפְּנֵי הַגְּזֵרָה שֶׁלֹּא יִהְיוּ מְצוּיִין אֵצֶל נְשׁוֹתֵיהֶן תָּמִיד. וּכְבָר בָּטְלָה גַּם תַּקָּנָה זוֹ שֶׁל תְּפִלָּה לְפִי שֶׁלֹּא פָּשְׁטָה בְּכָל יִשְׂרָאֵל וְלֹא הָיָה כֹּחַ בַּצִּבּוּר לַעֲמֹד בָּהּ:","מִנְהָג פָּשׁוּט בְּשִׁנְעָר וּבִסְפָרַד שֶׁאֵין בַּעַל קֶרִי מִתְפַּלֵּל עַד שֶׁרוֹחֵץ כָּל בְּשָׂרוֹ בְּמַיִם מִשּׁוּם (עמוס ד יב) ״הִכּוֹן לִקְרַאת אֱלֹהֶיךָ יִשְׂרָאֵל״. בַּמֶּה דְּבָרִים אֲמוּרִים בְּבָרִיא אוֹ בְּחוֹלֶה שֶׁבָּעַל. אֲבָל חוֹלֶה שֶׁרָאָה קֶרִי לְאָנְסוֹ פָּטוּר מִן הָרְחִיצָה וְאֵין בָּזֶה מִנְהָג. וְכֵן זָב שֶׁרָאָה קֶרִי וְנִדָּה שֶׁפָּלְטָה שִׁכְבַת זֶרַע אֵין בָּהֶן מִנְהָג אֶלָּא מְקַנְּחִין עַצְמָן וְרוֹחֲצִין יְדֵיהֶן וּמִתְפַּלְּלִין:","כִּסּוּי הָעֶרְוָה כֵּיצַד. אַף עַל פִּי שֶׁכִּסָּה עֶרְוָתוֹ כְּדֶרֶךְ שֶׁמְּכַסִּין לִקְרִיאַת שְׁמַע לֹא יִתְפַּלֵּל עַד שֶׁיְּכַסֶּה אֶת לִבּוֹ. וְאִם לֹא כִּסָּה לִבּוֹ אוֹ שֶׁנֶּאֱנַס וְאֵין לוֹ בְּמָה יְכַסֶּה הוֹאִיל וְכִסָּה עֶרְוָתוֹ וְהִתְפַּלֵּל יָצָא. וּלְכַתְּחִלָּה לֹא יַעֲשֶׂה:","טָהֳרַת מְקוֹם הַתְּפִלָּה כֵּיצַד. לֹא יִתְפַּלֵּל בִּמְקוֹם הַטִּנֹּפֶת וְלֹא בַּמֶּרְחָץ וְלֹא בְּבֵית הַכִּסֵּא וְלֹא בָּאַשְׁפָּה וְלֹא בְּמָקוֹם שֶׁאֵינוֹ בְּחֶזְקַת טָהֳרָה עַד שֶׁיִּבְדְּקֶנּוּ. כְּלָלוֹ שֶׁל דָּבָר כָּל מָקוֹם שֶׁאֵין קוֹרִין בּוֹ קְרִיאַת שְׁמַע אֵין מִתְפַּלְּלִין בּוֹ. וּכְשֵׁם שֶׁמַּרְחִיקִין מִצּוֹאָה וּמִמֵּי רַגְלַיִם וְרֵיחַ רַע וּמִן הַמֵּת וּמֵרְאִיַּת הָעֶרְוָה לִקְרִיאַת שְׁמַע כָּךְ מַרְחִיקִין לִתְפִלָּה:","הַמִּתְפַּלֵּל וּמָצָא צוֹאָה בִּמְקוֹמוֹ הוֹאִיל וְחָטָא מִפְּנֵי שֶׁלֹּא בָּדַק עַד שֶׁלֹּא הִתְפַּלֵּל חוֹזֵר וּמִתְפַּלֵּל בְּמָקוֹם טָהוֹר. הָיָה עוֹמֵד בִּתְפִלָּה וּמָצָא צוֹאָה כְּנֶגְדּוֹ אִם יָכוֹל לְהַלֵּךְ לְפָנָיו כְּדֵי שֶׁיִּזְרְקֶנָּה לְאַחֲרָיו אַרְבַּע אַמּוֹת יְהַלֵּךְ וְאִם לָאו יְסַלְּקֶנָּה לַצְּדָדִין. וְאִם אֵינוֹ יָכוֹל יַפְסִיק. גְּדוֹלֵי הַחֲכָמִים לֹא הָיוּ מִתְפַּלְּלִים בְּבַיִת שֶׁיֵּשׁ בּוֹ שֵׁכָר וְלֹא בְּבַיִת שֶׁיֵּשׁ בּוֹ מוּרְיָיס בְּעֵת עִפּוּשׁוֹ מִפְּנֵי שֶׁרֵיחוֹ רַע אַף עַל פִּי שֶׁהַמָּקוֹם טָהוֹר:","דְּבָרִים הַחוֹפְזִים אוֹתוֹ כֵּיצַד. אִם הָיָה צָרִיךְ לִנְקָבָיו לֹא יִתְפַּלֵּל. וְכָל הַצָּרִיךְ לִנְקָבָיו וְהִתְפַּלֵּל תְּפִלָּתוֹ תּוֹעֵבָה וְחוֹזֵר וּמִתְפַּלֵּל אַחַר שֶׁיַּעֲשֶׂה צְרָכָיו. וְאִם יָכוֹל לְהַעֲמִיד עַצְמוֹ כְּדֵי פַּרְסָה תְּפִלָּתוֹ תְּפִלָּה. וְאַף עַל פִּי כֵן לְכַתְּחִלָּה לֹא יִתְפַּלֵּל עַד שֶׁיִּבְדֹּק עַצְמוֹ יָפֶה יָפֶה וְיִבְדֹק נְקָבָיו וְיָסִיר כִּיחוֹ וְנִיעוֹ וְכָל הַדָּבָר הַטּוֹרְדוֹ וְאַחַר כָּךְ יִתְפַּלֵּל:","מִי שֶׁגִּהֵק וּפִהֵק וְנִתְעַטֵּשׁ בִּתְפִלָּתוֹ אִם לִרְצוֹנוֹ הֲרֵי זֶה מְגֻנֶּה. וְאִם בָּדַק גּוּפוֹ קֹדֶם שֶׁיִּתְפַּלֵּל וּבָא לְאָנְסוֹ אֵין בְּכָךְ כְּלוּם. נִזְדַּמֵּן לוֹ רֹק בִּתְפִלָּתוֹ מַבְלִיעוֹ בְּטַלִּיתוֹ אוֹ בְּבִגְדוֹ. וְאִם הָיָה מִצְטַעֵר בְּכָךְ זוֹרְקוֹ בְּיָדוֹ לַאֲחוֹרָיו כְּדֵי שֶׁלֹּא יִצְטַעֵר בַּתְּפִלָּה וְנִמְצָא טָרוּד. יָצָא מִמֶּנּוּ רוּחַ מִלְּמַטָּה כְּשֶׁהוּא עוֹמֵד בִּתְפִלָּה שֶׁלֹּא לְדַעְתּוֹ שׁוֹהֶה עַד שֶׁתִּכְלֶה הָרוּחַ וְחוֹזֵר לִתְפִלָּתוֹ:","בִּקֵּשׁ לְהוֹצִיא רוּחַ מִלְּמַטָּה וְנִצְטַעֵר הַרְבֵּה וְאֵינוֹ יָכוֹל לְהַעֲמִיד עַצְמוֹ מְהַלֵּךְ לְאַחֲרָיו אַרְבַּע אַמּוֹת וּמַמְתִּין עַד שֶׁתִּכְלֶה הָרוּחַ. וְאוֹמֵר רִבּוֹן כָּל הָעוֹלָמִים יְצַרְתָּנוּ נְקָבִים נְקָבִים חֲלוּלִים חֲלוּלִים גָּלוּי וְיָדוּעַ לְפָנֶיךָ חֶרְפָּתֵנוּ וּכְלִמָּתֵנוּ חֶרְפָּה וּכְלִמָּה בְּחַיֵּינוּ תּוֹלֵעָה וְרִמָּה בְּמִיתָתֵנוּ וְחוֹזֵר לִמְקוֹמוֹ וּמִתְפַּלֵּל:","הָיָה עוֹמֵד בִּתְפִלָּה וְנָטְפוּ מֵי רַגְלָיו עַל בִּרְכָּיו מַמְתִּין עַד שֶׁיִּכְלוּ הַמַּיִם וְחוֹזֵר לַמָּקוֹם שֶׁפָּסַק. וְאִם שָׁהָה כְּדֵי לִגְמֹר אֶת הַתְּפִלָּה חוֹזֵר לָרֹאשׁ:","וְכֵן הַמַּשְׁתִּין מַיִם שׁוֹהֶה כְּדֵי הִלּוּךְ ד׳‎ אַמּוֹת וְאַחַר כָּךְ יִתְפַּלֵּל. וּמִשֶּׁהִתְפַּלֵּל שׁוֹהֶה אַחַר תְּפִלָּתוֹ כְּדֵי הִלּוּךְ אַרְבַּע אַמּוֹת וְאַחַר כָּךְ מַשְׁתִּין כְּדֵי שֶׁיִּפְסֹק דִּבְרֵי הַתְּפִלָּה מִפִּיו:","כַּוָּנַת הַלֵּב כֵּיצַד. כָּל תְּפִלָּה שֶׁאֵינָהּ בְּכַוָּנָה אֵינָהּ תְּפִלָּה. וְאִם הִתְפַּלֵּל בְּלֹא כַּוָּנָה חוֹזֵר וּמִתְפַּלֵּל בְּכַוָּנָה. מָצָא דַּעְתּוֹ מְשֻׁבֶּשֶׁת וְלִבּוֹ טָרוּד אָסוּר לוֹ לְהִתְפַּלֵּל עַד שֶׁתִּתְיַשֵּׁב דַּעְתּוֹ. לְפִיכָךְ הַבָּא מִן הַדֶּרֶךְ וְהוּא עָיֵף אוֹ מֵצֵר אָסוּר לוֹ לְהִתְפַּלֵּל עַד שֶׁתִּתְיַשֵּׁב דַּעְתּוֹ. אָמְרוּ חֲכָמִים יִשְׁהֶה שְׁלֹשָׁה יָמִים עַד שֶׁיָּנוּחַ וְתִתְקָרֵר דַּעְתּוֹ וְאַחַר כָּךְ יִתְפַּלֵּל:","כֵּיצַד הִיא הַכַּוָּנָה. שֶׁיְּפַנֶּה אֶת לִבּוֹ מִכָּל הַמַּחֲשָׁבוֹת וְיִרְאֶה עַצְמוֹ כְּאִלּוּ הוּא עוֹמֵד לִפְנֵי הַשְּׁכִינָה. לְפִיכָךְ צָרִיךְ לֵישֵׁב מְעַט קֹדֶם הַתְּפִלָּה כְּדֵי לְכַוֵּן אֶת לִבּוֹ וְאַחַר כָּךְ יִתְפַּלֵּל בְּנַחַת וּבְתַחֲנוּנִים וְלֹא יַעֲשֶׂה תְּפִלָּתוֹ כְּמִי שֶׁהָיָה נוֹשֵׂא מַשּׂאוֹי וּמַשְׁלִיכוֹ וְהוֹלֵךְ לוֹ. לְפִיכָךְ צָרִיךְ לֵישֵׁב מְעַט אַחַר הַתְּפִלָּה וְאַחַר כָּךְ יִפָּטֵר. חֲסִידִים הָרִאשׁוֹנִים הָיוּ שׁוֹהִין שָׁעָה אַחַת קֹדֶם תְּפִלָּה וְשָׁעָה אַחַת לְאַחַר תְּפִלָּה וּמַאֲרִיכִין בִּתְפִלָּה שָׁעָה:","שִׁכּוֹר אַל יִתְפַּלֵּל מִפְּנֵי שֶׁאֵין לוֹ כַּוָּנָה. וְאִם הִתְפַּלֵּל תְּפִלָּתוֹ תּוֹעֵבָה. לְפִיכָךְ חוֹזֵר וּמִתְפַּלֵּל כְּשֶׁיִּתְרוֹקֵן מִשִּׁכְרוּתוֹ. שָׁתוּי אַל יִתְפַּלֵּל וְאִם הִתְפַּלֵּל תְּפִלָּתוֹ תְּפִלָּה. אֵי זֶה שִׁכּוֹר זֶה שֶׁאֵינוֹ יָכוֹל לְדַבֵּר לִפְנֵי הַמֶּלֶךְ. שָׁתוּי יָכוֹל לְדַבֵּר בִּפְנֵי הַמֶּלֶךְ וְאֵינוֹ מִשְׁתַּבֵּשׁ. אַף עַל פִּי כֵן הוֹאִיל וְשָׁתָה רְבִיעִית יַיִן לֹא יִתְפַּלֵּל עַד שֶׁיָּסִיר יֵינוֹ מֵעָלָיו","וְכֵן אֵין עוֹמְדִין לְהִתְפַּלֵּל לֹא מִתּוֹךְ שְׂחוֹק וְלֹא מִתּוֹךְ קַלּוּת רֹאשׁ וְלֹא מִתּוֹךְ שִׂיחָה וְלֹא מִתּוֹךְ מְרִיבָה וְלֹא מִתּוֹךְ כַּעַס אֶלָּא מִתּוֹךְ דִּבְרֵי תּוֹרָה. וְלֹא מִתּוֹךְ דִּין וַהֲלָכָה אַף עַל פִּי שֶׁהֵם דִּבְרֵי תּוֹרָה כְּדֵי שֶׁלֹּא יְהֵא לִבּוֹ טָרוּד בַּהֲלָכָה. אֶלָּא מִתּוֹךְ דִּבְרֵי תּוֹרָה שֶׁאֵין בָּהּ עִיּוּן כְּגוֹן הֲלָכוֹת פְּסוּקוֹת:","תְּפִלּוֹת הַפְּרָקִים כְּגוֹן תְּפִלַּת מוּסָף רֹאשׁ חֹדֶשׁ וּתְפִלַּת מוֹעֲדוֹת צָרִיךְ לְהַסְדִּיר תְּפִלָּתוֹ וְאַחַר כָּךְ עוֹמֵד וּמִתְפַּלֵּל כְּדֵי שֶׁלֹּא יִכָּשֵׁל בָּהּ. הָיָה מְהַלֵּךְ בִּמְקוֹם סַכָּנָה כְּגוֹן מְקוֹם גְּדוּדֵי חַיּוֹת וְלִסְטִים וְהִגִּיעַ זְמַן תְּפִלָּה מִתְפַּלֵּל בְּרָכָה אַחַת. וְזוֹ הִיא. צָרְכֵי עַמְּךָ יִשְׂרָאֵל מְרֻבִּים וְדַעְתָּם קְצָרָה. יְהִי רָצוֹן מִלְּפָנֶיךָ ה׳‎ אֱלֹהֵינוּ שֶׁתִּתֵּן לְכָל אֶחָד וְאֶחָד כְּדֵי פַּרְנָסָתוֹ וּלְכָל גְּוִיָּה וּגְוִיָּה דֵּי מַחְסוֹרָהּ וְהַטּוֹב בְּעֵינֶיךָ עֲשֵׂה בָּרוּךְ אַתָּה יְיָ׳‎ שׁוֹמֵעַ תְּפִלָּה. וּמִתְפַּלֵּל אוֹתָהּ בַּדֶּרֶךְ כְּשֶׁהוּא מְהַלֵּךְ, וְאִם יָכוֹל לַעֲמֹד עוֹמֵד. וּכְשֶׁהוּא מַגִּיעַ לְיִשּׁוּב וְתִתְקָרֵר דַּעְתּוֹ חוֹזֵר וּמִתְפַּלֵּל תְּפִלָּה כְּתַקָּנָתָהּ תְּשַׁע עֶשְׂרֵה בְּרָכוֹת:"],"Mishneh Torah, Rebels 3":["מִי שֶׁאֵינוֹ מוֹדֶה בַּתּוֹרָה שֶׁבְּעַל פֶּה אֵינוֹ זָקֵן מַמְרֵא הָאָמוּר בַּתּוֹרָה. אֶלָּא הֲרֵי זֶה בִּכְלַל הָאֶפִּיקוֹרוֹסִין [וּמִיתָתוֹ בְּכָל אָדָם]:","מֵאַחַר שֶׁנִּתְפַּרְסֵם שֶׁהוּא כּוֹפֵר בַּתּוֹרָה שֶׁבְּעַל פֶּה [מוֹרִידִין אוֹתוֹ] וְלֹא מַעֲלִין וַהֲרֵי הוּא כִּשְׁאָר כָּל הָאֶפִּיקוֹרוֹסִין וְהָאוֹמְרִין אֵין תּוֹרָה מִן הַשָּׁמַיִם וְהַמּוֹסְרִין וְהַמּוּמָרִין. שֶׁכָּל אֵלּוּ אֵינָם בִּכְלַל יִשְׂרָאֵל וְאֵין צָרִיךְ לֹא לְעֵדִים וְלֹא הַתְרָאָה וְלֹא דַּיָּנִים [אֶלָּא כָּל הַהוֹרֵג אֶחָד מֵהֶן עָשָׂה מִצְוָה גְּדוֹלָה וְהֵסִיר הַמִּכְשׁוֹל]:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּאִישׁ שֶׁכָּפַר בַּתּוֹרָה שֶׁבְּעַל פֶּה בְּמַחֲשַׁבְתּוֹ וּבִדְבָרִים שֶׁנִּרְאוּ לוֹ. וְהָלַךְ אַחַר דַּעְתּוֹ הַקַּלָּה וְאַחַר שְׁרִירוּת לִבּוֹ וְכוֹפֵר בַּתּוֹרָה שֶׁבְּעַל פֶּה תְּחִלָּה כְּצָדוֹק וּבַיְתּוֹס וְכֵן כָּל הַתּוֹעִים אַחֲרָיו. אֲבָל בְּנֵי הַתּוֹעִים הָאֵלֶּה וּבְנֵי בְּנֵיהֶם שֶׁהִדִּיחוּ אוֹתָם אֲבוֹתָם וְנוֹלְדוּ בֵּין הַקָּרָאִים וְגִדְּלוּ אוֹתָם עַל דַּעְתָּם. הֲרֵי הוּא כְּתִינוֹק שֶׁנִּשְׁבָּה בֵּינֵיהֶם וְגִדְּלוּהוּ וְאֵינוֹ זָרִיז לֶאֱחֹז בְּדַרְכֵי הַמִּצְוֹת שֶׁהֲרֵי הוּא כְּאָנוּס וְאַף עַל פִּי שֶׁשָּׁמַע אַחַר כָּךְ [שֶׁהוּא יְהוּדִי וְרָאָה הַיְהוּדִים וְדָתָם הֲרֵי הוּא כְּאָנוּס שֶׁהֲרֵי גִּדְּלוּהוּ עַל טָעוּתָם] כָּךְ אֵלּוּ שֶׁאָמַרְנוּ הָאוֹחֲזִים בְּדַרְכֵי אֲבוֹתָם הַקָּרָאִים שֶׁטָּעוּ. לְפִיכָךְ רָאוּי לְהַחְזִירָן בִּתְשׁוּבָה וּלְמָשְׁכָם בְּדִבְרֵי שָׁלוֹם עַד שֶׁיַּחְזְרוּ לְאֵיתָן הַתּוֹרָה:","אֲבָל זָקֵן מַמְרֵא הָאָמוּר בַּתּוֹרָה הוּא חָכָם אֶחָד מֵחַכְמֵי יִשְׂרָאֵל שֶׁיֵּשׁ בְּיָדוֹ קַבָּלָה וְדָן וּמוֹרֶה בְּדִבְרֵי תּוֹרָה כְּמוֹ שֶׁיָּדוּנוּ וְיוֹרוּ כָּל חַכְמֵי יִשְׂרָאֵל. שֶׁבָּאת לוֹ מַחְלֹקֶת בְּדִין מִן הַדִּינִים עִם בֵּית דִּין הַגָּדוֹל וְלֹא חָזַר לְדִבְרֵיהֶם אֶלָּא חָלַק עֲלֵיהֶם וְהוֹרָה לַעֲשׂוֹת שֶׁלֹּא כְּהוֹרָאָתָן. גָּזְרָה עָלָיו תּוֹרָה מִיתָה וּמִתְוַדֶּה וְיֵשׁ לוֹ חֵלֶק לָעוֹלָם הַבָּא. אַף עַל פִּי שֶׁהוּא דָּן וְהֵן דָּנִים הוּא קִבֵּל וְהֵם קִבְּלוּ הֲרֵי הַתּוֹרָה חָלְקָה לָהֶם כָּבוֹד. וְאִם רָצוּ בֵּית דִּין לִמְחל עַל כְּבוֹדָן וּלְהַנִּיחוֹ אֵינָן יְכוֹלִין כְּדֵי שֶׁלֹּא יַרְבּוּ מַחְלֹקֶת בְּיִשְׂרָאֵל:","אֵין זָקֵן מַמְרֵא חַיָּב מִיתָה עַד שֶׁיְּהֵא חָכָם שֶׁהִגִּיעַ לְהוֹרָאָה סָמוּךְ בַּסַּנְהֶדְרִין וְיַחְלֹק עַל בֵּית דִּין בְּדָבָר שֶׁזְּדוֹנוֹ כָּרֵת וְשִׁגְגָתוֹ חַטָּאת אוֹ בִּתְפִלִּין וְיוֹרֶה לַעֲשׂוֹת כְּהוֹרָאָתוֹ. אוֹ יַעֲשֶׂה הוּא עַל פִּי הוֹרָאָתוֹ וְיַחְלֹק עֲלֵיהֶן וְהֵן יוֹשְׁבִין בְּלִשְׁכַּת הַגָּזִית. אֲבָל אִם הָיָה תַּלְמִיד שֶׁלֹּא הִגִּיעַ לְהוֹרָאָה וְהוֹרָה לַעֲשׂוֹת פָּטוּר. שֶׁנֶּאֱמַר (דברים יז ח) \"כִּי יִפָּלֵא מִמְּךָ דָבָר לַמִּשְׁפָּט\" מִי שֶׁלֹּא יִפָּלֵא מִמֶּנּוּ אֶלָּא דָּבָר מֻפְלָא:","הָיָה חָכָם מֻפְלָא שֶׁל בֵּית דִּין וְחָלַק וְשָׁנָה וְלִמֵּד לַאֲחֵרִים כִּדְבָרָיו אֲבָל לֹא הוֹרָה לַעֲשׂוֹת פָּטוּר. שֶׁנֶּאֱמַר (דברים יז יב) \"וְהָאִישׁ אֲשֶׁר יַעֲשֶׂה בְזָדוֹן\" לֹא שֶׁיֹּאמַר בְּזָדוֹן אֶלָּא יוֹרֶה לַעֲשׂוֹת אוֹ יַעֲשֶׂה הוּא בְּעַצְמוֹ:","מְצָאָן חוּץ לִמְקוֹמָן וְהִמְרָה עֲלֵיהֶן פָּטוּר. שֶׁנֶּאֱמַר (דברים יז ח) \"וְקַמְתָּ וְעָלִיתָ אֶל הַמָּקוֹם\" מְלַמֵּד שֶׁהַמָּקוֹם גּוֹרֵם לוֹ מִיתָה. וְכָל אֵלּוּ וְכַיּוֹצֵא בָּהֶן שֶׁהֵן פְּטוּרִין מִן הַמִּיתָה יֵשׁ לְבֵית דִּין הַגָּדוֹל לְנַדּוֹתָם וּלְהַפְרִישָׁן וּלְהַכּוֹתָן וּלְמָנְעָן מִלְּלַמֵּד כְּפִי מַה שֶּׁיֵּרָאֶה לָהֶן שֶׁהַדָּבָר צָרִיךְ לְכָךְ:","וְכֵיצַד דָּנִין זָקֵן מַמְרֵא. בְּעֵת שֶׁיִּפָּלֵא דָּבָר וְיוֹרֶה בּוֹ חָכָם הַמַּגִּיעַ לְהוֹרָאָה בֵּין בְּדָבָר שֶׁיֵּרָאֶה בְּעֵינָיו בֵּין בְּדָבָר שֶׁקִּבֵּל מֵרַבּוֹתָיו. הֲרֵי הוּא וְהַחוֹלְקִין עִמּוֹ עוֹלִין לִירוּשָׁלַיִם וּבָאִין לְבֵית דִּין שֶׁעַל פֶּתַח הַר הַבַּיִת. אוֹמְרִים לָהֶן בֵּית דִּין כָּךְ הוּא הַדִּין. אִם שָׁמַע וְקִבֵּל מוּטָב וְאִם לָאו בָּאִין כֻּלָּן לְבֵית דִּין שֶׁעַל פֶּתַח הָעֲזָרָה וְאוֹמְרִים לָהֶם גַּם הֵם כָּךְ הוּא הַדִּין. אִם קִבְּלוּ יֵלְכוּ לָהֶן וְאִם לָאו כֻּלָּן בָּאִין לְבֵית דִּין הַגָּדוֹל לְלִשְׁכַּת הַגָּזִית שֶׁמִּשָּׁם תּוֹרָה יוֹצֵאת לְכָל יִשְׂרָאֵל שֶׁנֶּאֱמַר (דברים יז י) \"מִן הַמָּקוֹם הַהוּא אֲשֶׁר יִבְחַר ה'\". וּבֵית דִּין אוֹמֵר לָהֶם כָּךְ הוּא הַדִּין וְיוֹצְאִין כֻּלָּן. חָזַר זֶה הֶחָכָם לְעִירוֹ וְשָׁנָה וְלִמֵּד כְּדֶרֶךְ שֶׁהוּא לָמוּד הֲרֵי זֶה פָּטוּר. הוֹרָה לַעֲשׂוֹת אוֹ שֶׁעָשָׂה כְּהוֹרָאָתוֹ חַיָּב מִיתָה וְאֵינוֹ צָרִיךְ הַתְרָאָה. אֲפִלּוּ נָתַן טַעַם לִדְבָרָיו אֵין שׁוֹמְעִין לוֹ אֶלָּא כֵּיוָן שֶׁבָּאוּ עֵדִים שֶׁעָשָׂה כְּהוֹרָאָתוֹ אוֹ שֶׁהוֹרָה לַאֲחֵרִים לַעֲשׂוֹת גּוֹמְרִין דִּינוֹ לְמִיתָה בְּבֵית דִּין שֶׁבְּעִירוֹ. וְתוֹפְסִין אוֹתוֹ וּמַעֲלִין אוֹתוֹ מִשָּׁם לִירוּשָׁלַיִם. וְאֵין מְמִיתִין אוֹתוֹ בְּבֵית דִּין שֶׁבְּעִירוֹ וְלֹא בְּבֵית דִּין הַגָּדוֹל שֶׁיָּצָא חוּץ לִירוּשָׁלַיִם אֶלָּא מַעֲלִין אוֹתוֹ לְבֵית דִּין הַגָּדוֹל שֶׁבִּירוּשָׁלַיִם. וְעַד הָרֶגֶל מְשַׁמְּרִין אוֹתוֹ וְחוֹנְקִין אוֹתוֹ בָּרֶגֶל. שֶׁנֶּאֱמַר (דברים יג יב) \"וְכָל יִשְׂרָאֵל יִשְׁמְעוּ וְיִרָאוּ\" מִכְּלָל שֶׁצָּרִיךְ הַכְרָזָה. וְאַרְבָּעָה צְרִיכִין הַכְרָזָה. זָקֵן מַמְרֵא. וְעֵדִים זוֹמְמִין. וְהַמֵּסִית. וּבֵן סוֹרֵר וּמוֹרֶה. שֶׁהֲרֵי בְּכֻלָּן נֶאֱמַר יִשְׁמְעוּ וְיִרָאוּ:"],"Mishneh Torah, Red Heifer 2":["מַעֲלוֹת יְתֵרוֹת עָשׂוּ בְּטָהֳרַת פָּרָה אֲדֻמָּה וְהַרְחָקוֹת גְּדוֹלוֹת הִרְחִיקוּ מִטֻּמְאַת הַמֵּת בְּכָל מַעֲשֶׂיהָ. מִפְּנֵי שֶׁהִיא כְּשֵׁרָה בִּטְבוּלֵי יוֹם חָשׁוּ שֶׁמָּא יָבוֹאוּ לְזַלְזֵל בָּהּ. וּמִפְּנֵי זֶה כְּשֶׁמַּפְרִישִׁין הַכֹּהֵן הַשּׂוֹרֵף אוֹתָהּ מַפְרִישִׁין אוֹתוֹ לְלִשְׁכָּה מוּכֶנֶת בָּעֲזָרָה. וּבֵית אֶבֶן הָיְתָה נִקְרֵאת מִפְּנֵי שֶׁכָּל כֵּלֶיהָ כְּלֵי אֲבָנִים שֶׁאֵין מְקַבְּלִין טֻמְאָה. וּבִכְלֵי הָאֶבֶן הָיָה מִשְׁתַּמֵּשׁ כָּל שִׁבְעַת יְמֵי הַהַפְרָשָׁה. וְלֹא הָיוּ נוֹגְעִין בּוֹ אֶחָיו הַכֹּהֲנִים כְּדֵי לְהַרְבּוֹת בְּטָהֳרָתוֹ:","שִׁבְעַת יָמִים קדֶם שְׂרֵפַת הַפָּרָה מַפְרִישִׁין כֹּהֵן הַשּׂוֹרֵף אוֹתָהּ מִבֵּיתוֹ. כְּשֵׁם שֶׁמַּפְרִישִׁין כֹּהֵן גָּדוֹל לַעֲבוֹדַת יוֹם הַכִּפּוּרִים. וְדָבָר זֶה קַבָּלָה מִמּשֶׁה רַבֵּנוּ. וְכֵן מַפְרִישִׁין אוֹתוֹ מֵאִשְׁתּוֹ שֶׁמָּא תִּמָּצֵא נִדָּה וְיִהְיֶה טָמֵא שִׁבְעַת יָמִים:","הַלִּשְׁכָּה שֶׁהָיָה יוֹשֵׁב בָּהּ כָּל שִׁבְעָה צְפוֹנִית מִזְרָחִית הָיְתָה. כְּדֵי לְהַזְכִּירוֹ שֶׁהִיא כְּחַטָּאת הַנִּשְׁחֶטֶת בַּצָּפוֹן אַף עַל פִּי שֶׁהִיא נִשְׁחֶטֶת בַּחוּץ:","כָּל יוֹם וְיוֹם מִשִּׁבְעַת יְמֵי הַהַפְרָשָׁה מַזִּין עָלָיו מֵי חַטָּאת. שֶׁמָּא נִטְמָא לְמֵת וְהוּא לֹא יָדַע. חוּץ מִיּוֹם רְבִיעִי לְהַפְרָשָׁה שֶׁאֵין צָרִיךְ הַזָּאָה לְפִי שֶׁאִי אֶפְשָׁר שֶׁלֹּא יִהְיֶה לֹא שְׁלִישִׁי לְטֻמְאָתוֹ וְלֹא שְׁבִיעִי. שֶׁאֵין הַזָּאָה בַּשְּׁבִיעִי עוֹלָה מִשּׁוּם הַזָּאַת שְׁבִיעִי עַד שֶׁיַּזֶּה בַּשְּׁלִישִׁי מִלְּפָנֶיהָ. וּמִן הַדִּין הָיָה שֶׁאֵין צָרִיךְ הַזָּאָה אֶלָּא בִּשְׁלִישִׁי וּשְׁבִיעִי לְהַפְרָשָׁה בִּלְבַד וְזֶה שֶׁמַּזִּין יוֹם אַחַר יוֹם מַעֲלָה יְתֵרָה עָשׂוּ בְּפָרָה:","בִּרְבִיעִי בְּשַׁבָּת הָיוּ מַפְרִישִׁין אוֹתוֹ כְּדֵי שֶׁיָּחוּל רְבִיעִי שֶׁלּוֹ לִהְיוֹת בְּשַׁבָּת. שֶׁהַהַזָּיָה אֵינָהּ דּוֹחָה שַׁבָּת וְהָרְבִיעִי אֵין צָרִיךְ הַזָּיָה:","בְּכָל יוֹם וְיוֹם מִימֵי הַהַפְרָשָׁה שֶׁמַּזִּין עָלָיו בָּהֶם. מַזִּין מֵאֵפֶר פָּרָה מִן הַפָּרוֹת שֶׁנִּשְׂרְפוּ כְּבָר. וְאִם לֹא הָיָה שָׁם אֶלָּא אֵפֶר פָּרָה אַחַת בִּלְבַד מַזִּין מִמֶּנּוּ עָלָיו כָּל הַשִּׁשָּׁה:","כְּשֶׁמַּזִּין עָלָיו בִּימֵי הַהַפְרָשָׁה אֵין מַזֶּה עָלָיו אֶלָּא אָדָם שֶׁלֹּא נִטְמָא בְּמֵת מֵעוֹלָם שֶׁהַמַּזֶה צָרִיךְ שֶׁיִּהְיֶה טָהוֹר. וְאִם תֹּאמַר יַזֶּה עָלָיו אִישׁ שֶׁנִּטְמָא וְהֻזָּה עָלָיו. שֶׁמָּא זֶה שֶׁהִזָּה עָלָיו לֹא הָיָה טָהוֹר מִטֻּמְאַת מֵת. וְכֵן הַכֵּלִים שֶׁמְּמַלְּאִין בָּהֶן וּמְקַדְּשִׁין לְהַזּוֹת עַל הַכֹּהֵן הַשּׂוֹרֵף כֻּלָּם כְּלֵי אֲבָנִים הָיוּ שֶׁאֵין מְקַבְּלִין טֻמְאָה. וְכָל אֵלּוּ הַדְּבָרִים מַעֲלוֹת יְתֵרוֹת הֵן שֶׁעָשׂוּ בָּהּ. וְכֵיצַד יִמָּצֵא אִישׁ שֶׁלֹּא נִטְמָא בְּמֵת מֵעוֹלָם. חֲצֵרוֹת הָיוּ בִּירוּשָׁלַיִם בְּנוּיוֹת עַל גַּבֵּי הַסֶּלַע וְתַחְתֵּיהֶן חָלוּל מִפְּנֵי קֶבֶר הַתְּהוֹם. וּמְבִיאִין הָיוּ נָשִׁים עֻבָּרוֹת וְיוֹלְדוֹת שָׁם וּמְגַדְּלוֹת שָׁם אֶת בְּנֵיהֶם. וּכְשֶׁיִּרְצוּ לְהַזּוֹת עַל הַכֹּהֵן הַשּׂוֹרֵף מְבִיאִין שְׁוָרִים מִפְּנֵי שֶׁכְּרֵסֵיהֶן נְפוּחוֹת וּמַנִּיחִים עַל גַּבֵּיהֶן דְּלָתוֹת וְיוֹשְׁבִין הַתִּינוֹקוֹת עַל גַּבֵּי הַדְּלָתוֹת כְּדֵי שֶׁיִּהְיֶה הָאֹהֶל מַבְדִּיל בֵּינָם לְבֵין הָאָרֶץ מִפְּנֵי קֶבֶר הַתְּהוֹם. וְכוֹסוֹת שֶׁל אֶבֶן בְּיָדָם וְהוֹלְכִין לַשִּׁילוֹחַ. הִגִּיעוּ לַשִּׁילוֹחַ יוֹרְדִין שָׁם וּמְמַלְּאִין שֶׁאֵין לָחוּשׁ שָׁם מִפְּנֵי קֶבֶר הַתְּהוֹם שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לִקְבֹּר בַּנְּהָרוֹת. וְעוֹלִין וְיוֹשְׁבִין עַל גַּבֵּי הַדְּלָתוֹת וְהוֹלְכִין עַד שֶׁמַּגִּיעִין לְהַר הַבַּיִת. הִגִּיעוּ לְהַר הַבַּיִת יוֹרְדִין וּמְהַלְּכִין עַל רַגְלֵיהֶן מִפְּנֵי שֶׁכָּל הַר הַבַּיִת וְהָעֲזָרוֹת תַּחְתֵּיהֶן הָיָה חָלוּל מִפְּנֵי קֶבֶר הַתְּהוֹם. וּמְהַלְּכִין עַד פֶּתַח הָעֲזָרָה. וּבְפֶתַח הָעֲזָרָה הָיָה קָלָל שֶׁל אֵפֶר נוֹטְלִין הָאֵפֶר וְנוֹתְנִין בַּמַּיִם שֶׁבַּכּוֹסוֹת וּמַזִּין עַל הַכֹּהֵן הַשּׂוֹרֵף. וּמַטְבִּילִין הָיוּ הַתִּינוֹקוֹת שֶׁמְּמַלְּאִין וּמְקַדְּשִׁין וּמַזִּין עַל הַשּׂוֹרֵף אַף עַל פִּי שֶׁהֵן טְהוֹרִין מִטֻּמְאַת הַמֵּת שֶׁמָּא נִטְמְאוּ בְּטֻמְאָה אַחֶרֶת:","תִּינוֹק שֶׁטָּבַל לְמַלְּאוֹת וּלְהַזּוֹת לֹא יְמַלֵּא בְּכֵלָיו תִּינוֹק אַחֵר אַף עַל פִּי שֶׁטָּבַל. וְתִינוֹק שֶׁטָּבַל לְהַזּוֹת עַל כֹּהֵן זֶה אֵינוֹ מַזֶּה עַל כֹּהֵן אַחֵר עַד שֶׁיִּטְבּל לְשֵׁם מַעֲשֶׂה זֶה הַכֹּהֵן. וְכֵן כֵּלִים שֶׁטִּהֲרוּם לְחַטָּאת זוֹ וּבְנֵי אָדָם שֶׁטִּהֲרוּם לְחַטָּאת זוֹ לֹא יִתְעַסֵּק בָּהֶם בְּפָרָה אַחֶרֶת עַד שֶׁיִּטְבְּלוּ לִשְׁמָהּ. וְכָל הַדְּבָרִים הָאֵלּוּ מַעֲלוֹת יְתֵרוֹת בְּפָרָה:"],"Mishneh Torah, Repentance 4":["אַרְבָעָה וְעֶשְׂרִים דְּבָרִים מְעַכְּבִין אֶת הַתְּשׁוּבָה. אַרְבָּעָה מֵהֶן עָוֹן גָּדוֹל וְהָעוֹשֶׂה אֶחָד מֵהֶן אֵין הַקָּדוֹשׁ בָּרוּךְ הוּא מַסְפִּיק בְּיָדוֹ לַעֲשׂוֹת תְּשׁוּבָה לְפִי גֹּדֶל חֶטְאוֹ. וְאֵלּוּ הֵן. א) הַמַּחְטִיא אֶת הָרַבִּים וּבִכְלַל עָוֹן זֶה הַמְעַכֵּב אֶת הָרַבִּים מִלַּעֲשׂוֹת מִצְוָה. ב) וְהַמַּטֶּה אֶת חֲבֵרוֹ מִדֶּרֶךְ טוֹבָה לְרָעָה כְּגוֹן מֵסִית וּמַדִּיחַ. ג) הָרוֹאֶה בְּנוֹ יוֹצֵא לְתַרְבּוּת רָעָה וְאֵינוֹ מְמַחֶה בְּיָדוֹ. הוֹאִיל וּבְנוֹ בִּרְשׁוּתוֹ אִלּוּ מִחָה בּוֹ הָיָה פּוֹרֵשׁ וְנִמְצָא כְּמַחְטִיאוֹ. וּבִכְלַל עָוֹן זֶה כָּל שֶׁאֶפְשָׁר בְּיָדוֹ לִמְחוֹת בַּאֲחֵרִים בֵּין יָחִיד בֵּין רַבִּים וְלֹא מִחָה אֶלָּא יַנִּיחֵם בְּכִשְׁלוֹנָם. ד) וְהָאוֹמֵר אֶחְטָא וְאָשׁוּב וּבִכְלַל זֶה הָאוֹמֵר אֶחְטָא וְיוֹם הַכִּפּוּרִים מְכַפֵּר:","וּמֵהֶן חֲמִשָּׁה דְּבָרִים הַנּוֹעֲלִים דַּרְכֵי הַתְּשׁוּבָה בִּפְנֵי עוֹשֵׂיהֶן. וְאֵלּוּ הֵן. א) הַפּוֹרֵשׁ מִן הַצִּבּוּר, לְפִי שֶׁבִּזְמַן שֶׁיַּעֲשׂוּ תְּשׁוּבָה לֹא יִהְיֶה עִמָּהֶן וְאֵינוֹ זוֹכֶה עִמָּהֶן בִּזְכוּת שֶׁעוֹשִׂין. ב) וְהַחוֹלֵק עַל דִּבְרֵי חֲכָמִים, לְפִי שֶׁמַּחְלָקְתוֹ גּוֹרֶמֶת לוֹ לִפְרשׁ מֵהֶן וְאֵינוֹ יוֹדֵעַ דַּרְכֵי הַתְּשׁוּבָה. ג) וְהַמַּלְעִיג עַל הַמִּצְוֹת, שֶׁכֵּיוָן שֶׁנִּתְבַּזּוּ בְּעֵינָיו אֵינוֹ רוֹדֵף אַחֲרֵיהֶן וְלֹא עוֹשָׂן וְאִם לֹא יַעֲשֶׂה בַּמֶּה יִזְכֶּה. ד) וְהַמְבַזֶּה רַבּוֹתָיו, שֶׁדָּבָר זֶה גּוֹרֵם לוֹ לְדָחֳפוֹ וּלְטָרְדוֹ כְּגֵיחֲזִי וּבִזְמַן שֶׁנִּטְרָד לֹא יִמְצָא מְלַמֵּד וּמוֹרֶה לוֹ דֶּרֶךְ הָאֱמֶת. ה) וְהַשּׂוֹנֵא אֶת הַתּוֹכָחוֹת שֶׁהֲרֵי לֹא הִנִּיחַ לוֹ דֶּרֶךְ תְּשׁוּבָה. שֶׁהַתּוֹכָחָה גּוֹרֶמֶת לִתְשׁוּבָה שֶׁבִּזְמַן שֶׁמּוֹדִיעִין לוֹ לָאָדָם חֲטָאָיו וּמַכְלִימִין אוֹתוֹ חוֹזֵר בִּתְשׁוּבָה כְּמוֹ שֶׁכָּתוּב בַּתּוֹרָה (דברים ט ז) \"זְכֹר (וְ) אַל תִּשְׁכַּח\". (דברים ט ז) \"מַמְרִים הֱיִיתֶם\". (דברים כט ג) \"וְלֹא נָתַן ה' לָכֶם לֵב\". (דברים לב ו) \"עַם נָבָל וְלֹא חָכָם\". וְכֵן יְשַׁעְיָהוּ הוֹכִיחַ אֶת יִשְׂרָאֵל וְאָמַר (ישעיה א ד) \"הוֹי גּוֹי חֹטֵא\". (ישעיה א ג) \"יָדַע שׁוֹר קֹנֵהוּ\". (ישעיה מח ד) \"מִדַּעְתִּי כִּי קָשֶׁה אָתָּה\". וְכֵן צִוָּהוּ הָאֵל לְהוֹכִיחַ לַחַטָּאִים שֶׁנֶּאֱמַר (ישעיה נח א) \"קְרָא בְגָרוֹן אַל תַּחְשֹׂךְ\". וְכֵן כָּל הַנְּבִיאִים הוֹכִיחוּ לְיִשְׂרָאֵל עַד שֶׁחָזְרוּ בִּתְשׁוּבָה. לְפִיכָךְ צָרִיךְ לְהַעֲמִיד בְּכָל קָהָל וְקָהָל מִיִּשְׂרָאֵל חָכָם גָּדוֹל וְזָקֵן וִירֵא שָׁמַיִם מִנְּעוּרָיו וְאָהוּב לָהֶם שֶׁיְּהֵא מוֹכִיחַ לָרַבִּים וּמַחֲזִירָן בִּתְשׁוּבָה, וְזֶה שֶּׁשּׂוֹנֵא אֶת הַתּוֹכָחוֹת אֵינוֹ בָּא לַמּוֹכִיחַ וְלֹא שׁוֹמֵעַ דְּבָרָיו לְפִיכָךְ יַעֲמֹד בְּחַטֹּאתָיו שֶׁהֵם בְּעֵינָיו טוֹבִים:","וּמֵהֶם חֲמִשָּׁה דְּבָרִים הָעוֹשֶׂה אוֹתָן אִי אֶפְשָׁר לוֹ שֶׁיָּשׁוּב בִּתְשׁוּבָה גְּמוּרָה לְפִי שֶׁהֵם עֲוֹנוֹת שֶׁבֵּין אָדָם לַחֲבֵרוֹ וְאֵינוֹ יוֹדֵעַ חֲבֵרוֹ שֶׁחָטָא לוֹ כְּדֵי שֶׁיַּחֲזִיר לוֹ אוֹ יִשְׁאַל מִמֶּנּוּ לִמְחל לוֹ. וְאֵלּוּ הֵן. א) הַמְקַלֵּל אֶת הָרַבִּים וְלֹא קִלֵּל אָדָם יָדוּעַ כְּדֵי שֶׁיִּשְׁאַל מִמֶּנּוּ כַּפָּרָה. ב) וְהַחוֹלֵק עִם גַּנָּב, שֶׁלְּפִי שֶׁאֵינוֹ יוֹדֵעַ גְּנֵבָה זוֹ שֶׁל מִי הִיא אֶלָּא הַגַּנָּב גּוֹנֵב לָרַבִּים וּמֵבִיא לוֹ וְהוּא לוֹקֵחַ. וְעוֹד שֶׁהוּא מַחֲזִיק יַד הַגַּנָּב וּמַחְטִיאוֹ. ג) וְהַמּוֹצֵא אֲבֵדָה וְאֵינוֹ מַכְרִיז עָלֶיהָ עַד שֶׁיַּחֲזִירָהּ לִבְעָלֶיהָ, לְאַחַר זְמַן כְּשֶׁיַּעֲשֶׂה תְּשׁוּבָה אֵינוֹ יוֹדֵעַ לְמִי יַחֲזִיר. ד) וְהָאוֹכֵל שׁוֹר עֲנִיִּים וִיתוֹמִים וְאַלְמָנוֹת. אֵלּוּ בְּנֵי אָדָם אֻמְלָלִין הֵם וְאֵינָן יְדוּעִים וּמְפֻרְסָמִים וְגוֹלִים מֵעִיר לְעִיר וְאֵין לָהֶם מַכִּיר כְּדֵי שֶׁיֵּדַע שׁוֹר זֶה שֶׁל מִי הוּא וְיַחֲזִירֶנּוּ לוֹ. ה) וְהַמְקַבֵּל שֹׁחַד לְהַטּוֹת דִּין אֵינוֹ יוֹדֵעַ עַד הֵיכָן הִגִּיעַ הַטָּיָה זוֹ וְכַמָּה הִיא כֹּחָהּ כְּדֵי שֶׁיַּחֲזִיר, שֶׁהַדָּבָר יֵשׁ לוֹ רַגְלַיִם. וְעוֹד שֶׁהוּא מַחֲזִיק יַד זֶה וּמַחְטִיאוֹ:","וּמֵהֶן חֲמִשָּׁה דְּבָרִים הָעוֹשֶׂה אוֹתָן אֵין חֶזְקָתוֹ לָשׁוּב מֵהֶן. לְפִי שֶׁהֵם דְּבָרִים קַלִּים בְּעֵינֵי רֹב הָאָדָם וְנִמְצָא חוֹטֵא וְהוּא יְדַמֶּה שֶׁאֵין זֶה חֵטְא. וְאֵלּוּ הֵן. א) הָאוֹכֵל מִסְּעֻדָּה שֶׁאֵינָהּ מַסְפֶּקֶת לִבְעָלֶיהָ שֶׁזֶּה אֲבַק גֵּזֶל הוּא. וְהוּא מְדַמֶּה שֶׁלֹּא חָטָא וְיֹאמַר כְּלוּם אָכַלְתִּי אֶלָּא בִּרְשׁוּתוֹ. ב) הַמִּשְׁתַּמֵּשׁ בַּעֲבוֹטוֹ שֶׁל עָנִי שֶׁהָעֲבוֹט שֶׁל עָנִי אֵינוֹ אֶלָּא כְּגוֹן קוֹרְדוֹם וּמַחֲרֵשָׁה וְיֹאמַר בְּלִבּוֹ אֵינָן חֲסֵרִים וַהֲרֵי לֹא גָּזַלְתִּי אוֹתוֹ. ג) הַמִּסְתַּכֵּל בַּעֲרָיוֹת מַעֲלֶה עַל דַּעְתּוֹ שֶׁאֵין בְּכָךְ כְּלוּם שֶׁהוּא אוֹמֵר וְכִי בָּעַלְתִּי אוֹ קָרַבְתִּי אֶצְלָהּ. וְהוּא אֵינוֹ יוֹדֵעַ שֶׁרְאִיַּת הָעֵינַיִם עָוֹן גָּדוֹל שֶׁהִיא גּוֹרֶמֶת לְגוּפָן שֶׁל עֲרָיוֹת שֶׁנֶּאֱמַר (במדבר טו לט) \"וְלֹא תָתֻרוּ אַחֲרֵי לְבַבְכֶם וְאַחֲרֵי עֵינֵיכֶם\". ד) הַמִּתְכַּבֵּד בִּקְלוֹן חֲבֵרוֹ אוֹמֵר בְּלִבּוֹ שֶׁאֵינוֹ חֵטְא לְפִי שֶׁאֵין חֲבֵרוֹ עוֹמֵד שָׁם וְלֹא הִגִּיעַ לוֹ בּשֶׁת וְלֹא בִּיְּשׁוֹ אֶלָּא עָרַךְ מַעֲשָׂיו הַטּוֹבִים וְחָכְמָתוֹ לְמוּל מַעֲשֵׂה חֲבֵרוֹ אוֹ חָכְמָתוֹ כְּדֵי שֶׁיֵּרָאֶה מִכְּלָלוֹ שֶׁהוּא מְכֻבָּד וַחֲבֵרוֹ בָּזוּי. ה) וְהַחוֹשֵׁד כְּשֵׁרִים אוֹמֵר בְּלִבּוֹ שֶׁאֵינוֹ חֵטְא לְפִי שֶׁהוּא אוֹמֵר מֶה עָשִׂיתִי לוֹ וְכִי יֵשׁ שָׁם אֶלָּא חֲשָׁד שֶׁמָּא עָשָׂה אוֹ לֹא עָשָׂה וְהוּא אֵינוֹ יוֹדֵעַ שֶׁזֶּה עָוֹן שֶׁמֵּשִׂים אָדָם כָּשֵׁר בְּדַעְתּוֹ כְּבַעַל עֲבֵרָה:","וּמֵהֶן חֲמִשָּׁה דְּבָרִים הָעוֹשֶׂה אוֹתָם יִמָּשֵׁךְ אַחֲרֵיהֶם תָּמִיד וְקָשִׁים הֵם לִפְרשׁ מֵהֶן. לְפִיכָךְ צָרִיךְ אָדָם לְהִזָּהֵר מֵהֶן שֶׁמָּא יִדְבַּק בָּהֶן וְהֵן כֻּלָּן דֵּעוֹת רָעוֹת עַד מְאֹד. וְאֵלּוּ הֵן. רְכִילוּת. וְלָשׁוֹן הָרַע. וּבַעַל חֵמָה. וּבַעַל מַחֲשָׁבָה רָעָה. וְהַמִּתְחַבֵּר לָרָשָׁע מִפְּנֵי שֶׁהוּא לוֹמֵד מִמַּעֲשָׂיו וְהֵן נִרְשָׁמִים בְּלִבּוֹ. הוּא שֶׁאָמַר שְׁלֹמֹה (משלי יג כ) \"וְרֹעֶה כְסִילִים יֵרוֹעַ\". וּכְבָר בֵּאַרְנוּ בְּהִלְכוֹת דֵּעוֹת דְּבָרִים שֶׁצָּרִיךְ כָּל אָדָם לִנְהֹג בָּהֶן תָּמִיד, קַל וָחֹמֶר לְבַעַל תְּשׁוּבָה:","כָּל אֵלּוּ הַדְּבָרִים וְכַיּוֹצֵא בָּהֶן אַף עַל פִּי שֶׁמְּעַכְּבִין אֶת הַתְּשׁוּבָה אֵין מוֹנְעִין אוֹתָהּ אֶלָּא אִם עָשָׂה אָדָם תְּשׁוּבָה מֵהֶן הֲרֵי זֶה בַּעַל תְּשׁוּבָה וְיֵשׁ לוֹ חֵלֶק לָעוֹלָם הַבָּא:"],"Mishneh Torah, Rest on a Holiday 7":["חֻלוֹ שֶׁל מוֹעֵד אַף עַל פִּי שֶׁלֹּא נֶאֱמַר בּוֹ (ויקרא כג כד) (ויקרא כג לט) \"שַׁבָּתוֹן\" הוֹאִיל וְנִקְרָא (ויקרא כג ז) \"מִקְרָא קֹדֶשׁ\" וַהֲרֵי הוּא זְמַן חֲגִיגָה בַּמִּקְדָּשׁ אָסוּר בַּעֲשִׂיַּת מְלָאכָה כְּדֵי שֶׁלֹּא יִהְיֶה כִּשְׁאָר יְמֵי הַחל שֶׁאֵין בָּהֶן קְדֻשָּׁה כְּלָל. וְהָעוֹשֶׂה בּוֹ מְלָאכָה הָאֲסוּרָה מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת מִפְּנֵי שֶׁאִסּוּרוֹ מִדִּבְרֵי סוֹפְרִים. וְלֹא כָּל מְלֶאכֶת עֲבוֹדָה אֲסוּרָה בּוֹ כְּיוֹם טוֹב שֶׁסּוֹף הָעִנְיָן בַּדְּבָרִים שֶׁנֶּאֶסְרוּ בּוֹ כְּדֵי שֶׁלֹּא יִהְיֶה כְּיוֹם חֹל לְכָל דָּבָר. לְפִיכָךְ יֵשׁ מְלָאכוֹת אֲסוּרוֹת בּוֹ וְיֵשׁ מְלָאכוֹת מֻתָּרוֹת בּוֹ:","וְאֵלּוּ הֵן. כָּל מְלָאכָה שֶׁאִם לֹא יַעֲשֶׂה אוֹתָהּ בַּמּוֹעֵד יִהְיֶה שָׁם הֶפְסֵד הַרְבֵּה עוֹשִׂין אוֹתָהּ. וּבִלְבַד שֶׁלֹּא יִהְיֶה בָּהּ טֹרַח הַרְבֵּה. כֵּיצַד. מַשְׁקִין בֵּית הַשְּׁלָחִין בַּמּוֹעֵד אֲבָל לֹא בֵּית הַמַּשְׁקֶה. שֶׁאִם לֹא יַשְׁקֶה בֵּית הַשְּׁלָחִין וְהִיא הָאָרֶץ הַצְּמֵאָה יִפָּסְדוּ בּוֹ הָאִילָנוֹת שֶׁבָּהּ. וּכְשֶׁהוּא מַשְׁקֶה אוֹתָהּ לֹא יִדְלֶה וְיַשְׁקֶה מִן הַבְּרֵכָה אוֹ מִמֵּי הַגְּשָׁמִים מִפְּנֵי שֶׁהוּא טֹרַח גָּדוֹל. אֲבָל מַשְׁקֶה הוּא מִן הַמַּעְיָן בֵּין שֶׁהָיָה בֵּין שֶׁיָּצָא לְכַתְּחִלָּה מַמְשִׁיכוֹ וּמַשְׁקֶה בּוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הוֹפֵךְ אָדָם אֶת זֵיתָיו בַּמּוֹעֵד וְטוֹחֵן אוֹתָן וְדוֹרֵךְ אוֹתָן וּמְמַלֵּא הֶחָבִיּוֹת וְגַף אוֹתָן כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל. כָּל שֶׁיֵּשׁ בּוֹ הֶפְסֵד אִם לֹא נַעֲשָׂה עוֹשֵׂהוּ כְּדַרְכּוֹ וְאֵינוֹ צָרִיךְ שִׁנּוּי. וְכֵן מַכְנִיס אָדָם פֵּרוֹתָיו מִפְּנֵי הַגַּנָּבִים וּבִלְבַד שֶׁיַּכְנִיסֵם בְּצִנְעָה. וְשׁוֹלֶה פִּשְׁתָּנוֹ מִן הַמִּשְׁרֶה בִּשְׁבִיל שֶׁלֹּא תֹּאבַד. וְכֵן כֶּרֶם שֶׁהִגִּיעַ זְמַנּוֹ לְהִבָּצֵר בַּמּוֹעֵד בּוֹצְרִין אוֹתוֹ:","וְאָסוּר לָאָדָם שֶׁיִּתְכַּוֵּן וִיאַחֵר מְלָאכוֹת אֵלּוּ וְכַיּוֹצֵא בָּהֶן וְיַנִּיחֵם כְּדֵי לַעֲשׂוֹתָן בַּמּוֹעֵד מִפְּנֵי שֶׁהוּא פָּנוּי. וְכָל הַמְכַוֵּן מְלַאכְתּוֹ וְהִנִּיחָהּ לַמּוֹעֵד וַעֲשָׂאָהּ בַּמּוֹעֵד בֵּית דִּין מְאַבְּדִין אוֹתָהּ וּמַפְקִירִין אוֹתָהּ לַכּל. וְאִם כִּוֵּן מְלַאכְתּוֹ וּמֵת אֵין קוֹנְסִין בְּנוֹ אַחֲרָיו וְאֵין מְאַבְּדִין אוֹתָהּ מִמֶּנּוּ. וְאֵין מוֹנְעִין הַבֵּן מִלַּעֲשׂוֹת אוֹתָהּ מְלָאכָה בַּמּוֹעֵד כְּדֵי שֶׁלֹּא תֹּאבַד:","מִי שֶׁצָּרַךְ לִתְפֹּר לוֹ בֶּגֶד אוֹ לִבְנוֹת לוֹ מָקוֹם בַּמּוֹעֵד. אִם הָיָה הֶדְיוֹט וְאֵינוֹ מָהִיר בְּאוֹתָהּ מְלָאכָה הֲרֵי זֶה עוֹשֶׂה אוֹתָהּ כְּדַרְכּוֹ. וְאִם הָיָה אֻמָּן מָהִיר הֲרֵי זֶה עוֹשֶׂה אוֹתָהּ מַעֲשֵׂה הֶדְיוֹט. כֵּיצַד. בִּתְפִירָה מַכְלִיב וּבְבִנְיָן מַנִּיחַ אֲבָנִים וְאֵינוֹ טָח בְּטִיט עֲלֵיהֶן וְשָׁף סִדְקֵי הַקַּרְקַע וּמַעֲגִילָהּ בַּיָּד וּבָרֶגֶל כְּעֵין שֶׁמַּעֲגִילִים בְּמַחְלָצַיִם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִי שֶׁהָיְתָה לוֹ תְּבוּאָה מְחֻבֶּרֶת לַקַּרְקַע וְאֵין לוֹ מַה שֶּׁיֹּאכַל בַּמּוֹעֵד אֶלָּא מִמֶּנָּה אַף עַל פִּי שֶׁאֵין כָּאן הֶפְסֵד אֵין מַצְרִיכִין אוֹתוֹ לִקְנוֹת מַה שֶּׁיֹּאכַל מִן הַשּׁוּק עַד שֶׁיִּקְצֹר אַחַר הַמּוֹעֵד אֶלָּא קוֹצֵר וּמְעַמֵּר וְדָשׁ וְזוֹרֶה וּבוֹרֵר וְטוֹחֵן מַה שֶּׁהוּא צָרִיךְ. וּבִלְבַד שֶׁלֹּא יָדוּשׁ בְּפָרוֹת. שֶׁכָּל דָּבָר שֶׁאֵין בּוֹ הֶפְסֵד צָרִיךְ לְשַׁנּוֹת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כְּבָשִׁים שֶׁיָּכוֹל לֶאֱכל מֵהֶן בַּמּוֹעֵד כּוֹבְשָׁן. וְשֶׁאֵינָן רְאוּיִין אֶלָּא לְאַחַר הַמּוֹעֵד אָסוּר לְכָבְשָׁן. וְצָד אָדָם דָּגִים כָּל שֶׁיָּכוֹל לָצוּד וּמוֹלֵחַ הַכּל בַּמּוֹעֵד שֶׁהֲרֵי אֶפְשָׁר שֶׁיֹּאכַל מֵהֶן בַּמּוֹעֵד אִם יִסְחֹט אוֹתָן בְּיָדוֹ פְּעָמִים רַבּוֹת עַד שֶׁיִּתְרַכְּכוּ:","מְטִילִין שֵׁכָר בַּמּוֹעֵד לְצֹרֶךְ הַמּוֹעֵד. וְשֶׁלֹּא לְצֹרֶךְ הַמּוֹעֵד אָסוּר. אֶחָד שֵׁכָר תְּמָרִים וְאֶחָד שֵׁכָר שְׂעוֹרִים. אַף עַל פִּי שֶׁיֵּשׁ לוֹ יָשָׁן מַעֲרִים וְשׁוֹתֶה מִן הֶחָדָשׁ שֶׁאֵין הַעֲרָמָה זוֹ נִכֶּרֶת לָרוֹאֶה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כָּל מְלָאכוֹת שֶׁהֵן לְצֹרֶךְ הַמּוֹעֵד כְּשֶׁעוֹשִׂין אוֹתָן אֻמָּנֵיהֶן עוֹשִׂין בְּצִנְעָה. כֵּיצַד. הַצַּיָּדִים וְהַטּוֹחֲנִין וְהַבּוֹצְרִין לִמְכֹּר בַּשּׁוּק הֲרֵי אֵלּוּ עוֹשִׂין בְּצִנְעָה לְצֹרֶךְ הַמּוֹעֵד. וְאִם עָשָׂה לְצֹרֶךְ הַמּוֹעֵד וְהוֹתִיר הֲרֵי זֶה מֻתָּר:","עוֹשִׂין כָּל צָרְכֵי הָרַבִּים בַּמּוֹעֵד. כֵּיצַד. מְתַקְּנִים קִלְקוּלֵי הַמַּיִם שֶׁבִּרְשׁוּת הָרַבִּים. וּמְתַקְּנִין אֶת הַדְּרָכִים וְאֶת הָרְחוֹבוֹת. וְחוֹפְרִים לָרַבִּים בּוֹרוֹת שִׁיחִין וּמְעָרוֹת. וְכוֹרִין לָהֶן נְהָרוֹת כְּדֵי שֶׁיִּשְׁתּוּ מֵימֵיהֶן וְכוֹנְסִים מַיִם לְבוֹרוֹת וּמְעָרוֹת שֶׁל רַבִּים וּמְתַקְּנִין אֶת סִדְקֵיהֶן. וּמְסִירִין אֶת הַקּוֹצִין מִן הַדְּרָכִים. וּמוֹדְדִין אֶת הַמִּקְוָאוֹת וְכָל מִקְוֶה שֶׁנִּמְצָא חָסֵר מַרְגִּילִין לוֹ מַיִם וּמַשְׁלִימִין לוֹ שִׁעוּרוֹ:","וְיוֹצְאִין שְׁלוּחֵי בֵּית דִּין לְהַפְקִיר אֶת הַכִּלְאַיִם. וּפוֹדִין אֶת הַשְּׁבוּיִים וְאֶת הָעֶרְכִין וְאֶת הַחֲרָמִים וְאֶת הַהֶקְדֵּשׁוֹת. וּמַשְׁקִין אֶת הַסּוֹטוֹת. וְשׂוֹרְפִין אֶת הַפָּרָה. וְעוֹרְפִין אֶת הָעֶגְלָה. וְרוֹצְעִין עֶבֶד עִבְרִי. וּמְטַהֲרִין אֶת הַמְצֹרָע. וּמְצַיְּנִין עַל הַקְּבָרוֹת שֶׁמִּחוּ גְּשָׁמִים אֶת צִיּוּנָן כְּדֵי שֶׁיִּפְרְשׁוּ מֵהֶן הַכֹּהֲנִים. שֶׁכָּל אֵלּוּ צָרְכֵי רַבִּים הֵן:","וְדָנִים דִּינֵי מָמוֹנוֹת וְדִינֵי מַכּוֹת וְדִינֵי נְפָשׁוֹת בַּמּוֹעֵד. וּמִי שֶׁלֹּא קִבֵּל עָלָיו הַדִּין מְשַׁמְּתִין אוֹתוֹ בַּמּוֹעֵד. וּכְשֵׁם שֶׁדָּנִין בַּמּוֹעֵד כָּךְ כּוֹתְבִין מַעֲשֵׂה בֵּית דִּין וְכָל הַדּוֹמֶה לוֹ. כֵּיצַד. כּוֹתְבִין הַדַּיָּנִין אִגְּרוֹת שׁוּם שֶׁשָּׁמוּ לְבַעַל חוֹב וְאִגְּרוֹת שֶׁמָּכְרוּ בָּהֶן לִמְזוֹן הָאִשָּׁה וְהַבָּנוֹת. וְשִׁטְרֵי חֲלִיצָה וּמֵאוּנִין. וְכָל הַדּוֹמֶה לָהֶן מִדְּבָרִים שֶׁצְּרִיכִים הַדַּיָּנִין לְכָתְבָם כְּדֵי שֶׁיִּזְכְּרוּם. כְּגוֹן טַעֲנוֹת בַּעֲלֵי דִּינִין אוֹ דְּבָרִים שֶׁקִּבְּלוּ עֲלֵיהֶן כְּגוֹן אִישׁ פְּלוֹנִי נֶאֱמָן עָלַי. אוֹ אִישׁ פְּלוֹנִי יָדוּן לִי. מִי שֶׁצָּרִיךְ לִלְווֹת בַּמּוֹעֵד וְלֹא הֶאֱמִינוֹ הַמַּלְוֶה בְּעַל פֶּה הֲרֵי זֶה כּוֹתֵב שְׁטַר חוֹב. וְכֵן כּוֹתְבִין גִּטִּין וְקִדּוּשֵׁי נָשִׁים וְשׁוֹבְרִין וּמַתָּנוֹת. שֶׁכָּל אֵלּוּ כְּצָרְכֵי רַבִּים הֵן:","וְאָסוּר לִכְתֹּב בַּמּוֹעֵד אֲפִלּוּ סְפָרִים תְּפִלִּין וּמְזוּזוֹת. וְאֵין מַגִּיהִין אֲפִלּוּ אוֹת אַחַת בְּסֵפֶר הָעֲזָרָה מִפְּנֵי שֶׁזּוֹ מְלָאכָה שֶׁאֵינָהּ לְצֹרֶךְ הַמּוֹעֵד. אֲבָל כּוֹתֵב אָדָם תְּפִלִּין וּמְזוּזָה לְעַצְמוֹ וְטוֹוֶה תְּכֵלֶת לְבִגְדוֹ. וְאִם אֵין לוֹ מַה יֹּאכַל כּוֹתֵב וּמוֹכֵר לַאֲחֵרִים כְּדֵי פַּרְנָסָתוֹ:","וּמֻתָּר לִכְתֹּב אִגְּרוֹת שֶׁל שְׁאֵלַת שָׁלוֹם בַּמּוֹעֵד. וְכוֹתֵב חֶשְׁבּוֹנוֹתָיו וּמְחַשֵּׁב יְצִיאוֹתָיו. שֶׁכְּתִיבוֹת אֵלּוּ אֵין אָדָם נִזְהָר בְּתִקּוּנָן מְאֹד וְנִמְצְאוּ כְּמַעֲשֵׂה הֶדְיוֹט בִּמְלָאכוֹת:","עוֹשִׂין כָּל צָרְכֵי הַמֵּת בַּמּוֹעֵד. גּוֹזְזִין שְׂעָרוֹ וּמְכַבְּסִין כְּסוּתוֹ וְעוֹשִׂין לוֹ אָרוֹן. וְאִם לֹא הָיוּ לָהֶם נְסָרִים מְבִיאִין קוֹרוֹת וְנוֹסְרִין מֵהֶם נְסָרִים בְּצִנְעָה בְּתוֹךְ הַבַּיִת. וְאִם הָיָה אָדָם מְפֻרְסָם עוֹשִׂין אֲפִלּוּ בַּשּׁוּק. אֲבָל אֵין כּוֹרְתִין עֵץ מִן הַיַּעַר לִנְסֹר מִמֶּנּוּ לוּחוֹת לָאָרוֹן. וְאֵין חוֹצְבִין אֲבָנִים לִבְנוֹת בָּהֶן קֶבֶר:","אֵין רוֹאִין אֶת הַנְּגָעִים בַּמּוֹעֵד שֶׁמָּא יִמָּצֵא טָמֵא וְנִמְצָא חַגּוֹ נֶהֱפָךְ לְאֵבֶל. וְאֵין נוֹשְׂאִין נָשִׁים וְלֹא מְיַבְּמִין בַּמּוֹעֵד כְּדֵי שֶׁלֹּא תִּשְׁתַּכֵּחַ שִׂמְחַת הֶחָג בְּשִׂמְחַת הַנִּשּׂוּאִין. אֲבָל מַחֲזִיר אֶת גְּרוּשָׁתוֹ. וּמְאָרְסִין נָשִׁים בַּמּוֹעֵד. וּבִלְבַד שֶׁלֹּא יַעֲשֶׂה סְעֻדַּת אֵרוּסִין וְלֹא סְעֻדַּת נִשּׂוּאִין. שֶׁלֹּא יְעָרֵב שִׂמְחָה אַחֶרֶת בְּשִׂמְחַת הֶחָג:","אֵין מְגַלְּחִין וְאֵין מְכַבְּסִין בַּמּוֹעֵד גְּזֵרָה שֶׁמָּא יַשְׁהֶה אָדָם עַצְמוֹ לְתוֹךְ הַמּוֹעֵד וְיָבוֹא יוֹם טוֹב הָרִאשׁוֹן וְהוּא מְנֻוָּל. לְפִיכָךְ כָּל מִי שֶׁאִי אֶפְשָׁר לוֹ לְגַלֵּחַ וּלְכַבֵּס בְּעֶרֶב יוֹם טוֹב הֲרֵי זֶה מֻתָּר לְכַבֵּס וּלְגַלֵּחַ בַּמּוֹעֵד:","כֵּיצַד. אָבֵל שֶׁחָל שְׁבִיעִי שֶׁלּוֹ לִהְיוֹת בְּיוֹם טוֹב אוֹ שֶׁחָל לִהְיוֹת בְּעֶרֶב יוֹם טוֹב וַהֲרֵי הוּא שַׁבָּת שֶׁאִי אֶפְשָׁר לְגַלֵּחַ. וְהַבָּא מִמְּדִינַת הַיָּם וְהוּא שֶׁלֹּא יָצָא לְהִטַיֵּיל אֶלָּא לִסְחוֹרָה וְכַיּוֹצֵא בָּהּ. וְהַיּוֹצֵא מִבֵּית הַשִּׁבְיָה וּמִבֵּית הָאֲסוּרִים. וּמִי שֶׁהָיָה מְנֻדֶּה וְלֹא הִתִּירוּהוּ אֶלָּא בַּמּוֹעֵד. וּמִי שֶׁנִּשְׁבַּע שֶׁלֹּא לְגַלֵּחַ וְשֶׁלֹּא לְכַבֵּס וְלֹא נִשְׁאָל לְחָכָם לְהַתִּיר נִדְרוֹ אֶלָּא בַּמּוֹעֵד הֲרֵי אֵלּוּ מְגַלְּחִין וּמְכַבְּסִין בַּמּוֹעֵד:","וְכֻלָּן שֶׁהָיָה לָהֶן פְּנַאי לְגַלֵּחַ קֹדֶם הָרֶגֶל וְלֹא גִּלְּחוּ אֲסוּרִין. אֲבָל הַנָּזִיר וְהַמְצֹרָע שֶׁהִגִּיעַ זְמַן תִּגְלַחְתָּן בֵּין בְּתוֹךְ הַמּוֹעֵד בֵּין קֹדֶם הָרֶגֶל אַף עַל פִּי שֶׁהָיָה לָהֶם פְּנַאי מֻתָּרִין לְגַלֵּחַ בַּמּוֹעֵד שֶׁלֹּא יַשְׁהוּ קָרְבְּנוֹתֵיהֶן. וְכָל הַיּוֹצֵא מִטֻּמְאָתוֹ לְטָהֳרָתוֹ מֻתָּר לְגַלֵּחַ בַּמּוֹעֵד. וְקָטָן שֶׁנּוֹלַד בֵּין בַּמּוֹעֵד בֵּין לִפְנֵי הַמּוֹעֵד מֻתָּר לְגַלְּחוֹ בַּמּוֹעֵד. וְאַנְשֵׁי מִשְׁמָר שֶׁשָּׁלְמָה מִשְׁמַרְתָּן בְּתוֹךְ הַמּוֹעֵד מֻתָּרִין לְגַלֵּחַ מִפְּנֵי שֶׁאַנְשֵׁי מִשְׁמָר אֲסוּרִין לְגַלֵּחַ בְּשַׁבָּת שֶׁלָּהֶן:","מֻתָּר לִטּל שָׂפָה בְּחֻלּוֹ שֶׁל מוֹעֵד. וְלִטּל צִפָּרְנַיִם וַאֲפִלּוּ בִּכְלִי. וּמַעֲבֶרֶת הָאִשָּׁה שֵׂעָר מִבֵּית הַשֶּׁחִי וּמִבֵּית הָעֶרְוָה בֵּין בַּיָּד בֵּין בִּכְלִי. וְעוֹשָׂה כָּל תַּכְשִׁיטֶיהָ בַּמּוֹעֵד. כּוֹחֶלֶת וּפוֹקֶסֶת וּמַעֲבֶרֶת סְרָק עַל פָּנֶיהָ וְטוֹפֶלֶת עַצְמָהּ בְּסִיד וְכַיּוֹצֵא בּוֹ וְהוּא שֶׁתּוּכַל לְקַפְּלוֹ בַּמּוֹעֵד:","הַזָּבִים וְהַזָּבוֹת וְהַנִּדּוֹת וְהַיּוֹלְדוֹת וְכָל הָעוֹלִים מִטֻּמְאָה לְטָהֳרָה בְּתוֹךְ הַמּוֹעֵד הֲרֵי אֵלּוּ מֻתָּרִין לְכַבֵּס. וּמִי שֶׁאֵין לוֹ אֶלָּא חָלוּק אֶחָד הֲרֵי זֶה מְכַבְּסוֹ בַּמּוֹעֵד. מִטְפְּחוֹת הַיָּדַיִם וּמִטְפְּחוֹת הַסְּפָרִים וּמִטְפְּחוֹת הַסְפָג הֲרֵי אֵלּוּ מֻתָּרִין לְכַבֵּס בַּמּוֹעֵד. וְכֵן כְּלֵי פִּשְׁתָּן מֻתָּר לְכַבְּסָן בַּמּוֹעֵד מִפְּנֵי שֶׁצְּרִיכִין כִּבּוּס תָּמִיד אֲפִלּוּ נִתְכַּבְּסוּ עֶרֶב יוֹם טוֹב:","אֵין עוֹשִׂין סְחוֹרָה בַּמּוֹעֵד בֵּין לִמְכֹּר בֵּין לִקְנוֹת. וְאִם הָיָה דָּבָר הָאָבֵד שֶׁאֵינוֹ מָצוּי תָּמִיד לְאַחַר הַמּוֹעֵד כְּגוֹן סְפִינוֹת אוֹ שַׁיָּרוֹת שֶׁבָּאוּ אוֹ שֶׁהֵם מְבַקְּשִׁים לָצֵאת וּמָכְרוּ בְּזוֹל אוֹ לָקְחוּ בְּיֹקֶר הֲרֵי זֶה מֻתָּר לִקְנוֹת אוֹ לִמְכֹּר. וְאֵין לוֹקְחִין בָּתִּים וַעֲבָדִים וּבְהֵמָה אֶלָּא לְצֹרֶךְ הַמּוֹעֵד:","מוֹכְרֵי פֵּרוֹת כְּסוּת וְכֵלִים מוֹכְרִין בְּצִנְעָה לְצֹרֶךְ הַמּוֹעֵד. כֵּיצַד. אִם הָיְתָה הַחֲנוּת פְּתוּחָה לְזָוִית אוֹ לְמָבוֹי פּוֹתֵחַ כְּדַרְכּוֹ. וְאִם הָיְתָה פְּתוּחָה לִרְשׁוּת הָרַבִּים פּוֹתֵחַ אַחַת וְנוֹעֵל אַחַת. וְעֶרֶב יוֹם טוֹב הָאַחֲרוֹן שֶׁל חַג הַסֻּכּוֹת מוֹצִיא וּמְעַטֵּר אֶת הַשּׁוּק בְּפֵרוֹת בִּשְׁבִיל כְּבוֹד יוֹם טוֹב. מוֹכְרֵי תַּבְלִין מוֹכְרִין כְּדַרְכָּן בְּפַרְהֶסְיָא:","כָּל שֶׁאָסוּר לַעֲשׂוֹתוֹ בַּמּוֹעֵד אֵינוֹ אוֹמֵר לְנָכְרִי לַעֲשׂוֹתוֹ. וְכָל שֶׁאָסוּר לַעֲשׂוֹתוֹ בַּמּוֹעֵד אִם אֵין לוֹ מַה שֶּׁיֹּאכַל הֲרֵי זֶה עוֹשֶׂה כְּדֵי פַּרְנָסָתוֹ. וְכֵן עוֹשֶׂה סְחוֹרָה כְּדֵי פַּרְנָסָתוֹ. וּמֻתָּר לֶעָשִׁיר לִשְׂכֹּר פּוֹעֵל עָנִי שֶׁאֵין לוֹ מַה יֹּאכַל לַעֲשׂוֹת מְלָאכָה שֶׁהִיא אֲסוּרָה בַּמּוֹעֵד כְּדֵי שֶׁיִּטּל שְׂכָרוֹ לְהִתְפַּרְנֵס בּוֹ. וְכֵן לוֹקְחִין דְּבָרִים שֶׁאֵינָם לְצֹרֶךְ הַמּוֹעֵד מִפְּנֵי צֹרֶךְ הַמּוֹכֵר שֶׁאֵין לוֹ מַה יֹּאכַל:","שׂוֹכְרִין הַשָּׂכִיר עַל הַמְּלָאכָה בַּמּוֹעֵד לַעֲשׂוֹתָהּ לְאַחַר הַמּוֹעֵד וּבִלְבַד שֶׁלֹּא יִשְׁקל וְשֶׁלֹּא יִמְדֹּד וְלֹא יִמְנֶה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל. נָכְרִי שֶׁקִּבֵּל קִבּלֶת מִיִּשְׂרָאֵל אֲפִלּוּ הָיָה חוּץ לַתְּחוּם אֵינוֹ מַנִּיחוֹ לַעֲשׂוֹתוֹ בַּמּוֹעֵד. שֶׁהַכּל יוֹדְעִין שֶׁמְּלָאכָה זוֹ שֶׁל יִשְׂרָאֵל וְיַחְשְׁדוּ אוֹתוֹ שֶׁהוּא שָׂכַר אֶת הַנָּכְרִי לַעֲשׂוֹת לוֹ בַּמּוֹעֵד. שֶׁאֵין הַכּל יוֹדְעִין הַהֶפְרֵשׁ שֶׁיֵּשׁ בֵּין הַשָּׂכִיר וּבֵין הַקַּבְּלָן וּלְפִיכָךְ אָסוּר:"],"Mishneh Torah, Ritual Slaughter 3":["חֲמִשָׁה דְּבָרִים מַפְסִידִין אֶת הַשְּׁחִיטָה. וְעִקַּר הִלְכוֹת שְׁחִיטָה לְהִזָּהֵר בְּכָל אַחַת מֵהֶן. וְאֵלּוּ הֵן. שְׁהִיָּה. דְּרָסָה. חֲלָדָה. הַגְרָמָה. וְעִקּוּר:","שְׁהִיָּה כֵּיצַד. הֲרֵי שֶׁהִתְחִיל לִשְׁחֹט וְהִגְבִּיהַּ יָדוֹ קֹדֶם שֶׁיִּגְמֹר הַשְּׁחִיטָה וְשָׁהָה בֵּין בְּשׁוֹגֵג בֵּין בְּמֵזִיד בֵּין בְּאֹנֶס וְחָזַר הוּא אוֹ אַחֵר וְגָמַר אֶת הַשְּׁחִיטָה. אִם שָׁהָה כְּדֵי שֶׁיַּגְבִּיהַּ אֶת הַבְּהֵמָה וְיַרְבִּיצֶנָּה וְיִשְׁחֹט שְׁחִיטָתוֹ פְּסוּלָה. וְאִם שָׁהָה פָּחוֹת מִכְּדֵי זֶה שְׁחִיטָתוֹ כְּשֵׁרָה:","הָיְתָה בְּהֵמָה דַּקָּה שִׁעוּר שְׁהִיָּתָהּ כְּדֵי שֶׁיַּגְבִּיהַּ בְּהֵמָה דַּקָּה וְיַרְבִּיצֶנָּה וְיִשְׁחֹט. וְאִם הָיְתָה גַּסָּה כְּדֵי שֶׁיַּגְבִּיהֶנָּה וְיַרְבִּיצֶנָּה וְיִשְׁחֹט. וּבְעוֹף כְּדֵי שֶׁיַּגְבִּיהַּ בְּהֵמָה דַּקָּה וְיַרְבִּיצֶנָּה וְיִשְׁחֹט:","שָׁחַט מְעַט וְשָׁהָה מְעַט וְחָזַר וְשָׁחַט מְעַט וְשָׁהָה מְעַט עַד שֶׁגָּמַר הַשְּׁחִיטָה וְלֹא שָׁהָה בְּפַעַם אַחַת שִׁעוּר הַשְּׁהִיָּה אֲבָל כְּשֶׁתַּחְשֹׁב כָּל זְמַן הַשְּׁהִיּוֹת יִצְטָרֵף מִכֻּלָּן שִׁעוּר שְׁהִיָּה הֲרֵי זוֹ סְפֵק נְבֵלָה. וְכֵן אִם שָׁהָה כְּדֵי שֶׁיַּגְבִּיהֶנָּה וְיַרְבִּיצֶנָּה וּכְדֵי שֶׁיִּשְׁחֹט כְּמוֹ מִעוּט הַסִּימָנִין בִּלְבַד לֹא כְּדֵי שֶׁיִּשְׁחֹט שְׁחִיטָה גְּמוּרָה הֲרֵי זוֹ סְפֵק נְבֵלָה:","שָׁחַט רֹב אֶחָד בְּעוֹף אוֹ רֹב שְׁנַיִם בִּבְהֵמָה אַף עַל פִּי שֶׁשָּׁהָה חֲצִי הַיּוֹם וְחָזַר וְגָמַר חֲתִיכַת הַסִּימָנִין הֲרֵי זוֹ מֻתֶּרֶת. מֵאַחַר שֶׁנִּשְׁחַט בָּהּ כַּשִּׁעוּר הֲרֵי זֶה כִּמְחַתֵּךְ בְּשַׂר הַשְּׁחוּטָה:","שָׁחַט בַּקָּנֶה לְבַדּוֹ חֶצְיוֹ אוֹ מִעוּטוֹ וְשָׁהָה זְמַן מְרֻבֶּה הֲרֵי זֶה חוֹזֵר וְגוֹמֵר הַשְּׁחִיטָה וְאֵין בְּכָךְ כְּלוּם. אֲבָל אִם שָׁחַט רֹב הַקָּנֶה אוֹ שֶׁנִּקֵּב בַּוֵּשֶׁט כָּל שֶׁהוּא וְשָׁהָה כַּשִּׁעוּר בֵּין שֶׁחָזַר וְגָמַר הַשְּׁחִיטָה שֶׁהִתְחִיל בֵּין שֶׁשָּׁחַט שְׁחִיטָה גְּמוּרָה בְּמָקוֹם אַחֵר הֲרֵי זוֹ פְּסוּלָה. מִפְּנֵי שֶׁהַבְּהֵמָה אוֹ הָעוֹף שֶׁנִּפְסַק רֹב הַקָּנֶה שֶׁלָּהּ אוֹ שֶׁנִּקַּב הַוֵּשֶׁט בְּמַשֶּׁהוּ נְבֵלָה וְאֵין הַשְּׁחִיטָה מוֹעֶלֶת בָּהּ כְּמוֹ שֶׁיִּתְבָּאֵר:","הִנֵּה נִתְבָּאֵר לְךָ שֶׁאֵין שְׁהִיָּה בַּקָּנֶה בָּעוֹף כְּלָל. שֶׁאִם שָׁחַט רֹב הַקָּנֶה וְשָׁהָה כְּבָר נִגְמְרָה שְׁחִיטָתוֹ כְּשֶׁחָזַר וְגָמַר מְחַתֵּךְ בָּשָׂר הוּא. וְאִם שָׁחַט בְּמִעוּט הַקָּנֶה וְשָׁהָה הֲרֵי זֶה חוֹזֵר וְשׁוֹחֵט כָּל זְמַן שֶׁיִּרְצֶה שֶׁאֵינָהּ נֶאֱסֶרֶת מִשּׁוּם נְבֵלָה עַד שֶׁיִּפָּסֵק רֹב הַקָּנֶה:","שָׁחַט הָעוֹף וְשָׁהָה בּוֹ וְאֵינוֹ יוֹדֵעַ אִם נִקַּב הַוֵּשֶׁט אוֹ לֹא נִקַּב חוֹזֵר וְשׁוֹחֵט הַקָּנֶה לְבַדּוֹ בְּמָקוֹם אַחֵר וּמַנִּיחוֹ עַד שֶׁיָּמוּת וּבוֹדֵק הַוֵּשֶׁט מִבִּפְנִים. אִם לֹא נִמְצֵאת בּוֹ טִפַּת דָּם בְּיָדוּעַ שֶׁלֹּא נִקַּב וּכְשֵׁרָה:","חֲלָדָה כֵּיצַד. כְּגוֹן שֶׁהִכְנִיס הַסַּכִּין בֵּין סִימָן לְסִימָן. בֵּין שֶׁפָּסַק הַסִּימָן הָעֶלְיוֹן לְמַעְלָה בֵּין שֶׁשָּׁחַט הַתַּחְתּוֹן לְמַטָּה שֶׁהוּא דֶּרֶךְ שְׁחִיטָה הֲרֵי זוֹ פְּסוּלָה:","הִכְנִיס אֶת הַסַּכִּין תַּחַת הָעוֹר וְשָׁחַט שְׁנֵי הַסִּימָנִים כְּדַרְכָּן. אוֹ שֶׁהֶחְלִיד אֶת הַסַּכִּין תַּחַת צֶמֶר מְסֻבָּךְ. אוֹ שֶׁפָּרַס מַטְלִית עַל הַסַּכִּין וְעַל הַצַּוָּאר וְשָׁחַט תַּחַת הַמַּטְלִית הוֹאִיל וְאֵין הַסַּכִּין גְּלוּיָה הֲרֵי זוֹ סְפֵק נְבֵלָה. וְכֵן אִם שָׁחַט מִעוּט הַסִּימָנִים בְּהַחְלָדָה וְגָמַר הַשְּׁחִיטָה שֶׁלֹּא בְּהַחְלָדָה הֲרֵי זוֹ סְפֵק נְבֵלָה:","דְּרָסָה כֵּיצַד. כְּגוֹן שֶׁהִכָּה בְּסַכִּין עַל הַצַּוָּאר כְּדֶרֶךְ שֶׁמַּכִּין בְּסַיִף וְחָתַךְ הַסִּימָנִין בְּבַת אַחַת בְּלֹא הוֹלָכָה וְלֹא הוֹבָאָה. אוֹ שֶׁהִנִּיחַ הַסַּכִּין עַל הַצַּוָּאר וְדָחַק וְחָתַךְ לְמַטָּה כְּחוֹתֵךְ צְנוֹן אוֹ קִישׁוּת עַד שֶׁחָתַךְ הַסִּימָנִין הֲרֵי זוֹ פְּסוּלָה:","הַגְרָמָה כֵּיצַד. זֶה הַשּׁוֹחֵט בַּקָּנֶה לְמַעְלָה בְּמָקוֹם שֶׁאֵינוֹ רָאוּי לִשְׁחִיטָה. וּכְמוֹ שְׁנֵי חִטִּים יֵשׁ בְּסוֹף הַקָּנֶה לְמַעְלָה בְּטַבַּעַת גְּדוֹלָה. שָׁחַט בְּתוֹךְ הַחִטִּים אִם שִׁיֵּר מֵהֶן כָּל שֶׁהוּא לְמַעְלָה הֲרֵי זוֹ כְּשֵׁרָה. שֶׁהֲרֵי שָׁחַט מִשִּׁפּוּי כּוֹבַע וּלְמַטָּה. וְהוּא מִן הַמָּקוֹם הָרָאוּי לִשְׁחִיטָה. וְאִם לֹא שִׁיֵּר מֵהֶן כְּלוּם אֶלָּא שָׁחַט לְמַעְלָה מֵהֶן הֲרֵי זוֹ מֻגְרֶמֶת וּפְסוּלָה:","שָׁחַט רֹב הָאֶחָד אוֹ רֹב הַשְּׁנַיִם וְהִשְׁלִים הַשְּׁחִיטָה בִּדְרָסָה אוֹ בְּהַגְרָמָה הֲרֵי זוֹ כְּשֵׁרָה שֶׁהֲרֵי נִשְׁחַט הַשִּׁעוּר כָּרָאוּי. הִגְרִים בַּתְּחִלָּה שְׁלִישׁ וְשָׁחַט שְׁנֵי שְׁלִישִׁים הֲרֵי זוֹ כְּשֵׁרָה. שָׁחַט שְׁלִישׁ וְהִגְרִים שְׁלִישׁ וְחָזַר וְשָׁחַט שְׁלִישׁ הָאַחֲרוֹן כְּשֵׁרָה. הִגְרִים שְׁלִישׁ וְשָׁחַט שְׁלִישׁ וְחָזַר וְהִגְרִים שְׁלִישׁ הָאַחֲרוֹן הֲרֵי זוֹ פְּסוּלָה. וְאִם דָּרַס אוֹ הֶחְלִיד בֵּין בַּשְּׁלִישׁ הָרִאשׁוֹן בֵּין בַּשְּׁלִישׁ הָאֶמְצָעִי הֲרֵי זוֹ פְּסוּלָה:","עִקּוּר כֵּיצַד. כְּגוֹן שֶׁנֶּעֶקְרָה הַגַּרְגֶּרֶת וְהִיא הַקָּנֶה אוֹ הַוֵּשֶׁט וְנִשְׁמַט אֶחָד מֵהֶן אוֹ שְׁנֵיהֶן קֹדֶם גְּמַר שְׁחִיטָה. אֲבָל אִם שָׁחַט אֶחָד בָּעוֹף אוֹ רֻבּוֹ וְאַחַר כָּךְ נִשְׁמַט הַסִּימָן הַשֵּׁנִי שְׁחִיטָתוֹ כְּשֵׁרָה:","נִשְׁמַט אֶחָד מֵהֶן וְאַחַר כָּךְ שָׁחַט אֶת הַשֵּׁנִי שְׁחִיטָתוֹ פְּסוּלָה. שָׁחַט אֶחָד מֵהֶן וְנִמְצָא הַשֵּׁנִי שָׁמוּט וְאֵין יָדוּעַ אִם קֹדֶם שְׁחִיטָה נִשְׁמַט אוֹ אַחַר שְׁחִיטָה הֲרֵי זוֹ סְפֵק נְבֵלָה:","נִמְצָא הַסִּימָן הַשָּׁחוּט שָׁמוּט הֲרֵי זוֹ כְּשֵׁרָה. שֶׁוַּדַּאי אַחַר שְׁחִיטָה נֶעֱקַר. שֶׁאִלּוּ נֶעֱקַר קֹדֶם שְׁחִיטָה הָיָה מִתְדַּלְדֵּל וְלֹא נִשְׁחָט:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁלֹּא תָּפַס הַסִּימָנִין בְּיָדוֹ כְּשֶׁשָּׁחַט. אֲבָל אִם תְּפָסָן וְשָׁחַט אֶפְשָׁר שֶׁתִּשָּׁחֵט אַחַר הָעִקּוּר וּלְפִיכָךְ אִם נִמְצֵאת שְׁמוּטָה וּשְׁחוּטָה הֲרֵי זוֹ סְפֵק נְבֵלָה:","כָּל מָקוֹם שֶׁאָמַרְנוּ בִּשְׁחִיטָה פְּסוּלָה הֲרֵי זוֹ נְבֵלָה. וְאִם אָכַל מִמֶּנָּה כְּזַיִת לוֹקֶה מִשּׁוּם אוֹכֵל נְבֵלָה שֶׁאֵין מוֹצִיא מִידֵי נְבֵלָה אֶלָּא שְׁחִיטָה כְּשֵׁרָה כַּאֲשֶׁר צִוָּה משֶׁה רַבֵּנוּ עָלָיו הַשָּׁלוֹם כְּמוֹ שֶׁבֵּאַרְנוּ. וְכָל סָפֵק בִּשְׁחִיטָה הֲרֵי הוּא סְפֵק נְבֵלָה וְהָאוֹכֵל מִמֶּנָּה מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","בְּהֵמָה שֶׁנִּטַּל יָרֵךְ שֶׁלָּהּ וַחֲלָלָה עִמָּהּ עַד שֶׁתֵּרָאֶה חֲסֵרָה כְּשֶׁתִּרְבַּץ הֲרֵי זוֹ נְבֵלָה כְּמוֹ שֶׁנֶּחְתַּךְ חֶצְיָהּ וְנֶחְלְקָה לִשְׁנֵי גּוּפוֹת וְאֵין הַשְּׁחִיטָה מוֹעֶלֶת בָּהּ. וְכֵן אִם נִשְׁבְּרָה מִפְרֶקֶת וְרֹב בָּשָׂר עִמָּהּ אוֹ שֶׁנִּקְרְעָה מִגַּבָּהּ כְּדָג אוֹ שֶׁנִּפְסַק רֹב הַקָּנֶה אוֹ שֶׁנִּקַּב הַוֵּשֶׁט בְּכָל שֶׁהוּא בְּמָקוֹם הָרָאוּי לִשְׁחִיטָה הֲרֵי זוֹ נְבֵלָה מֵחַיִּים וְאֵין הַשְּׁחִיטָה מוֹעֶלֶת בָּהּ. וְאֶחָד הַבְּהֵמָה וְאֶחָד הָעוֹף בְּכָל הַדְּבָרִים הָאֵלֶּה:","שְׁנֵי עוֹרוֹת יֵשׁ לוֹ לַוֵּשֶׁט. הַחִיצוֹן אָדֹם וְהַפְּנִימִי לָבָן. נִקַּב הָאֶחָד מֵהֶן בִּלְבַד כְּשֵׁרָה. נִקְּבוּ שְׁנֵיהֶן בְּכָל שֶׁהוּא בְּמָקוֹם הָרָאוּי לִשְׁחִיטָה הֲרֵי זוֹ נְבֵלָה. וּבֵין שֶׁנִּשְׁחֲטָה בִּמְקוֹם הַנֶּקֶב בֵּין שֶׁנִּשְׁחֲטָה בְּמָקוֹם אַחֵר אֵין הַשְּׁחִיטָה מוֹעֶלֶת בָּהּ. נִקְּבוּ שְׁנֵיהֶם זֶה שֶׁלֹּא כְּנֶגֶד זֶה נְבֵלָה:","נִקַּב הַוֵּשֶׁט וְעָלָה בּוֹ קְרוּם וּסְתָמוֹ אֵין הַקְּרוּם כְּלוּם וַהֲרֵי הוּא נָקוּב כְּשֶׁהָיָה. נִמְצָא קוֹץ עוֹמֵד בַּוֵּשֶׁט הֲרֵי זוֹ סְפֵק נְבֵלָה שֶׁמָּא נִקַּב הַוֵּשֶׁט וְעָלָה קְרוּם בִּמְקוֹם הַנֶּקֶב וְאֵינוֹ נִרְאֶה. אֲבָל אִם נִמְצָא הַקּוֹץ לְאָרְכּוֹ בַּוֵּשֶׁט אֵין חוֹשְׁשִׁין לוֹ שֶׁרֹב הַבְּהֵמוֹת הַמִּדְבָּרִיּוֹת אוֹכְלוֹת הַקּוֹצִים תָּמִיד:","וֵשֶׁט אֵין לוֹ בְּדִיקָה מִבַּחוּץ אֶלָּא מִבִּפְנִים. כֵּיצַד. הוֹפְכוֹ וּבוֹדֵק. אִם נִמְצָא עָלָיו טִפַּת דָּם בְּיָדוּעַ שֶׁהָיָה נָקוּב:","גַּרְגֶּרֶת שֶׁנִּפְסַק רֹב חֲלָלָה בַּמָּקוֹם הָרָאוּי לִשְׁחִיטָה הֲרֵי זוֹ נְבֵלָה. וְכֵן אִם נִקְּבָה כְּאִיסָר. נִקְּבָה נְקָבִים קְטַנִּים אִם נְקָבִים שֶׁאֵין בָּהֶן חֶסְרוֹן הֵם מִצְטָרְפִין לְרֻבָּהּ וְאִם נְקָבִים שֶׁיֵּשׁ בָּהֶם חֶסְרוֹן מִצְטָרְפִין לִכְאִיסָר. וְכֵן אִם נִטְּלָה מִמֶּנָּה רְצוּעָה מִצְטָרֶפֶת לִכְאִיסָר. וּבְעוֹף כָּל שֶׁאִלּוּ מְקַפֵּל הָרְצוּעָה אוֹ הַנְּקָבִים שֶׁיֵּשׁ בָּהֶן חֶסְרוֹן וּמַנִּיחָן עַל פִּי הַקָּנֶה אִם חוֹפֶה אֶת רֻבּוֹ נְבֵלָה וְאִם לָאו כְּשֵׁרָה:","נִקְּבָה הַגַּרְגֶּרֶת נֶקֶב מְפֻלָּשׁ מִשְּׁנֵי צְדָדֶיהָ כְּדֵי שֶׁיִּכָּנֵס אִיסָר לְרָחְבּוֹ נְבֵלָה. נִסְדְּקָה לְאָרְכָּהּ אֲפִלּוּ לֹא נִשְׁתַּיֵּר מִן הַמָּקוֹם הָרָאוּי בָּהּ לִשְׁחִיטָה אֶלָּא מַשֶּׁהוּ לְמַעְלָה וּמַשֶּׁהוּ לְמַטָּה כְּשֵׁרָה:","גַּרְגֶּרֶת שֶׁנִּקְּבָה וְאֵין יָדוּעַ אִם קֹדֶם שְׁחִיטָה נִקְּבָה אוֹ אַחַר שְׁחִיטָה נִקְּבָה. נוֹקְבִין אוֹתָהּ עַתָּה בְּמָקוֹם אַחֵר וּמְדַמִּין הַנֶּקֶב לְנֶקֶב אִם נִדְמֶה לוֹ מֻתֶּרֶת. וְאֵין מְדַמִּין אֶלָּא מֵחֻלְיָא גְּדוֹלָה לְחֻלְיָא גְּדוֹלָה אוֹ מִקְּטַנָּה לִקְטַנָּה. אֲבָל לֹא מִקְּטַנָּה לִגְדוֹלָה שֶׁכָּל הַקָּנֶה חֻלְיוֹת חֻלְיוֹת הוּא וּבֵין כָּל חֻלְיָא וְחֻלְיָא חֻלְיָא אַחַת קְטַנָּה מִשְּׁתֵּיהֶן וְרַכָּה:"],"Mishneh Torah, Robbery and Lost Property 14":["הַשִׂמְלָה בִּכְלַל (דברים כב ג) \"כָּל אֲבֵדַת אָחִיךָ\" הָיְתָה וְכֵן הַשּׁוֹר וְהַשֶּׂה וְהַחֲמוֹר. וְלָמָּה פֵּרֵט הַכָּתוּב (דברים כב ג) \"חֲמוֹר\" לְהַחְזִירוֹ בְּסִימָנֵי מִרְדַּעַת אַף עַל פִּי שֶׁהַסִּימָן בְּדָבָר הַטָּפֵל לוֹ יַחְזִיר. וְלָמָּה פֵּרֵט שׁוֹר וְשֶׂה לְהַחְזִיר אֲפִלּוּ גִּזַּת הַשֶּׂה אוֹ גֵּז זְנַב שׁוֹר אַף עַל פִּי שֶׁהוּא דָּבָר מוּעָט. וְלָמָּה פֵּרֵט הַשִּׂמְלָה לִלְמֹד מִמֶּנָּה מָה הַשִּׂמְלָה מְיֻחֶדֶת שֶׁיֵּשׁ לָהּ סִימָנִין וְחֶזְקָתָהּ שֶׁיֵּשׁ לָהּ תּוֹבְעִין וְחַיָּב לְהַחְזִיר אַף כָּל דָּבָר שֶׁיֵּשׁ לוֹ סִימָנִים הֲרֵי הוּא בְּחֶזְקַת שֶׁיֵּשׁ לוֹ תּוֹבְעִין וְחַיָּב לְהַחְזִיר. אֲבָל דָּבָר שֶׁאֵין לוֹ תּוֹבְעִין אֶלָּא נִתְיָאֲשׁוּ מִמֶּנּוּ הַבְּעָלִים הֲרֵי הוּא שֶׁל מוֹצְאוֹ אַף עַל פִּי שֶׁיֵּשׁ בּוֹ סִימָנִים:","זֶה הַכְּלָל בַּאֲבֵדָה כָּל דָּבָר שֶׁאֵין בּוֹ סִימָן כֵּיוָן שֶׁאָבַד וְיָדְעוּ בּוֹ הַבְּעָלִים שֶׁאָבַד הֲרֵי זֶה בְּחֶזְקַת שֶׁנִּתְיָאֲשׁוּ בְּעָלָיו מִמֶּנּוּ. כְּגוֹן מַסְמֵר אֶחָד אוֹ מַחַט אַחַת אוֹ מַטְבֵּעַ שֶׁהֲרֵי אֵינָן יְכוֹלִים לִתֵּן סִימָן לְהַחְזִירוֹ לָהֶן וּלְפִיכָךְ הֲרֵי הוּא לָזֶה שֶׁמְּצָאוֹ:","וְכָל דָּבָר שֶׁיֵּשׁ בּוֹ סִימָן כְּגוֹן שִׂמְלָה וּבְהֵמָה הֲרֵי זֶה בְּחֶזְקַת שֶׁלֹּא נִתְיָאֲשׁוּ מִמֶּנּוּ בְּעָלָיו שֶׁהֲרֵי דַּעְתָּן תְּלוּיָה לִתֵּן סִימָנִין שֶׁיֵּשׁ בּוֹ וְיַחְזֹר לָהֶן לְפִיכָךְ הַמּוֹצְאוֹ חַיָּב לְהַכְרִיז אֶלָּא אִם כֵּן יָדַע שֶׁנִּתְיָאֲשׁוּ הַבְּעָלִים כְּגוֹן שֶׁשָּׁמַע אוֹתָם אוֹמְרִים וַי לְחֶסְרוֹן כִּיס וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ שֶׁמַּרְאִין שֶׁנִּתְיָאֲשׁוּ הֲרֵי אוֹתָהּ הָאֲבֵדָה שֶׁל מוֹצְאָהּ:","וְכֵן אִם מָצָא דָּבָר שֶׁיֵּשׁ בּוֹ סִימָן בַּיָּם וּבַנָּהָר וְכַיּוֹצֵא בָּהֶן אוֹ בְּמָקוֹם שֶׁרֻבּוֹ עַכּוּ\"ם הֲרֵי זֶה בְּחֶזְקַת שֶׁנִּתְיָאֲשׁוּ בְּעָלָיו מִמֶּנּוּ מִשָּׁעָה שֶׁנָּפַל. וּלְפִיכָךְ הֲרֵי הוּא שֶׁל מוֹצְאָן וְאַף עַל פִּי שֶׁלֹּא שָׁמְעוּ הַבְּעָלִים שֶׁנִּתְיָאֲשׁוּ מִמֶּנּוּ:","יֵאוּשׁ שֶׁלֹּא מִדַּעַת אֲפִלּוּ בְּדָבָר שֶׁאֵין בּוֹ סִימָן אֵינוֹ יֵאוּשׁ. כֵּיצַד. נָפַל מִמֶּנּוּ דִּינָר וְלֹא יָדַע בּוֹ שֶׁנָּפַל אַף עַל פִּי שֶׁכְּשֶׁיָּדַע בּוֹ שֶׁנָּפַל יִתְיָאֵשׁ הֲרֵי זֶה אֵינוֹ יֵאוּשׁ עַתָּה עַד שֶׁיֵּדְעוּ הַבְּעָלִים שֶׁנָּפַל. אֲבָל אִם עֲדַיִן אוֹמְרִים הַבְּעָלִים שֶׁמָּא נְתַתִּיו לִפְלוֹנִי אוֹ בְּמִגְדָּל הוּא מֻנָּח אוֹ שֶׁמָּא טָעִיתִי בַּחֶשְׁבּוֹן וְכַיּוֹצֵא בְּאֵלּוּ הַדְּבָרִים אֵין זֶה יֵאוּשׁ:","הָרוֹאֶה חֲבֵרוֹ שֶׁנָּפַל מִמֶּנּוּ דִּינָר עַל הָאָרֶץ וְלֹא יָדַע בּוֹ וְנָטַל הַדִּינָר קֹדֶם יֵאוּשׁ עוֹבֵר עַל עֲשֵׂה וְעַל שְׁנֵי לָאוִין כְּמוֹ שֶׁבֵּאַרְנוּ. וַאֲפִלּוּ הֶחְזִיר לוֹ הַדִּינָר לְאַחַר שֶׁנִּתְיָאֵשׁ מַתָּנָה הִיא זוֹ וּכְבָר עָבַר עַל הָאִסּוּרִים:","נָטַל הַדִּינָר לִפְנֵי יֵאוּשׁ עַל מְנָת לְהַחְזִירוֹ וּלְאַחַר יֵאוּשׁ נִתְכַּוֵּן לִגְזל אוֹתוֹ עוֹבֵר מִשּׁוּם (דברים כב א) \"הָשֵׁב תְּשִׁיבֵם\". הִמְתִּין לָהּ וְלֹא הוֹדִיעַ לַבְּעָלִים וְלֹא נָטַל הַדִּינָר עַד שֶׁיָּדְעוּ הַבְּעָלִים שֶׁנָּפַל שֶׁהֲרֵי נִתְיָאֲשׁוּ כְּמוֹ שֶׁבֵּאַרְנוּ וְאַחַר כָּךְ נָטַל הַדִּינָר מֵעַל הָאָרֶץ אֵינוֹ עוֹבֵר אֶלָּא מִשּׁוּם (דברים כב ג) \"לֹא תוּכַל לְהִתְעַלֵּם\". וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","רָאָה סֶלַע אוֹ מַטְבֵּעַ שֶׁנָּפַל אֲפִלּוּ מִשְּׁלֹשָׁה בְּנֵי אָדָם וְאַף עַל פִּי שֶׁאֵין בּוֹ שְׁוֵה פְּרוּטָה לְכָל אֶחָד וְאֶחָד חַיָּב לְהַחְזִיר שֶׁמָּא שֻׁתָּפִין הֵן וּמָחַל אֶחָד מֵהֶן חֶלְקוֹ לַחֲבֵרוֹ וְנִמְצֵאת אֲבֵדָתוֹ שֶׁל זֶה שְׁוֵה פְּרוּטָה:","רָאָה חֲבֵרוֹ שֶׁנָּפַל מִמֶּנּוּ דִּינָר בְּתוֹךְ הַחל אוֹ בְּתוֹךְ הֶעָפָר וְנִתְעַלֵּם מִמֶּנּוּ הֲרֵי זֶה כְּנוֹפֵל לַיָּם אוֹ לַנָּהָר וַהֲרֵי הוּא שֶׁל מוֹצְאוֹ. שֶׁהֲרֵי נִתְיָאֵשׁ מִמֶּנּוּ מִפְּנֵי שֶׁאֵין בּוֹ סִימָן. וַאֲפִלּוּ רָאָה אוֹתוֹ מֵבִיא כְּבָרָה לְחַפֵּשׂ אַחֲרָיו. בְּדַעַת רְעוּעָה הוּא מְחַפֵּשׂ כְּדֶרֶךְ שֶׁמְּחַפְּשִׂים בֶּעָפָר שְׁאָר הַבַּלָּשִׁין שֶׁלֹּא נָפַל מֵהֶן כְּלוּם שֶׁמָּא יִמְצְאוּ מַה שֶּׁנָּפַל לַאֲחֵרִים כָּךְ הוּא זֶה מְחַפֵּשׂ לֹא מִפְּנֵי שֶׁלֹּא נִתְיָאֵשׁ:","הַמּוֹצֵא סֶלַע בַּשּׁוּק. מְצָאוֹ חֲבֵרוֹ וְאָמַר לוֹ שֶׁלִּי הִיא וַחֲדָשָׁה הִיא וְשֶׁל מְדִינָה פְּלוֹנִית הִיא וְשֶׁל מֶלֶךְ פְּלוֹנִי הִיא. אֲפִלּוּ אָמַר שְׁמִי כָּתוּב עָלֶיהָ לֹא אָמַר כְּלוּם וְאֵינוֹ חַיָּב לְהַחְזִיר. שֶׁאֵין סִימָנֵי הַמַּטְבֵּעַ סִימָן מִפְּנֵי שֶׁחֶזְקָתוֹ לְהוֹצָאָה. וְאָנוּ אוֹמְרִין שֶׁלּוֹ הָיְתָה וְהוֹצִיאָהּ מִיָּדוֹ וְנָפְלָה מִיַּד אַחֵר. וְהוֹאִיל וְאֵינוֹ סִימָן שֶׁסּוֹמְכִין עָלָיו מִשְּׁעַת נְפִילָה נִתְיָאֵשׁ וַהֲרֵי הִיא שֶׁל מוֹצְאָהּ:","הַמּוֹצֵא דָּבָר שֶׁאֵין בּוֹ סִימָן בְּצַד דָּבָר שֶׁיֵּשׁ בּוֹ סִימָן חַיָּב לְהַכְרִיז. בָּא בַּעַל הַסִּימָן וְנָטַל אֶת שֶׁלּוֹ וְאָמַר שֶׁזֶּה בִּלְבַד נָפַל מִמֶּנּוּ זָכָה הַמּוֹצֵא בַּדָּבָר שֶׁאֵין בּוֹ סִימָן:","הַמּוֹצֵא כְּלֵי חֶרֶשׂ וְכַיּוֹצֵא בָּהֶן מִכֵּלִים שֶׁצּוּרַת כֻּלָּן שָׁוָה. אִם כֵּלִים חֲדָשִׁים הֵן הֲרֵי הֵם שֶׁלּוֹ שֶׁהֲרֵי הֵן כְּמוֹ דִּינָר מִשְּׁאָר הַדִּינָרִים שֶׁאֵין לוֹ סִימָן וְאֵין הַבְּעָלִים מַכִּירִים אוֹתָן. שֶׁהֲרֵי אֵינוֹ יוֹדֵעַ אִם פַּךְ זֶה אוֹ צְלוֹחִית זוֹ שֶׁלּוֹ אוֹ שֶׁל אַחֵר. וְאִם הָיוּ כֵּלִים שֶׁשְּׂבָעָתַן הָעַיִן חַיָּב לְהַכְרִיז. שֶׁאִם יָבוֹא תַּלְמִיד חָכָם וְיֹאמַר אַף עַל פִּי שֶׁאֵינוֹ יָכוֹל לִתֵּן בִּכְלִי כָּזֶה סִימָן יֵשׁ לִי בּוֹ טְבִיעוּת עַיִן חַיָּב לְהַרְאוֹתוֹ לוֹ, אִם הִכִּירוֹ וְאָמַר שֶׁלִּי הוּא מַחֲזִירִין לוֹ:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּתַלְמִיד וָתִיק שֶׁאֵינוֹ מְשַׁנֶּה בְּדִבּוּרוֹ כְּלָל אֶלָּא בְּדִבְרֵי שָׁלוֹם אוֹ בְּמַסֶכְתָּא אוֹ בְּמִטָּה אוֹ בְּבַיִת שֶׁהוּא מִתְאָרֵחַ בּוֹ. כֵּיצַד. הָיָה עוֹסֵק בְּמַסֶּכְתָּא דְּנִדָּה וְאָמַר בְּמִקְוָאוֹת אֲנִי שׁוֹנֶה כְּדֵי שֶׁלֹּא יִשְׁאָלוּהוּ שְׁאֵלוֹת בְּעִנְיַן נִדָּה. אוֹ שֶׁיָּשַׁן בְּמִטָּה זוֹ וְאוֹמֵר בְּזוֹ אֲנִי יָשֵׁן שֶׁמָּא יִמָּצֵא שָׁם קֶרִי. אוֹ שֶׁנִּתְאָרֵחַ אֵצֶל שִׁמְעוֹן וְאָמַר אֵצֶל רְאוּבֵן אֲנִי מִתְאָרֵחַ כְּדֵי שֶׁלֹּא יַטְרִיחַ עַל זֶה שֶׁנִּתְאָרֵחַ אֶצְלוֹ. אוֹ שֶׁהֵבִיא שָׁלוֹם בֵּין אָדָם לַחֲבֵרוֹ וְהוֹסִיף וְגָרַע כְּדֵי לְחַבְּבָן זֶה לָזֶה הֲרֵי זֶה מֻתָּר. אֲבָל אִם בָּאוּ עֵדִים שֶׁשִּׁנָּה בְּדִבּוּרוֹ חוּץ מִדְּבָרִים אֵלּוּ אֵין מַחֲזִירִין לוֹ בִּטְבִיעוּת עַיִן:"],"Mishneh Torah, Robbery and Lost Property 9":["הַגּוֹזֵל קַרְקַע מֵחֲבֵרוֹ וְהִפְסִידָהּ. כְּגוֹן שֶׁחָפַר בָּהּ בּוֹרוֹת שִׁיחִין וּמְעָרוֹת אוֹ שֶׁקָּצַץ אֶת הָאִילָנוֹת וְשִׁחֵת אֶת הַמַּעְיָנוֹת וְהָרַס הַבִּנְיָן. חַיָּב לְהַעֲמִיד לוֹ בַּיִת אוֹ שָׂדֶה כְּשֶׁהָיוּ בִּשְׁעַת הַגְּזֵלָה אוֹ יְשַׁלֵּם דְּמֵי מַה שֶּׁהִפְסִיד. אֲבָל אִם נִשְׁחֲתָה מֵאֵלֶיהָ כְּגוֹן שֶׁשְּׁטָפָהּ נָהָר אוֹ נִשְׂרְפָה בְּאֵשׁ שֶׁיָּרְדָה מִן הַשָּׁמַיִם אוֹמֵר לוֹ הֲרֵי שֶׁלְּךָ לְפָנֶיךָ שֶׁהַקַּרְקַע בְּחֶזְקַת בְּעָלִים קַיֶּמֶת וְאֵין אַחֲרָיוּת הֶפְסֵדָהּ עָלָיו אֶלָּא אִם כֵּן הִפְסִיד בְּיָדוֹ. מַה שֶּׁאֵין הַדִּין כֵּן בְּמִטַּלְטְלִין כְּמוֹ שֶׁבֵּאַרְנוּ:","גָּזַל שָׂדֶה וְנִגְזְלָה מִמֶּנּוּ וּנְטָלוּהָ מְצִיקִים בְּכֹחַ הַמֶּלֶךְ. אִם מַכַּת מְדִינָה הִיא כְּגוֹן שֶׁלָּקַח הַמֶּלֶךְ שָׂדוֹת אוֹ בָּתִּים שֶׁל כָּל אַנְשֵׁי הַמְּדִינָה אוֹמֵר לוֹ הֲרֵי שֶׁלְּךָ לְפָנֶיךָ. וְאִם מֵחֲמַת הַגַּזְלָן נִלְקְחָה חַיָּב לְהַעֲמִיד לוֹ שָׂדֶה אַחֶרֶת:","אָנַס הַמֶּלֶךְ אֶת הַגַּזְלָן וְאָמַר לוֹ הַרְאֵה לָנוּ כָּל מַה שֶּׁיֵּשׁ לְךָ וְהֶרְאָה שָׂדֶה זוֹ שֶׁגָּזַל בִּכְלַל שְׂדוֹתָיו וּנְטָלָהּ הַמֶּלֶךְ. חַיָּב לְהַעֲמִיד לוֹ שָׂדֶה אַחֶרֶת כְּמוֹתָהּ אוֹ נוֹתֵן דָּמֶיהָ:","גָּזַל שָׂדֶה וְהִפְסִידָהּ בְּיָדוֹ כְּשֶׁבַּעַל הַשָּׂדֶה גּוֹבֶה אֶת דְּמֵי מַה שֶּׁהִפְסִיד הַגַּזְלָן גּוֹבֶה אוֹתָן מִנְּכָסִים בְּנֵי חוֹרִין מִפְּנֵי שֶׁהִיא כְּמִלְוֶה עַל פֶּה. וְאִם עָמַד הַגַּזְלָן בַּדִּין וְנִתְחַיֵּב לְשַׁלֵּם וְאַחַר כָּךְ מָכַר גּוֹבֶה מִנְּכָסִים מְשֻׁעְבָּדִין:","גָּזַל שָׂדֶה וְאָכַל פֵּרוֹתֶיהָ מְשַׁלֵּם כָּל הַפֵּרוֹת שֶׁאָכַל מִנְּכָסִים בְּנֵי חוֹרִין. גָּזַל וְהִשְׁבִּיחַ שָׁמִין לוֹ וְיָדוֹ עַל הַתַּחְתּוֹנָה אִם הַשֶּׁבַח יֶתֶר עַל הַהוֹצָאָה נוֹטֵל הַהוֹצָאָה בִּלְבַד מִן הַנִּגְזָל וְאִם הַהוֹצָאָה יְתֵרָה עַל הַשֶּׁבַח אֵין לוֹ מִן הַהוֹצָאָה אֶלָּא שִׁעוּר הַשֶּׁבַח:","גָּזַל שָׂדֶה וּמְכָרָהּ וְהִשְׁבִּיחָהּ הַלּוֹקֵחַ אִם הַשֶּׁבַח יָתֵר עַל הַהוֹצָאָה נוֹטֵל הַהוֹצָאָה מִבַּעַל הַשָּׂדֶה וְהַקֶּרֶן נוֹטֵל עִם שְׁאָר הַשֶּׁבַח מִן הַגַּזְלָן:","הַקֶּרֶן גּוֹבֶה מִנְּכָסִים מְשֻׁעְבָּדִים וּשְׁאָר הַשֶּׁבַח מִנְּכָסִים בְּנֵי חוֹרִין. וְאִם הִכִּיר בָּהּ שֶׁהִיא גְּזוּלָה כְּשֶׁלְּקָחָהּ אֵינוֹ נוֹטֵל מִן הַגַּזְלָן אֶלָּא הַקֶּרֶן בִּלְבַד וּמַפְסִיד שְׁאָר הַשֶּׁבַח הַיָּתֵר עַל הַהוֹצָאָה. הָיְתָה הַהוֹצָאָה יְתֵרָה עַל הַשֶּׁבַח בֵּין שֶׁהִכִּיר בָּהּ שֶׁהִיא גְּזוּלָה בֵּין שֶׁלֹּא הִכִּיר בָּהּ אֵין לוֹ מִן הַהוֹצָאָה אֶלָּא שִׁעוּר הַשֶּׁבַח נוֹטֵל מִבַּעַל הַשָּׂדֶה וְהַקֶּרֶן נוֹטֵל מִן הַגַּזְלָן מִנְּכָסִים מְשֻׁעְבָּדִין:","הַגּוֹזֵל שָׂדֶה וּמְכָרָהּ וְאָכַל הַלּוֹקֵחַ פֵּרוֹתֶיהָ מְחַשְּׁבִין עָלָיו כָּל הַפֵּרוֹת שֶׁאָכַל וּמְשַׁלֵּם לְבַעַל הַשָּׂדֶה וְחוֹזֵר וְגוֹבֶה אוֹתָן מִן הַגַּזְלָן מִנְּכָסִים בְּנֵי חוֹרִין. וְאִם הִכִּיר בָּהּ שֶׁגְּזוּלָה הִיא אֵין לוֹ פֵּרוֹת וְאֵינוֹ גּוֹבֶה מִן הַגַּזְלָן אֶלָּא הַקֶּרֶן בִּלְבַד:","הַמּוֹכֵר שָׂדֶה שֶׁאֵינָהּ שֶׁלּוֹ אֵין מִמְכָּרוֹ מִמְכָּר וְלֹא קָנָה לוֹקֵחַ כְּלוּם כְּמוֹ שֶׁבֵּאַרְנוּ. חָזַר הַגַּזְלָן אַחַר שֶׁמְּכָרָהּ וּלְקָחָהּ מִבְּעָלֶיהָ נִתְקַיְּמָה בְּיַד הַלּוֹקֵחַ מִן הַגַּזְלָן. וַאֲפִלּוּ נְתָנָהּ לוֹ הַגַּזְלָן מַתָּנָה כְּשֶׁהָיְתָה גְּזוּלָה בְּיָדוֹ כֵּיוָן שֶׁחָזַר וּלְקָחָהּ נִתְקַיְּמָה בְּיַד זֶה שֶׁקִּבֵּל הַמַּתָּנָה שֶׁמִּפְּנֵי זֶה טָרַח הַגַּזְלָן עַד שֶׁקְּנָאָהּ כְּדֵי לַעֲמֹד בְּנֶאֱמָנוּתוֹ:","לְפִיכָךְ אִם תָּבַע הַלּוֹקֵחַ אֶת הַגַּזְלָן מִפְּנֵי שֶׁמָּכַר לוֹ שָׂדֶה שֶׁאֵינָהּ שֶׁלּוֹ וְנִתְחַיֵּב לְשַׁלֵּם וְהִתְחִיל בֵּית דִּין לְהַכְרִיז עַל נִכְסֵי הַגַּזְלָן כְּדֵי לְהַגְבּוֹת מֵהֶן לַלּוֹקֵחַ וְאַחַר שֶׁהִתְחִילוּ הַהַכְרָזָה לְקָחָהּ הַגַּזְלָן מִן הַבְּעָלִים לֹא נִתְקַיְּמָה בְּיַד הַלּוֹקֵחַ. שֶׁמֵּאַחַר שֶׁהִכְרִיזוּ עַל נְכָסָיו נִתְגַּלָּה שֶׁאֵינוֹ נֶאֱמָן וְלֹא לְקָחָהּ מִן הַבְּעָלִים כְּדֵי לְהַעֲמִידָהּ בְּיַד הַלּוֹקֵחַ:","לְקָחָהּ הַגַּזְלָן מִן הַבְּעָלִים אַחַר שֶׁמְּכָרָהּ כְּשֶׁהִיא גְּזוּלָה וְחָזַר וּמְכָרָהּ לְאַחֵר אוֹ נְתָנָהּ בְּמַתָּנָה אוֹ הוֹרִישָׁהּ. הֲרֵי גִּלָּה דַּעְתּוֹ שֶׁאֵינוֹ רוֹצֶה לְהַעֲמִידָהּ בְּיַד זֶה שֶׁלְּקָחָהּ מִמֶּנּוּ כְּשֶׁהָיְתָה גְּזוּלָה. וְכֵן אִם נָפְלָה לַגַּזְלָן בִּירֻשָּׁה לֹא נִתְקַיְּמָה בְּיַד הַלּוֹקֵחַ:","גְּבָאָהּ הַגַּזְלָן בְּחוֹבוֹ. אִם יֵשׁ לַנִּגְזָל קַרְקַע אַחֶרֶת וְאָמַר לוֹ הַגַּזְלָן זוֹ אֲנִי גּוֹבֶה בְּחוֹבִי הֲרֵי זֶה מִתְכַּוֵּן לְהַעֲמִידָהּ בְּיַד הַלּוֹקֵחַ. וְאִם אֵין לַנִּגְזָל קַרְקַע אֶלָּא זוֹ לִגְבּוֹת חוֹבוֹ הוּא שֶׁנִּתְכַּוֵּן:","נְתָנוּהָ הַבְּעָלִים לַגַּזְלָן מַתָּנָה קְנָאָהּ הַלּוֹקֵחַ שֶׁאִלּוּ לֹא טָרַח לַבְּעָלִים לֹא הָיוּ נוֹתְנִים לוֹ בְּמַתָּנָה וּמִפְּנֵי זֶה טָרַח כְּדֵי שֶׁיִּזְכֶּה בָּהּ בְּדִין וְיַעֲמֹד בְּנֶאֱמָנוּתוֹ וְתִתְקַיֵּם בְּיַד הַלּוֹקֵחַ:","הַגּוֹזֵל שָׂדֶה וְאַחַר שֶׁגְּזָלָהּ וְהֻחְזַק גַּזְלָן עָלֶיהָ חָזַר וּלְקָחָהּ מִבְּעָלִים הָרִאשׁוֹנִים וְטָעַן הַנִּגְזָל וְאָמַר אָנוּס הָיִיתִי בְּשָׁעָה שֶׁמְּכַרְתִּיהָ לוֹ וְשֶׁלֹּא לְדַעְתִּי מָכַרְתִּי מֵחֲמַת גַּזְלָנוּתוֹ לֹא זָכָה הַגַּזְלָן אַף עַל פִּי שֶׁיֵּשׁ לוֹ עֵדִים שֶׁבִּפְנֵיהֶם לְקָחָהּ וְתַחְזֹר הַשָּׂדֶה לַבְּעָלִים וּמַחְזִירִין לַגַּזְלָן הַדָּמִים שֶׁנָּתַן:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהֵעִידוּ הָעֵדִים שֶׁמָּנָה בִּפְנֵיהֶם אֶת הַמָּעוֹת. אֲבָל אִם הֵעִידוּ שֶׁבַּעַל הַקַּרְקַע מָכַר לַגַּזְלָן וְהוֹדָה לוֹ בִּפְנֵיהֶם שֶׁנָּתַן לוֹ דָּמִים כָּךְ וְכָךְ וְהַנִּגְזָל טוֹעֵן שֶׁלֹּא נָתַן לוֹ דָּמִים וּמֵחֲמַת יִרְאָה הוֹדָה לוֹ אֵין לַגַּזְלָן כְּלוּם אֶלָּא מוֹצִיאִין מִמֶּנּוּ הַשָּׂדֶה בְּלֹא דָּמִים מִפְּנֵי שֶׁלֹּא הוֹדָה לוֹ אֶלָּא מִפְּנֵי הַפַּחַד כְּשֶׁטָּעַן הוֹאִיל וְהֻחְזַק גַּזְלָן עָלֶיהָ:","אֵין בַּעַל הַשָּׂדֶה צָרִיךְ לַעֲשׂוֹת מוֹדָעָה עַל מֶכֶר זֶה הוֹאִיל וְהֻחְזַק זֶה גַּזְלָן עַל שָׂדֶה זוֹ וְאֵין רְאָיָתוֹ בָּהּ רְאָיָה. וְאֵין צָרִיךְ לִמְסֹר מוֹדָעָה. וְאֵין דִּין גַּזְלָן כְּדִין הָאוֹנֵס אֶת חֲבֵרוֹ וְתָלָה אוֹתוֹ עַד שֶׁיִּמְכֹּר לוֹ. שֶׁזֶּה הָאוֹנֵס אֵינוֹ רוֹצֶה לִגְזל וְלֹא גְּזָלוֹ עֲדַיִן כְּלוּם. לְפִיכָךְ אִם לֹא מָסַר הַמּוֹכֵר הָאָנוּס מוֹדָעָא מִמְכָּרוֹ קַיָּם:"],"Mishneh Torah, Sabbath 2":["דְחוּיָה הִיא שַׁבָּת אֵצֶל סַכָּנַת נְפָשׁוֹת כִּשְׁאָר כָּל הַמִּצְוֹת. לְפִיכָךְ חוֹלֶה שֶׁיֵּשׁ בּוֹ סַכָּנָה עוֹשִׂין לוֹ כָּל צְרָכָיו בְּשַׁבָּת עַל פִּי רוֹפֵא אֻמָּן שֶׁל אוֹתוֹ מָקוֹם. סָפֵק שֶׁהוּא צָרִיךְ לְחַלֵּל עָלָיו אֶת הַשַּׁבָּת סָפֵק שֶׁאֵינוֹ צָרִיךְ. וְכֵן אִם אָמַר רוֹפֵא לְחַלֵּל עָלָיו אֶת הַשַּׁבָּת וְרוֹפֵא אַחֵר אוֹמֵר אֵינוֹ צָרִיךְ מְחַלְּלִין עָלָיו אֶת הַשַּׁבָּת שֶׁסְּפֵק נְפָשׁוֹת דּוֹחֶה אֶת הַשַּׁבָּת:","אֲמָדוּהוּ בְּיוֹם הַשַּׁבָּת שֶׁהוּא צָרִיךְ לְכָךְ וְכָךְ לִשְׁמוֹנָה יָמִים אֵין אוֹמְרִים נַמְתִּין עַד הָעֶרֶב כְּדֵי שֶׁלֹּא לְחַלֵּל עָלָיו שְׁתֵּי שַׁבָּתוֹת אֶלָּא מַתְחִילִין מֵהַיּוֹם שֶׁהוּא שַׁבָּת וּמְחַלְּלִין עָלָיו אֲפִלּוּ מֵאָה שַׁבָּתוֹת כָּל זְמַן שֶׁהוּא צָרִיךְ וְיֵשׁ בּוֹ סַכָּנָה אוֹ סְפֵק סַכָּנָה מְחַלְּלִין. וּמַדְלִיקִין לוֹ אֶת הַנֵּר וּמְכַבִּין מִלְּפָנָיו אֶת הַנֵּר וְשׁוֹחֲטִין לוֹ וְאוֹפִין וּמְבַשְּׁלִין וּמְחִמִּין לוֹ חַמִּין בֵּין לְהַשְׁקוֹתוֹ בֵּין לִרְחִיצַת גּוּפוֹ. כְּלָלוֹ שֶׁל דָּבָר שַׁבָּת לְגַבֵּי חוֹלֶה שֶׁיֵּשׁ בּוֹ סַכָּנָה הֲרֵי הוּא כְּחל לְכָל הַדְּבָרִים שֶׁהוּא צָרִיךְ לָהֶן:","כְּשֶׁעוֹשִׂים דְּבָרִים הָאֵלּוּ אֵין עוֹשִׂין אוֹתָן לֹא עַל יְדֵי נָכְרִים וְלֹא עַל יְדֵי קְטַנִּים וְלֹא עַל יְדֵי עֲבָדִים וְלֹא עַל יְדֵי נָשִׁים כְּדֵי שֶׁלֹּא תְּהֵא שַׁבָּת קַלָּה בְּעֵינֵיהֶם. אֶלָּא עַל יְדֵי גְּדוֹלֵי יִשְׂרָאֵל וְחַכְמֵיהֶם. וְאָסוּר לְהִתְמַהְמֵהַּ בְּחִלּוּל שַׁבָּת לְחוֹלֶה שֶׁיֵּשׁ בּוֹ סַכָּנָה שֶׁנֶּאֱמַר (ויקרא יח ה) \"אֲשֶׁר יַעֲשֶׂה אוֹתָם הָאָדָם וָחַי בָּהֶם\" וְלֹא שֶׁיָּמוּת בָּהֶם. הָא לָמַדְתָּ שֶׁאֵין מִשְׁפְּטֵי הַתּוֹרָה נְקָמָה בָּעוֹלָם אֶלָּא רַחֲמִים וְחֶסֶד וְשָׁלוֹם בָּעוֹלָם. וְאִלּוּ הָאֶפִּיקוֹרוֹסִים שֶׁאוֹמְרִים שֶׁזֶּה חִלּוּל שַׁבָּת וְאָסוּר עֲלֵיהֶן הַכָּתוּב אוֹמֵר (יחזקאל כ כה) \"גַּם אֲנִי נָתַתִּי לָהֶם חֻקִּים לֹא טוֹבִים וּמִשְׁפָּטִים לֹא יִחְיוּ בָּהֶם\":","הַחוֹשֵׁשׁ בְּעֵינָיו וְהוּא שֶׁיִּהְיֶה בִּשְׁתֵּיהֶם אוֹ בְּאַחַת מֵהֶם צִיר אוֹ שֶׁהָיוּ דְּמָעוֹת שׁוֹתְתוֹת מֵהֶן מֵרֹב הַכְּאֵב אוֹ שֶׁהָיָה דָּם שׁוֹתֵת מֵהֶן אוֹ שֶׁהָיָה בָּהֶן קַדַּחַת וְכַיּוֹצֵא בָּחֳלָאִים אֵלּוּ הֲרֵי זֶה בִּכְלַל חוֹלִים שֶׁיֵּשׁ בָּהֶן סַכָּנָה וּמְחַלְּלִין עָלָיו אֶת הַשַּׁבָּת וְעוֹשִׂין לוֹ כָּל צָרְכֵי רְפוּאָה:","וְכֵן אִם יֵשׁ מַכָּה בַּחֲלַל גּוּפוֹ מִן הַשָּׂפָה וּלְפָנִים בֵּין בְּפִיו בֵּין בְּמֵעָיו בֵּין בִּכְבֵדוֹ וּטְחוֹלוֹ אוֹ בִּשְׁאָר מְקוֹמוֹת כָּל שֶׁיֵּשׁ בַּחֲלָלוֹ הֲרֵי זֶה חוֹלֶה שֶׁיֵּשׁ בּוֹ סַכָּנָה וְאֵינוֹ צָרִיךְ אֹמֶד שֶׁחָלְיוֹ כָּבֵד הוּא לְפִיכָךְ מְחַלְּלִין עָלָיו אֶת הַשַּׁבָּת מִיָּד בְּלֹא אֲמִידָה. וּמַכָּה שֶׁהִיא בְּגַב הַיָּד וְגַב הָרֶגֶל הֲרֵי הִיא כְּמַכָּה שֶׁל חָלָל וְאֵינָהּ צְרִיכָה אֹמֶד וּמְחַלְּלִין עָלֶיהָ אֶת הַשַּׁבָּת. וְהַחֹם שֶׁמְּסַמֵּר אֶת הַבָּשָׂר כְּמַכָּה שֶׁל חָלָל דָּמִי וּמְחַלְּלִין עָלָיו אֶת הַשַּׁבָּת וְכֵן כָּל חֹלִי שֶׁהָרוֹפְאִים אוֹמְרִין שֶׁזֶּה יֵשׁ בּוֹ סַכָּנָה אַף עַל פִּי שֶׁהוּא בְּעוֹר הַבָּשָׂר מִבַּחוּץ מְחַלְּלִין עָלָיו אֶת הַשַּׁבָּת עַל פִּיהֶם:","הַבּוֹלֵעַ נִימָה שֶׁל מַיִם מְחִמִּין לוֹ חַמִּין בְּשַׁבָּת וְעוֹשִׂין לוֹ כָּל צָרְכֵי רְפוּאָה מִפְּנֵי שֶׁהִיא סַכָּנַת נְפָשׁוֹת. וְכֵן מִי שֶׁנְּשָׁכוֹ כֶּלֶב שׁוֹטֶה אוֹ אֶחָד מִזּוֹחֲלֵי הֶעָפָר שֶׁמְּמִיתִין אֲפִלּוּ הָיוּ סָפֵק מְמִיתִין סָפֵק אֵין מְמִיתִין עוֹשִׂין לוֹ כָּל צָרְכֵי רְפוּאָה לְהַצִּילוֹ:","חוֹלֶה שֶׁאֲמָדוּהוּ רוֹפְאִים לְהָבִיא לוֹ גְּרוֹגֶרֶת אַחַת וְרָצוּ עֲשָׂרָה בְּנֵי אָדָם וְהֵבִיאוּ לוֹ עֶשֶׂר גְּרוֹגָרוֹת בְּבַת אַחַת כֻּלָּן פְּטוּרִין מִכְּלוּם. וַאֲפִלּוּ הֵבִיאוּ בָּזֶה אַחַר זֶה וַאֲפִלּוּ הִבְרִיא בָּרִאשׁוֹנָה שֶׁהֲרֵי כֻּלָּם בִּרְשׁוּת הֵבִיאוּ:","חוֹלֶה שֶׁהָיָה צָרִיךְ לִשְׁתֵּי גְּרוֹגָרוֹת וְלֹא מָצְאוּ אֶלָּא שְׁתֵּי גְּרוֹגָרוֹת בִּשְׁנֵי עֵקְצִין וְשָׁלֹשׁ גְּרוֹגָרוֹת בְּעֹקֶץ אֶחָד כּוֹרְתִין הָעֹקֶץ שֶׁיֵּשׁ בּוֹ שָׁלֹשׁ אַף עַל פִּי שֶׁאֵין צְרִיכִין אֶלָּא לִשְׁתַּיִם כְּדֵי שֶׁלֹּא יַרְבּוּ בִּבְצִירָה אֶלָּא יִכְרְתוּ עֹקֶץ אֶחָד וְלֹא יִכְרְתוּ שְׁנַיִם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַמְבַשֵּׁל לְחוֹלֶה בְּשַׁבָּת וְאָכַל הַחוֹלֶה וְהוֹתִיר אָסוּר לְבָרִיא לֶאֱכל מִן הַמֻּתָּר גְּזֵרָה שֶׁמָּא יַרְבֶּה בִּשְׁבִילוֹ. אֲבָל הַשּׁוֹחֵט לַחוֹלֶה בְּשַׁבָּת מֻתָּר לַבָּרִיא לֶאֱכל מִמֶּנּוּ בָּשָׂר חַי שֶׁאֵין בַּדָּבָר תּוֹסֶפֶת כְּדֵי שֶׁנִּגְזֹר שֶׁמָּא יַרְבֶּה בִּשְׁבִילוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","חוֹלֶה שֶׁאֵין בּוֹ סַכָּנָה עוֹשִׂין לוֹ כָּל צְרָכָיו עַל יְדֵי נָכְרִי. כֵּיצַד. אוֹמְרִין לַנָּכְרִי לַעֲשׂוֹת לוֹ וְהוּא עוֹשֶׂה. לְבַשֵּׁל לוֹ וְלֶאֱפוֹת וּלְהָבִיא רְפוּאָה מֵרְשׁוּת לִרְשׁוּת וְכַיּוֹצֵא בָּאֵלּוּ. וְכֵן כּוֹחֵל עֵינָיו מִן הַנָּכְרִי בְּשַׁבָּת אַף עַל פִּי שֶׁאֵין שָׁם סַכָּנָה. וְאִם הָיוּ צְרִיכִים לִדְבָרִים שֶׁאֵין בָּהֶן מְלָאכָה עוֹשִׂין אוֹתָן אֲפִלּוּ יִשְׂרָאֵל. לְפִיכָךְ מַעֲלִין אָזְנַיִם בְּשַׁבָּת וּמַעֲלִין אֻנְקְלִי וּמַחְזִירִין אֶת הַשֶּׁבֶר וְכָל כַּיּוֹצֵא בָּזֶה מֻתָּר:","הַיּוֹלֶדֶת כְּשֶׁכּוֹרַעַת לֵילֵד הֲרֵי הִיא בְּסַכָּנַת נְפָשׁוֹת וּמְחַלְּלִין עָלֶיהָ אֶת הַשַּׁבָּת. קוֹרְאִין לָהּ חֲכָמָה מִמָּקוֹם לְמָקוֹם וְחוֹתְכִים אֶת הַטַּבּוּר וְקוֹשְׁרִין אוֹתוֹ. וְאִם הָיְתָה צְרִיכָה לְנֵר בְּשָׁעָה שֶׁהִיא צוֹעֶקֶת בַּחֲבָלֶיהָ מַדְלִיקִין לָהּ אֶת הַנֵּר. וַאֲפִלּוּ הָיְתָה סוּמָא מִפְּנֵי שֶׁדַּעְתָּהּ מִתְיַשֶּׁבֶת עָלֶיהָ בַּנֵּר וְאַף עַל פִּי שֶׁאֵינָהּ רוֹאָה. וְאִם הָיְתָה צְרִיכָה לְשֶׁמֶן וְכַיּוֹצֵא בּוֹ מְבִיאִין לָהּ. וְכָל שֶׁאֶפְשָׁר לְשַׁנּוֹת מְשַׁנִּין בִּשְׁעַת הֲבָאָה כְּגוֹן שֶׁתָּבִיא לָהּ חֲבֶרְתָּהּ כְּלִי תָּלוּי בִּשְׂעָרָהּ. וְאִם אִי אֶפְשָׁר מְבִיאָה כְּדַרְכָּהּ:","אֵין מְיַלְּדִין אֶת הָעוֹבֶדֶת כּוֹכָבִים וּמַזָּלוֹת בְּשַׁבָּת וַאֲפִלּוּ בְּשָׂכָר וְאֵין חוֹשְׁשִׁין לְאֵיבָה וְאַף עַל פִּי שֶׁאֵין שָׁם חִלּוּל. אֲבָל מְיַלְּדִין אֶת בַּת גֵּר תּוֹשָׁב מִפְּנֵי שֶׁאָנוּ מְצֻוִּין לְהַחֲיוֹתוֹ. וְאֵין מְחַלְּלִין עָלֶיהָ אֶת הַשַּׁבָּת:","חַיָּה מִשֶּׁיַּתְחִיל הַדָּם לִהְיוֹת שׁוֹתֵת עַד שֶׁתֵּלֵד וְאַחַר שֶׁתֵּלֵד עַד שְׁלֹשָׁה יָמִים מְחַלְּלִין עָלֶיהָ אֶת הַשַּׁבָּת וְעוֹשִׂין לָהּ כָּל צְרָכֶיהָ. בֵּין שֶׁאָמְרָה צְרִיכָה אֲנִי בֵּין שֶׁאָמְרָה אֵינִי צְרִיכָה. וּמִשְּׁלֹשָׁה עַד שִׁבְעָה אִם אָמְרָה אֵינִי צְרִיכָה אֵין מְחַלְּלִין עָלֶיהָ אֶת הַשַּׁבָּת. וְאִם שָׁתְקָה וְאֵין צָרִיךְ לוֹמַר אִם אָמְרָה צְרִיכָה אֲנִי שֶׁמְּחַלְּלִין עָלֶיהָ אֶת הַשַּׁבָּת. וּמִשִּׁבְעָה וְעַד שְׁלֹשִׁים יוֹם הֲרֵי הִיא כְּחוֹלָה שֶׁאֵין בּוֹ סַכָּנָה וַאֲפִלּוּ אָמְרָה צְרִיכָה אֲנִי אֵין עוֹשִׂין לָהּ מְלָאכָה אֶלָּא עַל יְדֵי נָכְרִים:","עוֹשִׂין מְדוּרָה לְחַיָּה וַאֲפִלּוּ בִּימוֹת הַחַמָּה מִפְּנֵי שֶׁהַצִּנָּה קָשָׁה לְחַיָּה הַרְבֵּה בַּמְּקוֹמוֹת הַקָּרִים. אֲבָל אֵין עוֹשִׂין מְדוּרָה לְחוֹלֶה לְהִתְחַמֵּם בָּהּ. הִקִּיז דָּם וְנִצְטַנֵּן עוֹשִׂין לוֹ מְדוּרָה אֲפִלּוּ בִּתְקוּפַת תַּמּוּז. וּמַרְחִיצִין אֶת הַוָּלָד בְּשַׁבָּת בַּיּוֹם שֶׁנּוֹלַד אַחַר שֶׁחוֹתְכִין אֶת טִבּוּרוֹ אֲפִלּוּ בְּחַמִּין שֶׁהוּחַמּוּ בְּשַׁבָּת. וּמוֹלְחִין אוֹתוֹ וּמְלַפְּפִין אוֹתוֹ מִפְּנֵי שֶׁסַּכָּנָה הִיא לוֹ אִם לֹא יַעֲשׂוּ לוֹ כָּל אֵלּוּ. וְכֵן מַרְחִיצִים אוֹתוֹ לִפְנֵי הַמִּילָה וּלְאַחַר הַמִּילָה וּבַיּוֹם הַשְּׁלִישִׁי לַמִּילָה בְּחַמִּין שֶׁהוּחַמּוּ בְּשַׁבָּת מִפְּנֵי הַסַּכָּנָה:","הָאִשָּׁה שֶׁיָּשְׁבָה עַל הַמַּשְׁבֵּר וּמֵתָה מְבִיאִין סַכִּין בְּשַׁבָּת אֲפִלּוּ דֶּרֶךְ רְשׁוּת הָרַבִּים וְקוֹרְעִין אֶת כְּרֵסָהּ וּמוֹצִיאִין אֶת הַוָּלָד שֶׁמָּא יִמָּצֵא חַי שֶׁסְּפֵק נְפָשׁוֹת דּוֹחֶה אֶת הַשַּׁבָּת וַאֲפִלּוּ לָזֶה שֶׁאֵין חֶזְקָתוֹ חַי:","מְפַקְּחִין פִּקּוּחַ נֶפֶשׁ בְּשַׁבָּת וְאֵין צָרִיךְ לִטּל רְשׁוּת מִבֵּית דִּין. וְהַמַּקְדִּים לְהַצִּיל הַנֶּפֶשׁ הֲרֵי זֶה מְשֻׁבָּח. כֵּיצַד. רָאָה תִּינוֹק שֶׁנָּפַל לַיָּם פּוֹרֵשׂ מְצוּדָה וּמַעֲלֵהוּ וְאַף עַל פִּי שֶׁהוּא צָד הַדָּגִים עִמּוֹ. שָׁמַע שֶׁטָּבַע תִּינוֹק בַּיָּם וּפָרַשׂ מְצוּדָה לְהַעֲלוֹתוֹ וְהֶעֱלָה דָּגִים בִּלְבַד פָּטוּר מִכְּלוּם. נִתְכַּוֵּן לְהַעֲלוֹת דָּגִים וְהֶעֱלָה דָּגִים וְתִינוֹק פָּטוּר אֲפִלּוּ לֹא שָׁמַע שֶׁטָּבַע הוֹאִיל וְהֶעֱלָה תִּינוֹק עִם הַדָּגִים פָּטוּר:","נָפַל תִּינוֹק לַבּוֹר עוֹקֵר חֻלְיָה וּמַעֲלֵהוּ וְאַף עַל פִּי שֶׁהוּא מְתַקֵּן בָּהּ מַדְרֵגָה בִּשְׁעַת עֲקִירָתוֹ. נִנְעַל דֶּלֶת בִּפְנֵי תִּינוֹק שׁוֹבֵר הַדֶּלֶת וּמוֹצִיאוֹ וְאַף עַל פִּי שֶׁהוּא מְפַצֵּל אוֹתָהּ כְּמִין עֵצִים שֶׁרְאוּיִין לִמְלָאכָה שֶׁמָּא יִבָּעֵת הַתִּינוֹק וְיָמוּת. נָפְלָה דְּלֵקָה וְיֵשׁ שָׁם אָדָם שֶׁחוֹשְׁשִׁין שֶׁמָּא יִשָּׂרֵף מְכַבִּין אוֹתָהּ לְהַצִּילוֹ מִן הָאֵשׁ וְאַף עַל פִּי שֶׁהוּא כּוֹבֵשׁ דֶּרֶךְ וּמְתַקְּנָהּ בִּשְׁעַת כִּבּוּי. וְכָל הַקּוֹדֵם לְהַצִּיל הֲרֵי זֶה מְשֻׁבָּח וְאֵינוֹ צָרִיךְ לִטּל רְשׁוּת מִבֵּית דִּין בְּכָל דָּבָר שֶׁיֵּשׁ בּוֹ סַכָּנָה:","מִי שֶׁנָּפְלָה עָלָיו מַפּלֶת סָפֵק הוּא שָׁם סָפֵק אֵינוֹ שָׁם מְפַקְּחִין עָלָיו. מְצָאוּהוּ חַי אַף עַל פִּי שֶׁנִּתְרוֹצֵץ וְאִי אֶפְשָׁר שֶׁיִּבָּרֵא מְפַקְּחִין עָלָיו וּמוֹצִיאִין אוֹתוֹ לְחַיֵּי אוֹתָהּ שָׁעָה:","בָּדְקוּ עַד חָטְמוֹ וְלֹא מָצְאוּ בּוֹ נְשָׁמָה מַנִּיחִין אוֹתוֹ שָׁם שֶׁכְּבָר מֵת. בָּדְקוּ וּמָצְאוּ עֶלְיוֹנִים מֵתִים לֹא יֹאמְרוּ כְּבָר מֵתוּ תַּחְתּוֹנִים אֶלָּא מְפַקְּחִין עַל הַכּל שֶׁאֶפְשָׁר בְּמַפּלֶת שֶׁיָּמוּת הָעֶלְיוֹן וְיִהְיֶה הַתַּחְתּוֹן חַי:","הָיְתָה חָצֵר שֶׁיֵּשׁ בָּהּ עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת וְיִשְׂרְאֵלִים אֲפִלּוּ יִשְׂרָאֵל אֶחָד וְאֶלֶף עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת וְנָפְלָה עֲלֵיהֶם מַפּלֶת מְפַקְּחִין עַל הַכּל מִפְּנֵי יִשְׂרָאֵל. פֵּרַשׁ אֶחָד מֵהֶם לֶחָצֵר אַחֶרֶת וְנָפְלָה עָלָיו אוֹתָהּ חָצֵר מְפַקְּחִים עָלָיו שֶׁמָּא זֶה שֶׁפֵּרַשׁ הָיָה יִשְׂרָאֵל וְהַנִּשְׁאָרִים עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:","נֶעֶקְרוּ כֻּלָּן מֵחָצֵר זוֹ לֵילֵךְ לֶחָצֵר אַחֶרֶת וּבְעֵת עֲקִירָתָם פֵּרַשׁ אֶחָד מֵהֶן וְנִכְנַס לֶחָצֵר אַחֶרֶת וְנָפְלָה עָלָיו מַפּלֶת וְאֵין יָדוּעַ מִי הוּא אֵין מְפַקְּחִין עָלָיו. שֶׁכֵּיוָן שֶׁנֶּעֶקְרוּ כֻּלָּם אֵין כָּאן יִשְׂרָאֵל וְכָל הַפּוֹרֵשׁ מֵהֶן כְּשֶׁהֵן מְהַלְּכִין הֲרֵי הוּא בְּחֶזְקַת שֶׁפֵּרַשׁ מִן הָרֹב. לְפִיכָךְ אִם הָיָה הָרֹב יִשְׂרָאֵל אַף עַל פִּי שֶׁנֶּעֶקְרוּ כֻּלָּם וּפֵרַשׁ אֶחָד מֵהֶם לְחָצֵר אַחֶרֶת וְנָפְלָה עָלָיו מַפּלֶת מְפַקְּחִין:","הַמְהַלֵּךְ בַּמִּדְבָּר וְלֹא יָדַע מָתַי הוּא יוֹם שַׁבָּת מוֹנֶה מִיּוֹם שֶׁטָּעָה שִׁשָּׁה וּמְקַדֵּשׁ שְׁבִיעִי וּמְבָרֵךְ בּוֹ בִּרְכוֹת הַיּוֹם וּמַבְדִּיל בְּמוֹצָאֵי שַׁבָּת. וּבְכָל יוֹם וָיוֹם וַאֲפִלּוּ בְּיוֹם זֶה שֶׁהוּא מְקַדֵּשׁ וּמַבְדִּיל בּוֹ מֻתָּר לוֹ לַעֲשׂוֹת כְּדֵי פַּרְנָסָתוֹ בִּלְבַד כְּדֵי שֶׁלֹּא יָמוּת. וְאָסוּר לוֹ לַעֲשׂוֹת יוֹתֵר עַל פַּרְנָסָתוֹ שֶׁכָּל יוֹם וָיוֹם סְפֵק שַׁבָּת הוּא. וְאִם יָדַע שֶׁהוּא שְׁמִינִי לִיצִיאָתוֹ אוֹ חֲמִשָּׁה עָשָׂר לִיצִיאָתוֹ וְכַיּוֹצֵא בְּזֶה הַמִּנְיָן הֲרֵי זֶה מֻתָּר לַעֲשׂוֹת מְלָאכָה בְּאוֹתוֹ הַיּוֹם שֶׁהֲרֵי הַדָּבָר וַדַּאי שֶׁלֹּא יָצָא בְּשַׁיָּרָא בְּשַׁבָּת. וּשְׁאָר הַיָּמִים חוּץ מִיּוֹם זֶה עוֹשֶׂה כְּדֵי פַּרְנָסָה בִּלְבַד:","עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁצָּרוּ עַל עֲיָרוֹת יִשְׂרָאֵל אִם בָּאוּ עַל עִסְקֵי מָמוֹן אֵין מְחַלְּלִין עֲלֵיהֶן אֶת הַשַּׁבָּת וְאֵין עוֹשִׂין עִמָּהֶן מִלְחָמָה. וּבְעִיר הַסְּמוּכָה לַסְּפָר אֲפִלּוּ לֹא בָּאוּ אֶלָּא עַל עִסְקֵי תֶּבֶן וְקַשׁ יוֹצְאִין עֲלֵיהֶן בִּכְלֵי זַיִן וּמְחַלְּלִין עֲלֵיהֶן אֶת הַשַּׁבָּת. וּבְכָל מָקוֹם אִם בָּאוּ עַל עִסְקֵי נְפָשׁוֹת אוֹ שֶׁעָרְכוּ מִלְחָמָה אוֹ שֶׁצָּרוּ סְתָם יוֹצְאִין עֲלֵיהֶן בִּכְלֵי זַיִן וּמְחַלְּלִין עֲלֵיהֶן אֶת הַשַּׁבָּת. וּמִצְוָה עַל כָּל יִשְׂרָאֵל שֶׁיְּכוֹלִין לָבוֹא וְלָצֵאת וְלַעֲזֹר לְאַחֵיהֶם שֶׁבַּמָּצוֹר וּלְהַצִּילָם מִיַּד הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת בְּשַׁבָּת. וְאָסוּר לָהֶן לְהִתְמַהֲמֵהַּ לְמוֹצָאֵי שַׁבָּת. וּכְשֶׁיַּצִּילוּ אֶת אֲחֵיהֶן מֻתָּר לָהֶן לַחֲזֹר בִּכְלֵי זַיִן שֶׁלָּהֶן לִמְקוֹמָם בְּשַׁבָּת כְּדֵי שֶׁלֹּא לְהַכְשִׁילָן לֶעָתִיד לָבוֹא:","וְכֵן סְפִינָה הַמְטֹרֶפֶת בַּיָּם אוֹ עִיר שֶׁהִקִּיפָהּ כַּרְקוֹם אוֹ נָהָר מִצְוָה לָצֵאת בְּשַׁבָּת לְהַצִּילָן בְּכָל דָּבָר שֶׁיָּכוֹל לְהַצִּילָן. וַאֲפִלּוּ יָחִיד הַנִּרְדָּף מִפְּנֵי הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אוֹ מִפְּנֵי נָחָשׁ אוֹ דֹּב שֶׁהוּא רוֹדֵף אַחֲרָיו לְהָרְגוֹ מִצְוָה לְהַצִּילוֹ. וַאֲפִלּוּ בַּעֲשִׂיַּת כַּמָּה מְלָאכוֹת בְּשַׁבָּת וַאֲפִלּוּ לְתַקֵּן כְּלֵי זַיִן לְהַצִּילוֹ מֻתָּר. וְזוֹעֲקִים עֲלֵיהֶן וּמִתְחַנְּנִים בְּשַׁבָּת וּמַתְרִיעִין עֲלֵיהֶן לַעֲזֹר אוֹתָם. וְאֵין מִתְחַנְּנִים וְלֹא זוֹעֲקִין עַל הַדֶּבֶר בְּשַׁבָּת:","צָרִין עַל עֲיָרוֹת הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שְׁלֹשָׁה יָמִים קֹדֶם לַשַּׁבָּת. וְעוֹשִׂין עִמָּהֶן מִלְחָמָה בְּכָל יוֹם וָיוֹם וַאֲפִלּוּ בְּשַׁבָּת עַד שֶׁכּוֹבְשִׁין אוֹתָהּ וְאַף עַל פִּי שֶׁהִיא מִלְחֶמֶת הָרְשׁוּת. מִפִּי הַשְּׁמוּעָה לָמְדוּ (דברים כ כ) \"עַד רִדְתָּהּ\" וַאֲפִלּוּ בְּשַׁבָּת. וְאֵין צָרִיךְ לוֹמַר בְּמִלְחֶמֶת מִצְוָה. וְלֹא כָּבַשׁ יְהוֹשֻׁעַ יְרִיחוֹ אֶלָּא בְּשַׁבָּת:"],"Mishneh Torah, Sabbath 30":["אַרְבָּעָה דְּבָרִים נֶאֶמְרוּ בְּשַׁבָּת. שְׁנַיִם מִן הַתּוֹרָה. וּשְׁנַיִם מִדִּבְרֵי סוֹפְרִים וְהֵן מְפֹרָשִׁין עַל יְדֵי הַנְּבִיאִים. שֶׁבַּתּוֹרָה (שמות כ ז) \"זָכוֹר\" וְ (דברים ה יא) \"שָׁמוֹר\". וְשֶׁנִּתְפָּרְשׁוּ עַל יְדֵי הַנְּבִיאִים כָּבוֹד וָעֹנֶג שֶׁנֶּאֱמַר (ישעיה נח יג) \"וְקָרָאתָ לַשַּׁבָּת עֹנֶג וְלִקְדוֹשׁ ה' מְכֻבָּד\":","אֵיזֶהוּ כָּבוֹד זֶה שֶׁאָמְרוּ חֲכָמִים שֶׁמִּצְוָה עַל אָדָם לִרְחֹץ פָּנָיו יָדָיו וְרַגְלָיו בְּחַמִּין בְּעֶרֶב שַׁבָּת מִפְּנֵי כְּבוֹד הַשַּׁבָּת וּמִתְעַטֵּף בְּצִיצִית וְיוֹשֵׁב בְּכֹבֶד רֹאשׁ מְיַחֵל לְהַקְבָּלַת פְּנֵי הַשַּׁבָּת כְּמוֹ שֶׁהוּא יוֹצֵא לִקְרַאת הַמֶּלֶךְ. וַחֲכָמִים הָרִאשׁוֹנִים הָיוּ מְקַבְּצִין תַּלְמִידֵיהֶן בְּעֶרֶב שַׁבָּת וּמִתְעַטְּפִים וְאוֹמְרִים בּוֹאוּ וְנֵצֵא לִקְרַאת שַׁבָּת הַמֶּלֶךְ:","וּמִכְּבוֹד הַשַּׁבָּת שֶׁיִּלְבַּשׁ כְּסוּת נְקִיָּה. וְלֹא יִהְיֶה מַלְבּוּשׁ החֹל כְּמַלְבּוּשׁ הַשַּׁבָּת. וְאִם אֵין לוֹ לְהַחֲלִיף מְשַׁלְשֵׁל טַלִּיתוֹ כְּדֵי שֶׁלֹּא יְהֵא מַלְבּוּשׁוֹ כְּמַלְבּוּשׁ הַחל. וְעֶזְרָא תִּקֵּן שֶׁיְּהוּ הָעָם מְכַבְּסִים בַּחֲמִישִׁי מִפְּנֵי כְּבוֹד הַשַּׁבָּת:","אָסוּר לִקְבֹּעַ סְעֻדָּה וּמִשְׁתֶּה בְּעֶרֶב שַׁבָּת מִפְּנֵי כְּבוֹד הַשַּׁבָּת. וּמֻתָּר לֶאֱכל וְלִשְׁתּוֹת עַד שֶׁתֶּחְשַׁךְ. וְאַף עַל פִּי כֵן מִכְּבוֹד הַשַּׁבָּת שֶׁיִּמָּנַע אָדָם מִן הַמִּנְחָה וּלְמַעְלָה מִלִּקְבֹּעַ סְעֻדָּה כְּדֵי שֶׁיִּכָּנֵס לְשַׁבָּת כְּשֶׁהוּא מִתְאַוֶּה לֶאֱכל:","מְסַדֵּר אָדָם שֻׁלְחָנוֹ בְּעֶרֶב שַׁבָּת וְאַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ אֶלָּא לִכְזַיִת. וְכֵן מְסַדֵּר שֻׁלְחָנוֹ בְּמוֹצָאֵי שַׁבָּת וְאַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ אֶלָּא לִכְזַיִת. כְּדֵי לְכַבְּדוֹ בִּכְנִיסָתוֹ וּבִיצִיאָתוֹ. וְצָרִיךְ לְתַקֵּן בֵּיתוֹ מִבְּעוֹד יוֹם מִפְּנֵי כְּבוֹד הַשַּׁבָּת. וְיִהְיֶה נֵר דָּלוּק וְשֻׁלְחָן עָרוּךְ לֶאֱכל וּמִטָּה מֻצַּעַת שֶׁכָּל אֵלּוּ לִכְבוֹד שַׁבָּת הֵן:","אַף עַל פִּי שֶׁהָיָה אָדָם חָשׁוּב בְּיוֹתֵר וְאֵין דַּרְכּוֹ לִקַּח דְּבָרִים מִן הַשּׁוּק וְלֹא לְהִתְעַסֵּק בִּמְלָאכוֹת שֶׁבַּבַּיִת חַיָּב לַעֲשׂוֹת דְּבָרִים שֶׁהֵן לְצֹרֶךְ הַשַּׁבָּת בְּגוּפוֹ שֶׁזֶּה הוּא כְּבוֹדוֹ. חֲכָמִים הָרִאשׁוֹנִים מֵהֶם מִי שֶׁהָיָה מְפַצֵּל הָעֵצִים לְבַשֵּׁל בָּהֶן. וּמֵהֶן מִי שֶׁהָיָה מְבַשֵּׁל אוֹ מוֹלֵחַ בָּשָׂר אוֹ גּוֹדֵל פְּתִילוֹת אוֹ מַדְלִיק נֵרוֹת. וּמֵהֶן מִי שֶׁהָיָה יוֹצֵא וְקוֹנֶה דְּבָרִים שֶׁהֵן לְצֹרֶךְ הַשַּׁבָּת מִמַּאֲכָל וּמַשְׁקֶה אַף עַל פִּי שֶׁאֵין דַּרְכּוֹ בְּכָךְ. וְכָל הַמַּרְבֶּה בְּדָבָר זֶה הֲרֵי זֶה מְשֻׁבָּח:","אֵיזֶהוּ עֹנֶג זֶהוּ שֶׁאָמְרוּ חֲכָמִים שֶׁצָּרִיךְ לְתַקֵּן תַּבְשִׁיל שָׁמֵן בְּיוֹתֵר וּמַשְׁקֶה מְבֻשָּׂם לְשַׁבָּת הַכּל לְפִי מָמוֹנוֹ שֶׁל אָדָם. וְכָל הַמַּרְבֶּה בְּהוֹצָאַת שַׁבָּת וּבְתִקּוּן מַאֲכָלִים רַבִּים וְטוֹבִים הֲרֵי זֶה מְשֻׁבָּח. וְאִם אֵין יָדוֹ מַשֶּׂגֶת אֲפִלּוּ לֹא עָשָׂה אֶלָּא שֶׁלֶק וְכַיּוֹצֵא בּוֹ מִשּׁוּם כְּבוֹד שַׁבָּת הֲרֵי זֶה עֹנֶג שַׁבָּת. וְאֵינוֹ חַיָּב לְהָצֵר לְעַצְמוֹ וְלִשְׁאל מֵאֲחֵרִים כְּדֵי לְהַרְבּוֹת בְּמַאֲכָל בְּשַׁבָּת. אָמְרוּ חֲכָמִים הָרִאשׁוֹנִים עֲשֵׂה שַׁבַּתְּךָ חֹל וְאַל תִּצְטָרֵךְ לַבְּרִיּוֹת:","מִי שֶׁהָיָה עָנֹג וְעָשִׁיר וַהֲרֵי כָּל יָמָיו כְּשַׁבָּת צָרִיךְ לְשַׁנּוֹת מַאֲכַל שַׁבָּת מִמַּאֲכַל הַחל. וְאִם אִי אֶפְשָׁר לְשַׁנּוֹת מְשַׁנֶּה זְמַן הָאֲכִילָה אִם הָיָה רָגִיל לְהַקְדִּים מְאַחֵר וְאִם הָיָה רָגִיל לְאַחֵר מַקְדִּים:","חַיָּב אָדָם לֶאֱכל שָׁלֹשׁ סְעֻדּוֹת בְּשַׁבָּת אַחַת עַרְבִית וְאַחַת שַׁחֲרִית וְאַחַת בְּמִנְחָה. וְצָרִיךְ לְהִזָּהֵר בְּשָׁלֹשׁ סְעֻדּוֹת אֵלּוּ שֶׁלֹּא יִפְחֹת מֵהֶן כְּלָל. וַאֲפִלּוּ עָנִי הַמִּתְפַּרְנֵס מִן הַצְּדָקָה סוֹעֵד שָׁלֹשׁ סְעֻדּוֹת. וְאִם הָיָה חוֹלֶה מֵרֹב הָאֲכִילָה אוֹ שֶׁהָיָה מִתְעַנֶּה תָּמִיד פָּטוּר מִשָּׁלֹשׁ סְעֻדּוֹת. וְצָרִיךְ לִקְבֹּעַ כָּל סְעֻדָּה מִשְּׁלָשְׁתָּן עַל הַיַּיִן וְלִבְצֹעַ עַל שְׁתֵּי כִּכָּרוֹת. וְכֵן בְּיָמִים טוֹבִים:","אֲכִילַת בָּשָׂר וּשְׁתִיַּת יַיִן בְּשַׁבָּת עֹנֶג הוּא לוֹ. וְהוּא שֶׁהָיְתָה יָדוֹ מַשֶּׂגֶת. וְאָסוּר לִקְבֹּעַ סְעֻדָּה עַל הַיַּיִן בְּשַׁבָּת וּבְיָמִים טוֹבִים בִּשְׁעַת בֵּית הַמִּדְרָשׁ. אֶלָּא כָּךְ הָיָה מִנְהַג הַצַּדִּיקִים הָרִאשׁוֹנִים מִתְפַּלֵּל אָדָם בְּשַׁבָּת שַׁחֲרִית וּמוּסָף בְּבֵית הַכְּנֶסֶת וְיָבוֹא לְבֵיתוֹ וְיִסְעֹד סְעֻדָּה שְׁנִיָּה וְיֵלֵךְ לְבֵית הַמִּדְרָשׁ יִקְרָא וְיִשְׁנֶה עַד הַמִּנְחָה וְיִתְפַּלֵּל מִנְחָה וְאַחַר כָּךְ יִקְבַּע סְעֻדָּה שְׁלִישִׁית עַל הַיַּיִן וְיֹאכַל וְיִשְׁתֶּה עַד מוֹצָאֵי שַׁבָּת:","אָסוּר לוֹ לָאָדָם שֶׁיְּהַלֵּךְ בְּעַרְבֵי שַׁבָּתוֹת יוֹתֵר מִשָּׁלֹשׁ פַּרְסָאוֹת מִתְּחִלַּת הַיּוֹם כְּדֵי שֶׁיַּגִּיעַ לְבֵיתוֹ וְעוֹד הַיּוֹם רַב וְיָכִין סְעֻדָּה לְשַׁבָּת. שֶׁהֲרֵי אֵין אַנְשֵׁי בֵּיתוֹ יוֹדְעִין שֶׁהַיּוֹם יָבוֹא כְּדֵי לְהָכִין לוֹ. וְאֵין צָרִיךְ לוֹמַר אִם הָיָה מִתְאָרֵחַ אֵצֶל אֲחֵרִים שֶׁהֲרֵי מְבַיְּשָׁן מִפְּנֵי שֶׁלֹּא הֵכִינוּ לָהֶן דָּבָר הָרָאוּי לְאוֹרְחִין:","אָסוּר לְהִתְעַנּוֹת וְלִזְעֹק וּלְהִתְחַנֵּן וּלְבַקֵּשׁ רַחֲמִים בְּשַׁבָּת וַאֲפִלּוּ בְּצָרָה מִן הַצָּרוֹת שֶׁהַצִּבּוּר מִתְעַנִּין וּמַתְרִיעִין עֲלֵיהֶן אֵין מִתְעַנִּין וְלֹא מַתְרִיעִין בְּשַׁבָּת. וְלֹא בְּיָמִים טוֹבִים. חוּץ מֵעִיר שֶׁהִקִּיפוּהָ עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אוֹ נָהָר אוֹ סְפִינָה הַמִּטָּרֶפֶת בַּיָּם שֶׁמַּתְרִיעִין עֲלֵיהֶן בְּשַׁבָּת לְעָזְרָן וּמִתְחַנְּנִין וּמְבַקְּשִׁין עֲלֵיהֶן רַחֲמִים:","אֵין צָרִין עַל עֲיָרוֹת שֶׁל עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת פָּחוֹת מִשְּׁלֹשָׁה יָמִים קֹדֶם הַשַּׁבָּת. כְּדֵי שֶׁתִּתְיַשֵּׁב דַּעַת אַנְשֵׁי הַמִּלְחָמָה עֲלֵיהֶן וְלֹא יִהְיוּ מְבֹהָלִים וּטְרוּדִים בְּשַׁבָּת. אֵין מַפְלִיגִין בִּסְפִינָה פָּחוֹת מִשְּׁלֹשָׁה יָמִים קֹדֶם הַשַּׁבָּת כְּדֵי שֶׁתִּתְיַשֵּׁב דַּעְתּוֹ עָלָיו קֹדֶם הַשַּׁבָּת וְלֹא יִצְטַעֵר יֶתֶר מִדַּאי. וְלִדְבַר מִצְוָה מַפְלִיג בַּיָּם אֲפִלּוּ בְּעֶרֶב שַׁבָּת. וּפוֹסֵק עִמּוֹ לִשְׁבֹּת וְאֵינוֹ שׁוֹבֵת. וּמִצּוֹר לְצִידֹן וְכַיּוֹצֵא בָּהֶן אֲפִלּוּ לִדְבַר הָרְשׁוּת מֻתָּר לְהַפְלִיג בְּעֶרֶב שַׁבָּת. וּמָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא יַפְלִיג בְּעֶרֶב שַׁבָּת כְּלָל אֵין מַפְלִיגִין:","תַּשְׁמִישׁ הַמִּטָּה מֵעֹנֶג שַׁבָּת הוּא. לְפִיכָךְ עוֹנַת תַּלְמִידֵי חֲכָמִים הַבְּרִיאִים מְשַׁמְּשִׁין מִלֵּילֵי שַׁבָּת לְלֵילֵי שַׁבָּת. וּמֻתָּר לִבְעל בְּתוּלָה לְכַתְּחִלָּה בְּשַׁבָּת וְאֵין בָּזֶה לֹא מִשּׁוּם חוֹבֵל וְלֹא מִשּׁוּם צַעַר לָהּ:","הַשַּׁבָּת וַעֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת כָּל אַחַת מִשְּׁתֵּיהֶן שְׁקוּלָה כְּנֶגֶד שְׁאָר כָּל מִצְוֹת הַתּוֹרָה. וְהַשַּׁבָּת הִיא הָאוֹת שֶׁבֵּין הַקָּדוֹשׁ בָּרוּךְ הוּא וּבֵינֵינוּ לְעוֹלָם. לְפִיכָךְ כָּל הָעוֹבֵר עַל שְׁאָר הַמִּצְוֹת הֲרֵי הוּא בִּכְלַל רִשְׁעֵי יִשְׂרָאֵל. אֲבָל הַמְחַלֵּל שַׁבָּת בְּפַרְהֶסְיָא הֲרֵי הוּא כְּעוֹבֵד עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת וּשְׁנֵיהֶם כְּעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת לְכָל דִּבְרֵיהֶם. לְפִיכָךְ מְשַׁבֵּחַ הַנָּבִיא וְאוֹמֵר (ישעיה נו ב) \"אַשְׁרֵי אֱנוֹשׁ יַעֲשֶׂה זֹּאת וּבֶן אָדָם יַחֲזִיק בָּהּ שֹׁמֵר שַׁבָּת מֵחַלְּלוֹ\" וְגוֹ'. וְכָל הַשּׁוֹמֵר אֶת הַשַּׁבָּת כְּהִלְכָתָהּ וּמְכַבְּדָהּ וּמְעַנְּגָהּ כְּפִי כֹּחוֹ כְּבָר מְפֹרָשׁ בַּקַּבָּלָה שְׂכָרוֹ בָּעוֹלָם הַזֶּה יֶתֶר עַל הַשָּׂכָר הַצָּפוּן לָעוֹלָם הַבָּא. שֶׁנֶּאֱמַר (ישעיה נח יד) \"אָז תִּתְעַנַּג עַל ה' וְהִרְכַּבְתִּיךָ עַל בָּמֳתֵי אָרֶץ וְהַאֲכַלְתִּיךָ נַחֲלַת יַעֲקֹב אָבִיךָ כִּי פִּי ה' דִּבֵּר\"."],"Mishneh Torah, Sabbatical Year and the Jubilee 2":["לֹא יוֹצִיא אָדָם זְבָלִים מֵחֲצֵרוֹ וְיִתֵּן בְּתוֹךְ שָׂדֵהוּ בַּשְּׁבִיעִית מִפְּנֵי שֶׁנִּרְאֶה כִּמְזַבֵּל שָׂדֵהוּ שֶׁתִּהְיֶה יָפָה לִזְרִיעָה. וְאִם הוֹצִיא וְהֶעֱמִיד מִמֶּנּוּ אַשְׁפָּה מֻתָּר. וְלֹא יַעֲשֶׂה אַשְׁפָּה בְּתוֹךְ שָׂדֵהוּ עַד שֶׁיַּעֲבֹר זְמַן שֶׁמְּזַבְּלִין בּוֹ לַעֲבוֹדַת הָאָרֶץ וְהוּא מִשֶּׁיִּקְשֹׁר הַמָּתוֹק. וְלֹא יַעֲשֶׂה אַשְׁפָּה פְּחוּתָה מִמֵּאָה וַחֲמִשִּׁים סְאָה שֶׁל זֶבֶל כְּדֵי שֶׁתִּהְיֶה נִכֶּרֶת שֶׁהִיא אַשְׁפָּה. וְאִם יִרְצֶה לְהוֹסִיף מוֹסִיף. הָיָה לוֹ דָּבָר מֻעָט מוֹסִיף עָלָיו וְהוֹלֵךְ. וְלֹא יַעֲשֶׂה בְּכָל בֵּית סְאָה יֶתֶר מִשָּׁלֹשׁ אַשְׁפַּתּוֹת:","וְהָרוֹצֶה לַעֲשׂוֹת כָּל שָׂדֵהוּ שָׁלֹשׁ שָׁלֹשׁ אַשְׁפַּתּוֹת לְתוֹךְ בֵּית סְאָה עוֹשֶׂה. וְהָרוֹצֶה לַעֲשׂוֹת זִבְלוֹ אוֹצָר עוֹשֶׂה:","הָיָה מַעֲמִיד הַזֶּבֶל עַל הַסֶּלַע אוֹ שֶׁהֶעֱמִיק בָּאָרֶץ שְׁלֹשָׁה טְפָחִים וְהֶעֱרִים הַזֶּבֶל אוֹ שֶׁבָּנָה עַל הָאָרֶץ גֹּבַהּ שְׁלֹשָׁה וְהֶעֱמִיד עָלָיו הַזֶּבֶל. אֵינוֹ צָרִיךְ שִׁעוּר. אֲפִלּוּ עָשָׂה כֵּן כַּמָּה אַשְׁפַּתּוֹת לְתוֹךְ בֵּית סְאָה בֵּין גְּדוֹלוֹת בֵּין קְטַנּוֹת מֻתָּר. שֶׁהֲרֵי הַדָּבָר נִכָּר שֶׁאֵינָן לַעֲבוֹדַת הָאָרֶץ אֶלָּא לִכְנִיסַת הַזֶּבֶל:","מֻתָּר לְאָדָם לְהוֹצִיא זֶבֶל מִן הַסַּהַר שֶׁל צֹאן וְנוֹתֵן לְתוֹךְ שָׂדֵהוּ כְּדֶרֶךְ כָּל מַכְנִיסֵי זֶבֶל. וְהָעוֹשֶׂה דִּיר בְּתוֹךְ שָׂדֵהוּ בַּשְּׁבִיעִית לֹא יַעֲשֵׂהוּ יֶתֶר עַל בֵּית סָאתַיִם וְיַכְנִיס הַצֹּאן לְתוֹכוֹ. וּכְשֶׁיְּזַבְּלוּ אֶת כָּל הַדִּיר מֵנִיחַ דֹּפֶן אֶחָד מִדָּפְנֵי הַדִּיר וְעוֹשֶׂה דִּיר אַחֵר בְּצִדּוֹ. נִמְצָא מְזַבֵּל בְּתוֹךְ שָׂדֵהוּ בֵּית אַרְבַּעַת סְאִין:","הָיְתָה כָּל שָׂדֵהוּ בֵּית אַרְבַּעַת סְאִין מְשַׁיֵּר מִמֶּנָּה מִקְצָת מִפְּנֵי מַרְאִית הָעַיִן. כְּדֵי שֶׁיֵּדְעוּ הַכּל שֶׁהַצֹּאן הֵטִילוּ בָּהּ וְנִדַּיְירָה. וְלֹא יֹאמְרוּ זִבֵּל זֶה כָּל שָׂדֵהוּ בַּשְּׁבִיעִית:","לֹא יִפְתַּח אָדָם מֶחְצָב בַּתְּחִלָּה לְתוֹךְ שָׂדֵהוּ בַּשְּׁבִיעִית שֶׁמָּא יֹאמְרוּ לְתַקֵּן שָׂדֵהוּ נִתְכַּוֵּן שֶׁיָּסִיר מִמֶּנָּה הַסֶּלַע. וְאִם הִתְחִיל מִקֹּדֶם שְׁבִיעִית וּפִצֵּל מִמֶּנָּה שֶׁבַע וְעֶשְׂרִים אֲבָנִים בְּרִבּוּעַ שָׁלֹשׁ עַל שָׁלֹשׁ עַל רוּם שָׁלֹשׁ כָּל אֶבֶן מֵהֶן אַמָּה עַל אַמָּה בְּרוּם אַמָּה אוֹ גְּדוֹלוֹת מִזּוֹ הֲרֵי זֶה מֻתָּר לְנַקֵּר מִמֶּנּוּ בַּשְּׁבִיעִית כָּל מַה שֶּׁיִּרְצֶה:","גָּדֵר שֶׁל אֲבָנִים שֶׁיֵּשׁ בְּגָבְהוֹ עֲשָׂרָה טְפָחִים אוֹ יֶתֶר וְרָצָה לִטּל כָּל אֲבָנָיו אִם הָיוּ בּוֹ עֶשֶׂר אֲבָנִים אוֹ יֶתֶר כָּל אַחַת מֵהֶן מַשּׂוֹי שְׁנַיִם אוֹ גְּדוֹלוֹת מִזּוֹ הֲרֵי זֶה נוֹטֵל שֶׁהָרוֹאֶה יוֹדֵעַ שֶׁלְּצֹרֶךְ הָאֲבָנִים הוּא נוֹטֵל. הָיָה פָּחוֹת מֵעֲשָׂרָה אוֹ שֶׁהָיוּ פָּחוֹת מֵעֶשֶׂר אֲבָנִים אוֹ שֶׁהָיוּ אֲבָנָיו קְטַנּוֹת מִמַּשּׂוֹי שְׁנַיִם נוֹטֵל עַד שֶׁיַּנִּיחַ טֶפַח סָמוּךְ לָאָרֶץ:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁנִּתְכַּוֵּן לְתַקֵּן שָׂדֵהוּ (אוֹ) שֶׁהִתְחִיל לִטּל בַּשְּׁבִיעִית. אֲבָל אִם לֹא נִתְכַּוֵּן לְתַקֵּן שָׂדֵהוּ אוֹ שֶׁהִתְחִיל מִקֹּדֶם שְׁבִיעִית נוֹטֵל בַּשְּׁבִיעִית כָּל מַה שֶּׁיִּרְצֶה מִכָּל מָקוֹם וּגוֹמֵם עַד לָאָרֶץ. וְכֵן אִם הָיָה נוֹטֵל מִשְּׂדֵה חֲבֵרוֹ אַף עַל פִּי שֶׁהוּא קִבְּלָן גּוֹמֵם עַד לָאָרֶץ:","אֲבָנִים שֶׁרְאוּיוֹת שֶׁתְּזַעְזֵעַ אוֹתָן הַמַּחֲרֵשָׁה אוֹ שֶׁהָיוּ מְכֻסּוֹת וְנִתְגַּלּוּ. אִם יֵשׁ בָּהֶן שְׁתַּיִם שֶׁל מַשּׂוֹי שְׁנַיִם שְׁנַיִם הֲרֵי זֶה מֻתָּר לִטּוֹל אוֹתָן. הָיוּ קְטַנּוֹת מִזֶּה לֹא יִנָּטְלוּ:","הַמְסַקֵּל שָׂדֵהוּ בַּשְּׁבִיעִית מִפְּנֵי שֶׁהוּא צָרִיךְ לָאֲבָנִים נוֹטֵל אֶת הָעֶלְיוֹנוֹת וּמַנִּיחַ אֶת הַנּוֹגְעוֹת בָּאָרֶץ. וְכֵן אִם הָיָה לוֹ בְּשָׂדֵהוּ גַּרְגֵּר שֶׁל צְרוֹרוֹת אוֹ גַּל שֶׁל אֲבָנִים נוֹטֵל אֶת הָעֶלְיוֹנוֹת וּמַנִּיחַ אֶת הַנּוֹגְעוֹת בָּאָרֶץ. וְאִם יֵשׁ תַּחְתֵּיהֶן סֶלַע אוֹ קַשׁ יִטּל אֶת כֻּלָּן:","לֹא יְמַלֵּא אָדָם גַּיא עָפָר אוֹ יְתַקְּנֶנּוּ בְּעָפָר מִפְּנֵי שֶׁמְּתַקֵּן אֶת הָאָרֶץ. אֲבָל עוֹשֶׂה הוּא חַיִץ עַל פְּנֵי הַגַּיא. וְכָל אֶבֶן שֶׁיָּכוֹל לִפְשֹׁט אֶת יָדוֹ וְלִטְּלָהּ וְהוּא עוֹמֵד עַל שְׂפַת הַגַּיא הֲרֵי זוֹ תִּנָּטֵל:","אַבְנֵי כָּתֵף וְהֵם הַנִּטָּלוֹת שְׁתַּיִם שָׁלֹשׁ עַל הַכָּתֵף מֻתָּר לַהֲבִיאָן מִכָּל מָקוֹם בֵּין מִשְּׂדֵה חֲבֵרוֹ בֵּין מִשָּׂדֵהוּ. וְכֵן הַקַּבְּלָן מֵבִיא מִכָּל מָקוֹם וַאֲפִלּוּ אֲבָנִים גְּדוֹלוֹת בֵּין מִשָּׂדֶה שֶׁקִּבְּלָהּ בֵּין מִשָּׂדֶה שֶׁלֹּא קִבְּלָהּ:","פִּרְצָה שֶׁהִיא סוּגָה בְּעָפָר אִם אֵינָהּ מַכְשֶׁלֶת אֶת הָרַבִּים אָסוּר לִבְנוֹתָהּ. וְאִם הָיְתָה מַכְשֶׁלֶת אֶת הָרַבִּים אוֹ שֶׁלֹּא הָיְתָה סוּגָה בְּעָפָר אֶלָּא פְּתוּחָה לִרְשׁוּת הָרַבִּים מֻתָּר לִבְנוֹתָהּ:","אָסוּר לוֹ לִבְנוֹת גָּדֵר בַּשְּׁבִיעִית בֵּין שָׂדֵהוּ לִשְׂדֵה חֲבֵרוֹ. אֲבָל בּוֹנֶה גָּדֵר בֵּינוֹ וּבֵין רְשׁוּת הָרַבִּים. וּמֻתָּר לְהַעֲמִיק עַד הַסֶּלַע וּמוֹצִיא אֶת הֶעָפָר וְצוֹבְרוֹ בְּתוֹךְ שָׂדֵהוּ כְּדֶרֶךְ כָּל מַעֲמִידִין זֶבֶל. וְכֵן אִם חָפַר בּוֹר וְשִׁיחַ וּמְעָרָה בַּשְּׁבִיעִית צוֹבֵר הֶעָפָר בְּתוֹךְ שָׂדֵהוּ כְּדֶרֶךְ כָּל הַחוֹפְרִים:"],"Mishneh Torah, Sacrifices Rendered Unfit 13":["שָׁלֹשׁ מַחְשָׁבוֹת הֵן שֶׁפּוֹסְלִין אֶת הַקָּרְבָּנוֹת. וְאֵלּוּ הֵן. מַחֲשִׁבֶת שִׁנּוּי הַשֵּׁם. וּמַחְשֶׁבֶת הַמָּקוֹם. וּמַחְשֶׁבֶת הַזְּמַן. מַחֲשֶׁבֶת שִׁנּוּי הַשֵּׁם כֵּיצַד. זֶה הַשּׁוֹחֵט אֶת הַזֶּבַח שֶׁלֹּא לִשְׁמוֹ. כְּגוֹן שֶׁהָיָה עוֹלָה וְיַחְשֹׁב שֶׁהוּא שְׁלָמִים. אוֹ יִשְׁחָטֶנּוּ לְשֵׁם עוֹלָה וּשְׁלָמִים. אוֹ לְשֵׁם שְׁלָמִים וּלְשֵׁם עוֹלָה. אוֹ שֶׁשָּׁחַט הַזֶּבַח שֶׁלֹּא לְשֵׁם בְּעָלָיו. זוֹ הִיא מַחֲשֶׁבֶת שִׁנּוּי הַשֵּׁם. מַחֲשֶׁבֶת הַמָּקוֹם כֵּיצַד. כְּגוֹן שֶׁשָּׁחַט אֶת הַזֶּבַח לִשְׁמוֹ עַל מְנָת לִזְרֹק דָּמוֹ. אוֹ לְהַקְטִיר מִמֶּנּוּ דָּבָר הָרָאוּי לְהַקְטָרָה חוּץ לָעֲזָרָה. אוֹ לֶאֱכל מִמֶּנּוּ דָּבָר הָרָאוּי לַאֲכִילָה חוּץ לִמְקוֹם אֲכִילָתוֹ. זוֹ הִיא מַחֲשֶׁבֶת הַמָּקוֹם. וּזְבָחִים שֶׁחָשַׁב בָּהֶן מַחֲשָׁבָה זוֹ הֵם הַנִּקְרָאִים זְבָחִים שֶׁשְּׁחָטָן חוּץ לִמְקוֹמָן. מַחֲשֶׁבֶת הַזְּמַן כֵּיצַד. כְּגוֹן שֶׁשָּׁחַט אֶת הַזֶּבַח לִשְׁמוֹ עַל מְנָת לִזְרֹק דָּמוֹ מֵאַחַר שֶׁתִּשְׁקַע הַחַמָּה שֶׁאֵינוֹ זְמַן זְרִיקָתוֹ. אוֹ לְהַקְטִיר מִמֶּנּוּ דָּבָר הָרָאוּי לְהַקְטִיר לְמָחָר מֵאַחַר שֶׁיַּעֲלֶה עַמּוּד הַשַּׁחַר שֶׁאֵינוֹ זְמַן הַקְטָרָתוֹ. אוֹ לֶאֱכל מִמֶּנּוּ דָּבָר הָרָאוּי לַאֲכִילָה לְאַחַר זְמַן הָרָאוּי לַאֲכִילָתוֹ. זוֹ הִיא מַחֲשֶׁבֶת הַזְּמַן. וּזְבָחִים שֶׁחִשֵּׁב בָּהֶן מַחֲשָׁבָה זוֹ הֵם הַנִּקְרָאִים זְבָחִים שֶׁנִּשְׁחֲטוּ חוּץ לִזְמַנָּן וְהֵם הַנִּקְרָאִים פִּגּוּל בְּכָל מָקוֹם. וְזֶהוּ (ויקרא ז יח) (ויקרא יט ז) \"פִּגּוּל\" הֶאָמוּר בַּתּוֹרָה:","מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה שֶׁנֶּאֱמַר בַּתּוֹרָה (ויקרא ז יח) \"וְאִם הֵאָכל יֵאָכֵל מִבְּשַׂר זֶבַח שְׁלָמָיו\" אֵינוֹ מְדַבֵּר אֶלָּא בִּמְחַשֵּׁב בִּשְׁעַת הַקְרָבָה שֶׁיֹּאכַל מִמֶּנּוּ בַּשְּׁלִישִׁי. וְהוּא הַדִּין לְכָל קָרְבָּן שֶׁחִשֵּׁב עָלָיו בִּשְׁעַת מַעֲשָׂיו שֶׁיֹּאכַל מִמֶּנּוּ לְאַחַר זְמַן הָרָאוּי לַאֲכִילַת אוֹתוֹ קָרְבָּן. וְכֵן אִם חִשֵּׁב לְהַקְטִיר מִמֶּנּוּ בַּמִּזְבֵּחַ דָּבָר הָרָאוּי לְהַקְטָרָה [לְאַחַר זְמַן הָרָאוּי לְהַקְטָרָה]. כָּךְ לָמְדוּ מִפִּי הַשְּׁמוּעָה. אֶחָד אֲכִילַת אָדָם וְאֶחָד אֲכִילַת מִזְבֵּחַ. אִם חִשֵּׁב עֲלֵיהֶן אַחַר זְמַנָּן הֲרֵי הַקָּרְבָּן פִּגּוּל:","אֲבָל קָרְבָּן שֶׁלֹּא נִפְסְדָה מַחְשַׁבְתּוֹ אֶלָּא נִזְרַק דָּמוֹ עַל הַמִּזְבֵּחַ כְּהִלְכָתוֹ וְנִשְׁאַר מִמֶּנּוּ לְאַחַר זְמַן אֲכִילָתוֹ. אוֹתוֹ הַנִּשְׁאָר נִקְרָא נוֹתָר וְאָסוּר לְאָכְלוֹ. וְהַקָּרְבָּן כְּבָר נִרְצָה וְכִפֵּר. הֲרֵי הוּא אוֹמֵר בַּדָּם (ויקרא יז יא) \"וַאֲנִי נְתַתִּיו לָכֶם עַל הַמִּזְבֵּחַ לְכַפֵּר\" כֵּיוָן שֶׁהִגִּיעַ דָּם לַמִּזְבֵּחַ כְּהִלְכָתוֹ נִתְכַּפְּרוּ הַבְּעָלִים וְנִרְצָה הַקָּרְבָּן. לְפִיכָךְ אֵין מִתְפַּגֵּל אֶלָּא דָּבָר שֶׁיֵּשׁ לוֹ מַתִּירִין בֵּין לָאָדָם בֵּין לַמִּזְבֵּחַ כְּמוֹ שֶׁיִּתְבָּאֵר. אֶחָד זֶבַח שֶׁחִשֵּׁב בּוֹ אַחַת מִשָּׁלֹשׁ מַחֲשָׁבוֹת אֵלּוּ בִּשְׁעַת שְׁחִיטָה. אוֹ שֶׁחִשֵּׁב בִּשְׁעַת קַבָּלַת הַדָּם. אוֹ בִּשְׁעַת הוֹלָכָתוֹ לַמִּזְבֵּחַ. אוֹ בְּעֵת זְרִיקָתוֹ עַל הַמִּזְבֵּחַ:","נִמְצֵאתָ לָמֵד שֶׁבְּאַרְבַּע עֲבוֹדוֹת הַזֶּבַח נִפְסַל בְּמַחְשָׁבָה. בַּשְּׁחִיטָה. וּבַקַּבָּלָה. וּבְהוֹלָכַת הַדָּם. וּבִזְרִיקָתוֹ עַל הַמִּזְבֵּחַ:","וְהָעוֹף בִּשְׁנֵי דְּבָרִים. בַּמְּלִיקָה. וּבְמִצּוּי הַדָּם:","וְהַמְּנָחוֹת הַנִּקְמָצוֹת בְּאַרְבָּעָה. בַּקְּמִיצָה. וּבִנְתִינַת הַקֹּמֶץ בִּכְלִי שָׁרֵת. וּבְהוֹלָכַת הַקֹּמֶץ לַמִּזְבֵּחַ. וּבִזְרִיקָתוֹ עַל הָאֵשׁ:","אֲבָל אִם חִשֵּׁב בִּדְבָרִים אֲחֵרִים חוּץ מֵאֵלּוּ. כְּגוֹן שֶׁחִשֵּׁב בִּשְׁעַת הֶפְשֵׁט אוֹ בִּשְׁעַת נִתּוּחַ אוֹ בִּשְׁעַת הוֹלָכַת אֵימוּרִין לַמִּזְבֵּחַ. אוֹ בִּשְׁעַת בְּלִילַת הַמִּנְחָה אוֹ בִּשְׁעַת הַגָּשָׁתָהּ. וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. אֵין אוֹתָהּ הַמַּחְשָׁבָה מוֹעֶלֶת כְּלוּם. בֵּין שֶׁהָיְתָה מַחֲשֶׁבֶת שִׁנּוּי הַשֵּׁם בֵּין מַחֲשֶׁבֶת הַמָּקוֹם בֵּין מַחֲשֶׁבֶת הַזְּמַן:","וְכֵן הַמְחַשֵּׁב בְּאַחַת מֵאַרְבַּע עֲבוֹדוֹת אֵלּוּ אוֹ בְּכֻלָּן מַחֲשָׁבָה אַחֶרֶת חוּץ מִשָּׁלֹשׁ מַחֲשָׁבוֹת אֵלּוּ אֵין אוֹתָהּ הַמַּחְשָׁבָה מַפְסֶדֶת כְּלוּם. כֵּיצַד. הַמְחַשֵּׁב בִּשְׁעַת שְׁחִיטָה וְקַבָּלָה וְהוֹלָכָה וּזְרִיקָה לְהָנִיחַ דַּם הַזֶּבַח אוֹ אֵימוּרָיו לְמָחָר. אוֹ לְהוֹצִיאָן חוּץ לָעֲזָרָה. אוֹ שֶׁחִשֵּׁב לִזְרֹק הַדָּם עַל הַכֶּבֶשׁ שֶׁלֹּא כְּנֶגֶד הַיְסוֹד. אוֹ לִתֵּן אֶת הַנִּתָּנִין לְמַעְלָה לְמַטָּה וְאֶת הַנִּתָּנִין לְמַטָּה לְמַעְלָה. אוֹ לִתֵּן דָּמִים הַנִּתָּנִין בַּמִּזְבֵּחַ הַחִיצוֹן בַּמִּזְבֵּחַ הַפְּנִימִי. אוֹ אֶת הַנִּתָּנִין בַּפְּנִימִי לַחִיצוֹן. אוֹ לְהַכְנִיס דַּם הַחַטָּאת לִפְנִים. אוֹ שֶׁחִשֵּׁב שֶׁיֹּאכְלוּ הַזֶּבַח טְמֵאִים אוֹ שְׁאָר הַפְּסוּלִין לַאֲכִילָה. אוֹ שֶׁיַּקְרִיבוּם טְמֵאִים אוֹ שְׁאָר הַפְּסוּלִין לַעֲבוֹדָה. אוֹ לְעָרֵב דַּם הַזֶּבַח בְּדַם הַפְּסוּלִין. אוֹ שֶׁחִשֵּׁב לִשְׁבֹּר עַצְמוֹת הַפֶּסַח ולֶאֱכל מִמֶּנּוּ נָא. אוֹ שֶׁחִשֵּׁב לִשְׂרֹף חַטָּאת הַנִּשְׂרֶפֶת חוּץ לִזְמַנָּן. אוֹ חוּץ לִמְקוֹמָן. בְּכָל אֵלּוּ הַמַּחְשָׁבוֹת וְכַיּוֹצֵא בָּהֶן הַזֶּבַח כָּשֵׁר. וְכֵן אִם חִשֵּׁב בִּשְׁעַת קְמִיצַת הַמִּנְחָה וּבִשְׁעַת נְתִינָתוֹ לַכְּלִי וּבִשְׁעַת הוֹלָכָתוֹ וּבִשְׁעַת זְרִיקָתוֹ עַל הָאֵשׁ לְהָנִיחַ קֻמְצָהּ אוֹ לְבוֹנָתוֹ לְמָחָר אוֹ לְהוֹצִיאוֹ לַחוּץ הֲרֵי זוֹ כְּשֵׁרָה:","כְּבָר בֵּאַרְנוּ שֶׁהוֹלָכָה שֶׁלֹּא בָּרֶגֶל אֵינָהּ הוֹלָכָה. לְפִיכָךְ אֵין הַמַּחְשָׁבָה פּוֹסֶלֶת בָּהּ. וְהַמְהַלֵּךְ בְּמָקוֹם שֶׁאֵינוֹ צָרִיךְ הֲרֵי זוֹ הוֹלָכָה וְהַמַּחְשָׁבָה פּוֹסֶלֶת בָּהּ. כֵּיצַד. קִבֵּל הַדָּם וְהוּא עוֹמֵד בִּמְקוֹמוֹ וּפָשַׁט יָדוֹ לְזָרְקוֹ עַל הַמִּזְבֵּחַ. וְחִשֵּׁב בְּעֵת שֶׁפָּשַׁט יָדוֹ בַּדָּם אֵין הַמַּחְשָׁבָה פּוֹסֶלֶת בָּהּ. אֲבָל אִם קִבֵּל הַדָּם בִּפְנִים וְלֹא הִלֵּךְ בּוֹ לְגַבֵּי הַמִּזְבֵּחַ אֶלָּא הִלֵּךְ בּוֹ וְהוֹצִיאוֹ לַחוּץ. וְחִשֵּׁב בִּשְׁעַת הִלּוּכוֹ לַחוּץ בְּמַחְשֶׁבֶת הַזְּמַן וְכַיּוֹצֵא בָּהּ. הֲרֵי זוֹ פּוֹסֶלֶת:"],"Mishneh Torah, Sacrifices Rendered Unfit 7":["כָּל הַפְּסוּלִין לַעֲבוֹדָה שֶׁמָּלְקוּ מְלִיקָתָן פְּסוּלָה. וְאַף עַל פִּי שֶׁאוֹתוֹ הָעוֹף פָּסוּל אֵינוֹ כְּנִבְלַת הָעוֹף הַטָּהוֹר לְטֻמְאָה. וְכֵן אִם מָלַק בַּלַּיְלָה אוֹ שֶׁשָּׁחַט חֻלִּין בִּפְנִים וְקָדָשִׁים בַּחוּץ. אֵינָהּ כִּנְבֵלָה:","מָלַק תּוֹרִים שֶׁלֹּא הִגִּיעַ זְמַנָּן וּבְנֵי יוֹנָה שֶׁעָבַר זְמַנָּם וְשֶׁיָּבַשׁ גַּפָּהּ וְשֶׁנִּסְמֵית עֵינָהּ וְשֶׁנִּקְטְעָה רַגְלָהּ הֲרֵי זוֹ נְבֵלָה לְכָל דָּבָר. זֶה הַכְּלָל כָּל שֶׁהָיָה פְּסוּלָהּ בַּקֹּדֶשׁ פְּסוּלָה וְאֵינָהּ נְבֵלָה. לֹא הָיָה פְּסוּלָהּ בַּקֹּדֶשׁ הֲרֵי זוֹ נְבֵלָה לְכָל דָּבָר:","לְפִיכָךְ הַמּוֹלֵק וְנִמְצֵאת טְרֵפָה. אוֹ שֶׁמָּלַק בְּסַכִּין אוֹ שֶׁמָּלַק חֻלִּין בִּפְנִים וְקָדָשִׁים בַּחוּץ. הֲרֵי זוֹ נְבֵלָה לְכָל דָּבָר. שֶׁאֵין הַמְּלִיקָה מַתֶּרֶת וּמְטַהֶרֶת אֶלָּא דָּבָר שֶׁהוּא כָּשֵׁר לַמִּזְבֵּחַ:","אֲבָל הַנִּרְבָּע וְהַמֻּקְצֶה וְהַנֶּעֱבָד וְהָאֶתְנָן וְהַמְּחִיר וְהַטֻּמְטוּם וְהָאַנְדְּרוֹגִינוּס שֶׁנִּמְלְקוּ. הֲרֵי אֵלּוּ נְבֵלָה לְכָל דָּבָר וּמְטַמְּאִין בְּגָדִים בְּבֵית הַבְּלִיעָה. שֶׁאֵין הַקְּדֻשָּׁה חָלָה עֲלֵיהֶן וַהֲרֵי אֵין פְּסוּלָן בְּקֹדֶשׁ:","כְּבָר בֵּאַרְנוּ בְּמַעֲשֵׂה הַקָּרְבָּנוֹת שֶׁחַטַּאת הָעוֹף נַעֲשֵׂית לְמַטָּה וְעוֹלַת הָעוֹף לְמַעְלָה. חַטַּאת הָעוֹף שֶׁעֲשָׂאָהּ לְמַעְלָה פְּסוּלָה. בֵּין שֶׁעָשָׂה הַזָּיָתָהּ כְּמַעֲשֵׂה חַטָּאת. בֵּין שֶׁעֲשָׂאָהּ כְּמַעֲשֵׂה עוֹלָה. בֵּין שֶׁעֲשָׂאָהּ לְשֵׁם עוֹלָה. בֵּין שֶׁעֲשָׂאָהּ לְשֵׁם חַטָּאת:","וְכֵן עוֹלַת הָעוֹף שֶׁעֲשָׂאָהּ לְמַטָּה אֲפִלּוּ מָלַק סִימָן אֶחָד לְמַטָּה וְסִימָן אֶחָד לְמַעְלָה פְּסוּלָה בֵּין שֶׁמְּלָקוֹ כִּמְלִיקַת עוֹלָה בֵּין שֶׁעֲשָׂאָהּ כְּמַעֲשֵׂה חַטָּאת. בֵּין שֶׁעֲשָׂאָהּ לְשֵׁם חַטָּאת בֵּין שֶׁעֲשָׂאָהּ לְשֵׁם עוֹלָה:","חַטַּאת הָעוֹף שֶׁמְּלָקָהּ לְמַטָּה כִּמְלִיקַת עוֹלָה לְשֵׁם חַטָּאת אוֹ כְּמַעֲשֵׂה חַטָּאת לְשֵׁם עוֹלָה אוֹ כְּמַעֲשֵׂה עוֹלָה לְשֵׁם עוֹלָה פְּסוּלָה:","וְכֵן עוֹלַת הָעוֹף שֶׁעֲשָׂאָהּ לְמַעְלָה כְּמַעֲשֵׂה חַטָּאת לְשֵׁם עוֹלָה אוֹ כְּמַעֲשֵׂה חַטָּאת לְשֵׁם חַטָּאת פְּסוּלָה. כְּמַעֲשֵׂה עוֹלָה לְשֵׁם חַטָּאת כְּשֵׁרָה. וּבִלְבַד שֶׁלֹּא עָלְתָה לַבְּעָלִים לְשֵׁם חוֹבָה:","כָּל אֵלּוּ הָעוֹפוֹת שֶׁנִּפְסְלוּ מִפְּנֵי מְקוֹם עֲשִׂיָּתָן אוֹ מִפְּנֵי שִׁנּוּי מַעֲשֵׂיהֶן אוֹ שִׁנּוּי שְׁמָם. אֵינָן כְּנִבְלַת הָעוֹף לְטֻמְאָה. וְכֵן חַטַּאת הָעוֹף אוֹ עוֹלַת הָעוֹף שֶׁנִּתְפַּגְּלָה אוֹ נִטְמְאָה אוֹ נַעֲשֵׂית נוֹתָר אֵינָהּ מְטַמְּאָה בְּבֵית הַבְּלִיעָה כְּנִבְלַת הָעוֹף. שֶׁכָּל אֵלּוּ פְּסוּלָן בְּקֹדֶשׁ:","חַטַּאת הָעוֹף הַבָּאָה עַל הַסָּפֵק נַעֲשֵׂית כְּמִצְוָתָהּ וְאֵינָהּ נֶאֱכֶלֶת אֶלָּא תִּשָּׂרֵף כְּכָל פְּסוּלֵי הַמֻּקְדָּשִׁין. וְכֵיצַד תָּבוֹא עַל הַסָּפֵק. כְּגוֹן שֶׁהָיְתָה הָאִשָּׁה סְפֵק זָבָה אוֹ סְפֵק יוֹלֶדֶת וְכָל כַּיּוֹצֵא בָּזֶה. וְאֵין לָנוּ חַטַּאת בְּהֵמָה עַל סָפֵק. שֶׁאִם נִסְתַּפֵּק לוֹ אִם חָטָא אִם לֹא חָטָא יָבִיא אָשָׁם תָּלוּי כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת שְׁגָגוֹת:","חַטַּאת הָעוֹף הַבָּאָה עַל הַסָּפֵק וְנוֹדַע שֶׁהִיא חַיֶּבֶת בָּהּ וַדַּאי. אִם עַד שֶׁלֹּא נִמְלְקָה נוֹדַע לָהּ תֵּעָשֶׂה וַדָּאִית וְתֵאָכֵל. וְאִם אַחַר שֶׁנִּמְלְקָה נוֹדַע לָהּ הֲרֵי זֶה גּוֹמֵר הַזָּיַת דָּמָהּ וְתַמְצִיתוֹ וְתִשָּׂרֵף כְּדֵי שֶׁלֹּא יֹאמְרוּ חַטַּאת הָעוֹף הַבָּאָה עַל הַסָּפֵק תֵּאָכֵל שֶׁהֲרֵי בַּתְּחִלָּה עַל סָפֵק בָּאָה:","נוֹדַע לָהּ שֶׁאֵינָהּ חַיֶּבֶת בָּהּ מֵאַחַר שֶׁנִּמְלְקָה הֲרֵי זוֹ תִּקָּבֵר:"],"Mishneh Torah, Sacrificial Procedure 18":["כָּל הַקָּרְבָּנוֹת כֻּלָּן בֵּין קָרְבְּנוֹת בְּהֵמָה וְעוֹף בֵּין קָרְבְּנוֹת מְנָחוֹת מִצְוַת עֲשֵׂה לְהַקְרִיבָן בְּבֵית הַבְּחִירָה שֶׁנֶּאֱמַר (דברים יב יד) \"וְשָׁם תַּעֲשֶׂה כּל אֲשֶׁר אָנֹכִי מְצַוֶּךָּ\". וְכֵן מִצְוַת עֲשֵׂה לִהְיוֹת כָּל אָדָם מְטַפֵּל וּמֵבִיא קָרְבְּנוֹת בְּהֵמָה שֶׁנִּתְחַיֵּב לְהַקְרִיבָן מִחוּצָה לָאָרֶץ לְבֵית הַבְּחִירָה שֶׁנֶּאֱמַר (דברים יב כו) \"קָדָשֶׁיךָ אֲשֶׁר יִהְיוּ לְךָ וּנְדָרֶיךָ תִּשָּׂא\" וְגוֹ'. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁאֵינוֹ מְדַבֵּר אֶלָּא בְּקָדְשֵׁי חוּצָה לָאָרֶץ שֶׁהוּא מְטַפֵּל בָּהֶם עַד שֶׁיְּבִיאֵם לְבֵית הַבְּחִירָה:","הַמַּקְרִיב קָרְבָּן חוּץ לָעֲזָרָה בִּטֵּל מִצְוַת עֲשֵׂה וְעָבַר עַל לֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים יב יג) \"הִשָּׁמֶר לְךָ פֶּן תַּעֲלֶה עלֹתֶיךָ בְּכָל מָקוֹם אֲשֶׁר תִּרְאֶה\". וְאִם הִקְרִיב בְּמֵזִיד חַיָּב כָּרֵת שֶׁנֶּאֱמַר (ויקרא יז ח) \"אֲשֶׁר יַעֲלֶה עלָה אוֹ זָבַח\" (ויקרא יז ט) \"וְאֶל פֶּתַח אֹהֶל מוֹעֵד לֹא הֱבִיאוֹ\" \"וְנִכְרַת מֵעַמָּיו\". בְּשׁוֹגֵג מֵבִיא חַטָּאת קְבוּעָה:","וְכֵן הַשּׁוֹחֵט קָדָשִׁים חוּץ לָעֲזָרָה אַף עַל פִּי שֶׁלֹּא הֶעֱלָם אִם הָיָה מֵזִיד חַיָּב כָּרֵת שֶׁנֶּאֱמַר (ויקרא יז ג) \"אֲשֶׁר יִשְׁחַט שׁוֹר אוֹ כֶשֶׂב אוֹ עֵז\" וְגוֹ' (ויקרא יז ד) \"דָּם יֵחָשֵׁב לָאִישׁ הַהוּא דָּם שָׁפָךְ וְנִכְרַת\". וְאִם שָׁחַט בְּשׁוֹגֵג מֵבִיא חַטָּאת קְבוּעָה:","וְהֵיכָן הִזְהִיר עַל הַשְּׁחִיטָה בַּחוּץ. בְּהֶקֵּשׁ. נֶאֱמַר (דברים יב יד) \"שָׁם תַּעֲלֶה עלֹתֶיךָ\" וְנֶאֱמַר (דברים יב יד) \"וְשָׁם תַּעֲשֶׂה כּל אֲשֶׁר אָנֹכִי מְצַוֶּךָּ\". מָה הָעֲלִיָּה בַּחוּץ שֶׁעָנַשׁ עָלֶיהָ הִזְהִיר עָלֶיהָ בְּפֵרוּשׁ שֶׁנֶּאֱמַר (דברים יב יג) \"הִשָּׁמֶר לְךָ פֶּן תַּעֲלֶה עלֹתֶיךָ\". אַף עֲשִׂיָּה שֶׁבִּכְלַל הַשְּׁחִיטָה שֶׁעָנַשׁ עָלֶיהָ בְּפֵרוּשׁ הֲרֵי הוּא מֻזְהָר עָלֶיהָ. שֶׁלֹּא עָנַשׁ הַכָּתוּב אֶלָּא אִם כֵּן הִזְהִיר:","הַשּׁוֹחֵט קָדָשִׁים וְהֶעֱלָם בַּחוּץ חַיָּב שְׁתַּיִם. אַחַת עַל הַשְּׁחִיטָה וְאַחַת עַל הָעֲלִיָּה. שָׁחַט בִּפְנִים וְהֶעֱלָה בַּחוּץ חַיָּב עַל הָעֲלִיָּה. וְכֵן אִם שָׁחַט בַּחוּץ וְהֶעֱלָה בִּפְנִים חַיָּב עַל הַשְּׁחִיטָה:","אֵינוֹ חַיָּב אֶלָּא עַל שְׁחִיטַת קָדָשִׁים הָרְאוּיִין לִקָּרֵב לְגַבֵּי מִזְבֵּחַ. אֲבָל הַשּׁוֹחֵט בַּחוּץ אֶחָד מֵאִסּוּרֵי מִזְבֵּחַ אוֹ מֵחַטָּאוֹת הַמֵּתוֹת הֲרֵי זֶה פָּטוּר שֶׁנֶּאֱמַר (ויקרא יז ד) \"לִפְנֵי מִשְׁכַּן ה'\" וְכָל שֶׁאֵינוֹ רָאוּי לָבוֹא אֶל מִשְׁכַּן ה' אֵין חַיָּבִין עָלָיו:","שָׁחַט בַּחוּץ מְחֻסַּר זְמַן בְּגוּפוֹ אוֹ בַּבְּעָלִים הוֹאִיל וְאֵינוֹ רָאוּי עַתָּה לָבוֹא בִּפְנִים פָּטוּר:","אֵי זֶהוּ מְחֻסַּר זְמַן בְּגוּפוֹ. בְּהֵמָה בְּתוֹךְ שִׁבְעַת יְמֵי הַלֵּידָה. וְתוֹרִין שֶׁלֹּא הִגִּיעַ זְמַנָּן. וְאוֹתוֹ וְאֶת בְּנוֹ שֶׁנִּשְׁחַט אֶחָד מֵהֶם הַיּוֹם שֶׁאֵין הַשֵּׁנִי רָאוּי עַד לְמָחָר:","וְאֵי זֶהוּ מְחֻסַּר זְמַן בַּבְּעָלִים. קָרְבָּן שֶׁעֲדַיִן לֹא הִגִּיעַ זְמַן בְּעָלָיו לְהַקְרִיבוֹ. כֵּיצַד. הַזָּב וְהַזָּבָה וְהַיּוֹלֶדֶת שֶׁשָּׁחֲטוּ חַטָּאתָם בַּחוּץ [בְּתוֹךְ] יְמֵי סְפִירָה פְּטוּרִין. וְכֵן מְצֹרָע שֶׁשָּׁחַט חַטָּאתוֹ וַאֲשָׁמוֹ בַּחוּץ בְּתוֹךְ יְמֵי הַסְּפִירָה פָּטוּר. שֶׁעֲדַיִן לֹא נִרְאוּ בַּעֲלֵי הַקָּרְבָּנוֹת הָאֵלּוּ לְכַפָּרָה. אֲבָל אִם שָׁחֲטוּ עוֹלוֹתֵיהֶן בַּחוּץ בְּתוֹךְ יְמֵי הַסְּפִירָה חַיָּבִין. שֶׁהָעוֹלָה דּוֹרוֹן הִיא וְהַחַטָּאת וְהָאָשָׁם הִיא עִקַּר הַכַּפָּרָה. וְכֵן נָזִיר שֶׁשָּׁחַט חַטָּאתוֹ בַּחוּץ בְּתוֹךְ יְמֵי נְזִירוּתוֹ פָּטוּר. הִקְרִיב עוֹלָתוֹ אוֹ שְׁלָמָיו בַּחוּץ חַיָּב שֶׁהַחַטָּאת הִיא הַמְּעַכַּבְתּוֹ וְהִיא עִקַּר הַנְּזִירוּת:","אָשָׁם תָּלוּי וְחַטָּאת הָעוֹף הַבָּאָה עַל הַסָּפֵק שֶׁהִקְרִיבָן בַּחוּץ פָּטוּר שֶׁהֲרֵי לֹא נִקְבַּע הָאִסּוּר. אָשָׁם מְצֹרָע שֶׁשְּׁחָטוֹ בַּחוּץ שֶׁלֹּא לִשְׁמוֹ חַיָּב הוֹאִיל וְשֶׁלֹּא לִשְׁמוֹ רָאוּי בִּפְנִים וְכָשֵׁר כְּמוֹ שֶׁיִּתְבָּאֵר. וְכָל קָרְבָּן שֶׁהוּא פָּטוּר עַל שְׁחִיטָתוֹ בַּחוּץ כָּךְ הוּא פָּטוּר עַל הַעֲלָאָתוֹ:","שְׁנֵי שְׂעִירֵי יוֹם הַכִּפּוּרִים שֶׁשְּׁחָטָם בַּחוּץ. אִם עַד שֶׁלֹּא הִתְוַדָּה עֲלֵיהֶם חַיָּב כָּרֵת עַל שְׁנֵיהֶן הוֹאִיל וּרְאוּיִין לָבוֹא לִפְנֵי הַשֵּׁם לְוִדּוּי. וְאִם אַחַר שֶׁהִתְוַדָּה פָּטוּר עַל הַמִּשְׁתַּלֵּחַ שֶׁהֲרֵי אֵינוֹ רָאוּי לָבוֹא לִפְנֵי הַשֵּׁם:","הַשּׁוֹחֵט שְׁלָמִים בַּחוּץ קֹדֶם שֶׁיִּפָּתְחוּ דַּלְתוֹת הַהֵיכָל פָּטוּר. שֶׁהֲרֵי הֵן מְחֻסָּרִים מַעֲשֶׂה וְאַחַר כָּךְ יִהְיוּ רְאוּיִין לִקָּרֵב לִפְנֵי הַשֵּׁם כְּמוֹ שֶׁבֵּאַרְנוּ. וְהַשּׁוֹחֵט אֶת הַפֶּסַח בַּחוּץ אֲפִלּוּ בִּשְׁאָר יְמוֹת הַשָּׁנָה בֵּין לִשְׁמוֹ בֵּין שֶׁלֹּא לִשְׁמוֹ חַיָּב. שֶׁהַפֶּסַח בִּשְׁאָר יְמוֹת הַשָּׁנָה שְׁלָמִים הוּא:","בֶּהֱמַת חֻלִּין שֶׁעֻבָּרָהּ קָדְשֵׁי מִזְבֵּחַ אָסוּר לְשָׁחֳטָהּ בַּחוּץ. וְאִם שְׁחָטָהּ אֵינוֹ לוֹקֶה מִפְּנֵי שֶׁאֵינָהּ רְאוּיָה לָבוֹא לִפְנֵי הַשֵּׁם:","גָּנַב וְהִקְדִּישׁ וְאַחַר כָּךְ שָׁחַט בַּחוּץ חַיָּב. וּמֵאֵימָתַי הֶעֱמִידוּהָ בִּרְשׁוּתוֹ כְּדֵי לְחַיְּבוֹ עָלֶיהָ כָּרֵת. מִשָּׁעָה שֶׁהִקְדִּישָׁהּ. וְהוּא שֶׁשְּׁחָטָהּ אַחַר יֵאוּשׁ אֲבָל לִפְנֵי יֵאוּשׁ אֵינָהּ קְדוֹשָׁה:","הָיְתָה הַבְּהֵמָה כֻּלָּהּ בַּחוּץ וְצַוָּארָהּ בִּפְנִים וְשָׁחַט חַיָּב שֶׁנֶּאֱמַר (ויקרא יז ג) \"אֲשֶׁר יִשְׁחַט שׁוֹר אוֹ כֶּבֶשׂ אוֹ עֵז בַּמַּחֲנֶה אוֹ אֲשֶׁר יִשְׁחַט מִחוּץ לַמַּחֲנֶה\". אֶחָד הַשּׁוֹחֵט בַּמִּקְדָּשׁ וְצַוָּארָהּ בִּפְנִים וּשְׁאָר גּוּף הַבְּהֵמָה בַּחוּץ אוֹ שֶׁהָיָה גּוּפָהּ בִּפְנִים וְצַוָּארָהּ בַּחוּץ חַיָּב עַד שֶׁתִּהְיֶה הַבְּהֵמָה כֻּלָּהּ בַּמִּקְדָּשׁ שֶׁנֶּאֱמַר (ויקרא יז ט) \"וְאֶל פֶּתַח אֹהֶל מוֹעֵד לֹא יְבִיאֶנּוּ\". אֲבָל הַשּׁוֹחֵט בְּגַגּוֹ שֶׁל הֵיכָל אַף עַל פִּי שֶׁאֵינוֹ רָאוּי לִזְבִיחָה כְּלָל הֲרֵי זֶה פָּטוּר:","שְׁנַיִם שֶׁאָחֲזוּ בַּסַּכִּין וְשָׁחֲטוּ בַּחוּץ פְּטוּרִין שֶׁנֶּאֱמַר אֲשֶׁר יִשְׁחַט (ויקרא יז ג) \"אוֹ אֲשֶׁר יִשְׁחַט\" אֶחָד וְלֹא שְׁנַיִם. וְאֶחָד שֶׁשָּׁחַט בַּחוּץ אַף עַל פִּי שֶׁלֹּא נִתְכַּוֵּן לִשְׁחֹט קָדָשִׁים אֵלּוּ לַה' הֲרֵי זֶה חַיָּב שֶׁנֶּאֱמַר (ויקרא יז ד) \"דָּם יֵחָשֵׁב לָאִישׁ הַהוּא דָּם שָׁפָךְ\". אַף עַל פִּי שֶׁזֶּה הַדָּם בְּמַחֲשַׁבְתּוֹ כַּדָּם הַנִּשְׁפָּךְ לֹא כַּקָּרְבָּן הֲרֵי זֶה חַיָּב:","הַשּׁוֹחֵט בַּחוּץ בַּלַּיְלָה חַיָּב הוֹאִיל וְהַשְּׁחִיטָה בַּלַּיְלָה כְּשֵׁרָה בַּחוּץ. וְכֵן אִם הֶעֱלָה בַּלַּיְלָה מִזֶּה שֶׁשָּׁחַט בַּחוּץ בַּלַּיְלָה חַיָּב עַל הַעֲלָאָה. אֲבָל אִם שָׁחַט בִּפְנִים בַּלַּיְלָה וְהֶעֱלָה בַּחוּץ פָּטוּר. לְפִי שֶׁלֹּא הֶעֱלָה אֶלָּא דָּבָר פָּסוּל שֶׁאֵין לְךָ שְׁחִיטָה כְּשֵׁרָה בַּלַּיְלָה בַּמִּקְדָּשׁ. וְכֵן אִם קִבֵּל בִּכְלִי חֹל בִּפְנִים וְזָרַק בַּחוּץ פָּטוּר:","וְכֵן הַמּוֹלֵק אֶת הָעוֹף בַּחוּץ פָּטוּר. וְאִם הֶעֱלָהוּ פָּטוּר. מָלַק בִּפְנִים וְהֶעֱלָה בַּחוּץ חַיָּב עַל הַעֲלָאָה. שָׁחַט בִּפְנִים וְהֶעֱלָהוּ בַּחוּץ פָּטוּר שֶׁלֹּא הֶעֱלָה אֶלָּא דָּבָר שֶׁאֵינוֹ רָאוּי לִקָּרֵב. שָׁחַט אֶת הָעוֹף בַּחוּץ וְהֶעֱלָהוּ בַּחוּץ חַיָּב שְׁתַּיִם שֶׁהַשְּׁחִיטָה בַּחוּץ כְּשֵׁרָה וַהֲרֵי הִיא כִּמְלִיקָה בִּפְנִים:"],"Mishneh Torah, Sales 11":["הַמַּקְנֶּה בֵּין קַרְקַע בִּין מִטַּלְטְלִין וְהִתְנָה תְּנָאִין שֶׁאֶפְשָׁר לְקַיְּמָן. בֵּין שֶׁהִתְנָה הַמַּקְנֶה בֵּין שֶׁהִתְנָה הַקּוֹנֶה. אִם נִתְקַיְּמוּ הַתְּנָאִין נִקְנָה הַדָּבָר שֶׁהֻקְנָה. וְאִם לֹא נִתְקַיֵּם הַתְּנַאי לֹא קָנָה. וּכְבָר בֵּאַרְנוּ מִשְׁפְּטֵי הַתְּנָאִים בְּהִלְכוֹת אִישׁוּת:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁקָּנָה בְּדֶרֶךְ מִן הַדְּרָכִים שֶׁקּוֹנִין בָּהֶן וַהֲרֵי יֵשׁ עָלָיו לְקַיֵּם אֶת הַתְּנַאי. אֲבָל אִם לֹא קָנָה עַתָּה וְהִתְנָה עִמּוֹ שֶׁאִם נִתְקַיֵּם הַתְּנַאי זֶה יִקְנֶה וְאִם לֹא נִתְקַיֵּם לֹא יִקְנֶה אַף עַל פִּי שֶׁנִּתְקַיֵּם הַתְּנַאי לֹא קָנָה. שֶׁזּוֹ אַסְמַכְתָּא הִיא. שֶׁהֲרֵי סָמַךְ קְנִיָּתוֹ לַעֲשׂוֹת כָּךְ וְכָךְ וְכָל אַסְמַכְתָּא אֵינָהּ קוֹנָה שֶׁהֲרֵי לֹא גָּמַר בְּלִבּוֹ לְהַקְנוֹתוֹ:","כֵּיצַד. הַמּוֹכֵר בַּיִת לַחֲבֵרוֹ אוֹ נְתָנוֹ לוֹ בְּמַתָּנָה עַל מְנָת שֶׁיֵּלֵךְ עִמּוֹ לִירוּשָׁלַיִם בְּיוֹם פְּלוֹנִי. וְהֶחֱזִיק זֶה בַּבַּיִת. הֲרֵי זֶה קָנָה כְּשֶׁיֵּלֵךְ עִמּוֹ לִירוּשָׁלַיִם בְּאוֹתוֹ הַיּוֹם. וְאִם עָבַר אוֹתוֹ הַיּוֹם וְלֹא הָלַךְ לֹא קָנָה. אֲבָל אִם הִתְנָה וְאָמַר לוֹ אִם תֵּלֵךְ עִמִּי לִירוּשָׁלַיִם בְּיוֹם פְּלוֹנִי אוֹ אִם תָּבִיא לִי דָּבָר פְּלוֹנִי אֶתֵּן לְךָ בַּיִת זֶה אוֹ אֶמְכְּרֶנוּ לְךָ בְּכָךְ וְכָךְ. וְהָלַךְ עִמּוֹ בְּאוֹתוֹ הַיּוֹם אוֹ שֶׁהֵבִיא לוֹ. אַף עַל פִּי שֶׁהֶחְזִיק בַּבַּיִת אַחַר שֶׁקִּיֵּם הַתְּנַאי לֹא קָנָה שֶׁזּוֹ הִיא אַסְמַכְתָּא. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","לְפִיכָךְ הַנּוֹתֵן עֵרָבוֹן לַחֲבֵרוֹ וְאָמַר לוֹ אִם אֲנִי חוֹזֵר בִּי עֶרְבוֹנִי מָחוּל לְךָ וְהַלָּה אוֹמֵר וְאִם אֲנִי חוֹזֵר בִּי אֶכְפּל לְךָ עֶרְבוֹנְךָ. אִם חָזַר בּוֹ הַלּוֹקֵחַ קָנָה זֶה הָעֵרָבוֹן שֶׁהֲרֵי הוּא תַּחַת יָדוֹ. וְאִם חָזַר בּוֹ הַמּוֹכֵר אֵין מְחַיְּבִין אוֹתוֹ לִכְפּל הָעֵרָבוֹן שֶׁזּוֹ אַסְמַכְתָּא הִיא וְאַסְמַכְתָּא לֹא קָנָה:","וְכֵן מִי שֶׁפָּרַע מִקְצָת חוֹבוֹ וְהִשְׁלִישׁ אֶת הַשְּׁטָר וְאָמַר לוֹ אִם לֹא נָתַתִּי לְךָ עַד יוֹם פְּלוֹנִי תֵּן לוֹ שְׁטָרוֹ וְהִגִּיעַ זְמַן וְלֹא נָתַן לוֹ. לֹא יִתֵּן הַשָּׁלִישׁ אֶת הַשְּׁטָר שֶׁזּוֹ אַסְמַכְתָּא הִיא:","וְכֵן כָּל תְּנָאִין שֶׁמַּתְנִין בְּנֵי אָדָם בֵּינֵיהֶן. אַף עַל פִּי שֶׁהֵן בְּעֵדִים וּבִשְׁטָר. אִם יִהְיֶה כָּךְ אוֹ אִם תַּעֲשֶׂה כָּךְ אֶתֵּן לְךָ מָנֶה אוֹ אַקְנֶה לְךָ בַּיִת זֶה. וְאִם לֹא יִהְיֶה אוֹ לֹא תַּעֲשֶׂה לֹא אַקְנֶה לְךָ וְלֹא אֶתֵּן לְךָ. אַף עַל פִּי שֶׁעָשָׂה אוֹ שֶׁהָיָה הַדָּבָר לֹא קָנָה. שֶׁכָּל הָאוֹמֵר אִם יִהְיֶה אִם לֹא יִהְיֶה לֹא גָּמַר וְהִקְנָה. שֶׁהֲרֵי דַּעְתּוֹ עֲדַיִן סוֹמֶכֶת שֶׁמָּא יִהְיֶה אוֹ שֶׁמָּא לֹא יִהְיֶה:","כָּל הָאוֹמֵר קְנֵה מֵעַכְשָׁו אֵין כָּאן אַסְמַכְתָּא כְּלָל וְקָנָה. שֶׁאִלּוּ לֹא גָּמַר לְהַקְנוֹתוֹ לֹא הִקְנָהוּ מֵעַכְשָׁו. כֵּיצַד. אִם בָּאתִי מִכָּאן וְעַד יוֹם פְּלוֹנִי קְנֵה בַּיִת זֶה מֵעַכְשָׁו וְקָנוּ מִיָּדוֹ עַל כָּךְ. הֲרֵי זֶה קָנָה אִם בָּא בְּתוֹךְ הַזְּמַן שֶׁקָּבַע. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִי שֶׁמָּכַר חֲצֵרוֹ אוֹ שָׂדֵהוּ. וּפֵרֵשׁ בִּשְׁעַת הַמְּכִירָה שֶׁהוּא מוֹכֵר כְּדֵי לֵילֵךְ לְמָקוֹם פְּלוֹנִי אוֹ מִפְּנֵי הַמָּטָר שֶׁנִּמְנַע כְּדֵי לִקְנוֹת חִטִּים בִּדְמֵי חֲצֵרוֹ הֲרֵי זֶה כְּמוֹכֵר עַל תְּנַאי. לְפִיכָךְ אִם יָרַד הַמָּטָר אַחַר שֶׁמָּכַר. אוֹ בָּאוּ חִטִּין וְהוּזְלוּ. אוֹ נִמְנַע הַדֶּרֶךְ לֵילֵךְ לְאוֹתָהּ הָאָרֶץ. אוֹ שֶׁלֹּא נִסְתַּיֵּעַ לוֹ לַעֲלוֹת אוֹ לִקְנוֹת חִטִּים. הֲרֵי זֶה מַחְזִיר אוֹתָן הַדָּמִים וְתַחְזֹר לוֹ קַרְקַע. שֶׁהֲרֵי פֵּרֵשׁ שֶׁאֵינוֹ מוֹכֵר אֶלָּא לַעֲשׂוֹת דָּבָר פְּלוֹנִי וַהֲרֵי לֹא נַעֲשָׂה. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן:","אֲבָל הַמּוֹכֵר סְתָם אַף עַל פִּי שֶׁהָיָה בְּלִבּוֹ שֶׁמִּפְּנֵי כָּךְ וְכָךְ הוּא מוֹכֵר. וְאַף עַל פִּי שֶׁמַּרְאִין הַדְּבָרִים שֶׁאֵינוֹ מוֹכֵר אֶלָּא לַעֲשׂוֹת כָּךְ וְכָךְ וְלֹא נַעֲשָׂה אֵינוֹ חוֹזֵר. שֶׁהֲרֵי לֹא פֵּרֵשׁ וּדְבָרִים שֶׁבַּלֵּב אֵינָן דְּבָרִים:","מִי שֶׁהִקְנָה לַחֲבֵרוֹ וְהִתְנָה עָלָיו עַל מְנָת שֶׁתִּתֵּן מִקָּח זֶה אוֹ תִּמְכְּרֶנוּ לִפְלוֹנִי. אִם נְתָנוֹ אוֹ מְכָרוֹ לְאוֹתוֹ פְּלוֹנִי קָנָה. וְאִם לֹא קִיֵּם הַתְּנַאי וּמְכָרוֹ לְאַחֵר אוֹ שֶׁלֹּא מְכָרוֹ וְלֹא נְתָנוֹ בַּזְּמַן שֶׁקָּבַע לוֹ לֹא קָנָה. וְכֵן הַמּוֹכֵר אוֹ הַלּוֹקֵחַ שֶׁהִתְנוּ שֶׁיַּחְזִיר לוֹ הַמִּקָּח בִּזְמַן פְּלוֹנִי אוֹ כְּשֶׁיִּתֵּן לוֹ הַמָּעוֹת. הֲרֵי הַמֶּכֶר קַיָּם וְיַחְזִיר כְּשֶׁהִתְנָה:","מָכַר קַרְקַע לַחֲבֵרוֹ וְהִתְנָה הַמּוֹכֵר וְאָמַר לַלּוֹקֵחַ כְּשֶׁיִּהְיוּ לִי מָעוֹת תַּחְזִיר לִי הַקַּרְקַע זוֹ הֲרֵי הַפֵּרוֹת שֶׁל מוֹכֵר. מָכַר לוֹ סְתָם וְאָמַר לוֹ הַלּוֹקֵחַ מִדַּעְתּוֹ כְּשֶׁיִּהְיוּ לְךָ מָעוֹת תְּבִיאֵם לִי וַאֲנִי אַחְזִיר לְךָ קַרְקַע זוֹ. הֲרֵי הַתְּנַאי קַיָּם וְהַלּוֹקֵחַ אוֹכֵל פֵּרוֹת. וְאֵין בָּזֶה אֲבַק רִבִּית שֶׁהֲרֵי מִדַּעְתּוֹ חִיֵּב עַצְמוֹ בִּתְנַאי זֶה:","מַעֲשֶׂה בְּאִשָּׁה שֶׁשָּׁלְחָה רְאוּבֵן לִקְנוֹת לָהּ חָצֵר מִשִּׁמְעוֹן שֶׁהָיָה קְרוֹבוֹ וְאָמַר שִׁמְעוֹן הַמּוֹכֵר לִרְאוּבֵן הַשָּׁלִיחַ אִם יִהְיוּ לִי מָעוֹת תַּחְזִיר לִי פְּלוֹנִית קְרוֹבָתִי קַרְקַע זוֹ. וֶהֱשִׁיבוֹ רְאוּבֵן וְאָמַר לוֹ אַתָּה וּפְלוֹנִית קְרוֹבִים כְּמוֹ אַחִים. כְּלוֹמַר הַדָּבָר קָרוֹב שֶׁהִיא תַּחְזִיר לְךָ וְאֵינָהּ מַקְפֶּדֶת עַל זוֹ. וּבָא מַעֲשֶׂה לִפְנֵי חֲכָמִים וְאָמְרוּ הֲרֵי זֶה הַשָּׁלִיחַ לֹא קָנָה כְּלוּם שֶׁהֲרֵי לֹא סָמְכָה דַּעְתּוֹ שֶׁל קָרוֹב זֶה עַל דִּבְרֵי הַשָּׁלִיחַ מִפְּנֵי שֶׁלֹּא הֱשִׁיבוֹ תְּשׁוּבָה בְּרוּרָה וְנִמְצָא שֶׁלֹּא גָּמַר וְלֹא הִקְנָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אַסְמַכְתָּא שֶׁקָּנוּ מִיָּדוֹ עָלֶיהָ בְּבֵית דִּין חָשׁוּב הֲרֵי זֶה קָנָה. וְהוּא שֶׁיִּתְפֹּס זְכֻיּוֹתָיו בְּבֵית דִּין. וְהוּא שֶׁלֹּא יִהְיֶה אָנוּס:","כֵּיצַד. הֲרֵי שֶׁהִתְפִּיס שְׁטָרוֹ אוֹ שׁוֹבְרוֹ בְּבֵית דִּין. וְקָנוּ מִיָּדוֹ שֶׁאִם לֹא בָּא בְּיוֹם פְּלוֹנִי יִנָּתֵן שְׁטָר זֶה לְבַעַל דִּינוֹ וְהִגִּיעַ הַיּוֹם וְלֹא בָּא הֲרֵי אֵלּוּ נוֹתְנִים. וְאִם עִכְּבוֹ נָהָר אוֹ חֹלִי מִלָּבוֹא לֹא יִתְּנוּ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְהוּא שֶׁיִּהְיֶה בְּבֵית דִּין חָשׁוּב:","הַמְחַיֵּב עַצְמוֹ בְּמָמוֹן לְאַחֵר בְּלֹא תְּנַאי כְּלָל. אַף עַל פִּי שֶׁלֹּא הָיָה חַיָּב לוֹ כְּלוּם הֲרֵי זֶה חַיָּב. שֶׁדָּבָר זֶה מַתָּנָה הִיא וְאֵינָהּ אַסְמַכְתָּא. כֵּיצַד. הָאוֹמֵר לְעֵדִים הֱווּ עָלַי עֵדִים שֶׁאֲנִי חַיָּב לִפְלוֹנִי מָנֶה. אוֹ שֶׁכָּתַב לוֹ בִּשְׁטָר הֲרֵינִי חַיָּב לְךָ מָנֶה אַף עַל פִּי שֶׁאֵין שָׁם עֵדִים. אוֹ שֶׁאָמַר לוֹ בִּפְנֵי עֵדִים הֲרֵינִי חַיָּב לְךָ מָנֶה בִּשְׁטָר. אַף עַל פִּי שֶׁלֹּא אָמַר אַתֶּם עֵדַי. הוֹאִיל וְאָמַר בִּשְׁטָר הֲרֵי זֶה כְּמִי שֶׁאָמַר הֱווּ עָלַי עֵדִים וְחַיָּב לְשַׁלֵּם. אַף עַל פִּי שֶׁשְּׁנֵיהֶם מוֹדִים וְהָעֵדִים יוֹדְעִים שֶׁלֹּא הָיָה לוֹ אֶצְלוֹ כְּלוּם. שֶׁהֲרֵי חִיֵּב עַצְמוֹ. כְּמוֹ שֶׁיִּשְׁתַּעְבֵּד הֶעָרֵב. וְכָזֶה הוֹרוּ רֹב הַגְּאוֹנִים:","חִיֵּב עַצְמוֹ בְּדָבָר שֶׁאֵינוֹ קָצוּב. כְּגוֹן שֶׁאָמַר הֲרֵינִי חַיָּב לָזוּן אוֹתְךָ אוֹ לְכַסּוֹת חָמֵשׁ שָׁנִים. אַף עַל פִּי שֶׁקָּנוּ מִיָּדוֹ לֹא נִשְׁתַּעְבֵּד. שֶׁזּוֹ כְּמוֹ מַתָּנָה הִיא וְאֵין כָּאן דָּבָר יָדוּעַ וּמָצוּי שֶׁנְּתָנוֹ בְּמַתָּנָה. וְכֵן הוֹרוּ רַבּוֹתַי:","וּמִפְּנֵי מָה הַפּוֹסֵק עִם אִשְׁתּוֹ שֶׁיִּהְיֶה זָן אֶת בִּתָּהּ חַיָּב לְזוּנָהּ. מִפְּנֵי שֶׁפָּסַק בִּשְׁעַת נִשּׂוּאִין וְהַדָּבָר דּוֹמֶה לִדְבָרִים הַנִּקְנִין בַּאֲמִירָה:","כְּשֶׁהָיוּ חַכְמֵי סְפָרַד רוֹצִים לְהַקְנוֹת בְּאַסְמַכְתָּא כָּךְ הָיוּ עוֹשִׂין. קוֹנִין מִזֶּה שֶׁהוּא חַיָּב לַחֲבֵרוֹ מֵאָה דִּינָרִין. וְאַחַר שֶׁחִיֵּב עַצְמוֹ קוֹנִין מִבַּעַל חוֹבוֹ שֶׁכָּל זְמַן שֶׁיִּהְיֶה כָּךְ אוֹ שֶׁיַּעֲשֶׂה כָּךְ הֲרֵי הַחוֹב זֶה מָחוּל לוֹ מֵעַכְשָׁו. וְאִם לֹא יִהְיֶה אוֹ לֹא יַעֲשֶׂה הֲרֵינִי תּוֹבְעוֹ בְּמָמוֹן שֶׁחִיֵּב עַצְמוֹ בּוֹ. וְעַל דֶּרֶךְ זוֹ הָיִינוּ עוֹשִׂין בְּכָל הַתְּנָאִין שֶׁבֵּין אָדָם לְאִשְׁתּוֹ בְּשִׁדּוּכִין וּבְכָל הַדְּבָרִים הַדּוֹמִין לָהֶם:"],"Mishneh Torah, Sales 22":["אֵין אָדָם מַקְנֶה דָּבָר שֶׁלֹּא בָּא לָעוֹלָם. בֵּין בְּמֶכֶר בֵּין בְּמַתָּנָה בֵּין בְּמַתְּנַת שְׁכִיב מֵרַע. כֵּיצַד. מַה שֶּׁתּוֹצִיא שָׂדֶה זוֹ מָכוּר לְךָ. מַה שֶּׁיּוֹצִיא אִילָן זֶה נָתוּן לְךָ. תְּנוּ מַה שֶּׁתֵּלֵד בְּהֵמָה זוֹ לִפְלוֹנִי. לֹא קָנָה כְּלוּם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַמּוֹכֵר פֵּרוֹת דֶּקֶל לַחֲבֵרוֹ יָכוֹל לַחְזֹר בּוֹ אַף לְאַחַר שֶׁבָּאוּ הַפֵּרוֹת לָעוֹלָם. וְאִם שָׁמַט הַלּוֹקֵחַ וְאָכַל אֵין מוֹצִיאִין מִיָּדוֹ. וְכָל הַחוֹזֵר בּוֹ מִשְּׁנֵיהֶם אֵין חַיָּב לְקַבֵּל מִי שֶׁפָּרַע:","אֲבָל הַפּוֹסֵק עַל שַׁעַר שֶׁבַּשּׁוּק וְלֹא הָיָה אוֹתוֹ הַמִּין שֶׁפָּסַק עָלָיו בִּרְשׁוּת מוֹכֵר. חַיָּב לִקְנוֹת וְלִתֵּן לַלּוֹקֵחַ מַה שֶּׁפָּסַק. וְאִם חָזַר מְקַבֵּל מִי שֶׁפָּרַע:","מִי שֶׁפָּסַק עַל שַׁעַר שֶׁבַּשּׁוּק שֶׁיִּתֵּן אַרְבָּעָה סְאִין בְּסֶלַע. אִם הָיוּ שִׁבֳּלִים הֲרֵי זֶה קָנָה לְקַבֵּל מִי שֶׁפָּרַע. וְהוּא שֶׁיַּרְאֶה לוֹ בַּגֹּרֶן אוֹ שֶׁיֹּאמַר לוֹ בַּשּׁוּק הֲרֵינִי סוֹמֵךְ עָלֶיךָ. אֲבָל אִם לֹא נִרְאָה לוֹ בַּגֹּרֶן וְלֹא אָמַר לוֹ הֲרֵינִי סוֹמֵךְ עָלֶיךָ לֹא סָמְכָה דַּעְתּוֹ שֶׁל מוֹכֵר וְאֵינוֹ מְקַבֵּל מִי שֶׁפָּרַע. שֶׁהֲרֵי הוּא אוֹמֵר שֶׁמָּא פָּסַק עִם אַחֵר וְאֵין צָרִיךְ לְחִטִּים אֵלּוּ:","דָּבָר שֶׁאֵין בִּרְשׁוּתוֹ שֶׁל מַקְנֶה אֵינוֹ נִקְנֶה. וַהֲרֵי הוּא כְּדָבָר שֶׁלֹּא בָּא לָעוֹלָם. כֵּיצַד. מַה שֶּׁאִירַשׁ מֵאַבָּא מָכוּר לְךָ. מַה שֶּׁתַּעֲלֶה מְצוּדָתִי מִן הַיָּם נָתוּן לְךָ. שָׂדֶה זוֹ לִכְשֶׁאֶקָּחֶנָּה קְנוּיָה לְךָ. לֹא קָנָה כְּלוּם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִי שֶׁהָיָה מוֹרִישׁוֹ גּוֹסֵס וְנָטוּי לָמוּת וְרָצָה לִמְכֹּר מִנְּכָסָיו מְעַט כְּדֵי לְהוֹצִיא הַדָּמִים בְּצָרְכֵי קְבוּרָה. הוֹאִיל וְהַבֵּן עָנִי וְאִם יַמְתִּין עַד שֶׁיָּמוּת וְיִמְכֹּר יִשְׁתַּהֶא הַמֵּת וְיִתְבַּזֶּה. תִּקְנוּ חֲכָמִים שֶׁאִם מָכַר וְאָמַר מַה שֶּׁאִירַשׁ מֵאָבִי הַיּוֹם מָכוּר לְךָ מִמְכָּרוֹ קַיָּם. וְכֵן צַיָּד עָנִי שֶׁאֵין לוֹ מַה שֶּׁיֹּאכַל שֶׁאָמַר מַה שֶּׁתַּעֲלֶה מִן הַיָּם מְצוּדָתִי הַיּוֹם מָכוּר לְךָ. מִמְכָּרוֹ קַיָּם מִשּׁוּם כְּדֵי חַיָּיו:","הַבֵּן שֶׁמָּכַר בְּנִכְסֵי אָבִיו בְּחַיֵּי אָבִיו וּמֵת הַבֵּן בְּחַיֵּי הָאָב וְאַחַר כָּךְ מֵת הָאָב. בֶּן הַבֵּן מוֹצִיא מִיַּד הַלָּקוֹחוֹת. שֶׁהֲרֵי אָבִיו מָכַר דָּבָר שֶׁלֹּא בָּא עֲדַיִן לִרְשׁוּתוֹ. וְנִמְצְאוּ הַנְּכָסִים בִּרְשׁוּת הָאָב וְזֶה יוֹרֵשׁ אֲבִי אָבִיו. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִי שֶׁנָּתַן קַרְקַע מַתָּנָה לַחֲבֵרוֹ וְנָתַן לוֹ עַל גַּבָּהּ מֵאָה דִּינָרִין. אִם הָיוּ הַדִּינָרִין מְצוּיִין בִּרְשׁוּתוֹ כֵּיוָן שֶׁזָּכָה בַּשָּׂדֶה זָכָה בַּדִּינָרִין. וְאִם אֵין לוֹ דִּינָר אֵין מְחַיְּבִין אֶת הַנּוֹתֵן לִתֵּן לוֹ מֵאָה דִּינָרִין עַד שֶׁיָּבִיא הַזּוֹכֶה רְאָיָה שֶׁהָיָה לָזֶה דִּינָרִין בְּעֵת הַמַּתָּנָה. וְהוּא הַדִּין לִשְׁאָר מִטַּלְטְלִין שֶׁמַּקְנֶה אָדָם אוֹתָם עַל קַרְקַע. אִם אֵינָם בִּרְשׁוּת הַמּוֹכֵר אוֹ הַנּוֹתֵן לֹא קָנָה. שֶׁאֵין אָדָם מַקְנֶה דָּבָר שֶׁאֵינוֹ בִּרְשׁוּתוֹ:","מִי שֶׁהָיָה לוֹ פִּקָּדוֹן בְּיַד אַחֵר הֲרֵי זֶה מַקְנֵהוּ בֵּין בְּמֶכֶר בֵּין בְּמַתָּנָה. לְפִי שֶׁהַפִּקָּדוֹן בִּרְשׁוּת בְּעָלָיו הוּא וַהֲרֵי הוּא בְּחֶזְקַת שֶׁהוּא קַיָּם. וְאִם כָּפַר בּוֹ זֶה שֶׁהֻפְקַד אֶצְלוֹ אֵינוֹ יָכוֹל לְהַקְנוֹתוֹ. שֶׁזֶּה כְּמִי שֶׁאָבַד שֶׁאֵינוֹ בִּרְשׁוּתוֹ. אֲבָל הַמִּלְוֶה הוֹאִיל וּלְהוֹצָאָה נִתְּנָה אֵינָהּ בָּעוֹלָם וְאֵין אָדָם יָכוֹל לְהַקְנוֹתָהּ אֶלָּא בְּמַעֲמַד שְׁלָשְׁתָּן. וְהוּא דָּבָר שֶׁאֵין לוֹ טַעַם כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם הָיְתָה מִלְוֶה בִּשְׁטָר מַקְנֶה אֶת הַשְּׁטָר בִּכְתִיבָה וּמְסִירָה שֶׁהֲרֵי יֵשׁ כָּאן דָּבָר הַנִּמְסָר לִקְנוֹת שִׁעְבּוּד שֶׁבּוֹ:","כְּשֵׁם שֶׁאֵין אָדָם מַקְנֶה דָּבָר שֶׁלֹּא בָּא לָעוֹלָם. כָּךְ אֵין אָדָם מַקְנֶה לְמִי שֶׁלֹּא בָּא לָעוֹלָם. וַאֲפִלּוּ עֻבָּר הֲרֵי הוּא כְּמִי שֶׁלֹּא בָּא לָעוֹלָם. וְהַמְזַכֶּה לְעֻבָּר לֹא קָנָה. וְאִם הָיָה בְּנוֹ הוֹאִיל וְדַעְתּוֹ שֶׁל אָדָם קְרוֹבָה אֵצֶל בְּנוֹ קָנָה:","הָאוֹמֵר לְאִשְׁתּוֹ נְכָסַי לַבָּנִים שֶׁתֵּלְדִי מִמֶּנִּי הֲרֵי אֵלּוּ לֹא יִקְנוּ כְּלוּם. שֶׁכֵּיוָן שֶׁלֹּא נִתְעַבְּרָה בָּהֶן בִּשְׁעַת הַמַּתָּנָה עֲדַיִן לֹא בָּאוּ כְּדֵי לִהְיוֹת דַּעְתּוֹ קְרוֹבָה לָהֶם:","הַמַּקְנֶה לְמִין מִמִּינֵי חַיָּה לֹא הִקְנָה כְּלוּם. הִקְנָה קְצָת נְכָסָיו לִבְהֵמָה אוֹ לְמִי שֶׁלֹּא בָּא לָעוֹלָם וְחָזַר וְאָמַר לַחֲבֵרוֹ קְנֵה כִּבְהֵמָה זוֹ אוֹ כְּעֻבָּר זֶה לֹא קָנָה כְּלוּם. אָמַר לוֹ קְנֵה אַתְּ וּבְהֵמָה זוֹ אוֹ אַתְּ וְעֵבָּר זֶה קָנָה מֶחֱצָה:","אֵין אָדָם מַקְנֶה לֹא בְּמֶכֶר וְלֹא בְּמַתָּנָה אֶלָּא דָּבָר שֶׁיֵּשׁ בּוֹ מַמָּשׁ אֲבָל דָּבָר שֶׁאֵין בּוֹ מַמָּשׁ אֵינוֹ נִקְנֶה:","כֵּיצַד. אֵין אָדָם מַקְנֶה רֵיחַ הַתַּפּוּחַ הַזֶּה אוֹ טַעַם הַדְּבַשׁ הַזֶּה אוֹ עֵין הַבְּדלַח הַזֶּה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. לְפִיכָךְ הַמַּקְנֶה לַחֲבֵרוֹ אֲכִילַת פֵּרוֹת דֶּקֶל זֶה אוֹ דִּירַת בַּיִת זֶה לֹא קָנָה. עַד שֶׁיַּקְנֶה לוֹ גּוּף הַבַּיִת לָדוּר בּוֹ וְגוּף הָאִילָן לֶאֱכל פֵּרוֹתָיו כְּמוֹ שֶׁיִּתְבָּאֵר:","דִּין הַהֶקְדֵּשׁ וְדִין הָעֲנִיִּים וְדִין הַנְּדָרִים אֵינוֹ כְּדִין הַהֶדְיוֹט בִּקְנִיָּתוֹ שֶׁאִלּוּ אָמַר אָדָם כָּל מַה שֶּׁתֵּלֵד בְּהֶמְתִּי יִהְיֶה הֶקְדֵּשׁ לְבֶדֶק הַבַּיִת אוֹ יִהְיֶה אָסוּר עָלַי אוֹ אֶתְּנֶנּוּ לִצְדָקָה אַף עַל פִּי שֶׁאֵינוֹ מִתְקַדֵּשׁ לְפִי שֶׁאֵינוֹ בָּעוֹלָם הֲרֵי זֶה חַיָּב לְקַיֵּם דְּבָרוֹ שֶׁנֶּאֱמַר (במדבר ל ג) \"כְּכָל הַיֹּצֵא מִפִּיו יַעֲשֶׂה\":","וְהוֹאִיל וְהַדָּבָר כֵּן אִם צִוָּה אָדָם כְּשֶׁהוּא שְׁכִיב מֵרַע וְאָמַר כָּל מַה שֶּׁיּוֹצִיא אִילָן זֶה לָעֲנִיִּים. אוֹ כָּל שְׂכַר בַּיִת זֶה לָעֲנִיִּים זָכוּ בָּהֶן הָעֲנִיִּים:","יֵשׁ גְּאוֹנִים שֶׁחוֹלְקִין עַל דָּבָר זֶה וְאוֹמְרִים שֶׁאֵין הָעֲנִיִּים זוֹכִין אֶלָּא בִּדְבָרִים שֶׁהֶדְיוֹט קוֹנֶה בָּהֶן. וּלְפִיכָךְ לֹא יִזְכּוּ בְּדָבָר שֶׁלֹּא בָּא לָעוֹלָם. וְאֵין דַּעְתִּי נוֹטָה לִדְבָרִים אֵלּוּ. שֶׁאֵין אָדָם מְצֻוֶּה לְהַקְנוֹת. וְהוּא מְצֻוֶּה לְקַיֵּם דְּבָרָיו בִּצְדָקָה אוֹ בְּהֶקְדֵּשׁ כְּמוֹ שֶׁהוּא מְצֻוֶּה לְקַיֵּם הַנֵּדֶר כְּמוֹ שֶׁבֵּאַרְנוּ בַּעֲרָכִין:"],"Mishneh Torah, Sales 6":["הַפֵּרוֹת אַף עַל פִּי שֶׁאֵין קוֹנִין בָּהֶן כְּמוֹ שֶׁבֵּאַרְנוּ. הֲרֵי נִקְנִין בְּקִנְיָן כִּשְׁאָר הַמִּטַּלְטְלִין. אֲבָל הַמַּטְבֵּעַ כְּשֵׁם שֶׁאֵין קוֹנִין בּוֹ כָּךְ אֵינוֹ נִקְנֶה בְּקִנְיָן. נִמְצָא הַמַּטְבֵּעַ אֵינוֹ נִקְנֶה בְּקִנְיָן וְאֵינוֹ נַעֲשֶׂה הוּא עַצְמוֹ קִנְיָן לִקְנוֹת כִּשְׁאָר דְּבָרִים:","לְשׁוֹנוֹת שֶׁל זָהָב וְשֶׁל כֶּסֶף הֲרֵי הֵן כַּעֲשָׁשִׁיּוֹת שֶׁל בַּרְזֶל אוֹ שֶׁל נְחשֶׁת. וְהַכּל כִּשְׁאָר הַמִּטַּלְטְלִין הֵן. וְנִקְנִין בְּקִנְיָן וְקוֹנִין זֶה אֶת זֶה בְּהַחְלָפָה כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל הַמַּטְבְּעוֹת שֶׁל כֶּסֶף אוֹ דִּינָרִין שֶׁל זָהָב. אוֹ הַמָּעוֹת שֶׁל נְחשֶׁת. הֲרֵי הֵן כֻּלָּן דָּמִים כְּנֶגֶד שְׁאָר הַמִּטַּלְטְלִין. וְהַנּוֹתֵן אֶת אֶחָד מֵהֶן דְּמֵי הַמִּטַּלְטְלִין לֹא קָנָה עַד שֶׁיִּמְשֹׁךְ אוֹ יַגְבִּיהַּ כְּמוֹ שֶׁבֵּאַרְנוּ. וְאֵין אֶחָד מֵהֶן נִקְנֶה בְּקִנְיָן וְלֹא נַעֲשֶׂה קִנְיָן:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁקּוֹנֶה שְׁאָר מִטַּלְטְלִין בְּאֶחָד מִמִּינֵי מַטְבְּעוֹת אֵלּוּ אוֹ עֲבָדִים וְקַרְקָעוֹת. אֲבָל הַדִּינָרִין שֶׁל זָהָב לְגַבֵּי מַטְבְּעוֹת שֶׁל כֶּסֶף הֲרֵי הֵן כְּפֵרוֹת. וְכֵן הַמָּעוֹת שֶׁל נְחשֶׁת כְּמוֹ פֵּרוֹת לְגַבֵּי מַטְבְּעוֹת שֶׁל כֶּסֶף:","כֵּיצַד. נָתַן לוֹ דִּינָר שֶׁל זָהָב בְּעֶשְׂרִים וַחֲמִשָּׁה דִּינָר שֶׁל כֶּסֶף נִקְנֶה הַכֶּסֶף אַף עַל פִּי שֶׁעֲדַיִן לֹא בָּא הַכֶּסֶף לְיָדוֹ. וְחַיָּב לִתֵּן לוֹ עֶשְׂרִים וַחֲמִשָּׁה דִּינָר שֶׁל כֶּסֶף כְּמוֹ שֶׁפָּסַק עִמּוֹ. אִם חֲדָשִׁים חֲדָשִׁים אִם יְשָׁנִים יְשָׁנִים. אֲבָל אִם נָתַן לוֹ עֶשְׂרִים וַחֲמִשָּׁה כֶּסֶף בְּדִינַר זָהָב לֹא קָנָה עַד שֶׁיִּקַּח הַדִּינָר שֶׁל זָהָב. וְכָל אֶחָד יָכוֹל לַחְזֹר בּוֹ:","נָתַן לוֹ שְׁלֹשִׁים אִיסָר שֶׁל נְחשֶׁת בְּדִינָר שֶׁל כֶּסֶף. נִקְנֶה הַדִּינָר שֶׁל כֶּסֶף וְחַיָּב לִתֵּן לוֹ כְּמוֹ שֶׁפָּסַק עִמּוֹ. אִם דִּינָר חָדָשׁ חָדָשׁ אִם יָשָׁן יָשָׁן. אֲבָל אִם נָתַן לוֹ דִּינָר שֶׁל כֶּסֶף בִּשְׁלֹשִׁים אִיסָר. לֹא קָנָה עַד שֶׁיִּקַּח הָאִיסָרוֹת שֶׁל נְחשֶׁת. וְכָל אֶחָד מֵהֶן יָכוֹל לַחְזֹר בּוֹ:","וְכֵן מָעוֹת הָרָעוֹת שֶׁפְּסָלָתָן מַלְכוּת אוֹ הַמְּדִינָה אוֹ דִּינָרִין שֶׁאֵינָן יוֹצְאִין בְּאוֹתָהּ מְדִינָה וְאֵין נוֹשְׂאִין וְנוֹתְנִין בָּהֶן עַד שֶׁמְּשַׁנִּין אוֹתָן לְמַטְבֵּעַ אַחֵר. הֲרֵי הֵן כְּפֵרוֹת לְכָל דָּבָר וְנִקְנִין בְּקִנְיָן. וְקוֹנִין אֶת הַמָּעוֹת. וְאֵין הַמָּעוֹת קוֹנוֹת אוֹתָן כִּשְׁאָר כָּל הַפֵּרוֹת:","הַמַּטְבֵּעַ אֵין לוֹ דֶּרֶךְ שֶׁיִּזְכֶּה בּוֹ מִי שֶׁאֵינוֹ בִּרְשׁוּתוֹ אֶלָּא עַל גַּבֵּי קַרְקַע. כְּגוֹן שֶׁקָּנָה הַקַּרְקַע וְעַל גַּבּוֹ הַמָּעוֹת. אוֹ שֶׁיִּשְׂכֹּר אֶת מְקוֹם הַמָּעוֹת. כֵּיוָן שֶׁזָּכָה בַּקַּרְקַע בְּכֶסֶף אוֹ בִּשְׁטָר אוֹ בַּחֲזָקָה אוֹ בְּקִנְיָן זָכָה בַּמָּעוֹת. וְהוּא שֶׁיִּהְיוּ אוֹתָן הַמָּעוֹת קַיָּמִין כְּגוֹן שֶׁיִּהְיוּ מֻפְקָדִין בְּמָקוֹם אֶחָד. אֲבָל רְאוּבֵן שֶׁהָיָה לוֹ חוֹב עַל שִׁמְעוֹן וְהִקְנָה לְלֵוִי קַרְקַע וְעַל גַּבָּהּ חוֹב שֶׁיֵּשׁ לוֹ אֵצֶל שִׁמְעוֹן נִרְאֶה לִי שֶׁלֹּא קָנָה הַחוֹב:","הָיוּ עוֹמְדִים שְׁלָשְׁתָּן וְאָמַר לוֹ מָנֶה שֶׁיֵּשׁ לִי בְּיָדְךָ בֵּין פִּקָּדוֹן בֵּין מִלְוֶה תְּנֵהוּ לָזֶה. קָנָה לֵוִי. וְאֵין אֶחָד מִשְּׁלָשְׁתָּן יָכוֹל לַחְזֹר בּוֹ. וְדָבָר זֶה אָמְרוּ חֲכָמִים שֶׁהִיא הֲלָכָה שֶׁאֵין לָהּ טַעַם לְפִיכָךְ אֵין לְמֵדִין מִמֶּנָּה לְדִין אַחֵר:","הָיָה רְאוּבֵן חַיָּב לְשִׁמְעוֹן מֵאָה זוּז. וְאָמַר לְלֵוִי תֵּן לְשִׁמְעוֹן מֵאָה זוּז אֵלּוּ שֶׁאֲנִי חַיָּב לוֹ עַד שֶׁאֶתֵּן לְךָ אוֹ עַד שֶׁאֶעֱשֶׂה עִמְּךָ חֶשְׁבּוֹן. וְאָמַר לוֹ הֵן וְקִבֵּל שִׁמְעוֹן. כָּל אֶחָד מִשְּׁלָשְׁתָּן יָכוֹל לַחְזֹר בּוֹ. וַאֲפִלּוּ פָּרַע לֵוִי לְשִׁמְעוֹן מִקְצָת חוֹבוֹ. לְפִיכָךְ אִם לֹא פָּרַע לֵוִי לְשִׁמְעוֹן חוֹזֵר שִׁמְעוֹן וְתוֹבֵעַ אֶת רְאוּבֵן בִּשְׁאָר חוֹבוֹ:","הַמּוֹכֵר שְׁטַר חוֹב לַחֲבֵרוֹ אוֹ נְתָנוֹ לוֹ בְּמַתָּנָה. אֵינוֹ נִקְנֶה בִּמְסִירַת הַשְּׁטָר לְיָדוֹ. שֶׁלֹּא מָסַר לוֹ אֶלָּא הָרְאָיָה שֶׁבּוֹ וְאֵין הָרְאָיָה נִתְפֶּסֶת בַּיָּד:","וְכֵיצַד יִקְנֶה הַשְּׁטָר. שֶׁיִּכְתֹּב לוֹ הַמַּקְנֶה קְנֵה שְׁטָר פְּלוֹנִי וְכָל הַשִּׁעְבּוּד שֶׁיֵּשׁ בּוֹ וְיִמְסֹר לוֹ הַשְּׁטָר וְנִמְצָא שֶׁנִּקְנָה בִּכְתִיבָה וּמְסִירָה. וְאֵין צָרִיךְ עֵדִים לְעִנְיַן קְנִיָּתוֹ אֲבָל צָרִיךְ עֵדִים לְעִנְיַן תְּבִיעָתוֹ. שֶׁהֲרֵי הַנִּתְבָּע אוֹמֵר לוֹ מִי יֹאמַר שֶׁבַּעַל דְּבָרִים שֶׁלִּי כָּתַב וּמָסַר לְךָ:","קִנְיַן הַשְּׁטָרוֹת בַּדֶּרֶךְ הַזֹּאת מִדִּבְרֵי סוֹפְרִים. אֲבָל מִן הַתּוֹרָה אֵין הָרְאָיוֹת נִקְנוֹת אֶלָּא גּוּף הַדָּבָר בִּלְבַד קָנוּי. לְפִיכָךְ הַמּוֹכֵר שְׁטַר חוֹב לַחֲבֵרוֹ עֲדַיִן יָכוֹל לִמְחל. וַאֲפִלּוּ יוֹרְשׁוֹ מוֹחֲלוֹ:","הָאִשָּׁה שֶׁהִכְנִיסָה שְׁטַר חוֹב לְבַעֲלָהּ אֵינָהּ יְכוֹלָה לִמְחל אֶלָּא מִדַּעַת בַּעְלָהּ מִפְּנֵי שֶׁיָּדָהּ כְּיָדוֹ:","הַמַּקְנֶה לַחֲבֵרוֹ קַרְקַע כָּל שֶׁהוּא וְהִקְנָה לוֹ עַל גַּבָּהּ שְׁטַר חוֹב הֲרֵי זֶה קָנָה הַשְּׁטָר בְּכָל מָקוֹם שֶׁהוּא בְּלֹא כְּתִיבָה וּבְלֹא מְסִירָה. וְנִרְאֶה לִי שֶׁגַּם זֶה יָכוֹל לִמְחל אַחַר שֶׁמְּכָרוֹ. וְכֵן הַמּוֹכֵר קַרְקַע וְכָתַב הַשְּׁטָר וְאֵין הַלּוֹקֵחַ עִמּוֹ כֵּיוָן שֶׁהֶחְזִיק הַלּוֹקֵחַ בַּקַּרְקַע נִקְנָה הַשְּׁטָר בְּכָל מָקוֹם שֶׁהוּא:","הָאוֹמֵר זְכוּ בְּשָׂדֶה זוֹ לִפְלוֹנִי וְכִתְבוּ לוֹ אֶת הַשְּׁטָר וְהֶחֱזִיק הַזּוֹכֶה לוֹ בַּקַּרְקַע. יֵשׁ לַנּוֹתֵן לַחְזֹר בַּשְּׁטָר עַד שֶׁיַּגִּיעַ לְיַד בַּעַל הַמַּתָּנָה. וְאַף עַל פִּי שֶׁאֵינוֹ יָכוֹל לַחְזֹר בַּשָּׂדֶה:","אָמַר לָהֶם זְכוּ לוֹ בַּשָּׂדֶה עַל מְנָת שֶׁתִּכְתְּבוּ לוֹ אֶת הַשְּׁטָר. אַף עַל פִּי שֶׁהֶחְזִיקוּ לוֹ בַּשָּׂדֶה חוֹזֵר מִזֶּה וּמִזֶּה עַד שֶׁיַּגִּיעַ שְׁטַר הַמַּתָּנָה לִידֵי מְקַבֵּל הַמַּתָּנָה:"],"Mishneh Torah, Sanctification of the New Month 17":["כָּל הַדְּבָרִים שֶׁהִקְדַּמְנוּ כְּדֵי שֶׁיִּהְיוּ עֲתִידִים וּמוּכָנִים לִידִיעת הָרְאִיָּה. וּכְשֶׁתִּרְצֶה לָדַעַת זֹאת תַּתְחִיל וְתַחְשֹׁב וְתוֹצִיא מְקוֹם הַשֶּׁמֶשׁ הָאֲמִתִּי וּמְקוֹם הַיָּרֵחַ הָאֲמִתִּי וּמְקוֹם הָרֹאשׁ לִשְׁעַת הָרְאִיָּה. וְתִגְרַע מְקוֹם הַשֶּׁמֶשׁ הָאֲמִתִּי מִמְּקוֹם הַיָּרֵחַ הָאֲמִתִּי וְהַנִּשְׁאָר הוּא הַנִּקְרָא אֹרֶךְ רִאשׁוֹן:","וּמֵאַחַר שֶׁתֵּדַע מְקוֹם הָרֹאשׁ וּמְקוֹם הַיָּרֵחַ תֵּדַע מְקוֹם הַיָּרֵחַ כַּמָּה הוּא. וְאִם הוּא רֹחַב צְפוֹנִי אוֹ דְּרוֹמִי וְהוּא הַנִּקְרָא רֹחַב רִאשׁוֹן. וְהִזָּהֵר בָּאֹרֶךְ הַזֶּה הָרִאשׁוֹן וּבָרֹחַב הָרִאשׁוֹן וְיִהְיוּ שְׁנֵיהֶם מוּכָנִים לְךָ:","וְהִתְבּוֹנֵן בְּאֹרֶךְ זֶה הָרִאשׁוֹן וּבָרֹחַב הַזֶּה הָרִאשׁוֹן. אִם יֵצֵא לְךָ תֵּשַׁע מַעֲלוֹת בְּשָׁוֶה אוֹ פָּחוֹת. תֵּדַע בְּוַדַּאי שֶׁאִי אֶפְשָׁר לְעוֹלָם שֶׁיֵּרָאֶה הַיָּרֵחַ בְּאוֹתוֹ הַלַּיְלָה בְּכָל אֶרֶץ יִשְׂרָאֵל וְאֵין אַתָּה צָרִיךְ חֶשְׁבּוֹן אַחֵר. וְאִם יִהְיֶה הָאֹרֶךְ הָרִאשׁוֹן יֶתֶר עַל ט\"ו מַעֲלוֹת תֵּדַע בְּוַדַּאי שֶׁהַיָּרֵחַ יֵרָאֶה בְּכָל אֶרֶץ יִשְׂרָאֵל וְאֵין אַתָּה צָרִיךְ לְחֶשְׁבּוֹן אַחֵר. וְאִם יִהְיֶה הָאֹרֶךְ הָרִאשׁוֹן מ\"ט מַעֲלוֹת וְעַד ט\"ו תִּצְטָרֵךְ לִדְרשׁ וְלַחֲקֹר בְּחֶשְׁבּוֹנוֹת הָרְאִיָּה עַד שֶׁתֵּדַע אִם יֵרָאֶה אוֹ לֹא יֵרָאֶה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה מְקוֹם הַיָּרֵחַ הָאֲמִתִּי מִתְּחִלַּת מַזַּל גְּדִי עַד סוֹף מַזַּל תְּאוֹמִים. אֲבָל אִם הָיָה מְקוֹם הַיָּרֵחַ מִתְּחִלַּת מַזַּל סַרְטָן עַד סוֹף מַזַּל קֶשֶׁת וְיִהְיֶה אֹרֶךְ הָרִאשׁוֹן עֶשֶׂר מַעֲלוֹת אוֹ פָּחוֹת. תֵּדַע שֶׁאֵין הַיָּרֵחַ נִרְאֶה כְּלָל בְּאוֹתוֹ הַלַּיְלָה בְּכָל אֶרֶץ יִשְׂרָאֵל. וְאִם הָיָה הָרִאשׁוֹן יֶתֶר עַל כ\"ד מַעֲלוֹת וַדַּאי יֵרָאֶה בְּכָל גְּבוּל יִשְׂרָאֵל. וְאִם יִהְיֶה הָאֹרֶךְ הָרִאשׁוֹן מֵעֶשֶׂר מַעֲלוֹת עַד עֶשְׂרִים וְאַרְבַּע תִּצְטָרֵךְ לִדְרשׁ וְלַחֲקֹר בְּחֶשְׁבּוֹנוֹת הָרְאִיָּה אִם יֵרָאֶה אוֹ לֹא יֵרָאֶה:","וְאֵלּוּ הֵן חֶשְׁבּוֹנוֹת הָרְאִיָּה. הִתְבּוֹנֵן וּרְאֵה הַיָּרֵחַ בְּאֵיזֶה מַזָּל הוּא. אִם יִהְיֶה בְּמַזַּל טָלֶה תִּגְרַע מִן הָאֹרֶךְ הָרִאשׁוֹן נ\"ט חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל שׁוֹר תִּגְרַע מִן הָאֹרֶךְ מַעֲלָה אַחַת. וְאִם יִהְיֶה בְּמַזַּל תְּאוֹמִים תִּגְרַע מִן הָאֹרֶךְ נ\"ח חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל סַרְטָן תִּגְרַע מִן הָאֹרֶךְ (מ\"ג) [נ\"ב] חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל אַרְיֵה תִּגְרַע מִן הָאֹרֶךְ מ\"ג חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל בְּתוּלָה תִּגְרַע מִן הָאֹרֶךְ ל\"ז חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל מֹאזְנַיִם תִּגְרַע מִן הָאֹרֶךְ ל\"ד חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל עַקְרָב תִּגְרַע מִן הָאֹרֶךְ ל\"ד חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל קֶשֶׁת תִּגְרַע מִן הָאֹרֶךְ ל\"ו חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל גְּדִי תִּגְרַע מִן הָאֹרֶךְ מ\"ד חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל דְּלִי תִּגְרַע מִן הָאֹרֶךְ נ\"ג חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל דָּגִים תִּגְרַע מִן הָאֹרֶךְ נ\"ח חֲלָקִים. וְהַנִּשְׁאָר מִן הָאֹרֶךְ אַחַר שֶׁתִּגְרַע מִמֶּנּוּ אֵלּוּ הַחֲלָקִים הוּא הַנִּקְרָא אֹרֶךְ שֵׁנִי:","וְלָמָּה גּוֹרְעִין חֲלָקִים אֵלּוּ. לְפִי שֶׁמְּקוֹם הַיָּרֵחַ הָאֲמִתִּי אֵינוֹ הַמָּקוֹם שֶׁיֵּרָאֶה בּוֹ אֶלָּא שִׁנּוּי יֵשׁ בֵּינֵיהֶם בָּאֹרֶךְ וּבָרֹחַב. וְהוּא הַנִּקְרָא שִׁנּוּי הַמַּרְאֶה. וְשִׁנּוּי מַרְאֵה הָאֹרֶךְ בִּשְׁעַת הָרְאִיָּה לְעוֹלָם גּוֹרְעִין אוֹתוֹ מִן הָאֹרֶךְ כְּמוֹ שֶׁאָמַרְנוּ:","אֲבָל שִׁנּוּי מַרְאֵה הָרֹחַב. אִם הָיָה רֹחַב הַיָּרֵחַ צְפוֹנִי גּוֹרְעִין חֲלָקִים שֶׁל שִׁנּוּי מַרְאֵה הָרֹחַב מִן הָרֹחַב הָרִאשׁוֹן. וְאִם הָיָה רֹחַב הַיָּרֵחַ הַדְּרוֹמִי מוֹסִיפִין הַחֲלָקִים שֶׁל שִׁנּוּי מַרְאֵה הָרֹחַב עַל הָרֹחַב הָרִאשׁוֹן. וּמַה שֶּׁיִּהְיֶה הָרֹחַב הָרִאשׁוֹן אַחַר שֶׁמּוֹסִיפִין עָלָיו אוֹ גּוֹרְעִין מִמֶּנּוּ אוֹתָם הַחֲלָקִים הוּא הַנִּקְרָא רֹחַב שֵׁנִי:","וְכַמָּה הֵם הַחֲלָקִים שֶּׁמּוֹסִיפִין אוֹ גּוֹרְעִין אוֹתָן. אִם יִהְיֶה הַיָּרֵחַ בְּמַזַּל טָלֶה תִּשְׁעָה חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל שׁוֹר י' חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל תְּאוֹמִים ט\"ז חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל סַרְטָן כ\"ז חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל אַרְיֵה ל\"ח חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל בְּתוּלָה מ\"ד חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל מֹאזְנַיִם מ\"ו חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל עַקְרָב מ\"ה חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל קֶשֶׁת מ\"ד חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל גְּדִי ל\"ו חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל דְּלִי (כ\"ד) [כ\"ז] חֲלָקִים. וְאִם יִהְיֶה בְּמַזַּל דָּגִים י\"ב חֲלָקִים:","מֵאַחַר שֶׁתֵּדַע חֲלָקִים אֵלּוּ תִּגְרַע אוֹתָן מִן הָרֹחַב הָרִאשׁוֹן אוֹ תּוֹסִיף אוֹתָן עָלָיו כְּמוֹ שֶׁהוֹדַעְנוּךָ וְיֵצֵא לְךָ הָרֹחַב הַשֵּׁנִי. וּכְבָר יָדַעְתָּ אִם הוּא צְפוֹנִי אוֹ דְּרוֹמִי. וְתֵדַע כַּמָּה מַעֲלוֹת וְכַמָּה חֲלָקִים נַעֲשָׂה זֶה הָרֹחַב הַשֵּׁנִי וְתָכִין אוֹתוֹ לְפָנֶיךָ וְיִהְיֶה עָתִיד:","וְאַחַר כָּךְ תַּחֲזֹר וְתִקַּח מִן הָרֹחַב הַשֵּׁנִי הַזֶּה מִקְצָתוֹ. מִפְּנֵי שֶׁהַיָּרֵחַ נָלוֹז מְעַט בְּמַעְגָּלוֹ. וְכַמָּה הוּא הַמִּקְצָת שֶׁתִּקַּח מִמֶּנּוּ. אִם יִהְיֶה מְקוֹם הַיָּרֵחַ מִתְּחִלַּת מַזַּל טָלֶה עַד כ' מַעֲלוֹת מִמֶּנּוּ. אוֹ מִתְּחִלַּת מַזַּל מֹאזְנַיִם עַד כ' מַעֲלוֹת מִמֶּנּוּ. תִּקַּח מִן הָרֹחַב הַשֵּׁנִי שְׁנֵי חֲמִשָּׁיו. וְאִם יִהְיֶה הַיָּרֵחַ מִכ' מִמַּזַּל טָלֶה עַד י' מַעֲלוֹת מִמַּזַּל שׁוֹר אוֹ מִכ' מִמַּזַּל מֹאזְנַיִם עַד י' מַעֲלוֹת מִמַּזַּל עַקְרָב תִּקַּח מִן הָרֹחַב הַשֵּׁנִי שְׁלִישִׁיתוֹ. וְאִם יִהְיֶה הַיָּרֵחַ מֵעֶשֶׂר מַעֲלוֹת מִמַּזַּל שׁוֹר עַד כ' מִמֶּנּוּ אוֹ מֵעֶשֶׂר מַעֲלוֹת מִמַּזַּל עַקְרָב עַד כ' מִמֶּנּוּ תִּקַּח מִן הָרֹחַב הַשֵּׁנִי רְבִיעִיתוֹ. וְאִם יִהְיֶה הַיָּרֵחַ מִכ' מַעֲלוֹת מִמַּזַּל שׁוֹר עַד סוֹפוֹ אוֹ מִכ' מִמַּזַּל עַקְרָב עַד סוֹפוֹ תִּקַּח מִן הָרֹחַב הַשֵּׁנִי חֲמִישִׁיתוֹ. וְאִם יִהְיֶה הַיָּרֵחַ מִתְּחִלַּת מַזַּל תְּאוֹמִים עַד עֶשֶׂר מַעֲלוֹת מִמֶּנּוּ אוֹ מִתְּחִלַּת מַזַּל קֶשֶׁת עַד עֶשֶׂר מַעֲלוֹת מִמֶּנּוּ תִּקַּח מִן הָרֹחַב הַשֵּׁנִי שְׁתוּתוֹ. וְאִם יִהְיֶה הַיָּרֵחַ מִי' מַעֲלוֹת מִמַּזַּל תְּאוֹמִים וְעַד כ' מִמֶּנּוּ אוֹ מֵעֶשֶׂר מִמַּזַּל קֶשֶׁת עַד כ' מִמֶּנּוּ תִּקַּח מִן הָרֹחַב הַשֵּׁנִי חֲצִי שְׁתוּתוֹ. וְאִם יִהְיֶה מְקוֹם הַיָּרֵחַ מִכ' מִמַּזַּל תְּאוֹמִים עַד כ\"ה מִמֶּנּוּ אוֹ מִכ' מִמַּזַּל קֶשֶׁת עַד כ\"ה מִמֶּנּוּ תִּקַּח מִן הָרֹחַב הַשֵּׁנִי רְבִיעַ שְׁתוּתוֹ. וְאִם יִהְיֶה מְקוֹם הַיָּרֵחַ מִכ\"ה מִמַּזַּל תְּאוֹמִים עַד חָמֵשׁ מַעֲלוֹת מִמַּזַּל סַרְטָן אוֹ מִכ\"ה מִמַּזַּל קֶשֶׁת עַד חָמֵשׁ מַעֲלוֹת מִמַּזַּל גְּדִי לֹא תִּקַּח כְּלוּם. לְפִי שֶׁאֵין כָּאן נְלִיזַת מַעְגָּל. וְאִם יִהְיֶה הַיָּרֵחַ מֵחָמֵשׁ מִמַּזַּל סַרְטָן עַד עֶשֶׂר מִמֶּנּוּ אוֹ מֵחָמֵשׁ מִמַּזַּל גְּדִי עַד עֶשֶׂר מִמֶּנּוּ תִּקַּח מִן הָרֹחַב הַשֵּׁנִי רְבִיעַ שְׁתוּתוֹ. וְאִם יִהְיֶה מְקוֹם הַיָּרֵחַ מִי' מִמַּזַּל סַרְטָן עַד כ' מִמֶּנּוּ אוֹ מֵעֶשֶׂר מִמַּזַּל גְּדִי עַד עֶשְׂרִים מִמֶּנּוּ תִּקַּח מִן הָרֹחַב הַשֵּׁנִי חֲצִי שְׁתוּתוֹ. וְאִם יִהְיֶה מְקוֹם הַיָּרֵחַ מִכ' מִמַּזַּל סַרְטָן עַד סוֹפוֹ אוֹ מִכ' מִמַּזַּל גְּדִי עַד סוֹפוֹ תִּקַּח מִן הָרֹחַב הַשֵּׁנִי שְׁתוּתוֹ. וְאִם יִהְיֶה הַיָּרֵחַ מִתְּחִלַּת מַזַּל אַרְיֵה עַד עֶשֶׂר מַעֲלוֹת מִמֶּנּוּ אוֹ מִתְּחִלַּת מַזַּל דְּלִי עַד עֶשֶׂר מַעֲלוֹת מִמֶּנּוּ תִּקַּח מִמֶּנּוּ הָרֹחַב הַשֵּׁנִי חֲמִישִׁיתוֹ. וְאִם יִהְיֶה הַיָּרֵחַ מִי' מַעֲלוֹת מִמַּזַּל אַרְיֵה עַד כ' מִמֶּנּוּ אוֹ מִי' מִמַּזַּל דְּלִי עַד כ' מִמֶּנּוּ תִּקַּח מִן הָרֹחַב הַשֵּׁנִי רְבִיעִיתוֹ. וְאִם יִהְיֶה הַיָּרֵחַ מִכ' מִמַּזַּל אַרְיֵה עַד עֶשֶׂר מִמַּזַּל בְּתוּלָה אוֹ מִכ' מִמַּזַּל דְּלִי עַד עֶשֶׂר מִמַּזַּל דָּגִים תִּקַּח מִן הָרֹחַב הַשֵּׁנִי שְׁלִישִׁיתוֹ. וְאִם יִהְיֶה הַיָּרֵחַ מֵעֶשֶׂר מִמַּזַּל בְּתוּלָה עַד סוֹפוֹ אוֹ מִי' מַעֲלוֹת מִמַּזַּל דָּגִים עַד סוֹפוֹ תִּקַּח מִן הָרֹחַב הַשֵּׁנִי ב' חֲמִשָּׁיו. וְזֹאת הַמִּקְצָת שֶׁתִּקַּח מִן הָרֹחַב הַשֵּׁנִי הִיא הַנִּקְרֵאת מַעְגַּל הַיָּרֵחַ:","וְאַחַר כָּךְ תַּחֲזֹר וְתִתְבּוֹנֵן בְּרֹחַב הַיָּרֵחַ וְתִרְאֶה אִם הוּא צְפוֹנִי אוֹ דְּרוֹמִי. אִם הָיָה צְפוֹנִי תִּגְרַע מַעְגַּל הַיָּרֵחַ הַזֶּה מִן הָאֹרֶךְ הַשֵּׁנִי. וְאִם הָיָה רֹחַב הַיָּרֵחַ דְּרוֹמִי תּוֹסִיף הַמַּעְגָּל הַזֶּה עַל הָאֹרֶךְ הַשֵּׁנִי. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה מְקוֹם הַיָּרֵחַ מִתְּחִלַּת מַזַּל גְּדִי עַד סוֹף מַזַּל תְּאוֹמִים. אֲבָל אִם הָיָה הַיָּרֵחַ מִתְּחִלַּת מַזַּל סַרְטָן עַד סוֹף מַזַּל קֶשֶׁת יִהְיֶה הַדָּבָר הֵפֶךְ. שֶׁאִם יִהְיֶה רֹחַב הַיָּרֵחַ צְפוֹנִי תּוֹסִיף הַמַּעְגָּל עַל הָאֹרֶךְ הַשֵּׁנִי. וְאִם הָיָה רֹחַב הַיָּרֵחַ דְּרוֹמִי תִּגְרַע הַמַּעְגָּל מִן הָאֹרֶךְ הַשֵּׁנִי. וּמַה שֶּׁיִּהְיֶה הָאֹרֶךְ הַשֵּׁנִי אַחַר שֶׁתּוֹסִיף עָלָיו אוֹ תִּגְרַע מִמֶּנּוּ הוּא הַנִּקְרָא אֹרֶךְ הַשְּׁלִישִׁי. וְדַע שֶׁאִם לֹא יִהְיֶה שָׁם נְלִיזַת מַעְגָּל וְלֹא נָתַן הַחֶשְׁבּוֹן לָקַחַת מִן הָרֹחַב הַשֵּׁנִי כְּלוּם. יִהְיֶה הָאֹרֶךְ הַשֵּׁנִי עַצְמוֹ הוּא הָאֹרֶךְ הַשְּׁלִישִׁי בְּלֹא פָּחוֹת וּבְלֹא יֶתֶר:","וְאַחַר כָּךְ תַּחֲזֹר וְתִרְאֶה הָאֹרֶךְ הַשְּׁלִישִׁי הַזֶּה וְהוּא הַמַּעֲלוֹת שֶׁבֵּין הַיָּרֵחַ וְהַשֶּׁמֶשׁ בְּאֵיזֶה מַזָּל הוּא. אִם יִהְיֶה בְּמַזַּל דָּגִים אוֹ בְּמַזַּל טָלֶה. תּוֹסִיף עַל הָאֹרֶךְ הַשְּׁלִישִׁי שְׁתוּתוֹ. וְאִם יִהְיֶה הָאֹרֶךְ בְּמַזַּל דְּלִי אוֹ בְּמַזַּל שׁוֹר. תּוֹסִיף עַל הָאֹרֶךְ הַשְּׁלִישִׁי חֲמִישִׁיתוֹ. וְאִם יִהְיֶה הָאֹרֶךְ בְּמַזַּל גְּדִי אוֹ בְּמַזַּל תְּאוֹמִים. תּוֹסִיף עַל הָאֹרֶךְ הַשְּׁלִישִׁי שְׁתוּתוֹ. וְאִם יִהְיֶה הָאֹרֶךְ בְּמַזַּל קֶשֶׁת אוֹ בְּמַזַּל סַרְטָן. תָּנִיחַ הָאֹרֶךְ הַשְּׁלִישִׁי כְּמוֹת שֶׁהוּא וְלֹא תּוֹסִיף עָלָיו וְלֹא תִּגְרַע מִמֶּנּוּ. וְאִם הָיָה הָאֹרֶךְ בְּמַזַּל עַקְרָב אוֹ בְּמַזַּל אַרְיֵה. תִּגְרַע מִן הָאֹרֶךְ הַשְּׁלִישִׁי חֲמִישִׁיתוֹ. וְאִם יִהְיֶה הָאֹרֶךְ בְּמַזַּל מֹאזְנַיִם אוֹ בְּמַזַּל בְּתוּלָה. תִּגְרַע מִן הָאֹרֶךְ הַשְּׁלִישִׁי שְׁלִישִׁיתוֹ. וּמַה שֶּׁיִּהְיֶה הָאֹרֶךְ הַשְּׁלִישִׁי אַחַר שֶׁתּוֹסִיף עָלָיו אוֹ תִּגְרַע מִמֶּנּוּ אוֹ תָּנִיחַ אוֹתוֹ כְּמוֹת שֶׁהוּא. הוּא הַנִּקְרָא אֹרֶךְ רְבִיעִי. וְאַחַר כָּךְ תַּחֲזֹר אֵצֶל רֹחַב הַיָּרֵחַ הָרִאשׁוֹן וְתִקַּח שְׁנֵי שְׁלִישָׁיו לְעוֹלָם. וְזֶה הוּא הַנִּקְרָא מְנַת גֹּבַהּ הַמְּדִינָה. וְתִתְבּוֹנֵן וְתִרְאֶה אִם יִהְיֶה רֹחַב הַיָּרֵחַ צְפוֹנִי. תּוֹסִיף מְנַת גֹּבַהּ הַמְּדִינָה עַל הָאֹרֶךְ הָרְבִיעִי. וְאִם יִהְיֶה רֹחַב הַיָּרֵחַ דְּרוֹמִי. תִּגְרַע מְנַת גֹּבַהּ הַמְּדִינָה מִן הָאֹרֶךְ הָרְבִיעִי. וּמַה שֶּׁיִּהְיֶה הָאֹרֶךְ הָרְבִיעִי אַחַר שֶׁגּוֹרְעִין מִמֶּנּוּ אוֹ שֶׁמּוֹסִיפִין עָלָיו הוּא הַנִּקְרָא קֶשֶׁת הָרְאִיָּה:","כֵּיצַד. הֲרֵי שֶׁבָּאנוּ לַחְקֹר אִם יֵרָאֶה הַיָּרֵחַ בְּלֵיל עֶרֶב שַׁבָּת שֵׁנִי לְחֹדֶשׁ אִיָּר מִשָּׁנָה זוֹ אוֹ לֹא יֵרָאֶה. תּוֹצִיא מְקוֹם הַשֶּׁמֶשׁ הָאֲמִתִּי וּמְקוֹם הַיָּרֵחַ הָאֲמִתִּי וְרֹחַב הַיָּרֵחַ לְשָׁנָה זוֹ כְּמוֹ שֶׁהוֹדַעְנוּךָ. יֵצֵא לְךָ מְקוֹם הַשֶּׁמֶשׁ הָאֲמִתִּי בְּז' מַעֲלוֹת וְט' חֲלָקִים מִמַּזַּל שׁוֹר. סִימָנוֹ ז\"ט. וְיֵצֵא לְךָ מְקוֹם הַיָּרֵחַ הָאֲמִתִּי בְּי\"ח מַעֲלוֹת וְל\"ו חֲלָקִים מִמַּזַּל שׁוֹר. סִימָנוֹ י\"ח ל\"ו. וְיֵצֵא לְךָ רֹחַב הַיָּרֵחַ בְּרוּחַ דָּרוֹם שָׁלֹשׁ מַעֲלוֹת וְנ\"ג חֲלָקִים. סִימָנוֹ נ\"ג ג'. וְזֶה הוּא הָרֹחַב הָרִאשׁוֹן. וְתִגְרַע מְקוֹם הַשֶּׁמֶשׁ מִמְּקוֹם הַיָּרֵחַ יִשָּׁאֵר י\"א מַעֲלוֹת וְכ\"ז חֲלָקִים. סִימָנוֹ י\"א כ\"ז. וְזֶה הוּא הָאֹרֶךְ הָרִאשׁוֹן. וּלְפִי שֶׁהָיָה הַיָּרֵחַ בְּמַזַּל שׁוֹר יִהְיֶה שִׁנּוּי מַרְאֵה הָאֹרֶךְ מַעֲלָה אַחַת וְרָאוּי לִגְרֹעַ אוֹתָהּ מִן הָאֹרֶךְ הָרִאשׁוֹן. יֵצֵא לְךָ הָאֹרֶךְ הַשֵּׁנִי י' מַעֲלוֹת וְכ\"ז חֲלָקִים. סִימָנוֹ יכ\"ז. וְכֵן יִהְיֶה שִׁנּוּי מַרְאֵה הָרֹחַב י' חֲלָקִים. וּלְפִי שֶׁרֹחַב הַיָּרֵחַ הָיָה דְּרוֹמִי רָאוּי לְהוֹסִיף עָלָיו שִׁנּוּי הַמַּרְאֶה שֶׁהוּא עֲשָׂרָה חֲלָקִים. יֵצֵא לְךָ הָרֹחַב הַשֵּׁנִי ד' מַעֲלוֹת וְג' חֲלָקִים. סִימָנוֹ ד\"ג. וּלְפִי שֶׁהָיָה הַיָּרֵחַ בְּי\"ח מַעֲלוֹת מִמַּזַּל שׁוֹר רָאוּי לִקַּח מִן הָרֹחַב הַשֵּׁנִי רְבִיעִיתוֹ וְהוּא הַנִּקְרָא מַעְגַּל הַיָּרֵחַ. יֵצֵא לְךָ מַעְגַּל הַיָּרֵחַ לְעֵת זוֹ מַעֲלָה אַחַת וְחֵלֶק אֶחָד לְפִי שֶׁאֵין מְדַקְדְּקִין בִּשְׁנִיּוֹת:","וּלְפִי שֶׁרֹחַב הַיָּרֵחַ דְּרוֹמִי וּמְקוֹם הַיָּרֵחַ הָאֲמִתִּי בֵּין רֹאשׁ גְּדִי וְרֹאשׁ סַרְטָן. רָאוּי לְהוֹסִיף הַמַּעְגָּל עַל הָאֹרֶךְ הַשֵּׁנִי. יֵצֵא לְךָ הָאֹרֶךְ הַשְּׁלִישִׁי י\"א מַעֲלוֹת וְכ\"ח חֲלָקִים. סִימָנוֹ י\"א כ\"ח. וּלְפִי שֶׁהָאֹרֶךְ הַזֶּה בְּמַזַּל שׁוֹר רָאוּי לְהוֹסִיף עַל הָאֹרֶךְ הַשְּׁלִישִׁי חֲמִישִׁיתוֹ שֶׁהוּא שְׁתֵּי מַעֲלוֹת וְי\"ח חֲלָקִים. וְיֵצֵא לְךָ הָאֹרֶךְ הָרְבִיעִי י\"ג מַעֲלוֹת וּמ\"ו חֲלָקִים. סִימָנוֹ י\"ג מ\"ו. וְחָזַרְנוּ אֵצֶל הָרֹחַב הָרִאשׁוֹן וְלָקַחְנוּ שְׁנֵי שְׁלִישָׁיו וְיֵצֵא מְנַת גֹּבַהּ הַמְּדִינָה וְהוּא שְׁתֵּי מַעֲלוֹת וְל\"ה חֲלָקִים. וּלְפִי שֶׁהָיָה הָרֹחַב דְּרוֹמִי. רָאוּי לִגְרֹעַ מִמֶּנּוּ מְנַת גֹּבַהּ הַמְּדִינָה מִן הָאֹרֶךְ הָרְבִיעִי. יִשָּׁאֵר לְךָ י\"א מַעֲלוֹת וְי\"א חֲלָקִים. סִימָנוֹ י\"א י\"א. וְזוֹ הִיא קֶשֶׁת הָרְאִיָּה בַּלַּיְלָה הַזֶּה. וְעַל הַדֶּרֶךְ הַזֶּה תַּעֲשֶׂה וְתֵדַע קֶשֶׁת הָרְאִיָּה כַּמָּה מַעֲלוֹת וְכַמָּה חֲלָקִים יֵשׁ בָּהּ בְּכָל לֵיל רְאִיָּה שֶׁתִּרְצֶה לְעוֹלָם:","וְאַחַר שֶׁתֵּצֵא קֶשֶׁת זוֹ תָּבִין בָּהּ. וְדַע שֶׁאִם תִּהְיֶה קֶשֶׁת הָרְאִיָּה תֵּשַׁע מַעֲלוֹת אוֹ פָּחוֹת אָז אֶפְשָׁר שֶׁיֵּרָאֶה בְּכָל אֶרֶץ יִשְׂרָאֵל. וְאִם תִּהְיֶה קֶשֶׁת הָרְאִיָּה יֶתֶר עַל י\"ד מַעֲלוֹת אִי אֶפְשָׁר שֶׁלֹּא יֵרָאֶה וְיִהְיֶה גָּלוּי לְכָל אֶרֶץ יִשְׂרָאֵל:","וְאִם תִּהְיֶה קֶשֶׁת הָרְאִיָּה מִתְּחִלַּת מַעֲלָה עֲשִׂירִית עַד סוֹף מַעֲלַת י\"ד. תַּעֲרֹךְ קֶשֶׁת הָרְאִיָּה אֶל הָאֹרֶךְ הָרִאשׁוֹן וְתֵדַע אִם יֵרָאֶה אוֹ לֹא יֵרָאֶה מִן הַקִּצִּין שֶׁיֵּשׁ לוֹ. וְהֵן הַנִּקְרָאִין קִצֵּי הָרְאִיָּה:","וְאִלּוּ הֵן קִצֵּי הָרְאִיָּה. אִם תִּהְיֶה קֶשֶׁת הָרְאִיָּה מִיֶּתֶר עַל ט' מַעֲלוֹת עַד סוֹף עֶשֶׂר מַעֲלוֹת אוֹ יֶתֶר עַל עֶשֶׂר. וְיִהְיֶה הָאֹרֶךְ הָרִאשׁוֹן י\"ג מַעֲלוֹת אוֹ יוֹתֵר. וַדַּאי יֵרָאֶה. וְאִם תִּהְיֶה הַקֶּשֶׁת פָּחוֹת מִזֶּה אוֹ יִהְיֶה הָאֹרֶךְ פָּחוֹת מִזֶּה לֹא יֵרָאֶה:","וְאִם תִּהְיֶה קֶשֶׁת הָרְאִיָּה מִיֶּתֶר עַל עֶשֶׂר מַעֲלוֹת עַד סוֹף י\"א מַעֲלוֹת אוֹ יֶתֶר עַל אַחַת עֶשְׂרֵה. וְיִהְיֶה הָאֹרֶךְ הָרִאשׁוֹן י\"ב מַעֲלוֹת אוֹ יוֹתֵר. וַדַּאי יֵרָאֶה. וְאִם תִּהְיֶה הַקֶּשֶׁת פָּחוֹת מִזֶּה אוֹ יִהְיֶה הָאֹרֶךְ פָּחוֹת מִזֶּה לֹא יֵרָאֶה:","וְאִם תִּהְיֶה קֶשֶׁת הָרְאִיָּה מִיֶּתֶר עַל י\"א עַד סוֹף י\"ב מַעֲלוֹת אוֹ יֶתֶר עַל י\"ב. וְיִהְיֶה הָאֹרֶךְ הָרִאשׁוֹן י\"א מַעֲלוֹת אוֹ יוֹתֵר וַדַּאי יֵרָאֶה. וְאִם תִּהְיֶה הַקֶּשֶׁת פָּחוֹת מִזֶּה אוֹ יִהְיֶה הָאֹרֶךְ פָּחוֹת מִזֶּה לֹא יֵרָאֶה:","וְאִם תִּהְיֶה קֶשֶׁת הָרְאִיָּה מִיֶּתֶר עַל י\"ב מַעֲלוֹת עַד סוֹף י\"ג מַעֲלוֹת אוֹ יֶתֶר עַל י\"ג. וְיִהְיֶה הָאֹרֶךְ הָרִאשׁוֹן י' מַעֲלוֹת אוֹ יוֹתֵר וַדַּאי יֵרָאֶה. וְאִם תִּהְיֶה הַקֶּשֶׁת פָּחוֹת מִזֶּה אוֹ יִהְיֶה הָאֹרֶךְ פָּחוֹת מִזֶּה לֹא יֵרָאֶה:","וְאִם תִּהְיֶה הָרְאִיָּה מִיֶּתֶר עַל י\"ג מַעֲלוֹת עַד סוֹף י\"ד מַעֲלוֹת אוֹ יֶתֶר עַל י\"ד. וְיִהְיֶה הָאֹרֶךְ הָרִאשׁוֹן תֵּשַׁע מַעֲלוֹת אוֹ יוֹתֵר וַדַּאי יֵרָאֶה. וְאִם תִּהְיֶה הַקֶּשֶׁת פָּחוֹת מִזֶּה אוֹ יִהְיֶה הָאֹרֶךְ פָּחוֹת מִזֶּה לֹא יֵרָאֶה. וְעַד כָּאן סוֹף הַקִּצִּין:","כֵּיצַד. בָּאנוּ לְהִתְבּוֹנֵן בְּקֶשֶׁת הָרְאִיָּה שֶׁל לֵיל עֶרֶב שַׁבָּת שֵׁנִי לְחֹדֶשׁ אִיָּר מִשָּׁנָה זוֹ. יֵצֵא לָנוּ בְּחֶשְׁבּוֹן קֶשֶׁת הָרְאִיָּה י\"א מַעֲלוֹת וְי\"א חֲלָקִים כְּמוֹ שֶׁיָּדַעְתָּ. וּלְפִי שֶׁהָיָה קֶשֶׁת הָרְאִיָּה בֵּין עֶשֶׂר עַד אַרְבַּע עֶשְׂרֵה עָרַכְנוּ אוֹתָהּ אֶל הָאֹרֶךְ הָרִאשׁוֹן. וּכְבָר יָדַעְתָּ שֶׁהָאֹרֶךְ הָיָה בְּלֵיל זֶה י\"א מַעֲלוֹת וְכ\"ז חֲלָקִים. וּלְפִי שֶׁהָיְתָה קֶשֶׁת הָרְאִיָּה יֶתֶר עַל י\"א מַעֲלוֹת וְהָיָה הָאֹרֶךְ הָרִאשׁוֹן יֶתֶר עַל עֲשָׂרָה [א.] יוֹדֵעַ שֶׁוַּדַּאי יֵרָאֶה בְּלֵיל זֶה לְפִי הַקִּצִּין הַקְּצוּבוֹת. וְכֵן תַּעֲשֶׂה בְּכָל קֶשֶׁת וָקֶשֶׁת עִם הָאֹרֶךְ הָרִאשׁוֹן שֶׁלָּהּ:","וּכְבָר רָאִיתָ מִן הַמַּעֲשִׂים הָאֵלּוּ כַּמָּה חֶשְׁבּוֹנוֹת יֵשׁ בּוֹ וְכַמָּה תּוֹסָפוֹת וְכַמָּה גֵּרוּעִין אַחַר שֶׁיָּגַעְנוּ הַרְבֵּה. עַד שֶׁהִמְצִיאָנוּ דְּרָכִים קְרוֹבִים שֶׁאֵין בְּחֶשְׁבּוֹנָם עֹמֶק גָּדוֹל. שֶׁהַיָּרֵחַ עֲקַלְקַלּוֹת גְּדוֹלוֹת יֵשׁ בְּמַעְגְּלוֹתָיו. וּלְפִיכָךְ אָמְרוּ חֲכָמִים (תהילים קד יט) \"שֶׁמֶשׁ יָדַע מְבוֹאוֹ\" יָרֵחַ לֹא יָדַע מְבוֹאוֹ. וְאָמְרוּ חֲכָמִים פְּעָמִים בָּא בַּאֲרֻכָּה פְּעָמִים בָּא בִּקְצָרָה. כְּמוֹ שֶׁתִּרְאֶה מֵחֶשְׁבּוֹנוֹת אֵלּוּ שֶׁפְּעָמִים תּוֹסִיף וּפְעָמִים תִּגְרַע עַד שֶׁתְּהֵא קֶשֶׁת הָרְאִיָּה. וּפְעָמִים תִּהְיֶה קֶשֶׁת הָרְאִיָּה אֲרוּכָּה וּפְעָמִים קְצָרָה כְּמוֹ שֶׁבֵּאַרְנוּ:","וְטַעַם כָּל אֵלּוּ הַחֶשְׁבּוֹנוֹת וּמִפְּנֵי מָה מוֹסִיפִים מִנְיָן זֶה וּמִפְּנֵי מָה גּוֹרְעִין. וְהֵיאַךְ נוֹדַע כָּל דָּבָר וְדָבָר מֵאֵלּוּ הַדְּבָרִים. וְהָרְאָיָה עַל כָּל דָּבָר וְדָבָר. הִיא חָכְמַת הַתְּקוּפוֹת וְהַגִּימַטְרִיּוֹת שֶׁחִבְּרוּ בָּהּ חַכְמֵי יָוָן סְפָרִים הַרְבֵּה וְהֵם הַנִּמְצָאִים עַכְשָׁו בְּיַד הַחֲכָמִים. אֲבָל הַסְּפָרִים שֶׁחִבְּרוּ חַכְמֵי יִשְׂרָאֵל שֶׁהָיוּ בִּימֵי הַנְּבִיאִים מִבְּנֵי יִשָּׂשכָר לֹא הִגִּיעוּ אֵלֵינוּ. וּמֵאַחַר שֶׁכָּל אֵלּוּ הַדְּבָרִים בִּרְאָיוֹת בְּרוּרוֹת הֵם שֶׁאֵין בָּהֶם דֹּפִי וְאִי אֶפְשָׁר לְאָדָם לְהַרְהֵר אַחֲרֵיהֶם, אֵין חוֹשְׁשִׁין לַמְחַבֵּר בֵּין שֶׁחִבְּרוּ אוֹתָם נְבִיאִים בֵּין שֶׁחִבְּרוּ אוֹתָם הָאֻמּוֹת. שֶׁכָּל דָּבָר שֶׁנִּתְגַּלָּה טַעֲמוֹ וְנוֹדְעָה אֲמִתָּתוֹ בִּרְאָיוֹת שֶׁאֵין בָּהֶם דֹּפִי אָנוּ סוֹמְכִין עַל זֶה הָאִישׁ שֶׁאֲמָרוֹ אוֹ שֶׁלִּמְּדוֹ עַל הָרְאָיָה שֶׁנִּתְגַּלְּתָה וְהַטַּעַם שֶׁנּוֹדַע:"],"Mishneh Torah, Scroll of Esther and Hanukkah 2":["הַקוֹרֵא אֶת הַמְּגִלָּה לְמַפְרֵעַ לֹא יָצָא. קָרָא וְשָׁכַח פָּסוּק אֶחָד וְקָרָא פָּסוּק שֵׁנִי לוֹ וְחָזַר וְקָרָא פָּסוּק שֶׁשָּׁכַח וְחָזַר וְקָרָא פָּסוּק שְׁלִישִׁי לֹא יָצָא מִפְּנֵי שֶׁקָּרָא פָּסוּק אֶחָד לְמַפְרֵעַ. אֶלָּא כֵּיצַד עוֹשֶׂה. מַתְחִיל מִפָּסוּק שֵׁנִי שֶׁשָּׁכַח וְקוֹרֵא עַל הַסֵּדֶר:","מָצָא צִבּוּר שֶׁקָּרְאוּ חֶצְיָהּ לֹא יֹאמַר אֶקְרָא חֶצְיָהּ הָאַחֲרוֹן עִם הַצִּבּוּר וְאֶחֱזֹר וְאֶקְרָא חֶצְיָהּ רִאשׁוֹן, שֶׁזֶּה קוֹרֵא לְמַפְרֵעַ. אֶלָּא קוֹרֵא מִתְּחִלָּה וְעַד סוֹף עַל הַסֵּדֶר. קָרָא וְשָׁהָה מְעַט וְחָזַר וְקָרָא אַף עַל פִּי שֶׁשָּׁהָה כְּדֵי לִגְמֹר אֶת כֻּלָּהּ הוֹאִיל וְקָרָא עַל הַסֵּדֶר יָצָא:","הַקּוֹרֵא אֶת הַמְּגִלָּה עַל פֶּה לֹא יָצָא יְדֵי חוֹבָתוֹ. הַלּוֹעֵז שֶׁשָּׁמַע אֶת הַמְּגִלָּה הַכְּתוּבָה בִּלְשׁוֹן הַקֹּדֶשׁ וּבִכְתַב הַקֹּדֶשׁ אַף עַל פִּי שֶׁאֵינוֹ יוֹדֵעַ מַה הֵן אוֹמְרִין יָצָא יְדֵי חוֹבָתוֹ. וְכֵן אִם הָיְתָה כְּתוּבָה יְוָנִית וּשְׁמָעָהּ יָצָא אַף עַל פִּי שֶׁאֵינוֹ מַכִּיר, וַאֲפִלּוּ הָיָה הַשּׁוֹמֵעַ עִבְרִי:","הָיְתָה כְּתוּבָה תַּרְגּוּם אוֹ בְּלָשׁוֹן אַחֶרֶת מִלְּשׁוֹנוֹת הַגּוֹיִם לֹא יָצָא יְדֵי חוֹבָתוֹ בִּקְרִיאָתָהּ אֶלָּא הַמַּכִּיר אוֹתָהּ הַלָּשׁוֹן בִּלְבַד. וְהוּא שֶׁתִּהְיֶה כְּתוּבָה בִּכְתַב אוֹתוֹ הַלָּשׁוֹן. אֲבָל אִם הָיְתָה כְּתוּבָה בִּכְתָב עִבְרִי וּקְרָאָהּ אֲרָמִית לַאֲרָמִי לֹא יָצָא שֶׁנִּמְצָא זֶה קוֹרֵא עַל פֶּה. וְכֵיוָן שֶׁלֹּא יָצָא יְדֵי חוֹבָתוֹ הַקּוֹרֵא לֹא יָצָא הַשּׁוֹמֵעַ מִמֶּנּוּ:","הַקּוֹרֵא אֶת הַמְּגִלָּה בְּלֹא כַּוָּנָה לֹא יָצָא. כֵּיצַד. הָיָה כּוֹתְבָהּ אוֹ דּוֹרְשָׁהּ אוֹ מַגִּיהָהּ אִם כִּוֵּן אֶת לִבּוֹ לָצֵאת בִּקְרִיאָה זוֹ יָצָא וְאִם לֹא כִּוִּן לִבּוֹ לֹא יָצָא. קָרָא וְהוּא מִתְנַמְנֵם הוֹאִיל וְלֹא נִרְדַּם בַּשֵּׁנָה יָצָא:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהַמְכַוֵּן לִבּוֹ בַּכְּתִיבָה יָצָא. בְּשֶׁנִּתְכַּוֵּן לָצֵאת בַּקְּרִיאָה שֶׁקּוֹרֵא בְּסֵפֶר שֶׁמַּעְתִּיק מִמֶּנּוּ בְּשָׁעָה שֶׁהוּא כּוֹתֵב. אֲבָל אִם לֹא נִתְכַּוֵּן לָצֵאת בִּקְרִיאָה זוֹ שֶׁכָּתַב לֹא יָצָא. שֶׁאֵינוֹ יוֹצֵא יְדֵי חוֹבָתוֹ אֶלָּא בִּקְרִיאָתָהּ מִסֵּפֶר שֶׁכֻּלָּהּ כְּתוּבָה בּוֹ בִּשְׁעַת קְרִיאָה:","הַקּוֹרֵא אֶת הַמְּגִלָּה וְטָעָה בִּקְרִיאָתָהּ וְקָרָא קְרִיאָה מְשֻׁבֶּשֶׁת יָצָא. לְפִי שֶׁאֵין מְדַקְדְּקִין בִּקְרִיאָתָהּ. קְרָאָהּ עוֹמֵד אוֹ יוֹשֵׁב יָצָא וַאֲפִלּוּ בְּצִבּוּר. אֲבָל לֹא יִקְרָא בְּצִבּוּר יוֹשֵׁב לְכַתְּחִלָּה מִפְּנֵי כְּבוֹד הַצִּבּוּר. קְרָאוּהָ שְׁנַיִם אֲפִלּוּ עֲשָׂרָה כְּאֶחָד יָצְאוּ הַקּוֹרְאִין וְהַשּׁוֹמְעִים מִן הַקּוֹרְאִין. וְקוֹרֵא אוֹתָהּ גָּדוֹל עִם הַקָּטָן וַאֲפִלּוּ בְּצִבּוּר:","אֵין קוֹרְאִין בְּצִבּוּר בִּמְגִלָּה הַכְּתוּבָה בֵּין הַכְּתוּבִים. וְאִם קָרָא לֹא יָצָא. אֶלָּא אִם כֵּן הָיְתָה יְתֵרָה עַל שְׁאָר הַיְרִיעוֹת אוֹ חֲסֵרָה כְּדֵי שֶׁיְּהֵא לָהּ הֶכֵּר. אֲבָל הַיָּחִיד קוֹרֵא בָּהּ וַאֲפִלּוּ אֵינָהּ חֲסֵרָה וְלֹא יְתֵרָה וְיוֹצֵא בָּהּ יְדֵי חוֹבָתוֹ:","אֵין כּוֹתְבִין הַמְּגִלָּה אֶלָּא בִּדְיוֹ עַל הַגְּוִיל אוֹ עַל הַקְּלָף כְּסֵפֶר תּוֹרָה. וְאִם כְּתָבָהּ בְּמֵי עַפְּצָא וְקַנְקַנְתּוֹם כְּשֵׁרָה. כְּתָבָהּ בִּשְׁאָר מִינֵי צִבְעוֹנִין פְּסוּלָה. וּצְרִיכָה שִׂרְטוּט כַּתּוֹרָה עַצְמָהּ. וְאֵין הָעוֹר שֶׁלָּהּ צָרִיךְ לְעַבֵּד לִשְׁמָהּ. הָיְתָה כְּתוּבָה עַל הַנְּיָר אוֹ עַל עוֹר שֶׁאֵינוֹ מְעֻבָּד אוֹ שֶׁכְּתָבָהּ עַכּוּ\"ם אוֹ אֶפִּיקוֹרוֹס פְּסוּלָה:","הָיוּ בָּהּ אוֹתִיּוֹת מְטֻשְׁטָשׁוֹת אוֹ מְקֹרָעוֹת. אִם רִשּׁוּמָן נִכָּר אֲפִלּוּ הָיוּ רֻבָּהּ כְּשֵׁרָה. וְאִם אֵין רִשּׁוּמָן נִכָּר אִם הָיָה רֻבָּהּ שָׁלֵם כְּשֵׁרָה. וְאִם לָאו פְּסוּלָה וְהַקּוֹרֵא בָּהּ לֹא יָצָא. הִשְׁמִיט בָּהּ הַסּוֹפֵר אוֹתִיּוֹת אוֹ פְּסוּקִים וּקְרָאָן הַקּוֹרֵא אֶת הַמְּגִלָּה עַל פֶּה יָצָא:","הַמְּגִלָּה צְרִיכָה שֶׁתְּהֵא תְּפוּרָה כֻּלָּהּ עַד שֶׁיִּהְיוּ כָּל עוֹרוֹתֶיהָ מְגִלָּה אַחַת. וְאֵינָהּ נִתְפֶּרֶת אֶלָּא בְּגִידִין כְּסֵפֶר תּוֹרָה. וְאִם תְּפָרָהּ שֶׁלֹּא בְּגִידִין פְּסוּלָה. וְאֵינוֹ צָרִיךְ לִתְפֹּר אֶת כָּל הַיְרִיעָה בְּגִידִין כְּסֵפֶר תּוֹרָה אֶלָּא אֲפִלּוּ תָּפַר בְּגִידִין שָׁלֹשׁ תְּפִירוֹת בִּקְצֵה הַיְרִיעָה וְשָׁלֹשׁ בְּאֶמְצָעָהּ וְשָׁלֹשׁ בַּקָּצֶה הַשֵּׁנִי כְּשֵׁרָה מִפְּנֵי שֶׁנִּקְרֵאת אִגֶּרֶת:","וְצָרִיךְ הַקּוֹרֵא לִקְרוֹת עֲשֶׂרֶת בְּנֵי הָמָן וַעֲשֶׂרֶת בִּנְשִׁימָה אַחַת כְּדֵי לְהוֹדִיעַ לְכָל הָעָם שֶׁכֻּלָּם נִתְלוּ וְנֶהֶרְגוּ כְּאֶחָד. וּמִנְהַג כָּל יִשְׂרָאֵל שֶׁהַקּוֹרֵא הַמְּגִלָּה קוֹרֵא וּפוֹשֵׁט כְּאִגֶּרֶת לְהַרְאוֹת הַנֵּס וּכְשֶׁיִּגְמֹר חוֹזֵר וְכוֹרְכָהּ כֻּלָּהּ וּמְבָרֵךְ:","שְׁנֵי הַיָּמִים הָאֵלּוּ שֶׁהֵן י\"ד וְט\"ו אֲסוּרִין בְּהֶסְפֵּד וְתַעֲנִית לְכָל אָדָם בְּכָל מָקוֹם. בֵּין לִבְנֵי כְּרַכִּין שֶׁהֵן עוֹשִׂין ט\"ו בִּלְבַד. בֵּין לִבְנֵי עֲיָרוֹת שֶׁהֵן עוֹשִׂין י\"ד בִּלְבַד. וּשְׁנֵי הַיָּמִים אֲסוּרִין בְּהֶסְפֵּד וְתַעֲנִית בַּאֲדָר הָרִאשׁוֹן וּבָאֲדָר הַשֵּׁנִי. אַנְשֵׁי כְּפָרִים שֶׁהִקְדִּימוּ וְקָרְאוּ בְּשֵׁנִי אוֹ בַּחֲמִישִׁי הַסָּמוּךְ לְפוּרִים מֻתָּרִים בְּהֶסְפֵּד וְתַעֲנִית בְּיוֹם קְרִיאָתָהּ וַאֲסוּרִין בְּהֶסְפֵּד וְתַעֲנִית בִּשְׁנֵי הַיָּמִים הָאֵלּוּ אַף עַל פִּי שֶׁאֵין קוֹרְאִין בָּהֶן:","מִצְוַת יוֹם י\"ד לִבְנֵי כְּפָרִים וַעֲיָרוֹת וְיוֹם ט\"ו לִבְנֵי כְּרַכִּים לִהְיוֹת יוֹם שִׂמְחָה וּמִשְׁתֶּה וּמִשְׁלוֹחַ מָנוֹת לְרֵעִים וּמַתָּנוֹת לָאֶבְיוֹנִים. וּמֻתָּר בַּעֲשִׂיַּת מְלָאכָה, וְאַף עַל פִּי כֵן אֵין רָאוּי לַעֲשׂוֹת בּוֹ מְלָאכָה. אָמְרוּ חֲכָמִים כָּל הָעוֹשֶׂה מְלָאכָה בְּיוֹם פּוּרִים אֵינוֹ רוֹאֶה סִימַן בְּרָכָה לְעוֹלָם. בְּנֵי כְּפָרִים שֶׁקָּדְמוּ וְקָרְאוּ בְּשֵׁנִי אוֹ בַּחֲמִישִׁי אִם חִלְּקוּ מָעוֹת לָאֶבְיוֹנִים בְּיוֹם קְרִיאָתָן יָצְאוּ. אֲבָל הַשִּׂמְחָה וְהַמִּשְׁתֶּה אֵין עוֹשִׂין אוֹתָם אֶלָּא בְּיוֹם י\"ד. וְאִם הִקְדִּימוּ לֹא יָצְאוּ. וּסְעֻדַּת פּוּרִים שֶׁעֲשָׂאָהּ בַּלַּיְלָה לֹא יָצָא יְדֵי חוֹבָתוֹ:","כֵּיצַד חוֹבַת סְעֻדָּה זוֹ. שֶׁיֹּאכַל בָּשָׂר וִיתַקֵּן סְעֻדָּה נָאָה כְּפִי אֲשֶׁר תִּמְצָא יָדוֹ. וְשׁוֹתֶה יַיִן עַד שֶׁיִּשְׁתַּכֵּר וְיֵרָדֵם בְּשִׁכְרוּתוֹ. וְכֵן חַיָּב אָדָם לִשְׁלֹחַ שְׁתֵּי מְנוֹת בָּשָׂר אוֹ שְׁנֵי מִינֵי תַּבְשִׁיל אוֹ שְׁנֵי מִינֵי אֳכָלִין לַחֲבֵרוֹ שֶׁנֶּאֱמַר (אסתר ט יט) \"וּמִשְׁלוֹחַ מָנוֹת אִישׁ לְרֵעֵהוּ\", שְׁתֵּי מָנוֹת לְאִישׁ אֶחָד. וְכָל הַמַּרְבֶּה לִשְׁלֹחַ לְרֵעִים מְשֻׁבָּח. וְאִם אֵין לוֹ מַחֲלִיף עִם חֲבֵרוֹ זֶה שׁוֹלֵחַ לְזֶה סְעֻדָּתוֹ וְזֶה שׁוֹלֵחַ לְזֶה סְעֻדָּתוֹ כְּדֵי לְקַיֵּם וּמִשְׁלוֹחַ מָנוֹת אִישׁ לְרֵעֵהוּ:","וְחַיָּב לְחַלֵּק לָעֲנִיִּים בְּיוֹם הַפּוּרִים. אֵין פּוֹחֲתִין מִשְּׁנֵי עֲנִיִּים נוֹתֵן לְכָל אֶחָד מַתָּנָה אַחַת אוֹ מָעוֹת אוֹ מִינֵי תַּבְשִׁיל אוֹ מִינֵי אֳכָלִין שֶׁנֶּאֱמַר (אסתר ט כב) \"וּמַתָּנוֹת לָאֶבְיוֹנִים\", שְׁתֵּי מַתָּנוֹת לִשְׁנֵי עֲנִיִּים. וְאֵין מְדַקְדְּקִין בִּמְעוֹת פּוּרִים אֶלָּא כָּל הַפּוֹשֵׁט יָדוֹ לִטּל נוֹתְנִין לוֹ. וְאֵין מְשַׁנִּין מָעוֹת פּוּרִים לִצְדָקָה אַחֶרֶת:","מוּטָב לָאָדָם לְהַרְבּוֹת בְּמַתְּנוֹת אֶבְיוֹנִים מִלְּהַרְבּוֹת בִּסְעֻדָּתוֹ וּבְשִׁלּוּחַ מָנוֹת לְרֵעָיו. שֶׁאֵין שָׁם שִׂמְחָה גְּדוֹלָה וּמְפֹאָרָה אֶלָּא לְשַׂמֵּחַ לֵב עֲנִיִּים וִיתוֹמִים וְאַלְמָנוֹת וְגֵרִים. שֶׁהַמְשַׂמֵּחַ לֵב הָאֻמְלָלִים הָאֵלּוּ דּוֹמֶה לַשְּׁכִינָה שֶׁנֶּאֱמַר (ישעיה נז טו) \"לְהַחֲיוֹת רוּחַ שְׁפָלִים וּלְהַחֲיוֹת לֵב נִדְכָּאִים\":","כָּל סִפְרֵי הַנְּבִיאִים וְכָל הַכְּתוּבִים עֲתִידִין לִבָּטֵל לִימוֹת הַמָּשִׁיחַ חוּץ מִמְּגִלַּת אֶסְתֵּר וַהֲרֵי הִיא קַיֶּמֶת כַּחֲמִשָּׁה חֻמְּשֵׁי תּוֹרָה וְכַהֲלָכוֹת שֶׁל תּוֹרָה שֶׁבְּעַל פֶּה שֶׁאֵינָן בְּטֵלִין לְעוֹלָם. וְאַף עַל פִּי שֶׁכָּל זִכְרוֹן הַצָּרוֹת יְבֻטַּל שֶׁנֶּאֱמַר (ישעיה סה טז) \"כִּי נִשְׁכְּחוּ הַצָּרוֹת הָרִאשׁוֹנוֹת וְכִי נִסְתְּרוּ מֵעֵינִי\". יְמֵי הַפּוּרִים לֹא יִבָּטְלוּ שֶׁנֶּאֱמַר (אסתר ט כח) \"וִימֵי הַפּוּרִים הָאֵלֶּה לֹא יַעַבְרוּ מִתּוֹךְ הַיְּהוּדִים וְזִכְרָם לֹא יָסוּף מִזַּרְעָם\":"],"Mishneh Torah, Second Tithes and Fourth Year's Fruit 8":["הַלוֹקֵחַ בְּהֵמָה לְזִבְחֵי שְׁלָמִים וְחַיָּה לִבְשַׂר תַּאֲוָה מִמִּי שֶׁאֵינוֹ תַּגָּר וְאֵינוֹ מְדַקְדֵּק יָצָא הָעוֹר לְחֻלִּין. אֲפִלּוּ הָיוּ דְּמֵי הָעוֹר מְרֻבִּין עַל דְּמֵי הַבָּשָׂר. אֲבָל הַלּוֹקֵחַ מִן הַתַּגָּר לֹא יָצָא הָעוֹר לְחֻלִּין:","וְכֵן הַלּוֹקֵחַ כַּדֵּי יַיִן סְתוּמוֹת מִמָּקוֹם שֶׁדַּרְכָּם לְהִמָּכֵר סְתוּמוֹת מִמִּי שֶׁאֵינוֹ תַּגָּר יָצָא הַקַּנְקַן לְחֻלִּין. לְפִיכָךְ צָרִיךְ הַמּוֹכֵר לִפְתֹּחַ רָאשֵׁי הַכַּדִּים כְּדֵי שֶׁלֹּא יֵצֵא הַקַּנְקַן לְחֻלִּין. וְאִם רָצָה לְהַחֲמִיר עַל עַצְמוֹ וְלִמְכֹּר בְּמִדָּה יָצָא הַקַּנְקַן לְחֻלִּין:","לְקָחָן פְּתוּחוֹת אוֹ סְתוּמוֹת בְּמָקוֹם שֶׁדַּרְכָּן לְהִמָּכֵר פְּתוּחוֹת. אוֹ שֶׁלָּקַח מִן הַתַּגָּר שֶׁמְּדַקְדֵּק בִּמְכִירָתוֹ לֹא יָצָא הַקַּנְקַן לְחֻלִּין. לָקַח סַלֵּי תְּאֵנִים וַעֲנָבִים עִם הַכְּלִי לֹא יָצְאוּ דְּמֵי הַכְּלִי לְחֻלִּין:","לָקַח אֱגוֹזִים וּשְׁקֵדִים וְכַיּוֹצֵא בָּהֶן יָצְאוּ קְלִפָּתָן לְחֻלִּין. לָקַח חוֹתָל שֶׁל תְּמָרִים יָצָא הַחוֹתָל לְחֻלִּין. קֻפָּה שֶׁל תְּמָרִים אִם דְּרוּסוֹת יָצְאוּ הַקֻּפּוֹת לְחֻלִּין. וְאִם לָאו לֹא יָצְאוּ לְחֻלִּין:","מִי שֶׁהָיָה לוֹ יַיִן שֶׁל מַעֲשֵׂר שֵׁנִי וְהִשְׁאִיל קַנְקַנָּיו לְאוֹתוֹ מַעֲשֵׂר. אַף עַל פִּי שֶׁסָּתַם אֶת פִּיהֶם לֹא קָנָה מַעֲשֵׂר אֶת הַקַּנְקַנִּים. כִּנֵּס הַיַּיִן לְתוֹכוֹ סְתָם אִם קָרָא שֵׁם וְעָשָׂהוּ מַעֲשֵׂר עַד שֶׁלֹּא סָתַם אֶת פִּיהֶם לֹא קָנָה מַעֲשֵׂר אֶת הַקַּנְקַנִּים. וְאִם מִשֶּׁסָּתַם פִּיהֶן קָרָא שֵׁם וְעָשָׂהוּ מַעֲשֵׂר קָנָה מַעֲשֵׂר אֶת הַקַּנְקַן. הִפְקִיד לְתוֹךְ הַקַּנְקַן רְבִיעִית חֻלִּין אוֹ שֶׁכָּנַס לְתוֹכָן שֶׁמֶן אוֹ חֹמֶץ אוֹ צִיר אוֹ דְּבַשׁ שֶׁל מַעֲשֵׂר שֵׁנִי סְתָם בֵּין מִשֶּׁסָּתַם בֵּין עַד שֶׁלֹּא סָתַם לֹא קָנָה מַעֲשֵׂר אֶת הַקַּנְקַנִּים:","צְבִי שֶׁלְּקָחוֹ בְּכֶסֶף מַעֲשֵׂר וּמֵת יִקָּבֵר בְּעוֹרוֹ. לְקָחוֹ חַי וּשְׁחָטוֹ וְנִטְמָא הֲרֵי זֶה יִפָּדֶה כִּשְׁאָר פֵּרוֹת שֶׁנִּטְמְאוּ. הַמַּנִּיחַ דִּינַר מַעֲשֵׂר שֵׁנִי לִהְיוֹת אוֹכֵל כְּנֶגְדּוֹ עַד שֶׁיֵּצֵא לְחֻלִּין וְהָיָה הַדִּינָר יוֹצֵא בְּעֶשְׂרִים מָעָה. אָכַל עָלָיו בְּעֶשֶׂר מָעָה וְהֻזְּלוּ הַמָּעוֹת לְאַחַר זְמַן וַהֲרֵי הַדִּינָר יוֹצֵא בְּאַרְבָּעִים מָעָה צָרִיךְ לֶאֱכל עָלָיו בְּעֶשְׂרִים מָעָה וְאַחַר כָּךְ יֵצֵא לְחֻלִּין. הוּקְרוּ הַמָּעוֹת וַהֲרֵי הַדִּינָר יוֹצֵא בְּעֶשֶׂר מָעִין אוֹכֵל עָלָיו בְּחָמֵשׁ מָעִין וְאַחַר כָּךְ יֵצֵא לְחֻלִּין:","הַלּוֹקֵחַ פֵּרוֹת בְּסֶלַע שֶׁל כֶּסֶף מַעֲשֵׂר וּמָשַׁךְ הַפֵּרוֹת וְלֹא הִסְפִּיק לִתֵּן הַסֶּלַע עַד שֶׁהוּקְרוּ הַפֵּרוֹת וְעָמְדוּ בִּשְׁתַּיִם. הֲרֵי זֶה מַפְרִישׁ עֲלֵיהֶן סֶלַע בִּלְבַד שֶׁנֶּאֱמַר וְנָתַן (אֶת) הַכֶּסֶף וְקָם לוֹ. בִּנְתִינַת הַכֶּסֶף קוֹנֶה. וְהַשָּׂכָר לַמַעֲשֵׂר:","מָשַׁךְ פֵּרוֹת בִּשְׁתֵּי סְלָעִים וְלֹא הִסְפִּיק לִתֵּן הַמָּעוֹת עַד שֶׁהוּזְלוּ הַפֵּרוֹת וְעָמְדוּ בְּסֶלַע אֵינוֹ מַפְרִישׁ עֲלֵיהֶן מִמְּעוֹת מַעֲשֵׂר שֵׁנִי אֶלָּא סֶלַע אַחַת. וּמוֹסִיף עָלֶיהָ סֶלַע שְׁנִיָּה מִן הַחֻלִּין וְנוֹתֵן לַמּוֹכֵר. וְאִם הָיָה הַמּוֹכֵר עַם הָאָרֶץ הֲרֵי זֶה מֻתָּר לִתֵּן סֶלַע שְׁנִיָּה מִמְּעוֹת מַעֲשֵׂר שֵׁנִי שֶׁל דְּמַאי. נָתַן לוֹ סֶלַע שֶׁל מַעֲשֵׂר וְלֹא הִסְפִּיק לִמְשֹׁךְ הַפֵּרוֹת עַד שֶׁעָמְדוּ בִּשְׁתַּיִם. מַה שֶּׁפָּדָה פָּדָה וְהַדִּין בֵּינֵיהֶן:","נָתַן לוֹ סְלָעִים שְׁתַּיִם שֶׁל מַעֲשֵׂר וְלֹא הִסְפִּיק לִמְשֹׁךְ הַפֵּרוֹת עַד שֶׁחָזְרוּ לִהְיוֹת בְּסֶלַע מַה שֶּׁפָּדָה פָּדָה. וּמִדַּת הַדִּין בֵּינֵיהֶם שֶׁהַמַּעֲשֵׂר שֵׁנִי פְּדִיָּתוֹ הִיא מְשִׁיכָתוֹ:","מִי שֶׁהָיוּ לוֹ פֵּרוֹת חֻלִּין בִּירוּשָׁלַיִם וְהָיוּ לוֹ מְעוֹת מַעֲשֵׂר שֵׁנִי חוּץ לִירוּשָׁלַיִם אוֹמֵר הֲרֵי הַמָּעוֹת הָהֵם מְחֻלָּלִין עַל הַפֵּרוֹת הָאֵלּוּ וְיֹאכְלֵם שָׁם בְּטָהֳרָה וְיֵצְאוּ אוֹתָן הַמָּעוֹת לְחֻלִּין בִּמְקוֹמָן:","הָיוּ לוֹ מְעוֹת מַעֲשֵׂר שֵׁנִי בִּירוּשָׁלַיִם וְיֵשׁ לוֹ פֵּרוֹת חוּץ לִירוּשָׁלַיִם אוֹמֵר הֲרֵי הַמָּעוֹת הָאֵלּוּ מְחֻלָּלִין עַל פֵּרוֹת הָהֵם וְיֵצְאוּ הַמָּעוֹת לְחֻלִּין וְיַעֲלוּ הַפֵּרוֹת וְיֵאָכְלוּ בִּירוּשָׁלַיִם. שֶׁאֵינוֹ צָרִיךְ לִהְיוֹת הַמָּעוֹת וְהַפֵּרוֹת בְּמָקוֹם אֶחָד בִּשְׁעַת הַחִלּוּל:","מִי שֶׁהָיוּ לוֹ מְעוֹת מַעֲשֵׂר בִּירוּשָׁלַיִם וְצָרִיךְ לָהֶם. וְיֵשׁ לַחֲבֵרוֹ פֵּרוֹת חֻלִּין שֶׁרוֹצֶה לְאָכְלָן. אוֹמֵר לַחֲבֵרוֹ הֲרֵי הַמָּעוֹת הָאֵלּוּ מְחֻלָּלִין עַל פֵּרוֹתֶיךָ וְנִמְצְאוּ אוֹתָם הַפֵּרוֹת לְקוּחוֹת בְּכֶסֶף מַעֲשֵׂר וְיֹאכַל אוֹתָם חֲבֵרוֹ בְּטָהֳרָה. וְלֹא הִפְסִיד כְּלוּם. וְיָצְאוּ הַמָּעוֹת לְחֻלִּין:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה חֲבֵרוֹ בַּעַל הַפֵּרוֹת חָבֵר. שֶׁאֵין מוֹסְרִין פֵּרוֹת שֶׁל מַעֲשֵׂר שֵׁנִי שֶׁל וַדַּאי אֶלָּא לְחָבֵר. לְפִיכָךְ אִם הָיוּ הַמָּעוֹת שֶׁל דְּמַאי אוֹמֵר כֵּן אַף לְעַם הָאָרֶץ. וּמֻתָּר לְחַלֵּל מַעֲשֵׂר שֵׁנִי עַל פֵּרוֹת עַם הָאָרֶץ וְעַל מְעוֹתָיו וְאֵין חוֹשְׁשִׁין לָהֶם שֶׁמָּא שֶׁל מַעֲשֵׂר שֵׁנִי הֵם:","הַמַּנִּיחַ דִּינָר שֶׁל מַעֲשֵׂר לִהְיוֹת אוֹכֵל כְּנֶגְדּוֹ וְהוֹלֵךְ כֵּיוָן שֶׁאָכַל עָלָיו עַד שֶׁלֹּא נִשְׁאַר מִמֶּנּוּ (אֶלָּא) פָּחוֹת מִפְּרוּטָה יָצָא לְחֻלִּין. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁל דְּמַאי אֲבָל בְּשֶׁל וַדַּאי לֹא יֵצֵא לְחֻלִּין עַד שֶׁיִּשָּׁאֵר מִמֶּנּוּ פָּחוֹת מִשְּׁוֵה פְּרוּטָה אַחַר שֶׁמּוֹסִיפִין אֶת הַחֹמֶשׁ. כְּגוֹן שֶׁנִּשְׁאַר מִמֶּנּוּ פָּחוֹת מֵאַרְבָּעָה חֻמְשֵׁי שְׁוֵה פְּרוּטָה:","טְמֵאִין וּטְהוֹרִין שֶׁהָיוּ אוֹכְלִין אוֹ שׁוֹתִין כְּאֶחָד בִּירוּשָׁלַיִם. וְרָצוּ הַטְּהוֹרִין לִהְיוֹת אוֹכְלִין מַעֲשֵׂר שֵׁנִי שֶׁלָּהֶם. מַנִּיחִין סֶלַע שֶׁל מַעֲשֵׂר שֵׁנִי וְאוֹמֵר. כָּל שֶׁהַטְּהוֹרִים אוֹכְלִים וְשׁוֹתִין סֶלַע זוֹ מְחֻלָּל עָלָיו. וְתֵצֵא הַסֶּלַע לְחֻלִּין שֶׁהֲרֵי אָכְלוּ וְשָׁתוּ בְּשָׁוְיָהּ בְּטָהֳרָה. וּבִלְבַד שֶׁלֹּא יִגְּעוּ הַטְּמֵאִים בַּמַאֲכָל שֶׁלֹּא יְטַמְּאוּהוּ:"],"Mishneh Torah, Shofar, Sukkah and Lulav 2":["הַכּל חַיָּבִין לִשְׁמֹעַ קוֹל שׁוֹפָר כֹּהֲנִים לְוִיִּים וְיִשְׂרְאֵלִים וְגֵרִים וַעֲבָדִים מְשֻׁחְרָרִים. אֲבָל נָשִׁים וַעֲבָדִים וּקְטַנִּים פְּטוּרִין. מִי שֶׁחֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין וְטֻמְטוּם וְאַנְדְּרוֹגִינוּס חַיָּבִין:","כָּל מִי שֶׁאֵינוֹ חַיָּב בַּדָּבָר אֵינוֹ מוֹצִיא אֶת הַחַיָּב יְדֵי חוֹבָתוֹ. לְפִיכָךְ אִשָּׁה אוֹ קָטָן שֶׁתָּקְעוּ בַּשּׁוֹפָר הַשּׁוֹמֵעַ מֵהֶן לֹא יָצָא. אַנְדְּרוֹגִינוּס מוֹצִיא אֶת מִינוֹ וְאֵינוֹ מוֹצִיא אֶת שֶׁאֵינוֹ מִינוֹ. טֻמְטוּם אֵינוֹ מוֹצִיא לֹא אֶת מִינוֹ וְלֹא שֶׁאֵינוֹ מִינוֹ. שֶׁהַטֻּמְטוּם שֶׁנִּקְרַע אֶפְשָׁר שֶׁיִּמָּצֵא זָכָר וְאֶפְשָׁר שֶׁיִּמָּצֵא נְקֵבָה:","וְכֵן מִי שֶׁחֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין אֵינוֹ מוֹצִיא אֲפִלּוּ עַצְמוֹ שֶׁאֵין צַד עַבְדוּת שֶׁבּוֹ מוֹצִיא צַד חֵרוּת שֶׁבּוֹ. אֶלָּא כֵּיצַד יֵצֵא יְדֵי חוֹבָתוֹ. שֶׁיִּשְׁמַע מִבֶּן חוֹרִין שֶׁיִּתְקַע לוֹ:","הַמִּתְעַסֵּק בִּתְקִיעַת שׁוֹפָר לְהִתְלַמֵּד לֹא יָצָא יְדֵי חוֹבָתוֹ. וְכֵן הַשּׁוֹמֵעַ מִן הַמִּתְעַסֵּק לֹא יָצָא. נִתְכַּוֵּן שׁוֹמֵעַ לָצֵאת יְדֵי חוֹבָתוֹ וְלֹא נִתְכַּוֵּן הַתּוֹקֵעַ לְהוֹצִיאוֹ אוֹ שֶׁנִּתְכַּוֵּן הַתּוֹקֵעַ לְהוֹצִיאוֹ וְלֹא נִתְכַּוֵּן הַשּׁוֹמֵעַ לָצֵאת לֹא יָצָא יְדֵי חוֹבָתוֹ. עַד שֶׁיִּתְכַּוֵּן שׁוֹמֵעַ וּמַשְׁמִיעַ:","מִי שֶׁתָּקַע וְנִתְכַּוֵּן לְהוֹצִיא כָּל הַשּׁוֹמֵעַ תְּקִיעָתוֹ וְשָׁמַע הַשּׁוֹמֵעַ וְנִתְכַּוֵּן לָצֵאת יְדֵי חוֹבָתוֹ אַף עַל פִּי שֶׁאֵין הַתּוֹקֵעַ מִתְכַּוֵּן לְזֶה פְּלוֹנִי שֶׁשָּׁמַע תְּקִיעָתוֹ וְאֵינוֹ יוֹדְעוֹ יָצָא. שֶׁהֲרֵי נִתְכַּוֵּן לְכָל מִי שֶׁיִּשְׁמָעֶנּוּ. לְפִיכָךְ מִי שֶׁהָיָה מְהַלֵּךְ בַּדֶּרֶךְ אוֹ יוֹשֵׁב בְּתוֹךְ בֵּיתוֹ וְשָׁמַע הַתְּקִיעוֹת מִשְּׁלִיחַ צִבּוּר יָצָא אִם נִתְכַּוֵּן לָצֵאת. שֶׁהֲרֵי שְׁלִיחַ צִבּוּר מִתְכַּוֵּן לְהוֹצִיא אֶת הָרַבִּים יְדֵי חוֹבָתָן:","יוֹם טוֹב שֶׁל רֹאשׁ הַשָּׁנָה שֶׁחָל לִהְיוֹת בְּשַׁבָּת אֵין תּוֹקְעִין בַּשּׁוֹפָר בְּכָל מָקוֹם. אַף עַל פִּי שֶׁהַתְּקִיעָה מִשּׁוּם שְׁבוּת וּמִן הַדִּין הָיָה שֶׁתּוֹקְעִין יָבוֹא עֲשֵׂה שֶׁל תּוֹרָה וְיִדְחֶה שְׁבוּת שֶׁל דִּבְרֵיהֶם. וְלָמָּה אֵין תּוֹקְעִין גְּזֵרָה שֶׁמָּא יִטְּלֶנּוּ בְּיָדוֹ וְיוֹלִיכֶנּוּ לְמִי שֶׁיִּתְקַע לוֹ וְיַעֲבִירֶנּוּ אַרְבַּע אַמּוֹת בִּרְשׁוּת הָרַבִּים. אוֹ יוֹצִיאוֹ מֵרְשׁוּת לִרְשׁוּת וְיָבוֹא לִידֵי אִסּוּר סְקִילָה. שֶׁהַכּל חַיָּבִים בִּתְקִיעָה וְאֵין הַכּל בְּקִיאִין לִתְקֹעַ:","הַתִּינוֹקוֹת שֶׁלֹּא הִגִּיעוּ לְחִנּוּךְ אֵין מְעַכְּבִין אוֹתָן מִלִּתְקֹעַ בְּשַׁבָּת שֶׁאֵינָהּ יוֹם טוֹב שֶׁל רֹאשׁ הַשָּׁנָה כְּדֵי שֶׁיִּלְמְדוּ. וּמֻתָּר לְגָדוֹל שֶׁיִּתְעַסֵּק עִמָּהֶן כְּדֵי לְלַמְּדָן בְּיוֹם טוֹב. בֵּין קָטָן שֶׁהִגִּיעַ לְחִנּוּךְ בֵּין קָטָן שֶׁלֹּא הִגִּיעַ לְחִנּוּךְ. שֶׁהַתְּקִיעָה אֵינָהּ אֲסוּרָה אֶלָּא מִשּׁוּם שְׁבוּת:","כְּשֶׁגָּזְרוּ שֶׁלֹּא לִתְקֹעַ בְּשַׁבָּת לֹא גָּזְרוּ אֶלָּא בְּמָקוֹם שֶׁאֵין בּוֹ בֵּית דִּין. אֲבָל בִּזְמַן שֶׁהָיָה הַמִּקְדָּשׁ קַיָּם וְהָיָה בֵּית דִּין הַגָּדוֹל בִּירוּשָׁלַיִם הָיוּ הַכּל תּוֹקְעִין בִּירוּשָׁלַיִם בְּשַׁבָּת כָּל זְמַן שֶׁבֵּית דִּין יוֹשְׁבִין. וְלֹא אַנְשֵׁי יְרוּשָׁלַיִם בִּלְבַד אֶלָּא כָּל עִיר שֶׁהָיְתָה בְּתוֹךְ תְּחוּם יְרוּשָׁלַיִם וְהָיְתָה רוֹאָה יְרוּשָׁלַיִם לֹא שֶׁתִּהְיֶה בְּתוֹךְ הַנַּחַל. וְהָיְתָה שׁוֹמַעַת קוֹל תְּקִיעַת יְרוּשָׁלַיִם לֹא שֶׁתִּהְיֶה בְּרֹאשׁ הָהָר. וְהָיְתָה יְכוֹלָה לָבוֹא בִּירוּשָׁלַיִם לֹא שֶׁיִּהְיֶה נָהָר מַפְסִיק בֵּינֵיהֶם. אַנְשֵׁי אוֹתָהּ הָעִיר הָיוּ תּוֹקְעִים בְּשַׁבָּת כִּירוּשָׁלַיִם. אֲבָל בִּשְׁאָר עָרֵי יִשְׂרָאֵל לֹא הָיוּ תּוֹקְעִין:","וּבַזְּמַן הַזֶּה שֶׁחָרַב הַמִּקְדָּשׁ כָּל מָקוֹם שֶׁיֵּשׁ בּוֹ בֵּית דִּין קָבוּעַ וְהוּא שֶׁיִּהְיֶה סָמוּךְ בְּאֶרֶץ יִשְׂרָאֵל תּוֹקְעִין בּוֹ בְּשַׁבָּת. וְאֵין תּוֹקְעִין בְּשַׁבָּת אֶלָּא בְּבֵית דִּין שֶׁקִּדְּשׁוּ אֶת הַחֹדֶשׁ אֲבָל שְׁאָר בָּתֵּי דִּינִין אֵין תּוֹקְעִין בָּהֶן אַף עַל פִּי שֶׁהֵן סְמוּכִין. וְאֵין תּוֹקְעִין אֶלָּא בִּפְנֵי בֵּית דִּין גָּדוֹל בִּלְבַד כָּל זְמַן שֶׁהֵן יוֹשְׁבִין וַאֲפִלּוּ נִנְעֲרוּ לַעֲמֹד וְלֹא עָמְדוּ תּוֹקְעִין בִּפְנֵיהֶם. אֲבָל חוּץ לְבֵית דִּין אֵין תּוֹקְעִין. וְלָמָּה תּוֹקְעִין בִּפְנֵי בֵּית דִּין מִפְּנֵי שֶׁבֵּית דִּין זְרִיזִין הֵן וְלֹא יָבוֹאוּ הַתּוֹקְעִין לְהַעֲבִיר הַשּׁוֹפָר בִּפְנֵיהֶם בִּרְשׁוּת הָרַבִּים שֶׁבֵּית דִּין מַזְהִירִין אֶת הָעָם וּמוֹדִיעִין אוֹתָן:","בַּזְּמַן הַזֶּה שֶׁאָנוּ עוֹשִׂין שְׁנֵי יָמִים בַּגָּלוּת כְּדֶרֶךְ שֶׁתּוֹקְעִין בְּרִאשׁוֹן תּוֹקְעִין בְּשֵׁנִי. וְאִם חָל יוֹם רִאשׁוֹן לִהְיוֹת בְּשַׁבָּת וְלֹא הָיָה בַּמָּקוֹם בֵּית דִּין הָרְאוּיִין לִתְקֹעַ תּוֹקְעִין בְּשֵׁנִי בִּלְבַד:"],"Mishneh Torah, Slaves 6":["הַכּוֹתֵב גֵּט שִׁחְרוּר לְעַבְדּוֹ וְזִכָּה לוֹ בּוֹ עַל יְדֵי אַחֵר וְאָמַר זְכֵה בְּגֵט זֶה לִפְלוֹנִי עַבְדִּי יָצָא לְחֵרוּת אַף עַל פִּי שֶׁלֹּא הִגִּיעַ גֵּט לְיָדוֹ שֶׁזָּכִין לְאָדָם שֶׁלֹּא בְּפָנָיו. אֲבָל אִם אָמַר תְּנוּ גֵּט זֶה לְעַבְדִּי אֵינוֹ יָכוֹל לַחְזֹר בּוֹ וְלֹא יֵצֵא הָעֶבֶד לְחֵרוּת עַד שֶׁיַּגִּיעַ הַגֵּט לְיָדוֹ. לְפִיכָךְ הָאוֹמֵר תְּנוּ גֵּט זֶה לְעַבְדִּי וּמֵת לֹא יִתְּנוּ לְאַחַר מִיתָה:","הַכּוֹתֵב בִּשְׁטָר עָשִׂיתִי פְּלוֹנִי עַבְדִּי בֶּן חוֹרִין אוֹ נַעֲשָׂה פְּלוֹנִי עַבְדִּי בֶּן חוֹרִין אוֹ הֲרֵי הוּא בֶּן חוֹרִין הֲרֵי זֶה יֵצֵא לְחֵרוּת. כָּתַב בַּשְּׁטָר אֶעֱשֶׂנּוּ בֶּן חוֹרִין לֹא יֵצֵא לְחֵרוּת:","הָאוֹמֵר עָשִׂיתִי פְּלוֹנִי עַבְדִּי בֶּן חוֹרִין וְהוּא אוֹמֵר לֹא עֲשָׂאַנִי חוֹשְׁשִׁין שֶׁמָּא זִכָּה לוֹ עַל יְדֵי אַחֵר. אָמַר כָּתַבְתִּי גֵּט שִׁחְרוּר וְנָתַתִּי לוֹ וְהוּא אָמַר לֹא כָּתַב וְלֹא נָתַן הוֹדָאַת בַּעַל דִּין כְּמֵאָה עֵדִים וַהֲרֵי זֶה עֶבֶד עַד שֶׁיְּשַׁחְרְרֵנוּ בְּפָנֵינוּ:","מִי שֶׁצִּוָּה בִּשְׁעַת מִיתָתוֹ פְּלוֹנִית שִׁפְחָתִי אַל יִשְׁתַּעְבְּדוּ בָּהּ יוֹרְשַׁי הֲרֵי זוֹ שִׁפְחָה כְּשֶׁהָיְתָה וְאָסוּר לַיּוֹרְשִׁים לְהִשְׁתַּעְבֵּד בָּהּ מִפְּנֵי שֶׁמִּצְוָה לְקַיֵּם דִּבְרֵי הַמֵּת. וְכֵן אִם אָמַר עֲשׂוּ לָהּ קוֹרַת רוּחַ כּוֹפִין אֶת הַיּוֹרְשִׁין וְאֵין מִשְׁתַּעְבְּדִין בָּהּ אֶלָּא בִּמְלָאכָה שֶׁהִיא רוֹצָה בָּהּ. צִוָּה וְאָמַר שַׁחְרְרוּהָ כּוֹפִין אֶת הַיּוֹרְשִׁין לְשַׁחְרֵר אוֹתָהּ:","בְּשִׁשָּׁה דְּבָרִים שָׁוִין שִׁחְרוּרֵי עֲבָדִים לְגִטֵּי נָשִׁים וּבִשְׁאָר דְּבָרִים הֲרֵי הֵן כִּשְׁאָר כָּל הַשְּׁטָרוֹת. וְאֵלּוּ הֵן הַשִּׁשָּׁה. פְּסוּלִים בְּעַרְכָּאוֹת שֶׁל עַכּוּ\"ם. וּכְשֵׁרִין בְּעֵד כּוּתִי. וּצְרִיכִין כְּתִיבָה לְשֵׁם הַמְּשֻׁחְרָר עַצְמוֹ. וְאֵין נִכְתָּבִין בִּמְחֻבָּר. וְאֵין חוֹתְמִין עֵדֵיהֶם אֶלָּא זֶה בִּפְנֵי זֶה. אֶחָד גִּטֵּי נָשִׁים וְאֶחָד שִׁחְרוּרֵי עֲבָדִים שָׁוִין לַמּוֹלִיךְ וְלַמֵּבִיא. כֵּיצַד. כָּל הַשְּׁטָרוֹת הָעוֹלִים בְּעַרְכָּאוֹת שֶׁל עַכּוּ\"ם כְּשֵׁרִים בְּכָל הַתְּנָאִים שֶׁאָנוּ מְבָאֲרִים בְּהִלְכוֹת הַלְוָאָה חוּץ מִגִּטֵּי נָשִׁים וְשִׁחְרוּרֵי עֲבָדִים:","כָּל שְׁטָר שֶׁיֵּשׁ עָלָיו אֲפִלּוּ עֵד אֶחָד כּוּתִי פָּסוּל חוּץ מִגִּטֵּי נָשִׁים וְשִׁחְרוּרֵי עֲבָדִים שֶׁהֵן כְּשֵׁרִין בְּעֵד אֶחָד יִשְׂרָאֵל וְעֵד אֶחָד כּוּתִי וְהוּא שֶׁיִּהְיֶה כּוּתִי חָבֵר. וּבַזְּמַן הַזֶּה שֶׁהַכּוּתִים כְּעַכּוּ\"ם לְכָל דִּבְרֵיהֶם אָנוּ לְמֵדִין מֵהֶן לִצְדוֹקִין שֶׁהַצְּדוֹקִין בַּזְּמַן הַזֶּה כְּמוֹ כּוּתִי בְּאוֹתוֹ הַזְּמַן קֹדֶם שֶׁגָּזְרוּ עֲלֵיהֶם שֶׁיִּהְיוּ כְּעַכּוּ\"ם לְכָל דִּבְרֵיהֶם. בְּגֵט אִשָּׁה הוּא אוֹמֵר (דברים כד א) \"וְכָתַב לָהּ\" לִשְׁמָהּ וּבְגֵט שִׁחְרוּר הוּא אוֹמֵר (ויקרא יט כ) \"אוֹ חֻפְשָׁה לֹא נִתַּן לָהּ\", עַד שֶׁיִּכְתֹּב לִשְׁמָהּ. בְּגֵט אִשָּׁה הוּא אוֹמֵר וְכָתַב וְנָתַן מִי שֶׁאֵינוֹ מְחֻסָּר אֶלָּא נְתִינָה יָצָא הַכּוֹתֵב בִּמְחֻבָּר וְאַחַר כָּךְ קִצֵּץ שֶׁהֲרֵי מְחֻסַּר קְצִיצָה וּנְתִינָה וּבְגֵט שִׁחְרוּר הוּא אוֹמֵר (וְנָתַן לָהּ) לֹא יִהְיֶה מְחֻסָּר אֶלָּא נְתִינָה. אֶחָד גִּטֵּי נָשִׁים וְשִׁחְרוּרֵי עֲבָדִים אֵינָן חוֹתְמִין עֵדֵיהֶם אֶלָּא זֶה בִּפְנֵי זֶה. וּכְבָר בֵּאַרְנוּ טַעַם הַדָּבָר בְּהִלְכוֹת גֵּרוּשִׁין:","וְכֵיצַד שָׁוִין בְּמוֹלִיךְ וּמֵבִיא שֶׁהַמֵּבִיא גֵּט שִׁחְרוּר בְּאֶרֶץ יִשְׂרָאֵל אֵין צָרִיךְ לוֹמַר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם וּבְחוּצָה לָאָרֶץ אִם אֵין עֵדִים מְצוּיִין לְקַיְּמוֹ וְאָמַר הַשָּׁלִיחַ בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם זֶהוּ קִיּוּמוֹ. וְאִם בָּא הָאָדוֹן וְעִרְעֵר אַחַר כָּךְ אֵין מַשְׁגִּיחִין בּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ בְּגִטֵּי נָשִׁים. כְּשֵׁם שֶׁהָאִשָּׁה עַצְמָהּ מְבִיאָה גִּטָּהּ וְאֵינָהּ צְרִיכָה לְקַיְּמוֹ הוֹאִיל וְהַגֵּט יוֹצֵא מִתַּחַת יָדָהּ כָּךְ הָעֶבֶד שֶׁשְּׁטַר שִׁחְרוּר יוֹצֵא מִתַּחַת יָדוֹ אֵינוֹ צָרִיךְ לְקַיְּמוֹ. וּכְשֵׁם שֶׁהָאִשָּׁה אוֹמֶרֶת בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם אִם הִתְנָה עָלֶיהָ כְּמוֹ שֶׁבֵּאַרְנוּ בִּמְקוֹמוֹ כָּךְ הָעֶבֶד שֶׁהֵבִיא גֵּט וְאָמַר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם נֶאֱמָן עַל אוֹתוֹ הַדֶּרֶךְ וְאֵין צָרִיךְ קִיּוּם:","כָּל הַכָּשֵׁר לְהָבִיא גֵּט הָאִשָּׁה כָּשֵׁר לְהָבִיא גֵּט הָעֶבֶד. וְהָעֶבֶד מְקַבֵּל גֵּט לַחֲבֵרוֹ מִיַּד רַבּוֹ שֶׁל חֲבֵרוֹ אֲבָל לֹא מִיַּד רַבּוֹ שֶׁל מְקַבֵּל. הַכּוֹתֵב שְׁטַר אֵרוּסִין לְשִׁפְחָתוֹ אַף עַל פִּי שֶׁאָמַר לָהּ צְאִי בּוֹ לְחֵרוּת וְהִתְקַדְּשִׁי בּוֹ אֵין בַּלָּשׁוֹן הַזֶּה לְשׁוֹן שִׁחְרוּר וְאֵינָהּ מְקֻדֶּשֶׁת וְלֹא מְשֻׁחְרֶרֶת:"],"Mishneh Torah, Tefillin, Mezuzah and the Torah Scroll 4":["הֵיכָן מְנִיחִין תְּפִלִּין שֶׁל רֹאשׁ. מְנִיחִין אוֹתָן עַל הַקָּדְקֹד שֶׁהוּא סוֹף הַשֵּׂעָר שֶׁכְּנֶגֶד הַפָּנִים וְהוּא הַמָּקוֹם שֶׁמּוֹחוֹ שֶׁל תִּינוֹק רוֹפֵס בּוֹ. וְצָרִיךְ לְכַוֵּן אוֹתָם בָּאֶמְצַע כְּדֵי שֶׁיִּהְיוּ בֵּין הָעֵינַיִם. וְיִהְיֶה הַקֶּשֶׁר בְּגֹבַהּ הָעֹרֶף שֶׁהוּא סוֹף הַגֻּלְגּלֶת:","וְשֶׁל יָד קוֹשֵׁר אוֹתָהּ עַל שְׂמֹאלוֹ עַל הַקִּבֹּרֶת וְהוּא הַבָּשָׂר הַתּוֹפֵחַ שֶׁבַּמַּרְפֵּק שֶׁבֵּין פֶּרֶק הַכָּתֵף וּבֵין פֶּרֶק הַזְּרוֹעַ שֶׁנִּמְצָא כְּשֶׁהוּא מְדַבֵּק מַרְפֵּקוֹ לִצְלָעָיו תִּהְיֶה תְּפִלָּה כְּנֶגֶד לִבּוֹ וְנִמְצָא מְקַיֵּם (דברים ו ו) ״וְהָיוּ הַדְּבָרִים הָאֵלֶּה״ (דברים ו ו) ״עַל לְבָבֶךָ״:","הַמֵּנִיחַ תְּפִלָּה שֶׁל יָד עַל פַּס יָדוֹ אוֹ שֶׁל רֹאשׁ עַל מִצְחוֹ הֲרֵי זֶה דֶּרֶךְ צְדוֹקִים. הָעוֹשֶׂה תְּפִלָּתוֹ עֲגֻלָּה כֶּאֱגוֹז אֵין בָּהּ מִצְוָה כְּלָל. אִטֵּר מֵנִיחַ תְּפִלִּין בִּימִינוֹ שֶׁהוּא שְׂמֹאל שֶׁלּוֹ. וְאִם הָיָה שׁוֹלֵט בִּשְׁתֵּי יָדָיו מֵנִיחַ אוֹתָהּ בִּשְׂמֹאלוֹ שֶׁהוּא שְׂמֹאל כָּל אָדָם. וּמְקוֹם קְשִׁירַת הַתְּפִלִּין וּמְקוֹם הֲנָחָתָן מִפִּי הַשְּׁמוּעָה לְמָדוּם:","תְּפִלָּה שֶׁל רֹאשׁ אֵינָהּ מְעַכֶּבֶת שֶׁל יָד וְשֶׁל יָד אֵינָהּ מְעַכֶּבֶת שֶׁל רֹאשׁ מִפְּנֵי שֶׁהֵן שְׁתֵּי מִצְווֹת זוֹ לְעַצְמָהּ וְזוֹ לְעַצְמָהּ. וְכֵיצַד מְבָרְכִין. עַל שֶׁל רֹאשׁ מְבָרֵךְ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל מִצְוַת תְּפִלִּין. וְעַל שֶׁל יָד מְבָרֵךְ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְהַנִּיחַ תְּפִלִּין:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהֵנִיחַ אַחַת מֵהֶן אֲבָל אִם הֵנִיחַ שְׁתֵּיהֶן מְבָרֵךְ בְּרָכָה אַחַת וְהִיא לְהַנִּיחַ תְּפִלִּין. וְקוֹשֵׁר שֶׁל יָד וְאַחַר כָּךְ מֵנִיחַ שֶׁל רֹאשׁ. וּכְשֶׁהוּא חוֹלֵץ חוֹלֵץ שֶׁל רֹאשׁ וְאַחַר כָּךְ חוֹלֵץ שֶׁל יָד:","מִי שֶׁבֵּרֵךְ לְהַנִּיחַ תְּפִלִּין וְקָשַׁר תְּפִלִּין שֶׁל יָד אָסוּר לוֹ לְסַפֵּר וַאֲפִלּוּ לְהָשִׁיב שָׁלוֹם לְרַבּוֹ עַד שֶׁיָּנִיחַ שֶׁל רֹאשׁ. וְאִם שָׂח הֲרֵי זוֹ עֲבֵרָה וְצָרִיךְ לְבָרֵךְ בְּרָכָה שְׁנִיָּה עַל מִצְוַת תְּפִלִּין וְאַחַר כָּךְ מֵנִיחַ שֶׁל רֹאשׁ:","תְּפִלִּין כָּל זְמַן שֶׁמְּנִיחָן מְבָרֵךְ עֲלֵיהֶן וַאֲפִלּוּ חוֹלֵץ וְלוֹבֵשׁ כַּמָּה פְּעָמִים בְּיוֹם. וְכָל הַמִּצְווֹת כֻּלָּן מְבָרֵךְ עֲלֵיהֶם קֹדֶם לַעֲשִׂיָּתָן. לְפִיכָךְ צָרִיךְ לְבָרֵךְ עַל הַתְּפִלָּה שֶׁל יָד אַחַר הֲנָחָה עַל הַקִּבֹּרֶת קֹדֶם קְשִׁירָתָן. שֶׁקְּשִׁירָתָן זוֹ הִיא עֲשִׂיָּתָן:","כְּשֶׁחוֹלֵץ אָדָם תְּפִלָּיו לְהַצְנִיעָן בִּכְלִי לֹא יַנִּיחַ שֶׁל יָד מִלְּמַטָּה וְשֶׁל רֹאשׁ מִלְּמַעְלָה מִפְּנֵי שֶׁבְּשָׁעָה שֶׁהוּא רוֹצֶה לְלָבְשָׁן יִפְגַּע בְּשֶׁל רֹאשׁ תְּחִלָּה וְנִמְצָא שֶׁמַּנִּיחָהּ וּמוֹצִיא שֶׁל יָד לְפִי שֶׁאֵין לוֹבְשִׁין שֶׁל רֹאשׁ קֹדֶם שֶׁל יָד. וְאָסוּר לָאָדָם לְהַנִּיחַ מִצְוָה וְלַעֲבֹר מִמֶּנָּה לְמִצְוָה אַחֶרֶת אֶלָּא מִצְוָה שֶׁתָּבוֹא לְיָדוֹ שֶׁל אָדָם בַּתְּחִלָּה בָּהּ הוּא מִתְעַסֵּק. לְפִיכָךְ צָרִיךְ לְהַנִּיחַ שֶׁל יָד לְמַעְלָה כְּדֵי שֶׁיִּפְגַּע בָּהּ תְּחִלָּה וְיִלְבַּשׁ עַל הַסֵּדֶר:","כְּלִי שֶׁהֱכִינוֹ לְהַנִּיחַ בּוֹ תְּפִלִּין וְהִנִּיחָם בּוֹ נִתְקַדֵּשׁ וְאָסוּר לְהִשְׁתַּמֵּשׁ בּוֹ בְּדִבְרֵי חֹל. הֱכִינוֹ וְלֹא הִנִּיחַ בּוֹ אוֹ שֶׁהִנִּיחַ בּוֹ עַרְאַי וְלֹא הֱכִינוֹ לֹא נִתְקַדֵּשׁ וַהֲרֵי הוּא חֹל כְּמוֹ שֶׁהָיָה. וְאָסוּר לִתְלוֹת אֶת הַתְּפִלִּין בֵּין בָּרְצוּעָה בֵּין בַּתְּפִלָּה עַצְמָהּ אֲבָל תּוֹלֶה הוּא אֶת הַכִּיס שֶׁהַתְּפִלִּין מֻנָּחִין בּוֹ:","זְמַן הֲנָחַת הַתְּפִלִּין בַּיּוֹם וְלֹא בַּלַּיְלָה שֶׁנֶּאֱמַר (שמות יג י) ״מִיָּמִים יָמִימָה״. (שמות יג י) ״חֻקָּה״ זוֹ הִיא מִצְוַת תְּפִלִּין. וְכֵן שַׁבָּתוֹת וְיָמִים טוֹבִים אֵינָן זְמַן תְּפִלִּין שֶׁנֶּאֱמַר (שמות יג טז) ״וְהָיָה לְאוֹת״ וְשַׁבָּתוֹת וְיָמִים טוֹבִים הֵן עַצְמָן אוֹת. וּמֵאֵימָתַי זְמַן הֲנָחָתָן מִשֶּׁיִּרְאֶה אֶת חֲבֵרוֹ בְּרִחוּק אַרְבַּע אַמּוֹת וְיַכִּירֵהוּ, עַד שֶׁתִּשְׁקַע הַחַמָּה:","מִי שֶׁהֵנִיחַ תְּפִלִּין קֹדֶם שֶׁתִּשְׁקַע הַחַמָּה וְחָשְׁכָה עָלָיו אֲפִלּוּ הֵן עָלָיו כָּל הַלַּיְלָה מֻתָּר. וְאֵין מוֹרִין דָּבָר זֶה לָרַבִּים אֶלָּא מְלַמְּדִין אֶת הַכּל שֶׁלֹּא יָנִיחוּ תְּפִלִּין עֲלֵיהֶן בַּלַּיְלָה אֶלָּא יַחְלְצוּ אוֹתָן מִשֶּׁתִּשְׁקַע הַחַמָּה. וְכָל הַמֵּנִיחַ תְּפִלִּין לְכַתְּחִלָּה אַחַר שֶׁתִּשְׁקַע הַחַמָּה עוֹבֵר בְּלָאו שֶׁנֶּאֱמַר (שמות יג י) ״וְשָׁמַרְתָּ אֶת הַחֻקָּה הַזֹּאת״ וְגוֹ׳‎ (שמות יג י) ״מִיָּמִים יָמִימָה״:","הָיָה בָּא בַּדֶּרֶךְ וּתְפִלִּין בְּרֹאשׁוֹ וְשָׁקְעָה עָלָיו הַחַמָּה וְקָדַשׁ הַיּוֹם מַנִּיחַ יָדוֹ עֲלֵיהֶן עַד שֶׁהוּא מַגִּיעַ לְבֵיתוֹ וְחוֹלֵץ. הָיָה יוֹשֵׁב בְּבֵית הַמִּדְרָשׁ וּתְפִלִּין בְּרֹאשׁוֹ וְקָדַשׁ עָלָיו הַיּוֹם מַנִּיחַ יָדוֹ עֲלֵיהֶן עַד שֶׁמַּגִּיעַ לְבֵיתוֹ וְחוֹלֵץ. וְאִם יֵשׁ בַּיִת סָמוּךְ לַחוֹמָה שֶׁמִּשְׁתַּמְּרִין בּוֹ מַנִּיחָן שָׁם. וְאִם לֹא חָלַץ תְּפִלָּיו מִשֶּׁשָּׁקְעָה הַחַמָּה מִפְּנֵי שֶׁלֹּא הָיָה לוֹ מָקוֹם לְשָׁמְרָן וְנִמְצָאוּ עָלָיו כְּדֵי לְשָׁמְרָן מֻתָּר:","כָּל הַפָּטוּר מִקְּרִיאַת שְׁמַע פָּטוּר מִתְּפִלִּין. קָטָן שֶׁיּוֹדֵעַ לִשְׁמֹר תְּפִלָּיו אָבִיו לוֹקֵחַ לוֹ תְּפִלִּין כְּדֵי לְחַנְּכוֹ בְּמִצְווֹת. חוֹלֵי מֵעַיִם וְכָל מִי שֶׁלֹּא יָכוֹל לִשְׁמֹר אֶת נְקָבָיו אֶלָּא בְּצַעַר פָּטוּר מִן הַתְּפִלִּין. וְכָל הַטְּמֵאִים כֻּלָּן חַיָּבִין בִּתְפִלִּין כִּטְהוֹרִים. מִצְטַעֵר וּמִי שֶׁאֵין דַּעְתּוֹ מְיֻשֶּׁבֶת וּנְכוֹנָה עָלָיו פָּטוּר מִן הַתְּפִלִּין שֶׁהַמֵּנִיחַ תְּפִלִּין אָסוּר לוֹ לְהַסִּיחַ דַּעְתּוֹ מֵהֶן. כֹּהֲנִים בִּשְׁעַת הָעֲבוֹדָה וְהַלְוִיִּם בְּשָׁעָה שֶׁאוֹמְרִים הַשִּׁיר עַל הַדּוּכָן וְיִשְׂרָאֵל בְּשָׁעָה שֶׁעוֹמְדִים בַּמִּקְדָּשׁ פְּטוּרִין מִן הַתְּפִלָּה וּמִן הַתְּפִלִּין:","חַיָּב אָדָם לְמַשְׁמֵשׁ בִּתְפִלָּיו כָּל זְמַן שֶׁהֵם עָלָיו שֶׁלֹּא יַסִּיחַ דַּעְתּוֹ מֵהֶם אֲפִלּוּ רֶגַע אֶחָד. שֶׁקְּדֻשָּׁתָן גְּדוֹלָה מִקְּדֻשַּׁת הַצִּיץ. שֶׁהַצִּיץ אֵין בּוֹ אֶלָּא שֵׁם אֶחָד וְאֵלּוּ יֵשׁ בָּהֶם אֶחָד וְעֶשְׂרִים שֵׁם שֶׁל יוּ״ד הֵ״א בְּשֶׁל רֹאשׁ וּכְמוֹתָן בְּשֶׁל יָד:","תְּפִלִּין צְרִיכִין גּוּף נָקִי שֶׁיִּזָּהֵר שֶׁלֹּא תֵּצֵא מִמֶּנּוּ רוּחַ מִלְּמַטָּה כָּל זְמַן שֶׁהֵם עָלָיו. לְפִיכָךְ אָסוּר לִישָׁן בָּהֶם לֹא שְׁנַת קֶבַע וְלֹא שְׁנַת עַרְאַי אֶלָּא אִם הִנִּיחַ עֲלֵיהֶן סוּדָר וְלֹא הָיְתָה עִמּוֹ אִשָּׁה יָשֵׁן בָּהֶם שְׁנַת עַרְאַי. וכֵּיצַד הוּא עוֹשֶׂה. מַנִּיחַ רֹאשׁוֹ בֵּין בִּרְכָּיו וְהוּא יוֹשֵׁב וְיָשֵׁן:","הָיוּ תְּפִלָּיו כְּרוּכִין בְּיָדוֹ מֻתָּר לִישֹׁן בָּהֶם אֲפִלּוּ שְׁנַת קֶבַע. וְאֵינוֹ אוֹכֵל בָּהֶם אֶלָּא אֲכִילַת עַרְאַי. אֲבָל אִם נִכְנַס לִסְעֻדַּת קֶבַע חוֹלְצָן וּמַנִּיחָן עַל שֻׁלְחָנוֹ עַד שֶׁיִּטּל יָדָיו וְאַחַר כָּךְ יְנִיחֵם וִיבָרֵךְ עַל מְזוֹנוֹ וְהוּא לָבוּשׁ בָּהֶן:","הָיָה לָבוּשׁ תְּפִלִּין וְהֻצְרַךְ לְבֵית הַכִּסֵּא לֹא יַנִּיחַ הַתְּפִלִּין בַּחוֹרִין הַסְּמוּכִין לִרְשׁוּת הָרַבִּים וְיִכָּנֵס שֶׁמָּא יִטְּלוּם עוֹבְרֵי דְּרָכִים. כֵּיצַד יַעֲשֶׂה. אֲפִלּוּ הֻצְרַךְ לְהַשְׁתִּין מַיִם חוֹלֵץ תְּפִלָּיו בְּרִחוּק אַרְבַּע אַמּוֹת וְגוֹלְלָן בְּבִגְדוֹ כְּמִין סֵפֶר תּוֹרָה וְאוֹחֲזָן בִּימִינוֹ כְּנֶגֶד לִבּוֹ. וְיִזָּהֵר כְּדֵי שֶׁלֹּא תְּהֵא רְצוּעָה יוֹצֵאת מִתַּחַת יָדוֹ טֶפַח. וְנִכְנָס וְעוֹשֶׂה צְרָכָיו. וּכְשֶׁיֵּצֵא מַרְחִיק אַרְבַּע אַמּוֹת מִבֵּית הַכִּסֵּא וְלוֹבְשָׁן:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּבֵית הַכִּסֵּא הַקָּבוּעַ שֶׁאֵין נִיצוֹצוֹת נִתָּזוֹת עָלָיו. אֲבָל בֵּית הַכִּסֵּא עַרְאַי לֹא יִכָּנֵס בָּהֶן כְּשֶׁהֵם גְּלוּלִים אֶלָּא חוֹלֵץ אוֹתָן וְנוֹתְנָן לַחֲבֵרוֹ לְשָׁמְרָן. וְאֵין מֵי רַגְלַיִם כָּלִין אֲפִלּוּ בְּבֵית הַכִּסֵּא קָבוּעַ אֶלָּא בִּישִׁיבָה. וְאִם הָיָה עָפָר תָּחוּחַ אֲפִלּוּ בַּעֲמִידָה. הָיָה בְּמָקוֹם קָשֶׁה יַעֲמֹד בִּמְקוֹם מִדְרוֹן כְּדֵי שֶׁלֹּא יִנָּתְזוּ נִיצוֹצוֹת עָלָיו:","הָיָה לָבוּשׁ בִּתְפִלִּין וְהֻצְרַךְ לְבֵית הַכִּסֵּא לְעֵת עֶרֶב וְלֹא נִשְׁאַר מִן הַיּוֹם כְּדֵי לְלָבְשָׁן אַחַר שֶׁיֵּצֵא לֹא יִכָּנֵס בָּהֶם גְּלוּלִים בְּבִגְדוֹ וַאֲפִלּוּ לְהַשְׁתִּין מַיִם בְּבֵית הַכִּסֵּא קָבוּעַ. אֶלָּא כֵּיצַד יַעֲשֶׂה. חוֹלְצָן וּמַנִּיחָן בְּכֶלְיָן אִם הָיָה בּוֹ טֶפַח אוֹ בִּכְלִי שֶׁאֵינוֹ כֶּלְיָן אַף עַל פִּי שֶׁאֵין בּוֹ טֶפַח וְאוֹחֵז הַכְּלִי בְּיָדוֹ וְנִכְנָס. וְכֵן אִם הֻצְרַךְ בַּלַּיְלָה מַנִּיחָן בִּכְלִי וְאוֹחֵז הַכְּלִי בְּיָדוֹ וְנִכְנָס:","שָׁכַח וְנִכְנַס לְבֵית הַכִּסֵּא וְהוּא לָבוּשׁ תְּפִלִּין מֵנִיחַ יָדוֹ עֲלֵיהֶן עַד שֶׁיִּגְמֹר עַמּוּד רִאשׁוֹן וְיוֹצֵא וְחוֹלֵץ. אַחַר כָּךְ נִכְנָס וְעוֹשֶׂה צְרָכָיו. שֶׁאִם יַפְסִיק בְּעַמּוּד רִאשׁוֹן בֵּין בִּגְדוֹלִים בֵּין בִּקְטַנִּים יָבוֹא לִידֵי חֳלָאִים שֶׁיֵּשׁ בָּהֶן סַכָּנָה גְּדוֹלָה:","שָׁכַח וְשִׁמֵּשׁ מִטָּתוֹ בִּתְפִלִּין הֲרֵי זֶה לֹא יֹאחַז לֹא בָּרְצוּעָה וְלֹא בַּקְּצִיצָה עַד שֶׁיִּטּל יָדָיו וְיִטְּלֵם מִפְּנֵי שֶׁהַיָּדַיִם עַסְקָנִיּוֹת:","הַנִּכְנָס לְבֵית הַמֶּרְחָץ מָקוֹם שֶׁבְּנֵי אָדָם עוֹמְדִין לְבוּשִׁין מֻתָּר לְהַנִּיחַ תְּפִלִּין. וּמָקוֹם שֶׁבְּנֵי אָדָם עוֹמְדִין שָׁם מִקְצָתָן עֲרוּמִים וּמִקְצָתָן לְבוּשִׁין אֵינוֹ חוֹלֵץ תְּפִלָּיו וְאֵינוֹ מֵנִיחַ שָׁם תְּפִלִּין לְכַתְּחִלָּה. וּמָקוֹם שֶׁבְּנֵי אָדָם עוֹמְדִים עֲרוּמִים חוֹלֵץ תְּפִלָּיו וְאֵין צָרִיךְ לוֹמַר שֶׁאֵינוֹ מֵנִיחַ:","לֹא יְהַלֵּךְ אָדָם בְּבֵית הַקְּבָרוֹת וּתְפִלִּין בְּרֹאשׁוֹ. וַאֲפִלּוּ בְּתוֹךְ אַרְבַּע אַמּוֹת שֶׁל מֵת אוֹ בְּתוֹךְ אַרְבַּע אַמּוֹת שֶׁל קֶבֶר צָרִיךְ לַחֲלֹץ תְּפִלָּיו עַד שֶׁיַּרְחִיק אַרְבַּע אַמּוֹת. וְלֹא יִלְבַּשׁ אָדָם תְּפִלִּין עַד שֶׁיְּכַסֶּה עֶרְוָתוֹ וְיִלְבַּשׁ בְּגָדָיו. הַנּוֹשֵׂא מַשּׂאוֹי עַל רֹאשׁוֹ חוֹלֵץ תְּפִלָּיו שֶׁל רֹאשׁ עַד שֶׁיָּסִיר הַמַּשּׂאוֹי מֵעָלָיו וַאֲפִלּוּ מִטְפַּחַת אָסוּר לְהַנִּיחַ עַל הָרֹאשׁ שֶׁיֵּשׁ בּוֹ תְּפִלִּין. אֲבָל צוֹנֵף הוּא מִצְנַפְתּוֹ עַל תְּפִלָּיו:","בַּיִת שֶׁיֵּשׁ בּוֹ תְּפִלִּין אוֹ סֵפֶר תּוֹרָה אָסוּר לְשַׁמֵּשׁ בּוֹ מִטָּתוֹ עַד שֶׁיּוֹצִיאֵם אוֹ יַנִּיחֵם בִּכְלִי וְיַנִּיחַ הַכְּלִי בִּכְלִי אַחֵר שֶׁאֵינוֹ כֶּלְיָן. אֲבָל אִם הָיָה הַכְּלִי הַשֵּׁנִי מְזֻמָּן לָהֶם אֲפִלּוּ עֲשָׂרָה כֵּלִים כִּכְלִי אֶחָד הֵן חֲשׁוּבִין. וְאִם הִנִּיחָן כְּלִי בְּתוֹךְ כְּלִי מֻתָּר לְהַנִּיחָן תַּחַת מְרַאֲשֹׁתָיו בֵּין כַּר לְכֶסֶת שֶׁלֹּא כְּנֶגֶד רֹאשׁוֹ כְּדֵי לְשָׁמְרָן וַאֲפִלּוּ אִשְׁתּוֹ עִמּוֹ בַּמִּטָּה:","קְדֻשַּׁת תְּפִלִּין קְדֻשָּׁתָן גְּדוֹלָה הִיא. שֶׁכָּל זְמַן שֶׁהַתְּפִלִּין בְּרֹאשׁוֹ שֶׁל אָדָם וְעַל זְרוֹעוֹ הוּא עָנָו וִירֵא שָׁמַיִם וְאֵינוֹ נִמְשָׁךְ בִּשְׂחוֹק וּבְשִׂיחָה בְּטֵלָה וְאֵינוֹ מְהַרְהֵר מַחֲשָׁבוֹת רָעוֹת אֶלָּא מְפַנֶּה לִבּוֹ בְּדִבְרֵי הָאֱמֶת וְהַצֶּדֶק. לְפִיכָךְ צָרִיךְ אָדָם לְהִשְׁתַּדֵּל לִהְיוֹתָן עָלָיו כָּל הַיּוֹם שֶׁמִּצְוָתָן כָּךְ הִיא. אָמְרוּ עָלָיו עַל רַב תַּלְמִידוֹ שֶׁל רַבֵּנוּ הַקָּדוֹשׁ שֶׁכָּל יָמָיו לֹא רָאוּהוּ שֶׁהָלַךְ אַרְבַּע אַמּוֹת בְּלֹא תּוֹרָה אוֹ בְּלֹא צִיצִית אוֹ בְּלֹא תְּפִלִּין:","אַף עַל פִּי שֶׁמִּצְוָתָן לְלָבְשָׁן כָּל הַיּוֹם, בִּשְׁעַת תְּפִלָּה יוֹתֵר מִן הַכּל. אָמְרוּ חֲכָמִים כָּל הַקּוֹרֵא קְרִיאַת שְׁמַע בְּלֹא תְּפִלִּין כְּאִלּוּ מֵעִיד עֵדוּת שֶׁקֶר בְּעַצְמוֹ. וְכָל שֶׁאֵינוֹ מֵנִיחַ תְּפִלִּין עוֹבֵר בִּשְׁמוֹנָה עֲשֵׂה שֶׁהֲרֵי בְּאַרְבַּע פָּרָשִׁיּוֹת צִוָּה עַל תְּפִלִּין שֶׁל רֹאשׁ וְעַל תְּפִלִּין שֶׁל יָד. וְכָל הָרָגִיל בִּתְפִלִּין מַאֲרִיךְ יָמִים שֶׁנֶּאֱמַר (ישעיהו לח טז) ״ה׳‎ עֲלֵיהֶם יִחְיוּ״:"],"Mishneh Torah, Testimony 15":["כָּל עֵדוּת שֶׁתָּבוֹא הֲנָאָה לְאָדָם מִמֶּנָּה אֵינוֹ מֵעִיד בָּהּ שֶׁזֶּה הוּא כְּמֵעִיד עַל עַצְמוֹ. לְפִיכָךְ בְּנֵי הָעִיר שֶׁבָּא מְעַרְעֵר לְעַרְעֵר עֲלֵיהֶם בַּמֶּרְחָץ אוֹ בִּרְחוֹב שֶׁל עִיר. אֵין אֶחָד מִבַּעֲלֵי הָעִיר מֵעִיד בְּדָבָר זֶה וְלֹא דָּן עַד שֶׁיְּסַלֵּק עַצְמוֹ בְּקִנְיָן גָּמוּר וְאַחַר כָּךְ יָעִיד אוֹ יָדִין:","בְּנֵי הָעִיר שֶׁנִּגְנַב סֵפֶר תּוֹרָה שֶׁלָּהֶן הוֹאִיל וְלִשְׁמִיעָה הוּא עָשׂוּי שֶׁאִי אֶפְשָׁר לְאָדָם לְסַלֵּק עַצְמוֹ מִמֶּנּוּ אֵין דָּנִין בְּדַיָּנֵי אוֹתָהּ הָעִיר וְאֵין מְבִיאִין רְאָיָה מֵאַנְשֵׁי אוֹתָהּ הָעִיר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָאוֹמֵר תְּנוּ מָנֶה לַעֲנִיֵּי עִירִי אֵין דָּנִין בְּדַיָּנֵי אוֹתָהּ הָעִיר וְאֵין מְבִיאִין רְאָיָה מֵאַנְשֵׁי אוֹתָהּ הָעִיר. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ הָעֲנִיִּים סְמוּכִים עֲלֵיהֶם וּפוֹסְקִין עֲלֵיהֶן צְדָקָה. אֲפִלּוּ אָמְרוּ שְׁנַיִם מֵאַנְשֵׁי אוֹתָהּ הָעִיר אָנוּ נִתֵּן דָּבָר הַקָּצוּב עָלֵינוּ וְנָעִיד אֵין שׁוֹמְעִין לָהֶם. שֶׁהֲנָאָה הוּא לָהֶם שֶׁיִּתְעַשְּׁרוּ עֲנִיִּים אֵלּוּ הוֹאִיל וְהֵן סְמוּכִין עַל בְּנֵי הָעִיר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","קַרְקַע שֶׁבֵּין שְׁנֵי שֻׁתָּפִין שֶׁבָּא מְעַרְעֵר לְהוֹצִיאָהּ מִתַּחַת יַד הַשֻׁתָּף. אֵינוֹ מֵעִיד לְשֻׁתָּפוֹ עָלֶיהָ אֶלָּא אִם סִלֵּק עַצְמוֹ מִמֶּנָּה וְקָנוּ מִיָּדוֹ שֶׁנְּתָנָהּ לַשֻּׁתָּף וְשֶׁאִם בָּא בַּעַל חוֹב שֶׁלּוֹ וּטְרָפָהּ מִיַּד הַשֻׁתָּף מְשַׁלֵּם לוֹ דָּמֶיהָ. וְאַחַר כָּךְ מֵעִיד לוֹ עָלֶיהָ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָעוֹרֵר עַל הַשָּׂדֶה אִם יֵשׁ בָּהּ פֵּרוֹת אֵין הָאָרִיס מֵעִיד לוֹ עָלֶיהָ. שֶׁהֲרֵי רוֹצֶה הָאָרִיס לְהַעֲמִידָהּ בְּיַד בְּעָלֶיהָ כְּדֵי שֶׁיִּטּל חֶלְקוֹ בַּפֵּרוֹת. וְאִם אֵין בָּהּ פֵּרוֹת מֵעִיד. אֲבָל הַשּׂוֹכֵר אִם לָקַח הַשְּׂכִירוּת בְּיָדוֹ וְאָמַר כָּל מִי שֶׁתִּתְקַיֵּם שָׂדֶה זוֹ בְּיָדוֹ יִטּל הֲרֵי זֶה מֵעִיד. וְאִם כְּבָר נָתַן הַשְּׂכִירוּת לְבַעַל הַשָּׂדֶה אֵינוֹ מֵעִיד. כֵּיוָן שֶׁאִם תֵּצֵא הַשָּׂדֶה לַמְעַרְעֵר חַיָּב לִתֵּן לוֹ שְׂכַר כָּל הַשָּׁנִים שֶׁיָּשַׁב בָּהּ אֵינוֹ מֵעִיד. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","שִׁמְעוֹן שֶׁלָּוָה וְהָיָה רְאוּבֵן עָרֵב וּבָא יְהוּדָה לְעַרְעֵר עַל שִׁמְעוֹן הַלּוֶֹה וְהוֹצִיא קַרְקַע מִתַּחַת יָדוֹ. אִם יֵשׁ לְשִׁמְעוֹן שָׂדֶה אַחֶרֶת כְּנֶגֶד הַחוֹב הֲרֵי רְאוּבֵן הֶעָרֵב יֵשׁ לוֹ לְהָעִיד עַל אוֹתוֹ קַרְקַע שֶׁהִיא שֶׁל שִׁמְעוֹן. שֶׁאֵין לוֹ הֲנָאָה בָּזֶה שֶׁאִם לְקָחָהּ יְהוּדָה הֲרֵי שָׂדֶה אַחֶרֶת שֶׁיִּפָּרַע מִמֶּנָּה בַּעַל חוֹבוֹ. וְכֵן לוֹקֵחַ רִאשׁוֹן מֵעִיד לְלוֹקֵחַ שֵׁנִי שֶׁלָּקַח אַחֲרָיו שֶׁזֶּה הַשָּׂדֶה שֶׁלּוֹ. וְהוּא שֶׁיֵּשׁ לַמּוֹכֵר שָׂדֶה בֶּן חוֹרִין כְּנֶגֶד דְּמֵי שָׂדֶה שֶׁל לוֹקֵחַ רִאשׁוֹן. שֶׁאֵין לְלוֹקֵחַ רִאשׁוֹן הֲנָאָה בַּעֲמִידַת זֶה הַשָּׂדֶה בְּיַד לוֹקֵחַ שֵׁנִי. שֶׁאֲפִלּוּ נִטְרַף לוֹקֵחַ הָרִאשׁוֹן עַל הַמּוֹכֵר הוּא חוֹזֵר וַהֲרֵי יֵשׁ לוֹ שָׂדֶה אַחֶרֶת שֶׁיִּגְבֶּה מִמֶּנָּה:"],"Mishneh Torah, Testimony 6":["כְּבָר בֵּאַרְנוּ שֶׁקִּיּוּם שְׁטָרוֹת מִדִּבְרֵיהֶם כְּדֵי שֶׁלֹּא תִּנְעל דֶּלֶת בִּפְנֵי לוֹוִין. אַף עַל פִּי כֵן אֵין מְקַיְּמִין שְׁטָרוֹת אֶלָּא בִּשְׁלֹשָׁה אֲפִלּוּ שְׁלָשְׁתָּן הֶדְיוֹטוֹת מִפְּנֵי שֶׁהוּא דִּין. וּלְפִיכָךְ אֵין מְקַיְּמִין שְׁטָרוֹת בַּלַּיְלָה כְּמוֹ שֶׁבֵּאַרְנוּ:","בְּאֶחָד מֵחֲמִשָּׁה דְּרָכִים מִתְקַיֵּם הַשְּׁטָר בְּבֵית דִּין. הַדֶּרֶךְ הָאֶחָד שֶׁיִּהְיוּ דַּיָּנִים מַכִּירִין כְּתַב יְדֵי הָעֵדִים שֶׁזּוֹ עֵדוּת פְּלוֹנִי וְזוֹ עֵדוּת פְּלוֹנִי. הַדֶּרֶךְ הַשֵּׁנִי שֶׁיַּחְתְּמוּ הָעֵדִים בִּפְנֵיהֶם. הַדֶּרֶךְ הַשְּׁלִישִׁי שֶׁיָּבוֹאוּ הָעֵדִים הַחֲתוּמִים בִּפְנֵיהֶם וְיֹאמַר כָּל אֶחָד וְאֶחָד זֶה כְּתַב יָדִי וַאֲנִי עֵד בַּדָּבָר הַזֶּה. הַדֶּרֶךְ הָרְבִיעִי שֶׁאִם מֵתוּ עֵדֵי הַשְּׁטָר אוֹ שֶׁהָיוּ בִּמְדִינָה אַחֶרֶת יָבוֹאוּ עֵדִים וְיָעִידוּ עַל כְּתַב יָדָן שֶׁהוּא זֶה. הַדֶּרֶךְ הַחֲמִישִׁי שֶׁיִּהְיֶה כְּתַב יָדָן יוֹצֵא מִשְּׁטָרוֹת אֲחֵרִים וְעוֹרְכִין בֵּית דִּין זֶה הַכְּתָב לְאוֹתוֹ הַכְּתָב שֶׁבִּשְׁטָרוֹת אֲחֵרִים וְיִהְיֶה דּוֹמֶה זֶה לָזֶה וְיֵרָאֶה לָהֶם בְּיַחַד שֶׁכְּתַב יְדֵי אֵלּוּ הוּא כְּתַב יְדֵי אֵלּוּ:","אֵין מְקַיְּמִין אֶת הַשְּׁטָר מִשְּׁטָרוֹת אֲחֵרִים אֶלָּא מִשְּׁנֵי שְׁטָרוֹת שֶׁל שְׁתֵּי שָׂדוֹת שֶׁאֲכָלוּם בַּעֲלֵיהֶן שָׁלֹשׁ שָׁנִים אֲכִילָה גְּלוּיָה נְכוֹנָה בְּלֹא שׁוּם יִרְאָה וְלֹא פַּחַד מִתְּבִיעָה בָּעוֹלָם כְּדֶרֶךְ שֶׁאוֹכְלִין כָּל בַּעֲלֵי שָׂדוֹת שְׂדוֹתֵיהֶן. אוֹ מִשְּׁנֵי שִׁטְרֵי כְּתֻבּוֹת. וְהוּא שֶׁיֵּצְאוּ שְׁנֵי הַשְּׁטָרוֹת מִתַּחַת יְדֵי אַחֵר לֹא מִתַּחַת יְדֵי זֶה שֶׁרוֹצֶה לְקַיֵּם שְׁטָרוֹ שֶׁמָּא הוּא זִיֵּף הַכּל. וְכֵן מְקַיְּמִין הַשְּׁטָר מִשְּׁטָר שֶׁקָּרָא עָלָיו עַרְעָר וְהֻחְזַק בְּבֵית דִּין מְקַיְּמִין מִמֶּנּוּ לְבַדּוֹ כְּמוֹ שֶׁמְּקַיְּמִין מִשְּׁטַר שְׁתֵּי שָׂדוֹת אוֹ מִשְּׁתֵי כְּתֻבּוֹת:","בֵּית דִּין שֶׁכָּתְבוּ בְּמוֹשַׁב שְׁלֹשָׁה הָיִינוּ וְנִתְקַיֵּם שְׁטָר זֶה בְּפָנֵינוּ הֲרֵי זֶה מְקֻיָּם אַף עַל פִּי שֶׁלֹּא פֵּרְשׁוּ בְּאֵי זֶה דֶּרֶךְ מֵחֲמִשָּׁה דְּרָכִים נִתְקַיֵּם. שֶׁאֵין חוֹשְׁשִׁין לְבֵית דִּין שֶׁמָּא יִטְעוּ. וּכְבָר נָהֲגוּ כָּל בָּתֵּי דִּינִין שֶׁרָאִינוּ וְשָׁמַעְנוּ שֶׁיִּכְתְּבוּ הַדֶּרֶךְ שֶׁנִּתְקַיֵּם בָּהּ לִפְנֵיהֶם:","וּלְעוֹלָם אֵין בֵּית דִּין בּוֹדְקִין אַחַר בֵּית דִּין אַחֵר אֶלָּא מַחֲזִיקִין אוֹתָן שֶׁהֵן בְּקִיאִין וְלֹא יִטְעוּ. אֲבָל בּוֹדְקִין אַחַר הָעֵדִים:","שְׁלֹשָׁה שֶׁיָּשְׁבוּ לְקַיֵּם אֶת הַשְּׁטָר וּמֵת אֶחָד מֵהֶם צְרִיכִין לִכְתֹּב בְּמוֹשַׁב שְׁלֹשָׁה הָיִינוּ וְהָאֶחָד אֵינֶנּוּ. שֶׁמָּא יֹאמַר הָרוֹאֶה בֵּית דִּין בִּשְׁנַיִם קִיְּמוּהוּ. אֲפִלּוּ הָיָה כָּתוּב בּוֹ בְּבֵית דִּין יֹאמַר שֶׁמָּא דִּמּוּ שֶׁשְּׁנַיִם בֵּית דִּין הֵם. וְאִם יֵשׁ בּוֹ מַשְׁמָע שֶׁהָיוּ שְׁלֹשָׁה אֵינוֹ צָרִיךְ:","שְׁלֹשָׁה שֶׁיָּשְׁבוּ לְקַיֵּם אֶת הַשְּׁטָר וּבָאוּ שְׁנֵי עֵדִים וְעִרְעֲרוּ עַל אֶחָד מֵהֶן שֶׁהוּא גַּזְלָן וְכַיּוֹצֵא בּוֹ וּבָאוּ שְׁנַיִם אֲחֵרִים וְהֵעִידוּ שֶׁחָזַר בִּתְשׁוּבָה. אִם עַד שֶׁלֹּא חָתְמוּ הֵעִידוּ שֶׁחָזַר הֲרֵי זֶה חוֹתֵם עִמָּהֶם שֶׁהֲרֵי שְׁלֹשָׁה הָיוּ וְאִם אַחַר שֶׁחָתְמוּ הַשְּׁנַיִם הֵעִידוּ עָלָיו שֶׁחָזַר בִּתְשׁוּבָה אֵינוֹ חוֹתֵם עִמָּהֶן שֶׁהֲרֵי הוּא כְּמִי שֶׁאֵינוֹ בְּעֵת חֲתִימַת הַשְּׁנַיִם. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁעִרְעֲרוּ עָלָיו בַּעֲבֵרָה. אֲבָל עִרְעֲרוּ עָלָיו בִּפְגַם מִשְׁפָּחָה כְּמוֹ שֶׁאָמְרוּ אִמּוֹ לֹא נִשְׁתַּחְרְרָה וְעֶבֶד הוּא אוֹ לֹא נִתְגַּיְּרָה וְעַכּוּ\"ם הוּא וְנוֹדַע אַחַר שֶׁחָתְמוּ הַשְּׁנַיִם שֶׁאֵין בְּמִשְׁפַּחְתּוֹ פְּגָם וְשֶׁהוּא כָּשֵׁר הֲרֵי זֶה חוֹתֵם עִמָּהֶם שֶׁזֶּה גִּלּוּי דָּבָר שֶׁהָיָה מִקֹּדֶם הוּא:","מֻתָּר לִכְתֹּב הַקִּיּוּם בַּשְּׁטָר קֹדֶם שֶׁיִּתְקַיֵּם הַשְּׁטָר שֶׁאֵין הַכְּתִיבָה עִקָּר אֶלָּא הַחֲתִימָה. וְאֵין הַדַּיָּנִים צְרִיכִין לִקְרוֹת הַשְּׁטָר שֶׁמְּקַיְּמִין אוֹתוֹ אֶלָּא מְקַיְּמִין אוֹתוֹ מֵעֵדָיו אַף עַל פִּי שֶׁלֹּא יָדְעוּ מַה כָּתוּב בּוֹ:"],"Mishneh Torah, The Order of Prayer 1":["סדר תפלות כל השנה","נָהֲגוּ הָעָם לִקְרוֹת בְּכָל יוֹם בַּשַּׁחַר אַחַר שֶׁקּוֹרִין פָּרָשַׁת צַו וּבִרְכַּת כֹּהֲנִים קוֹרִין מִשְׁנָה זוֹ. אֵלּוּ דְּבָרִים שֶׁאֵין לָהֶם שִׁעוּר הַפֵּאָה וְהַבִּכּוּרִים וְהָרֵאָיוֹן וּגְמִילוּת חֲסָדִים וְתַלְמוּד תּוֹרָה. אֵלּוּ דְּבָרִים שֶׁאָדָם אוֹכֵל פֵּרוֹתֵיהֶן בָּעוֹלָם הַזֶּה וְהַקֶּרֶן קַיֶּמֶת לוֹ לָעוֹלָם הַבָּא. כִּבּוּד אָב וָאֵם וּגְמִילוּת חֲסָדִים וְעִיּוּן תְּפִלָּה וּבִקּוּר חוֹלִים וְהַשְׁכָּמַת בֵּית הַמִּדְרָשׁ וְהַכְנָסַת אוֹרְחִים וַהֲבָאַת שָׁלוֹם בֵּין אָדָם לַחֲבֵרוֹ וְתַלְמוּד תּוֹרָה כְּנֶגֶד כֻּלָּם. אָמַר רַבִּי זֵירָא בְּנוֹת יִשְׂרָאֵל הֵן הֶחְמִירוּ עַל עַצְמָן שֶׁאֲפִלּוּ רוֹאוֹת טִפַּת דָּם כְּחַרְדָּל יוֹשְׁבוֹת עָלֶיהָ שִׁבְעָה נְקִיִּים. תָּנָא דְּבֵי אֵלִיָּהוּ כָּל הַשּׁוֹנֶה הֲלָכוֹת בְּכָל יוֹם מֻבְטָח לוֹ שֶׁהוּא בֶּן הָעוֹלָם הַבָּא שֶׁנֶּאֱמַר הֲלִיכוֹת עוֹלָם לוֹ אַל תִּקְרֵי הֲלִיכוֹת אֶלָּא הֲלָכוֹת. אָמַר רַבִּי אֶלְעָזָר אָמַר רַבִּי חֲנִינָא תַּלְמִידֵי חֲכָמִים מַרְבִּים שָׁלוֹם בָּעוֹלָם שֶׁנֶּאֱמַר וְכָל בָּנַיִךְ לִמּוּדֵי יְיָ׳‎ וְכוּ׳‎. מִזְמוֹר לְדָוִד יְיָ׳‎ מִי יָגוּר בְּאָהֳלֶךָ מִי יִשְׁכֹּן בְּהַר קָדְשֶׁךָ הוֹלֵךְ תָּמִים וּפֹעֵל צֶדֶק. לְעוֹלָם יְהֵא אָדָם יְרֵא שָׁמַיִם בַּסֵּתֶר וּמוֹדֶה עַל הָאֱמֶת וְדוֹבֵר אֱמֶת בִּלְבָבוֹ וְיַשְׁכֵּם וְיֹאמַר. רִבּוֹן הָעוֹלָמִים לֹא עַל צִדְקוֹתֵינוּ אֲנַחְנוּ מַפִּילִים תַּחֲנוּנֵנוּ לְפָנֶיךָ כִּי עַל רַחֲמֶיךָ הָרַבִּים מָה אָנוּ מֶה חַיֵּינוּ מַה חַסְדֵּנוּ מַה צִּדְקָתֵנוּ מַה כֹּחֵנוּ וּמַה גְּבוּרָתֵנוּ מַה נֹּאמַר לְפָנֶיךָ יְיָ׳‎ אֱלֹהֵינוּ הֲלֹא כָּל הַגִּבּוֹרִים כְּאַיִן לְפָנֶיךָ וְאַנְשֵׁי הַשֵּׁם כְּלֹא הָיוּ וַחֲכָמִים כִּבְלִי מַדָּע וּנְבוֹנִים כִּבְלִי הַשְׂכֵּל כִּי כָל מַעֲשֵׂינוּ תֹּהוּ וָבֹהוּ וִימֵי חַיֵּינוּ הֶבֶל לְפָנֶיךָ כְּמוֹ שֶׁכָּתוּב בְּדִבְרֵי קָדְשְׁךָ וּמוֹתַר הָאָדָם וְגוֹ׳‎. אֲבָל אֲנַחְנוּ עַמְּךָ בְּנֵי בְרִיתֶךָ בְּנֵי אַבְרָהָם אוֹהַבְךָ שֶׁנִּשְׁבַּעְתָּ לוֹ בְּהַר הַמּוֹרִיָּה. זֶרַע יִצְחָק יְחִידְךָ שֶׁנֶּעֱקַד עַל גַּבֵּי מִזְבְּחֶךָ. עֲדַת יַעֲקֹב בִּנְךָ בְּכֹרֶךָ שֶׁמֵּאַהֲבָתְךָ שֶׁאָהַבְתָּ אוֹתוֹ וּמִשִּׂמְחָתְךָ שֶׁשָּׂמַחְתָּ בּוֹ קָרָאתָ אוֹתוֹ יִשְׂרָאֵל וִישֻׁרוּן.","לְפִיכָךְ אָנוּ חַיָּבִין לְהוֹדוֹת לְךָ וּלְשַׁבֵּחֲךָ וּלְפָאֶרְךָ וְלִתֵּן שֶׁבַח וְהוֹדָאָה לִשְׁמֶךָ. וְחַיָּבִין אָנוּ לוֹמַר לְפָנֶיךָ בְּכָל יוֹם עֶרֶב וָבֹקֶר שְׁמַע יִשְׂרָאֵל יְיָ׳‎ אֱלֹהֵינוּ יְיָ׳‎ אֶחָד. אַשְׁרֵינוּ מַה טּוֹב חֶלְקֵנוּ מַה נָּעִים גּוֹרָלֵנוּ מַה יָּפָה יְרֻשָּׁתֵנוּ. אַשְׁרֵינוּ שֶׁאָנוּ מַשְׁכִּימִין וּמַעֲרִיבִין בְּכָל יוֹם תָּמִיד עֶרֶב וָבֹקֶר וְאוֹמְרִים שְׁמַע יִשְׂרָאֵל יְיָ׳‎ אֱלֹהֵינוּ יְיָ׳‎ אֶחָד. אַתָּה הוּא קֹדֶם שֶׁנִּבְרָא הָעוֹלָם אַתָּה הוּא אַחַר שֶׁנִּבְרָא הָעוֹלָם אַתָּה הוּא בָּעוֹלָם הַזֶּה וְאַתָּה הוּא לָעוֹלָם הַבָּא אַתָּה הוּא רִאשׁוֹן וְאַתָּה הוּא אַחֲרוֹן. קַדֵּשׁ שִׁמְךָ הַגָּדוֹל וְהַקָּדוֹשׁ בְּעוֹלָמֶךָ וּבִישׁוּעָתְךָ תָּרוּם וְתַגְבִּיהַּ קַרְנֵנוּ בָּרוּךְ הַמְקַדֵּשׁ שְׁמוֹ בָּרַבִּים. אַתָּה הוּא יְיָ׳‎ אֱלֹהֵינוּ בַּשָּׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתַּחַת וּבִשְׁמֵי הַשָּׁמַיִם הָעֶלְיוֹנִים. אַתָּה הוּא רִאשׁוֹן וְאַתָּה הוּא אַחֲרוֹן וּמִבַּלְעָדֶיךָ אֵין אֱלֹהִים קַבֵּץ קוֶֹיךָ מֵאַרְבַּע כַּנְפוֹת הָאָרֶץ יַכִּירוּ וְיֵדְעוּ כָּל בָּאֵי עוֹלָם כִּי אַתָּה הוּא הָאֱלֹהִים לְבַדְּךָ לְכל מַמְלְכוֹת הָאָרֶץ אַתָּה עָשִׂיתָ אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ וּמִי בְּכָל מַעֲשֵׂה יָדֶיךָ בָּעֶלְיוֹנִים אוֹ בַתַּחְתּוֹנִים מִי שֶׁיֹּאמַר לְךָ מַה תַּעֲשֶׂה. אָבִינוּ שֶׁבַּשָּׁמַיִם עֲשֵׂה עִמָּנוּ כְּמוֹ שֶׁהִבְטַחְתָּנוּ עַל יְדֵי חוֹזֶךָ בָּעֵת הַהִיא אָבִיא אֶתְכֶם וּבָעֵת קַבְּצִי אֶתְכֶם כִּי אֶתֵּן אֶתְכֶם לְשֵׁם וְלִתְהִלָּה בְּכל עַמֵּי הָאָרֶץ בְּשׁוּבִי אֶת שְׁבוּתֵיכֶם לְעֵינֵיכֶם אָמַר יְיָ. וְנֶאֱמַר אַתָּה הוּא יְיָ׳‎ לְבַדֶּךָ אַתָּה עָשִׂיתָ אֶת הַשָּׁמַיִם שְׁמֵי הַשָּׁמַיִם וְכָל צְבָאָם הָאָרֶץ וְכָל אֲשֶׁר עָלֶיהָ הַיַּמִּים וְכָל אֲשֶׁר בָּהֶם וְאַתָּה מְחַיֶּה אֶת כֻּלָּם וּצְבָא הַשָּׁמַיִם לְךָ מִשְׁתַּחֲוִים. אַתָּה הוּא יְיָ׳‎ הָאֱלֹהִים אֲשֶׁר בָּחַרְתָּ בְּאַבְרָם וְהוֹצֵאתוֹ מֵאוּר כַּשְׂדִּים וְשַׂמְתָּ שְּׁמוֹ אַבְרָהָם. אַתָּה הוּא וּשְׁנוֹתֶיךָ לֹא יִתָּמּוּ. יְיָ׳‎ מֶלֶךְ יְיָ׳‎ מָלָךְ יְיָ׳‎ יִמְלֹךְ לְעוֹלָם וָעֶד. יְיָ׳‎ מֶלֶךְ כוּ׳‎ עַד בָּרוּךְ יְיָ׳‎ לְעוֹלָם אָמֵן וְאָמֵן:","בְּרָכָה רִאשׁוֹנָה שֶׁמְּבָרְכִין לִפְנֵי פְּסוּקֵי הַזְּמִירוֹת זֶהוּ נֻסְחָהּ. בָּרוּךְ שֶׁאָמַר וְהָיָה הָעוֹלָם בָּרוּךְ הוּא בָּרוּךְ אוֹמֵר וְעוֹשֶׂה בָּרוּךְ גּוֹזֵר וּמְקַיֵּם בָּרוּךְ מְרַחֵם עַל הָאָרֶץ בָּרוּךְ מְרַחֵם עַל הַבְּרִיּוֹת בָּרוּךְ מַעֲבִיר אֲפֵלָה וּמֵבִיא אוֹרָה בָּרוּךְ מְשַׁלֵּם שָׂכָר טוֹב לִירֵאָיו בָּרוּךְ שֶׁאֵין לְפָנֶיךָ לֹא עַוְלָה לֹא שִׁכְחָה וְלֹא כָּזָב וְלֹא מִרְמָה לֹא מַשּׂוֹא פָנִים וְלֹא מִקַּח שֹׁחַד בָּרוּךְ אֵל חַי לָעַד וְקַיָּם לָנֶצַח. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הָאֵל הַמְהֻלָּל בְּפִי עַמּוֹ מְשֻׁבָּח וּמְפֹאָר בִּלְשׁוֹן כָּל חֲסִידָיו וַעֲבָדָיו וּבְשִׁירֵי דָּוִד עַבְדְּךָ מְשִׁיחֶךָ נְהַלֶּלְךָ יְיָ׳‎ אֱלֹהֵינוּ בִּשְׁבָחוֹת וּבִזְמִירוֹת נוֹדֶךָ וּנְשַׁבֵּחֲךָ וּנְפָאֶרְךָ וְנַזְכִּיר שִׁמְךָ מַלְכֵּנוּ אֱלֹהֵינוּ יָחִיד חֵי הָעוֹלָמִים מְשֻׁבָּח וּמְפֹאָר עֲדֵי עַד שְׁמוֹ בָּרוּךְ אַתָּה יְיָ׳‎ מֶלֶךְ מְהֻלָּל בַּתִּשְׁבָּחוֹת. וְקוֹרִין פְּסוּקִין אֵלּוּ יְהִי כְבוֹד יְיָ׳‎ לְעוֹלָם יִשְׂמַח יְיָ׳‎ בְּמַעֲשָׂיו כוּ׳‎ אַשְׁרֵי כוּ׳‎ עַד סוֹף תִּלִּים. וְאַחַר כָּךְ קוֹרֵא פְּסוּקִים אֵלּוּ בָּרוּךְ יְיָ׳‎ לְעוֹלָם אָמֵן וְאָמֵן. יִמְלוֹךְ יְיָ׳‎ לְעוֹלָם אָמֵן וְאָמֵן. וַיְבָרֶךְ דָּוִיד אֶת יְיָ לְעֵינֵי כָּל הַקָּהָל וַיֹּאמֶר דָּוִיד בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵי יִשְׂרָאֵל וְכוּ׳‎:","בְּרָכָה אַחֲרוֹנָה שֶׁל אַחַר פְּסוּקֵי הַזְּמִירוֹת זֶהוּ נֻסְחָהּ. יִשְׁתַּבַּח שִׁמְךָ לָעַד מַלְכֵּנוּ הָאֵל הַמֶּלֶךְ הַגָּדוֹל וְהַקָּדוֹשׁ בַּשָּׁמַיִם וּבָאָרֶץ כִּי לְךָ נָאֶה יְיָ׳‎ אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ וְכוּ׳‎. וְקוֹרֵא הַשִּׁירָה עַד סוֹפָהּ כְּמִנְהַג הַמָּקוֹם. בְּשַׁבָּת נָהֲגוּ כָּל הָעָם לְהוֹסִיף לִפְנֵי בְּרָכָה זוֹ נֹסַח זֶה. נִשְׁמַת כָּל חַי תְּבָרֵךְ אֶת שִׁמְךָ יְיָ׳‎ אֱלֹהֵינוּ וְרוּחַ כָּל בָּשָׂר תְּפָאֵר וּתְרוֹמֵם זִכְרְךָ מַלְכֵּנוּ תָּמִיד לְדוֹר וָדוֹר וּמֵעוֹלָם וְעַד עוֹלָם אַתָּה אֵל וּמִבַּלְעָדֶיךָ אֵין אֱלֹהִים וְאֵין לָנוּ מֶלֶךְ גּוֹאֵל וּמוֹשִׁיעַ פּוֹדֶה וּמַצִּיל בְּכָל עֵת צָרָה וְצוּקָה אֶלָּא אַתָּה מְפַרְנֵס וּמְרַחֵם אֱלוֹהַּ כָּל בְּרִיּוֹת אֲדוֹן הַתּוֹלָדוֹת הַמְהֻלָּל בַּתִּשְׁבָּחוֹת הַמְנַהֵג עוֹלָמוֹ בְּחֶסֶד וּבְרִיּוֹתָיו בְּרַחֲמִים רַבִּים. אֱלֹהִים אֱמֶת לֹא יָנוּם וְלֹא יִישַׁן הַמְעוֹרֵר יְשֵׁנִים וְהַמֵּקִיץ נִרְדָּמִים סוֹמֵךְ נוֹפְלִים וְרוֹפֵא חוֹלִים וּמַתִּיר אֲסוּרִים וּלְךָ אֲנַחְנוּ מוֹדִים. וְאִלּוּ פִינוּ מָלֵא שִׁירָה כַּיָּם וּלְשׁוֹנֵנוּ רִנָּה כַּהֲמוֹן גַּלָּיו וְשִׂפְתוֹתֵינוּ שֶׁבַח כְּמֶרְחֲבֵי רָקִיעַ וְעֵינֵינוּ מְאִירוֹת כַּשֶּׁמֶשׁ וְכַיָּרֵחַ וְיָדֵינוּ פְּרוּשׂוֹת כְּנִשְׁרֵי שָׁמַיִם וְרַגְלֵינוּ קַלּוֹת כָּאַיָּלוֹת אֵין אָנוּ מַסְפִּיקִין לְהוֹדוֹת לְךָ יְיָ׳‎ אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ וּלְבָרֵךְ אֶת שְׁמֶךָ עַל אַחַת מֵאֶלֶף אַלְפֵי אֲלָפִים וְרֹב רֻבֵּי רְבָבוֹת פְּעָמִים הַטּוֹבוֹת נִסִּים וּגְבוּרוֹת שֶׁעָשִׂיתָ עִמָּנוּ וְעִם אֲבוֹתֵינוּ. מִלְּפָנִים מִמִּצְרַיִם גְּאַלְתָּנוּ יְיָ׳‎ אֱלֹהֵינוּ מִבֵּית עֲבָדִים פְּדִיתָנוּ. בָּרָעָב זַנְתָּנוּ וּבְשָׂבָע כִּלְכַּלְתָּנוּ. מֵחֶרֶב הִצַּלְתָּנוּ וּמִדֶּבֶר מִלַּטְתָּנוּ וּמֵחֳלָאִים רָעִים רַבִּים דִּלִּיתָנוּ. וְעַד הֵנָּה עֲזָרוּנוּ רַחֲמֶיךָ יְיָ׳‎ אֱלֹהֵינוּ וְלֹא עֲזָבוּנוּ חֲסָדֶיךָ עַל כֵּן אֵיבָרִים שֶׁפִּלַּגְתָּ בָּנוּ וְרוּחַ וּנְשָׁמָה שֶׁנָּפַחְתָּ בְּאַפֵּנוּ וְלָשׁוֹן אֲשֶׁר שַׂמְתָּ בְּפִינוּ הֵן הֵם יוֹדוּ וִיבָרְכוּ אֶת שִׁמְךָ יְיָ׳‎ אֱלֹהֵינוּ וְכוּ׳‎ יִשְׁתַּבַּח וְכוּ׳‎. וְכֵן נָהֲגוּ לִקְרוֹת כָּל מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת קֹדֶם שֶׁיַּתְחִילוּ פְּסוּקֵי הַזְּמִירוֹת בְּיוֹם הַשַּׁבָּת וּבְיוֹם הַכִּפּוּרִים. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ לִקְרוֹת הַלֵּל הַגָּדוֹל בְּשַׁבָּתוֹת קֹדֶם פְּסוּקֵי הַזְּמִירוֹת. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ לִקְרוֹת שִׁיר הַמַּעֲלוֹת הַכּל כְּמִנְהָגָם:","בְּרָכָה רִאשׁוֹנָה שֶׁלִּפְנֵי קְרִיאַת שְׁמַע זוֹ הִיא נֻסְחָהּ. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם יוֹצֵר אוֹר וּבוֹרֵא חשֶׁךְ כוּ׳‎ עַד יוֹצֵר הַמְּאוֹרוֹת. בְּרָכָה שְׁנִיָּה אַהֲבַת עוֹלָם אֲהַבְתָּנוּ יְיָ׳‎ אֱלֹהֵינוּ חֶמְלָה גְּדוֹלָה וִיתֵרָה חָמַלְתָּ עָלֵינוּ אָבִינוּ מַלְכֵּנוּ כוּ׳‎ עַד בְּעַמּוֹ יִשְׂרָאֵל בְּאַהֲבָה:","בְּרָכָה אַחֲרוֹנָה שֶׁלְּאַחַר קְרִיאַת שְׁמַע זוֹ הִיא נֻסְחָהּ. אֱמֶת וְיַצִּיב וְכוּ׳‎ עַד בָּרוּךְ אַתָּה יְיָ׳‎ גָּאַל יִשְׂרָאֵל. וּבְעַרְבִית בְּרָכָה רִאשׁוֹנָה בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר בִּדְבָרוֹ מַעֲרִיב עֲרָבִים עַד בָּרוּךְ אַתָּה יְיָ׳‎ הַמַּעֲרִיב עֲרָבִים. בְּרָכָה שְׁנִיָּה אַהֲבַת עוֹלָם בֵּית יִשְׂרָאֵל עַמְּךָ אָהָבְתָּ וְכוּ׳‎ עַד בָּרוּךְ אַתָּה יְיָ׳‎ אוֹהֵב עַמּוֹ יִשְׂרָאֵל.","בְּרָכָה רִאשׁוֹנָה שֶׁלְּאַחַר קְרִיאַת שְׁמַע שֶׁל עַרְבִית זוֹ הִיא נֻסְחָהּ. אֱמֶת וֶאֱמוּנָה כָּל זֹאת קַיָּם עָלֵינוּ כוּ׳‎ עַד בָּרוּךְ אַתָּה יְיָ׳‎ גָּאַל יִשְׂרָאֵל.","בְּרָכָה אַחֲרוֹנָה זוֹ הִיא נֻסְחָהּ. הַשְׁכִּיבֵנוּ יְיָ׳‎ אֱלֹהֵינוּ לְשָׁלוֹם וְכוּ׳‎ עַד בָּרוּךְ שׁוֹמֵר עַמּוֹ יִשְׂרָאֵל לָעַד. בָּרוּךְ יְיָ׳‎ לְעוֹלָם אָמֵן וְאָמֵן כוּ׳‎ עַד פָּדִיתָה אוֹתִי יְיָ׳‎ אֵל אֱמֶת. יִרְאוּ עֵינֵינוּ וְיִשְׂמַח לִבֵּנוּ כוּ׳‎ עַד יְיָ׳‎ מֶלֶךְ יְיָ׳‎ מָלָךְ יְיָ׳‎ יִמְלֹךְ לְעוֹלָם וָעֶד.","וְנָהֲגוּ מִקְצָת הָעָם לְבָרֵךְ פְּסוּקִים בְּאֶמְצַע בְּרָכָה וְקוֹרְאִין בְּנֹסַח זֶה. וַיַּרְא כָּל הָעָם וַיִּפְּלוּ עַל פְּנֵיהֶם וַיֹּאמְרוּ יְיָ׳‎ הוּא הָאֱלֹהִים יְיָ׳‎ הוּא הָאֱלֹהִים. הוֹשִׁיעֵנוּ אֱלֹהֵי יִשְׁעֵנוּ וְקַבְּצֵנוּ וְהַצִּילֵנוּ מִן הַגּוֹיִם לְהוֹדוֹת לְשֵׁם קָדְשֶׁךָ לְהִשְׁתַּבֵּחַ בִּתְהִלָּתֶךָ. כִּי לֹא יִטּוֹשׁ יְיָ׳‎ אֶת עַמּוֹ בַּעֲבוּר שְׁמוֹ הַגָּדוֹל כִּי הוֹאִיל יְיָ׳‎ לַעֲשׂוֹת אֶתְכֶם לוֹ לְעָם וְעָלוּ מוֹשִׁעִים בְּהַר צִיּוֹן לִשְׁפֹּט אֶת הַר עֵשָׂו וְהָיְתָה לַיְיָ׳‎ הַמְּלוּכָה וְהָיָה יְיָ׳‎ לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה יְיָ׳‎ אֶחָד וּשְׁמוֹ אֶחָד. אֱלֹהֵינוּ שֶׁבַּשָּׁמַיִם יַחֵד שִׁמְךָ הַקָּרוּי עָלֵינוּ קַיֵּם אֶת שְׁמֶךָ וּמַלְכוּתֶךָ עָלֵינוּ תָּמִיד. בְּיָדְךָ נַפְשׁוֹת הַחַיִּים וְהַמֵּתִים אֲשֶׁר בְּיָדוֹ נֶפֶשׁ כָּל חָי וְרוּחַ כָּל בְּשַׂר אִישׁ בְּיָדְךָ אַפְקִיד רוּחִי פָּדִיתָה אוֹתִי יְיָ׳‎ אֵל אֱמֶת. וַאֲנַחְנוּ עַמְּךָ וְצֹאן מַרְעִיתֶךָ נוֹדֶה לְךָ לְעוֹלָם לְדוֹר וָדוֹר נְסַפֵּר תְּהִלָּתֶךָ. יְיָ׳‎ הַצִּילָה נַפְשִׁי מִשְּׂפַת שֶׁקֶר מִלָּשׁוֹן רְמִיָּה. יִשְׂרָאֵל נוֹשַׁע בַּיְיָ׳‎ תְּשׁוּעַת עוֹלָמִים לֹא תֵבשׁוּ וְלֹא תִכָּלְמוּ עַד עוֹלְמֵי עַד. יְהִי יְיָ׳‎ אֱלֹהֵינוּ עִמָּנוּ כַּאֲשֶׁר הָיָה עִם אֲבוֹתֵינוּ אַל יַעַזְבֵנוּ וְאַל יִטְּשֵׁנוּ לְהַטּוֹת לְבָבֵנוּ אֵלָיו לָלֶכֶת בְּכָל דְּרָכָיו לִשְׁמֹר מִצְוֹתָיו וְחֻקָּיו וּמִשְׁפָּטָיו אֲשֶׁר צִוָּה אֶת אֲבוֹתֵינוּ. כָּל הַנְּשָׁמָה תְּהַלֵּל יָהּ הַלְלוּיָהּ. בָּרוּךְ יְיָ׳‎ בַּיּוֹם בָּרוּךְ יְיָ׳‎ בַּלַּיְלָה בָּרוּךְ יְיָ׳‎ בְּשָׁכְבֵנוּ בָּרוּךְ יְיָ׳‎ בְּקוּמֵנוּ תָּמִיד נְהַלֶּלְךָ סֶלָה וְנָשִׂיחַ בְּחֻקֶּיךָ וּבֶאֱמוּנָתֶךָ. בָּרוּךְ אַתָּה יְיָ׳‎ הַמּוֹלֵךְ בִּכְבוֹדוֹ חַי וְקַיָּם תָּמִיד יִמְלוֹךְ עָלֵינוּ וְכוּ׳‎:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 16":["כְּשֵׁם שֶׁמִּצְוָה לְהָמִית אֶת הַמְחֻיָּב מִיתָה כָּךְ מִצְוַת עֲשֵׂה לְהַלְקוֹת אֶת הַמְחֻיָּב מַלְקוֹת. שֶׁנֶּאֱמַר (דברים כה ב) \"וְהִפִּילוֹ הַשֹּׁפֵט וְהִכָּהוּ לְפָנָיו\". וְאַף עַל פִּי שֶׁמַּלְקוֹת בִּשְׁלֹשָׁה בִּמְקוֹם מִיתָה הִיא עוֹמֶדֶת:","מַלְקִין בַּזְּמַן הַזֶּה בְּכָל מָקוֹם מִן הַתּוֹרָה בִּפְנֵי שְׁלֹשָׁה סְמוּכִין אֲבָל לֹא בִּפְנֵי הֶדְיוֹטוֹת:","וְכָל מַלְקִיּוֹת שֶׁמַּלְקִין דַּיָּנֵי חוּצָה לָאָרֶץ בְּכָל מָקוֹם אֵינָהּ אֶלָּא מַכַּת מַרְדּוּת:","אֵין אָדָם לוֹקֶה אֶלָּא בְּעֵדִים וְהַתְרָאָה וּבוֹדְקִין הָעֵדִים בִּדְרִישָׁה וּבַחֲקִירָה כְּדֶרֶךְ שֶׁעוֹשִׂים בְּדִינֵי נְפָשׁוֹת. עָבַר עַל לָאו שֶׁנִּתַּק לַעֲשֵׂה וְהִתְרוּ בּוֹ וְאָמְרוּ לוֹ אַל תַּעֲשֶׂה דָּבָר זֶה שֶׁאִם תַּעֲשֶׂנּוּ וְלֹא תְּקַיֵּם עֲשֵׂה שֶׁבּוֹ תִּלְקֶה. וְעָבַר וְלֹא קִיֵּם הָעֲשֵׂה הֲרֵי זֶה לוֹקֶה. אַף עַל פִּי שֶׁהַתְרָאָה בְּסָפֵק הִיא שֶׁאִם יְקַיֵּם יִפָּטֵר הַתְרָאַת סָפֵק הַתְרָאָה הִיא:","עָבַר עֲבֵרָה שֶׁיֵּשׁ בָּהּ מַלְקוֹת וּמִיתַת בֵּית דִּין כְּאַחַת כְּגוֹן שֶׁשָּׁחַט אוֹתוֹ וְאֶת בְּנוֹ לַעֲבוֹדָה זָרָה. אִם הִתְרוּ בּוֹ לְמִיתָה סוֹקְלִין אוֹתוֹ וְאֵינוֹ לוֹקֶה שֶׁהֲרֵי נִתְחַיֵּב בְּדִין גָּדוֹל מִזֶּה. וְאִם הִתְרוּ בּוֹ לְמַלְקוֹת בִּלְבַד לוֹקֶה:","אֵינוֹ צָרִיךְ שְׁנֵי עֵדִים לְמַלְקוֹת אֶלָּא בִּשְׁעַת מַעֲשֶׂה אֲבָל הָאִסּוּר עַצְמוֹ בְּעֵד אֶחָד יֻחְזַק. כֵּיצַד. אָמַר עֵד אֶחָד חֵלֶב כְּלָיוֹת הוּא זֶה. כִּלְאֵי הַכֶּרֶם הֵם פֵּרוֹת אֵלּוּ. גְּרוּשָׁה אוֹ זוֹנָה אִשָּׁה זוֹ. וְאָכַל אוֹ בָּעַל בְּעֵדִים אַחַר שֶׁהִתְרָה בּוֹ. הֲרֵי זֶה לוֹקֶה אַף עַל פִּי שֶׁעִקַּר הָאִסּוּר בְּעֵד אֶחָד. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁלֹּא הִכְחִישׁ הָעֵד בְּעֵת שֶׁקָּבַע הָאִסּוּר. אֲבָל אִם אָמַר אֵינוֹ חֵלֶב זֶה. וְזוֹ אֵינָהּ גְּרוּשָׁה. וְאָכַל אוֹ בָּעַל אַחַר שֶׁהִכְחִישׁ. אֵינוֹ לוֹקֶה עַד שֶׁיִּקְבְּעוּ הָאִסּוּר שְׁנֵי עֵדִים:","שָׁתַק בְּעֵת שֶׁהֵעִיד הָעֵד הָאֶחָד בִּקְבִיעוּת הָאִסּוּר וְאַחַר שֶׁעָבַר וְהִתְרוּ בּוֹ טָעַן לְהַכְחִישׁ הָעֵד אֵין שׁוֹמְעִין לוֹ אֶלָּא לוֹקֶה:","כֵּיצַד מַלְקִין אוֹתוֹ. כּוֹפֵת שְׁתֵּי יָדָיו עַל הָעַמּוּד אֵילָךְ וְאֵילָךְ וְחַזַּן הַכְּנֶסֶת אוֹחֵז בִּבְגָדָיו. אִם נִקְרְעוּ נִקְרְעוּ וְאִם נִפְרְמוּ נִפְרְמוּ. עַד שֶׁהוּא מְגַלֶּה אֶת לִבּוֹ. שֶׁאֵינוֹ מַכֵּהוּ עַל כְּסוּתוֹ שֶׁנֶּאֱמַר (דברים כה ב) \"וְהִכָּהוּ\" וְלֹא לִכְסוּתוֹ. וְהָאֶבֶן נְתוּנָה מֵאֲחוֹרָיו שֶׁהַחַזָּן הַמַּכֶּה עוֹמֵד עָלֶיהָ. וּרְצוּעָה שֶׁל עֵגֶל בְּיָדוֹ כְּפוּלָה לִשְׁנַיִם וּשְׁנַיִם לְאַרְבָּעָה. וּשְׁתֵּי רְצוּעוֹת שֶׁל חֲמוֹר עוֹלוֹת וְיוֹרְדוֹת בּוֹ. וְרֹחַב הָרְצוּעָה טֶפַח וְאָרְכָּהּ כְּדֵי שֶׁתְּהֵא מַגַּעַת עַד פִּי כְּרֵסוֹ. וְיַד שֶׁל רְצוּעוֹת שֶׁאוֹחֵז בָּהּ אָרְכָּהּ טֶפַח:","הָאִישׁ הַמַּכֶּה צָרִיךְ לִהְיוֹת יָתֵר בְּדֵעָה וְחָסֵר בְּכֹחַ. וּמַגְבִּיהַּ אֶת הָרְצוּעוֹת בִּשְׁתֵּי יָדָיו וּמַכֶּה בְּיָדוֹ אַחַת בְּכָל כֹּחוֹ. וּמַלְקֵהוּ שְׁלִישׁ מִלְּפָנָיו [עַל חָזֵהוּ] בֵּין דָּדָיו וּשְׁנֵי שְׁלִישִׁים מֵאֲחוֹרָיו. שְׁלִישׁ עַל כָּתֵף זֶה וּשְׁלִישׁ עַל כָּתֵף זֶה:","הַמֻּכֶּה אֵינוֹ עוֹמֵד וְלֹא יוֹשֵׁב אֶלָּא מֻטֶּה. שֶׁנֶּאֱמַר (דברים כה ב) \"וְהִפִּילוֹ הַשֹּׁפֵט וְהִכָּהוּ לְפָנָיו\" שֶׁיְּהוּ עֵינָיו שֶׁל שׁוֹפֵט בּוֹ לֹא שֶׁיִּהְיֶה מַבִּיט בְּדָבָר אַחֵר וּמַכֵּהוּ מִכָּאן שֶׁאֵין מַכִּים שְׁנַיִם כְּאֶחָד:","הַגָּדוֹל שֶׁבַּדַּיָּנִים קוֹרֵא כָּל זְמַן שֶׁזֶּה לוֹקֶה (דברים כח נח) \"אִם לֹא תִשְׁמֹר לַעֲשׂוֹת\". (דברים כח נט) \"וְהִפְלָא ה' אֶת מַכֹּתְךָ\". וּמִתְכַּוֵּן שֶׁיִּגְמֹר הַפְּסוּקִים עִם הַמַּלְקִיּוֹת. וְאִם לֹא גָּמַר חוֹזֵר לִתְחִלַּת הַמִּקְרָא וְקוֹרֵא וְחוֹזֵר וְקוֹרֵא עַד שֶׁתִּגָּמֵר כָּל הַהַכָּאָה. וְהַשֵּׁנִי שֶׁבַּדַּיָּנִים מוֹנֶה וְהַשְּׁלִישִׁי אוֹמֵר לַחַזָּן הַכֵּה. כָּל זְמַן שֶׁמַּכֶּה עַל פִּיו הוּא מַכֶּה:","מֵת תַּחַת יָדוֹ פָּטוּר. וְאִם הוֹסִיף רְצוּעָה אַחַת עַל הָאֹמֶד וּמֵת הֲרֵי הַחַזָּן גּוֹלֶה. וְאִם לֹא מֵת הֲרֵי הַחַזָּן עָבַר עַל מִצְוַת לֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים כה ג) \"לֹא יֹסִיף\". וְהוּא הַדִּין לְכָל מַכֶּה אֶת חֲבֵרוֹ שֶׁהוּא בְּלֹא תַּעֲשֶׂה. וּמָה אִם זֶה שֶׁנָּתְנָה תּוֹרָה רְשׁוּת לְהַכּוֹתוֹ צִוָּה הַכָּתוּב שֶׁלֹּא לְהַכּוֹתוֹ יָתֵר עַל רִשְׁעוֹ קַל וָחֹמֶר לִשְׁאָר כָּל הָאָדָם. לְפִיכָךְ כָּל הַמַּכֶּה אֶת חֲבֵרוֹ אֲפִלּוּ הִכָּה עֶבֶד הַכָּאָה שֶׁאֵין בָּהּ שְׁוֵה פְּרוּטָה לוֹקֶה. אֲבָל אִם יֵשׁ בָּהּ שְׁוֵה פְּרוּטָה הוֹאִיל וְהוּא חַיָּב לְשַׁלֵּם מָמוֹן אֵין אָדָם מְשַׁלֵּם וְלוֹקֶה כְּמוֹ שֶׁבֵּאַרְנוּ בְּכַמָּה מְקוֹמוֹת:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 3":["עַד אֵימָתַי יוֹשְׁבִין הַדַּיָּנִים בְּדִין. סַנְהֶדְרִי קְטַנָּה וּבֵית דִּין שֶׁל שְׁלֹשָׁה יוֹשְׁבִין מֵאַחַר תְּפִלַּת הַשַּׁחַר עַד סוֹף שֵׁשׁ שָׁעוֹת בַּיּוֹם. אֲבָל בֵּית דִּין הַגָּדוֹל הָיוּ יוֹשְׁבִין מִתָּמִיד שֶׁל שַׁחַר עַד תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם. וּבְשַׁבָּתוֹת וְיָמִים טוֹבִים הָיוּ יוֹשְׁבִין בְּבֵית הַמִּדְרָשׁ שֶׁבְּהַר הַבַּיִת:","אֵין בֵּית דִּין שֶׁל שִׁבְעִים וְאֶחָד צְרִיכִין שֶׁיִּהְיוּ יוֹשְׁבִין כֻּלָּן כְּאֶחָד בִּמְקוֹמָן שֶׁבַּמִּקְדָּשׁ. אֶלָּא בְּעֵת שֶׁיְּהוּ צְרִיכִין לְהִתְקַבֵּץ מִתְקַבְּצִין כֻּלָּן. וּבִשְׁאָר הָעִתּוֹת כָּל מִי שֶׁהָיָה לוֹ עֵסֶק יֵצֵא לַעֲשׂוֹת חֶפְצוֹ וְחוֹזֵר וְהוּא שֶׁלֹּא יִפְחֲתוּ מֵעֶשְׂרִים וּשְׁלֹשָׁה יוֹשְׁבִין תָּמִיד כָּל זְמַן יְשִׁיבָתָן. הֻצְרַךְ אֶחָד מֵהֶן לָצֵאת הֲרֵי זֶה מִסְתַּכֵּל בַּחֲבֵרָיו הַנִּשְׁאָרִים אִם יִשָּׁאֲרוּ שָׁם עֶשְׂרִים וּשְׁלֹשָׁה יֵצֵא וְאִם לָאו לֹא יֵצֵא עַד שֶׁיָּבוֹא אַחֵר:","אֵין מַתְחִילִין אֶת הַדִּינִין בַּלַּיְלָה. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁהַדִּינִין כִּנְגָעִים שֶׁנֶּאֱמַר (דברים כא ה) \"כָּל רִיב וְכָל נָגַע\" מָה רְאִיַּת נְגָעִים בַּיּוֹם בִּלְבַד אַף הַדִּינִין בַּיּוֹם בִּלְבַד:","וְכֵן אֵין מְקַבְּלִין עֵדוּת וְאֵין מְקַיְּמִין שְׁטָרוֹת בַּלַּיְלָה. וּבְדִינֵי מָמוֹנוֹת אִם הִתְחִילוּ בַּיּוֹם מֻתָּר לִגְמֹר הַדִּין בַּלַּיְלָה:","הַנְּחָלוֹת כְּדִינִין שֶׁנֶּאֱמַר בָּהֶן לְחֻקַּת מִשְׁפָּט. לְפִיכָךְ אֵין מַפִּילִין נְחָלוֹת בַּלַּיְלָה:","שְׁנַיִם שֶׁנִּכְנְסוּ לְבַקֵּר אֶת הַחוֹלֶה וְצִוָּה בִּפְנֵיהֶם. כּוֹתְבִים וְאֵין עוֹשִׂים דִּין. וְאִם הָיוּ שְׁלֹשָׁה רָצוּ כּוֹתְבִין רָצוּ עוֹשִׂין דִּין. בַּמֶּה דְּבָרִים אֲמוּרִים בַּיּוֹם. אֲבָל בַּלַּיְלָה כּוֹתְבִין וְאֵין עוֹשִׂין דִּין:","כָּל בֵּית דִּין שֶׁל יִשְׂרָאֵל שֶׁהוּא הָגוּן שְׁכִינָה עִמָּהֶם. לְפִיכָךְ צְרִיכִין הַדַּיָּנִים לֵישֵׁב בְּאֵימָה וְיִרְאָה וַעֲטִיפָה וְכֹבֶד רֹאשׁ וְאָסוּר לְהָקֵל רֹאשׁ אוֹ לִשְׂחֹק אוֹ לְסַפֵּר בְּשִׂיחָה בְּטֵלָה בְּבֵית דִּין אֶלָּא בְּדִבְרֵי תּוֹרָה וְחָכְמָה:","כָּל סַנְהֶדְרִין אוֹ מֶלֶךְ אוֹ רֹאשׁ גּוֹלָה שֶׁהֶעֱמִידוּ לָהֶן לְיִשְׂרָאֵל דַּיָּן שֶׁאֵינוֹ הָגוּן וְאֵינוֹ חָכָם בְּחָכְמַת הַתּוֹרָה וְרָאוּי לִהְיוֹת דַּיָּן. אַף עַל פִּי שֶׁהוּא כֻּלּוֹ מַחֲמַדִּים וְיֵשׁ בּוֹ טוֹבוֹת אֲחֵרוֹת הֲרֵי זֶה שֶׁהֶעֱמִידוֹ עוֹבֵר בְּלֹא תַּעֲשֶׂה. שֶׁנֶּאֱמַר לֹא תַכִּירוּ פָנִים בַּמִּשְׁפָּט. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה מְדַבֵּר כְּנֶגֶד הַמְמֻנֶּה לְהוֹשִׁיב דַּיָּנִין. אָמְרוּ חֲכָמִים שֶׁמָּא תֹּאמַר אִישׁ פְּלוֹנִי נָאֶה אוֹשִׁיבֶנּוּ דַּיָּן. אִישׁ פְּלוֹנִי גִּבּוֹר אוֹשִׁיבֶנּוּ דַּיָּן. אִישׁ פְּלוֹנִי קְרוֹבִי אוֹשִׁיבֶנּוּ דַּיָּן. אִישׁ פְּלוֹנִי יוֹדֵעַ בְּכָל לָשׁוֹן אוֹשִׁיבֶנּוּ דַּיָּן. נִמְצָא מְזַכֶּה אֶת הַחַיָּב וּמְחַיֵּב אֶת הַזַּכַּאי לֹא מִפְּנֵי שֶׁהוּא רָשָׁע אֶלָּא מִפְּנֵי שֶׁאֵינוֹ יוֹדֵעַ. לְכָךְ נֶאֱמַר (דברים א יז) \"לֹא תַכִּירוּ פָנִים בַּמִּשְׁפָּט\". וְעוֹד אָמְרוּ כָּל הַמַּעֲמִיד לְיִשְׂרָאֵל דַּיָּן שֶׁאֵינוֹ הָגוּן כְּאִלּוּ הֵקִים מַצֵּבָה שֶׁנֶּאֱמַר (דברים טז כב) \"וְלֹא תָקִים לְךָ מַצֵּבָה אֲשֶׁר שָׂנֵא ה' אֱלֹהֶיךָ\". וּבִמְקוֹם תַּלְמִידֵי חֲכָמִים כְּאִלּוּ נָטַע אֲשֵׁרָה שֶׁנֶּאֱמַר (דברים טז כא) \"לֹא תִטַּע לְךָ אֲשֵׁרָה כָּל עֵץ אֵצֶל מִזְבַּח ה' אֱלֹהֶיךָ\". וְכֵן אָמְרוּ חֲכָמִים (שמות כ כ) \"לֹא תַעֲשׂוּן אִתִּי אֱלֹהֵי כֶסֶף\" אֱלוֹהַּ הַבָּא בִּשְׁבִיל כֶּסֶף וְזָהָב זֶה הַדַּיָּן שֶׁמִּנּוּהוּ מִפְּנֵי עָשְׁרוֹ בִּלְבַד:","כָּל דַּיָּן שֶׁנָּתַן מָמוֹן כְּדֵי שֶׁיִּתְמַנֶּה אָסוּר לַעֲמֹד מִפָּנָיו. וְצִוּוּ חֲכָמִים לְהָקֵל אוֹתוֹ וּלְזַלְזֵל בּוֹ. וְאָמְרוּ חֲכָמִים שֶׁהַטַּלִּית שֶׁמִּתְעַטֵּף בָּהּ תְּהִי בְּעֵינֶיךָ כְּמִרְדַּעַת שֶׁל חֲמוֹר:","כָּךְ הָיָה דֶּרֶךְ חֲכָמִים הָרִאשׁוֹנִים בּוֹרְחִין מִלְּהִתְמַנּוֹת. וְדוֹחֲקִין עַצְמָן הַרְבֵּה שֶׁלֹּא יֵשְׁבוּ בַּדִּין עַד שֶׁיֵּדְעוּ שֶׁאֵין שָׁם רָאוּי כְּמוֹתָם וְשֶׁאִם יִמָּנְעוּ מִן הַדִּין תְּקַלְקֵל הַשּׁוּרָה. אַף עַל פִּי כֵן לֹא הָיוּ יוֹשְׁבִין בַּדִּין אֶלָּא עַד שֶׁמַּכְבִּידִין עֲלֵיהֶם אֶת הָעָם וְהַזְּקֵנִים וּפוֹצְרִים בָּהֶן:"],"Mishneh Torah, Theft 6":["כָּל דָּבָר שֶׁחֶזְקָתוֹ שֶׁהוּא גָּנוּב אָסוּר לִקַּח אוֹתוֹ. וְכֵן אִם רֹב אוֹתוֹ הַדָּבָר שֶׁהוּא גָּנוּב אֵין לוֹקְחִין אוֹתוֹ. לְפִיכָךְ אֵין לוֹקְחִים מִן הָרוֹעִים צֶמֶר אוֹ חָלָב אוֹ גְּדָיִים. אֲבָל לוֹקְחִין מֵהֶן חָלָב וּגְבִינָה בַּמִּדְבָּר אֲבָל לֹא בַּיִּשּׁוּב. וּמֻתָּר לִקַּח מִן הָרוֹעִים אַרְבַּע צֹאן אוֹ אַרְבַּע גִּזּוֹת שֶׁל צֶמֶר מֵעֵדֶר קָטָן אוֹ חָמֵשׁ מֵעֵדֶר גָּדוֹל. שֶׁאֵין חֶזְקָתוֹ שֶׁהוּא גָּנוּב בְּדָבָר זֶה:","כְּלָלוֹ שֶׁל דָּבָר כָּל שֶׁהָרוֹעֶה מוֹכְרוֹ אִם הָיָה בַּעַל הַבַּיִת מַרְגִּישׁ בּוֹ מֻתָּר לְלָקְחוֹ מִן הָרוֹעֶה. וְאִם אֵין בַּעַל הַבַּיִת מַרְגִּישׁ בּוֹ אָסוּר לְלָקְחוֹ:","אֵין לוֹקְחִין מִשּׁוֹמְרֵי פֵּרוֹת עֵצִים אוֹ פֵּרוֹת אֶלָּא בִּזְמַן שֶׁהֵן יוֹשְׁבִין וּמוֹכְרִים וְהַסַּלִּים וְהַפֶּלֶס לִפְנֵיהֶם. שֶׁהֲרֵי הַדָּבָר גָּלוּי וְיֵשׁ לוֹ קוֹל וְאֵין זֶה גְּנֵבָה. וְלוֹקְחִין מִפֶּתַח הַגִּנָּה אֲבָל לֹא מֵאֲחוֹרֵי הַגִּנָּה. וְכֻלָּן שֶׁאָמְרוּ הַטְמֵן אָסוּר לָקַחַת מֵהֶן. וּמֻתָּר לָקַחַת מִן הָאָרִיס שֶׁהֲרֵי יֵשׁ לוֹ חֵלֶק בַּפֵּרוֹת וּבָעֵצִים:","אֵין לוֹקְחִין מִן הַנָּשִׁים וּמִן הָעֲבָדִים וּמִן הַקְּטַנִּים אֶלָּא דְּבָרִים שֶׁחֶזְקָתָן שֶׁהֵן שֶׁלָּהֶן מִדַּעַת הַבְּעָלִים. כְּגוֹן נָשִׁים שֶׁמָּכְרוּ כְּלֵי פִּשְׁתָּן בַּגָּלִיל אוֹ עֲגָלִים בַּשָּׁרוֹן. וְכֻלָּן שֶׁאָמְרוּ הַטְמֵן אָסוּר לִקַּח מֵהֶן מִפְּנֵי שֶׁהֵן בְּחֶזְקַת גְּנֵבָה. וְלוֹקְחִים בֵּיצִים וְתַרְנְגוֹלִים בְּכָל מָקוֹם מִכָּל אָדָם. וְאִם אָמַר הַטְמֵן אָסוּר:","לוֹקְחִין מִן הַבַּדָּדִין זֵיתִים בְּמִדָּה וְשֶׁמֶן בְּמִדָּה אֲבָל לֹא זֵיתִים מוּעָטִים וְלֹא שֶׁמֶן מוּעָט שֶׁחֶזְקָתוֹ גְּנֵבָה הֵם. וְכֵן כָּל כַּיּוֹצֵא בָּהֶם:","מוֹכִין שֶׁהַכּוֹבֵס מוֹצִיא הֲרֵי אֵלּוּ שֶׁלּוֹ וְשֶׁהַסּוֹרֵק מוֹצִיא הֲרֵי אֵלּוּ שֶׁל בַּעַל הַבַּיִת. הַכּוֹבֵס נוֹטֵל שְׁלֹשָׁה חוּטִין וְהֵן שֶׁלּוֹ יֶתֶר מִכֵּן שֶׁל בַּעַל הַבַּיִת. אִם הָיָה שָׁחוֹר עַל גַּבֵּי לָבָן נוֹטֵל אֶת הַכּל וְהֵם שֶׁלּוֹ:","הַחַיָּט שֶׁשִּׁיֵּר מִן הַחוּט כְּדֵי מְשִׁיכַת מַחַט וְשִׁיֵּר מִן הַבֶּגֶד מַטְלִית שֶׁהִיא שָׁלֹשׁ אֶצְבָּעוֹת עַל שָׁלֹשׁ אֶצְבָּעוֹת חַיָּב לְהַחְזִירָן לַבְּעָלִים. פָּחוֹת מִכָּאן שֶׁלּוֹ:","נְסֹרֶת שֶׁהֶחָרָשׁ מוֹצִיא. בְּמַעֲצָד שֶׁלּוֹ. בְּכַשִּׁיל שֶׁל בַּעַל הַבַּיִת. וְאִם הָיָה עוֹשֶׂה אֵצֶל בַּעַל הַבַּיִת אַף הַנְּסֹרֶת שֶׁל בַּעַל הַבַּיִת. וְכָל הַדְּבָרִים הָאֵלּוּ וְכַיּוֹצֵא בָּהֶן הוֹלְכִין בָּהֶן אַחַר מִנְהַג הַמְּדִינָה:","כָּל אֻמָּן שֶׁמָּכַר דָּבָר מִן הַדְּבָרִים שֶׁאֵינוֹ שֶׁלּוֹ כְּהִלְכוֹת הַמְּדִינָה. כְּגוֹן מוֹכִין שֶׁמְּכָרָן הַסּוֹרֵק בְּמָקוֹם שֶׁנָּהֲגוּ שֶׁיִּהְיוּ שֶׁל בַּעַל הַבַּיִת. אָסוּר לִקַּח מִמֶּנּוּ מִפְּנֵי שֶׁהֵן בְּחֶזְקַת גְּנֵבָה. אֲבָל לוֹקְחִין מִמֶּנּוּ כַּר מָלֵא מוֹכִין. וְאִם מָכַר הָאֻמָּן דְּבָרִים שֶׁהֵן שֶׁלּוֹ כְּהִלְכוֹת מְדִינָה לוֹקְחִין מִמֶּנּוּ. וְאִם אָמַר הַטְמֵן אָסוּר:"],"Mishneh Torah, Those Who Defile Bed or Seat 10":["עַם הָאָרֶץ אַף עַל פִּי שֶׁהוּא יִשְׂרָאֵל וְיֶשְׁנוֹ בְּתוֹרָה וּבְמִצְוֹת הֲרֵי הוּא בְּחֶזְקַת טָמֵא וּבְגָדָיו מִדְרָס לְטָהֳרוֹת. וְאִם נָגְעוּ בְּגָדָיו בָּאֳכָלִין וּמַשְׁקִין הֲרֵי הֵן טְמֵאִין. וְאִם נָגַע בִּכְלִי חֶרֶס מֵאֲוִירוֹ טִמְּאָהוּ. וְשׂוֹרְפִין אֶת הַתְּרוּמָה עַל מַגָּעָן אַף עַל פִּי שֶׁטֻּמְאָתָן בְּסָפֵק. וְאֵינָן נֶאֱמָנִין עַל הַטָּהֳרוֹת לְפִי שֶׁאֵינָן בְּקִיאִין בְּדִקְדוּקֵי טָהֳרוֹת וְטֻמְאוֹת. וּלְעוֹלָם הוּא בְּחֶזְקָה זוֹ וְאֵינוֹ נֶאֱמָן עַל הַטָּהֳרוֹת עַד שֶׁיְּקַבֵּל עָלָיו דִּבְרֵי חֲבֵרוּת. וּמַה הֵן דִּבְרֵי חֲבֵרוּת שֶׁיְּקַבֵּל עָלָיו שֶׁיְּהֵא נִזְהָר בְּטֻמְאוֹת שֶׁלֹּא יִטָּמֵּא בָּהֶן. וּבְטָהֳרוֹת שֶׁלֹּא יְטַמֵּא אוֹתָם. וְיִזָּהֵר בִּנְטִילַת יָדַיִם וּבְטָהֳרָתָן שֶׁלֹּא יִקַּח מֵעַם הָאָרֶץ דָּבָר לַח וְלֹא יִתְאָרֵחַ אֶצְלוֹ וְלֹא יְאָרְחוֹ אֶצְלוֹ בִּכְסוּתוֹ:","הַבָּא לְקַבֵּל דִּבְרֵי חֲבֵרוּת חוּץ מִדָּבָר אֶחָד מֵהֶן אֵין מְקַבְּלִין אוֹתוֹ. רְאִינוּהוּ שֶׁנּוֹהֵג בְּצִנְעָה בְּתוֹךְ בֵּיתוֹ מְקַבְּלִין אוֹתוֹ וְאַחַר כָּךְ מְלַמְּדִין אוֹתוֹ עִסְקֵי טֻמְאָה וְטָהֳרָה. וְאִם לֹא רְאִינוּהוּ שֶׁנּוֹהֵג בְּצִנְעָה בְּבֵיתוֹ מְלַמְּדִין אוֹתוֹ וְאַחַר כָּךְ מְקַבְּלִין אוֹתוֹ. וּמְקַבְּלִין אוֹתוֹ תְּחִלָּה לְטָהֳרַת הַיָּדָיִם וְאַחַר כָּךְ מְקַבְּלִין אוֹתוֹ לְטָהֳרוֹת. וְאִם אָמַר אֵינִי מְקַבֵּל אֶלָּא לְטָהֳרַת הַיָּדָיִם מְקַבְּלִין אוֹתוֹ. קִבֵּל לְטָהֳרוֹת וְלֹא לַיָּדַיִם אַף לְטָהֳרוֹת אֵין מְקַבְּלִין אוֹתוֹ. כְּשֶׁמְּקַבְּלִין אוֹתוֹ חוֹשְׁשִׁין לוֹ כָּל שְׁלֹשִׁים יוֹם עַד שֶׁיִּלְמַד וְיִהְיֶה רָגִיל בְּטָהֳרוֹת. וְאַחַר שְׁלֹשִׁים יוֹם מִשֶּׁיְּקַבֵּל דִּבְרֵי חֲבֵרוּת הֲרֵי בְּגָדָיו טְהוֹרִין וְכָל אֳכָלָיו וּמַשְׁקָיו טְהוֹרִין וְנֶאֱמָן עַל כָּל הַטָּהֳרוֹת כִּשְׁאָר כָּל הַחֲבֵרִים וְאַף עַל פִּי שֶׁאֵינוֹ תַּלְמִיד חָכָם:","תַּלְמִידֵי חֲכָמִים הֲרֵי הֵן בְּחֶזְקַת טָהֳרָה. נֶאֱמָנִין וְאֵינָן צְרִיכִין לְקַבֵּל דִּבְרֵי חֲבֵרוּת אֲבָל מִשֶּׁחָרַב בֵּית הַמִּקְדָּשׁ נָהֲגוּ כֹּהֲנִים סִלְסוּל בְּעַצְמָן שֶׁלֹּא יְהוּ מוֹסְרִין טָהֳרוֹת אֲפִלּוּ לְתַלְמִידֵי חֲכָמִים עַד שֶׁיְּקַבֵּל עָלָיו דִּבְרֵי חֲבֵרוּת:","זָקֵן וְיוֹשֵׁב בִּישִׁיבָה אֵינוֹ צָרִיךְ לְקַבֵּל שֶׁכְּבָר קִבֵּל בְּשָׁעָה שֶׁיָּשַׁב:","הַמְקַבֵּל דִּבְרֵי חֲבֵרוּת צָרִיךְ לְקַבֵּל בִּפְנֵי שְׁלֹשָׁה חֲבֵרִים. וּבָנָיו וּבְנֵי בֵּיתוֹ אֵינָן צְרִיכִין לְקַבֵּל בִּפְנֵי שְׁלֹשָׁה מִפְּנֵי שֶׁהוּא מְלַמְּדָן וּמַרְגִּילָן בְּדֶרֶךְ טָהֳרָה. וְאֵשֶׁת חָבֵר וּבָנָיו וּבְנֵי בֵּיתוֹ וַעֲבָדָיו הֲרֵי הֵן כְּחָבֵר. וְחָבֵר שֶׁמֵּת אִשְׁתּוֹ וּבָנָיו וּבְנֵי בֵּיתוֹ בְּחֶזְקַת חֲבֵרִים עַד שֶׁיֵּחָשְׁדוּ:","אֵשֶׁת עַם הָאָרֶץ אוֹ בִּתּוֹ שֶׁנִּשֵּׂאת לְחָבֵר וְכֵן עַבְדּוֹ שֶׁנִּמְכַּר לְחָבֵר הֲרֵי אֵלּוּ צְרִיכִין לְקַבֵּל עֲלֵיהֶן דִּבְרֵי חֲבֵרוּת כְּבַתְּחִלָּה. אֲבָל אֵשֶׁת חָבֵר אוֹ בִּתּוֹ שֶׁנִּשֵּׂאת לְעַם הָאָרֶץ וְכֵן עַבְדּוֹ שֶׁנִּמְכַּר לְעַם הָאָרֶץ אֵין צְרִיכִין לְקַבֵּל דִּבְרֵי חֲבֵרוּת כְּבַתְּחִלָּה:","עַם הָאָרֶץ שֶׁקִּבֵּל עָלָיו דִּבְרֵי חֲבֵרוּת וְהָיוּ לוֹ טָהֳרוֹת כְּשֶׁהָיָה עַם הָאָרֶץ וְאָמַר אֲנִי יוֹדֵעַ וַדַּאי שֶׁלֹּא נִטְמְאוּ בִּזְמַן שֶׁנִּתְעַסְּקוּ בָּהֶן אֲחֵרִים הֲרֵי הֵן אֲסוּרוֹת כְּמִקֹּדֶם וְאִם הוּא בְּעַצְמוֹ נִתְעַסֵּק בָּהֶן הֲרֵי הֵן מֻתָּרוֹת לוֹ וַאֲסוּרוֹת לְכָל אָדָם. וְנִשְׁאַל הֶחָבֵר עַל טָהֳרוֹתָיו וּמוֹרֶה בָּהֶן טָהֳרָה לְעַצְמוֹ וְאֵין חוֹשְׁדִין אוֹתוֹ בְּכָךְ:","חָבֵר שֶׁנַּעֲשָׂה גַּבַּאי לַמֶּלֶךְ אוֹ מוֹכְסָן וְכַיּוֹצֵא בָּהֶן דּוֹחִין אוֹתוֹ מֵחֲבֵרוּתוֹ. פֵּרַשׁ מִמַּעֲשָׂיו הָרָעִים הֲרֵי הוּא כְּכָל אָדָם וְצָרִיךְ לְקַבֵּל דִּבְרֵי חֲבֵרוּת כְּבַתְּחִלָּה:","עַם הָאָרֶץ שֶׁקִּבֵּל עָלָיו דִּבְרֵי חֲבֵרוּת וְנֶחְשָׁד לְדָבָר אֶחָד אֵינוֹ חָשׁוּד אֶלָּא לְאוֹתוֹ דָּבָר. וְכָל הֶחָשׁוּד לֶחָמוּר נֶחְשָׁד עַל הַקַּל. לַקַּל לֹא נֶחְשָׁד לֶחָמוּר:","חָבֵר שֶׁנֶּחְשָׁד עַל הַטָּהֳרוֹת כְּגוֹן שֶׁמָּכַר אֳכָלִין טְמֵאִין בְּחֶזְקַת שֶׁהֵן טְהוֹרִין הֲרֵי זֶה אֵינוֹ נֶאֱמָן לְעוֹלָם עַד שֶׁיִּוָּדַע שֶׁחָזַר בִּתְשׁוּבָה גְּמוּרָה:","הֶחָשׁוּד עַל הַשְּׁבִיעִית אוֹ עַל הַתְּרוּמָה שֶׁמְּכָרָן לְשֵׁם חֻלִּין הֲרֵי זֶה חָשׁוּד עַל הַטָּהֳרוֹת שֶׁהֶחָשׁוּד עַל דָּבָר שֶׁל תּוֹרָה הֲרֵי הוּא חָשׁוּד עַל דִּבְרֵי סוֹפְרִים. וְהָאֳכָלִין הַטְּמֵאִין אֵין מְטַמְּאִין אֲחֵרִים אֶלָּא מִדִּבְרֵיהֶן כְּמוֹ שֶׁיִּתְבָּאֵר. וְכָל הֶחָשׁוּד עַל דָּבָר נֶאֱמָן לְהָעִיד בּוֹ לַאֲחֵרִים וְלָדוּן בּוֹ לַאֲחֵרִים. חֲזָקָה הִיא שֶׁאֵין אָדָם חוֹטֵא כְּדֵי שֶׁיֵּהָנוּ בּוֹ אֲחֵרִים:"],"Mishneh Torah, Tithes 1":["אַחַר שֶׁמַּפְרִישִׁין תְּרוּמָה גְּדוֹלָה מַפְרִישׁ אֶחָד מֵעֲשָׂרָה מִן הַנִּשְׁאָר וְזֶהוּ הַנִּקְרָא מַעֲשֵׂר רִאשׁוֹן וּבוֹ נֶאֱמַר (במדבר יח כד) \"כִּי אֶת מַעְשַׂר בְּנֵי יִשְׂרָאֵל אֲשֶׁר יָרִימוּ לַה'\" וְגוֹ'. וְהַמַּעֲשֵׂר הַזֶּה לִלְוִיִּים זְכָרִים וּנְקֵבוֹת שֶׁנֶּאֱמַר (במדבר יח כא) \"וְלִבְנֵי לֵוִי הִנֵּה נָתַתִּי כָּל מַעֲשֵׂר בְּיִשְׂרָאֵל לְנַחֲלָה\":","מַעֲשֵׂר רִאשׁוֹן מֻתָּר בַּאֲכִילָה לְיִשְׂרָאֵל וּמֻתָּר לְאָכְלוֹ בְּטֻמְאָה שֶׁאֵין בּוֹ קְדֻשָּׁה כְּלָל. וְכָל מָקוֹם שֶׁנֶּאֱמַר בְּמַעַשְׂרוֹת קֹדֶשׁ אוֹ פְּדִיָּה אֵינוֹ אֶלָּא מַעֲשֵׂר שֵׁנִי. וּמִנַּיִן שֶׁמַּעֲשֵׂר רִאשׁוֹן חֻלִּין שֶׁנֶּאֱמַר (במדבר יח כז) \"וְנֶחְשַׁב לָכֶם תְּרוּמַתְכֶם כַּדָּגָן מִן הַגֹּרֶן וְכַמְלֵאָה מִן הַיָּקֶב\" מָה גֹּרֶן וְיֶקֶב חֻלִּין לְכָל דָּבָר אַף מַעֲשֵׂר רִאשׁוֹן שֶׁנִּטְּלָה תְּרוּמָתוֹ חֻלִּין לְכָל דָּבָר. לְפִיכָךְ בַּת לֵוִי שֶׁנִּשְׁבֵּית אוֹ שֶׁנִּבְעֲלָה בְּעִילַת זְנוּת נוֹתְנִין לָהּ הַמַּעֲשֵׂר וְאוֹכֶלֶת. אֲבָל מִי שֶׁשָּׁמְעָה שֶׁמֵּת בַּעְלָהּ אוֹ הֵעִיד לָהּ עֵד אֶחָד וְנִסֵּת וְאַחַר כָּךְ בָּא בַּעְלָהּ קָנְסוּ אוֹתָהּ חֲכָמִים שֶׁתִּהְיֶה אֲסוּרָה בְּמַעֲשֵׂר:","לְוִיִּים וְכֹהֲנִים מַפְרִישִׁין מַעֲשֵׂר רִאשׁוֹן כְּדֵי לְהַפְרִישׁ מִמֶּנּוּ תְּרוּמַת מַעֲשֵׂר. וְכֵן הַכֹּהֲנִים מַפְרִישִׁין שְׁאָר תְּרוּמוֹת וּמַעַשְׂרוֹת לְעַצְמָן. וּלְפִי שֶׁהַכֹּהֲנִים נוֹטְלִין מִן הַכּל יָכוֹל יֹאכְלוּ פֵּרוֹתֵיהֶן בְּטִבְלָן תַּלְמוּד לוֹמַר (במדבר יח כח) \"כֵּן תָּרִימוּ גַּם אַתֶּם\" מִפִּי הַשְּׁמוּעָה לָמְדוּ אַתֶּם אֵלּוּ הַלְוִיִּם גַּם אַתֶּם לְרַבּוֹת אֶת הַכֹּהֲנִים:","אֵין מוֹצִיאִין הַמַּעֲשֵׂר מִיַּד הַכֹּהֲנִים שֶׁנֶּאֱמַר (במדבר יח כו) \"כִּי תִקְחוּ מֵאֵת בְּנֵי יִשְׂרָאֵל\" וְכֵן כָּל מַתְּנוֹת כְּהֻנָּה אֵין מוֹצִיאִין אוֹתָן מִכֹּהֵן לְכֹהֵן. וְעֶזְרָא קָנַס אֶת הַלְוִיִּם בִּזְמַנּוֹ שֶׁלֹּא יִתְּנוּ לָהֶן מַעֲשֵׂר רִאשׁוֹן אֶלָּא יִנָּתֵן לַכֹּהֲנִים לְפִי שֶׁלֹּא עָלוּ עִמּוֹ לִירוּשָׁלַיִם:","הָאוֹכֵל פֵּרוֹתָיו טְבָלִין וְכֵן לֵוִי שֶׁאָכַל הַמַּעֲשֵׂר בְּטִבְלוֹ אַף עַל פִּי שֶׁהֵן חַיָּבִין מִיתָה לַשָּׁמַיִם אֵין מְשַׁלְּמִין הַמַּתָּנוֹת לְבַעֲלֵיהֶן שֶׁנֶּאֱמַר (במדבר יח כד) \"אֲשֶׁר יָרִימוּ לַה'\" אֵין לְךָ בָּהֶן כְּלוּם עַד שֶׁיָּרִימוּ אוֹתָן. וּבְחוּצָה לָאָרֶץ מֻתָּר לְאָדָם לִהְיוֹת אוֹכֵל וְהוֹלֵךְ תְּחִלָּה וְאַחַר כָּךְ מַפְרִישׁ תְּרוּמָה וּמַעַשְׂרוֹת:","מְעַשְּׂרִין מִמָּקוֹם זֶה עַל מָקוֹם אַחֵר וְאֵינוֹ צָרִיךְ לְעַשֵּׂר מִן הַמֻּקָּף. אֲבָל אֵין מְעַשְּׂרִין מִמִּין עַל שֶׁאֵינוֹ מִינוֹ וְלֹא מִן הַחַיָּב עַל הַפָּטוּר וְלֹא מִן הַפָּטוּר עַל הַחַיָּב וְאִם עִשֵּׂר אֵינוֹ מְעֻשָּׂר:","כָּל שֶׁאָמַרְנוּ בִּתְרוּמָה אֵין תּוֹרְמִין מִזֶּה עַל זֶה כָּךְ בְּמַעֲשֵׂר אֵין מְעַשְּׂרִין מִזֶּה עַל זֶה. וְכָל שֶׁאָמַרְנוּ בִּתְרוּמָה אִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה כָּךְ בְּמַעֲשֵׂר אִם הִפְרִישׁ מַעַשְׂרוֹתָיו מַעַשְׂרוֹת. וְכָל שֶׁהוּא פָּטוּר מִן הַתְּרוּמָה פָּטוּר מִן הַמַּעֲשֵׂר. וְכָל הַתּוֹרֵם מְעַשֵּׂר. כָּל שֶׁאָמַרְנוּ בָּהֶן לֹא יִתְרֹמוּ וְאִם תָּרְמוּ תְּרוּמָתָן תְּרוּמָה כָּךְ אִם עִשְּׂרוּ מַעַשְׂרוֹתֵיהֶן מַעַשְׂרוֹת. וְכָל שֶׁאֵין תְּרוּמָתוֹ תְּרוּמָה כָּךְ אֵין מַעַשְׂרוֹתֵיהֶן מַעַשְׂרוֹת:","הָאוֹמֵר לַחֲבֵרוֹ הֲרֵינִי מְעַשֵּׂר עַל יָדֶיךָ אֵינוֹ צָרִיךְ לַעֲמֹד עִמּוֹ עַד שֶׁיִּרְאֶה אִם יְעַשֵּׂר אוֹ לֹא יְעַשֵּׂר. וְאִם אָמַר הוּא לַחֲבֵרוֹ עַשֵּׂר עַל יָדִי צָרִיךְ לַעֲמֹד עִמּוֹ:","הֶחָרוּבִין אֵינָן חַיָּבִין בְּמַעַשְׂרוֹת אֶלָּא מִדִּבְרֵיהֶם. לְפִי שֶׁאֵינָן מַאֲכָל [רֹב] אָדָם. וְהַשְּׁקֵדִים הַמָּרִים בֵּין בְּגָדְלָן בֵּין בִּקְטַנָּן פְּטוּרִין לְפִי שֶׁאֵינָן אֹכֶל:","אִילָן שֶׁנְּטָעוֹ בְּתוֹךְ הַבַּיִת פָּטוּר מִמַּעַשְׂרוֹת שֶׁנֶּאֱמַר (דברים יד כב) \"עַשֵּׂר תְּעַשֵּׂר אֵת כָּל תְּבוּאַת זַרְעֶךָ הַיֹּצֵא הַשָּׂדֶה\". וְיֵרָאֶה לִי שֶׁהוּא חַיָּב בְּמַעַשְׂרוֹת מִדִּבְרֵיהֶם שֶׁהֲרֵי תְּאֵנָה הָעוֹמֶדֶת בֶּחָצֵר חַיָּב לְעַשֵּׂר פֵּרוֹתֶיהָ אִם אֲסָפָן כְּאַחַת:","בְּצָלִים שֶׁהִשְׁרִישׁוּ זֶה בְּצַד זֶה אֲפִלּוּ הִשְׁרִישׁוּ בְּקַרְקַע עֲלִיָּה פְּטוּרִין מִן הַמַּעַשְׂרוֹת. נָפְלָה עֲלֵיהֶן מַפּלֶת וַהֲרֵי הֵן מְגֻלִּין הֲרֵי אֵלּוּ כִּנְטוּעִין בַּשָּׂדֶה וְחַיָּבִין בְּמַעַשְׂרוֹת:","הַמְשַׁמֵּר שָׂדֵהוּ מִפְּנֵי עֲנָבָיו וּבָא אַחֵר וְאָסַף אֶת הַתְּאֵנִים הַנִּשְׁאָרוֹת בְּאוֹתָהּ שָׂדֶה. אוֹ שֶׁהָיָה מְשַׁמֵּר שָׂדֵהוּ מִפְּנֵי הַמִּקְשָׁאוֹת וְהַמִדְּלָעוֹת וּבָא אֶחָד וְאָסַף אֶת הָעֲנָבִים הַנִּשְׁאָרִים שָׁם הַמְפֻזָּרִים בַּשָּׂדֶה. בִּזְמַן שֶׁבַּעַל הַשָּׂדֶה מַקְפִּיד עֲלֵיהֶן אֲסוּרִין מִשּׁוּם גֵּזֶל וּלְפִיכָךְ חַיָּבִין בְּמַעֲשֵׂר וּבִתְרוּמָה. אֵין בַּעַל הַשָּׂדֶה מַקְפִּיד עֲלֵיהֶן מֻתָּרִין מִשּׁוּם גֵּזֶל וּפְטוּרִין מִן הַמַּעֲשֵׂר:","אֵין מְעַשְּׂרִין אֶלָּא מִן הַמֻּבְחָר שֶׁנֶּאֱמַר (במדבר יח ל) \"בַּהֲרִימְכֶם אֶת חֶלְבּוֹ מִמֶּנּוּ וְנֶחְשַׁב לָכֶם כִּתְבוּאַת גֹּרֶן וְכִתְבוּאַת יָקֶב\". כְּשֵׁם שֶׁמַּעֲשֵׂר שֶׁמַּפְרִישִׁים הַלְוִיִּם מִן הַחֵלֶב שֶׁבּוֹ כָּךְ מַעֲשֵׂר שֶׁמַּפְרִישִׁים יִשְׂרָאֵל מִן הַגֹּרֶן וּמִן הַיֶּקֶב מִן הַחֵלֶב שֶׁבּוֹ:","אֵין מְעַשְּׂרִין בְּאֹמֶד אֶלָּא בְּמִדָּה אוֹ בְּמִשְׁקָל אוֹ בְּמִנְיָן. וְכָל הַמְדַקְדֵּק בַּשִּׁעוּר מְשֻׁבָּח. וְהַמַּרְבֶּה בְּמַעַשְׂרוֹת מַעַשְׂרוֹתָיו מְקֻלְקָלִין שֶׁהֲרֵי הַטֶּבֶל מְעֹרָב בָּהֶן. וּפֵרוֹתָיו מְתֻקָּנִין:","הַמַּפְרִישׁ מִקְצָת מַעֲשֵׂר אֵינוֹ מְעַשֵּׂר אֶלָּא כְּמִי שֶׁחָלַק אֶת הָעֲרֵמָה. אֲבָל צָרִיךְ [לְהַפְרִישׁ] מִזֶּה הַחֵלֶק שֶׁיּוֹצִיא מַעֲשֵׂר שֶׁלּוֹ. כֵּיצַד. הָיוּ לוֹ מֵאָה סְאָה הִפְרִישׁ מֵהֶם חֲמִשָּׁה לְשֵׁם מַעֲשֵׂר אֵינוֹ מַעֲשֵׂר וְאֵינוֹ יָכוֹל לְהַפְרִישׁ עַל הֶחָמֵשׁ סְאִין מַעֲשֵׂר בְּמָקוֹם אַחֵר אֶלָּא מַפְרִישׁ מֵהֶן חֲצִי סְאָה שֶׁהִיא הַמַּעֲשֵׂר שֶׁלָּהֶן:","הַמַּפְרִישׁ מַעֲשֵׂר זֶה מְבָרֵךְ תְּחִלָּה כְּדֶרֶךְ שֶׁמְּבָרְכִין עַל הַמִּצְוֹת. וְכֵן מְבָרֵךְ עַל מַעֲשֵׂר שֵׁנִי וְעַל מַעֲשַׂר עָנִי וְעַל מַעֲשֵׂר מִן הַמַּעֲשֵׂר מְבָרֵךְ עַל כָּל אֶחָד בִּפְנֵי עַצְמוֹ. וְאִם הִפְרִישׁ הַכּל זֶה אַחַר זֶה מִיָּד וְלֹא סָח בֵּינֵיהֶן כּוֹלְלָן בִּבְרָכָה אַחַת וּמְבָרֵךְ לְהַפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת:"],"Mishneh Torah, Tithes 8":["הַפֵּרוֹת שֶׁהוּרַם מֵהֶן תְּרוּמָה גְּדוֹלָה וּתְרוּמַת מַעֲשֵׂר הֵן הַנִּקְרָאִין חֻלִּין. וְאִם הִפְרִישׁ מֵהֶן שְׁאָר מַעַשְׂרוֹתֵיהֶן הֵן הַנִּקְרָאִין חֻלִּין מְתֻקָּנִין בְּכָל מָקוֹם:","טֶבֶל שֶׁנִּתְעָרֵב בְּחֻלִּין מְתֻקָּנִין מִין בְּמִינוֹ שֶׁאִי אֶפְשָׁר לְהַלֵּךְ אַחַר הַטַּעַם. אִם יֵשׁ לוֹ פֵּרוֹת אֲחֵרוֹת מוֹצִיא עַל אוֹתוֹ טֶבֶל תְּרוּמָה וּמַעַשְׂרוֹת לְפִי חֶשְׁבּוֹן. וְאִם אֵין לוֹ פֵּרוֹת אֲחֵרוֹת לְהוֹצִיא עַל אוֹתוֹ טֶבֶל הֲרֵי הַכּל אָסוּר עַד שֶׁיַּפְרִישׁ. וּכְשֶׁהוּא מַפְרִישׁ מַפְסִיד מִן הַחֻלִּין הַמְתֻקָּנִין כְּדֵי תְּרוּמַת מַעֲשֵׂר שֶׁבַּטֶּבֶל:","כֵּיצַד. מֵאָה סְאָה שֶׁל טֶבֶל שֶׁנִּתְעָרֵב בְּמֵאָה סְאָה שֶׁל חֻלִּין מְתֻקָּנִין מַפְרִישׁ מִן הַכּל אֶחָד וּמֵאָה. וְכָל שֶׁהִפְרִישׁ טֶבֶל וְיִשָּׁאֵר צ\"ט חֻלִּין מְתֻקָּנִין נִמְצָא מַפְסִיד סְאָה אַחַת. וְכֵן אִם הָיָה אוֹתוֹ טֶבֶל טָבוּל לִתְרוּמָה מַפְסִיד מִן הַחֻלִּין הַמְתֻקָּנִין כְּדֵי תְּרוּמָה וּתְרוּמַת מַעֲשֵׂר. וְלָמָּה מַפְסִיד סְאָה זוֹ כְּדֵי שֶׁלֹּא יֹאמַר מֵאָה שֶׁהִפְרִישׁ הֵן מֵאָה שֶׁל חֻלִּין וְהַמֵּאָה שֶׁנִּשְׁאֲרוּ הוּא הַטֶּבֶל. וְכֵן אִם הָיָה הַטֶּבֶל פָּחוֹת מִן הַחֻלִּין אוֹ מְרֻבֶּה עַל הַחֻלִּין מַגְבִּיהַּ הַטֶּבֶל וּכְדֵי תְּרוּמַת מַעֲשֵׂר שֶׁבַּטֶּבֶל מִן הַחֻלִּין אוֹ כְּדֵי תְּרוּמָה וּתְרוּמַת מַעֲשֵׂר אִם הָיָה הַטֶּבֶל טָבוּל לִתְרוּמָה:","וְכֵן אִם נִתְעָרֵב מַעֲשֵׂר טָבוּל בְּחֻלִּין מְתֻקָּנִין אוֹסֵר בְּכָל שֶׁהוּא. אִם יֵשׁ לוֹ מַעֲשֵׂר אַחֵר מוֹצִיא אוֹתוֹ עַל מַעֲשֵׂר הַטָּבוּל תְּרוּמַת מַעֲשֵׂר לְפִי חֶשְׁבּוֹן. וְאִם אֵין לוֹ מַעֲשֵׂר מַגְבִּיהַּ הַמַּעֲשֵׂר שֶׁנִּתְעָרֵב וּמַפְסִיד מִן הַחֻלִּין הַמְתֻקָּנִין כְּדֵי תְּרוּמַת מַעֲשֵׂר שֶׁבַּמַעֲשֵׂר הַטָּבוּל:","כֵּיצַד. מֵאָה מַעֲשֵׂר שֶׁנִּתְעָרֵב בְּמֵאָה חֻלִּין מְתֻקָּנִין מַפְרִישׁ מִן הַכּל מֵאָה וְעֶשֶׂר וְכָל שֶׁהִפְרִישׁ מַעֲשֵׂר וְהַתִּשְׁעִים הַנִּשְׁאָרוֹת הֵן חֻלִּין כְּשֶׁהָיוּ. וְכֵן אִם הָיוּ הַחֻלִּין מְרֻבִּין עַל הַמַּעֲשֵׂר הַטָּבוּל אוֹ פְּחוּתִים מִמֶּנּוּ מַפְרִישׁ הַמַּעֲשֵׂר וּכְדֵי תְּרוּמַת מַעֲשֵׂר שֶׁבַּמַעֲשֵׂר הַטָּבוּל מִן הַחֻלִּין:","טֶבֶל שֶׁנִּתְעָרֵב בְּמַעֲשֵׂר טָבוּל אִם הָיָה הַטֶּבֶל כַּמַעֲשֵׂר מַפְסִיד מִן הַטֶּבֶל כְּדֵי תְּרוּמַת מַעֲשֵׂר שֶׁבּוֹ. כֵּיצַד. מֵאָה סְאָה טֶבֶל שֶׁנִּתְעָרֵב בְּמֵאָה סְאָה מַעֲשֵׂר מַפְרִישׁ אֶחָד וּמֵאָה וְזֶה שֶׁהִפְרִישׁ מַעֲשֵׂר וְתִשְׁעִים וְתֵשַׁע הַנִּשְׁאָרוֹת טֶבֶל. הָיָה הַטֶּבֶל מְרֻבֶּה עַל הַמַּעֲשֵׂר מַפְרִישׁ הַמַּעֲשֵׂר בִּלְבַד. וְלֹא יַפְסִיד מִן הַטֶּבֶל כְּלוּם שֶׁאִם יִקְרָא שֵׁם לִתְרוּמַת מַעֲשֵׂר שֶׁנִּטְבַּל נִמְצָא הַמַּעֲשֵׂר מְדֻמָּע בִּתְרוּמַת מַעֲשֵׂר שֶׁל טֶבֶל שֶׁעָלְתָה עִמּוֹ. הָיָה הַמַּעֲשֵׂר מְרֻבֶּה עַל הַטֶּבֶל קוֹרֵא שֵׁם לִתְרוּמַת מַעֲשֵׂר [שֶׁבַּטֶּבֶל] וּמַפְרִישׁ הַטֶּבֶל וּכְדֵי תְּרוּמַת מַעֲשֵׂר שֶׁל טִבְלוֹ אֶחָד מִמֵּאָה מִן הַמַּעֲשֵׂר וְיִהְיֶה הַטֶּבֶל כֻּלּוֹ מְדֻמָּע וְיִמְכְּרֶנָּה לְכֹהֵן חוּץ מִדְּמֵי שְׁתֵּי תְּרוּמוֹת שֶׁבּוֹ וְנִמְצָא מַפְסִיד מִן הַמַּעֲשֵׂר אֶחָד מִמֵּאָה שֶׁבּוֹ שֶׁהוּא כְּמוֹ תְּרוּמַת מַעֲשֵׂר שֶׁבַּטֶּבֶל. כֵּיצַד. מֵאָה טֶבֶל עִם מָאתַיִם מַעֲשֵׂר מַפְרִישׁ מֵאָה וְשָׁלֹשׁ וְהַשָּׁלֹשׁ הֵן תְּרוּמַת מַעֲשֵׂר שֶׁל מֵאָה טֶבֶל וְשִׁעוּר תְּרוּמַת מַעֲשֵׂר מִמָּאתַיִם כְּדֵי שֶׁלֹּא יָבוֹא לִטְעוֹת אִם נִתְעָרְבוּ בִּכְמוֹתוֹ וְיִשָּׁאֵר קצ\"ז וְהֵם מַעֲשֵׂר כְּשֶׁהָיוּ:","מִי שֶׁהָיוּ לוֹ עֶשֶׂר שׁוּרוֹת שֶׁל עֶשֶׂר עֶשֶׂר כַּדֵּי יַיִן וְקָבַע כַּד אֶחָד מִשּׁוּרָה הַחִיצוֹנָה מַעֲשֵׂר עַל מָקוֹם אַחֵר וְאֵין יָדוּעַ אֵי זוֹ שׁוּרָה הַחִיצוֹנָה הִיא. נוֹטֵל שְׁתֵּי חָבִיּוֹת בַּאֲלַכְסוֹן וּמְעָרֵב שְׁתֵּיהֶן וּמַפְרִישׁ מֵהֶן:","קְבָעָהּ בַּחֲצִי שׁוּרָה הַחִיצוֹנָה וְאֵין יָדוּעַ אֵי זוֹ חֲצִי שׁוּרָה הִיא נוֹטֵל אַרְבַּע חָבִיּוֹת מֵאַרְבַּע זָוִיּוֹת. קְבָעָהּ בְּשׁוּרָה אַחַת מֵהֶן וְאֵין יָדוּעַ אֵי זוֹ שׁוּרָה הִיא נוֹטֵל שׁוּרָה אַחַת בַּאֲלַכְסוֹן. קְבָעָהּ בַּחֲצִי שׁוּרָה וְאֵין יָדוּעַ אֵי זוֹ חֲצִי שׁוּרָה הִיא נוֹטֵל שְׁתֵּי שׁוּרוֹת בַּאֲלַכְסוֹן שֶׁהֲרֵי נָטַל חָבִית מִכָּל חֲצִי שׁוּרָה וּמְעָרֵב וּמַפְרִישׁ:","קָבַע הַמַּעֲשֵׂר בְּכַד אַחַת מֵהֶן וְאֵין יָדוּעַ אֵי זוֹ הִיא נוֹטֵל מִכָּל כַּד וְכַד מִן הַמֵּאָה וּמְעָרֵב וּמַפְרִישׁ כְּדֵי כַּד אַחַת וּמְעַשֵּׂר:"],"Mishneh Torah, Transmission of the Oral Law 12":["רַבֵּנוּ הַקָּדוֹשׁ חִבַּר הַמִּשְׁנָה. וּמִיְּמוֹת מֹשֶׁה וְעַד רַבֵּנוּ הַקָּדוֹשׁ, לֹא חִבְּרוּ חִבּוּר שֶׁמְּלַמְּדִין אוֹתוֹ בָּרַבִּים בְּתוֹרָה שֶׁבְּעַל פֶּה; אֵלָא בְּכָל דּוֹר וָדוֹר, רֹאשׁ בֵּית דִּין אוֹ נָבִיא שֶׁיִּהְיֶה בְּאוֹתוֹ הַדּוֹר, כּוֹתֵב לְעַצְמוֹ זִכָּרוֹן בַּשְּׁמוּעוֹת שֶׁשָּׁמַע מֵרִבּוֹתָיו, וְהוּא מְלַמֵּד עַל פֶּה בָּרַבִּים."],"Mishneh Torah, Transmission of the Oral Law 23":["רַבִּינָא וְרָב אַשֵׁי, הֶם סוֹף חַכְמֵי הַתַּלְמוּד; וְרָב אַשֵׁי הוּא שֶׁחִבַּר הַתַּלְמוּד הַבַּבְלִי בְּאֶרֶץ שִׁנְעָר, אַחַר שֶׁחִבַּר רִבִּי יוֹחָנָן הַתַּלְמוּד הַיְּרוּשְׁלְמִי בִּכְמוֹ מֵאָה שָׁנָה."],"Mishneh Torah, Transmission of the Oral Law 34":["וּדְבָרִים הַלָּלוּ, בְּדִינִים וּגְזֵרוֹת וְתַקָּנוֹת וּמִנְהָגוֹת שֶׁנִּתְחַדְּשׁוּ אַחַר חִבּוּר הַתַּלְמוּד. אֲבָל כָּל הַדְּבָרִים שֶׁבַּתַּלְמוּד הַבַּבְלִי, חַיָּבִין כָּל בֵּית יִשְׂרָאֵל לָלֶכֶת בָּהֶם; וְכוֹפִין כָּל עִיר וְעִיר וְכָל מְדִינָה וּמְדִינָה לִנְהֹג בְּכָל הַמִּנְהָגוֹת שֶׁנָּהֲגוּ חֲכָמִים שֶׁבַּתַּלְמוּד, וְלִגְזֹר גְּזֵרוֹתָם וְלָלֶכֶת בְּתַקָּנוֹתָם."],"Mishneh Torah, Transmission of the Oral Law 45":["וּמִנְיַן מִצְווֹת שֶׁלַּתּוֹרָה הַנּוֹהֲגוֹת לְדוֹרוֹת, שֵׁשׁ מֵאוֹת וּשְׁלוֹשׁ עֶשְׂרֵה מִצְווֹת: מֵהֶן מִצְווֹת עֲשֵׂה מָאתַיִם שְׁמוֹנֶה וְאַרְבָּעִים, סִימָן לָהֶן מִנְיַן אֵבָרָיו שֶׁלָּאָדָם; וּמֵהֶן מִצְווֹת לֹא תַעֲשֶׂה שְׁלוֹשׁ מֵאוֹת חָמֵשׁ וְשִׁשִּׁים, סִימָן לָהֶן מִנְיַן יְמוֹת הַחַמָּה."],"Mishneh Torah, Trespass 7":["מִי שֶׁשָּׁגַג וְלָקַח הֶקְדֵּשׁ אוֹ מְעוֹת הֶקְדֵּשׁ וּנְתָנוֹ לְשָׁלִיחַ לְהוֹצִיאוֹ בְּתוֹרַת חֻלִּין. אִם עָשָׂה הַשָּׁלִיחַ שְׁלִיחוּתוֹ הַמְשַׁלֵּחַ הוּא שֶׁמָּעַל. וְאִם לֹא עָשָׂה שְׁלִיחוּתוֹ אֶלָּא עָשָׂה הַשָּׁלִיחַ מִדַּעַת עַצְמוֹ הַשָּׁלִיחַ הוּא שֶׁמָּעַל. כֵּיצַד. בַּעַל הַבַּיִת שֶׁאָמַר לִשְׁלוּחוֹ תֵּן (לִי) מֵאוֹתוֹ בָּשָׂר לָאוֹרְחִין הָלַךְ וְנָתַן לָהֶן כִּכָּר. אוֹ שֶׁאָמַר לוֹ תֵּן לָהֶן כִּכָּר וְנָתַן לָהֶן בָּשָׂר. אָמַר לִשְׁלוּחוֹ הָבֵא לִי מִן הַחַלּוֹן וְהֵבִיא לוֹ מִן הַמִּגְדָּל. אוֹ שֶׁאָמַר לוֹ הָבֵא מִן הַמִּגְדָּל וְהֵבִיא לוֹ מִן הַחַלּוֹן. הַשָּׁלִיחַ מָעַל. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. הָלַךְ הַשָּׁלִיחַ וְהֵבִיא מִן הַחַלּוֹן כְּמוֹ שֶׁאָמַר לוֹ אַף עַל פִּי שֶׁאָמַר הַשּׁוֹלֵחַ לֹא הָיָה בְּלִבִּי שֶׁיָּבִיא אֶלָּא מִן הַמִּגְדָּל בַּעַל הַבַּיִת מָעַל. שֶׁהֲרֵי עָשָׂה שְׁלִיחוּת מַאֲמָרוֹ וּדְבָרִים שֶׁבַּלֵּב אֵינָן דְּבָרִים. וַאֲפִלּוּ הָיָה הַשָּׁלִיחַ חֵרֵשׁ אוֹ שׁוֹטֶה אוֹ קָטָן שֶׁאֵין לָהֶן שְׁלִיחוּת אִם עָשָׂה כְּמַאֲמָרוֹ בַּעַל הַבַּיִת מָעַל וְאִם לֹא עָשָׂה שְׁלִיחוּתוֹ בַּעַל הַבַּיִת פָּטוּר. אָמַר לִשְׁלוּחוֹ תֵּן לָאוֹרְחִין חֲתִיכָה חֲתִיכָה שֶׁל בָּשָׂר הָלַךְ הַשָּׁלִיחַ וְאָמַר לָהֶן טלוּ שְׁתַּיִם שְׁתַּיִם. בַּעַל הַבַּיִת מָעַל שֶׁהֲרֵי נַעֲשָׂה דְּבָרוֹ וְהַשָּׁלִיחַ פָּטוּר מִפְּנֵי שֶׁהוּא מוֹסִיף עַל שְׁלִיחוּת בַּעַל הַבַּיִת וְלֹא עָקַר הַשְּׁלִיחוּת. אֲבָל אִם אָמַר לָהֶם הַשָּׁלִיחַ טלוּ שְׁתַּיִם שְׁתַּיִם מִדַּעְתִּי שְׁנֵיהֶן מָעֲלוּ. נָטְלוּ הָאוֹרְחִים שָׁלֹשׁ שָׁלֹשׁ אַף הָאוֹרְחִין מָעֲלוּ מִפְּנֵי שֶׁכָּל אֶחָד מֵהֶן עָשָׂה שְׁלִיחוּת חֲבֵרוֹ וְהוֹסִיף מִדַּעְתּוֹ. נִמְצָא חֲבֵרוֹ חַיָּב לְפִי שֶׁנַּעֲשׂוּ דְּבָרָיו וְלֹא נֶעֶקְרָה הַשְּׁלִיחוּת וְהוּא חַיָּב עַל זֶה שֶׁהוֹסִיף מִדַּעְתּוֹ:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ הַחֲתִיכוֹת מִקָּדְשֵׁי בֶּדֶק הַבַּיִת. אֲבָל אִם הָיוּ בְּשַׂר עוֹלָה וְכַיּוֹצֵא בּוֹ לֹא מָעַל אֶלָּא הָאוֹכֵל בִּלְבַד שֶׁהֲרֵי הוּא חַיָּב בְּאִסּוּר אַחֵר יֶתֶר עַל הַמְּעִילָה. וּבְכָל הַתּוֹרָה כֻּלָּהּ אֵין שָׁלִיחַ לִדְבַר עֲבֵרָה אֶלָּא בִּמְעִילָה לְבַדָּהּ שֶׁלֹּא יִתְעָרֵב עִמָּהּ אִסּוּר אַחֵר:","הַנּוֹתֵן פְּרוּטַת הֶקְדֵּשׁ לִשְׁלוּחוֹ וְאָמַר לוֹ הָבֵא לִי בְּחֶצְיָהּ נֵרוֹת וּבְחֶצְיָהּ פְּתִילוֹת. הָלַךְ וְהֵבִיא לוֹ בְּכֻלָּהּ נֵרוֹת אוֹ בְּכֻלָּהּ פְּתִילוֹת. אוֹ שֶׁאָמַר לוֹ הָבֵא לִי בְּכֻלָּהּ נֵרוֹת אוֹ בְּכֻלָּהּ פְּתִילוֹת הָלַךְ וְהֵבִיא בְּחֶצְיָהּ נֵרוֹת וּבְחֶצְיָהּ פְּתִילוֹת שְׁנֵיהֶם פְּטוּרִים. בַּעַל הַבַּיִת לֹא מָעַל שֶׁהֲרֵי לֹא נַעֲשָׂה שְׁלִיחוּתוֹ בִּפְרוּטָה. וְהַשָּׁלִיחַ לֹא מָעַל שֶׁהֲרֵי לֹא עָקַר שְׁלִיחוּתוֹ בִּפְרוּטָה. אֲבָל אִם אָמַר לוֹ הָבֵא לִי בְּחֶצְיָהּ נֵרוֹת מִמָּקוֹם פְּלוֹנִי וּבְחֶצְיָהּ פְּתִילוֹת מִמָּקוֹם פְּלוֹנִי וְהָלַךְ וְהֵבִיא נֵרוֹת מִמְּקוֹם פְּתִילוֹת וּפְתִילוֹת מִמְּקוֹם נֵרוֹת הַשָּׁלִיחַ מָעַל:","נָתַן לוֹ שְׁתֵּי פְּרוּטוֹת וְאָמַר לוֹ הָבֵא לִי אֶתְרוֹג וְהָלַךְ וְהֵבִיא לוֹ בִּפְרוּטָה אֶתְרוֹג וּבִפְרוּטָה רִמּוֹן. הַשָּׁלִיחַ מָעַל וּבַעַל הַבַּיִת פָּטוּר שֶׁהֲרֵי שְׁלָחוֹ לִקְנוֹת לוֹ אֶתְרוֹג שֶׁשָּׁוֶה שְׁתֵּי פְּרוּטוֹת. לְפִיכָךְ אִם הָיָה הָאֶתְרוֹג שֶׁהֵבִיא לוֹ בִּפְרוּטָה אַחַת שָׁוֶה שְׁתֵּי פְּרוּטוֹת שְׁנֵיהֶם מָעֲלוּ:","הַשּׁוֹלֵחַ פְּרוּטָה בְּיַד שְׁלוּחוֹ לִקְנוֹת לוֹ בָּהּ חֵפֶץ וְנִזְכַּר בַּעַל הַבַּיִת שֶׁהִיא הֶקְדֵּשׁ קֹדֶם שֶׁתַּגִּיעַ לְיַד הַחֶנְוָנִי הַשָּׁלִיחַ מָעַל שֶׁהוּא שׁוֹגֵג וּבַעַל הַבַּיִת כְּבָר נִזְכַּר וְאֵין הַמֵּזִיד חַיָּב בְּקָרְבַּן מְעִילָה כְּמוֹ שֶׁבֵּאַרְנוּ. נִזְכַּר אַף הַשָּׁלִיחַ וְיָדַע שֶׁהִיא הֶקְדֵּשׁ קֹדֶם שֶׁתַּגִּיעַ לַחֶנְוָנִי שְׁנֵיהֶם פְּטוּרִים מִקָּרְבַּן מְעִילָה וְהַחֶנְוָנִי חַיָּב כְּשֶׁיּוֹצִיא אוֹתָהּ פְּרוּטָה שֶׁנִּתְעָרְבָה בִּמְעוֹתָיו שֶׁהֲרֵי הוּא שׁוֹגֵג. הוֹדִיעוּ לְחֶנְוָנִי שֶׁפְּרוּטָה שֶׁנָּתְנוּ לוֹ הֶקְדֵּשׁ שְׁלָשְׁתָּן פְּטוּרִין וְנִתְפַּס הַמִּקָּח לַהֶקְדֵּשׁ:","וְכֵיצַד יַעֲשֶׂה כְּדֵי לְהַצִּיל הַחֶנְוָנִי מִן הַחֵטְא עַד שֶׁיִּהְיֶה מֻתָּר לְהִשְׁתַּמֵּשׁ בְּכָל הַמָּעוֹת. נוֹטֵל פְּרוּטָה שֶׁל חֻלִּין אוֹ כְּלִי כָּל שֶׁהוּא וְאוֹמֵר פְּרוּטָה שֶׁל הֶקְדֵּשׁ בְּכָל מָקוֹם שֶׁהִיא מְחֻלֶּלֶת עַל זֶה. וְתֵעָשֶׂה אוֹתָהּ פְּרוּטָה אוֹ הַכְּלִי הֶקְדֵּשׁ וְיֻתַּר הַחֶנְוָנִי לְהִשְׁתַּמֵּשׁ בְּכָל הַמָּעוֹת. וְכֵן פְּרוּטָה שֶׁל הֶקְדֵּשׁ שֶׁנִּתְעָרְבָה בְּכָל הַכִּיס אוֹ שֶׁאָמַר פְּרוּטָה בְּכִיס זֶה הֶקְדֵּשׁ. מְחַלֵּל אוֹתָהּ וְאַחַר כָּךְ יִשְׁתַּמֵּשׁ בַּכִּיס. וְאִם הוֹצִיא וְלֹא חִלֵּל לֹא מָעַל עַד שֶׁיּוֹצִיא אֶת כָּל הַכִּיס:","אָמַר כִּיס מִכִּיסַי הֶקְדֵּשׁ וְשׁוֹר מִשְּׁוָרַי הֶקְדֵּשׁ. מוֹעֲלִין בְּכֻלָּן וּמוֹעֲלִין בְּמִקְצָתָן. כֵּיצַד עוֹשֶׂה. מֵבִיא אֶת הַגָּדוֹל שֶׁבָּהֶם וְאוֹמֵר אִם הֶקְדֵּשׁ הוּא הֲרֵי הוּא הֶקְדֵּשׁ וְאִם לָאו הַהֶקְדֵּשׁ בְּכָל מָקוֹם שֶׁהוּא מְחֻלָּל עַל זֶה. וִיהַנֶּה בַּקָּטָן:","הַמּוֹעֵל בְּפָחוֹת מִשְּׁוֵה פְּרוּטָה בֵּין בְּזָדוֹן בֵּין בִּשְׁגָגָה מְשַׁלֵּם אֶת הַקֶּרֶן וְאֵינוֹ חַיָּב חֹמֶשׁ וְלֹא קָרְבָּן. וְיֵרָאֶה לִי שֶׁאֵינוֹ לוֹקֶה עַל פָּחוֹת מִשְּׁוֵה פְּרוּטָה אִם הָיָה מֵזִיד:","הַמַּפְקִיד מָעוֹת אֵצֶל בַּעַל הַבַּיִת וְנִשְׁתַּמֵּשׁ בָּהֶן וְהוֹצִיא. בַּעַל הַבַּיִת מָעַל. שֶׁהֲרֵי אֵין לוֹ רְשׁוּת לְהִשְׁתַּמֵּשׁ בָּהֶן וּבַעַל הַפִּקָּדוֹן לֹא הִרְשָׁהוּ:","הִפְקִידָן אֵצֶל שֻׁלְחָנִי אוֹ חֶנְוָנִי וְלֹא הָיוּ חֲתוּמִין וְלֹא קְשׁוּרִין קֶשֶׁר מְשֻׁנֶּה הוֹאִיל וְיֵשׁ לוֹ רְשׁוּת מִן הַדִּין לְהִשְׁתַּמֵּשׁ בָּהֶן אִם הוֹצִיאוּ שְׁנֵיהֶן פְּטוּרִין. בַּעַל הַפִּקָּדוֹן פָּטוּר שֶׁהֲרֵי לֹא אָמַר לוֹ הִשְׁתַּמֵּשׁ בָּהֶן. וְהַחֶנְוָנִי פָּטוּר מִפְּנֵי שֶׁאֵינָן קְשׁוּרִין קֶשֶׁר מְשֻׁנֶּה וְלֹא חֲתוּמִין וּכְאִלּוּ הִשְׁתַּמֵּשׁ בִּרְשׁוּת:","הָאִשָּׁה שֶׁהִכְנִיסָה מָעוֹת שֶׁל הֶקְדֵּשׁ לְבַעְלָהּ. אוֹ שֶׁהִקְדִּישׁ מוֹרִישָׁהּ וּמֵת וְנָפְלוּ לָהּ הֶקְדֵּשׁוֹת בִּירֻשָּׁה. לִכְשֶׁיּוֹצִיא הַבַּעַל הַמָּעוֹת בַּחֲפָצָיו יִמְעל:"],"Mishneh Torah, Vessels 19":["כַּמָּה שִׁעוּר הַשֶּׁבֶר שֶׁיִּשָּׁבֵר כְּלִי חֶרֶס וְיִטְהַר מִטֻּמְאָתוֹ אִם הָיָה טָמֵא. אוֹ לֹא יְקַבֵּל טֻמְאָה אִם הָיָה טָהוֹר. הֶעָשׂוּי לָאֳכָלִין מִשֶּׁיִּנָּקֵב בְּמוֹצִיא זֵיתִים. וְהֶעָשׂוּי לְמַשְׁקִין מִשֶּׁיִּנָּקֵב בְּמַכְנִיס מַשְׁקִין, כְּשֶׁמַּנִּיחִין אוֹתוֹ עַל הַמַּשְׁקֶה יִכָּנֵס הַמַּשְׁקֶה לַכְּלִי בַּנֶּקֶב. הֶעָשׂוּי לְכָךְ וּלְכָךְ מְטִילִין אוֹתוֹ לְחֻמְרוֹ וַהֲרֵי הוּא מְקַבֵּל טֻמְאָה עַד שֶׁיִּנָּקֵב בְּמוֹצִיא זַיִת. וְלֹא אָמְרוּ בְּמוֹצִיא מַשְׁקֶה אֶלָּא בְּגִסְטְרָא בִּלְבַד לְפִי שֶׁהִיא עֲשׂוּיָה לְקַבֵּל הַמַּשְׁקִין הַנּוֹזְלִים מִן הַכֵּלִים וְאִם הוֹצִיאָה מַשְׁקִין הֲרֵי זֶה בָּטֵל תַּשְׁמִישָׁהּ:","חָמֵשׁ מִדּוֹת בִּכְלִי חֶרֶס. נִקַּב בְּמוֹצִיא מַשְׁקֶה טָהוֹר מִלְּהִתְטַמֵּא מִשּׁוּם גִּסְטְרָא וַעֲדַיִן הוּא חָשׁוּב כְּלִי לְקַדֵּשׁ בּוֹ מֵי חַטָּאת. נִקַּב בְּכוֹנֵס מַשְׁקֶה אֵינוֹ רָאוּי לְקַדֵּשׁ בּוֹ מֵי חַטָּאת וַעֲדַיִן כְּלִי הוּא חָשׁוּב לְהַכְשִׁיר הַזְּרָעִים בְּמַשְׁקִין הַתְּלוּשִׁין בּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. נִקַּב כְּשֹׁרֶשׁ קָטָן אֵין הַמַּיִם שֶׁבְּתוֹכוֹ מַכְשִׁירִין אֶת הַזְּרָעִים וַהֲרֵי הֵן כְּמוֹ שֶׁאֵינָן בַּכְּלִי וַעֲדַיִן כְּלִי הוּא חָשׁוּב לְקַבֵּל בּוֹ זֵיתִים וּמְקַבֵּל טֻמְאָה. נִקַּב בְּמוֹצִיא זֵיתִים טָהוֹר וַהֲרֵי הוּא כִּכְלֵי גְּלָלִים וַאֲבָנִים שֶׁאֵין מְקַבְּלִין טֻמְאָה וַעֲדַיִן כְּלִי הוּא חָשׁוּב לְהַצִּיל בְּצָמִיד פָּתִיל עַד שֶׁיִּפָּחֵת רֻבּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ בְּטֻמְאַת מֵת (בְּפֶרֶק שְׁנֵים עָשָׂר):","הֶחָבִית שִׁעוּרָהּ כֶּאֱגוֹזִים. הָאִלְפָּס וְהַקְּדֵרָה שִׁעוּרָן כְּזֵיתִים. וְכֵן עֲרֵבָה שֶׁל חֶרֶס אֲפִלּוּ הָיְתָה גְּדוֹלָה וּמַחְזֶקֶת אַרְבָּעִים סְאָה בְּלַח וְנִפְחֲתָה בְּמוֹצִיא זֵיתִים אַף עַל פִּי שֶׁהוּא מַטָּהּ עַל צִדָּה וְלָשׁ בָּהּ טְהוֹרָה שֶׁמִּתְּחִלָּתָהּ לֹא נַעֲשֵׂית לְכָךְ:","הַפַּךְ וְהַטֶּנִי שִׁעוּרָן בְּשֶׁמֶן. וְהַצַּרְצוּר שִׁעוּרוֹ בְּמַיִם:","נֵר שֶׁנִּטַּל פִּיו טָהוֹר. וְשֶׁל אֲדָמָה שֶׁהֻסַּק פִּיו בִּפְתִילָה אֵינוֹ מְקַבֵּל טֻמְאָה וְאֵינוֹ בִּכְלַל כְּלֵי חֶרֶס עַד שֶׁיֻּסַּק כֻּלּוֹ בַּכִּבְשָׁן כִּכְלֵי חֶרֶס:","חָבִית שֶׁנִּפְחֲתָה וּכְשֶׁמַּטִּין אוֹתָהּ עַל דָּפְנָהּ מְקַבֶּלֶת אוֹ שֶׁנֶּחְלְקָה כְּמִין שְׁתֵּי עֲרֵבוֹת עֲדַיִן הִיא מְקַבֶּלֶת טֻמְאָה. נִתְרַעְעָה וְאֵינָהּ יְכוֹלָה לְהִטַּלְטֵל בַּחֲצִי קַב גְּרוֹגָרוֹת טְהוֹרָה:","חָבִית שֶׁנִּטְּלוּ אָזְנֶיהָ הֲרֵי הִיא כְּגִסְטְרָא אֲפִלּוּ אֹזֶן אַחַת. נִסְדְּקָה לְמַטָּה מֵאָזְנֶיהָ אַף עַל פִּי שֶׁאָזְנֶיהָ קַיָּמוֹת הֲרֵי זוֹ כְּגִסְטְרָא. וְאִם עֲשָׂאָהּ מִתְּחִלָּה שֶׁלֹּא בְּאָזְנַיִם נִדּוֹנֶת כְּחָבִית:","חָבִית שֶׁנִּסְדְּקָה בַּכִּבְשָׁן וְנִמְצָא שֶׁהִיא כִּשְׁתֵּי גִּסְטְרָאוֹת. אִם מִשֶּׁנִּגְמְרָה מְלַאכְתָּהּ נִסְדְּקָה כָּל גִּסְטְרָא מֵהֶן מְקַבֶּלֶת טֻמְאָה. וְאִם נִסְדְּקָה קֹדֶם שֶׁתִּגָּמֵר מְלַאכְתָּהּ וְאַחַר כָּךְ נִשְׂרְפָה בַּכִּבְשָׁן טְהוֹרָה. וְהֵיאַךְ יִוָּדַע דָּבָר זֶה. אִם הָיוּ שְׁבָרֶיהָ שָׁוִין וְתוֹכָהּ מַאֲדִים עַד שֶׁלֹּא נִגְמְרָה מְלַאכְתָּהּ נִסְדְּקָה. אֵין שְׁבָרֶיהָ שָׁוִין וְאֵין תּוֹכָהּ מַאֲדִים בְּיָדוּעַ שֶׁאַחַר שֶׁנִּגְמְרָה מְלַאכְתָּהּ נִשְׁבְּרָה וּמְקַבֶּלֶת טֻמְאָה כִּשְׁאָר שִׁבְרֵי כְּלֵי חֶרֶס הָרְאוּיִין לְתַשְׁמִישׁ:","גִּסְטְרָא שֶׁנִּתְרַעְעָה וְאֵינָהּ מְקַבֶּלֶת מַשְׁקִין אַף עַל פִּי שֶׁמְּקַבֶּלֶת אֳכָלִין הֲרֵי זוֹ טְהוֹרָה שֶׁאֵינָהּ עֲשׂוּיָה אֶלָּא לְקַבֵּל מַשְׁקִין הַדּוֹלְפִין כְּמוֹ שֶׁבֵּאַרְנוּ וְאִם הָיְתָה דּוֹלֶפֶת אֵין עוֹשִׂין גִּסְטְרָא לְגִסְטְרָא. וְכֵן גִּסְטְרָא שֶׁנִּפְחֲתָה אוֹ שֶׁנֶּחְלְקָה לִשְׁתַּיִם טְהוֹרָה שֶׁלֹּא אָמְרוּ שְׁיָרִים שֶׁל שְׁיָרִים מִתְטַמְּאִין אֶלָּא שְׁיָרֵי כְּלֵי חֶרֶס בִּלְבַד הֵן שֶׁמִּתְטַמְּאִין:","גִּסְטְרָא שֶׁחִדּוּדִין יוֹצְאִין מִמֶּנָּה בֵּין שֶׁהָיְתָה יוֹשֶׁבֶת בֵּין שֶׁהָיְתָה מֻטָּה עַל צִדָּהּ כָּל הַמְקַבֵּל מִן הַחִדּוּדִין זֵיתִים כְּשֶׁיִּתְמַלֵּא הַגִּסְטְרָא זֵיתִים מְטַמֵּא בְּמַגָּע וּכְנֶגְדוֹ מִתְטַמֵּא בָּאֲוִיר וְכָל שֶׁאֵין מְקַבֵּל עִמָּהּ בְּזֵיתִים מִתְטַמֵּא בְּמַגָּע וְאֵין כְּנֶגְדּוֹ מִתְטַמֵּא בָּאֲוִיר:","כֵּיצַד מִתְטַמֵּא בְּמַגָּע וְאֵין כְּנֶגְדּוֹ מִתְטַמֵּא בָּאֲוִיר. שֶׁאִם נָגְעָה הַטֻּמְאָה בַּגִּסְטְרָא מִתּוֹכָהּ מִתְטַמֵּא הַחִדּוּד. נִכְנְסָה הַטֻּמְאָה בַּאֲוִיר הַגִּסְטְרָא אֲפִלּוּ הָיְתָה כְּנֶגֶד הַחִדּוּד לֹא נִטְמָא הַחִדּוּד:","וְכֵיצַד כְּנֶגְדּוֹ מִתְטַמֵּא בָּאֲוִיר. שֶׁאִם הָיְתָה הַטֻּמְאָה בַּאֲוִיר הַגִּסְטְרָא כְּנֶגֶד הַחִדּוּד נִטְמָא הַחִדּוּד עִם הַגִּסְטְרָא. וְעַל דֶּרֶךְ זֶה הוּא בְּכָל מָקוֹם שֶׁנֶּאֱמַר (במדבר ה יז) \"בִּכְלִי חֶרֶס\" וּבְתַנּוּר וְכִירַיִם מִתְטַמֵּא בְּמַגָּע וּכְנֶגְדוֹ בָּאֲוִיר אוֹ אֵין מִתְטַמֵּא כְּנֶגְדּוֹ בָּאֲוִיר. וְכֵן כָּל טֻמְאַת מַגָּע הָאֲמוּרָה בְּעִנְיַן כְּלִי חֶרֶס אוֹ תַּנּוּר וְכִירַיִם הוּא שֶׁתִּגַּע הַטֻּמְאָה בָּהֶן מִתּוֹכָן וְכָל טֻמְאַת אֲוִיר הוּא שֶׁלֹּא תִּגַּע הַטֻּמְאָה כְּלָל אֶלָּא תִּכָּנֵס לָאֲוִיר בִּלְבַד:","חָבִית שֶׁנִּתְרַעְעָה וּטְפָלָהּ בִּגְלָלִים אַף עַל פִּי שֶׁהוּא נוֹטֵל אֶת הַגְּלָלִים וְהַחֲרָסִים נוֹפְלִים הֲרֵי זוֹ מְקַבֶּלֶת טֻמְאָה מִפְּנֵי שֶׁלֹּא בָּטַל שֵׁם כְּלִי מֵעָלֶיהָ. נִשְׁבְּרָה וְדִבֵּק חֲרָסֶיהָ אַחַר שֶׁפֵּרְשׁוּ אוֹ שֶׁהֵבִיא חֲרָסִים מִמָּקוֹם אַחֵר וּטְפָלָם בִּגְלָלִים אַף עַל פִּי שֶׁנּוֹטֵל אֶת הַגְּלָלִים וַחֲרָסֶיהָ עוֹמְדִין הֲרֵי זוֹ טְהוֹרָה מִפְּנֵי שֶׁבָּטַל מֵעָלֶיהָ שֵׁם כְּלִי. הָיָה בָּהֶן חֶרֶס מַחֲזִיק רְבִיעִית כְּנֶגֶד אוֹתוֹ הַחֶרֶס בִּלְבַד מִתְטַמֵּא בָּאֲוִיר מִפְּנֵי שֶׁהוּא כְּלִי בִּפְנֵי עַצְמוֹ. וּשְׁאָר הֶחָבִית אֵינוֹ מִתְטַמֵּא עַד שֶׁתִּגַּע בָּהּ הַטֻּמְאָה מִתּוֹכָהּ מִפְּנֵי שֶׁאֵינָהּ כְּלִי שָׁלֵם:","חָבִית שֶׁנִּקְּבָה וְסָתַם הַנֶּקֶב בְּזֶפֶת וְאַחַר כָּךְ נִשְׁבְּרָה אִם יֵשׁ בַּחֶרֶס הַסָּתוּם בְּזֶפֶת כְּדֵי לְהַחֲזִיק רְבִיעִית הֲרֵי זֶה מְקַבֵּל טֻמְאָה מִפְּנֵי שֶׁהוּא מִשִּׁבְרֵי הֶחָבִית וְלֹא בָּטַל שֵׁם כְּלִי מֵעָלֶיהָ. אֲבָל חֶרֶס שֶׁנִּקַּב אַחַר שֶׁפֵּרַשׁ מִן הַכְּלִי וְסָתַם הַנֶּקֶב בְּזֶפֶת אַף עַל פִּי שֶׁהוּא מַחֲזִיק רְבִיעִית טָהוֹר. שֶׁהַחֶרֶס שֶׁנִּקַּב בָּטַל שֵׁם כְּלִי מֵעָלָיו וְטָהַר וְכָל שֶׁטָּהַר בִּכְלִי חֶרֶס שָׁעָה אַחַת אֵין לוֹ טֻמְאָה לְעוֹלָם:","קוּמְקוּמוֹס שֶׁנִּקַּב וַעֲשָׂאָהוּ בְּזֶפֶת טָהוֹר שֶׁאֵינוֹ יָכוֹל לְקַבֵּל הַחַמִּין כְּצוֹנֵן. וְכֵן כְּלֵי הַזֶּפֶת וְהַשַּׁעֲוָה וְכַיּוֹצֵא בָּהֶן טְהוֹרִין וְאֵינָן בִּכְלַל הַכֵּלִים:","מַשְׁפֵּךְ שֶׁל חֶרֶס שֶׁפְּקָקוֹ בְּזֶפֶת אֵינוֹ מְקַבֵּל טֻמְאָה שֶׁאֵין הַזֶּפֶת מְשִׂימוֹ כְּלִי קִבּוּל. אֲבָל מַשְׁפֵּךְ שֶׁל עֵץ שֶׁסְּתָמוֹ הֲרֵי זֶה כִּכְלִי קִבּוּל וּמִתְטַמֵּא:"],"Mishneh Torah, Vessels 4":["שָׁלֹשׁ מִדּוֹת בִּכְלֵי עֵץ שֶׁאֵינָן עֲשׂוּיִין לְקַבָּלָה. כָּל כְּלִי עֵץ הֶעָשׂוּי לְתַשְׁמִישׁ אָדָם בִּלְבַד כְּגוֹן הַסֻּלָּם טָהוֹר וְאֵינוֹ מְקַבֵּל טֻמְאָה כְּלָל וְלֹא רִבּוּהוּ חֲכָמִים לְטֻמְאָה. וְכָל כְּלִי עֵץ הֶעָשׂוּי לְתַשְׁמִישׁ הַכֵּלִים וְהָאָדָם כְּגוֹן הַשֻּׁלְחָן וְהַטַּבְלָא וְהַמִּטָּה וְכַיּוֹצֵא בָּהֶן מְקַבְּלִין טֻמְאָה. וּמִנַּיִן שֶׁהֵן לְתַשְׁמִישׁ אָדָם וְתַשְׁמִישׁ מְשַׁמְּשָׁיו שֶׁהֲרֵי מַנִּיחַ הַקְּעָרוֹת עַל הַשֻּׁלְחָן וְהַכּוֹסוֹת עַל הַטַּבְלָא וְהַמַּצָּעוֹת עַל הַמִּטָּה. וְכָל כְּלִי עֵץ הֶעָשׂוּי לְתַשְׁמִישׁ הַכֵּלִים בִּלְבַד שֶׁהֲרֵי הוּא מְשַׁמֵּשׁ מְשַׁמְּשֵׁי אָדָם אִם לֹא הָיָה מְשַׁמֵּשׁ אֶת הַכֵּלִים אֶלָּא בִּשְׁעַת מְלָאכָה בִּלְבַד הֲרֵי זֶה טָהוֹר מִכְּלוּם כְּגוֹן מְנוֹרָה שֶׁל עֵץ שֶׁמְּשַׁמֶּשֶׁת הַנֵּר בִּשְׁעַת הַדְלָקָה, וְכַן וְהוּא כְּלִי שֶׁמַּנִּיחִין תַּחַת הַכֵּלִים בִּשְׁעַת מְלָאכָה, וְהַדְּפוּסִין כֻּלָּן. וְאִם הָיָה מְשַׁמֵּשׁ אֶת הַכֵּלִים בִּשְׁעַת מְלָאכָה וְשֶׁלֹּא בִּשְׁעַת מְלָאכָה הֲרֵי זֶה מְקַבֵּל טֻמְאָה כְּגוֹן כִּסּוּי הַקַּפָצָה וְכַיּוֹצֵא בּוֹ וְתִיק הַסַּיִף וְהַסַּכִּין וְהָרֹמַח וְהַמִּסְפָּרִים וְהַתַּעַר וְהַמִּכְחוֹל וְהַמִּכְתָּב וּבֵית הַכּוֹחַל וְתִיק טַבְלָא וּסְקוּרְטִיָא וּבֵית הַחִצִּים וּבֵית הַפַּגוֹזוֹת וְתִיק חֲלָלִים כָּל אֵלּוּ וְכַיּוֹצֵא בָּהֶן אַף עַל פִּי שֶׁאֵינָן אֶלָּא מְשַׁמְּשֵׁי כֵּלִים מְקַבְּלִין טֻמְאָה שֶׁהֲרֵי הַכְּלִי צָרִיךְ לָהֶן בִּשְׁעַת מְלָאכָה וְשֶׁלֹּא בִּשְׁעַת מְלָאכָה. אֲבָל כִּסּוּי קַמַטְרָא וְכִסּוּי תֵּבָה וְכִסּוּי טֶנִי וְהַמַּכְבֵּשׁ שֶׁל חָרָשׁ וְהַכִּסֵּא שֶׁתַּחַת הַתֵּבָה וְהַקְּמָתִין שֶׁלָּהּ וְהַקֵּלֶב שֶׁבּוֹנִין עָלָיו תִּיק הַסַּפָּר וּבֵית הַנֶּגֶר וְהַמַּנְעוּל וְהַמְּזוּזָה וְתִיק נְבָלִים וְהַכִּנּוֹרוֹת וְהַקֵּלֶב שֶׁל גּוֹדְלֵי מִצְנֶפֶת וּדְפוּס שֶׁל תְּפִלִּין וְסוּס שֶׁל עֵץ שֶׁל זֶמֶר שֶׁמְּשַׂחֲקִין בּוֹ וּרְבִיעִית הַמְּקוֹנֶנֶת וּגְנוֹנַת הֶעָנִי וְסָמוֹכוֹת הַמִּטָּה וְנַקְלִיטֵי הַמִּטָּה וַחֲמוֹר שֶׁתַּחַת הַמִּטָּה כָּל אֵלּוּ וְכַיּוֹצֵא בָּהֶן טְהוֹרִין מִפְּנֵי שֶׁהֵן מְשַׁמְּשֵׁי הַכֵּלִים בִּשְׁעַת מְלָאכָה בִּלְבַד:","מַלְבֵּן הַמִּטָּה אִם הָיָה מְלֻבָּשׁ בְּפִיקוֹת וְיֵשׁ לוֹ רַגְלַיִם שֶׁמְּחַבְּרָן עִם הַמִּטָּה הֲרֵי זֶה מִתְטַמֵּא עִם הַמִּטָּה שֶׁהֲרֵי נוֹתְנִין אוֹתוֹ בִּפְנֵי הַמִּטָּה וַהֲרֵי הוּא כְּאֶחָד מֵאֵיבָרֶיהָ. נְתָנוֹ עַל שְׁתֵּי לְשׁוֹנוֹת וַהֲרֵי הוּא גָּבוֹהַּ עַל הַמִּטָּה אַף עַל פִּי שֶׁמְּסֹרָג בַּחֲבָלִים הוֹאִיל וְאֵין לוֹ רַגְלַיִם טָהוֹר מִפְּנֵי שֶׁהוּא מִמְּשַׁמְּשֵׁי הַכֵּלִים בִּשְׁעַת מְלָאכָה בִּלְבַד כְּמַלְבְּנֵי בְּנֵי לֵוִי שֶׁתּוֹלִין בָּהֶם כִּנּוֹרוֹתֵיהֶן וּכְלֵי הַשֵּׁיר שֶׁהֵן טְהוֹרִין:","מַכְבֵּשׁ שֶׁל שְׁכַּף שֶׁמּוֹתֵחַ עָלָיו אֶת הָעוֹר טָהוֹר מִפְּנֵי שֶׁמַּנִּיחַ עָלָיו אֶת הָאֶבֶן בַּמָּקוֹם הֶחָקוּק שֶׁיֵּשׁ בּוֹ וּמְשַׁמֵּשׁ עָלָיו וְנִמְצָא עָשׂוּי לְשַׁמֵּשׁ אֶת הַכֵּלִים בִּשְׁעַת מְלָאכָה וְאֵינוֹ מִתְטַמֵּא מִשּׁוּם קִבּוּל שֶׁהֲרֵי הֶחָקָק שֶׁבּוֹ עָשׂוּי לְהִתְמַלְּאוֹת בְּאֶבֶן:","חִפּוּיֵי הַמִּטָּה טְהוֹרִין וְכֵן כָּל הַחִפּוּיִין בֵּין שֶׁהָיוּ שֶׁל עֵץ אוֹ שֶׁל עֶצֶם אוֹ שֶׁל עוֹר אוֹ שֶׁל מַתֶּכֶת טְהוֹרִין שֶׁנֶּאֱמַר (ויקרא יא לב) \"אֲשֶׁר יֵעָשֶׂה מְלָאכָה בָּהֶן\" פְּרָט לְחִפּוּיֵי הַכֵּלִים. וְכֵן כְּלֵי עֵץ אוֹ עֶצֶם שֶׁיֵּשׁ בָּהֶן בֵּית קִבּוּל שֶׁצִּפָּם בְּמַתֶּכֶת טְהוֹרִים וְאֵין מְקַבְּלִין טֻמְאָה מֵאַחַר שֶׁצִּפָּם בִּטְּלָן וְהַצִּפּוּי עַצְמוֹ טָהוֹר כְּמוֹ שֶׁבֵּאַרְנוּ:","הָעוֹשֶׂה כְּלִי מִקְצָתוֹ מִן הָעֵץ וּמִקְצָתוֹ מִן הַמַּתֶּכֶת אִם הָיָה הָעֵץ מְשַׁמֵּשׁ הַמַּתֶּכֶת מְקַבֵּל טֻמְאָה וְאִם הָיְתָה הַמַּתֶּכֶת מְשַׁמֶּשֶׁת אֶת הָעֵץ הַכּל טָהוֹר. כֵּיצַד. מַפְתֵּחַ שֶׁל עֵץ וְשִׁנָּיו מִמַּתֶּכֶת אֲפִלּוּ שֵׁן אֶחָד הֲרֵי זֶה מְקַבֵּל טֻמְאָה. הָיְתָה הִיא מִמַּתֶּכֶת וְשִׁנַּיִם שֶׁלּוֹ מֵעֵץ הַכּל טָהוֹר:","טַבַּעַת שֶׁל מַתֶּכֶת וְחוֹתָמָהּ שֶׁל אַלְמוֹג טְמֵאָה. הָיְתָה שֶׁל אַלְמוֹג וְחוֹתָמוֹ שֶׁל מַתֶּכֶת הֲרֵי זוֹ אֵינָהּ מְקַבֶּלֶת טֻמְאָה:","הַשֵּׁן שֶׁל מַתֶּכֶת אוֹ הַחוֹתָם מְקַבֵּל טֻמְאָה בִּפְנֵי עַצְמוֹ אִם לֹא הָיָה מְחֻבָּר לָעֵץ. וְכֵן הַמְעַבֵּד וְהַמַּזְרֶה וְהַמָּגוֹב וְהַמַּסְרֵק שֶׁל רֹאשׁ שֶׁנִּטְּלָה אֶחָד מִשִּׁנֵּיהֶן וַעֲשָׂאָהּ שֶׁל מַתֶּכֶת הֲרֵי אֵלּוּ מְקַבְּלִין טֻמְאָה:","מַקֵּל שֶׁעָשָׂה בְּרֹאשׁוֹ מַסְמֵר כְּמִין רִמּוֹן כְּדֵי שֶׁיִּהְיֶה אוֹחֵז בּוֹ אֵינוֹ מְקַבֵּל טֻמְאָה. עֲשָׂאָהוּ שֶׁלֹּא תִּהְיֶה הָאָרֶץ אוֹכֶלֶת אֶת הָעֵץ מְקַבֵּל טֻמְאָה:","וְכֵן מַקֵּל שֶׁקָּבַע בּוֹ מַסְמְרִים כְּדֵי לְהַכּוֹת בּוֹ מְקַבֵּל טֻמְאָה שֶׁנִּמְצָא הָעֵץ מְשַׁמֵּשׁ אֶת הַמַּתֶּכֶת. עֲשָׂאָן לְנוֹי אֵינוֹ מְקַבֵּל טֻמְאָה שֶׁהֲרֵי הַמַּתֶּכֶת מְשַׁמֶּשֶׁת אֶת הָעֵץ:","וְכֵן מְנַקִּיּוֹת שֶׁל מַתֶּכֶת שֶׁקְּבָעָן בַּמַּקֵּל אוֹ בַּדֶּלֶת לְנוֹי טְהוֹרוֹת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה מִשְּׁאָר הַכֵּלִים:"],"Mishneh Torah, Vessels of the Sanctuary and Those Who Serve Therein 6":["אִי אֶפְשָׁר שֶׁיִּהְיֶה קָרְבָּנוֹ שֶׁל אָדָם קָרֵב וְהוּא אֵינוֹ עוֹמֵד עַל גַּבָּיו. וְקָרְבְּנוֹת הַצִּבּוּר הֵן קָרְבָּן שֶׁל כָּל יִשְׂרָאֵל וְאִי אֶפְשָׁר שֶׁיִּהְיוּ יִשְׂרָאֵל כֻּלָּן עוֹמְדִין בָּעֲזָרָה בִּשְׁעַת קָרְבָּן. לְפִיכָךְ תִּקְּנוּ נְבִיאִים הָרִאשׁוֹנִים שֶׁיִּבְרְרוּ מִיִּשְׂרָאֵל כְּשֵׁרִים וִירֵאֵי חֵטְא וְיִהְיוּ שְׁלוּחֵי כָּל יִשְׂרָאֵל לַעֲמֹד עַל הַקָּרְבָּנוֹת וְהֵם הַנִּקְרָאִים אַנְשֵׁי מַעֲמָד. וְחִלְּקוּ אוֹתָם כ\"ד מַעֲמָדוֹת כְּמִנְיַן מִשְׁמְרוֹת כְּהֻנָּה וּלְוִיָּה. וְעַל כָּל מַעֲמָד וּמַעֲמָד אֶחָד מֵהֶן מְמֻנֶּה עַל כֻּלָּם וְהוּא נִקְרָא רֹאשׁ הַמַּעֲמָד:","בְּכָל שַׁבָּת וְשַׁבָּת מִתְקַבְּצִין אַנְשֵׁי מַעֲמָד שֶׁל אוֹתָהּ שַׁבָּת. מִי שֶׁהָיָה מֵהֶן בִּירוּשָׁלַיִם אוֹ קָרוֹב לָהּ נִכְנָסִין לַמִּקְדָּשׁ עִם מִשְׁמַר כְּהֻנָּה וּלְוִיָּה שֶׁל אוֹתָהּ שַׁבָּת. וְהָרְחוֹקִים שֶׁבְּאוֹתוֹ מַעֲמָד כֵּיוָן שֶׁהִגִּיעַ מַעֲמָד שֶׁלָּהֶן הֵן מִתְקַבְּצִין לְבֵית הַכְּנֶסֶת שֶׁבִּמְקוֹמָן:","וּמַה הֵן עוֹשִׂין אֵלּוּ הַמִּתְקַבְּצִין בֵּין בִּירוּשָׁלַיִם בֵּין בְּבָתֵּי כְּנֵסִיּוֹת. מִתְעַנִּין בְּשֵׁנִי בַּשַּׁבָּת שֶׁלָּהֶן. וּבִשְׁלִישִׁי וּבִרְבִיעִי וּבַחֲמִישִׁי. אֲבָל בְּעֶרֶב שַׁבָּת לֹא הָיוּ מִתְעַנִּין מִפְּנֵי כְּבוֹד שַׁבָּת וּבְאֶחָד בְּשַׁבָּת אֵינָם מִתְעַנִּים כְּדֵי שֶׁלֹּא יֵצְאוּ מֵעֹנֶג שַׁבָּת לְצוֹם:","וּבְכָל יוֹם וְיוֹם מִשַּׁבָּת שֶׁהָיָה מַעֲמָדָן מִתְפַּלְּלִין אַרְבַּע תְּפִלּוֹת שַׁחֲרִית וּמִנְחָה וּנְעִילָה וְעוֹד מוֹסִיפִין תְּפִלָּה אַחֶרֶת בֵּין שַׁחֲרִית וּמִנְחָה וְהִיא יְתֵרָה לָהֶן. וְנוֹשְׂאִין כַּפֵּיהֶן הַכֹּהֲנִים בַּמַעֲמָד שָׁלֹשׁ פְּעָמִים בְּכָל יוֹם בְּשַׁחֲרִית וּבַתְּפִלָּה זוֹ הַיְתֵרָה וּבִנְעִילָה. וְקוֹרִין בְּסֵפֶר תּוֹרָה שְׁלֹשָׁה אֲנָשִׁים שְׁתֵּי פְּעָמִים בְּכָל יוֹם בְּשַׁחֲרִית וּבַתְּפִלָּה הַשְּׁנִיָּה שֶׁמּוֹסִיפִין אֲבָל בְּמִנְחָה לֹא הָיוּ קוֹרִין בְּסֵפֶר תּוֹרָה אֶלָּא עַל פֶּה כְּקוֹרְאִין אֶת שְׁמַע. וְלֹא הָיוּ מִתְקַבְּצִין לִתְפִלַּת מִנְחָה בְּעֶרֶב שַׁבָּת מִפְּנֵי שֶׁהֵן טְרוּדִין לְשַׁבָּת:","וְקִבּוּצָן לְכָל תְּפִלָּה מֵאַרְבַּע תְּפִלּוֹת אֵלּוּ וַעֲמִידָתָן שָׁם לִתְפִלָּה וְלִתְחִנָּה וּלְבַקָּשָׁה וְלִקְרוֹת בַּתּוֹרָה נִקְרָא מַעֲמָד:","וּבַמֶּה הָיוּ קוֹרְאִין בְּמַעֲשֵׂה בְּרֵאשִׁית. בַּיּוֹם הָרִאשׁוֹן קוֹרְאִין בְּרֵאשִׁית וִיהִי רָקִיעַ. בַּשֵּׁנִי יְהִי רָקִיעַ וְיִקָּווּ. בִּשְׁלִישִׁי יִקָּווּ וִיהִי מְאֹרֹת. בִּרְבִיעִי (בראשית א יד) \"יְהִי מְאֹרֹת\" (בראשית א כ) \"וְיִשְׁרְצוּ\". בַּחֲמִישִׁי יִשְׁרְצוּ (בראשית א כד) \"וְתוֹצֵא הָאָרֶץ\". בְּשִׁשִּׁי תּוֹצֵא הָאָרֶץ (בראשית ב א) \"וַיְכֻלּוּ\":","פָּרָשָׁה גְּדוֹלָה קוֹרְאִין אוֹתָהּ בִּשְׁנַיִם וּקְטַנָּה קוֹרֵא אוֹתָהּ אֶחָד. וּשְׁתֵּי פָּרָשִׁיּוֹת שֶׁקּוֹרְאִין שַׁחֲרִית הֵם שֶׁחוֹזְרִין וְקוֹרִין אוֹתָן בִּתְפִלָּה הַשְּׁנִיָּה בַּסֵּפֶר. וְחוֹזְרִין וְקוֹרְאִין אוֹתָן בַּמִּנְחָה עַל פֶּה:","שְׁמוֹנַת יְמֵי חֲנֻכָּה לֹא הָיוּ אַנְשֵׁי מַעֲמָד עוֹשִׂין מַעֲמָד בְּשַׁחֲרִית. וְכָל יוֹם שֶׁיֵּשׁ בּוֹ קָרְבַּן מוּסָף לֹא הָיָה בּוֹ מַעֲמָד לֹא בִּתְפִלָּה שְׁנִיָּה שֶׁלָּהֶם וְלֹא בַּמִּנְחָה. אֶלָּא בְּשַׁחֲרִית וּבִנְעִילָה בִּלְבַד. וְכָל יוֹם שֶׁהָיָה בּוֹ קָרְבַּן הָעֵצִים לֹא הָיָה בּוֹ מַעֲמָד בִּנְעִילָה אֶלָּא בְּשַׁחֲרִית וּבִתְפִלָּה שְׁנִיָּה וּבְמִנְחָה:","וּמַהוּ קָרְבַּן הָעֵצִים. זְמַן קָבוּעַ הָיָה לְמִשְׁפָּחוֹת מִשְׁפָּחוֹת לָצֵאת לַיְעָרִים לְהָבִיא עֵצִים לַמַּעֲרָכָה. וְיוֹם שֶׁיַּגִּיעַ לִבְנֵי מִשְׁפָּחָה זוֹ לְהָבִיא הָעֵצִים הָיוּ מַקְרִיבִין עוֹלוֹת נְדָבָה וְזֶהוּ קָרְבַּן הָעֵצִים וְהָיָה לָהֶם כְּמוֹ יוֹם טוֹב. וַאֲסוּרִין בּוֹ בְּהֶסְפֵּד וּבְתַעֲנִית וּבַעֲשִׂיַּת מְלָאכָה וְדָבָר זֶה מִנְהָג:","אֲפִלּוּ יָחִיד שֶׁהִתְנַדֵּב עֵצִים אוֹ גְּזָרִים בַּמַּעֲרָכָה אָסוּר בְּאוֹתוֹ הַיּוֹם בְּהֶסְפֵּד וּבְתַעֲנִית וּבַעֲשִׂיַּת מְלָאכָה וְדָבָר זֶה מִנְהָג:","אַנְשֵׁי מַעֲמָד אֲסוּרִין מִלְּסַפֵּר וּמִלְּכַבֵּס כָּל שַׁבָּת שֶׁלָּהֶן. וּבַחֲמִישִׁי מֻתָּרִין מִפְּנֵי כְּבוֹד הַשַּׁבָּת. וּמִפְּנֵי מָה אָסְרוּ עֲלֵיהֶם לְסַפֵּר וּלְכַבֵּס כְּדֵי שֶׁלֹּא יִכָּנְסוּ לְמַעֲמָדָם כְּשֶׁהֵם מְנֻוָּלִין. אֶלָּא יְסַפְּרוּ וִיכַבְּסוּ מִקֹּדֶם:"],"Mishneh Torah, Vows 2":["אֶחָד הַנּוֹדֵר מִפִּי עַצְמוֹ אוֹ שֶׁהִדִּירוֹ חֲבֵרוֹ וְאָמַר אָמֵן אוֹ דָּבָר שֶׁעִנְיָנוֹ כְּעִנְיַן אָמֵן שֶׁהוּא קַבָּלַת דְּבָרִים:","וְאֵין הַנּוֹדֵר נֶאֱסָר בְּדָבָר שֶׁאָסַר עַל עַצְמוֹ עַד שֶׁיּוֹצִיא בִּשְׂפָתָיו וְיִהְיֶה פִּיו וְלִבּוֹ שָׁוִין כְּמוֹ שֶׁבֵּאַרְנוּ בִּשְׁבוּעוֹת. אֲבָל הַמִּתְכַּוֵּן לִנְדֹּר בְּנָזִיר וְנָדַר בְּקָרְבָּן. בְּקָרְבָּן וְנָדַר בְּנָזִיר. בִּשְׁבוּעָה וְנָדַר. אוֹ שֶׁנִּתְכַּוֵּן לִנְדֹּר וְנִשְׁבַּע. אוֹ שֶׁנִּתְכַּוֵּן לוֹמַר תְּאֵנִים וְאָמַר עֲנָבִים. הֲרֵי זֶה מֻתָּר בִּשְׁנֵיהֶם וְאֵין כָּאן נֵדֶר:","הַנּוֹדֵר עַל דַּעַת אֲחֵרִים הֲרֵי זֶה כְּנִשְׁבָּע עַל דַּעַת אֲחֵרִים. וְכֵן הַנּוֹדֵר וְחָזַר בּוֹ בְּתוֹךְ כְּדֵי דִּבּוּר אוֹ שֶׁמִּחוּ בּוֹ בְּתוֹךְ כְּדֵי דִּבּוּר וְקִבֵּל הֲרֵי זֶה מֻתָּר. וְדִין כָּל אֵלּוּ הַדְּבָרִים בִּנְדָרִים כְּדִינָן בִּשְׁבוּעוֹת:","מִי שֶׁהִתְנָה קֹדֶם שֶׁיִּדֹּר וְאָמַר כָּל נֵדֶר שֶׁאֶדֹּר מִכָּאן וְעַד עֶשֶׂר שָׁנִים הֲרֵינִי חוֹזֵר בָּהֶן אוֹ הֲרֵי הֵן בְּטֵלִים וְכַיּוֹצֵא בַּדְּבָרִים אֵלּוּ וְאַחַר כָּךְ נָדַר. אִם הָיָה זוֹכֵר הַתְּנַאי בְּשָׁעָה שֶׁנָּדַר הֲרֵי נִדְרוֹ קַיָּם שֶׁהֲרֵי בִּטֵּל הַתְּנַאי בְּנֵדֶר זֶה. וְאִם לֹא זָכַר הַתְּנַאי אֶלָּא אַחַר שֶׁנָּדַר אַף עַל פִּי שֶׁקִּבֵּל הַתְּנַאי בְּלִבּוֹ וְקִיְּמוֹ הֲרֵי הַנֵּדֶר בָּטֵל. וְאַף עַל פִּי שֶׁלֹּא הוֹצִיא עַתָּה הַחֲזָרָה בְּפִיו כְּבָר הִקְדִּים הַחֲזָרָה לַנֵּדֶר וְהוֹצִיאָהּ בְּפִיו מִקֹּדֶם. וְיֵשׁ שֶׁמּוֹרֶה לְהַחְמִיר וְאוֹמֵר וְהוּא שֶׁיִּזְכֹּר הַתְּנַאי אַחַר שֶׁנָּדַר בְּתוֹךְ כְּדֵי דִּבּוּר:","מִי שֶׁהִקְדִּים אֶת הַתְּנַאי לְשָׁנָה אוֹ לְעֶשֶׂר וְאַחַר כָּךְ נָדַר וְנִזְכַּר בְּשָׁעָה שֶׁנָּדַר שֶׁיֵּשׁ לוֹ תְּנַאי וְשָׁכַח עַל אֵי זֶה דָּבָר הִתְנָה וְכֵיצַד הָיָה הַתְּנַאי. אִם אָמַר עַל דַּעַת רִאשׁוֹנָה אֲנִי עוֹשֶׂה אֵין נִדְרוֹ נֵדֶר שֶׁהֲרֵי בִּטְּלוֹ. וְאִם לֹא אָמַר עַל דַּעַת רִאשׁוֹנָה אֲנִי עוֹשֶׂה כְּבָר בִּטֵּל הַתְּנַאי וְקִיֵּם הַנֵּדֶר שֶׁהֲרֵי זָכַר בִּשְׁעַת הַנֵּדֶר שֶׁיֵּשׁ שָׁם תְּנַאי וְאַף עַל פִּי כֵן נָדַר:","יֵשׁ מֵהַגְּאוֹנִים שֶׁאוֹמְרִים אֵין כָּל אֵלּוּ הַדְּבָרִים נוֹהֲגִין אֶלָּא בִּנְדָרִים בִּלְבַד לֹא בִּשְׁבוּעוֹת. וְיֵשׁ מִי שֶׁמּוֹרֶה שֶׁדִּין הַנְּדָרִים וְהַשְּׁבוּעוֹת בְּעִנְיָנוֹת אֵלּוּ אֶחָד הֵם. וְכִי יֵשׁ לוֹ לְהַקְדִּים תְּנַאי לִשְׁבוּעָתוֹ כְּדֶרֶךְ שֶׁאָמְרוּ בִּנְדָרִים:","סְתָם נְדָרִים לְהַחְמִיר. וּפֵרוּשָׁן יֵשׁ בּוֹ לְהָקֵל וּלְהַחְמִיר. כֵּיצַד. הָאוֹמֵר הֲרֵי הַפֵּרוֹת הָאֵלּוּ עָלַי כְּבָשָׂר מָלִיחַ וּכְיֵין נֶסֶךְ. אוֹמְרִין לוֹ וּמֶה הָיָה בְּלִבְּךָ. אִם פֵּרֵשׁ וְאָמַר כְּבָשָׂר מָלִיחַ שֶׁל קָרְבָּן וּכְיַיִן שֶׁנִּתְנַסֵּךְ עַל הַמִּזְבֵּחַ הָיָה בְּלִבִּי הֲרֵי זֶה אָסוּר. וְאִם אָמַר לֹא הָיָה בְּלִבִּי אֶלָּא תִּקְרֹבֶת עַכּוּ\"ם וְיַיִן שֶׁנִּתְנַסֵּךְ לָהּ הֲרֵי זֶה מֻתָּר. וְאִם נָדַר סְתָם הֲרֵי זֶה אָסוּר:","וְכֵן הָאוֹמֵר הֲרֵי הַפֵּרוֹת הָאֵלּוּ עָלַי חֵרֶם. אִם כְּחֵרֶם שֶׁל בֶּדֶק הַבַּיִת אָסוּר. וְאִם כְּחֶרְמֵי הַכֹּהֲנִים מֻתָּר. מִפְּנֵי שֶׁהֵן מָמוֹן שֶׁלָּהֶם וְאֵין בָּהּ אִסּוּר. וְאִם סְתָם אָסוּר:","הֲרֵי הֵן עָלַי כְּמַעֲשֵׂר. אִם כְּמַעֲשַׂר בְּהֵמָה אָסוּר מִפְּנֵי שֶׁהוּא קָרְבָּן שֶׁהִקְדִּישׁוֹ בְּיָדוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם כְּמַעֲשַׂר דָּגָן מֻתָּר וְאִם סְתָם אָסוּר:","הֲרֵי הֵן עָלַי כִּתְרוּמָה. אִם לִתְרוּמַת הַלִּשְׁכָּה נִתְכַּוֵּן הֲרֵי זֶה אָסוּר. וְאִם לִתְרוּמַת הַגֹּרֶן נִתְכַּוֵּן מֻתָּר. וְאִם סְתָם אָסוּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּמָקוֹם שֶׁמַּשְׁמָע כָּל אֶחָד מֵאֵלּוּ שָׁם שְׁנֵי עִנְיָנוֹת. אֲבָל מָקוֹם שֶׁדַּרְכָּן שֶׁאֵין קוֹרְאִים חֵרֶם סְתָם אֶלָּא לְחֶרְמֵי בֶּדֶק הַבַּיִת בִּלְבַד וְאָמַר שָׁם הֲרֵי הֵן עָלַי חֵרֶם הֲרֵי זֶה אָסוּר. וְכֵן אִם הָיָה דַּרְכָּן שֶׁאֵין קוֹרְאִים חֵרֶם סְתָם אֶלָּא לְחֶרְמֵי כֹּהֲנִים הֲרֵי זֶה מֻתָּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה שֶׁאֵין הוֹלְכִין בִּנְדָרִים אֶלָּא אַחַר לְשׁוֹן אַנְשֵׁי אוֹתוֹ מָקוֹם בְּאוֹתוֹ זְמַן:","הַנּוֹדֵר בְּחֵרֶם וְאָמַר לֹא הָיָה בְּלִבִּי אֶלָּא חֶרְמוֹ שֶׁל יָם שֶׁהִיא הַמִּכְמֹרֶת. נָדַר בְּקָרְבָּן וְאָמַר לֹא הָיָה בְּלִבִּי אֶלָּא בְּקָרְבְּנוֹת מְלָכִים. אָמַר לַחֲבֵרוֹ הֲרֵי עַצְמִי עָלֶיךָ קָרְבָּן וְאָמַר לֹא הָיָה בְּלִבִּי אֶלָּא לְאָסְרוֹ בְּעֶצֶם שֶׁהִנַּחְתִּי לִי לִהְיוֹת נוֹדֵר בּוֹ דֶּרֶךְ שְׂחוֹק. נָדַר שֶׁלֹּא תֵּהָנֶה לוֹ אִשְׁתּוֹ וְאָמַר לֹא הָיָה בְּלִבִּי אֶלָּא אִשְׁתִּי רִאשׁוֹנָה שֶׁגֵּרַשְׁתִּיהָ. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ הַדְּבָרִים שֶׁמַּשְׁמָעָן לְכָל הָעָם אִסּוּר וְהוּא אוֹמֵר לֹא נִתְכַּוַּנְתִּי אֶלָּא לְכָךְ וּלְכָךְ. אִם הָיָה הַנּוֹדֵר תַּלְמִיד חָכָם הֲרֵי זֶה מֻתָּר וְאֵין צָרִיךְ שְׁאֵלָה לְחָכָם. וְאִם הָיָה עַם הָאָרֶץ מַרְאִין בְּעֵינָיו שֶׁזֶּה נֵדֶר וְשֶׁהוּא אָסוּר וּפוֹתְחִים לוֹ פֶּתַח מִמָּקוֹם אַחֵר וּמַתִּירִין לוֹ. וּבֵין שֶׁהָיָה תַּלְמִיד חָכָם אוֹ עַם הָאָרֶץ גּוֹעֲרִין בָּהֶן וּמְלַמְּדִין אוֹתָן שֶׁלֹּא יִנְהֲגוּ מִנְהָג זֶה בִּנְדָרִים וְלֹא יִהְיוּ נוֹדְרִין דֶּרֶךְ שְׂחוֹק וְהִתּוּל:","וְכֵן הָאוֹמֵר לְאִשְׁתּוֹ הֲרֵי אַתְּ עָלַי כְּאִמִּי אוֹ הָאוֹמֵר פֵּרוֹת אֵלּוּ עָלַי כִּבְשַׂר חֲזִיר שֶׁאֵין כָּאן נֵדֶר כְּמוֹ שֶׁבֵּאַרְנוּ. אִם הָיָה הָאוֹמֵר תַּלְמִיד חָכָם אֵינוֹ צָרִיךְ שְׁאֵלָה לְחָכָם. וְאִם הָיָה עַם הָאָרֶץ צָרִיךְ שְׁאֵלָה לְחָכָם וּמַרְאִין בְּעֵינָיו שֶׁאִשְׁתּוֹ אֲסוּרָה וְשֶׁאוֹתָן הַפֵּרוֹת אֲסוּרִין וּפוֹתְחִין לוֹ פֶּתַח מִמָּקוֹם אַחֵר וּמַתִּירִין לוֹ נִדְרוֹ כְּדֵי שֶׁלֹּא יִנְהֲגוּ קַלּוּת רֹאשׁ בִּנְדָרִים:","הַהֶפְקֵר אַף עַל פִּי שֶׁאֵינוֹ נֵדֶר הֲרֵי הוּא כְּמוֹ נֵדֶר שֶׁאָסוּר לוֹ לַחְזֹר בּוֹ. וּמַה הוּא הַהֶפְקֵר הוּא שֶׁיֹּאמַר אָדָם נְכָסִים אֵלּוּ הֶפְקֵר לַכּל. בֵּין בְּמִטַּלְטְלִין בֵּין בְּקַרְקָעוֹת. וְכֵיצַד דִּין הַהֶפְקֵר. כָּל הַקּוֹדֵם וְזָכָה בּוֹ קָנָהוּ לְעַצְמוֹ וְנַעֲשָׂה שֶׁלּוֹ. וַאֲפִלּוּ זֶה שֶׁהִפְקִיר דִּינוֹ בּוֹ כְּדִין כָּל אָדָם אִם קָדַם וְזָכָה בּוֹ קָנָהוּ:","הַמַּפְקִיר לַעֲנִיִּים אֲבָל לֹא לַעֲשִׁירִים אֵינוֹ הֶפְקֵר עַד שֶׁיַּפְקִיר לַכּל כִּשְׁמִטָּה. והַמַּפְקִיר עֲבָדָיו הַגְּדוֹלִים קָנוּ עַצְמָן. וְהַקְּטַנִּים כָּל הַקּוֹדֵם וְהֶחֱזִיק בָּהֶן זָכָה כִּשְׁאָר הַמִּטַּלְטְלִין:","הַמַּפְקִיר אֶת הַקַּרְקַע כָּל הַקּוֹדֵם וְהֶחֱזִיק בָּהּ זָכָה. דִּין תּוֹרָה אֲפִלּוּ הִפְקִיר בִּפְנֵי אֶחָד הֲרֵי זֶה הֶפְקֵר וְנִפְטָר מִן הַמַּעַשְׂרוֹת כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ. אֲבָל מִדִּבְרֵי סוֹפְרִים אֵינוֹ הֶפְקֵר עַד שֶׁיַּפְקִיר בִּפְנֵי שְׁלֹשָׁה כְּדֵי שֶׁיִּהְיֶה אֶחָד זוֹכֶה אִם רָצָה וְהַשְּׁנַיִם מְעִידִים. וְהָאוֹמֵר הֲרֵי זֶה הֶפְקֵר וְזֶה. הֲרֵי הַשֵּׁנִי סְפֵק הֶפְקֵר וְאִם אָמַר וְזֶה כְּמוֹ זֶה אוֹ שֶׁאָמַר וְגַם זֶה הֲרֵי הִתְפִּיס הַשֵּׁנִי וְיִהְיֶה הֶפְקֵר וַדַּאי:","הַמַּפְקִיר אֶת שָׂדֵהוּ וְלֹא זָכָה בָּהּ אָדָם כָּל שְׁלֹשָׁה יָמִים יָכוֹל לַחְזֹר בּוֹ. אַחַר שְׁלֹשָׁה יָמִים אֵינוֹ יָכוֹל לַחְזֹר בּוֹ אֶלָּא אִם כֵּן קָדַם וְזָכָה בָּהּ הֲרֵי הוּא כְּזוֹכֶה מִן הַהֶפְקֵר בֵּין הוּא בֵּין אַחֵר:","הָאוֹמֵר שָׂדֶה זוֹ מֻפְקֶרֶת לְיוֹם אֶחָד לְשַׁבָּת אַחַת לְחֹדֶשׁ אֶחָד לְשָׁנָה אַחַת לְשָׁבוּעַ אֶחָד עַד שֶׁלֹּא זָכָה בָּהּ הוּא אוֹ אַחֵר יָכוֹל לַחְזֹר בּוֹ. וּמִשֶּׁזָּכָה בָּהּ בֵּין הוּא בֵּין אַחֵר אֵינוֹ יָכוֹל לַחְזֹר בּוֹ. וּמִפְּנֵי מָה יֵשׁ לוֹ לַחְזֹר כָּאן עַד שֶׁיִּזְכּוּ בָּהּ מִפְּנֵי שֶׁזֶּה דָּבָר שֶׁאֵינוֹ מָצוּי הוּא שֶׁאֵין אָדָם מַפְקִיר לִזְמַן קָצוּב:","דָּבָר הַמֻּפְקָר שֶׁבָּא אֶחָד וּשְׁמָרוֹ וְהָיָה מַבִּיט בּוֹ שֶׁלֹּא יִטְּלֶנּוּ אָדָם לֹא קָנָהוּ בְּהַבָּטָה אֶלָּא עַד שֶׁיַּגְבִּיהוֹ אִם הָיָה מִטַּלְטְלִין אוֹ יַחֲזִיק בַּקַּרְקַע כְּדֶרֶךְ שֶׁקּוֹנִין הַלָּקוֹחוֹת:"]} as Record<string, string[]>;
